INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-001', 'aws-clf', 'Uma startup quer reduzir o tempo que a equipe gasta com patching de SO, troca de discos e renovação de hardware, focando apenas no produto. Qual benefício da nuvem AWS endereça esse objetivo de forma mais direta?',
  '[{"id":"A","text":"Foco no diferencial do negócio em vez de heavy lifting indiferenciado"},{"id":"B","text":"Economias de escala globais"},{"id":"C","text":"Elasticidade automática de capacidade"},{"id":"D","text":"Alcance global em minutos"}]'::jsonb, 'A',
  '{
    "summary": "AWS gerencia hardware, hypervisor, patching base e datacenter — é exatamente o ''undifferentiated heavy lifting'' que o framework descreve como vantagem da nuvem.",
    "whyCorrect": "AWS gerencia hardware, hypervisor, patching base e datacenter — é exatamente o ''undifferentiated heavy lifting'' que o framework descreve como vantagem da nuvem.",
    "whyWrong": {
     "B": "Economias de escala é benefício financeiro, não operacional.",
     "C": "Elasticidade é sobre variação de carga, não sobre manutenção.",
     "D": "Alcance global é sobre latência/expansão."
    },
    "keyConcept": "Princípio ''stop spending money running and maintaining data centers'' do Well-Architected.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Princípio ''stop spending money running and maintaining data centers'' do Well-Architected?",
     "Quais cenários reais aplicam Princípio ''stop spending money running and maintaining data centers'' do Well-Architected?",
     "Como AWS se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["benefits","well-architected","operational-excellence"]'::jsonb, 'ai-draft', 'active', now(), now()
)
