INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-003', 'aws-clf', 'Uma equipe precisa hospedar um site estático (HTML, CSS, JS, imagens) com baixo custo, alta durabilidade e acesso público global. Qual combinação de serviços AWS atende melhor a esse requisito?',
  '[{"id":"A","text":"Amazon EC2 com Auto Scaling atrás de um Application Load Balancer"},{"id":"B","text":"AWS Lambda com API Gateway e Amazon DynamoDB"},{"id":"C","text":"Amazon S3 com hosting estático e Amazon CloudFront na frente"},{"id":"D","text":"AWS Elastic Beanstalk em um ambiente single-instance"}]'::jsonb, 'C',
  '{
    "summary": "S3 oferece 11 9s de durabilidade e custo por GB baixíssimo; CloudFront entrega de edge locations próximas do usuário, reduzindo latência e custo de egress.",
    "whyCorrect": "S3 oferece 11 9s de durabilidade e custo por GB baixíssimo; CloudFront entrega de edge locations próximas do usuário, reduzindo latência e custo de egress.",
    "whyWrong": {
     "B": "Lambda+API Gateway é para APIs dinâmicas.",
     "D": "Elastic Beanstalk é PaaS para apps que rodam código no servidor.",
     "A": "EC2+ALB envolve instâncias rodando 24/7 com custo fixo de compute mais o ALB ($16+/mês mínimo), tudo isso só para servir arquivos estáticos. Há patching, monitoramento de saúde, configuração de web server (nginx/Apache) — overhead operacional alto para um caso onde S3 entrega o mesmo resultado por centavos. Esta opção faria sentido se houvesse processamento server-side."
    },
    "keyConcept": "Padrão recomendado AWS: S3 + CloudFront para sites estáticos.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão recomendado AWS: S3 + CloudFront para sites estáticos?",
     "Quais cenários reais aplicam Padrão recomendado AWS: S3 + CloudFront para sites estáticos?",
     "Como GB se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["s3","cloudfront","static-hosting"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
