INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-004', 'aws-clf', 'Uma empresa quer prever o gasto da AWS dos próximos 12 meses com base no histórico atual de uso e receber alertas quando ultrapassar um valor definido. Qual combinação de ferramentas atende essas duas necessidades?',
