INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-005', 'aws-clf', 'Uma empresa precisa criar uma rede privada virtual na AWS e definir explicitamente o range de IPs, sub-redes e rotas, isolada de outras contas. Qual serviço entrega esse isolamento de rede no nível mais fundamental?',
  '[{"id":"A","text":"Amazon VPC"},{"id":"B","text":"AWS Direct Connect"},{"id":"C","text":"AWS Transit Gateway"},{"id":"D","text":"Amazon Route 53"}]'::jsonb, 'A',
  '{
    "summary": "VPC é a primitiva de rede isolada — CIDR escolhido, subnets, route tables, IGW/NGW, SGs e NACLs vivem dentro dela.",
    "whyCorrect": "VPC é a primitiva de rede isolada — CIDR escolhido, subnets, route tables, IGW/NGW, SGs e NACLs vivem dentro dela.",
    "whyWrong": {
     "B": "Direct Connect é conectividade dedicada on-prem ↔ AWS, não cria a rede em si.",
     "C": "Transit Gateway interliga VPCs e on-prem, mas depende das VPCs existirem antes.",
     "D": "Route 53 é DNS, não rede."
    },
    "keyConcept": "VPC é foundation de qualquer arquitetura de rede AWS.",
    "tutorSeeds": [
