INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-006', 'aws-clf', 'Uma empresa tem cargas de trabalho previsíveis rodando 24/7 em Amazon EC2 por pelo menos 1 ano e quer reduzir custo em troca de compromisso de uso. Qual modelo de pricing entrega o maior desconto para esse perfil?',
  '[{"id":"A","text":"On-Demand Instances"},{"id":"B","text":"Savings Plans ou Reserved Instances de 1 ou 3 anos"},{"id":"C","text":"Spot Instances"},{"id":"D","text":"Dedicated Hosts no-tenancy"}]'::jsonb, 'B',
  '{
    "summary": "Compute Savings Plans e Standard RIs oferecem até ~72% de desconto vs On-Demand em troca de compromisso de gasto/horas por 1 ou 3 anos — encaixe perfeito em workload estável 24/7.",
    "whyCorrect": "Compute Savings Plans e Standard RIs oferecem até ~72% de desconto vs On-Demand em troca de compromisso de gasto/horas por 1 ou 3 anos — encaixe perfeito em workload estável 24/7.",
    "whyWrong": {
     "A": "On-Demand é o preço cheio, sem compromisso. [extra: incompatível com workload crítico 24/7.]",
     "C": "Spot tem desconto maior (~90%) mas pode ser interrompido",
     "D": "Dedicated Hosts é caro e endereça compliance/licenciamento, não desconto."
    },
    "keyConcept": "Regra: workload previsível e longo prazo → Savings Plans/RI; workload tolerante a interrupção → Spot.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: workload previsível e longo prazo → Savings Plans/RI; workload tolerante a interrupção → Spot?",
     "Quais cenários reais aplicam Regra: workload previsível e longo prazo → Savings Plans/RI; workload tolerante a interrupção → Spot?",
     "Como RIs se compara com alternativas?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["savings-plans","reserved-instances","pricing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
