INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-007', 'aws-clf', 'Um administrador precisa conceder a um aplicativo rodando em Amazon EC2 acesso a um bucket do Amazon S3 sem armazenar access keys na instância. Qual é a abordagem recomendada pela AWS?',
  '[{"id":"A","text":"Criar um IAM user com policy de S3 e colocar suas access keys em variáveis de ambiente"},{"id":"B","text":"Conceder permissões via security group apontando para o bucket"},{"id":"C","text":"Anexar uma IAM role à instância EC2 via instance profile com a policy de S3 necessária"},{"id":"D","text":"Habilitar Block Public Access no bucket e o EC2 acessa automaticamente"}]'::jsonb, 'C',
  '{
    "summary": "IAM roles via instance profile entregam credenciais temporárias rotacionadas automaticamente pelo metadata service — zero secret em disco.",
    "whyCorrect": "IAM roles via instance profile entregam credenciais temporárias rotacionadas automaticamente pelo metadata service — zero secret em disco.",
    "whyWrong": {
     "A": "IAM users com access keys hardcoded é exatamente o anti-pattern",
     "B": "security groups controlam tráfego TCP/UDP, não permissões IAM",
     "D": "Block Public Access é defesa contra exposição pública, não autorização."
    },
    "keyConcept": "Regra: cargas de trabalho devem usar roles, nunca long-lived keys.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: cargas de trabalho devem usar roles, nunca long-lived keys?",
     "Quais cenários reais aplicam Regra: cargas de trabalho devem usar roles, nunca long-lived keys?",
     "Como IAM se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["iam","ec2","instance-profile","least-privilege"]'::jsonb, 'ai-draft', 'active', now(), now()
)
