INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-008', 'aws-clf', 'Uma empresa armazena 200 TB de logs de auditoria que devem ser mantidos por 7 anos para compliance, com acesso raro mas recuperação em minutos quando solicitado. Qual classe do Amazon S3 minimiza custo dentro desses requisitos?',
  '[{"id":"A","text":"S3 Standard"},{"id":"B","text":"S3 Standard-IA"},{"id":"C","text":"S3 Glacier Deep Archive"},{"id":"D","text":"S3 Glacier Instant Retrieval"}]'::jsonb, 'D',
  '{
    "summary": "Glacier Instant Retrieval é a classe mais barata que ainda entrega recuperação em milissegundos — ideal para ''acesso raro mas quando precisar, é rápido''.",
    "whyCorrect": "Glacier Instant Retrieval é a classe mais barata que ainda entrega recuperação em milissegundos — ideal para ''acesso raro mas quando precisar, é rápido''.",
    "whyWrong": {
     "A": "Standard é cara para acesso raro. Standard-IA é mais barata mas ainda paga por GB de armazenamento bem acima de Glacier.",
     "C": "Deep Archive é a mais barata absoluta mas tem recuperação em 12 horas",
     "B": "Standard-IA é para acesso infrequente com recuperação em milissegundos, mas seu custo por GB de armazenamento é significativamente maior que Glacier Instant Retrieval. Para 200 TB mantidos por 7 anos, a diferença é grande. Standard-IA seria correto se o acesso fosse ''algumas vezes por mês''; para ''acesso raro'' (≤1x/quarter), Glacier IR ganha em custo mantendo a recuperação em ms."
    },
    "keyConcept": "Regra de escolha: frequência de acesso + tempo aceitável de recuperação.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra de escolha: frequência de acesso + tempo aceitável de recuperação?",
     "Quais cenários reais aplicam Regra de escolha: frequência de acesso + tempo aceitável de recuperação?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["s3","storage-classes","glacier","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
