INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-009', 'aws-clf', 'Uma equipe quer implementar políticas de governança centralizadas que limitem quais regiões e serviços contas-filhas podem usar, sem precisar configurar cada conta individualmente. Qual recurso da AWS entrega isso?',
  '[{"id":"A","text":"Service Control Policies (SCPs) em AWS Organizations"},{"id":"B","text":"IAM permissions boundaries em cada conta"},{"id":"C","text":"AWS Config rules em cada conta"},{"id":"D","text":"Resource-based policies em cada serviço"}]'::jsonb, 'A',
  '{
    "summary": "SCPs são aplicadas no nível da Organization ou OU e definem o ceiling máximo de permissões para todas as contas dentro — bloqueio centralizado sem tocar cada conta.",
    "whyCorrect": "SCPs são aplicadas no nível da Organization ou OU e definem o ceiling máximo de permissões para todas as contas dentro — bloqueio centralizado sem tocar cada conta.",
    "whyWrong": {
     "B": "Permissions boundaries são per-principal dentro de uma conta, não centralizadas.",
     "C": "Config rules detectam drift e geram findings, não bloqueiam ações em tempo real.",
     "D": "Resource-based policies são por recurso, não governança transversal."
    },
    "keyConcept": "Padrão de multi-account governance AWS: Organizations + SCPs + Control Tower.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão de multi-account governance AWS: Organizations + SCPs + Control Tower?",
     "Quais cenários reais aplicam Padrão de multi-account governance AWS: Organizations + SCPs + Control Tower?",
     "Como SCPs se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["organizations","scp","governance","multi-account"]'::jsonb, 'ai-draft', 'active', now(), now()
)
