INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-010', 'aws-clf', 'Após uma migração, a equipe relata que um workload web em EC2 ficou intermitentemente inacessível durante picos de tráfego, mesmo com Auto Scaling configurado. As métricas do CloudWatch mostram CPU em 95% sustentado. Qual ajuste atende melhor o problema?',
  '[{"id":"A","text":"Aumentar o tamanho do EBS volume das instâncias"},{"id":"B","text":"Ajustar a política de scaling para escalar com base em CPU \u003e70% e diminuir cooldown"},{"id":"C","text":"Migrar para instâncias t2.micro para reduzir custo"},{"id":"D","text":"Substituir o Application Load Balancer por um Network Load Balancer"}]'::jsonb, 'B',
  '{
    "summary": "CPU saturada antes do scaling agir indica threshold alto demais ou cooldown longo — baixar gatilho para 70% e reduzir cooldown permite reação antes da saturação.",
    "whyCorrect": "CPU saturada antes do scaling agir indica threshold alto demais ou cooldown longo — baixar gatilho para 70% e reduzir cooldown permite reação antes da saturação.",
    "whyWrong": {
     "C": "EBS resolve I/O, não CPU. t2.micro é menor, agravaria.",
     "A": "EBS volume size afeta capacidade de armazenamento e (em alguns tipos) IOPS de disco. O sintoma aqui é CPU saturada em 95%, não fila de I/O — aumentar EBS não adiciona ciclos de CPU. Esta opção seria correta se a métrica problemática fosse VolumeQueueLength ou throttling de I/O.",
     "D": "ALB opera em L7 (HTTP/HTTPS) e NLB em L4 (TCP/UDP) — a diferença é protocolo e features, não capacidade de compute das instâncias backend. Mesmo com NLB, as instâncias EC2 continuariam saturadas em 95% de CPU. O LB distribui tráfego, mas não gera capacidade adicional. Esta opção seria correta se o problema fosse latência de TLS termination ou jitter."
    },
    "keyConcept": "Conceito: scaling reativo precisa de threshold abaixo do ponto de saturação e cooldown compatível com tempo de boot da AMI.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: scaling reativo precisa de threshold abaixo do ponto de saturação e cooldown compatível com tempo de boot da AMI?",
     "Quais cenários reais aplicam Conceito: scaling reativo precisa de threshold abaixo do ponto de saturação e cooldown compatível com tempo de boot da AMI?",
     "Como CPU se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'troubleshoot', '["ec2","auto-scaling","cloudwatch"]'::jsonb, 'ai-draft', 'active', now(), now()
)
