INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-011', 'aws-clf', 'Uma empresa precisa decidir entre Basic, Developer, Business e Enterprise Support para sua conta AWS. O requisito principal é ter acesso 24x7 a engenheiros AWS para casos de produção e a um Technical Account Manager (TAM) dedicado. Qual plano atende?',
  '[{"id":"A","text":"AWS Basic Support"},{"id":"B","text":"AWS Developer Support"},{"id":"C","text":"AWS Enterprise Support"},{"id":"D","text":"AWS Business Support"}]'::jsonb, 'C',
  '{
    "summary": "TAM dedicado é exclusivo de Enterprise (e Enterprise On-Ramp em escopo limitado); 24x7 a engenheiros para produção e SLA agressivo de business-critical também.",
    "whyCorrect": "TAM dedicado é exclusivo de Enterprise (e Enterprise On-Ramp em escopo limitado); 24x7 a engenheiros para produção e SLA agressivo de business-critical também.",
    "whyWrong": {
     "A": "Basic não tem suporte técnico via case.",
     "B": "Developer é horário comercial e sem TAM.",
     "D": "Business tem 24x7 mas sem TAM dedicado."
    },
    "keyConcept": "Regra: precisa de TAM → Enterprise (ou On-Ramp como entry).",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: precisa de TAM → Enterprise (ou On-Ramp como entry)?",
     "Quais cenários reais aplicam Regra: precisa de TAM → Enterprise (ou On-Ramp como entry)?",
     "Como TAM se compara com alternativas?"
    ]
   }'::jsonb,
