INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-013', 'aws-clf', 'Uma equipe quer rodar containers Docker sem provisionar nem gerenciar EC2 hosts (serverless de container), pagando apenas pelo vCPU/memória consumidos por task. Qual combinação AWS atende?',
  '[{"id":"A","text":"Amazon ECS ou EKS com AWS Fargate como capacity provider"},{"id":"B","text":"Amazon ECS com launch type EC2"},{"id":"C","text":"Amazon EC2 com Docker instalado manualmente"},{"id":"D","text":"AWS Lambda com container images"}]'::jsonb, 'A',
  '{
    "summary": "Fargate roda containers ECS/EKS sem expor EC2 hosts ao cliente — billing por vCPU·s + memória·s da task.",
    "whyCorrect": "Fargate roda containers ECS/EKS sem expor EC2 hosts ao cliente — billing por vCPU·s + memória·s da task.",
    "whyWrong": {
     "B": "ECS launch type EC2 expõe hosts EC2 (cliente patcha).",
     "C": "EC2+Docker manual é IaaS puro.",
     "D": "Lambda com container images existe mas é função, não orquestração de container long-running com modelo task/pod."
    },
    "keyConcept": "Regra: container serverless = Fargate; função serverless = Lambda.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: container serverless = Fargate; função serverless = Lambda?",
     "Quais cenários reais aplicam Regra: container serverless = Fargate; função serverless = Lambda?",
     "Como ECS se compara com alternativas?"
    ]
   }'::jsonb,
