INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-014', 'aws-clf', 'Uma empresa global quer reduzir a latência de uma API hospedada na regiao us-east-1 para usuários na Ásia e Europa, sem mover a infra. A API serve respostas em sua maioria dinâmicas (não-cacheáveis), mas se beneficia de TLS terminado próximo do usuário e roteamento por anycast. Qual serviço atende melhor?',
  '[{"id":"A","text":"Amazon CloudFront com TTL=0"},{"id":"B","text":"AWS Global Accelerator"},{"id":"C","text":"Amazon Route 53 com latency-based routing"},{"id":"D","text":"Adicionar uma read replica RDS por região"}]'::jsonb, 'B',
  '{
    "summary": "Global Accelerator dá IPs anycast que entram na rede AWS no edge mais próximo, terminam TLS e fazem path interno otimizado até us-east-1 — perfeito para tráfego dinâmico não-cacheável.",
    "whyCorrect": "Global Accelerator dá IPs anycast que entram na rede AWS no edge mais próximo, terminam TLS e fazem path interno otimizado até us-east-1 — perfeito para tráfego dinâmico não-cacheável.",
    "whyWrong": {
     "A": "CloudFront é otimizado para conteúdo cacheável [extra: com TTL=0 não cacheia mas adiciona hop.]",
     "C": "Route 53 latency routing só vale se houver endpoints em múltiplas regiões.",
     "D": "RDS replica exige refatorar a app e replicação, fora de escopo."
    },
    "keyConcept": "Regra: estático/cacheável → CloudFront; dinâmico/anycast → Global Accelerator.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: estático/cacheável → CloudFront; dinâmico/anycast → Global Accelerator?",
     "Quais cenários reais aplicam Regra: estático/cacheável → CloudFront; dinâmico/anycast → Global Accelerator?",
     "Como IPs se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["global-accelerator","cloudfront","latency"]'::jsonb, 'ai-draft', 'active', now(), now()
)
