INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-015', 'aws-clf', 'Após habilitar AWS CloudTrail em uma conta, a equipe não consegue ver eventos de API S3 GetObject/PutObject no log trail padrão. Qual ajuste resolve isso?',
  '[{"id":"A","text":"Aumentar a retenção do bucket destino do CloudTrail"},{"id":"B","text":"Mudar a região do trail para us-east-1"},{"id":"C","text":"Habilitar Data Events para S3 (objetos) no trail; por padrão só Management Events são registrados"},{"id":"D","text":"Habilitar versioning no bucket monitorado"}]'::jsonb, 'C',
  '{
    "summary": "CloudTrail por padrão captura Management Events (operações no plano de controle: CreateBucket, PutBucketPolicy).",
    "whyCorrect": "CloudTrail por padrão captura Management Events (operações no plano de controle: CreateBucket, PutBucketPolicy). Operações no plano de dados (GetObject/PutObject) são Data Events e precisam ser habilitadas explicitamente — têm custo adicional.",
    "whyWrong": {
     "A": "Retenção não afeta o que é capturado. Versioning é feature do S3, não do CloudTrail.",
     "B": "Região não filtra Data Events.",
     "D": "Versioning no S3 mantém múltiplas versões de objetos para proteção contra delete/overwrite acidental — é feature de durabilidade dos dados, não de auditoria de API. CloudTrail é independente do versioning: ele registra a operação (GetObject, PutObject) se Data Events estiverem habilitados, com ou sem versioning. Versioning seria a resposta para ''proteger objetos contra deleção acidental''."
    },
    "keyConcept": "Conceito: Management vs Data Events vs Insights — saber o que cada um cobre.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: Management vs Data Events vs Insights — saber o que cada um cobre?",
     "Quais cenários reais aplicam Conceito: Management vs Data Events vs Insights — saber o que cada um cobre?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'troubleshoot', '["cloudtrail","audit","s3","data-events"]'::jsonb, 'ai-draft', 'active', now(), now()
)
