INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-001', 'aws-clf', 'Uma startup roda 20 instâncias EC2 m5.large em produção 24/7 há 18 meses sem previsão de redução. O CFO pediu para reduzir custo de compute sem mudar o tipo de instância. Considerando compromisso de 1 ano, qual modelo entrega o maior desconto sobre On-Demand mantendo flexibilidade entre regiões?',
  '[{"id":"A","text":"Compute Savings Plans de 1 ano, pagamento parcial"},{"id":"B","text":"Spot Instances com fleet diversificada"},{"id":"C","text":"EC2 Reserved Instances Standard zonal de 1 ano"},{"id":"D","text":"Dedicated Hosts com licença BYOL"}]'::jsonb, 'A',
  '{
    "summary": "Compute Savings Plans aplicam desconto (até ~66%) em qualquer região, família ou tamanho de EC2/Fargate/Lambda mediante compromisso de gasto $/h.",
    "whyCorrect": "Compute Savings Plans aplicam desconto (até ~66%) em qualquer região, família ou tamanho de EC2/Fargate/Lambda mediante compromisso de gasto $/h.",
    "whyWrong": {
     "B": "Spot pode ser interrompido [extra: não serve workload 24/7 crítico]",
     "C": "Standard RI zonal trava AZ específica e família",
     "D": "Dedicated Hosts são mais caros (foco em licenças)."
    },
    "keyConcept": "Regra: workload steady com flexibilidade → Savings Plans; workload tolerante a falhas → Spot.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: workload steady com flexibilidade → Savings Plans; workload tolerante a falhas → Spot?",
     "Quais cenários reais aplicam Regra: workload steady com flexibilidade → Savings Plans; workload tolerante a falhas → Spot?",
     "Como EC2 se compara com alternativas?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["pricing","savings-plans","ec2"]'::jsonb, 'ai-draft', 'active', now(), now()
)
