INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-003', 'aws-clf', 'Qual a principal diferença entre EC2 Instance Savings Plans e Compute Savings Plans?',
  '[{"id":"A","text":"Compute SP só vale para Lambda; Instance SP só para EC2"},{"id":"B","text":"Compute SP exige compromisso de 3 anos obrigatório"},{"id":"C","text":"Instance SP exige família/região fixas com maior desconto; Compute SP é flexível com desconto menor"},{"id":"D","text":"Não há diferença prática — são sinônimos comerciais"}]'::jsonb, 'C',
  '{
    "summary": "Instance SP exige commit em família+região específicas (ex: m5 em us-east-1) e dá desconto similar ao RI Standard (~72%); Compute SP é cross-família/região/serviço (EC2/Fargate/Lambda) com desconto até ~66%.",
    "whyCorrect": "Instance SP exige commit em família+região específicas (ex: m5 em us-east-1) e dá desconto similar ao RI Standard (~72%); Compute SP é cross-família/região/serviço (EC2/Fargate/Lambda) com desconto até ~66%.",
    "whyWrong": {
     "A": "Compute SP cobre também Fargate e Lambda",
     "B": "prazos são 1 ou 3 anos para ambos.",
     "D": "Instance SP e Compute SP são produtos distintos com regras de aplicação, escopo e desconto diferentes. Instance SP é restrito a família+região (até ~72% de desconto, similar ao Standard RI); Compute SP cobre EC2 (qualquer família/região/SO), Fargate e Lambda (~66%). A AWS expõe ambos no console como SKUs separados — não são sinônimos comerciais."
    },
    "keyConcept": "Regra: mais restrição → maior desconto.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: mais restrição → maior desconto?",
     "Quais cenários reais aplicam Regra: mais restrição → maior desconto?",
     "Como SP se compara com alternativas?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'recall', '["pricing","savings-plans"]'::jsonb, 'ai-draft', 'active', now(), now()
)
