INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-004', 'aws-clf', 'Uma empresa adquiriu Reserved Instances Standard de 3 anos para EC2 m5.xlarge em us-east-1. Seis meses depois, querem trocar para r5.xlarge devido a novo workload memory-bound. Qual ação é possível?',
  '[{"id":"A","text":"Trocar livremente entre famílias via console"},{"id":"B","text":"Cancelar a RI com reembolso integral"},{"id":"C","text":"Converter para Convertible RI sem custo"},{"id":"D","text":"Vender a RI no Reserved Instance Marketplace e comprar nova"}]'::jsonb, 'D',
  '{
    "summary": "Standard RI não permite mudar família — apenas tamanho dentro da mesma família (size-flexibility).",
    "whyCorrect": "Standard RI não permite mudar família — apenas tamanho dentro da mesma família (size-flexibility). Para trocar, deve vender no Marketplace (sujeito a aprovação) e comprar nova.",
    "whyWrong": {
     "B": "AWS não permite cancelar com reembolso",
     "C": "Standard não converte para Convertible troca livre só com Convertible RI.",
