INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-005', 'aws-clf', 'Uma empresa precisa rodar software com licença vinculada a sockets físicos (ex: Windows Server BYOL legado). Qual modelo de compra é exigido para atender ao requisito de licenciamento?',
  '[{"id":"A","text":"Dedicated Hosts"},{"id":"B","text":"EC2 On-Demand padrão"},{"id":"C","text":"Spot Instances"},{"id":"D","text":"Savings Plans Compute"}]'::jsonb, 'A',
  '{
    "summary": "Dedicated Hosts dão visibilidade dos sockets/cores do host físico, permitindo BYOL de licenças socket-based.",
    "whyCorrect": "Dedicated Hosts dão visibilidade dos sockets/cores do host físico, permitindo BYOL de licenças socket-based.",
    "whyWrong": {
     "C": "Dedicated Instances isolam tenant mas não dão visibilidade de sockets.",
     "D": "On-Demand/Spot/Savings Plans rodam em multi-tenant",
