INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-006', 'aws-clf', 'Qual diferença prática entre Dedicated Instances e Dedicated Hosts?',
  '[{"id":"A","text":"Não há — são o mesmo produto"},{"id":"B","text":"Dedicated Instances isolam tenant; Dedicated Hosts ainda dão visibilidade e controle do hardware físico"},{"id":"C","text":"Dedicated Hosts são cobrados por instância; Dedicated Instances por host"},{"id":"D","text":"Dedicated Instances só rodam em Outposts"}]'::jsonb, 'B',
  '{
    "summary": "Dedicated Instances garantem que VMs do cliente rodam em hardware não compartilhado, mas o cliente não vê o host.",
    "whyCorrect": "Dedicated Instances garantem que VMs do cliente rodam em hardware não compartilhado, mas o cliente não vê o host. Dedicated Hosts alocam o host físico inteiro — cliente vê sockets/cores e controla onde cada instância roda (essencial para BYOL).",
    "whyWrong": {
     "A": "Outposts é outro produto.",
     "C": "cobrança Hosts é por host/hora, Instances por instância/hora",
     "D": "Dedicated Instances estão disponíveis em qualquer Região AWS comercial — não há vinculação com AWS Outposts. Outposts é uma oferta de hardware AWS instalado on-premises do cliente e funciona com modelo de tenancy próprio. Esta opção mistura dois conceitos não relacionados (tenancy dedicada vs hardware hybrid)."
    },
    "keyConcept": "Regra: licença socket-based → Hosts; só isolamento → Instances.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: licença socket-based → Hosts; só isolamento → Instances?",
     "Quais cenários reais aplicam Regra: licença socket-based → Hosts; só isolamento → Instances?",
     "Como VMs se compara com alternativas?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'recall', '["pricing","dedicated-hosts","dedicated-instances"]'::jsonb, 'ai-draft', 'active', now(), now()
