INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-029', 'aws-clf', 'Qual a diferença entre AWS-generated cost allocation tags e user-defined cost allocation tags?',
  '[{"id":"A","text":"AWS-generated (ex: aws:createdBy) são geradas pela AWS; user-defined são criadas pelo cliente. Ambas exigem ativação para custo"},{"id":"B","text":"Não há — são sinônimos"},{"id":"C","text":"AWS-generated são pagas; user-defined são gratuitas"},{"id":"D","text":"Apenas user-defined funcionam em CUR"}]'::jsonb, 'A',
  '{
    "summary": "AWS gera tags como `aws:createdBy`, `aws:cloudformation:stack-name`; cliente cria tags arbitrárias `Environment=prod`.",
    "whyCorrect": "AWS gera tags como `aws:createdBy`, `aws:cloudformation:stack-name`; cliente cria tags arbitrárias `Environment=prod`. Ambas precisam ser ativadas como cost allocation tag para aparecer em billing.",
    "whyWrong": {
     "D": "ambas funcionam em CUR.",
     "B": "Existe diferença clara e documentada: AWS-generated tags têm prefixo `aws:` (ex: `aws:createdBy`, `aws:cloudformation:stack-name`) e são imutáveis — o cliente não pode editá-las nem aplicá-las manualmente. User-defined tags têm chave arbitrária criada pelo cliente. Ambas precisam de ativação separada como cost allocation tag para aparecer em Cost Explorer/CUR.",
     "C": "Tagueamento (incluindo cost allocation) é gratuito em AWS — não há cobrança por aplicar tags nem por ativá-las como cost allocation. O único custo associado é indireto: armazenamento do CUR no S3 e queries de Athena. Tanto AWS-generated quanto user-defined são gratuitas."
    },
    "keyConcept": "Regra: prefixo `aws:` = system tag; sem prefixo = user.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: prefixo `aws:` = system tag; sem prefixo = user?",
     "Quais cenários reais aplicam Regra: prefixo `aws:` = system tag; sem prefixo = user?",
     "Como AWS se compara com alternativas?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'recall', '["tagging","cost-allocation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
