INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-035', 'aws-clf', 'Quais são as 5 categorias de checks do AWS Trusted Advisor?',
  '[{"id":"A","text":"Compute, Storage, Database, Network, Security"},{"id":"B","text":"Reliability, Security, Cost, Performance, Sustainability"},{"id":"C","text":"Cost, Performance, Security, Fault Tolerance, Service Limits"},{"id":"D","text":"Operational, Security, Reliability, Performance, Cost"}]'::jsonb, 'C',
  '{
    "summary": "As 5 categorias do Trusted Advisor são Cost Optimization, Performance, Security, Fault Tolerance e Service Limits (quotas).",
    "whyCorrect": "As 5 categorias do Trusted Advisor são Cost Optimization, Performance, Security, Fault Tolerance e Service Limits (quotas).",
    "whyWrong": {
     "B": "opção C/D são pilares do Well-Architected Framework (que tem 6: + Operational Excellence, Sustainability).",
     "A": "Esta lista mistura categorias de serviço (Compute, Storage, Database, Network) com Security — corresponde a uma taxonomia de produtos AWS, não às categorias de checks do Trusted Advisor. Trusted Advisor categoriza por dimensão de qualidade arquitetural, não por tipo de serviço.",
     "D": "Esta lista (Operational, Security, Reliability, Performance, Cost) corresponde aos 5 pilares originais do AWS Well-Architected Framework — não às categorias do Trusted Advisor. Confusão comum: Well-Architected é framework de design/review; Trusted Advisor é serviço de checks automatizados sobre a conta."
    },
    "keyConcept": "Regra: TA ≠ Well-Architected.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: TA ≠ Well-Architected?",
     "Quais cenários reais aplicam Regra: TA ≠ Well-Architected?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'recall', '["trusted-advisor"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
