INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-036', 'aws-clf', 'Qual check do Trusted Advisor identifica buckets S3 com permissão pública de leitura/escrita?',
  '[{"id":"A","text":"Cost Optimization → Idle Load Balancers"},{"id":"B","text":"Performance → Overutilized EC2"},{"id":"C","text":"Service Limits → S3 Bucket count"},{"id":"D","text":"Security → Amazon S3 Bucket Permissions"}]'::jsonb, 'D',
  '{
    "summary": "Trusted Advisor inclui check Security → S3 Bucket Permissions, sinalizando buckets com ACLs públicas ou bucket policies permissivas.",
    "whyCorrect": "Trusted Advisor inclui check Security → S3 Bucket Permissions, sinalizando buckets com ACLs públicas ou bucket policies permissivas.",
    "whyWrong": {
     "A": "Idle Load Balancers é um check de Cost Optimization que sinaliza ALBs/NLBs sem traffic ou backend saudável para reduzir gasto — não tem relação com permissões de S3. Seria a resposta para ''identificar load balancers desperdiçando dinheiro sem uso''.",
     "B": "Overutilized EC2 é check de Performance que sinaliza instâncias com CPU/memória/network consistentemente saturadas, sugerindo upgrade de tipo — escopo de capacity planning, não de segurança de S3. Seria a resposta para ''identificar instâncias EC2 sobrecarregadas''.",
     "C": "S3 Bucket count é um Service Limits check que monitora aproximação ao limite de 1000 buckets por conta — é sobre quotas, não sobre permissões. Seria a resposta para ''identificar contas próximas de atingir o limite de buckets''."
    },
    "keyConcept": "Regra: permissões públicas S3 → categoria Security.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: permissões públicas S3 → categoria Security?",
     "Quais cenários reais aplicam Regra: permissões públicas S3 → categoria Security?",
     "Como ACLs se compara com alternativas?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["trusted-advisor","security","s3"]'::jsonb, 'ai-draft', 'active', now(), now()
)
