INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-038', 'aws-clf', 'Uma startup elegível recebeu créditos AWS via AWS Activate. Como eles aparecem no billing?',
  '[{"id":"A","text":"Como reembolso em cartão"},{"id":"B","text":"Como linha negativa aplicada automaticamente até o limite/expiração"},{"id":"C","text":"Como Savings Plans"},{"id":"D","text":"Como tag aws:credit nos recursos"}]'::jsonb, 'B',
  '{
    "summary": "Créditos aparecem como crédito aplicado na fatura (linha negativa), respeitando regras de elegibilidade por serviço/região e data de expiração configurada.",
    "whyCorrect": "Créditos aparecem como crédito aplicado na fatura (linha negativa), respeitando regras de elegibilidade por serviço/região e data de expiração configurada.",
    "whyWrong": {
     "A": "Não há reembolso de cartão",
     "D": "não tagueiam recursos.",
     "C": "Savings Plans são compromissos de gasto $/hora comprados pelo cliente (1 ou 3 anos) — créditos AWS Activate são benefícios promocionais (linha negativa na fatura). São mecanismos contábeis e operacionais completamente distintos: SP gera desconto sobre uso futuro mediante commit; créditos abatem o valor faturado. Activate não é entregue na forma de SP."
    },
    "keyConcept": "Regra: créditos AWS são aplicados automaticamente até esgotar/expirar.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: créditos AWS são aplicados automaticamente até esgotar/expirar?",
     "Quais cenários reais aplicam Regra: créditos AWS são aplicados automaticamente até esgotar/expirar?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["billing-tools","credits","activate"]'::jsonb, 'ai-draft', 'active', now(), now()
)
