INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-040', 'aws-clf', 'Uma empresa que rodava EC2 m5.xlarge em On-Demand a $0.192/h migrou para Compute Savings Plan 1y All Upfront com desconto de 50%. Sobre o efetivo desconto, qual statement é correto?',
  '[{"id":"A","text":"O desconto aplica-se a horas além do commit em All Upfront sem custo adicional"},{"id":"B","text":"All Upfront permite cobrir 100% das horas do ano sem limite"},{"id":"C","text":"Após esgotar o crédito, o custo cai para zero"},{"id":"D","text":"Horas até o commit/hora são cobertas pelo SP; horas excedentes voltam a On-Demand a $0.192/h"}]'::jsonb, 'D',
  '{
    "summary": "SP comprometem um valor $/hora; uso até esse hourly commit é coberto com desconto; uso adicional é cobrado a On-Demand.",
    "whyCorrect": "SP comprometem um valor $/hora; uso até esse hourly commit é coberto com desconto; uso adicional é cobrado a On-Demand.",
    "whyWrong": {
     "A": "Não há cobertura ilimitada (depende do commit/h) All Upfront paga upfront mas com mesmo commit/h",
     "C": "nunca cai a zero.",
     "B": "All Upfront refere-se a COMO o commit é pago (100% adiantado, gerando desconto extra) — não a QUE quantidade de uso é coberto. O commit em $/hora é o mesmo independentemente de payment option; horas que excedem o commit/h voltam a On-Demand. All Upfront vs Partial vs No Upfront muda só o cashflow e o desconto efetivo, não o teto de cobertura."
    },
    "keyConcept": "Regra: SP cobrem até o commit/h — dimensionar com cuidado.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: SP cobrem até o commit/h — dimensionar com cuidado?",
     "Quais cenários reais aplicam Regra: SP cobrem até o commit/h — dimensionar com cuidado?",
     "Como SP se compara com alternativas?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'troubleshoot', '["pricing","savings-plans"]'::jsonb, 'ai-draft', 'active', now(), now()
)
