INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-001', 'aws-clf', 'Uma empresa roda workload misto: 200 vCPU em EC2 (várias famílias), 50 funções Lambda críticas e 30 tarefas Fargate. Quer um único commitment que reduza custo em todos esses serviços ao máximo com flexibilidade de família e região. Qual Savings Plan escolher?',
  '[{"id":"A","text":"Compute Savings Plans de 1 ou 3 anos"},{"id":"B","text":"EC2 Instance Savings Plans em cada família predominante"},{"id":"C","text":"SageMaker Savings Plans"},{"id":"D","text":"Reserved Instances Standard regionais"}]'::jsonb, 'A',
  '{
    "summary": "Compute Savings Plans é o único tipo que cobre EC2 + Fargate + Lambda simultaneamente, com flexibilidade cross-família e cross-região.",
    "whyCorrect": "Compute SP aplica desconto (~66%) em qualquer uso de EC2 (qualquer família, tamanho, OS, tenancy, região), Fargate e Lambda. É exatamente o caso de uso de workload misto.",
    "whyWrong": {
     "B": "EC2 Instance SP cobre APENAS EC2 numa família+região específicas. Não cobre Lambda nem Fargate, e exige múltiplos commitments separados por família.",
     "C": "SageMaker SP cobre apenas instâncias SageMaker (ml.*). Não se aplica a EC2 genérico, Lambda ou Fargate.",
     "D": "RI Standard cobre só EC2 (não Lambda nem Fargate) e Regional RI dá flexibilidade de AZ/size dentro da família apenas — não cross-família."
    },
    "keyConcept": "Hierarquia de Savings Plans: Compute SP (máxima flexibilidade, ~66% off) > EC2 Instance SP (família+região fixas, ~72% off) > SageMaker SP (só ML). Escolha pelo escopo do workload.",
    "compareWith": [
     "EC2 Instance Savings Plans",
     "SageMaker Savings Plans",
     "Reserved Instances Standard"
    ],
    "realWorldContext": "Empresas com arquitetura mista (web/API em EC2, eventos em Lambda, containers em Fargate) padronizam em Compute SP. Trocar ''qual família vou usar daqui a 12 meses?'' por ''qual gasto $/h vou manter?'' é o ponto.",
    "commonMistakes": "Achar que Compute SP cobre RDS, ElastiCache ou Redshift — NÃO cobre. Para RDS/ElastiCache/Redshift/OpenSearch existem Reserved Nodes/Instances específicas, não Savings Plans.",
    "tutorSeeds": [
     "Por que Compute SP dá menos desconto que EC2 Instance SP?",
     "Quais serviços NÃO são cobertos por Compute Savings Plans?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["savings-plans","compute-sp","lambda","fargate"]'::jsonb, 'ai-draft', 'active', now(), now()
)
