INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-002', 'aws-clf', 'O CFO autoriza um commitment de Savings Plans, mas tem caixa restrito no primeiro mês. Entre as opções de pagamento (All Upfront, Partial Upfront, No Upfront) de um Compute SP de 1 ano, qual a relação correta entre pagamento e desconto?',
  '[{"id":"A","text":"Todas as opções dão o mesmo desconto, só muda o cronograma de cobrança"},{"id":"B","text":"All Upfront dá o maior desconto; No Upfront, o menor; Partial fica no meio"},{"id":"C","text":"No Upfront dá maior desconto porque a AWS prefere fluxo recorrente"},{"id":"D","text":"Só All Upfront é elegível para Compute SP"}]'::jsonb, 'B',
  '{
    "summary": "Quanto mais cedo o pagamento, maior o desconto efetivo — All Upfront > Partial > No Upfront.",
    "whyCorrect": "A AWS recompensa risco financeiro antecipado: All Upfront paga 100% no início e tem o maior desconto efetivo. Partial paga 50% upfront + mensal. No Upfront paga só mensalmente — o desconto cai poucos pontos percentuais comparado a All Upfront.",
    "whyWrong": {
     "A": "Falso. As três opções têm descontos efetivos diferentes, embora a diferença entre elas seja pequena (1–3 pp).",
     "C": "Inverso. A AWS premia caixa antecipado, não fluxo recorrente.",
     "D": "Falso. Compute SP aceita as três opções de pagamento."
    },
    "keyConcept": "Trade-off de Savings Plans: maior commitment financeiro upfront = maior desconto. Avaliar custo de oportunidade do caixa vs economia adicional.",
    "compareWith": [
     "RI All/Partial/No Upfront",
     "Pagamento antecipado em commitments cloud em geral"
    ],
    "realWorldContext": "Para a maioria das empresas, Partial Upfront é o ponto ótimo: ~50% do desconto máximo sem comprometer caixa integralmente. Startups em runway curto preferem No Upfront mesmo perdendo ~3 pp.",
    "commonMistakes": "Pensar que No Upfront ''não tem commitment'' — TEM. Você se obriga ao gasto mensal mesmo sem uso; cobrança continua se workload some.",
    "tutorSeeds": [
     "Como calcular o break-even entre Partial e All Upfront?",
     "O que acontece se eu deletar todas as instâncias com Compute SP ativo?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'recall', '["savings-plans","payment-options"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
