INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-003', 'aws-clf', 'Time de ML usa instâncias ml.p4d.24xlarge no SageMaker Training 24/7. Quer reduzir custo, mas mantém liberdade de mudar entre ml.p4d e ml.g5 conforme experimento. Qual commitment é o adequado?',
  '[{"id":"A","text":"EC2 Instance Savings Plans família p4d"},{"id":"B","text":"Compute Savings Plans"},{"id":"C","text":"SageMaker Savings Plans"},{"id":"D","text":"Reserved Instances padrão EC2"}]'::jsonb, 'C',
  '{
    "summary": "SageMaker Savings Plans é o único que cobre uso do SageMaker (Training, Inference, Notebooks, Processing) com flexibilidade entre famílias ml.*.",
    "whyCorrect": "SageMaker SP foi criado especificamente para workloads ml.*: cobre Training, RealTime Inference, Batch Transform, Notebook, Processing, Data Wrangler, Studio. Permite mudar entre famílias (ml.p4d, ml.g5, ml.c5, etc.) dentro do compromisso de $/h.",
    "whyWrong": {
     "A": "EC2 Instance SP não cobre SageMaker. Instâncias ml.* são gerenciadas pelo SageMaker e cobradas em SKU separado de EC2.",
     "B": "Compute SP cobre apenas EC2, Lambda e Fargate. NÃO cobre SageMaker.",
     "D": "EC2 RI também não se aplica a ml.* instances do SageMaker — é cobrança diferente."
    },
    "keyConcept": "Cada família de Savings Plan tem escopo de serviços específico. SageMaker tem SKU separado do EC2; precisa de SP dedicado.",
    "compareWith": [
     "Compute SP",
     "EC2 Instance SP",
     "EC2 Reserved Instances"
    ],
    "realWorldContext": "Times de ML que rodam treinamento contínuo (foundational models, fine-tuning constante) economizam ~64% com SageMaker SP de 3 anos All Upfront. Sem SP, ml.p4d.24xlarge On-Demand chega a ~$32/h.",
    "commonMistakes": "Comprar Compute SP achando que vai cobrir SageMaker — a fatura continua cobrando o uso ml.* em On-Demand.",
    "tutorSeeds": [
     "Por que a AWS separou SageMaker das outras famílias de SP?",
     "SageMaker Serverless Inference é coberto pelo SageMaker SP?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["savings-plans","sagemaker","ml"]'::jsonb, 'ai-draft', 'active', now(), now()
)
