INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-004', 'aws-clf', 'Empresa estuda Savings Plans de 1 ano vs 3 anos. Roadmap diz que migração para Graviton (arm64) acontece em 14 meses, com mudança de famílias e possível redução de footprint de 40%. Qual a recomendação mais prudente?',
  '[{"id":"A","text":"Comprar 3 anos All Upfront — maior desconto independe da migração"},{"id":"B","text":"Misturar 3 anos All Upfront em 100% do baseline e cobrir picos com On-Demand"},{"id":"C","text":"Não comprar nada e usar On-Demand até a migração"},{"id":"D","text":"Comprar 1 ano No Upfront e reavaliar após a migração"}]'::jsonb, 'D',
  '{
    "summary": "Com mudança arquitetural prevista em 14 meses e possível redução de footprint, 1 ano é mais prudente que 3 anos.",
    "whyCorrect": "Compute SP é flexível entre famílias (incluindo Graviton), mas o commitment é em $/h. Se o footprint cai 40%, sobra commitment não utilizado por ~22 meses no plano de 3 anos. O plano de 1 ano permite recalibrar após a migração.",
    "whyWrong": {
     "A": "Maximizar desconto sem considerar o commitment de gasto é armadilha — sobra de SP vira custo sem uso correspondente.",
     "B": "Comprar 3 anos em 100% do baseline atual ignora que o baseline vai diminuir; mesmo problema do A.",
     "C": "Renunciar a ~30% de desconto durante 14 meses é desperdício; o risco de 1 ano é baixo."
    },
    "keyConcept": "Prazo do Savings Plan deve casar com horizonte de visibilidade do workload. 3 anos para steady state confirmado; 1 ano quando há mudanças previstas.",
    "compareWith": [
     "RI Convertible (permite trocar família mas mantém commitment)",
     "On-Demand"
    ],
    "realWorldContext": "Migração para Graviton tipicamente reduz custo de compute em 20–40% adicional. Combinar essa redução com SP existente exige cálculo cuidadoso de break-even.",
    "commonMistakes": "Comprar 3 anos pelo desconto sem considerar volatilidade do workload — empresa fica pagando SP fantasma.",
    "tutorSeeds": [
     "Compute SP cobre Graviton automaticamente?",
     "Como dimensionar o tamanho do commitment ($/h) de um SP?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'scenario', '["savings-plans","graviton","term-length"]'::jsonb, 'ai-draft', 'active', now(), now()
)
