INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-005', 'aws-clf', 'Um Compute Savings Plan já está ativo. O time scala up adicionando novas instâncias EC2 c7g em outra região. Como o desconto se comporta?',
  '[{"id":"A","text":"Aplica-se automaticamente até o limite de $/h não consumido em outras instâncias"},{"id":"B","text":"Não se aplica — Compute SP cobre apenas a região onde foi comprado"},{"id":"C","text":"Aplica somente após reativação manual no console"},{"id":"D","text":"Aplica só se as instâncias forem da mesma família que existia antes"}]'::jsonb, 'A',
  '{
    "summary": "Compute SP é cross-região e cross-família por padrão; o desconto é aplicado automaticamente até esgotar o commitment de $/h.",
    "whyCorrect": "O motor de billing avalia uso elegível por hora e aplica o desconto até o limite do commitment $/h, priorizando o uso de maior desconto on-demand-equivalent. Não importa a região nem família.",
    "whyWrong": {
     "B": "Confunde com EC2 Instance SP, que é fixo em região+família. Compute SP é global na conta.",
     "C": "Não há reativação manual — aplicação é automática pelo billing engine a cada hora.",
     "D": "Compute SP cobre todas as famílias EC2 e ainda Lambda/Fargate; não há restrição."
    },
    "keyConcept": "Compute SP funciona como ''crédito horário de gasto'' — qualquer uso elegível desconta do crédito até o teto $/h.",
    "compareWith": [
     "EC2 Instance SP (região+família fixas)",
     "RI Regional (família fixa, região fixa)"
    ],
    "realWorldContext": "Times multi-região usam um único Compute SP corporativo que cobre us-east-1, sa-east-1 e eu-west-1 simultaneamente — sem precisar dividir commitments.",
    "commonMistakes": "Comprar múltiplos Compute SPs achando que precisa um por região — desperdício, um único SP cobre tudo.",
    "tutorSeeds": [
     "Como o billing engine prioriza qual instância recebe desconto primeiro?",
     "O que é ''on-demand equivalent rate''?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["savings-plans","compute-sp","cross-region"]'::jsonb, 'ai-draft', 'active', now(), now()
)
