INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-006', 'aws-clf', 'Comparando EC2 Instance Savings Plans de 3 anos All Upfront com Compute Savings Plans de 3 anos All Upfront para a mesma família m6i em us-east-1, qual a diferença esperada de desconto?',
  '[{"id":"A","text":"Compute SP sempre dá maior desconto por ser mais flexível"},{"id":"B","text":"EC2 Instance SP dá ~72%, Compute SP dá ~66% — Instance é maior por ser mais restrito"},{"id":"C","text":"Ambos dão exatamente o mesmo desconto"},{"id":"D","text":"Não existe Instance SP de 3 anos — só de 1 ano"}]'::jsonb, 'B',
  '{
    "summary": "EC2 Instance SP dá desconto maior (~72%) que Compute SP (~66%) na mesma família, porque exige commitment fixo em família+região.",
    "whyCorrect": "Trade-off padrão da AWS: mais restrição = mais desconto. EC2 Instance SP trava região e família; em troca, oferece desconto similar ao RI Standard. Compute SP é flexível mas paga preço pela flexibilidade.",
    "whyWrong": {
     "A": "Inverso — flexibilidade custa desconto, não dá. Compute SP é menor que Instance SP.",
     "C": "Falso — descontos diferem em até 6 pp.",
     "D": "Falso. Instance SP existe em 1 ou 3 anos, igual Compute SP."
    },
    "keyConcept": "Regra de ouro de pricing AWS: quanto mais restrição você aceita (família, região, AZ, prazo, pagamento upfront), maior o desconto.",
    "compareWith": [
     "RI Standard (~72%)",
     "RI Convertible (~66%)",
     "Compute SP (~66%)",
     "EC2 Instance SP (~72%)"
    ],
    "realWorldContext": "Padrão de mercado: usar EC2 Instance SP para o baseline ''cravado'' (família que você TEM CERTEZA que vai manter) + Compute SP para a camada flexível.",
    "commonMistakes": "Comprar 100% em EC2 Instance SP de uma família — qualquer mudança de família desperdiça o SP.",
    "tutorSeeds": [
     "Posso ter EC2 Instance SP e Compute SP ativos ao mesmo tempo?",
     "Qual a ordem de aplicação de descontos entre RI, Instance SP e Compute SP?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'recall', '["savings-plans","compute-sp","instance-sp"]'::jsonb, 'ai-draft', 'active', now(), now()
)
