INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-007', 'aws-clf', 'Equipe FinOps quer entender a ordem em que descontos são aplicados quando uma conta tem RI Standard, EC2 Instance SP e Compute SP ativos simultaneamente. Qual é a ordem correta?',
  '[{"id":"A","text":"Compute SP → Instance SP → RI"},{"id":"B","text":"É aleatório a cada hora"},{"id":"C","text":"RI → EC2 Instance SP → Compute SP"},{"id":"D","text":"Sempre o que dá maior desconto primeiro, ignorando o tipo"}]'::jsonb, 'C',
  '{
    "summary": "Ordem fixa: RI primeiro (descontos mais granulares), depois EC2 Instance SP, por fim Compute SP — sempre maximizando o uso dos commitments mais restritos.",
    "whyCorrect": "A AWS aplica primeiro o RI (que é instance-specific), depois EC2 Instance SP (família+região fixas) e por último Compute SP (flexível). Isso garante que o cliente não desperdice commitments mais restritivos.",
    "whyWrong": {
     "A": "Ordem inversa — gastaria Compute SP primeiro e poderia deixar RI/Instance SP ocioso.",
     "B": "Não é aleatório — há ordem determinística documentada.",
     "D": "Não é por desconto, é por especificidade do commitment."
    },
    "keyConcept": "Aplicação de descontos vai do mais específico para o mais flexível, protegendo o cliente de desperdiçar commitments com escopo estreito.",
    "compareWith": [
     "Bin-packing de descontos",
     "Como Cost Explorer mostra utilização de RI/SP"
    ],
    "realWorldContext": "Cost Explorer → Reservations / Savings Plans Utilization mostra % de uso de cada commitment. Ideal: RI e Instance SP a 100%, Compute SP a 100% — qualquer < 95% é sinal de over-commitment.",
    "commonMistakes": "Comprar RI Standard zonal e Compute SP cobrindo a mesma instância — RI é aplicado primeiro, mas se RI vence e Compute SP sobra, há período de overlap mal otimizado.",
    "tutorSeeds": [
     "Como ver a ordem de aplicação na fatura?",
     "O que é ''unused commitment'' e como evitar?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'best-practice', '["savings-plans","ri","discount-order"]'::jsonb, 'ai-draft', 'active', now(), now()
)
