INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-008', 'aws-clf', 'Após 18 meses do SP de 3 anos, o time descobre que está sub-utilizando o commitment ($/h efetivo está em 70% do plano). Qual ação está disponível?',
  '[{"id":"A","text":"Cancelar o SP e receber reembolso proporcional"},{"id":"B","text":"Reduzir o commitment $/h via console"},{"id":"C","text":"Trocar por outro SP de prazo menor"},{"id":"D","text":"Continuar pagando o commitment; SPs não podem ser cancelados nem reduzidos"}]'::jsonb, 'D',
  '{
    "summary": "Savings Plans não podem ser cancelados, reduzidos nem trocados; o commitment é firme até o fim do prazo.",
    "whyCorrect": "Diferente de RI Convertible (que permite trocar por outro RI Convertible), SPs são compromissos firmes. AWS oferece em troca a flexibilidade interna (cross-família/região) — mas não cancelamento.",
    "whyWrong": {
     "A": "Não há reembolso. Após compra, o commitment é irrevogável.",
     "B": "Console não tem opção de reduzir; apenas de comprar SPs adicionais.",
     "C": "SPs não podem ser trocados — só RI Convertible tem essa flexibilidade."
    },
    "keyConcept": "Savings Plans = trade-off entre flexibilidade de uso (cross-família/região) e flexibilidade financeira (sem cancelamento). RI Convertible tem flexibilidade financeira (troca), mas é mais limitado em uso.",
    "compareWith": [
     "RI Standard (no cancelamento, vendável no Marketplace)",
     "RI Convertible (trocável)",
     "On-Demand"
    ],
    "realWorldContext": "Erro caro: comprar 3 anos em volume agressivo e ter contração de workload. Best-practice é começar com 60–70% do baseline em SP, deixar 30–40% em On-Demand para absorver volatilidade.",
    "commonMistakes": "Achar que ''Convertible'' aplica a SP — não aplica. Só RI Convertible permite troca.",
    "tutorSeeds": [
     "Posso revender SP no Marketplace?",
     "Como mitigar over-commitment de SP?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'troubleshoot', '["savings-plans","cancellation","commitment"]'::jsonb, 'ai-draft', 'active', now(), now()
)
