INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-009', 'aws-clf', 'Empresa quer flexibilidade para trocar de família (de m5 para m7i, depois para m7g Graviton) ao longo de 3 anos, sem perder o desconto. Qual instrumento de compra é o adequado?',
  '[{"id":"A","text":"Reserved Instances Convertible"},{"id":"B","text":"Reserved Instances Standard regional"},{"id":"C","text":"EC2 Instance Savings Plans"},{"id":"D","text":"Spot Instances com fleet"}]'::jsonb, 'A',
  '{
    "summary": "RI Convertible é o único que permite trocar família/OS/tenancy/região durante o termo, mantendo o desconto.",
    "whyCorrect": "RI Convertible permite operações ''exchange'' — troca por outro RI Convertible de igual ou maior valor. Suporta mudança de família, OS, tenancy e região. Ideal para roadmaps multi-família.",
    "whyWrong": {
     "B": "RI Standard regional é fixo em família; só permite mudar tamanho dentro da mesma família. Pode ser vendido no Marketplace, mas não trocado.",
     "C": "EC2 Instance SP é fixo em família+região; não permite troca de família.",
     "D": "Spot não tem ''desconto fixo''; é preço de mercado volátil e pode ser interrompido."
    },
    "keyConcept": "RI Convertible troca desconto (~66% vs ~72% do Standard) por flexibilidade contratual de mudança de família/OS/tenancy.",
    "compareWith": [
     "RI Standard",
     "Compute SP (mais flexível ainda, sem precisar de exchange)"
    ],
    "realWorldContext": "Convertible já foi muito usado, mas Compute SP cobre 80% dos casos com menos burocracia (sem precisar fazer ''exchange''). Convertible ainda faz sentido em famílias específicas que SP não cobre bem.",
    "commonMistakes": "Confundir Convertible com Standard regional — Standard só muda size dentro da família, não troca família.",
    "tutorSeeds": [
     "Quando RI Convertible ainda vale mais que Compute SP?",
     "Como funciona a operação ''exchange'' de RI Convertible?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["ri","convertible","exchange"]'::jsonb, 'ai-draft', 'active', now(), now()
)
