INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-010', 'aws-clf', 'Para garantir capacidade reservada (capacity reservation) numa AZ específica para um workload de baixa latência, qual variante de RI é a única que oferece capacity reservation por design?',
  '[{"id":"A","text":"RI Standard regional"},{"id":"B","text":"RI Standard zonal"},{"id":"C","text":"RI Convertible regional"},{"id":"D","text":"Compute Savings Plans"}]'::jsonb, 'B',
  '{
    "summary": "Apenas Zonal RIs reservam capacidade na AZ; Regional RIs e SPs dão apenas billing discount, sem garantia de capacidade.",
    "whyCorrect": "RI Standard zonal especifica a AZ e reserva capacidade ali (a AWS garante que a instância poderá ser lançada). Regional RIs só dão desconto sobre uso sem reservar capacidade.",
    "whyWrong": {
     "A": "Regional RI dá desconto e flexibilidade de AZ, MAS não reserva capacidade — em evento de scarcity, pode haver Insufficient Capacity Error.",
     "C": "Convertible regional também não reserva capacidade.",
     "D": "Savings Plans nunca reservam capacidade — são puramente desconto."
    },
    "keyConcept": "Reserva de capacidade vs reserva de desconto: zonal RI faz os dois; regional RI e SP fazem só desconto. Para capacidade pura, existe também On-Demand Capacity Reservation (sem desconto).",
    "compareWith": [
     "On-Demand Capacity Reservation (ODCR)",
     "Capacity Blocks for ML"
    ],
    "realWorldContext": "Empresas em mercados regulados (finance, healthcare) com DR multi-AZ usam zonal RI para garantir failover. Hoje a alternativa moderna é Compute SP + ODCR para separar desconto de capacidade.",
    "commonMistakes": "Comprar Regional RI achando que reserva capacidade — em evento de capacidade insuficiente da AZ, lança ICE.",
    "tutorSeeds": [
     "O que é On-Demand Capacity Reservation?",
     "Capacity Blocks for ML — quando usar?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'best-practice', '["ri","zonal","capacity-reservation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
