INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-011', 'aws-clf', 'Um RI Standard de 3 anos foi comprado há 18 meses, mas o workload foi descontinuado. A empresa quer recuperar parte do valor. Qual opção existe?',
  '[{"id":"A","text":"Cancelar diretamente no console com reembolso proporcional"},{"id":"B","text":"Trocar por On-Demand credits via Support"},{"id":"C","text":"Vender no AWS Reserved Instance Marketplace"},{"id":"D","text":"Converter em Savings Plan equivalente"}]'::jsonb, 'C',
  '{
    "summary": "RI Standard pode ser listado e vendido no Reserved Instance Marketplace para outros clientes AWS — recupera parte do valor não consumido.",
    "whyCorrect": "RI Marketplace é o canal oficial. Vendedor define preço, AWS cobra taxa de 12% sobre o valor recebido. Comprador adquire RI com termo restante. Standard regional e zonal são vendíveis.",
    "whyWrong": {
     "A": "Não há cancelamento direto com reembolso para RI.",
     "B": "Support não converte RI em créditos genéricos.",
     "D": "Não há conversão automática RI→SP. SP precisa ser comprado separadamente."
    },
    "keyConcept": "RI Marketplace é o único mecanismo de ''saída'' antes do fim do termo para RI Standard. Convertible NÃO pode ser vendido no Marketplace (exchange é a saída deles).",
    "compareWith": [
     "RI Convertible exchange",
     "Savings Plans (sem saída possível)"
    ],
    "realWorldContext": "Conta vendedora precisa ter US Bank Account configurada. Compradores acham bons preços em RIs com 6–12 meses restantes — bom para projetos curtos.",
    "commonMistakes": "Tentar vender RI Convertible no Marketplace — não é elegível. Apenas Standard.",
    "tutorSeeds": [
     "Como precificar um RI no Marketplace?",
     "Por que Convertible não é vendável?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'troubleshoot', '["ri","marketplace","resale"]'::jsonb, 'ai-draft', 'active', now(), now()
)
