INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-012', 'aws-clf', 'Diferença entre RI Standard ''regional'' e ''zonal'' (mesma família, mesmo prazo): qual afirmação é correta?',
  '[{"id":"A","text":"Regional dá maior desconto e reserva capacidade em qualquer AZ"},{"id":"B","text":"Zonal cobre múltiplas regiões; regional só uma"},{"id":"C","text":"Não há diferença prática"},{"id":"D","text":"Zonal dá maior desconto e reserva capacidade na AZ; regional dá flexibilidade de AZ/size mas não reserva capacidade"}]'::jsonb, 'D',
  '{
    "summary": "Zonal: maior desconto + capacity reservation, mas trava AZ. Regional: desconto menor, flexibilidade de AZ/size dentro da família, sem capacidade reservada.",
    "whyCorrect": "Trade-off clássico: zonal entrega o máximo (desconto + capacidade) em troca de rigidez de AZ. Regional troca capacidade por flexibilidade — útil para workloads que escalam entre AZs.",
    "whyWrong": {
     "A": "Inverso — regional dá desconto menor que zonal, e não reserva capacidade em nenhuma AZ.",
     "B": "Nenhum dos dois cobre múltiplas regiões — RI é sempre por região. Para múltiplas regiões use Compute SP.",
     "C": "Há diferença significativa em capacidade e flexibilidade."
    },
    "keyConcept": "Eixo de RI: especificidade (Zonal > Regional) determina desconto e capacidade. Quanto mais específico, mais desconto e mais garantia, menos flexibilidade.",
    "compareWith": [
     "RI Convertible",
     "On-Demand Capacity Reservation"
    ],
    "realWorldContext": "Workloads stateful (RDS, NoSQL self-managed) em AZ fixa: zonal RI. Workloads stateless atrás de ALB com Auto Scaling cross-AZ: regional RI.",
    "commonMistakes": "Comprar regional achando que reserva capacidade — em events de capacity scarcity, lança ICE.",
    "tutorSeeds": [
     "Como migrar de zonal RI para regional RI?",
     "Quando vale a pena a flexibilidade de regional vs o desconto extra de zonal?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'recall', '["ri","zonal","regional"]'::jsonb, 'ai-draft', 'active', now(), now()
)
