INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-013', 'aws-clf', 'Equipe quer rodar workload Spot com diversificação máxima entre famílias e AZs para minimizar interrupções. Qual abordagem é a recomendada pela AWS?',
  '[{"id":"A","text":"EC2 Spot Fleet ou EC2 Auto Scaling Group com allocation strategy ''price-capacity-optimized''"},{"id":"B","text":"On-Demand Capacity Reservation com Spot fallback"},{"id":"C","text":"Spot Block de 6 horas (sem interrupção garantida)"},{"id":"D","text":"Single instance Spot na maior família disponível"}]'::jsonb, 'A',
  '{
    "summary": "Spot Fleet/ASG com ''price-capacity-optimized'' diversifica entre famílias/AZs escolhendo pools com melhor combinação preço+capacidade — minimiza interrupção.",
    "whyCorrect": "''price-capacity-optimized'' é a estratégia recomendada hoje pela AWS (substituiu ''capacity-optimized'' como padrão). Escolhe pools considerando ambos: preço atual e disponibilidade de capacidade. Resultado: ~60% menos interrupção que estratégias antigas.",
    "whyWrong": {
     "B": "ODCR é On-Demand, não tem ''Spot fallback'' nativo. Misturar é via Mixed Instance Policy no ASG, não em ODCR.",
     "C": "Spot Blocks foram DESCONTINUADOS para novas instâncias (deprecated). Não estão mais disponíveis.",
     "D": "Single instance é exatamente o anti-padrão — sem diversificação, qualquer reclaim daquele pool derruba tudo."
    },
    "keyConcept": "Spot interruption se minimiza por diversificação (mais pools = menos correlação de reclaim). Estratégia atual: price-capacity-optimized.",
    "compareWith": [
     "lowest-price (mais barato mas mais interrupção)",
     "capacity-optimized (foco em capacidade, ignora preço)"
    ],
    "realWorldContext": "EMR, Karpenter no EKS, ECS Capacity Providers usam Spot Fleet com price-capacity-optimized + 10+ instance types diversificados. Interrupção rate cai para <5%.",
    "commonMistakes": "Usar ''lowest-price'' como estratégia — economiza centavos mas eleva taxa de interrupção significativamente.",
    "tutorSeeds": [
     "Por que Spot Block foi descontinuado?",
     "Como o 2-minute warning de Spot interruption funciona?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'best-practice', '["spot","spot-fleet","allocation-strategy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
