INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-014', 'aws-clf', 'Workload Spot precisa drainar conexões e salvar checkpoint antes de ser interrompido. Qual mecanismo AWS notifica a instância?',
  '[{"id":"A","text":"SNS topic gerenciado pela AWS automaticamente assinado"},{"id":"B","text":"Spot Interruption Notice — disponível em IMDS e EventBridge, com 2 minutos de antecedência"},{"id":"C","text":"CloudWatch alarm acionado por métrica ''SpotInterruptPending''"},{"id":"D","text":"Não há notificação — a instância é encerrada sem aviso"}]'::jsonb, 'B',
  '{
    "summary": "Spot Interruption Notice é entregue via IMDS (Instance Metadata Service em /latest/meta-data/spot/instance-action) e como evento EventBridge, com 2 minutos de antecedência.",
    "whyCorrect": "Dois canais: (1) IMDS poll: app dentro da instância consulta endpoint; (2) EventBridge: rule reage ao evento ''EC2 Spot Instance Interruption Warning'' e dispara Lambda/SQS para orquestrar drain. 2 minutos é suficiente para checkpoint leve.",
    "whyWrong": {
     "A": "Não há SNS topic gerenciado automaticamente. Pode-se configurar via EventBridge → SNS, mas não vem pronto.",
     "C": "Não existe métrica nativa ''SpotInterruptPending'' no CloudWatch — o canal é EventBridge.",
     "D": "Há sim 2 minutos de notice. Antes disso, a instância também pode receber ''rebalance recommendation'' (signal preventivo)."
    },
    "keyConcept": "Spot Interruption Notice = 2 min de aviso; Rebalance Recommendation = signal preventivo, sem deadline fixo, indicando elevado risco de reclaim em breve.",
    "compareWith": [
     "EC2 Rebalance Recommendation",
     "ASG Lifecycle Hooks"
    ],
    "realWorldContext": "Karpenter + Spot usa rebalance recommendation para começar a substituir nodes ANTES dos 2 min do interrupt notice — drain limpo sem perda de pods.",
    "commonMistakes": "Esperar SNS sem configurar a EventBridge rule. Outro: ignorar rebalance recommendation achando que basta o 2-min notice.",
    "tutorSeeds": [
     "Diferença entre rebalance recommendation e interruption notice?",
     "Como testar o handler de interrupção em desenvolvimento?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["spot","interruption","eventbridge","imds"]'::jsonb, 'ai-draft', 'active', now(), now()
)
