INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-015', 'aws-clf', 'Time discute Spot Blocks (defined duration Spot) para job batch de 4 horas. Qual é a situação atual desse modelo?',
  '[{"id":"A","text":"Funciona normalmente em todas as regiões"},{"id":"B","text":"Só disponível em regiões US"},{"id":"C","text":"Foi descontinuado para novos workloads — não disponível para novas contas/instâncias"},{"id":"D","text":"Renomeado para Spot Reservation"}]'::jsonb, 'C',
  '{
    "summary": "Spot Blocks (defined duration) foram descontinuados pela AWS para novos workloads — a recomendação é usar Spot regular com handling adequado ou EC2 On-Demand para jobs curtos críticos.",
    "whyCorrect": "AWS oficialmente descontinuou Spot Blocks (''defined duration Spot'') por baixo uso e overlap com Spot regular bem configurado. Não está disponível em novas implantações.",
    "whyWrong": {
     "A": "Falso — está descontinuado globalmente para novos workloads.",
     "B": "Não é uma restrição regional; é descontinuação global.",
     "D": "Não foi renomeado — foi removido. Não existe ''Spot Reservation''."
    },
    "keyConcept": "Modelos legacy: AWS descontinua periodicamente features pouco usadas (Spot Blocks, EC2 Classic, T2 Unlimited override, etc.). Verificar status atual antes de planejar.",
    "compareWith": [
     "Spot regular com diversificação",
     "Capacity Blocks for ML (novo, ainda existe)"
    ],
    "realWorldContext": "Para jobs batch de duração definida (4h), best practice atual: Spot regular com checkpoint + retry, ou On-Demand se downtime impactar SLA.",
    "commonMistakes": "Estudar material antigo de certificação que ainda menciona Spot Blocks como vivos.",
    "tutorSeeds": [
     "Quais outras features foram descontinuadas em EC2 recentemente?",
     "Como o exame CLF-C02 cobre features descontinuadas?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'recall', '["spot","spot-blocks","deprecated"]'::jsonb, 'ai-draft', 'active', now(), now()
)
