INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-016', 'aws-clf', 'Time FinOps quer fazer queries SQL ad-hoc sobre todos os custos detalhados da última 12 meses (linha por linha de uso). Qual combinação de ferramentas atende?',
  '[{"id":"A","text":"Cost Explorer com filtro avançado"},{"id":"B","text":"AWS Budgets com SQL builder"},{"id":"C","text":"AWS Pricing Calculator com export"},{"id":"D","text":"Cost and Usage Report (CUR) em S3 + Athena (ou Redshift/QuickSight)"}]'::jsonb, 'D',
  '{
    "summary": "CUR exporta o detalhamento de cobrança linha-a-linha para S3 (Parquet ou CSV); Athena consulta diretamente com SQL padrão.",
    "whyCorrect": "Cost and Usage Report é o dataset mais granular da AWS (linha por linha de uso, com tags, RI/SP allocation, blended/unblended cost). Em Parquet particionado por mês, Athena consulta em segundos.",
    "whyWrong": {
     "A": "Cost Explorer é poderoso mas com granularidade limitada e SEM SQL — UI filtros + API.",
     "B": "Budgets não tem SQL builder; serve para definir limites com alertas.",
     "C": "Pricing Calculator estima custo futuro, não relata uso passado."
    },
    "keyConcept": "Stack de FinOps avançado: CUR → S3 → Athena/Redshift → QuickSight/Tableau. Esse é o padrão para empresas que precisam de SQL flexível e dashboards customizados.",
    "compareWith": [
     "Cost Explorer (UI/API, sem SQL)",
     "AWS Cost Anomaly Detection (detecção, não query)"
    ],
    "realWorldContext": "Empresas grandes mantêm CUR em Parquet em S3 + Glue Crawler + Athena workgroup dedicado para FinOps. QuickSight conecta para dashboards. Custo do storage CUR é desprezível.",
    "commonMistakes": "Tentar fazer análise complexa só com Cost Explorer e bater no limite de granularidade. Outro: não habilitar CUR no início e depois precisar de retroativo (CUR só gera a partir da ativação).",
    "tutorSeeds": [
     "Qual a diferença entre blended e unblended cost no CUR?",
     "Como queriar CUR no Athena com particionamento eficiente?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["cur","athena","finops"]'::jsonb, 'ai-draft', 'active', now(), now()
)
