INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-017', 'aws-clf', 'Empresa tem 80 contas em uma Organization. Quer agrupar custo por ''projeto'', ''time'' e ''ambiente'' independentemente de tags inconsistentes nas contas. Qual feature do AWS Billing entrega isso?',
  '[{"id":"A","text":"Cost Categories"},{"id":"B","text":"Cost Allocation Tags somente"},{"id":"C","text":"Resource Groups"},{"id":"D","text":"Tag Policies"}]'::jsonb, 'A',
  '{
    "summary": "Cost Categories agrupa custos via regras (account ID, service, tag, region, charge type, etc.) — independente de tagging consistente.",
    "whyCorrect": "Cost Categories permite criar dimensões customizadas (ex: ''Projeto Alpha'' = contas 111, 222 + tag Project=alpha). Funciona em Cost Explorer, Budgets e CUR como dimensão pivotável.",
    "whyWrong": {
     "B": "Cost Allocation Tags só funciona se as tags estão presentes e ativadas em billing. Não resolve tagging inconsistente.",
     "C": "Resource Groups agrupa recursos para gerenciamento (não para billing). Não é dimensão de Cost Explorer.",
     "D": "Tag Policies validam/padronizam tags (governança), mas não criam dimensões de billing."
    },
    "keyConcept": "Cost Categories = camada de regras lógicas sobre o dado de custo. Resolve fragmentação de tagging sem precisar refazer tags em todos os recursos.",
    "compareWith": [
     "Cost Allocation Tags (tag-based)",
     "Resource Groups (management)",
     "Tag Policies (governance)"
    ],
    "realWorldContext": "Empresas que herdaram tagging caótico (M&A, equipes diferentes) usam Cost Categories como ''camada de tradução'' até estabilizar tag policy. Suporta inheritance entre categorias.",
    "commonMistakes": "Tentar resolver com Cost Allocation Tags em ambiente sem disciplina de tagging — leva meses.",
    "tutorSeeds": [
     "Cost Categories vs Cost Allocation Tags — quando usar cada?",
     "Como aplicar Cost Categories retroativamente?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["cost-categories","finops"]'::jsonb, 'ai-draft', 'active', now(), now()
)
