INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-018', 'aws-clf', 'Empresa quer detecção automática de gastos anômalos (picos repentinos) por serviço, conta ou Cost Category, com alerta por email/SNS. Qual ferramenta entrega isso nativamente?',
  '[{"id":"A","text":"AWS Budgets com threshold dinâmico"},{"id":"B","text":"AWS Cost Anomaly Detection"},{"id":"C","text":"CloudWatch Anomaly Detection"},{"id":"D","text":"Trusted Advisor"}]'::jsonb, 'B',
  '{
    "summary": "AWS Cost Anomaly Detection usa ML para detectar gastos fora do padrão histórico e alertar via SNS/email, organizado por monitor (service/account/Cost Category/tag).",
    "whyCorrect": "É um serviço dedicado de FinOps: ML treinado em histórico, detecção contínua, suporta múltiplos ''monitors'' segmentados, integrado a SNS/email. Não exige threshold manual.",
    "whyWrong": {
     "A": "Budgets exige threshold explícito (fixo ou % do baseline). Não usa ML para detecção de anomalia.",
     "C": "CloudWatch Anomaly Detection é para métricas técnicas (CPU, latência, etc.), não para custo.",
     "D": "Trusted Advisor traz recomendações estáticas de economia, não detecção de anomalia em tempo real."
    },
    "keyConcept": "Cost Anomaly Detection = detecção; Budgets = limites; Cost Explorer = análise; CUR = dado bruto. Cada um tem papel distinto na pilha FinOps.",
    "compareWith": [
     "AWS Budgets",
     "CloudWatch alarms",
     "AWS Trusted Advisor"
    ],
    "realWorldContext": "Padrão de configuração: 1 monitor por linha de negócio + 1 monitor ''service-level'' geral. Threshold de alerta tipicamente $100 ou 10% — abaixo disso, vira ruído.",
    "commonMistakes": "Achar que Budgets faz detecção de anomalia — Budgets só dispara em threshold fixo definido por você.",
    "tutorSeeds": [
     "Como Cost Anomaly Detection escolhe o baseline?",
     "Pode-se suprimir false positives recorrentes?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'scenario', '["cost-anomaly-detection","finops","alerting"]'::jsonb, 'ai-draft', 'active', now(), now()
)
