INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-019', 'aws-clf', 'Cost Explorer mostra que 35% do gasto de EC2 está ''Unblended'' diferente de ''Amortized''. Qual a diferença conceitual entre essas duas visões?',
  '[{"id":"A","text":"Unblended inclui taxas; Amortized exclui"},{"id":"B","text":"São sinônimos"},{"id":"C","text":"Unblended é cobrança real do mês; Amortized distribui custos upfront de RI/SP ao longo do termo"},{"id":"D","text":"Amortized é o preço bruto; Unblended é com desconto aplicado"}]'::jsonb, 'C',
  '{
    "summary": "Unblended = visão de cash (o que foi cobrado naquele mês). Amortized = distribuição contábil de pagamentos upfront ao longo do prazo do RI/SP.",
    "whyCorrect": "Se você compra RI All Upfront de $36.000 por 3 anos, Unblended mostra $36k no mês 1 e $0 nos seguintes; Amortized mostra $1.000/mês durante 36 meses. Para análise de unit economics, use Amortized.",
    "whyWrong": {
     "A": "Diferença não é sobre taxas; é sobre tratamento de upfront.",
     "B": "Não são sinônimos — visões diferentes do mesmo dado.",
     "D": "Inverso na ideia — mas ambos consideram desconto."
    },
    "keyConcept": "Blended cost = média entre contas da Org (legado). Unblended = cobrança real por conta. Amortized = distribuição de pagamentos upfront. Net Amortized = amortized líquido de RI/SP refunds.",
    "compareWith": [
     "Blended cost (legacy)",
     "Net unblended",
     "Net amortized"
    ],
    "realWorldContext": "Times de FinOps reportam unit economics ($ por usuário, por API call) usando Amortized para não distorcer o mês de compra de RI/SP. Time financeiro vê Unblended para gestão de caixa.",
    "commonMistakes": "Apresentar custo por feature usando Unblended e ver ''queda artificial'' depois do mês 1 de RI upfront — métrica enviesada.",
    "tutorSeeds": [
     "Como CUR expõe blended/unblended/amortized?",
     "Quando usar Blended cost ainda hoje?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'recall', '["cost-explorer","amortized","unblended"]'::jsonb, 'ai-draft', 'active', now(), now()
)
