INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-020', 'aws-clf', 'Equipe SRE quer disparar ação automática quando um Budget atinge 90% — por exemplo, anexar SCP de Deny para impedir lançamento de novas instâncias. Qual feature da AWS entrega isso?',
  '[{"id":"A","text":"Cost Anomaly Detection Hooks"},{"id":"B","text":"CloudWatch Alarm com SNS"},{"id":"C","text":"Trusted Advisor Auto-Remediation"},{"id":"D","text":"AWS Budgets Actions"}]'::jsonb, 'D',
  '{
    "summary": "AWS Budgets Actions automatiza respostas quando um Budget é violado — aplicar SCP, IAM policy, parar EC2/RDS, etc.",
    "whyCorrect": "Budgets Actions permite vincular ações concretas ao threshold: anexar SCP de Deny, aplicar IAM policy custom, executar SSM Automation, parar EC2/RDS. Aprovação manual ou automática.",
    "whyWrong": {
     "A": "Cost Anomaly Detection alerta via SNS, mas não tem ''hooks'' que apliquem SCPs. Você precisa orquestrar via Lambda.",
     "B": "CloudWatch + SNS notifica humano; não anexa SCP nativamente.",
     "C": "Trusted Advisor não tem auto-remediation nativa (recomenda, não age)."
    },
    "keyConcept": "Budgets evoluiu de ''apenas alerta'' para ''enforcement'': Actions fecham o loop entre detecção e mitigação.",
    "compareWith": [
     "EventBridge + Lambda (DIY equivalente)",
     "Service Control Policies"
    ],
    "realWorldContext": "Padrão em sandboxes: Budget de $500/mês com Action que anexa SCP de Deny para ec2:RunInstances ao atingir 100%. Evita ''PoC que vira produção sem aviso''.",
    "commonMistakes": "Confiar só em alerta de Budget e ninguém olhar o email no fim de semana — gasto explode antes da resposta humana.",
    "tutorSeeds": [
     "Como reverter Budget Action depois?",
     "Quais permissões a Budgets Actions role precisa?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["budgets","budget-actions","automation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
