INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-021', 'aws-clf', 'Time precisa monitorar especificamente se a utilização dos seus Savings Plans está caindo abaixo de 95% (sinal de over-commitment). Qual tipo de Budget é apropriado?',
  '[{"id":"A","text":"Savings Plans Utilization Budget"},{"id":"B","text":"Cost Budget com filtro de SP"},{"id":"C","text":"Usage Budget em EC2-Hours"},{"id":"D","text":"Reservation Budget Convertible-only"}]'::jsonb, 'A',
  '{
    "summary": "Savings Plans Utilization Budget alerta quando a utilização do commitment cai abaixo de um % definido — diagnóstico direto de over-commitment.",
    "whyCorrect": "Tipo nativo de Budget dedicado a SP utilization: você define o piso (ex: 95%) e recebe alerta se cair. Existe também Coverage Budget (% do uso elegível coberto por SP) e RI Utilization/Coverage equivalents.",
    "whyWrong": {
     "B": "Cost Budget monitora gasto $, não utilização %.",
     "C": "Usage Budget conta horas de uso, não cobre métrica de utilization de SP.",
     "D": "Não existe ''Reservation Budget Convertible-only'' como tipo — RI tem Utilization e Coverage budgets, sem filtro Convertible-only nativo."
    },
    "keyConcept": "4 tipos de Budget: Cost, Usage, Reservation Utilization/Coverage, Savings Plans Utilization/Coverage. Cada um responde uma pergunta diferente.",
    "compareWith": [
     "RI Utilization Budget",
     "SP Coverage Budget"
    ],
    "realWorldContext": "FinOps maduro tem 2 budgets: SP Utilization > 95% (evitar desperdício) + SP Coverage > 70% do EC2 elegível (evitar gastar demais em On-Demand evitável).",
    "commonMistakes": "Olhar só Cost Budget e não notar que SP está sub-utilizado mensalmente.",
    "tutorSeeds": [
     "Diferença entre SP Utilization Budget e Coverage Budget?",
     "Como calcular o threshold ótimo de utilization?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["budgets","savings-plans","utilization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
