INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-022', 'aws-clf', 'Time recebeu alerta de Budget às 23h e ninguém viu. Para reduzir dependência humana, qual padrão arquitetural integra Budget Actions a workflow de aprovação corporativo?',
  '[{"id":"A","text":"Budget Action ''auto-execute'' sem aprovação — sempre"},{"id":"B","text":"Budget Action com ''approval required'' apontando para SNS topic integrado ao Slack/PagerDuty via Lambda"},{"id":"C","text":"Cron Lambda que verifica Budget a cada minuto"},{"id":"D","text":"Email para todos os usuários da conta"}]'::jsonb, 'B',
  '{
    "summary": "Budget Action com modo ''approval required'' + SNS para Slack/PagerDuty permite aprovação humana on-call sem bloquear nem ignorar.",
    "whyCorrect": "Modo ''approval required'' segura a ação até alguém aprovar via console ou API. Combinado com SNS → Lambda → Slack/PagerDuty, gera notificação acionável 24/7.",
    "whyWrong": {
     "A": "Auto-execute sem aprovação é arriscado em produção — pode parar workload crítico em alerta de falso positivo.",
     "C": "Cron a cada minuto reinventa a roda; Budget já tem trigger nativo.",
     "D": "Email broadcast vira ruído ignorado."
    },
    "keyConcept": "Defesa em profundidade: detecção (Budget) + canal de alerta acionável (PagerDuty/Slack) + capacidade de aprovar/recusar com 1 clique.",
    "compareWith": [
     "Cost Anomaly Detection alerts",
     "CloudWatch composite alarms"
    ],
    "realWorldContext": "Empresas com on-call 24/7: PagerDuty service dedicado a ''AWS Cost Anomaly + Budget Critical'' com escalation policy. SLA de 15min para responder.",
    "commonMistakes": "Apenas auto-execute em prod — pode causar outage por falso positivo de Budget.",
    "tutorSeeds": [
     "Como integrar Budget Actions com ServiceNow approval?",
     "Como auditar quem aprovou cada Budget Action?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'scenario', '["budgets","budget-actions","incident-response"]'::jsonb, 'ai-draft', 'active', now(), now()
)
