INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-023', 'aws-clf', 'Equipe quer monitorar especificamente quanto do uso EC2 elegível está coberto por RI/SP (objetivo: aumentar coverage). Qual budget atende?',
  '[{"id":"A","text":"Cost Budget filtrado por RI"},{"id":"B","text":"Usage Budget em EC2-Hours"},{"id":"C","text":"RI Coverage Budget"},{"id":"D","text":"Não existe budget nativo para coverage"}]'::jsonb, 'C',
  '{
    "summary": "RI Coverage Budget (e SP Coverage Budget equivalente) monitora % do uso elegível coberto por reservation — é a métrica certa para guiar compras adicionais.",
    "whyCorrect": "AWS oferece tipos específicos: Coverage Budget (cobertura — quanto do uso está protegido por commitment) e Utilization Budget (utilização — quanto do commitment está em uso). Para guiar compra adicional, Coverage.",
    "whyWrong": {
     "A": "Cost Budget mede $, não % de cobertura.",
     "B": "Usage Budget mede consumo, não cobertura.",
     "D": "Existe sim — Coverage Budget é nativo."
    },
    "keyConcept": "Coverage = quanto do uso está sob desconto. Utilization = quanto do desconto comprado está sendo usado. Ambos próximos de 100% = pricing eficiente.",
    "compareWith": [
     "SP Coverage Budget",
     "RI Utilization Budget"
    ],
    "realWorldContext": "Pipeline típico: Coverage < 70% sinal para comprar mais SP/RI; Utilization < 95% sinal para investigar over-commitment e ajustar futuras compras.",
    "commonMistakes": "Confundir Coverage com Utilization — eles medem coisas opostas (cobertura do uso vs uso do commitment).",
    "tutorSeeds": [
     "Como decidir entre comprar mais RI vs mais SP via Coverage Budget?",
     "Existe coverage budget para Lambda?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'recall', '["budgets","ri","coverage"]'::jsonb, 'ai-draft', 'active', now(), now()
)
