INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-024', 'aws-clf', 'Em AWS Organizations com Consolidated Billing ativo, qual NÃO é um benefício direto?',
  '[{"id":"A","text":"Volume discount tiering agregado entre contas-membro"},{"id":"B","text":"Compartilhamento automático de descontos de RI/SP entre contas"},{"id":"C","text":"Fatura única para todas as contas-membro"},{"id":"D","text":"Aumento de quotas de serviço automaticamente em todas as contas"}]'::jsonb, 'D',
  '{
    "summary": "Quotas de serviço são por conta e região — Consolidated Billing não muda quotas. Os outros 3 itens SÃO benefícios reais.",
    "whyCorrect": "Quotas (ex: número de VPCs, EIPs, EC2 vCPU) são definidos por conta+região e não compartilhados via Organizations. Aumento exige Service Quotas request per account ou IPM por nível de Support.",
    "whyWrong": {
     "A": "É benefício real: volume tiering (ex: S3, data transfer) considera o consumo agregado da Org.",
     "B": "É benefício real: RI Regional e Savings Plans compartilham desconto entre contas-membro por padrão (controlável via ''sharing settings'').",
     "C": "É benefício real: payer account recebe a fatura unificada."
    },
    "keyConcept": "Consolidated Billing afeta dinheiro (descontos, volume tiers, fatura), não limites técnicos (quotas).",
    "compareWith": [
     "Service Quotas",
     "RI/SP sharing settings"
    ],
    "realWorldContext": "Erro comum em adoção de Organizations: assumir que ''agora todas as contas têm quota X'' — não. Cada conta precisa de quota request individual.",
    "commonMistakes": "Achar que Org agrega quota de vCPU e descobrir limite ao escalar prod.",
    "tutorSeeds": [
     "Como desabilitar RI/SP sharing entre contas?",
     "Volume discount tiering — quais serviços têm?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'recall', '["organizations","consolidated-billing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
