INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-025', 'aws-clf', 'Conta-membro A comprou RI Regional para m5.large em us-east-1. A conta B (mesma Org) também tem m5.large rodando. Por padrão, o RI da conta A pode dar desconto para a conta B?',
  '[{"id":"A","text":"Sim — RI sharing está ativo por padrão na Organization"},{"id":"B","text":"Não — cada conta usa só seus próprios RIs"},{"id":"C","text":"Apenas se A for o management account"},{"id":"D","text":"Só RI Zonal compartilha, Regional não"}]'::jsonb, 'A',
  '{
    "summary": "RI sharing está LIGADO por padrão na Organization. Discount excedente flui para outras contas-membro automaticamente, priorizando primeiro a conta que comprou.",
    "whyCorrect": "Setting ''Reserved Instance discount sharing'' é true por default em Organizations. Mecânica: a conta dona usa primeiro; o que sobra vira pool para outras contas com uso elegível. Mesma lógica para SP sharing.",
    "whyWrong": {
     "B": "Falso — sharing está on por default; precisaria explicitamente desligar (RI sharing = false).",
     "C": "Não há restrição de quem é management — qualquer conta dona compartilha por default.",
     "D": "Inverso — Regional RI tem flexibilidade e é compartilhável; Zonal também compartilha mas só com matching exato AZ."
    },
    "keyConcept": "Sharing default ON é decisão da AWS para maximizar uso de descontos. Desligar é caso de uso específico (ex: chargeback estrito).",
    "compareWith": [
     "Cost Allocation per account",
     "SP Sharing settings"
    ],
    "realWorldContext": "Empresas com chargeback rigoroso (cada BU paga seu) desativam sharing para que cada conta veja só descontos próprios. Caso contrário, A ''subsidia'' B sem clareza.",
    "commonMistakes": "Achar que comprou RI mas não vê desconto na conta — descoberta: foi consumido por outra conta da Org primeiro.",
    "tutorSeeds": [
     "Como desligar RI sharing por conta?",
     "Sharing afeta amortized cost por conta?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["organizations","ri-sharing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
