INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-026', 'aws-clf', 'Empresa quer que cada conta-membro pague exatamente o que consome SEM benefício de descontos cross-account. O que configurar?',
  '[{"id":"A","text":"Não há como — sharing é obrigatório"},{"id":"B","text":"Desabilitar RI/SP discount sharing nas configurações de billing da Organization"},{"id":"C","text":"Criar SCP de Deny billing:Share"},{"id":"D","text":"Comprar RI em cada conta separadamente apenas"}]'::jsonb, 'B',
  '{
    "summary": "No Billing console da management account, em ''Preferences'', pode-se desligar RI discount sharing e SP discount sharing por conta-membro.",
    "whyCorrect": "Setting explícito em Billing Preferences. Pode aplicar globalmente ou por conta específica. Quando off, RI/SP só dá desconto à conta que comprou.",
    "whyWrong": {
     "A": "Falso — é configurável, não obrigatório.",
     "C": "Não existe action ''billing:Share'' como SCP-controlável; é setting de preference.",
     "D": "Sub-ótimo — fragmenta commitments e perde eficiência. Setting de sharing é o caminho correto."
    },
    "keyConcept": "Trade-off: sharing ON maximiza uso de descontos (eficiência financeira global); sharing OFF dá visibilidade pura de chargeback (governança financeira).",
    "compareWith": [
     "Cost Categories para chargeback (alternativa que mantém sharing)",
     "Cost Allocation Tags"
    ],
    "realWorldContext": "Empresas com BUs com P&L separado e demanda de chargeback rigoroso fazem off. Empresas startup-like ou com cost center compartilhado deixam on.",
    "commonMistakes": "Tentar resolver chargeback desligando sharing sem entender que perde eficiência de pooling.",
    "tutorSeeds": [
     "Cost Categories + sharing ON resolve chargeback sem perder eficiência?",
     "Posso desligar sharing só para SP e manter para RI?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["organizations","billing-preferences","chargeback"]'::jsonb, 'ai-draft', 'active', now(), now()
)
