INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-027', 'aws-clf', 'Conta-membro foi removida da Organization. O que acontece com os Savings Plans comprados por essa conta?',
  '[{"id":"A","text":"SP é transferido automaticamente para a payer account"},{"id":"B","text":"SP é cancelado e reembolsado"},{"id":"C","text":"SP continua ativo na conta agora standalone, com mesmo termo e desconto"},{"id":"D","text":"SP vira On-Demand imediatamente"}]'::jsonb, 'C',
  '{
    "summary": "SP fica vinculado à conta que comprou. Se essa conta sai da Org, o SP segue ativa na conta standalone com mesmo termo.",
    "whyCorrect": "Ownership de SP/RI é por conta, não por Organization. Quando uma conta deixa a Org, leva consigo os commitments. Apenas o sharing entre contas se interrompe.",
    "whyWrong": {
     "A": "Não há transferência automática para payer.",
     "B": "SP não pode ser cancelado nem reembolsado — em remoção da Org também não.",
     "D": "SP não vira On-Demand."
    },
    "keyConcept": "Commitments seguem a conta, não a Org. Movimentação de contas entre Orgs preserva RI/SP.",
    "compareWith": [
     "RI transfer (Convertible exchange dentro da mesma conta)",
     "Account migration"
    ],
    "realWorldContext": "Em M&A, divestiture, ou reorganização interna, planejar SP/RI ownership cuidadosamente — comprar na conta certa importa para futuras separações.",
    "commonMistakes": "Comprar todo SP na management account ''para centralizar'' e descobrir que ao quebrar a Org, todo o commitment fica na ex-management.",
    "tutorSeeds": [
     "Como migrar SP entre contas?",
     "Account migration entre Orgs — passos?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'troubleshoot', '["organizations","savings-plans","account-migration"]'::jsonb, 'ai-draft', 'active', now(), now()
)
