INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-028', 'aws-clf', 'Empresa tem 50 contas e quer um único pagamento mensal com nota fiscal centralizada, mantendo isolamento de recursos. Qual estrutura é a correta?',
  '[{"id":"A","text":"Cross-account IAM role ''BillingPayer'' em cada conta"},{"id":"B","text":"Migrar todas as contas para uma única conta com IAM Identity Center"},{"id":"C","text":"Contratar AWS Marketplace Reseller Program"},{"id":"D","text":"AWS Organizations com Consolidated Billing — management account paga e recebe fatura única"}]'::jsonb, 'D',
  '{
    "summary": "AWS Organizations + Consolidated Billing é o mecanismo nativo: management account é o pagador; member accounts mantêm isolamento de recursos.",
    "whyCorrect": "Consolidated Billing é a feature core da Org: uma fatura, ainda com detalhamento por conta no Cost Explorer e CUR. Cada conta-membro mantém seu próprio IAM, recursos, VPCs.",
    "whyWrong": {
     "A": "IAM role não muda quem paga — billing payer é definido pela hierarquia de Organizations.",
     "B": "Consolidar em uma única conta destrói isolamento (qualquer IAM error vaza recursos).",
     "C": "Reseller Program é para parceiros revendendo AWS, não para gestão interna."
    },
    "keyConcept": "Multi-account é best-practice de isolamento (security boundary). Consolidated Billing resolve o trade-off da multiplicidade de faturas.",
    "compareWith": [
     "Single account com IAM (anti-padrão)",
     "AWS Control Tower (Org + guardrails)"
    ],
    "realWorldContext": "Padrão: Control Tower (sobre Organizations) cria landing zone com OUs estruturadas, log archive, audit, billing centralizado. Single sign-on via Identity Center.",
    "commonMistakes": "Tentar resolver com IAM cross-account — não muda billing ownership.",
    "tutorSeeds": [
     "Diferença entre Consolidated Billing only vs full Organizations?",
     "Como funcionou antes do AWS Organizations existir?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'best-practice', '["organizations","consolidated-billing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
