INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-029', 'aws-clf', 'Empresa tem incidente crítico em produção e precisa de chamada arquitetural com engenheiro AWS em até 1 hora, 24/7, com Slack channel dedicado. Qual nível de Support entrega isso?',
  '[{"id":"A","text":"Enterprise Support"},{"id":"B","text":"Developer Support"},{"id":"C","text":"Business Support"},{"id":"D","text":"Enterprise On-Ramp Support"}]'::jsonb, 'A',
  '{
    "summary": "Enterprise Support é o único com TAM (Technical Account Manager) dedicado, response em <15min para Business-Critical System Down, IEM e suporte arquitetural contínuo.",
    "whyCorrect": "Enterprise: TAM dedicado, response <15min para Business-Critical System Down, Infrastructure Event Management (IEM), Concierge Billing, suporte 24/7 para todos os usuários da conta, acesso a workshops, Well-Architected reviews.",
    "whyWrong": {
     "B": "Developer: response 12–24h business hours, sem TAM, sem chat 24/7. Inadequado para produção crítica.",
     "C": "Business: response <1h para Production Down, 24/7, mas sem TAM dedicado nem IEM nem Concierge.",
     "D": "Enterprise On-Ramp: TAM pool (não dedicado), response <30min para Business-Critical, sem IEM full. Intermediário entre Business e Enterprise."
    },
    "keyConcept": "Pirâmide de Support: Basic (free, doc only) → Developer (12–24h) → Business (<1h prod down) → Enterprise On-Ramp (<30min, TAM pool) → Enterprise (<15min, TAM dedicado, IEM).",
    "compareWith": [
     "Enterprise On-Ramp (mid-tier novo)",
     "Business Support"
    ],
    "realWorldContext": "Enterprise Support custa ~$15k/mês mínimo (10% do gasto da conta com floor). Faz sentido para empresas com >$150k/mês em AWS ou com workload regulado.",
    "commonMistakes": "Tentar Business Support em workload com SLA 99.99% — sem TAM, sem IEM, atendimento por ticket via chat.",
    "tutorSeeds": [
     "O que é IEM (Infrastructure Event Management)?",
     "Quando Enterprise On-Ramp é melhor que Business?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["support","enterprise","tam"]'::jsonb, 'ai-draft', 'active', now(), now()
)
