INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-030', 'aws-clf', 'Diferença entre Trusted Advisor checks no nível Basic/Developer vs Business+/Enterprise: qual está correto?',
  '[{"id":"A","text":"Todos os tiers recebem todos os checks; só muda o canal de notificação"},{"id":"B","text":"Basic/Developer recebem apenas 7 checks core; Business+/Enterprise recebem todos os checks (~115+) em todas as 5 categorias"},{"id":"C","text":"Apenas Enterprise tem checks de Cost Optimization"},{"id":"D","text":"Trusted Advisor é pago à parte do Support"}]'::jsonb, 'B',
  '{
    "summary": "Basic/Developer recebem 7 checks core (foco em segurança e service limits); Business+/Enterprise desbloqueiam o catálogo completo nas 5 categorias.",
    "whyCorrect": "Os 7 checks core do free tier focam em alto risco: IAM use, MFA root, security groups overly permissive, S3 bucket public, EBS public snapshots, RDS public snapshots, service limits. Business+ libera o catálogo full (~115+ checks).",
    "whyWrong": {
     "A": "Falso — número de checks varia significativamente por tier.",
     "C": "Cost Optimization checks existem em Business+ também, não só Enterprise.",
     "D": "Trusted Advisor é incluído no Support — não cobra à parte."
    },
    "keyConcept": "Trusted Advisor 5 categorias: Cost Optimization, Performance, Security, Fault Tolerance, Service Limits. Free = subset de Security + Service Limits.",
    "compareWith": [
     "AWS Compute Optimizer (recommendations distintas)",
     "AWS Cost Explorer (Rightsizing recommendations)"
    ],
    "realWorldContext": "TA é primeira parada FinOps em empresas com Business Support — checks ''Underutilized EC2 Instances'' e ''Reserved Instance Optimization'' identificam economia rapidamente.",
    "commonMistakes": "Ficar no Developer Support achando que tem TA full e perder visibilidade de Cost Optimization.",
    "tutorSeeds": [
     "TA vs Compute Optimizer — quando usar cada?",
     "Como API de Trusted Advisor expõe os checks?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'recall', '["support","trusted-advisor"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
