INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-031', 'aws-clf', 'Empresa vai fazer launch importante (Black Friday) e quer suporte AWS dedicado durante o evento, com revisão pré-evento de arquitetura, monitoramento em tempo real e equipe AWS standby. Qual feature do Enterprise Support entrega isso?',
  '[{"id":"A","text":"Concierge Billing"},{"id":"B","text":"Well-Architected Review"},{"id":"C","text":"Infrastructure Event Management (IEM)"},{"id":"D","text":"Trusted Advisor Operations Review"}]'::jsonb, 'C',
  '{
    "summary": "IEM é o serviço dedicado a eventos críticos: AWS engineers revisam arquitetura antes, monitoram durante e fazem hot-line standby.",
    "whyCorrect": "Infrastructure Event Management: scope pré-evento (review arquitetural, load test analysis, scaling plan), durante (war room com AWS standby) e pós (postmortem). Incluído em Enterprise Support; em Enterprise On-Ramp é via ad-hoc charge.",
    "whyWrong": {
     "A": "Concierge Billing é equipe especializada em billing/cost — não em eventos técnicos.",
     "B": "Well-Architected Review é avaliação genérica de arquitetura, não event-specific standby.",
     "D": "Não existe esse produto nomeado."
    },
    "keyConcept": "IEM = ''AWS engineers as event SREs'' — preparação, monitoring e response durante janela crítica.",
    "compareWith": [
     "Well-Architected Review",
     "Countdown program (AWS Pro Services)"
    ],
    "realWorldContext": "Black Friday e-commerce, lançamento de produto, IPO press release, migrações grandes — momentos típicos de IEM. Solicitar 4–6 semanas antes.",
    "commonMistakes": "Achar que Business Support permite IEM — só Enterprise (e On-Ramp em modo limitado).",
    "tutorSeeds": [
     "Quantos IEMs vêm incluídos por ano no Enterprise?",
     "Diferença IEM vs AWS Countdown Premium?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["support","iem","enterprise"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
