INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-032', 'aws-clf', 'Empresa quer downgrade de Enterprise Support para Business Support para economizar. Qual consideração é crítica?',
  '[{"id":"A","text":"Perde TAM, IEM e response \u003c15min — passa a \u003c1h para Production Down sem TAM dedicado"},{"id":"B","text":"Trusted Advisor full ainda funciona mesmo em Business"},{"id":"C","text":"Concierge Billing continua disponível"},{"id":"D","text":"Letra A e B são corretas"}]'::jsonb, 'D',
  '{
    "summary": "Downgrade Enterprise→Business mantém Trusted Advisor full e response Production Down <1h, mas perde TAM, IEM, Concierge Billing e response Business-Critical <15min.",
    "whyCorrect": "Tanto (A) quanto (B) são verdadeiros. A perda principal é o suporte dedicado (TAM) e eventos críticos. Mas Trusted Advisor full E Cost Optimization Hub continuam ativos em Business+.",
    "whyWrong": {
     "A": "Verdadeiro mas incompleto — também é verdade que TA full segue.",
     "B": "Verdadeiro mas incompleto.",
     "C": "Concierge Billing é exclusivo do Enterprise — perde no downgrade."
    },
    "keyConcept": "Mapeamento de features por tier exige tabela mental: TAM, IEM, Concierge, response <15min são Enterprise-only.",
    "compareWith": [
     "Tabela completa de Support plans"
    ],
    "realWorldContext": "Empresas em fase de cost-cutting fazem downgrade temporário. Risco: incidente crítico em janela vulnerável. Plan B: tickets continuam funcionando, mas sem TAM proativo.",
    "commonMistakes": "Achar que perde tudo no downgrade — TA e support 24/7 chat continuam.",
    "tutorSeeds": [
     "Posso ter Enterprise Support em uma conta e Business em outra na mesma Org?",
     "Como ressuscitar TAM relationship depois de upgrade?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'troubleshoot', '["support","tier-comparison"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
