INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-033', 'aws-clf', 'Empresa quer comprar software de terceiro na AWS Marketplace com termo negociado, preço customizado e contrato direto com vendor. Qual modalidade atende?',
  '[{"id":"A","text":"Private Offer (Marketplace Private Offer)"},{"id":"B","text":"Public offer padrão"},{"id":"C","text":"SaaS pay-as-you-go"},{"id":"D","text":"Free Tier listing"}]'::jsonb, 'A',
  '{
    "summary": "Private Offers permitem ao vendor criar oferta customizada (preço, termo, EULA) visível apenas para a conta-alvo, cobrada via AWS bill.",
    "whyCorrect": "Private Offer é o canal padrão de Marketplace para deals enterprise: vendor cria oferta com termos negociados, comprador aceita, cobrança aparece no AWS bill consolidado. Conta como spend AWS para EDP (Enterprise Discount Program) muitas vezes.",
    "whyWrong": {
     "B": "Public offer = preço de catálogo fixo, sem negociação.",
     "C": "SaaS pay-as-you-go é modelo de cobrança (uso medido), não modalidade de contratação. Pode existir em Private Offer também.",
     "D": "Free Tier não envolve negociação."
    },
    "keyConcept": "Marketplace tem 3 modelos de pricing (SaaS subscription, SaaS contract, AMI hourly/annual) × 2 visibilidades (public/private offer). Private offer aplica sobre qualquer modelo.",
    "compareWith": [
     "BYOL (Bring Your Own License)",
     "SaaS Subscription Marketplace"
    ],
    "realWorldContext": "Datadog, Snowflake, Databricks comumente vendidos via Private Offer para enterprise — cliente consolida $ no AWS bill (compra de SP/RI fica mais escalável) e vendor recebe sem fricção de PO/invoice.",
    "commonMistakes": "Comprar tudo em Public Offer e perder negociação possível via Private.",
    "tutorSeeds": [
     "Private Offer count para AWS EDP commit?",
     "Como Channel Partner facilita Private Offer?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["marketplace","private-offer"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
