INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-034', 'aws-clf', 'Empresa já tem licença on-prem do Oracle Database e quer trazer para EC2 sem comprar nova licença pelo Marketplace. Qual modelo de licenciamento aplica?',
  '[{"id":"A","text":"License-Included (LI)"},{"id":"B","text":"BYOL — Bring Your Own License"},{"id":"C","text":"SaaS Contract"},{"id":"D","text":"Free Tier"}]'::jsonb, 'B',
  '{
    "summary": "BYOL permite usar licença adquirida fora da AWS em recursos AWS, pagando apenas compute/storage. Para Oracle, exige Dedicated Hosts em muitos casos por requisitos de licenciamento.",
    "whyCorrect": "BYOL é o modelo padrão para reutilizar licença on-prem. Para Oracle/SQL Server enterprise, costuma exigir Dedicated Host (visibilidade do hardware físico para licenciamento por socket/core).",
    "whyWrong": {
     "A": "License-Included = AMI/SaaS já vem com licença embutida no preço (você paga por hora a AWS, que repassa ao vendor).",
     "C": "SaaS Contract = compra de período prefixado de SaaS via Marketplace.",
     "D": "Free Tier = pricing tier, não modelo de licença."
    },
    "keyConcept": "Modelos de licença: BYOL (sua), LI (AWS te vende junto), SaaS subscription. AWS License Manager governa o uso de BYOL para evitar non-compliance.",
    "compareWith": [
     "License-Included AMI (RHEL, SQL Server, Windows)",
     "AWS License Manager"
    ],
    "realWorldContext": "Empresas que migram Oracle/SQL Server enterprise para AWS usam BYOL + Dedicated Hosts + License Manager para garantir compliance e evitar audit risk.",
    "commonMistakes": "Trazer Oracle via BYOL em instância EC2 normal (shared tenancy) — viola termos da maioria das licenças Oracle Enterprise.",
    "tutorSeeds": [
     "AWS License Manager — quais use cases?",
     "Por que Oracle exige Dedicated Host?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["marketplace","byol","license-manager"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
