INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-035', 'aws-clf', 'AWS Compute Optimizer recomenda ''downsizing'' de uma EC2 m5.4xlarge para m5.2xlarge com ''medium risk''. Qual ação é a correta antes de aplicar?',
  '[{"id":"A","text":"Aplicar imediatamente — Compute Optimizer só recomenda quando é seguro"},{"id":"B","text":"Ignorar — Compute Optimizer só serve para Reserved Instances"},{"id":"C","text":"Verificar métricas no detalhe (CPU/memory/network percentile), considerar burst patterns e testar em staging"},{"id":"D","text":"Trocar imediatamente por Graviton (m6g.2xlarge)"}]'::jsonb, 'C',
  '{
    "summary": "Compute Optimizer fornece recomendações baseadas em 14 dias de métricas. ''Medium risk'' indica algum picos não cobertos — validar antes de aplicar.",
    "whyCorrect": "Compute Optimizer apresenta: current type, recommended type, estimated savings, risk level (low/medium/high), métricas observadas (p99 CPU, memory se CWAgent ativo). ''Medium'' = há sinais de pico que podem regredir performance.",
    "whyWrong": {
     "A": "Recomendações são sugestões, não automações. Risk level indica confiança.",
     "B": "Falso — Compute Optimizer analisa EC2, Auto Scaling, EBS, Lambda. Não é RI-specific.",
     "D": "Migrar para Graviton exige rebuild da aplicação (ARM compatibility); não é decisão de ''aplicar imediatamente''."
    },
    "keyConcept": "Rightsizing requer dado (métricas), recomendação (Compute Optimizer) e validação (teste em staging). Pular qualquer etapa gera risco.",
    "compareWith": [
     "AWS Trusted Advisor (Underutilized EC2)",
     "Cost Explorer Rightsizing Recommendations"
    ],
    "realWorldContext": "Empresas maduras integram Compute Optimizer API em pipeline FinOps: recomendações com ''low risk'' + economia > $200/mês entram em ticket automático para revisão técnica.",
    "commonMistakes": "Aplicar ''medium/high risk'' sem teste e gerar incidente de performance. Outro: ignorar baseline de memory (precisa CWAgent ou nightly snapshot).",
    "tutorSeeds": [
     "Como habilitar memory metrics no Compute Optimizer?",
     "Compute Optimizer vs Cost Explorer Rightsizing — diferença?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["compute-optimizer","rightsizing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
