INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-036', 'aws-clf', 'Diferença entre AWS Compute Optimizer e Trusted Advisor ''Low Utilization EC2 Instances''?',
  '[{"id":"A","text":"Mesma feature com nomes diferentes"},{"id":"B","text":"Trusted Advisor é pago, Compute Optimizer é grátis"},{"id":"C","text":"Compute Optimizer só funciona em Spot"},{"id":"D","text":"Trusted Advisor faz check binário (utilização baixa); Compute Optimizer faz recomendação granular de instance type com modelo ML"}]'::jsonb, 'D',
  '{
    "summary": "TA detecta instâncias subutilizadas (regra estática). Compute Optimizer recomenda instance type específico via ML treinado em 14 dias de métricas.",
    "whyCorrect": "TA: regra simples (p.ex. CPU médio < 10% por 14 dias = subutilizada). Compute Optimizer: ML que avalia CPU, memory, network, I/O e sugere instance type específico com economia estimada e nível de risco.",
    "whyWrong": {
     "A": "São features distintas com overlap parcial.",
     "B": "Ambos têm tier free; TA full está em Business+, Compute Optimizer é free com opt-in.",
     "C": "Compute Optimizer cobre EC2, ASG, EBS, Lambda — não é Spot-only."
    },
    "keyConcept": "Trusted Advisor = checks gerais binários. Compute Optimizer = recomendação ML granular. Cost Explorer Rightsizing = visão de custo+economia projetada.",
    "compareWith": [
     "TA Low Utilization check",
     "Cost Explorer Rightsizing",
     "AWS Optimizations Hub"
    ],
    "realWorldContext": "Stack FinOps: TA para alertas básicos, Compute Optimizer para decisão de instance type, Cost Explorer para projeção financeira.",
    "commonMistakes": "Usar só TA e perder oportunidades de migração entre famílias (que Compute Optimizer destaca).",
    "tutorSeeds": [
     "AWS Optimizations Hub agrega ambos?",
     "Compute Optimizer cobra algo?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'recall', '["compute-optimizer","trusted-advisor","comparison"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
