INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-037', 'aws-clf', 'Time quer comparar Spot regular com ''Spot best-fit allocation strategy''. Qual descrição corresponde a ''price-capacity-optimized''?',
  '[{"id":"A","text":"Escolhe pools considerando combinação ótima de baixo preço E alta capacidade disponível, reduzindo interrupções"},{"id":"B","text":"Escolhe sempre o pool de menor preço, ignorando capacidade"},{"id":"C","text":"Pré-aloca capacidade On-Demand e converte em Spot"},{"id":"D","text":"Apenas reserva capacidade na AZ, sem otimizar preço"}]'::jsonb, 'A',
  '{
    "summary": "''price-capacity-optimized'' é a estratégia padrão recomendada: combina sinal de preço E capacidade para minimizar interrupções mantendo preço atrativo.",
    "whyCorrect": "AWS treinou modelo que combina ambos os sinais. Lança em pools com balanço ótimo — não é só o mais barato (volátil), não é só capacidade (caro). Substituiu ''capacity-optimized'' como recomendação padrão da AWS desde 2022.",
    "whyWrong": {
     "B": "Essa descrição é da ''lowest-price'' (estratégia antiga e arriscada).",
     "C": "Não existe esse mecanismo nomeado.",
     "D": "Confunde com Zonal RI / ODCR — capacidade pura sem otimização de preço."
    },
    "keyConcept": "Spot strategies: lowest-price (legado, arriscado), capacity-optimized (foco em capacidade, ignora preço), price-capacity-optimized (padrão atual, balanceado), diversified (espalhar uniformemente).",
    "compareWith": [
     "lowest-price",
     "capacity-optimized",
     "diversified"
    ],
    "realWorldContext": "Karpenter, EMR-on-EKS e ECS Capacity Providers usam price-capacity-optimized por padrão para alcançar <5% interruption rate em workloads ML/batch.",
    "commonMistakes": "Continuar usando lowest-price por inércia de tutoriais antigos.",
    "tutorSeeds": [
     "Quando capacity-optimized ainda faz sentido?",
     "Diversified strategy — quando aplicar?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'best-practice', '["spot","allocation-strategy","price-capacity-optimized"]'::jsonb, 'ai-draft', 'active', now(), now()
)
