INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-038', 'aws-clf', 'Empresa precisa de relatório customizado: gasto S3 por bucket, por mês, com cost allocation tag ''Team''. Cost Explorer mostra agregado da Org. Onde estão os dados granulares por bucket?',
  '[{"id":"A","text":"S3 access logs"},{"id":"B","text":"Cost and Usage Report (CUR) com nível de granularidade ''resource-level'' habilitado"},{"id":"C","text":"CloudTrail data events"},{"id":"D","text":"AWS Config"}]'::jsonb, 'B',
  '{
    "summary": "CUR com ''resource ID'' option ativa expõe cost por ARN de recurso — incluindo bucket S3, individual EC2 instance, etc.",
    "whyCorrect": "CUR é o único dataset com granularidade de resource ID + tag por linha de uso. Cost Explorer não chega a bucket-level por padrão. CUR + Athena permite SUM por bucket, por tag, por mês.",
    "whyWrong": {
     "A": "S3 access logs mostram requisições, não custo.",
     "C": "CloudTrail data events trackeia chamadas API, não custo.",
     "D": "AWS Config trackeia config/state, não custo."
    },
    "keyConcept": "Cost por recurso: CUR + resource ID + tags ativadas como cost allocation tags. Sem essas três peças, dado granular não existe.",
    "compareWith": [
     "S3 Storage Lens (storage metrics, não custo)",
     "Cost Explorer (agregado)"
    ],
    "realWorldContext": "FinOps maduro: CUR diário em S3 Parquet + Glue table + Athena workgroup. Dashboard QuickSight mostra ''custo S3 por bucket por team'' com refresh diário.",
    "commonMistakes": "Tentar fazer no Cost Explorer e bater no limite de detalhamento por recurso.",
    "tutorSeeds": [
     "Custo do próprio CUR storage e queries Athena?",
     "Como ativar cost allocation tags retroativamente?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'troubleshoot', '["cur","athena","s3","resource-level"]'::jsonb, 'ai-draft', 'active', now(), now()
)
