INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-039', 'aws-clf', 'Time usa Cost Anomaly Detection com monitor ''AWS services'' e recebe muitos falsos positivos em fim de mês (consumo recorrente de billing closing). Qual ação reduz ruído sem desativar a detecção?',
  '[{"id":"A","text":"Aumentar threshold de alerta para $5.000"},{"id":"B","text":"Desligar Cost Anomaly Detection no fim do mês"},{"id":"C","text":"Criar subscriptions específicas por dimensão (service/account/Cost Category) e ajustar thresholds por monitor"},{"id":"D","text":"Mover para AWS Budgets em vez de CAD"}]'::jsonb, 'C',
  '{
    "summary": "Segmentar monitors por dimensão e ajustar thresholds individualmente reduz ruído sem perder sensibilidade. CAD aprende padrão por monitor.",
    "whyCorrect": "CAD permite múltiplos monitors com escopos diferentes (todos os services, service específico, Cost Category, linked account, tag). ML treina por monitor, então um monitor ''EC2-only'' fica mais sensível a anomalias EC2 sem ruído de S3, etc. Subscription de alerta tem threshold próprio.",
    "whyWrong": {
     "A": "Sobe threshold global e perde sensibilidade a anomalias menores em outros services.",
     "B": "Desligar perde valor justamente quando mais precisa (mês cheio).",
     "D": "Budgets não detecta anomalias por ML — só thresholds fixos."
    },
    "keyConcept": "CAD escala por segmentação: 1 monitor genérico + N monitors específicos = melhor sinal/ruído.",
    "compareWith": [
     "AWS Budgets (limites fixos)",
     "Cost Explorer (análise manual)"
    ],
    "realWorldContext": "Padrão maduro: monitor ''service-level'' geral + monitors ''critical-service'' (EC2, RDS, OpenSearch) com threshold mais sensível. Subscriptions diferentes para email vs PagerDuty.",
    "commonMistakes": "Único monitor com threshold único — fica entre dois extremos ruins.",
    "tutorSeeds": [
     "Como suprimir anomalia recorrente?",
     "CAD funciona por linked account em Org?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'troubleshoot', '["cost-anomaly-detection","tuning"]'::jsonb, 'ai-draft', 'active', now(), now()
)
