INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v2-040', 'aws-clf', 'Empresa quer escolher rapidamente o nível de Support adequado. Workload: e-commerce em produção, ~$80k/mês gasto AWS, SLA 99.9% para usuários finais, sem TAM dedicado (mas quer response rápido). Qual tier escolher?',
  '[{"id":"A","text":"Developer Support"},{"id":"B","text":"Enterprise On-Ramp Support"},{"id":"C","text":"Enterprise Support"},{"id":"D","text":"Business Support"}]'::jsonb, 'D',
  '{
    "summary": "Business Support: response <1h para Production System Down, 24/7, Trusted Advisor full, sem TAM. Para $80k/mês sem necessidade de TAM, é o sweet spot.",
    "whyCorrect": "Business cobre: 24/7 phone/chat/email, response <1h Production Down, <4h Production Impaired, Trusted Advisor completo, AWS Support API, Infra Event Management ad-hoc. Custo: 10% do gasto AWS com floor de $100/mês. Para $80k → ~$8k/mês.",
    "whyWrong": {
     "A": "Developer: business-hours only, response 12–24h. Inadequado para 99.9% SLA.",
     "B": "Enterprise On-Ramp: TAM pool (não dedicado), response <30min, mas custa ~$5.5k mínimo + benefício marginal para esse perfil (sem necessidade de TAM).",
     "C": "Enterprise: ~$15k/mês mínimo + TAM dedicado. Overkill quando ''sem TAM dedicado'' é requisito explícito."
    },
    "keyConcept": "Escolha de Support: workload prod 24/7 SLA = Business no mínimo. TAM justifica On-Ramp/Enterprise quando há complexidade arquitetural contínua.",
    "compareWith": [
     "Tabela Support tiers",
     "Enterprise Discount Program (EDP)"
    ],
    "realWorldContext": "Padrão mid-market: Business Support entre $50k–$200k/mês gasto AWS. Acima disso, On-Ramp ou Enterprise compensa pelo TAM e IEM.",
    "commonMistakes": "Ficar em Developer para economizar e perder SLA por response 24h em incidente.",
    "tutorSeeds": [
     "Como calcular ROI de upgrade de Support?",
     "Posso ter Support diferentes em contas diferentes da mesma Org?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["support","business-tier","decision"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
