INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-001', 'aws-clf', 'Uma empresa global de e-commerce precisa de um Technical Account Manager (TAM) dedicado, atendendo apenas à sua conta, com response time de 15 minutos para incidentes business-critical e acesso ao AWS Countdown. Qual nível de Support atende esses três requisitos simultaneamente?',
  '[{"id":"A","text":"Enterprise Support"},{"id":"B","text":"Business Support"},{"id":"C","text":"Enterprise On-Ramp Support"},{"id":"D","text":"Developer Support"}]'::jsonb, 'A',
  '{
    "summary": "Apenas Enterprise Support fornece TAM dedicado, 15min de SLA para P1 (business-critical) e AWS Countdown.",
    "whyCorrect": "Enterprise Support ($15.000/mês ou 3-10% dependendo do spend) inclui TAM dedicado (não compartilhado), response time < 15 minutos para casos business-critical 24x7, AWS Concierge (billing/account), Infrastructure Event Management (IEM) incluído e acesso ao AWS Countdown (programa de eventos de larga escala como migrations, Black Friday, etc.).",
    "whyWrong": {
     "B": "Business Support ($100/mês com tier) não tem TAM (nem dedicado nem pool), nem AWS Countdown. Response time P1 é < 1 hora, não 15min.",
     "C": "Enterprise On-Ramp ($5.500/mês) tem TAM em POOL (não dedicado), response P1 < 30 minutos (não 15min) e AWS Countdown não é incluído por padrão.",
     "D": "Developer Support ($29/mês ou 3%) não tem TAM nem suporte 24x7; apenas e-mail em horário comercial."
    },
    "keyConcept": "TAM dedicado e response P1 < 15min são EXCLUSIVOS do Enterprise Support.",
    "compareWith": [
     "Enterprise On-Ramp: TAM pool, P1 < 30min",
     "Business: full Trusted Advisor + 24x7, mas SEM TAM",
     "Developer: apenas e-mail business hours"
    ],
    "realWorldContext": "Empresas Fortune 500 com cargas críticas (bancos, varejistas globais, healthcare) tipicamente assinam Enterprise. Para uma empresa com $500k/mês na AWS, 3% = $15k/mês é o mínimo.",
    "commonMistakes": "Confundir Enterprise On-Ramp com Enterprise; o On-Ramp é o tier ''meio termo'' lançado em 2021 para clientes que não justificam Enterprise pleno.",
    "tutorSeeds": [
     "Liste todos os benefícios exclusivos do Enterprise Support",
     "Quando faz sentido migrar de Business para Enterprise On-Ramp?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["support-tiers","enterprise-support","tam","sla"]'::jsonb, 'ai-draft', 'active', now(), now()
)
