INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-002', 'aws-clf', 'Qual o response time alvo para um caso ''Business-critical system down'' (P1/Severidade Crítica) no Enterprise On-Ramp Support?',
  '[{"id":"A","text":"Menos de 15 minutos, 24x7"},{"id":"B","text":"Menos de 30 minutos, 24x7"},{"id":"C","text":"Menos de 1 hora, 24x7"},{"id":"D","text":"Menos de 4 horas em horário comercial"}]'::jsonb, 'B',
  '{
    "summary": "Enterprise On-Ramp tem SLA de < 30 minutos para casos business-critical 24x7.",
    "whyCorrect": "Enterprise On-Ramp ($5.500/mês mínimo) foi posicionado como tier intermediário entre Business e Enterprise. Para casos business-critical (P1), oferece response em menos de 30 minutos, 24x7. É o segundo tier mais rápido depois de Enterprise (< 15min).",
    "whyWrong": {
     "A": "< 15 minutos é exclusivo de Enterprise Support ($15k/mês).",
     "C": "< 1 hora é o SLA de Business Support para production system down.",
     "D": "< 4 horas em horário comercial seria mais alinhado com Developer ou casos de severidade média."
    },
    "keyConcept": "Tabela de SLAs por severidade é uma das pegadinhas mais cobradas: Enterprise 15min, On-Ramp 30min, Business 1h, Developer não tem severidade crítica.",
    "compareWith": [
     "Enterprise P1: < 15min",
     "Business P1 (production down): < 1h",
     "Developer: sem P1 — apenas General Guidance (24h) e System Impaired (12h)"
    ],
    "realWorldContext": "Startups Series B/C que rodam SaaS production-grade mas ainda não escalam o suficiente para justificar Enterprise frequentemente escolhem On-Ramp.",
    "commonMistakes": "Pensar que Enterprise On-Ramp tem o mesmo SLA do Enterprise — não tem; é metade da velocidade no P1.",
    "tutorSeeds": [
     "Compare todos os SLAs entre On-Ramp e Enterprise",
     "Qual diferença prática entre On-Ramp e Business em produção?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'recall', '["support-tiers","enterprise-on-ramp","sla","response-time"]'::jsonb, 'ai-draft', 'active', now(), now()
)
