INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-003', 'aws-clf', 'Um cliente Developer Support abre um caso solicitando ajuda com ''um EC2 que travou em produção''. Qual o response time alvo da AWS para esse caso?',
  '[{"id":"A","text":"Menos de 1 hora, 24x7"},{"id":"B","text":"Menos de 15 minutos, 24x7"},{"id":"C","text":"Menos de 12 horas em horário comercial — Developer não tem severidade Production System Down"},{"id":"D","text":"Menos de 4 horas, 24x7"}]'::jsonb, 'C',
  '{
    "summary": "Developer Support NÃO oferece severidade P1/P2 de produção. Máximo é ''System Impaired'' (12h) em horário comercial.",
    "whyCorrect": "O Developer Support ($29/mês ou 3% do uso, o que for maior) é destinado a ambientes de desenvolvimento/teste. Só tem duas severidades disponíveis: ''General Guidance'' (resposta < 24 horas business hours) e ''System Impaired'' (< 12 horas business hours). Não existe nível ''Production System Down'' nem ''Business-Critical'' nesse tier. Atendimento apenas por e-mail (sem chat/phone) e apenas em horário comercial local.",
    "whyWrong": {
     "A": "< 1 hora seria Business Support (Production System Down).",
     "B": "< 15 minutos é exclusivo de Enterprise Support para P1.",
     "D": "< 4 horas seria Business Support para ''Production System Impaired''."
    },
    "keyConcept": "Developer Support não suporta workloads de produção — esse é o ponto central de upsell para Business.",
    "compareWith": [
     "Business: 4 severidades, 24x7 chat/phone/email",
     "Developer: 2 severidades, business hours, e-mail apenas"
    ],
    "realWorldContext": "Equipes que rodam workload de produção em Developer Support acabam descobrindo na hora ruim que não há canal urgente — daí a recomendação universal: produção exige Business mínimo.",
    "commonMistakes": "Achar que Developer cobre produção 24x7 porque é pago.",
    "tutorSeeds": [
     "Quais severidades estão disponíveis em cada tier?",
     "Por que produção exige Business mínimo?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'troubleshoot', '["support-tiers","developer-support","sla","production"]'::jsonb, 'ai-draft', 'active', now(), now()
)
