INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-004', 'aws-clf', 'Uma empresa quer acesso ao AWS Concierge (equipe especializada em billing, account e operations). Em quais níveis de Support esse benefício está disponível?',
  '[{"id":"A","text":"Em todos os tiers pagos (Developer, Business, Enterprise On-Ramp, Enterprise)"},{"id":"B","text":"Apenas Enterprise"},{"id":"C","text":"Business, Enterprise On-Ramp e Enterprise"},{"id":"D","text":"Apenas Enterprise On-Ramp e Enterprise"}]'::jsonb, 'D',
  '{
    "summary": "AWS Concierge é exclusivo dos dois tiers Enterprise — On-Ramp e Enterprise.",
    "whyCorrect": "O AWS Concierge é uma equipe especializada não-técnica que ajuda com billing, account management, custom reporting, programmatic discounts e Marketplace. Está disponível apenas em Enterprise On-Ramp e Enterprise. Business e Developer NÃO têm acesso.",
    "whyWrong": {
     "A": "Developer e Business não têm Concierge.",
     "B": "Tanto On-Ramp quanto Enterprise têm acesso.",
     "C": "Business não tem Concierge — esse é um diferenciador chave de On-Ramp."
    },
    "keyConcept": "Concierge = consultoria de billing/account, NÃO suporte técnico. Exclusivo do Enterprise tier (com ou sem On-Ramp).",
    "compareWith": [
     "TAM dedicado: só Enterprise",
     "Concierge: On-Ramp e Enterprise",
     "Full Trusted Advisor: Business+"
    ],
    "realWorldContext": "Empresas com complexidade de billing (Organizations com várias contas, Marketplace pesado, EDP/PPA) tipicamente justificam On-Ramp pelo Concierge isolado.",
    "commonMistakes": "Confundir Concierge (billing) com TAM (técnico).",
    "tutorSeeds": [
     "Qual a diferença entre TAM e Concierge?",
     "Quando o Concierge é mais valioso que o TAM?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["support-tiers","concierge","enterprise"]'::jsonb, 'ai-draft', 'active', now(), now()
)
