INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-005', 'aws-clf', 'Um gestor de TI quer acesso ao conjunto COMPLETO de checks do AWS Trusted Advisor (não apenas os 6 checks básicos). Qual o tier de Support mínimo necessário?',
  '[{"id":"A","text":"Business Support"},{"id":"B","text":"AWS Basic Support (gratuito)"},{"id":"C","text":"Developer Support"},{"id":"D","text":"Enterprise Support"}]'::jsonb, 'A',
  '{
    "summary": "Business Support é o tier MÍNIMO para acesso completo aos checks do Trusted Advisor.",
    "whyCorrect": "O Trusted Advisor completo (centenas de checks em Cost, Performance, Security, Fault Tolerance, Service Quotas e Operational Excellence) está disponível a partir de Business Support. Basic e Developer têm acesso apenas aos 6 ''core checks'' (S3 bucket permissions, Security Groups specific ports, IAM use, MFA root, EBS public snapshots, RDS public snapshots e Service Limits — alguns também incluídos).",
    "whyWrong": {
     "B": "Basic só tem os 6 core checks de segurança.",
     "C": "Developer também limitado aos 6 core checks.",
     "D": "Enterprise tem o completo, mas o MÍNIMO é Business."
    },
    "keyConcept": "Business = unlock completo de Trusted Advisor + 24x7 + AWS Support API.",
    "compareWith": [
     "Basic/Developer: 6 core checks",
     "Business+: full Trusted Advisor + API",
     "Enterprise: Trusted Advisor Priority (curated por TAM)"
    ],
    "realWorldContext": "Empresas que querem usar Trusted Advisor para cost optimization sistemático precisam de Business — o ROI dos checks de Cost geralmente paga o tier sozinho.",
    "commonMistakes": "Achar que Trusted Advisor é totalmente grátis no Basic.",
    "tutorSeeds": [
     "Liste os 6 core checks gratuitos",
     "Diferença entre Trusted Advisor e Trusted Advisor Priority"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'best-practice', '["trusted-advisor","support-tiers","business-support"]'::jsonb, 'ai-draft', 'active', now(), now()
)
