INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-006', 'aws-clf', 'O Infrastructure Event Management (IEM) é um benefício do AWS Support. Em quais cenários ele está INCLUÍDO sem custo adicional?',
  '[{"id":"A","text":"Em Basic e Developer Support"},{"id":"B","text":"Em Enterprise On-Ramp e Enterprise (incluído); Business pode comprar separado"},{"id":"C","text":"Em Business Support (incluído)"},{"id":"D","text":"Em todos os tiers pagos (Developer+)"}]'::jsonb, 'B',
  '{
    "summary": "IEM é INCLUÍDO em Enterprise On-Ramp e Enterprise; clientes Business podem adquirir como add-on pago.",
    "whyCorrect": "O Infrastructure Event Management é um engajamento estruturado da AWS para eventos planejados de alta carga (lançamentos de produto, Black Friday, migrações). Inclui pré-avaliação, monitoração em tempo real e recomendações. Vem incluso em Enterprise On-Ramp (limitado/ano) e Enterprise. Clientes Business podem comprar como serviço adicional, mas NÃO faz parte do plano.",
    "whyWrong": {
     "A": "Basic e Developer não têm IEM.",
     "C": "Business pode comprar separado — não vem incluído.",
     "D": "Developer não tem IEM."
    },
    "keyConcept": "IEM = engajamento programado para eventos críticos. Incluído apenas no tier Enterprise (On-Ramp e Full).",
    "compareWith": [
     "AWS Countdown: Enterprise (e Premier Partners) — para migrations grandes",
     "IEM: eventos pontuais de carga",
     "Concierge: contínuo, billing/account"
    ],
    "realWorldContext": "Para Black Friday, varejistas usam IEM 30-60 dias antes para revisar capacity planning, Auto Scaling e arquitetura.",
    "commonMistakes": "Confundir IEM com AWS Countdown — o Countdown é para programas mais longos (3+ meses) como migrations enterprise.",
    "tutorSeeds": [
     "Diferença entre IEM e AWS Countdown",
     "Quando IEM é a melhor escolha?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'best-practice', '["iem","support-tiers","events"]'::jsonb, 'ai-draft', 'active', now(), now()
)
