INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-007', 'aws-clf', 'Uma empresa quer ter acesso ao AWS Countdown (programa especializado para eventos de alta visibilidade como product launches, large migrations e Cloud Adoption initiatives). Qual o tier mínimo de Support exigido?',
  '[{"id":"A","text":"Business Support"},{"id":"B","text":"Enterprise On-Ramp"},{"id":"C","text":"Enterprise Support"},{"id":"D","text":"Está disponível em qualquer tier pago como add-on"}]'::jsonb, 'C',
  '{
    "summary": "AWS Countdown é disponibilizado para clientes Enterprise Support (e via Premier-tier Partners).",
    "whyCorrect": "O AWS Countdown é um programa estruturado, com duração de várias semanas a meses, que ajuda clientes a executar eventos complexos (launches, migrations corporativas, transformações). Está reservado a clientes Enterprise Support (não On-Ramp por padrão) e parceiros Premier que ofereçam o programa para seus clientes.",
    "whyWrong": {
     "A": "Business não tem Countdown.",
     "B": "Enterprise On-Ramp não inclui Countdown por padrão.",
     "D": "Countdown não é vendido como add-on para tiers menores."
    },
    "keyConcept": "AWS Countdown = engajamento mais longo e amplo que IEM. Exclusivo do Enterprise tier (e Premier Partners).",
    "compareWith": [
     "IEM: evento pontual (dias a semanas), On-Ramp e Enterprise",
     "Countdown: programa (semanas a meses), Enterprise apenas",
     "Concierge: contínuo billing"
    ],
    "realWorldContext": "Empresas migrando datacenter para AWS em fase ''Migration Acceleration Program (MAP)'' tipicamente engajam Countdown.",
    "commonMistakes": "Achar que On-Ramp tem todos os benefícios do Enterprise — não tem.",
    "tutorSeeds": [
     "Diferença entre Countdown e MAP (Migration Acceleration Program)",
     "Quando usar Countdown vs IEM?"
