INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-008', 'aws-clf', 'O Basic Support (gratuito, default em toda conta AWS) inclui quais recursos? (Escolha a resposta MAIS completa.)',
  '[{"id":"A","text":"Apenas documentação e fóruns públicos; nenhum canal AWS direto"},{"id":"B","text":"Tudo do item B, mais Trusted Advisor completo"},{"id":"C","text":"Documentação, fóruns, suporte por e-mail business hours e Trusted Advisor completo"},{"id":"D","text":"Documentação, whitepapers, AWS re:Post, 6 core checks de Trusted Advisor, AWS Personal Health Dashboard e suporte a questões de account/billing 24x7"}]'::jsonb, 'D',
  '{
    "summary": "Basic Support inclui docs, AWS re:Post, 6 core checks do Trusted Advisor, Personal Health Dashboard e support 24x7 para questões de billing/account (não-técnicas).",
    "whyCorrect": "Basic é gratuito e inclui: (1) acesso a documentação e whitepapers; (2) AWS re:Post (Q&A da comunidade); (3) 6 core checks do Trusted Advisor (alguns de segurança e service limits); (4) AWS Personal Health Dashboard (alertas de eventos AWS que afetam seus recursos); (5) suporte a perguntas de account/billing 24x7 (mas NÃO técnicas).",
    "whyWrong": {
     "A": "Subestima: Basic SIM tem suporte 24x7 para account/billing.",
     "B": "Trusted Advisor completo é Business+, não Basic.",
     "C": "Basic não tem suporte técnico por e-mail, e não tem TA completo."
    },
    "keyConcept": "Basic = grátis, sem suporte técnico, mas com billing/account support 24x7.",
    "compareWith": [
     "Developer: e-mail business hours para questões técnicas",
     "Business: 24x7 chat/phone/email para tudo",
     "Basic: zero técnico, mas billing 24x7"
    ],
    "realWorldContext": "Toda conta nova AWS começa em Basic. Adequado para sandboxes, learning, hobbies.",
    "commonMistakes": "Achar que Basic não tem nenhum suporte da AWS — tem para conta/billing.",
    "tutorSeeds": [
     "O que é AWS re:Post?",
     "Qual a diferença entre Personal Health Dashboard e Service Health Dashboard?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'recall', '["basic-support","support-tiers","free"]'::jsonb, 'ai-draft', 'active', now(), now()
)
