INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-009', 'aws-clf', 'Uma startup paga $29/mês de Developer Support, mas seu uso AWS subiu para $5.000/mês. Como o valor cobrado pelo Developer Support será calculado?',
  '[{"id":"A","text":"$29/mês ou 3% do uso mensal AWS, o que for MAIOR — neste caso, $150/mês (3% de $5.000)"},{"id":"B","text":"Continua sendo $29/mês — preço fixo independente do uso"},{"id":"C","text":"$29/mês ou 3% do uso mensal AWS, o que for MENOR"},{"id":"D","text":"$5.000 × 10% = $500/mês"}]'::jsonb, 'A',
  '{
    "summary": "Developer Support: $29/mês OU 3% do consumo AWS, o que for MAIOR. Com $5k de uso, paga 3% = $150/mês.",
    "whyCorrect": "AWS Support é tiered por consumo. Developer cobra o MAIOR entre $29/mês ou 3% do uso mensal (descontando taxes, créditos e custos de Support). Para $5.000 de uso: 3% = $150, que é maior que $29 — então a fatura de Support será $150 naquele mês.",
    "whyWrong": {
     "B": "$29 é o MÍNIMO, não fixo. Acima de $967/mês de uso, 3% supera $29.",
     "C": "Inverso — é o maior dos dois, não menor.",
     "D": "10% não é a taxa de Developer (3% é). Business é tiered."
    },
    "keyConcept": "Support pago em AWS sempre tem um piso fixo + percentual do uso (o maior dos dois).",
    "compareWith": [
     "Developer: max($29, 3% uso)",
     "Business: max($100, percentual decrescente conforme spend cresce — 10% até $10k, depois decresce)",
     "Enterprise On-Ramp: max($5.500, 10%)",
     "Enterprise: max($15.000, percentual decrescente)"
    ],
    "realWorldContext": "Esse modelo evita que clientes ''gigantes'' paguem muito pouco e que pequenos clientes paguem desproporcionalmente.",
    "commonMistakes": "Esquecer que o preço de Support escala com o uso.",
    "tutorSeeds": [
     "Como calcular o custo de Business Support para $100k/mês de uso?",
     "Por que Enterprise tem teto de spend?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'scenario', '["pricing","developer-support","support-tiers"]'::jsonb, 'ai-draft', 'active', now(), now()
)
