INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-010', 'aws-clf', 'Uma empresa usa AWS Organizations com 200 contas-membro. Para que TODAS as contas tenham acesso ao Business Support, qual abordagem é correta?',
  '[{"id":"A","text":"Apenas a management account precisa de Business Support — todas as contas-membro herdam"},{"id":"B","text":"Cada conta-membro precisa de seu próprio plano Business Support (custo individual por conta)"},{"id":"C","text":"Não é possível ter Business Support em Organizations"},{"id":"D","text":"Apenas a primeira conta criada precisa de Business Support — as demais usam Basic gratuito"}]'::jsonb, 'B',
  '{
    "summary": "O nível de Support é POR CONTA, não herdado. Cada conta no Organizations precisa do seu próprio plano de Support pago.",
    "whyCorrect": "AWS Support é configurado a nível de conta individual. Mesmo em Organizations com consolidated billing, cada conta-membro que precisar de Business (ou superior) precisa ter o plano contratado nela própria. O custo é por conta. Algumas empresas estabelecem que apenas algumas contas (produção) têm Business Support, e contas de dev/sandbox ficam em Basic.",
    "whyWrong": {
     "A": "Support NÃO é herdado por Organizations.",
     "C": "É plenamente possível — só precisa ativar em cada conta.",
     "D": "Não há ''desconto'' por conta primeira."
    },
    "keyConcept": "Support = por conta. Consolidated billing junta custos, mas planos de Support são individuais.",
    "compareWith": [
     "Volume pricing (S3, EC2): consolidated, agregado",
     "Reserved Instances: compartilhados via Organizations",
     "Support: NÃO compartilhado — por conta"
    ],
    "realWorldContext": "Empresas grandes contornam isso negociando Enterprise Discount Program (EDP) com a AWS, que pode incluir condições especiais de Support.",
    "commonMistakes": "Achar que ativar Business na management account propaga para todas.",
    "tutorSeeds": [
     "Quais benefícios de Organizations são herdados vs por conta?",
     "Como otimizar custo de Support em ambientes multi-conta?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["organizations","support-tiers","multi-account"]'::jsonb, 'ai-draft', 'active', now(), now()
)
