INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-011', 'aws-clf', 'Uma empresa quer começar a explorar AWS gratuitamente. Sobre o AWS Free Tier, qual afirmação é CORRETA?',
  '[{"id":"A","text":"Tudo é gratuito por 12 meses; depois a conta é encerrada se não houver cartão"},{"id":"B","text":"Free Tier dura 24 meses para qualquer serviço AWS"},{"id":"C","text":"Free Tier tem 3 categorias: Always Free (sempre grátis), 12-Month Free (12 meses do início da conta), e Trials (curta duração após primeiro uso)"},{"id":"D","text":"Free Tier é exclusivo de Basic Support — clientes pagos não recebem"}]'::jsonb, 'C',
  '{
    "summary": "AWS Free Tier tem 3 tipos: Always Free, 12-Month Free (a partir da criação da conta) e Short-term Trials.",
    "whyCorrect": "AWS Free Tier categoriza ofertas em três tipos: (1) **Always Free** — sempre grátis dentro de limites mensais (ex: Lambda 1M req/mês, DynamoDB 25GB armazenamento, CloudFront 1TB/mês out, SNS 1M publish). (2) **12-Month Free** — grátis por 12 meses a partir da criação da conta (ex: EC2 750h t2.micro/t3.micro, S3 5GB, RDS 750h db.t2.micro/t3.micro/t4g.micro). (3) **Trials** — créditos ou tempo limitado após o primeiro uso de um serviço (ex: Amazon Inspector 90 dias, Redshift 2 meses).",
    "whyWrong": {
     "A": "Conta não é encerrada — apenas começa a cobrar uso acima dos limites.",
     "B": "Não é 24 meses — é 12 meses para a categoria 12-Month, e ilimitado para Always Free.",
     "D": "Free Tier vale para qualquer conta, independente do plano de Support."
    },
    "keyConcept": "Free Tier ≠ ''tudo é grátis''. Há limites mensais e diferentes durações.",
    "compareWith": [
     "Always Free: Lambda 1M, DynamoDB 25GB, S3 Glacier 10GB-month",
     "12-Month: EC2 t2.micro 750h, S3 5GB, RDS micro 750h",
     "Trials: Inspector, Macie, Detective"
    ],
    "realWorldContext": "Engenheiros que estudam para certificações AWS conseguem laboratórios completos quase sem custo aproveitando o Free Tier por 12 meses.",
    "commonMistakes": "Pensar que ''750h grátis'' significa que pode rodar 4 EC2 t2.micro 24x7 — não. 750h é o total, e 4 instâncias 24x7 consomem 4×730h = 2.920h.",
    "tutorSeeds": [
     "Liste 5 serviços Always Free com seus limites",
     "Quando começa o relógio do 12-Month Free?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'best-practice', '["free-tier","pricing","always-free"]'::jsonb, 'ai-draft', 'active', now(), now()
)
