INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-012', 'aws-clf', 'Quando começa a contagem dos 12 meses do AWS Free Tier (categoria 12-Month Free)?',
  '[{"id":"A","text":"Quando o usuário consome o primeiro recurso elegível"},{"id":"B","text":"No primeiro dia do mês fiscal AWS"},{"id":"C","text":"Quando o usuário ativa explicitamente o Free Tier via Console"},{"id":"D","text":"Na data de criação da conta AWS"}]'::jsonb, 'D',
  '{
    "summary": "Os 12 meses contam a partir da DATA DE CRIAÇÃO da conta AWS — independente de uso.",
    "whyCorrect": "O relógio do 12-Month Free Tier começa exatamente quando a conta é criada (signup). Por exemplo, conta criada em 15/janeiro/2025 → 12-Month Free vai até 15/janeiro/2026, independente de quando o usuário começar a usar os serviços.",
    "whyWrong": {
     "A": "Não — o relógio anda mesmo se a conta nunca usou nada.",
     "B": "AWS não tem ''mês fiscal'' para Free Tier.",
     "C": "Free Tier é automático, não requer ativação."
    },
    "keyConcept": "Free Tier 12-Month = 12 meses corridos do signup. Importante para timing de POCs.",
    "compareWith": [
     "Always Free: ilimitado (sempre grátis dentro do limite mensal)",
     "12-Month: relógio do signup",
     "Trials: relógio do primeiro uso do serviço específico"
    ],
    "realWorldContext": "Estudantes que criam conta ''para depois usar'' perdem meses do Free Tier sem perceber — recomenda-se criar quando vai começar de fato.",
    "commonMistakes": "Achar que o relógio começa no primeiro uso.",
    "tutorSeeds": [
     "Posso ter Free Tier renovado abrindo nova conta?",
     "Como rastrear o status do Free Tier?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["free-tier","12-month","billing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
