INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-013', 'aws-clf', 'Sobre o AWS Free Tier para Amazon EC2, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"750 horas/mês de t2.micro OU t3.micro grátis por 12 meses — total combinado entre os dois tipos"},{"id":"B","text":"750 horas/mês de qualquer tipo de instância EC2, ilimitado para sempre"},{"id":"C","text":"100 horas/mês de t2.micro, válido apenas no primeiro mês"},{"id":"D","text":"5 instâncias t2.micro 24x7 grátis por 12 meses"}]'::jsonb, 'A',
  '{
    "summary": "EC2 Free Tier = 750h/mês de t2.micro OU t3.micro (combinadas) por 12 meses do signup.",
    "whyCorrect": "O Free Tier do EC2 inclui 750 horas por mês de uso de instâncias t2.micro (ou t3.micro em regiões onde t2 não está disponível). Esse total é dividido entre as duas — não 750 de cada. 750h ≈ 31 dias × 24h = 744h, suficiente para uma instância 24x7. Se rodar 2 instâncias 24x7, consume 1.488h e excede 738h.",
    "whyWrong": {
     "A se interpretada errada": "OK na letra A.",
     "B": "Não é para qualquer tipo — só t2.micro/t3.micro, e só 12 meses.",
     "C": "Não — 750h/mês, não 100h.",
     "D": "5 instâncias 24x7 = 3.650h, muito acima do limite."
    },
    "keyConcept": "750h ≈ uma micro instância 24x7. Múltiplas instâncias consomem proporcionalmente.",
    "compareWith": [
     "EC2 t2.micro/t3.micro: 750h/mês, 12 meses",
     "RDS db.t2/t3/t4g.micro: 750h/mês, 12 meses",
     "S3: 5GB, 12 meses"
    ],
    "realWorldContext": "Lab pessoal de uma única VM 24x7 cabe perfeitamente no Free Tier por 12 meses.",
    "commonMistakes": "Subir vários EC2 em paralelo achando que cada um tem 750h.",
    "tutorSeeds": [
     "Como monitorar consumo do Free Tier?",
     "O que acontece se passar de 750h?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'scenario', '["free-tier","ec2","12-month"]'::jsonb, 'ai-draft', 'active', now(), now()
)
