INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-014', 'aws-clf', 'Quais dos seguintes serviços têm oferta **Always Free** (sempre grátis dentro de limites mensais)? Selecione a opção correta.',
  '[{"id":"A","text":"Amazon EC2 — 750 horas/mês de t2.micro"},{"id":"B","text":"AWS Lambda — 1 milhão de requests/mês e 400.000 GB-segundos de compute"},{"id":"C","text":"Amazon RDS — 750 horas/mês de db.t2.micro"},{"id":"D","text":"Amazon S3 — 5 GB de armazenamento"}]'::jsonb, 'B',
  '{
    "summary": "Lambda tem Always Free (1M req + 400k GB-sec/mês). EC2, RDS e S3 do enunciado são 12-Month, não Always Free.",
    "whyCorrect": "AWS Lambda é o exemplo clássico de Always Free: 1 milhão de requests e 400.000 GB-segundos de compute time por mês, indefinidamente — não expira em 12 meses. Outros Always Free famosos: DynamoDB 25GB armazenamento, CloudFront 1TB/mês out, SNS 1M publish, SQS 1M req, Cognito 50.000 MAUs, AWS Glue Data Catalog 1M objetos.",
    "whyWrong": {
     "A": "EC2 t2.micro é 12-Month Free, não Always Free.",
     "C": "RDS db.t2.micro é 12-Month Free.",
     "D": "S3 5GB é 12-Month Free."
    },
    "keyConcept": "Always Free é tipicamente para serviços serverless/PaaS de baixo consumo; 12-Month é para serviços com infra dedicada (EC2/RDS).",
    "compareWith": [
     "Always Free: Lambda, DynamoDB, CloudFront, SNS, SQS, Cognito",
     "12-Month Free: EC2, RDS, S3, EBS, ELB"
    ],
    "realWorldContext": "Arquiteturas serverless small-scale podem rodar permanentemente no Always Free.",
    "commonMistakes": "Confundir Always Free com 12-Month Free.",
    "tutorSeeds": [
     "Liste 10 serviços com Always Free e seus limites",
     "Por que EC2 não é Always Free?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'recall', '["free-tier","always-free","lambda"]'::jsonb, 'ai-draft', 'active', now(), now()
)
