INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-015', 'aws-clf', 'Uma empresa quer ESTIMAR o custo de uma arquitetura AWS planejada (EC2, RDS, S3, ELB) antes de implementá-la. Qual ferramenta da AWS é mais apropriada?',
  '[{"id":"A","text":"AWS Cost Explorer"},{"id":"B","text":"AWS Budgets"},{"id":"C","text":"AWS Pricing Calculator"},{"id":"D","text":"AWS TCO Calculator"}]'::jsonb, 'C',
  '{
    "summary": "AWS Pricing Calculator estima o custo PROSPECTIVO de uma arquitetura AWS antes da implementação.",
    "whyCorrect": "O AWS Pricing Calculator é uma ferramenta web gratuita que permite modelar uma arquitetura AWS detalhada (serviço por serviço, com configurações como tipo de instância, região, storage, transferência) e gerar uma estimativa de custo mensal e anual. Suporta cenários complexos, salvar estimativas, exportar para CSV/PDF e compartilhar URLs.",
    "whyWrong": {
     "A": "Cost Explorer analisa custos PASSADOS e atuais — não estima cargas futuras hipotéticas. Faz forecast a partir do uso histórico, sim, mas não modela novas arquiteturas.",
     "B": "Budgets define ALERTAS de custo — não estima futuro hipotético.",
     "D": "TCO Calculator compara on-prem vs AWS — adequado para business case, não para detalhar arquitetura AWS futura."
    },
    "keyConcept": "Pricing Calculator = estimar AWS prospectivo. TCO Calculator = comparar on-prem vs AWS. Cost Explorer = analisar histórico/atual.",
    "compareWith": [
     "Pricing Calculator: estimativa pré-implementação",
     "TCO Calculator: business case migração",
     "Cost Explorer: análise post-mortem e forecast curto prazo",
     "AWS Budgets: alertas e limites"
    ],
    "realWorldContext": "Toda RFP/proposta corporativa para mover workload à AWS começa com uma estimativa no Pricing Calculator anexada à apresentação.",
    "commonMistakes": "Usar Cost Explorer para estimar uma arquitetura ainda não implementada.",
    "tutorSeeds": [
     "Como criar e compartilhar uma estimativa no Pricing Calculator?",
     "Pricing Calculator considera Free Tier?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'scenario', '["pricing-calculator","estimating","tools"]'::jsonb, 'ai-draft', 'active', now(), now()
)
