INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-016', 'aws-clf', 'O CFO de uma empresa quer um relatório que COMPARE o custo de manter o datacenter on-premises atual (servidores físicos, energia, refrigeração, espaço, pessoal) com o custo equivalente migrando tudo para AWS. Qual ferramenta a AWS oferece para esse business case?',
  '[{"id":"A","text":"AWS Pricing Calculator"},{"id":"B","text":"AWS Cost Explorer"},{"id":"C","text":"AWS Migration Hub"},{"id":"D","text":"AWS Total Cost of Ownership (TCO) Calculator / Migration Evaluator"}]'::jsonb, 'D',
  '{
    "summary": "TCO Calculator (e a versão moderna Migration Evaluator) compara TCO on-prem vs AWS — ideal para business case de migração.",
    "whyCorrect": "O TCO Calculator (e sua evolução, o Migration Evaluator, ex-TSO Logic) modela todos os custos de manter infra on-premises: hardware, software, datacenter (espaço, energia, refrigeração), pessoal de operações, manutenção. E compara contra a estimativa equivalente AWS. Gera um relatório executivo focado em ROI e payback period — ideal para CFOs.",
    "whyWrong": {
     "A": "Pricing Calculator só estima o lado AWS, não modela on-premises.",
     "B": "Cost Explorer analisa custo AWS existente — não tem dados on-prem.",
     "C": "Migration Hub é orquestração de migração — rastreia movimentação de servidores, não faz business case."
    },
    "keyConcept": "TCO Calculator/Migration Evaluator = on-prem vs AWS (business case). Pricing Calculator = só AWS (engenharia).",
    "compareWith": [
     "TCO Calculator: business case macro on-prem vs AWS",
     "Migration Evaluator: versão moderna, com agente que escaneia datacenter",
     "Pricing Calculator: estimativa detalhada AWS-only",
     "Migration Hub: rastreamento de migração em execução"
    ],
    "realWorldContext": "Apresentações ao board sobre migração à nuvem invariavelmente usam Migration Evaluator/TCO Calculator como anexo.",
    "commonMistakes": "Confundir TCO com Pricing Calculator.",
    "tutorSeeds": [
     "Quais componentes de custo on-prem o TCO Calculator considera?",
     "Qual a diferença entre TCO Calculator e Migration Evaluator?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["tco-calculator","migration-evaluator","business-case"]'::jsonb, 'ai-draft', 'active', now(), now()
)
