INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-017', 'aws-clf', 'Sobre o AWS Pricing Calculator, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"É gratuito e público (não requer login AWS); permite gerar URLs compartilháveis e exportar estimativas em CSV/PDF"},{"id":"B","text":"Requer assinatura de Business Support para ser usado"},{"id":"C","text":"Calcula apenas o custo de EC2 e S3"},{"id":"D","text":"Aplica automaticamente Reserved Instances e Savings Plans em todas as estimativas"}]'::jsonb, 'A',
  '{
    "summary": "Pricing Calculator é gratuito, público (sem login obrigatório), suporta a maioria dos serviços AWS e gera estimativas compartilháveis.",
    "whyCorrect": "O Pricing Calculator está em calculator.aws e é acessível sem login. Suporta dezenas de serviços (EC2, RDS, S3, Lambda, DynamoDB, CloudFront, ELB, etc.). Permite agrupar estimativas, exportar (CSV/PDF) e compartilhar via URL persistente. Suporta cálculo de Reserved Instances e Savings Plans, mas é opt-in por serviço — não aplica automaticamente.",
    "whyWrong": {
     "B": "Não requer Support para uso.",
     "C": "Suporta muito mais que EC2 e S3.",
     "D": "Reserved/Savings Plans devem ser explicitamente selecionados em cada serviço, não aplicados automaticamente."
    },
    "keyConcept": "Pricing Calculator = pública, gratuita, com URLs compartilháveis — ferramenta universal de POC.",
    "compareWith": [
     "Pricing Calculator: estimativa AWS",
     "Cost Explorer: análise histórico (requer login)"
    ],
    "realWorldContext": "Arquitetos enviam URLs do Calculator a clientes para discutir cenários sem expor dados sensíveis da conta.",
    "commonMistakes": "Achar que precisa de assinatura ou login.",
    "tutorSeeds": [
     "Como modelar uma arquitetura com Auto Scaling no Pricing Calculator?",
     "O Calculator considera Spot Instances?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'best-practice', '["pricing-calculator","tools","estimating"]'::jsonb, 'ai-draft', 'active', now(), now()
)
