INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-020', 'aws-clf', 'Uma empresa ativou a tag `Project` como Cost Allocation Tag hoje, dia 15/maio. Tags `Project=AppA` foram aplicadas há meses em vários recursos. Quando dados de custo agrupados por `Project` aparecerão no Cost Explorer?',
  '[{"id":"A","text":"Imediatamente, com dados retroativos desde a data de criação dos recursos"},{"id":"B","text":"Apenas no início do próximo mês fiscal"},{"id":"C","text":"Em 7 dias, com retroação dos últimos 90 dias"},{"id":"D","text":"Em até 24 horas, mas apenas para dados a partir do momento da ativação — ativação NÃO é retroativa"}]'::jsonb, 'D',
  '{
    "summary": "Ativação de Cost Allocation Tags propaga em até 24h e NÃO é retroativa — dados anteriores não recebem o agrupamento.",
    "whyCorrect": "Quando uma tag é ativada como Cost Allocation Tag, leva até 24 horas para aparecer em Cost Explorer e Cost & Usage Reports (CUR). E o efeito é apenas prospectivo: gastos anteriores à ativação NÃO são agrupados pela tag, mesmo que o recurso já tivesse a tag aplicada. Por isso a recomendação é ativar tags assim que adotar a política de tagging.",
    "whyWrong": {
     "A": "Falso — não é retroativo.",
     "B": "Não tem que esperar mês fiscal — propaga em 24h.",
     "C": "Sem retroação."
    },
    "keyConcept": "Activate Cost Allocation Tags EARLY. Atraso = perda permanente de visibilidade histórica.",
    "compareWith": [
     "Aplicar tag: imediato no recurso",
     "Ativar Cost Allocation Tag: 24h, prospectivo apenas"
    ],
    "realWorldContext": "Empresas que descobrem chargeback meses depois precisam adotar metadata complementar (planilhas, billing groups manuais) para reconstruir histórico.",
    "commonMistakes": "Esperar dados retroativos após ativação.",
    "tutorSeeds": [
     "Como reconstruir histórico se esqueci de ativar tag?",
     "Quais outras práticas evitam esse problema?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'troubleshoot', '["cost-allocation-tags","tagging","billing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
