INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-022', 'aws-clf', 'Uma SaaS resseller revende recursos AWS para clientes finais (Business Units BU-A, BU-B e BU-C). Quer aplicar PRICING CUSTOMIZADO (ex: 5% de markup sobre EC2 para BU-A, 10% sobre S3 para BU-B), gerar faturas customizadas por BU e fazer chargeback. Qual serviço AWS atende esse cenário?',
  '[{"id":"A","text":"AWS Cost Categories"},{"id":"B","text":"AWS Billing Conductor"},{"id":"C","text":"AWS Cost Allocation Tags"},{"id":"D","text":"AWS Cost Explorer"}]'::jsonb, 'B',
  '{
    "summary": "AWS Billing Conductor permite criar billing groups, pricing rules customizadas, custom line items e gerar faturas modificadas para chargeback/reseller.",
    "whyCorrect": "AWS Billing Conductor é projetado exatamente para o cenário de chargeback complexo e reseller. Permite: (1) criar **billing groups** (agrupar contas de Organizations em unidades); (2) **pricing rules** (markdowns/markups, descontos globais, override de preços por serviço/região); (3) **custom line items** (taxas adicionais como ''support fee'' ou ''platform fee''); (4) gerar **proforma invoice** customizada por billing group para chargeback. Não altera a fatura AWS real para a management account, mas gera relatórios paralelos para chargeback.",
    "whyWrong": {
     "A": "Cost Categories agrupa custos para visualização — não aplica markup nem gera faturas custom.",
     "C": "Tags são metadata para alocação, sem pricing customizado.",
     "D": "Cost Explorer só visualiza, não modifica preços."
    },
    "keyConcept": "Billing Conductor = reseller/multi-BU pricing engine + chargeback invoices.",
    "compareWith": [
     "Cost Categories: agrupamento visual",
     "Billing Conductor: pricing customizado + faturas",
     "Tags: metadata",
     "AWS Marketplace SaaS Contracts: revenda formal AWS"
    ],
    "realWorldContext": "MSPs (Managed Service Providers) e holdings com múltiplas subsidiárias usam Billing Conductor para repassar custos com seu próprio modelo comercial.",
    "commonMistakes": "Tentar usar Cost Categories para markup — não é a ferramenta correta.",
    "tutorSeeds": [
     "Quais tipos de pricing rules o Billing Conductor suporta?",
     "Billing Conductor altera o que a AWS cobra ou só o relatório?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'scenario', '["billing-conductor","chargeback","reseller"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
