INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-023', 'aws-clf', 'Sobre o AWS Billing Conductor, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"Altera o valor real que a AWS cobra da management account"},{"id":"B","text":"Substitui completamente o Cost Explorer"},{"id":"C","text":"Gera relatórios e proforma invoices customizadas para chargeback interno; a fatura real da AWS para a management account NÃO é alterada"},{"id":"D","text":"É gratuito e ilimitado"}]'::jsonb, 'C',
  '{
    "summary": "Billing Conductor gera DOCUMENTOS de chargeback alternativos; a fatura da AWS para a management account continua a real (sem markup).",
    "whyCorrect": "Billing Conductor cria ''pro forma billing'' — relatórios separados que aplicam suas regras (markup, custom line items, descontos) sobre billing groups. A fatura real da AWS para a management account permanece inalterada (valor real do uso). O Conductor é uma ferramenta de chargeback INTERNO; quem faz chargeback usa esses relatórios pro forma para repassar valores às BUs/clientes finais.",
    "whyWrong": {
     "A": "Não altera a fatura real da AWS — só gera relatório paralelo.",
     "B": "Não substitui Cost Explorer; complementa.",
     "D": "É pago: $0.01 por conta gerenciada (lookup) e por billing group por dia."
    },
    "keyConcept": "Billing Conductor = ferramenta de chargeback. Não modifica o pagamento real à AWS, mas a apresentação de custos para BUs.",
    "compareWith": [
     "AWS Marketplace SaaS Contract: revenda formal",
     "Billing Conductor: chargeback interno multi-BU"
    ],
    "realWorldContext": "Holdings repassam custos para subsidiárias adicionando ''overhead'' (% de support, gestão).",
    "commonMistakes": "Achar que Billing Conductor altera o que paga à AWS.",
    "tutorSeeds": [
     "Quanto custa o Billing Conductor?",
     "Quando NÃO usar Billing Conductor?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["billing-conductor","chargeback","pricing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
