INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-024', 'aws-clf', 'Quais elementos podem ser configurados em uma ''Pricing Rule'' do AWS Billing Conductor? (Escolha a opção MAIS completa.)',
  '[{"id":"A","text":"Apenas descontos percentuais globais"},{"id":"B","text":"Apenas markup fixo em USD por hora de EC2"},{"id":"C","text":"Trocar moeda de USD para BRL"},{"id":"D","text":"Markups (acréscimo %), discounts (desconto %), e tiering por uso por serviço/operação/região; Custom Line Items para taxas fixas ou variáveis adicionais"}]'::jsonb, 'D',
  '{
    "summary": "Billing Conductor suporta markups, discounts, tiering, e Custom Line Items para taxas adicionais — todos configuráveis por billing group, serviço, operação ou região.",
    "whyCorrect": "Pricing Rules no Billing Conductor são flexíveis: aplicar markup ou discount percentual (ex: +10% no EC2 da BU-A), tiering (taxas diferentes em volumes), targeting granular (por serviço, operação como ''RunInstances'', região). Adicionalmente, **Custom Line Items** permitem adicionar cobranças fixas (ex: ''platform fee: $500'') ou variáveis (% de gasto total) que não correspondem a uso AWS real — útil para repassar custos de pessoal, licenças, etc.",
    "whyWrong": {
     "A": "Vai muito além de descontos globais.",
     "B": "Markups são percentuais, não fixos em USD/hora.",
     "C": "Billing Conductor não converte moeda."
    },
    "keyConcept": "Pricing Rules + Custom Line Items = motor completo de pricing customizado.",
    "compareWith": [
     "Markup: +5% no S3",
     "Discount: -10% em EC2",
     "Tiering: $0.020/GB nos primeiros 1TB, $0.018/GB acima",
     "Custom Line Item: ''platform fee mensal: $1.000''"
    ],
    "realWorldContext": "MSP cobra cliente final com markup 15% + Custom Line Item de ''managed services fee'' fixa mensal — Billing Conductor automatiza tudo.",
    "commonMistakes": "Pensar que Conductor é só desconto global.",
    "tutorSeeds": [
     "Como modelar ''platform overhead'' no Billing Conductor?",
     "Diferença entre Pricing Rule e Custom Line Item"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'best-practice', '["billing-conductor","pricing-rules","custom-line-items"]'::jsonb, 'ai-draft', 'active', now(), now()
)
