INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-025', 'aws-clf', 'Uma empresa tem licenças Microsoft Windows Server e SQL Server adquiridas separadamente que quer trazer para a AWS (BYOL — Bring Your Own License) em EC2 Dedicated Hosts. Qual serviço AWS ajuda a TRACKAR e GERENCIAR essas licenças centralmente?',
  '[{"id":"A","text":"AWS License Manager"},{"id":"B","text":"AWS Marketplace"},{"id":"C","text":"AWS Systems Manager"},{"id":"D","text":"AWS Trusted Advisor"}]'::jsonb, 'A',
  '{
    "summary": "AWS License Manager rastreia licenças BYOL (Windows, SQL Server, Oracle, SAP, IBM) com configurações que vinculam licenças a recursos, alertando sobre over-licensing.",
    "whyCorrect": "AWS License Manager permite criar ''license configurations'' (regras: ex: ''Windows Server Datacenter: 16 cores por host, 100 licenças disponíveis'') e associá-las a recursos como EC2 Dedicated Hosts ou AMIs. Rastreia consumo, alerta sobre over-provisioning e ajuda em audit compliance com vendor (Microsoft, Oracle, SAP).",
    "whyWrong": {
     "B": "Marketplace é loja de software com licença incluída — não tracking de BYOL.",
     "C": "Systems Manager faz configuração/patching, não tracking de licenças.",
     "D": "Trusted Advisor não rastreia licenças BYOL."
    },
    "keyConcept": "License Manager = governance e tracking de BYOL, especialmente Windows/SQL/Oracle.",
    "compareWith": [
     "BYOL via License Manager: você traz sua licença",
     "License Included: AWS embute licença no preço da instância",
     "Marketplace SaaS: licença gerenciada pelo vendor"
    ],
    "realWorldContext": "Empresas migrando datacenter com investimento existente em licenças Microsoft Volume Licensing usam License Manager para evitar comprar de novo.",
    "commonMistakes": "Confundir License Manager (BYOL) com Marketplace (vendor-managed).",
    "tutorSeeds": [
     "Como funciona BYOL para SQL Server?",
     "Quais tipos de software License Manager rastreia?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["license-manager","byol","windows"]'::jsonb, 'ai-draft', 'active', now(), now()
)
