INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-026', 'aws-clf', 'Sobre BYOL (Bring Your Own License) em AWS, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"BYOL sempre é o modelo mais barato — AWS oferece desconto automático"},{"id":"B","text":"Cliente traz sua própria licença comercial (Windows, SQL, Oracle, SAP) e roda em AWS, tipicamente em Dedicated Hosts/Instances para conformidade com termos de licenciamento"},{"id":"C","text":"BYOL é gratuito — não há custo de licença nem de infraestrutura"},{"id":"D","text":"BYOL só funciona em Linux open-source"}]'::jsonb, 'B',
  '{
    "summary": "BYOL = cliente traz licença comercial existente para AWS; tipicamente em Dedicated Hosts/Instances para atender termos de license mobility.",
    "whyCorrect": "BYOL permite a clientes com licenças adquiridas (Microsoft Volume Licensing, Oracle, SAP, IBM) executá-las em AWS. Para muitas dessas licenças, especialmente Windows e SQL Server pré-2019 SA, os termos exigem que o hardware seja dedicado ao cliente — daí o uso de **EC2 Dedicated Hosts** (visibilidade do host físico, controle por affinity e socket counting) ou **Dedicated Instances**. Após 2019, Microsoft restringiu BYOL em hardware compartilhado em alguns produtos.",
    "whyWrong": {
     "A": "Nem sempre mais barato — depende de SA (Software Assurance), do tipo de carga e do TCO.",
     "C": "BYOL elimina parcela de licença na fatura AWS, mas infraestrutura AWS continua paga.",
     "D": "Open-source Linux não precisa de BYOL (já é livre)."
    },
    "keyConcept": "BYOL = trazer licença comercial. AWS oferece Dedicated Hosts para license compliance.",
    "compareWith": [
     "License Included: AWS embute o custo da licença no preço da instância",
     "BYOL: você traz, paga só infra (em Dedicated Host tipicamente)",
     "AWS Marketplace SaaS: licença gerenciada pelo ISV"
    ],
    "realWorldContext": "Empresas com investimento em SQL Server Enterprise + SA por anos preferem BYOL para preservar valor da licença existente.",
    "commonMistakes": "Achar que BYOL é sempre mais barato sem fazer análise.",
    "tutorSeeds": [
     "Quando BYOL faz sentido financeiramente?",
     "Quais limitações Microsoft impôs ao BYOL?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'best-practice', '["byol","license-manager","dedicated-host"]'::jsonb, 'ai-draft', 'active', now(), now()
)
