INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-027', 'aws-clf', 'Um vendor de software ISV quer vender SUA própria licença gerenciada (não BYOL do cliente) na AWS, integrando faturamento à AWS bill do cliente. Qual canal AWS é correto?',
  '[{"id":"A","text":"AWS License Manager — apenas tracking"},{"id":"B","text":"AWS Activate"},{"id":"C","text":"AWS Marketplace — modelos PAYG, Annual Contract, SaaS Contracts ou BYOL listing"},{"id":"D","text":"AWS Service Catalog"}]'::jsonb, 'C',
  '{
    "summary": "AWS Marketplace é a plataforma onde ISVs publicam software (AMIs, containers, SaaS) com diferentes modelos de billing integrados à AWS bill.",
    "whyCorrect": "AWS Marketplace é o canal oficial AWS para ISVs venderem suas soluções. Suporta vários modelos: (1) **Pay-as-you-go (PAYG)** — cobrado por hora/uso; (2) **Annual Contract** — commit anual com desconto; (3) **SaaS Contracts** — assinatura recorrente para SaaS hospedado pelo vendor; (4) **BYOL listing** — vendor lista o software mas cliente trás licença separada (paga ao vendor diretamente); (5) **Private Offer** — termos negociados. Todos integrados à AWS bill do cliente (exceto BYOL).",
    "whyWrong": {
     "A": "License Manager é interno (tracking), não canal de venda.",
     "B": "Activate é para startups (créditos AWS), não para ISVs.",
     "D": "Service Catalog é catálogo interno corporativo de templates aprovados, não loja pública."
    },
    "keyConcept": "Marketplace = canal AWS para ISVs com vários modelos de billing.",
    "compareWith": [
     "PAYG: paga por uso",
     "Annual: commit anual, descontado",
     "SaaS Contract: assinatura SaaS",
     "Private Offer: negociado",
     "BYOL listing: cliente paga vendor à parte"
    ],
    "realWorldContext": "Empresas adoram Marketplace porque a fatura vem na AWS bill (um pagamento só, créditos AWS aplicáveis).",
    "commonMistakes": "Confundir Marketplace com Service Catalog.",
    "tutorSeeds": [
     "Diferença entre Annual Contract e PAYG no Marketplace",
     "O que são Private Offers?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["marketplace","isv","billing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
