INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-028', 'aws-clf', 'Uma empresa quer comprar uma solução de WAF de terceiros no AWS Marketplace com COMMIT ANUAL para receber desconto. Que modelo de pricing escolher?',
  '[{"id":"A","text":"Pay-as-you-go"},{"id":"B","text":"BYOL"},{"id":"C","text":"Spot Pricing"},{"id":"D","text":"Annual Contract (Marketplace)"}]'::jsonb, 'D',
  '{
    "summary": "Annual Contracts no AWS Marketplace = commit anual com desconto sobre PAYG.",
    "whyCorrect": "AWS Marketplace Annual Contracts oferecem o software ou SaaS por preço fixo anual, com desconto significativo (10-40%) em relação ao PAYG. Útil quando o cliente planeja uso sustentado por ≥12 meses. O contrato é cobrado upfront ou parcelado mensalmente, dependendo do vendor. Renovação pode ser automática.",
    "whyWrong": {
     "A": "PAYG cobra por uso — sem desconto por commit.",
     "B": "BYOL = cliente já possui licença separada.",
     "C": "Spot Pricing é exclusivo do EC2 — não existe no Marketplace."
    },
    "keyConcept": "Annual Contract no Marketplace = análogo a Reserved Instance, mas para software de terceiros.",
    "compareWith": [
     "PAYG: flexível, mais caro/uso",
     "Annual Contract: 10-40% desconto, commit 1 ano",
     "SaaS Contract: assinatura, escalável"
    ],
    "realWorldContext": "Empresas adotam licenças anuais de SIEM, WAF, EDR via Marketplace para simplificar billing e POs.",
    "commonMistakes": "Confundir Annual Contract (Marketplace) com Reserved Instance (EC2).",
    "tutorSeeds": [
     "Annual Contract é cancelável?",
     "Como migrar de PAYG para Annual?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'scenario', '["marketplace","annual-contract","commit"]'::jsonb, 'ai-draft', 'active', now(), now()
)
