INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-029', 'aws-clf', 'Uma startup brasileira em estágio Series A foi aceita em uma aceleradora portfolio AWS Activate. Qual benefício é tipicamente concedido por esse programa?',
  '[{"id":"A","text":"Créditos AWS (tipicamente $1.000 até $100.000 dependendo do tier), créditos de Support, créditos de Business Support e acesso a recursos como office hours"},{"id":"B","text":"Apenas treinamento gratuito"},{"id":"C","text":"Hardware físico gratuito para datacenter"},{"id":"D","text":"Equity investment direto da AWS"}]'::jsonb, 'A',
  '{
    "summary": "AWS Activate oferece créditos AWS (até $100k em portfolios maiores), créditos de Business Support, training e office hours para startups.",
    "whyCorrect": "AWS Activate tem dois caminhos: (1) **Activate Founders** — até $1.000 em credits para startups self-funded ou pre-seed; (2) **Activate Portfolio** — startups respaldadas por VCs/aceleradoras parceiras AWS, até $100.000 em credits, créditos de Business Support, acesso a office hours, training (incluindo cursos pagos do Skill Builder), descontos em ferramentas terceiras. Não envolve equity investment direto da AWS.",
    "whyWrong": {
     "B": "Activate vai muito além de training.",
     "C": "AWS não fornece hardware físico — somente cloud.",
     "D": "AWS não faz equity investment direto via Activate."
    },
    "keyConcept": "Activate = créditos AWS + Business Support + training para startups, sem equity.",
    "compareWith": [
     "Founders: $1k credits, self-funded",
     "Portfolio: até $100k credits, VC-backed",
     "Activate vs Marketplace Free Tier vs AWS Free Tier — todos diferentes"
    ],
    "realWorldContext": "Startups que aplicam para Activate via aceleradora (Y Combinator, Techstars, Endeavor) recebem créditos automaticamente.",
    "commonMistakes": "Achar que Activate dá equity.",
    "tutorSeeds": [
     "Como uma startup aplica para Activate?",
     "Créditos Activate expiram?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["aws-activate","startups","credits"]'::jsonb, 'ai-draft', 'active', now(), now()
)
