INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-030', 'aws-clf', 'Uma startup recebeu $50.000 em créditos AWS Activate (válidos por 2 anos). Ela também tem créditos promocionais de outra campanha ($5.000, expiram em 6 meses). Qual a ordem de consumo desses créditos quando faturados juntos?',
  '[{"id":"A","text":"Sempre o maior primeiro (Activate $50k antes)"},{"id":"B","text":"AWS consome créditos com EXPIRAÇÃO MAIS PRÓXIMA primeiro (os $5.000 que expiram em 6 meses) — para minimizar perda do cliente"},{"id":"C","text":"Sempre o menor primeiro"},{"id":"D","text":"Cliente escolhe manualmente qual usar primeiro"}]'::jsonb, 'B',
  '{
    "summary": "AWS consome créditos por ordem de expiração — créditos com expiração mais próxima são usados PRIMEIRO, automaticamente.",
    "whyCorrect": "A AWS aplica créditos automaticamente na fatura na seguinte ordem: (1) créditos com data de expiração mais próxima primeiro; (2) entre créditos com mesma expiração, aplica-se por serviço/região elegível conforme termos do crédito; (3) crédito sem expiração definida fica por último. Esse comportamento maximiza o valor que o cliente extrai antes que algum crédito expire.",
    "whyWrong": {
     "A": "Não é por tamanho — é por proximidade de expiração.",
     "C": "Idem — irrelevante o valor.",
     "D": "Cliente não escolhe manualmente — é automático."
    },
    "keyConcept": "Order of credit consumption = soonest-to-expire FIRST.",
    "compareWith": [
     "Activate: 2 anos típico",
     "Promotional credits: variam por campanha",
     "EDP credits: termos negociados"
    ],
    "realWorldContext": "Startups que recebem múltiplas tranches de créditos não precisam se preocupar — AWS administra automaticamente.",
    "commonMistakes": "Achar que cliente escolhe ordem.",
    "tutorSeeds": [
     "Onde ver lista de créditos ativos?",
     "Créditos cobrem todos os serviços ou só alguns?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'scenario', '["promotional-credits","activate","billing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
