INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-032', 'aws-clf', 'Em AWS Organizations com consolidated billing, créditos da management account são automaticamente compartilhados com contas-membro?',
  '[{"id":"A","text":"Sim, sempre, automaticamente"},{"id":"B","text":"Não, créditos nunca são compartilhados em Organizations"},{"id":"C","text":"Apenas créditos Activate são compartilhados; outros não"},{"id":"D","text":"Por padrão, créditos da management account são aplicados primeiro à própria management account e DEPOIS, se houver sobra, distribuídos a contas-membro — comportamento configurável"}]'::jsonb, 'D',
  '{
    "summary": "Por padrão, créditos vão primeiro à conta em que foram concedidos; sobras escorrem para outras contas da Organization (configurável).",
    "whyCorrect": "Em uma Organization com consolidated billing, créditos aplicados em uma conta consumem primeiro o uso DAQUELA conta. Se sobra, a AWS aplica em outras contas da Organization conforme política configurada no Billing Console (Credit Sharing). Pode-se desabilitar o sharing (créditos ficam só na conta original) ou permitir distribuição. Importante: o comportamento de expirar primeiro continua válido.",
    "whyWrong": {
     "A": "Não é automático/incontestável — é configurável.",
     "B": "Falso — pode ser compartilhado.",
     "C": "Não há diferenciação por tipo de crédito quanto ao sharing."
    },
    "keyConcept": "Credit Sharing em Organizations: padrão = consome local primeiro, sobra escorre; configurável via Credit Sharing preference.",
    "compareWith": [
     "RI/SP sharing: padrão ativo",
     "Volume pricing: agregado",
     "Support: NÃO compartilhado",
     "Credits: configurável"
    ],
    "realWorldContext": "Empresas centralizam todos créditos na management account e habilitam sharing para maximizar uso.",
    "commonMistakes": "Achar que credits sempre escorrem ou nunca escorrem.",
    "tutorSeeds": [
     "Como configurar Credit Sharing?",
     "RI sharing vs Credit sharing"
    ]
   }'::jsonb,
