INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-033', 'aws-clf', 'Uma empresa quer recomendações automáticas para REDIMENSIONAR seus recursos: EC2 (downsize ou family change), EBS (volumes superdimensionados), Lambda (memória excessiva) e Auto Scaling Groups. Qual serviço AWS analisa CloudWatch metrics e gera essas recomendações?',
  '[{"id":"A","text":"AWS Compute Optimizer"},{"id":"B","text":"AWS Trusted Advisor"},{"id":"C","text":"AWS Cost Explorer"},{"id":"D","text":"AWS Personal Health Dashboard"}]'::jsonb, 'A',
  '{
    "summary": "AWS Compute Optimizer usa ML para recomendar rightsizing de EC2, EBS, Lambda, ASGs e ECS on Fargate, baseado em CloudWatch metrics.",
    "whyCorrect": "AWS Compute Optimizer é um serviço que usa machine learning para analisar métricas históricas (CloudWatch) e recomendar mudanças: downsize EC2 (mudar de m5.xlarge para m5.large), trocar family (m5 → m6g ARM Graviton, ~20% mais barato), reduzir IOPS provisionados em EBS, otimizar memória de Lambda, redimensionar ASGs. Suporta opt-in por conta/Organization. É gratuito (com tier ''enhanced'' pago).",
    "whyWrong": {
     "B": "Trusted Advisor faz recomendações mais simples (idle/underutilized) mas não tem ML detalhado.",
     "C": "Cost Explorer mostra histórico/forecast e RI/SP recommendations — não rightsizing detalhado de recursos.",
     "D": "Personal Health Dashboard alerta sobre eventos AWS — sem rightsizing."
    },
    "keyConcept": "Compute Optimizer = ML rightsizing recommender. Trusted Advisor = checks gerais. Cost Explorer = análise + RI/SP recs.",
    "compareWith": [
     "Compute Optimizer: rightsizing EC2/EBS/Lambda/ASG/Fargate",
     "Cost Explorer: RI/SP recommendations + análise",
     "Trusted Advisor: 6+ checks, incluindo underutilized"
    ],
    "realWorldContext": "Empresas reduzem 20-30% do custo EC2 após Compute Optimizer adoption, principalmente migrando para Graviton.",
    "commonMistakes": "Confundir Compute Optimizer com Trusted Advisor.",
    "tutorSeeds": [
     "Quais métricas o Compute Optimizer usa?",
     "Como ativar Compute Optimizer em Organization?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["compute-optimizer","rightsizing","ml"]'::jsonb, 'ai-draft', 'active', now(), now()
)
