INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-034', 'aws-clf', 'AWS Compute Optimizer suporta recomendações para quais recursos? (Escolha a opção MAIS completa.)',
  '[{"id":"A","text":"Apenas EC2 instances"},{"id":"B","text":"EC2 instances, Auto Scaling Groups, EBS volumes, Lambda functions e ECS services on Fargate"},{"id":"C","text":"EC2, S3, DynamoDB e RDS"},{"id":"D","text":"Todos os serviços AWS, incluindo SaaS e Marketplace"}]'::jsonb, 'B',
  '{
    "summary": "Compute Optimizer cobre EC2, Auto Scaling Groups, EBS volumes, Lambda functions e ECS Fargate.",
    "whyCorrect": "Compute Optimizer foca recursos de COMPUTE e armazenamento associado, com ML rightsizing: (1) **EC2 instances** — recomenda família, tamanho, Graviton migration; (2) **Auto Scaling Groups** — quando ASG mantém capacidade fixa, recomenda right-sizing; (3) **EBS volumes** — IOPS/throughput não utilizados; (4) **Lambda functions** — alocação de memória otimizada; (5) **ECS services on Fargate** — CPU/memory rightsizing.",
    "whyWrong": {
     "A": "Faz mais que EC2.",
     "C": "RDS, S3 e DynamoDB NÃO são cobertos pelo Compute Optimizer. Para RDS, use Performance Insights e RDS recommendations no Cost Explorer.",
     "D": "Não é universal — só compute resources."
    },
    "keyConcept": "Compute Optimizer = COMPUTE resources only (EC2, ASG, EBS, Lambda, Fargate). RDS/S3/DynamoDB usam outras ferramentas.",
    "compareWith": [
     "Compute Optimizer: EC2/ASG/EBS/Lambda/Fargate",
     "Cost Explorer: RDS/Redshift RI recs",
     "Trusted Advisor: checks gerais"
    ],
    "realWorldContext": "Para RDS rightsizing, usa-se Performance Insights + DB Instance Recommendations no Cost Explorer.",
    "commonMistakes": "Achar que Compute Optimizer cobre tudo.",
    "tutorSeeds": [
     "Como otimizar RDS então?",
     "Compute Optimizer tem custo?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'recall', '["compute-optimizer","rightsizing","scope"]'::jsonb, 'ai-draft', 'active', now(), now()
)
