INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-035', 'aws-clf', 'Sobre AWS Cost Explorer, qual feature requer assinatura paga (não vem incluído no plano gratuito)?',
  '[{"id":"A","text":"Análise de custos por serviço e tag (visualização diária)"},{"id":"B","text":"Forecast de custo para 12 meses à frente"},{"id":"C","text":"Hourly granularity e Resource-level granularity (filtros e visualizações por hora e por recurso específico)"},{"id":"D","text":"Reserved Instance recommendations"}]'::jsonb, 'C',
  '{
    "summary": "Hourly e Resource-level granularity no Cost Explorer são features PAGAS — $0.01 por 1.000 USERecords. Daily granularity é grátis.",
    "whyCorrect": "Cost Explorer por padrão tem granularidade diária (gratuita). Para análise mais granular — por hora ou por recurso individual (ex: cada EC2 instance ID separadamente) — é necessário ativar essa feature paga, que custa $0.01 por 1.000 USERecords (registros de uso) consultados. Útil para troubleshooting de picos de custo, análise de spikes intraday.",
    "whyWrong": {
     "A": "Daily por serviço/tag é grátis.",
     "B": "Forecast é grátis e nativo.",
     "D": "RI/SP recommendations são gratuitos."
    },
    "keyConcept": "Cost Explorer free = daily granularity + forecast + RI/SP recs. Paid = hourly + resource-level.",
    "compareWith": [
     "Daily: grátis (até 13 meses histórico)",
     "Hourly: paga",
     "Resource-level: paga"
    ],
    "realWorldContext": "Empresas com picos de tráfego ativam hourly para identificar exatamente quando custos picam (ex: campanha às 14h disparou $5k em CloudFront).",
    "commonMistakes": "Achar que tudo no Cost Explorer é grátis.",
    "tutorSeeds": [
     "Qual o custo exato de hourly granularity?",
     "Quanto tempo histórico Cost Explorer guarda?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'recall', '["cost-explorer","pricing","granularity"]'::jsonb, 'ai-draft', 'active', now(), now()
)
