INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-036', 'aws-clf', 'O Cost Explorer oferece RECOMMENDATIONS para reduzir custos. Quais TIPOS de recomendações são geradas por ele?',
  '[{"id":"A","text":"Apenas recomendações de Reserved Instances"},{"id":"B","text":"Apenas recomendações de Spot Instances"},{"id":"C","text":"Apenas recomendações de Free Tier"},{"id":"D","text":"Reserved Instance recommendations, Savings Plans recommendations e Rightsizing recommendations (esta última requer Compute Optimizer ativo)"}]'::jsonb, 'D',
  '{
    "summary": "Cost Explorer gera RI recommendations, Savings Plans recommendations e Rightsizing (com Compute Optimizer integrado).",
    "whyCorrect": "Cost Explorer Recommendations: (1) **Reserved Instance recommendations** — sugere RIs com base em uso histórico (EC2, RDS, ElastiCache, Redshift, OpenSearch); (2) **Savings Plans recommendations** — sugere commit em Compute SP ou EC2 Instance SP; (3) **Rightsizing recommendations** — em conjunto com Compute Optimizer, recomenda mudança de tamanho/family de EC2. Cada uma com term (1yr/3yr) e payment option (No/Partial/All Upfront).",
    "whyWrong": {
     "A": "Vai além de RI.",
     "B": "Não há recomendação de Spot (Spot é descontinuação dinâmica, não recomendação).",
     "C": "Free Tier não tem recomendação no Cost Explorer."
    },
    "keyConcept": "Cost Explorer recommendations = RI + SP + Rightsizing.",
    "compareWith": [
     "RI recs: serviços específicos",
     "SP recs: compute genérico",
     "Rightsizing: via Compute Optimizer"
    ],
    "realWorldContext": "Empresas implementam workflow trimestral: revisar SP/RI recommendations no Cost Explorer, comprar novos commits.",
    "commonMistakes": "Achar que Cost Explorer só faz análise histórica.",
    "tutorSeeds": [
     "Como avaliar uma RI recommendation?",
     "Quando preferir SP vs RI?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["cost-explorer","recommendations","ri","sp"]'::jsonb, 'ai-draft', 'active', now(), now()
)
