INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-037', 'aws-clf', 'Uma empresa quer ENTENDER se seus custos vão crescer nos próximos 3 meses dado o padrão atual de uso AWS. Qual feature do Cost Explorer atende?',
  '[{"id":"A","text":"Cost Explorer Forecast — projeta custos futuros baseado em padrão histórico, com upper/lower bound de confidence"},{"id":"B","text":"AWS Budgets"},{"id":"C","text":"Trusted Advisor"},{"id":"D","text":"Compute Optimizer"}]'::jsonb, 'A',
  '{
    "summary": "Cost Explorer Forecast usa ML para projetar custo até 12 meses, com bandas de confiança (upper/lower bound).",
    "whyCorrect": "Cost Explorer Forecast é feature nativa e gratuita que usa machine learning para projetar custos futuros (até 12 meses) com base no padrão histórico. Mostra três curvas: forecast central, upper bound (limite superior, 80% de confiança) e lower bound (limite inferior). É a melhor ferramenta para responder ''quanto vou gastar nos próximos 3 meses?''",
    "whyWrong": {
     "A": "Resposta correta — Cost Explorer Forecast.",
     "B": "AWS Budgets define ALERTAS sobre limites — não projeta sozinho (mas usa forecast).",
     "C": "Trusted Advisor não projeta custo.",
     "D": "Compute Optimizer não projeta custo total."
    },
    "keyConcept": "Cost Explorer Forecast = projeção ML de custo futuro. AWS Budgets = alerta sobre limites (pode usar forecast).",
    "compareWith": [
     "Cost Explorer Forecast: projeção 12 meses",
     "AWS Budgets: alertar quando ultrapassar X% do forecast",
     "Cost Anomaly Detection: detectar anomalias retroativas"
    ],
    "realWorldContext": "CFO recebe forecast mensal para planejar orçamento; Budgets envia alerta automático se forecast indica ultrapassar limite.",
    "commonMistakes": "Confundir Forecast (projeção) com Budgets (alerta).",
    "tutorSeeds": [
     "Como melhorar precisão do forecast?",
     "Forecast considera RI/SP existentes?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'scenario', '["cost-explorer","forecast","planning"]'::jsonb, 'ai-draft', 'active', now(), now()
)
