INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-038', 'aws-clf', 'Uma empresa compra um software SaaS (gerenciado pelo vendor) via AWS Marketplace. Como esse SaaS é faturado tipicamente?',
  '[{"id":"A","text":"Vendor envia fatura separada por e-mail; AWS bill não inclui SaaS"},{"id":"B","text":"AWS faz consolidação: o SaaS Contract aparece na AWS bill do cliente, somado aos demais serviços AWS — uma única fatura/pagamento"},{"id":"C","text":"Apenas SaaS Free Tier é coberto"},{"id":"D","text":"Cliente paga vendor em criptomoeda"}]'::jsonb, 'B',
  '{
    "summary": "Marketplace SaaS Contracts são consolidados na AWS bill — fatura única integrada.",
    "whyCorrect": "Uma das grandes vantagens do AWS Marketplace é a consolidação de billing: produtos SaaS, AMI software, container images e Annual Contracts aparecem na MESMA fatura AWS mensal do cliente. Isso simplifica procurement (um único fornecedor: AWS), aplicação de créditos AWS aplicáveis, e contabilidade. Créditos Activate frequentemente cobrem Marketplace, dependendo dos termos.",
    "whyWrong": {
     "A": "Falso — é consolidado.",
     "C": "Free Tier do Marketplace existe mas é separado da pergunta.",
     "D": "Sem relação."
    },
    "keyConcept": "Marketplace = billing consolidado na AWS bill = procurement simplificado.",
    "compareWith": [
     "Marketplace SaaS: AWS bill",
     "BYOL listing: cliente paga vendor à parte",
     "Direct purchase do vendor: fora de Marketplace, fatura separada"
    ],
    "realWorldContext": "Empresas com procurement complexo preferem Marketplace pois evitam abrir PO com cada vendor separadamente.",
    "commonMistakes": "Achar que Marketplace exige pagamento separado.",
    "tutorSeeds": [
     "Créditos AWS aplicam-se a Marketplace?",
     "Posso negociar via Private Offer?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'scenario', '["marketplace","saas-contract","consolidated-billing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
