INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-039', 'aws-clf', 'Sobre uma listagem **BYOL no AWS Marketplace**, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"AWS cobra licença + infra na bill do cliente"},{"id":"B","text":"Licenças BYOL no Marketplace são sempre gratuitas"},{"id":"C","text":"AWS cobra APENAS a infraestrutura (EC2, EBS); a licença é negociada e paga DIRETAMENTE ao vendor (fora da AWS bill)"},{"id":"D","text":"BYOL listing não existe no Marketplace"}]'::jsonb, 'C',
  '{
    "summary": "BYOL listing no Marketplace: AWS cobra só a infra (EC2/EBS); licença é tratada diretamente com vendor.",
    "whyCorrect": "Em uma BYOL listing no AWS Marketplace, o vendor publica seu software (AMI, container) com indicação clara que o cliente deve adquirir a licença separadamente pelo canal do próprio vendor. A AWS bill só inclui o custo de INFRA (compute, storage, network). Útil para clientes corporativos que já têm contratos enterprise com o vendor (Microsoft EA, Oracle ULA, SAP, IBM).",
    "whyWrong": {
     "A": "BYOL = licença NÃO está na AWS bill.",
     "B": "Software por trás continua pago — só não passa pela AWS.",
     "D": "BYOL listings existem e são comuns."
    },
    "keyConcept": "BYOL no Marketplace = infra cobrada pela AWS, licença paga direto ao vendor.",
    "compareWith": [
     "Hourly/PAYG: licença + infra na AWS bill",
     "Annual Contract: licença + infra na AWS bill",
     "BYOL listing: só infra na AWS bill"
    ],
    "realWorldContext": "Empresas com SQL Server EA preferem BYOL Marketplace para Windows AMIs, reusando licença existente em vez de pagar licença duplicada.",
    "commonMistakes": "Achar que BYOL Marketplace inclui licença.",
    "tutorSeeds": [
     "Como License Manager se integra com BYOL Marketplace?",
     "Quais vendors oferecem BYOL listings?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'best-practice', '["marketplace","byol","licensing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
