INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-bill-v3-040', 'aws-clf', 'Uma empresa adotou Compute Optimizer e o relatório indica que 40% das instâncias EC2 estão SUPER-DIMENSIONADAS, com uma economia potencial de $15.000/mês ao migrar para tamanhos menores. Antes de aplicar todas as mudanças, qual é a MELHOR PRÁTICA?',
  '[{"id":"A","text":"Aplicar imediatamente todas as recomendações via script — Compute Optimizer é sempre 100% preciso"},{"id":"B","text":"Ignorar Compute Optimizer pois suas recomendações são teóricas"},{"id":"C","text":"Apenas migrar para Spot Instances em vez de redimensionar"},{"id":"D","text":"Aplicar primeiro em ambientes não-produtivos (dev/staging) e em produção fazer rollout gradual com janelas de manutenção e monitoração de performance via CloudWatch"}]'::jsonb, 'D',
  '{
    "summary": "Aplicar recomendações de rightsizing gradualmente: começar em dev/staging, validar com CloudWatch e expandir cuidadosamente para produção.",
    "whyCorrect": "Compute Optimizer dá recomendações fortes (com risk score e expected impact), mas pode haver cargas com padrões que ML não captou (ex: pico anual de Black Friday, batch jobs noturnos não cobertos no período de análise). A best practice é: (1) Aplicar em dev/staging primeiro; (2) Validar performance com CloudWatch (CPU, memória, network); (3) Em produção, rollout gradual com janela de manutenção; (4) Monitorar pós-mudança 1-2 semanas; (5) Rollback se performance degradar.",
    "whyWrong": {
     "A": "Compute Optimizer não é 100% — analisa janela histórica que pode não capturar todos os padrões.",
     "B": "Ignorar recomendações é desperdício de dinheiro garantido.",
     "C": "Spot é estratégia diferente — adequada apenas a workloads tolerantes a interrupção; não substitui rightsizing."
    },
    "keyConcept": "Rightsizing recommendations = sugestões, não verdades absolutas. Validar antes de aplicar em prod.",
    "compareWith": [
     "Compute Optimizer: recomendação ML",
     "CloudWatch: validação real",
     "AWS Config: tracking de mudanças",
     "Auto Scaling: ajuste dinâmico contínuo"
    ],
    "realWorldContext": "Casos comuns: Compute Optimizer sugere reduzir EC2 de m5.xlarge para m5.large; após mudança, batch job mensal estoura memória — necessário voltar.",
    "commonMistakes": "Aplicar tudo em massa em produção sem validação.",
    "tutorSeeds": [
     "Como configurar guardrails para rightsizing?",
     "Qual janela mínima de análise para confiar no Compute Optimizer?"
    ]
   }'::jsonb,
  'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["compute-optimizer","rightsizing","operations"]'::jsonb, 'ai-draft', 'active', now(), now()
)
