INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-002', 'aws-clf', 'Um CFO avalia migrar de um data center próprio (servidores comprados a cada 5 anos, energia, refrigeração, equipe de operação física) para AWS. Qual é o principal benefício financeiro desse movimento, segundo os 6 benefícios da nuvem?',
  '[{"id":"A","text":"Eliminar completamente todos os custos operacionais"},{"id":"B","text":"Trocar despesa de capital (CapEx) por despesa variável (OpEx) baseada no uso"},{"id":"C","text":"Garantir o mesmo custo unitário independente da escala"},{"id":"D","text":"Transferir a responsabilidade fiscal dos servidores para a AWS"}]'::jsonb, 'B',
  '{
    "summary": "Trade CapEx for variable expense: deixa de comprar hardware adiantado (CapEx amortizado) e paga pelo consumo (OpEx).",
    "whyCorrect": "Trade CapEx for variable expense: deixa de comprar hardware adiantado (CapEx amortizado) e paga pelo consumo (OpEx).",
    "whyWrong": {
     "C": "Custo operacional não desaparece Custo unitário diminui com escala (economies of scale, outro benefício).",
     "D": "Responsabilidade fiscal é tema contábil/jurídico, não relacionado.",
     "A": "AWS não elimina todos os custos operacionais — apenas converte CapEx em OpEx variável e elimina custos de DC físico (refrigeração, energia, hardware swap). Empresa ainda tem custos: pessoas, software, suporte AWS, transferência de dados, treinamento. ''Eliminar completamente'' é claim absoluto que não se sustenta."
    },
    "keyConcept": "Princípio 1 dos 6 benefícios.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Princípio 1 dos 6 benefícios?",
     "Quais cenários reais aplicam Princípio 1 dos 6 benefícios?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["benefits","capex-opex","finance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
