INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-003', 'aws-clf', 'Uma empresa de e-commerce serve apenas o Brasil, mas precisa expandir para Europa e Japão em 6 meses, com latência aceitável para usuários locais. A equipe quer evitar construir data centers no exterior. Qual benefício da nuvem AWS atende esse objetivo?',
  '[{"id":"A","text":"Benefit from massive economies of scale"},{"id":"B","text":"Stop guessing capacity"},{"id":"C","text":"Go global in minutes"},{"id":"D","text":"Increase speed and agility"}]'::jsonb, 'C',
  '{
    "summary": "''Go global in minutes'' descreve replicar workload em múltiplas regiões AWS sem CapEx adicional — sa-east-1, eu-west-1, ap-northeast-1 cobrem os 3 mercados.",
    "whyCorrect": "''Go global in minutes'' descreve replicar workload em múltiplas regiões AWS sem CapEx adicional — sa-east-1, eu-west-1, ap-northeast-1 cobrem os 3 mercados.",
    "whyWrong": {
     "B": "Economias de escala falam de custo por unidade. ''Stop guessing capacity'' é elasticidade.",
     "D": "Agility é velocidade de iteração interna.",
     "A": "Economies of scale (preço unitário menor por agregação de demanda) é benefício real da AWS, mas não endereça o requisito específico de EXPANSÃO GEOGRÁFICA com baixa latência. Pricing global da AWS pode ser melhor, mas o que viabiliza Europa+Japão em meses é a presença de Regions em cada geografia."
    },
    "keyConcept": "Princípio dos 6 benefícios da nuvem.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Princípio dos 6 benefícios da nuvem?",
     "Quais cenários reais aplicam Princípio dos 6 benefícios da nuvem?",
     "Como AWS se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["benefits","global","regions"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
