INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-004', 'aws-clf', 'Uma equipe gasta 60% do tempo aplicando patches no SO de servidores físicos, trocando discos defeituosos e renovando hardware de 5 anos. O CTO quer redirecionar esse esforço para construir features de produto. Qual benefício da nuvem AWS descreve diretamente essa mudança?',
  '[{"id":"A","text":"Trade capital expense for variable expense"},{"id":"B","text":"Massive economies of scale"},{"id":"C","text":"Stop guessing capacity"},{"id":"D","text":"Stop spending money running and maintaining data centers"}]'::jsonb, 'D',
  '{
    "summary": "''Stop spending money running and maintaining DCs'' captura exatamente o undifferentiated heavy lifting — racks, energia, hardware swap são abstraídos pela AWS.",
    "whyCorrect": "''Stop spending money running and maintaining DCs'' captura exatamente o undifferentiated heavy lifting — racks, energia, hardware swap são abstraídos pela AWS.",
    "whyWrong": {
     "C": "Economies of scale é preço por uso. ''Stop guessing capacity'' é planejamento de capacidade.",
     "A": "CapEx→OpEx é benefício financeiro (não comprar hardware adiantado) — mas o enunciado fala de TEMPO da equipe gasto em patching/troca de discos, não de orçamento. A redirecionamento de ESFORÇO é capturado por ''stop maintaining DCs''; redirecionamento de DINHEIRO é ''trade CapEx for OpEx''.",
     "B": "Economies of scale (preço por agregação) reduz custo de cloud — não tem relação direta com tempo de equipe gasto operando hardware. Mesmo se a AWS fosse mais cara, o benefício de ''stop maintaining DCs'' (liberar equipe) ainda existiria."
    },
    "keyConcept": "Foco no diferencial do produto vs operação de infra.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Foco no diferencial do produto vs operação de infra?",
     "Quais cenários reais aplicam Foco no diferencial do produto vs operação de infra?",
     "Como DCs se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["benefits","undifferentiated-heavy-lifting"]'::jsonb, 'ai-draft', 'active', now(), now()
)
