INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-005', 'aws-clf', 'Uma plataforma de streaming previa 10.000 usuários simultâneos mas comprou hardware para 50.000 ''por garantia''. 80% da capacidade fica ociosa fora de eventos. Qual benefício da nuvem AWS resolve esse antipadrão?',
  '[{"id":"A","text":"Stop guessing capacity"},{"id":"B","text":"Massive economies of scale"},{"id":"C","text":"Go global in minutes"},{"id":"D","text":"Trade capital expense for variable expense"}]'::jsonb, 'A',
  '{
    "summary": "''Stop guessing capacity'' descreve elasticidade: provisiona 10k normalmente, escala para 50k+ no evento e reduz após.",
    "whyCorrect": "''Stop guessing capacity'' descreve elasticidade: provisiona 10k normalmente, escala para 50k+ no evento e reduz após. Pagar só pelo usado elimina overprovisioning.",
    "whyWrong": {
     "B": "Economies of scale é preço unitário. ''Go global'' é geografia.",
     "C": "Go global (Regions múltiplas) endereça expansão geográfica — não tem relação com overprovisioning de capacidade local. A startup tem 1 problema, capacity planning, não expansão internacional.",
     "D": "CapEx→OpEx é benefício relacionado (pagar variável vs fixo), mas o ângulo específico do problema é ''previsão errada de capacidade'', que é resolvido por elasticidade automática (stop guessing), não por modelo financeiro per se. Em CapEx fixo de cloud também daria overprovisioning."
    },
    "keyConcept": "Princípio dos 6 benefícios.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Princípio dos 6 benefícios?",
     "Quais cenários reais aplicam Princípio dos 6 benefícios?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["benefits","elasticity","capacity"]'::jsonb, 'ai-draft', 'active', now(), now()
)
