INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-006', 'aws-clf', 'Um arquiteto explica para a diretoria por que rodar 1 milhão de instâncias EC2 no agregado da AWS resulta em preço/hora menor do que rodar 100 servidores no DC próprio. Qual benefício da nuvem AWS sustenta essa lógica?',
  '[{"id":"A","text":"Speed and agility"},{"id":"B","text":"Benefit from massive economies of scale"},{"id":"C","text":"Stop guessing capacity"},{"id":"D","text":"Go global in minutes"}]'::jsonb, 'B',
  '{
    "summary": "AWS agrega o consumo de milhões de clientes e negocia hardware/energia em volume — esse desconto se reflete no preço por instância.",
    "whyCorrect": "AWS agrega o consumo de milhões de clientes e negocia hardware/energia em volume — esse desconto se reflete no preço por instância. É o benefício clássico de economies of scale.",
    "whyWrong": {
     "A": "Agility é prazo, elasticidade é variação, ''go global'' é geografia.",
     "C": "Stop guessing capacity refere-se a elasticidade individual do cliente (escalar conforme demanda) — não explica por que o preço unitário AWS é menor que DC próprio. São benefícios diferentes.",
     "D": "Go global in minutes é sobre expansão geográfica — não justifica menor preço/hora vs DC próprio. Pricing menor vem de agregação massiva (economies of scale)."
    },
    "keyConcept": "Conceito: poder de compra agregado da AWS > cliente individual.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: poder de compra agregado da AWS > cliente individual?",
     "Quais cenários reais aplicam Conceito: poder de compra agregado da AWS > cliente individual?",
     "Como AWS se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["benefits","economies-of-scale"]'::jsonb, 'ai-draft', 'active', now(), now()
)
