INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-007', 'aws-clf', 'Uma equipe quer rodar 50 experimentos A/B simultâneos com diferentes configurações de ML, derrubando cada experimento após 2 horas. No DC físico isso seria proibitivo. Qual COMBINAÇÃO de benefícios da nuvem habilita esse padrão?',
  '[{"id":"A","text":"Economies of scale + global reach"},{"id":"B","text":"Stop maintaining DCs + economies of scale"},{"id":"C","text":"CapEx→OpEx + speed/agility + stop guessing capacity"},{"id":"D","text":"Go global + economies of scale"}]'::jsonb, 'C',
  '{
    "summary": "Pagar por hora (variable expense) + provisionar/destruir em segundos (agility) + escalar dinamicamente (stop guessing) habilitam experimentação massiva.",
    "whyCorrect": "Pagar por hora (variable expense) + provisionar/destruir em segundos (agility) + escalar dinamicamente (stop guessing) habilitam experimentação massiva.",
    "whyWrong": {
     "B": "Economies of scale dá desconto mas não habilita o padrão. ''Stop maintaining DCs'' é operacional, não experimental. ''Go global'' é irrelevante para A/B local.",
     "A": "Economies of scale e global reach são benefícios reais mas não são o que VIABILIZA 50 experimentos curtos: o problema central é provisionar/destruir rápido + pagar só pelas horas usadas. Global reach seria relevante se experimentos precisassem rodar em múltiplas geografias.",
     "D": "Go global + economies of scale tratam de geografia e pricing — não endereçam diretamente experimentação rápida e fail-cheap. A combinação correta foca em variable expense + agility + elasticity."
    },
    "keyConcept": "Padrão fail-fast/cheap experimentation.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão fail-fast/cheap experimentation?",
     "Quais cenários reais aplicam Padrão fail-fast/cheap experimentation?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["benefits","experimentation","agility"]'::jsonb, 'ai-draft', 'active', now(), now()
)
