INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-008', 'aws-clf', 'Uma empresa migrou para AWS e a diretoria reclama que ''a conta da AWS é maior que o custo do DC antigo''. Investigando, descobre-se que rodam EC2 m5.4xlarge 24/7 em On-Demand mesmo para workloads de batch noturno. Qual benefício da nuvem NÃO está sendo aproveitado?',
  '[{"id":"A","text":"Economies of scale (a AWS é cara mesmo)"},{"id":"B","text":"Go global in minutes"},{"id":"C","text":"Stop spending on data centers"},{"id":"D","text":"Variable expense / pay-as-you-go (deveriam desligar/redimensionar conforme uso)"}]'::jsonb, 'D',
  '{
    "summary": "On-Demand 24/7 para batch noturno é o oposto de variable expense — paga por horas ociosas.",
    "whyCorrect": "On-Demand 24/7 para batch noturno é o oposto de variable expense — paga por horas ociosas. Deveriam usar Spot, scheduling, ou desligar fora do horário.",
    "whyWrong": {
     "A": "Economies of scale é benefício embutido no preço base. ''Go global'' não é aplicável.",
     "B": "Go global é sobre presença geográfica — não tem relação com o antipadrão descrito (instâncias 24/7 para workload batch). A empresa não está deixando de aproveitar expansão geográfica; está deixando de aproveitar pay-as-you-go.",
     "C": "Já houve benefício de stop spending on DCs (saíram do DC físico) — esse não é o que está sendo NEGLIGENCIADO. A reclamação é custo da AWS alto, e a causa é uso fixo 24/7 que ignora a natureza variável do pricing."
    },
    "keyConcept": "Antipattern: migrar lift-and-shift e manter padrão de uso fixo.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Antipattern: migrar lift-and-shift e manter padrão de uso fixo?",
     "Quais cenários reais aplicam Antipattern: migrar lift-and-shift e manter padrão de uso fixo?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'troubleshoot', '["benefits","cost","variable-expense"]'::jsonb, 'ai-draft', 'active', now(), now()
)
