INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-009', 'aws-clf', 'Uma fintech expandindo para 5 países precisa cumprir requisitos de soberania de dados locais (dados de cidadãos europeus em EU, brasileiros no BR, etc). Qual benefício da nuvem AWS habilita esse padrão sem CapEx em cada país?',
  '[{"id":"A","text":"Go global in minutes (deploy em Regions locais)"},{"id":"B","text":"Economies of scale"},{"id":"C","text":"Variable expense"},{"id":"D","text":"Speed and agility"}]'::jsonb, 'A',
  '{
    "summary": "AWS Regions em cada geografia (eu-central-1, sa-east-1, ap-southeast-1) permitem deploy local rapidamente — atende soberania sem construir DC físico.",
    "whyCorrect": "AWS Regions em cada geografia (eu-central-1, sa-east-1, ap-southeast-1) permitem deploy local rapidamente — atende soberania sem construir DC físico.",
    "whyWrong": {
     "B": "Economies of scale e variable expense são vantagens transversais mas não endereçam soberania.",
     "D": "Agility é tempo de iteração.",
     "C": "Variable expense (pay-as-you-go) é benefício de pricing — mas não endereça SOBERANIA DE DADOS, que é requisito regulatório de localização física. Mesmo com OpEx, dados precisam estar nos Regions corretos. Variable expense seria a resposta se o problema fosse custo variável."
    },
    "keyConcept": "Conceito: Regions são unidades geográficas independentes para compliance/soberania.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: Regions são unidades geográficas independentes para compliance/soberania?",
     "Quais cenários reais aplicam Conceito: Regions são unidades geográficas independentes para compliance/soberania?",
     "Como AWS Regions se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["benefits","data-sovereignty","regions"]'::jsonb, 'ai-draft', 'active', now(), now()
)
