INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-011', 'aws-clf', 'Uma equipe lança um produto novo sem saber se vai atrair 100 ou 100.000 usuários. Querem evitar comprar capacidade para o pior cenário e também evitar quedas em sucesso viral. Qual combinação de benefícios da nuvem AWS atende?',
  '[{"id":"A","text":"Economies of scale + go global"},{"id":"B","text":"Speed/agility + stop maintaining DCs"},{"id":"C","text":"Stop guessing capacity + variable expense"},{"id":"D","text":"Go global + economies of scale"}]'::jsonb, 'C',
  '{
    "summary": "Stop guessing = escalar para cima/baixo conforme demanda real.",
    "whyCorrect": "Stop guessing = escalar para cima/baixo conforme demanda real. Variable expense = pagar pela escala efetivamente usada. Juntos eliminam o dilema ''subestimar = queda / superestimar = desperdício''.",
    "whyWrong": {
     "A": "Economies of scale dá desconto, não elasticidade. ''Go global'' é geografia.",
     "B": "Agility é tempo de iteração.",
     "D": "Go global + economies of scale são benefícios reais, mas não endereçam o dilema CENTRAL descrito (capacity uncertainty entre 100 e 100.000 usuários). Go global cobre expansão geográfica; o problema aqui é elasticidade pura. A combinação certa é stop guessing + variable expense."
    },
    "keyConcept": "Padrão clássico de produto em early stage.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão clássico de produto em early stage?",
     "Quais cenários reais aplicam Padrão clássico de produto em early stage?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["benefits","elasticity","demand"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
