INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-012', 'aws-clf', 'Qual afirmação descreve melhor a diferença entre ''elasticidade'' e ''escalabilidade'' no contexto dos benefícios da nuvem AWS?',
  '[{"id":"A","text":"São sinônimos no contexto AWS"},{"id":"B","text":"Elasticidade só se aplica a storage; escalabilidade só a compute"},{"id":"C","text":"Elasticidade exige Reserved Instances; escalabilidade exige On-Demand"},{"id":"D","text":"Escalabilidade é a capacidade de crescer; elasticidade é crescer E encolher automaticamente conforme demanda"}]'::jsonb, 'D',
  '{
    "summary": "Escalabilidade = sistema suporta carga maior (pode ser manual).",
    "whyCorrect": "Escalabilidade = sistema suporta carga maior (pode ser manual). Elasticidade = ajuste automático bidirecional (cresce E encolhe) conforme demanda real — é estritamente um superset orientado a custo.",
    "whyWrong": {
     "A": "Não são sinônimos.",
     "B": "Elasticidade e escalabilidade aplicam-se a ambos compute E storage (e mais — network, database, etc.). Auto Scaling de EC2 é elasticidade de compute; S3 Intelligent-Tiering é elasticidade de storage class; RDS storage autoscaling existe. Não há separação por tipo de recurso.",
     "C": "Elasticidade NÃO depende de Reserved Instances — RIs são compromisso de pricing, ortogonal a escalar. Auto Scaling Groups e elasticidade funcionam em On-Demand, Spot ou em capacidade coberta por SP/RI. Conceitos confundidos: pricing model vs scaling behavior."
    },
    "keyConcept": "Distinção importante em provas e em design de arquitetura.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Distinção importante em provas e em design de arquitetura?",
     "Quais cenários reais aplicam Distinção importante em provas e em design de arquitetura?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["benefits","elasticity","scalability"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
