INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-013', 'aws-clf', 'Uma equipe projeta uma aplicação web e o arquiteto recomenda ''design for failure'' — assumir que qualquer componente pode falhar a qualquer momento. Qual prática AWS implementa esse princípio mais diretamente?',
  '[{"id":"A","text":"Distribuir instâncias em múltiplas Availability Zones com health checks e auto-recovery"},{"id":"B","text":"Usar apenas instâncias EC2 do mesmo tipo para uniformidade"},{"id":"C","text":"Aumentar o tamanho da instância (scale up) para evitar falhas"},{"id":"D","text":"Manter snapshots EBS semanais em uma única AZ"}]'::jsonb, 'A',
  '{
    "summary": "AZs são datacenters fisicamente isolados — distribuir Auto Scaling Group em ≥2 AZs sobrevive a falha de uma AZ inteira.",
    "whyCorrect": "AZs são datacenters fisicamente isolados — distribuir Auto Scaling Group em ≥2 AZs sobrevive a falha de uma AZ inteira. Health checks substituem instâncias falhas automaticamente.",
    "whyWrong": {
     "B": "Mesmo tipo de instância não previne falha.",
     "C": "Scale up vertical aumenta blast radius.",
     "D": "Snapshots em 1 AZ falham junto com a AZ."
    },
    "keyConcept": "Princípio: assumir falha → redundância em múltiplas AZs.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Princípio: assumir falha → redundância em múltiplas AZs?",
     "Quais cenários reais aplicam Princípio: assumir falha → redundância em múltiplas AZs?",
     "Como AZs se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'best-practice', '["design-principles","fail-fast","multi-az"]'::jsonb, 'ai-draft', 'active', now(), now()
)
