INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-016', 'aws-clf', 'Uma aplicação processa pedidos chamando sincronamente 5 microsserviços em cadeia (A→B→C→D→E). Se um serviço fica lento, toda a chain trava. Qual abordagem AWS aplica o princípio ''design for failure'' e ''loose coupling''?',
  '[{"id":"A","text":"Aumentar o timeout das chamadas síncronas para 60 segundos"},{"id":"B","text":"Consolidar todos os microsserviços em um monolito"},{"id":"C","text":"Migrar de EC2 para Lambda mantendo chamadas síncronas em cadeia"},{"id":"D","text":"Substituir todas as chamadas síncronas por mensageria assíncrona via SQS/SNS quando possível"}]'::jsonb, 'D',
  '{
    "summary": "Filas/eventos quebram o acoplamento temporal — A escreve em fila e segue; B consome no seu ritmo.",
    "whyCorrect": "Filas/eventos quebram o acoplamento temporal — A escreve em fila e segue; B consome no seu ritmo. Falhas/lentidão de B não bloqueiam A.",
    "whyWrong": {
     "A": "Timeout maior amplifica o problema (mais conexões presas).",
     "B": "Monolito tem outro tipo de acoplamento (deploy).",
     "C": "Lambda em cadeia síncrona tem o mesmo problema com cold starts."
    },
    "keyConcept": "Princípio: desacoplar via mensagens.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Princípio: desacoplar via mensagens?",
     "Quais cenários reais aplicam Princípio: desacoplar via mensagens?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["design-principles","async","microservices"]'::jsonb, 'ai-draft', 'active', now(), now()
)
