INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-017', 'aws-clf', 'Uma equipe quer aumentar capacidade de processamento. Tem duas opções: (1) trocar uma instância m5.large por m5.24xlarge (scale up vertical), ou (2) adicionar mais instâncias m5.large em um Auto Scaling Group (scale out horizontal). Qual princípio AWS recomenda preferir a segunda?',
  '[{"id":"A","text":"Scale horizontally to increase aggregate workload availability"},{"id":"B","text":"Use a single large instance to minimize networking"},{"id":"C","text":"Always use the largest available instance type"},{"id":"D","text":"Prefer monolithic architecture for cost optimization"}]'::jsonb, 'A',
  '{
    "summary": "Scale out (horizontal) distribui carga entre múltiplos nós menores: aumenta disponibilidade agregada, reduz blast radius de uma instância morta, e em geral é mais granular.",
    "whyCorrect": "Scale out (horizontal) distribui carga entre múltiplos nós menores: aumenta disponibilidade agregada, reduz blast radius de uma instância morta, e em geral é mais granular. Scale up (vertical) tem ceiling físico e SPOF.",
    "whyWrong": {
     "B": "Networking interno entre EC2 na mesma VPC tem latência baixa.",
     "C": "Usar sempre o maior tipo de instância é o anti-padrão: viola scale horizontally (concentra carga em SPOF), tem ceiling físico (mesmo o maior tipo eventualmente esgota), e o blast radius de uma falha é máximo. AWS recomenda múltiplas instâncias menores.",
     "D": "Arquitetura monolítica concentra todos os componentes em um processo/instância — oposto de loose coupling, oposto de scale out horizontal. Aumenta blast radius e dificulta escalar componentes individualmente. AWS Well-Architected recomenda decomposição em serviços fracamente acoplados."
    },
    "keyConcept": "Princípio Well-Architected.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Princípio Well-Architected?",
     "Quais cenários reais aplicam Princípio Well-Architected?",
     "Como SPOF se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["design-principles","horizontal-scaling"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
