INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-018', 'aws-clf', 'Uma equipe migra para AWS e mantém o padrão antigo: provisiona EC2 para o pico previsto de Black Friday durante o ano inteiro. Qual princípio AWS de design recomenda mudar essa prática?',
  '[{"id":"A","text":"Always use the largest instance type for safety"},{"id":"B","text":"Stop guessing your capacity needs — provision based on actual demand"},{"id":"C","text":"Buy 3-year Reserved Instances for the peak"},{"id":"D","text":"Disable Auto Scaling to keep performance predictable"}]'::jsonb, 'B',
  '{
    "summary": "''Stop guessing capacity'' = usar Auto Scaling baseado em métricas reais.",
    "whyCorrect": "''Stop guessing capacity'' = usar Auto Scaling baseado em métricas reais. Nuvem permite ter capacidade de pico só durante o pico.",
    "whyWrong": {
     "A": "Usar sempre o maior tipo de instância para ''segurança'' é overprovisioning crônico — paga-se pela capacidade de pico durante 100% do tempo. Viola variable expense e stop guessing. Pior em On-Demand. Seria razoável apenas se workload realmente fosse 24/7 saturado.",
     "C": "Comprar 3-year RIs para o pico de Black Friday compromete capital por 3 anos para servir 1 semana de uso real — desperdício enorme. RIs são para BASELINE de uso constante, não para spikes. Para picos, usar Auto Scaling com On-Demand/Spot.",
     "D": "Desativar Auto Scaling para ''performance previsível'' é o oposto do princípio: AS é exatamente o mecanismo que viabiliza não-provisionar para pico. Performance previsível vem de health checks, monitoring e tuning, não de capacidade fixa em pico."
    },
    "keyConcept": "Princípio dos 5 design principles.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Princípio dos 5 design principles?",
     "Quais cenários reais aplicam Princípio dos 5 design principles?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'best-practice', '["design-principles","capacity"]'::jsonb, 'ai-draft', 'active', now(), now()
)
