INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-019', 'aws-clf', 'Uma equipe de DevOps quer reduzir o tempo de feedback entre commit e detecção de problemas em produção. Qual princípio de design AWS recomenda?',
  '[{"id":"A","text":"Deploys mensais consolidados para reduzir risco"},{"id":"B","text":"Deploys apenas em horário comercial com aprovação manual"},{"id":"C","text":"Make frequent, small, reversible changes (deploys pequenos e frequentes com rollback fácil)"},{"id":"D","text":"Eliminar testes automatizados para acelerar deploy"}]'::jsonb, 'C',
  '{
    "summary": "Mudanças pequenas e frequentes (com canary/blue-green/CI-CD) reduzem blast radius e aceleram aprendizado.",
    "whyCorrect": "Mudanças pequenas e frequentes (com canary/blue-green/CI-CD) reduzem blast radius e aceleram aprendizado. Reversibilidade fácil incentiva experimentação.",
    "whyWrong": {
     "A": "Deploys mensais grandes têm maior blast radius e dificultam isolamento de bugs.",
     "B": "Restrições de horário não escalam com produto global.",
     "D": "Sem testes é antipattern."
    },
    "keyConcept": "Princípio Operational Excellence.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Princípio Operational Excellence?",
     "Quais cenários reais aplicam Princípio Operational Excellence?",
     "Como CI-CD se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["design-principles","ci-cd"]'::jsonb, 'ai-draft', 'active', now(), now()
)
