INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-021', 'aws-clf', 'Um arquiteto deseja eliminar SPOFs (single points of failure) na camada web. A app está em uma única EC2 sem ALB, sem ASG, em uma única AZ. Quais mudanças aplicam o princípio ''design for failure''?',
  '[{"id":"A","text":"Colocar instâncias em Auto Scaling Group atrás de um ALB, distribuídas em ≥2 AZs"},{"id":"B","text":"Aumentar o tamanho da instância de m5.large para m5.4xlarge"},{"id":"C","text":"Habilitar Termination Protection na instância única"},{"id":"D","text":"Migrar para um Dedicated Host"}]'::jsonb, 'A',
  '{
    "summary": "ASG + ALB + multi-AZ é a receita padrão: ALB roteia para instâncias saudáveis, ASG substitui automaticamente as falhas, multi-AZ sobrevive a falha de DC.",
    "whyCorrect": "ASG + ALB + multi-AZ é a receita padrão: ALB roteia para instâncias saudáveis, ASG substitui automaticamente as falhas, multi-AZ sobrevive a falha de DC.",
    "whyWrong": {
     "B": "Maior instância continua SPOF.",
     "C": "Termination Protection só protege contra delete acidental.",
     "D": "Dedicated Host é tenancy, não HA."
    },
    "keyConcept": "Princípio: redundância > recursos maiores.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Princípio: redundância > recursos maiores?",
     "Quais cenários reais aplicam Princípio: redundância > recursos maiores?",
     "Como ASG se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["design-principles","high-availability"]'::jsonb, 'ai-draft', 'active', now(), now()
)
