INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-022', 'aws-clf', 'Qual dos seguintes é um dos 6 pilares do AWS Well-Architected Framework adicionado mais recentemente (2021)?',
  '[{"id":"A","text":"Operational Excellence"},{"id":"B","text":"Sustainability"},{"id":"C","text":"Security"},{"id":"D","text":"Reliability"}]'::jsonb, 'B',
  '{
    "summary": "Sustainability foi o 6º pilar adicionado em re:Invent 2021.",
    "whyCorrect": "Sustainability foi o 6º pilar adicionado em re:Invent 2021. Os outros 5 (OE, Security, Reliability, Performance, Cost) já existiam.",
    "whyWrong": {
     "C": "OE, Security, Reliability são pilares originais.",
     "A": "Operational Excellence é um dos 5 pilares ORIGINAIS do Well-Architected Framework (lançado em 2015) — não é o adicionado mais recentemente. Foi um dos primeiros pilares formalizados.",
     "D": "Reliability é um dos 5 pilares ORIGINAIS do Well-Architected (existe desde 2015). Não foi adicionado em 2021. O adicionado em re:Invent 2021 foi Sustainability, refletindo crescente preocupação com pegada de carbono."
    },
    "keyConcept": "Conceito: 6 pilares = OE + Security + Reliability + Performance Efficiency + Cost Optimization + Sustainability.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: 6 pilares = OE + Security + Reliability + Performance Efficiency + Cost Optimization + Sustainability?",
     "Quais cenários reais aplicam Conceito: 6 pilares = OE + Security + Reliability + Performance Efficiency + Cost Optimization + Sustainability?",
     "Como OE se compara com alternativas?"
    ]
