INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-027', 'aws-clf', 'Uma equipe usa Compute Savings Plans, S3 Intelligent-Tiering, right-sizes EC2 mensalmente e desliga ambientes de dev fora do horário comercial. Qual pilar do Well-Architected guia essas práticas?',
