INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-029', 'aws-clf', 'Uma equipe quer aumentar disponibilidade movendo de single-AZ para multi-AZ. O custo dobra. Qual pilar do Well-Architected captura esse trade-off explícito entre dois pilares?',
  '[{"id":"A","text":"Reliability vs Cost Optimization (trade-off explícito permitido pelo framework)"},{"id":"B","text":"Sustainability vs Performance"},{"id":"C","text":"Security vs Operational Excellence"},{"id":"D","text":"Não existe trade-off — pilares são independentes"}]'::jsonb, 'A',
  '{
    "summary": "O framework reconhece explicitamente trade-offs entre pilares — mais Reliability (redundância) frequentemente custa mais.",
    "whyCorrect": "O framework reconhece explicitamente trade-offs entre pilares — mais Reliability (redundância) frequentemente custa mais. A decisão é informada pelo business value.",
    "whyWrong": {
     "B": "Outros pares têm trade-offs também (ex: Security vs Performance via encryption overhead), mas o cenário descrito é o clássico Reliability x Cost.",
     "C": "Security e Operational Excellence frequentemente se reforçam (mais OE = melhor detection/response) — não há trade-off canônico entre eles. O trade-off mais clássico e citado pelo framework é Reliability vs Cost: redundância (multi-AZ, multi-Region) aumenta tanto disponibilidade quanto custo.",
     "D": "Trade-offs entre pilares EXISTEM e são explicitamente reconhecidos no Well-Architected — esta opção é factualmente incorreta. Multi-AZ aumenta Reliability mas dobra custo de RDS; encryption pode adicionar latência (Performance vs Security); auto-shutdown reduz custo mas pode afetar reliability se mal configurado."
    },
    "keyConcept": "Conceito: pilares NÃO são independentes — equilíbrio é parte do framework.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: pilares NÃO são independentes — equilíbrio é parte do framework?",
     "Quais cenários reais aplicam Conceito: pilares NÃO são independentes — equilíbrio é parte do framework?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["well-architected","trade-offs"]'::jsonb, 'ai-draft', 'active', now(), now()
)
