INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-030', 'aws-clf', 'Após um post-mortem, a equipe escreve um runbook automatizado para o procedimento que falhou e adiciona um Game Day mensal para validar a recovery. Essas práticas pertencem majoritariamente a qual pilar?',
  '[{"id":"A","text":"Security"},{"id":"B","text":"Operational Excellence"},{"id":"C","text":"Cost Optimization"},{"id":"D","text":"Performance Efficiency"}]'::jsonb, 'B',
  '{
    "summary": "OE inclui runbooks, playbooks, Game Days, observability, post-mortems e melhoria contínua.",
    "whyCorrect": "OE inclui runbooks, playbooks, Game Days, observability, post-mortems e melhoria contínua. Embora a recovery seja Reliability, a prática de Game Day + runbook é OE.",
    "whyWrong": {
     "A": "Security/Cost/Performance têm outros focos.",
     "C": "Cost Optimization cobre Savings Plans, right-sizing, expenditure awareness — não runbooks de recovery ou Game Days. Práticas pós-mortem e validação de recovery são governança operacional, não financeira.",
     "D": "Performance Efficiency cobre seleção de tipos de recurso, caching, monitoring para latência — não runbooks de incidente ou Game Days. Práticas descritas são sobre operar bem (OE), não sobre throughput/latência (Performance)."
