INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-035', 'aws-clf', 'Uma aplicação tem latência p99 ruim. A equipe quer atacar pelo pilar Performance Efficiency. Qual prática NÃO é parte desse pilar?',
  '[{"id":"A","text":"Selecionar o tipo de instância ideal para o workload (compute, memory, storage optimized)"},{"id":"B","text":"Usar caching com ElastiCache/CloudFront"},{"id":"C","text":"Habilitar AWS Shield para mitigar DDoS"},{"id":"D","text":"Monitorar performance e ajustar continuamente"}]'::jsonb, 'C',
