INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-037', 'aws-clf', 'Qual é o objetivo central do AWS Well-Architected Framework?',
  '[{"id":"A","text":"Fornecer um conjunto consistente de princípios e melhores práticas para projetar/operar cargas na AWS"},{"id":"B","text":"Substituir a documentação de produtos AWS"},{"id":"C","text":"Garantir descontos de pricing automáticos para quem aderir"},{"id":"D","text":"Forçar uso de serviços específicos da AWS"}]'::jsonb, 'A',
  '{
    "summary": "WA Framework é um conjunto de boas práticas + perguntas + tool de revisão para guiar decisões arquiteturais — não substitui docs, não dá desconto, e não força serviços.",
    "whyCorrect": "WA Framework é um conjunto de boas práticas + perguntas + tool de revisão para guiar decisões arquiteturais — não substitui docs, não dá desconto, e não força serviços.",
    "whyWrong": {
     "B": "Well-Architected NÃO substitui documentação de produtos AWS — são recursos complementares. Documentação descreve COMO usar um serviço; WA descreve PRINCÍPIOS arquiteturais e práticas. WA referencia documentação, não a substitui.",
     "C": "Não há descontos automáticos de pricing por aderir ao Well-Architected — é framework de boas práticas, não programa de billing. Cliente pode até receber créditos AWS após realizar WA Review com partner certificado, mas isso é promoção pontual, não característica do framework.",
     "D": "Well-Architected NÃO força uso de serviços específicos — é agnóstico a quais serviços usar. As perguntas são sobre práticas (encryption ativa? logs centralizados?), não ''use serviço X''. O framework reconhece que múltiplos serviços podem atender ao mesmo requisito."
    },
    "keyConcept": "Ver Well-Architected Framework.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Ver Well-Architected Framework?",
     "Quais cenários reais aplicam Ver Well-Architected Framework?",
     "Como WA se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["well-architected","framework"]'::jsonb, 'ai-draft', 'active', now(), now()
)
