INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-038', 'aws-clf', 'Uma empresa percebe que tem 80 TB de snapshots EBS antigos sem owner, dados S3 em Standard com último acesso há 2 anos, e clusters dev rodando 24/7. Qual pilar do Well-Architected mais imediatamente endereçaria essas observações?',
  '[{"id":"A","text":"Security apenas"},{"id":"B","text":"Cost Optimization (com forte sobreposição com Sustainability)"},{"id":"C","text":"Performance Efficiency apenas"},{"id":"D","text":"Reliability apenas"}]'::jsonb, 'B',
  '{
    "summary": "Recursos não usados → custo + uso desnecessário de energia/hardware.",
    "whyCorrect": "Recursos não usados → custo + uso desnecessário de energia/hardware. Cost Optimization (expenditure awareness, cost-effective resources) é o foco direto, com sobreposição com Sustainability (data patterns — eliminar dados não-essenciais).",
    "whyWrong": {
     "A": "Security/Performance/Reliability não tratam recursos ociosos.",
     "C": "Performance Efficiency foca em uso adequado de recursos para meeting de SLAs de latência/throughput — recursos órfãos não impactam diretamente performance da aplicação que está rodando. O problema descrito é gasto desnecessário, não lentidão.",
     "D": "Reliability foca em disponibilidade e recovery — recursos sem owner não comprometem reliability da aplicação principal. Snapshots órfãos e dev 24/7 não são fault modes — são waste. O pilar canônico é Cost Optimization."
    },
    "keyConcept": "Conceito: pilares são complementares — várias respostas podem ser corretas, mas Cost é o mais direto.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: pilares são complementares — várias respostas podem ser corretas, mas Cost é o mais direto?",
     "Quais cenários reais aplicam Conceito: pilares são complementares — várias respostas podem ser corretas, mas Cost é o mais direto?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["well-architected","cost","sustainability"]'::jsonb, 'ai-draft', 'active', now(), now()
)
