INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-042', 'aws-clf', 'Uma empresa substitui seu CRM Siebel on-prem por Salesforce SaaS durante a migração para AWS. Qual estratégia das 6 Rs descreve esse movimento?',
  '[{"id":"A","text":"Refactor"},{"id":"B","text":"Repurchase (drop and shop)"},{"id":"C","text":"Replatform"},{"id":"D","text":"Retain"}]'::jsonb, 'B',
