INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-043', 'aws-clf', 'Durante a discovery de migração, uma equipe descobre que um servidor de aplicação está rodando mas ninguém na empresa consegue identificar a função, nem aparece tráfego significativo nos logs há 18 meses. Qual estratégia das 6 Rs aplicar?',
  '[{"id":"A","text":"Rehost"},{"id":"B","text":"Refactor"},{"id":"C","text":"Retire (descomissionar)"},{"id":"D","text":"Retain"}]'::jsonb, 'C',
  '{
    "summary": "Retire = identificar e desligar workloads sem uso.",
    "whyCorrect": "Retire = identificar e desligar workloads sem uso. Reduz custo, surface de ataque e escopo de migração. Estima-se que ~10-20% das apps em DCs grandes podem ser retired.",
    "whyWrong": {
     "B": "Refactor de app sem uso é absurdo.",
     "D": "Retain = manter on-prem por motivo específico (não ''por inércia'').",
     "A": "Rehost (lift-and-shift) migraria o servidor para AWS as-is — mas o requisito aqui é DESLIGAR um workload sem uso, não migrar. Rehostar app esquecido seria gastar dinheiro em algo que ninguém usa. A 6R correta é Retire (descomissionar)."
    },
    "keyConcept": "Conceito: discovery é crucial — retire libera orçamento.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: discovery é crucial — retire libera orçamento?",
     "Quais cenários reais aplicam Conceito: discovery é crucial — retire libera orçamento?",
     "Como DCs se compara com alternativas?"
    ]
   }'::jsonb,
