INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-050', 'aws-clf', 'Qual afirmação descreve corretamente a diferença de responsabilidade entre IaaS e PaaS na AWS?',
  '[{"id":"A","text":"Em IaaS o cliente não tem responsabilidade nenhuma; PaaS é mais restritivo"},{"id":"B","text":"Em IaaS o cliente patcha o OS; em PaaS isso é abstraído pelo provedor"},{"id":"C","text":"PaaS exige que o cliente gerencie o datacenter físico"},{"id":"D","text":"IaaS e PaaS são idênticos em responsabilidade"}]'::jsonb, 'B',
