INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-052', 'aws-clf', 'Uma equipe precisa decidir entre 3 modelos: IaaS (EC2), PaaS (Elastic Beanstalk), SaaS (WorkMail). Qual fator NÃO é um critério legítimo de escolha entre modelos?',
  '[{"id":"A","text":"Quanto controle a equipe precisa sobre OS/runtime"},{"id":"B","text":"Tempo de equipe disponível para gerenciar infra"},{"id":"C","text":"Customização técnica exigida pela aplicação"},{"id":"D","text":"Se a AWS oferece SLA financeiro maior em IaaS vs SaaS"}]'::jsonb, 'D',
  '{
    "summary": "SLAs variam por serviço específico, não por modelo (IaaS/PaaS/SaaS).",
    "whyCorrect": "SLAs variam por serviço específico, não por modelo (IaaS/PaaS/SaaS). Não é critério de escolha entre modelos.",
    "whyWrong": {
     "A": "Controle, tempo de equipe e customização são critérios legítimos clássicos.",
     "B": "Tempo de equipe disponível para gerenciar infra É critério legítimo de escolha — equipes pequenas tendem a preferir mais managed (PaaS/SaaS) para focar em produto; equipes com expertise em ops podem assumir IaaS. (Item correto: C — SLA não varia sistematicamente por modelo).",
     "C": "Customização técnica exigida pela aplicação É critério legítimo — apps com necessidades especiais (drivers customizados, kernel tuning, GPU específica) podem exigir IaaS; apps padrão Java/Python rodam bem em PaaS. (Item correto: C — SLA financeiro não é função do modelo)."
    },
    "keyConcept": "Conceito: escolha do modelo é trade-off controle × esforço × customização — não SLA agregado.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: escolha do modelo é trade-off controle × esforço × customização — não SLA agregado?",
     "Quais cenários reais aplicam Conceito: escolha do modelo é trade-off controle × esforço × customização — não SLA agregado?",
     "Como SLAs se compara com alternativas?"
    ]
   }'::jsonb,
