INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-053', 'aws-clf', 'Qual descreve corretamente o modelo de deployment ''public cloud''?',
  '[{"id":"A","text":"Infra hospedada e operada por um provedor (ex: AWS), multi-tenant, acessível via internet"},{"id":"B","text":"Infra hospedada no DC do próprio cliente, com hardware dedicado"},{"id":"C","text":"Combinação de cloud + on-premises com conectividade dedicada"},{"id":"D","text":"Apenas acessível por usuários de um único país"}]'::jsonb, 'A',
  '{
    "summary": "Public cloud = provedor (AWS/Azure/GCP) é dono da infra, oferta multi-tenant, acesso via internet com isolamento lógico (VPC, IAM, encryption).",
    "whyCorrect": "Public cloud = provedor (AWS/Azure/GCP) é dono da infra, oferta multi-tenant, acesso via internet com isolamento lógico (VPC, IAM, encryption).",
    "whyWrong": {
     "C": "On-prem/private cloud é cliente-owned.",
     "B": "Infra hospedada no DC do cliente com hardware dedicado é DEFINIÇÃO de private cloud (on-premises) — oposto de public cloud. Public cloud é multi-tenant, do provedor, acessível via internet pública (com isolamento lógico).",
     "D": "Public cloud por design é acessível globalmente via internet — não é restrita a um único país. AWS Regions estão espalhadas globalmente e qualquer cliente pode acessar qualquer Region (com exceções: GovCloud e China são restritas). ''Acessível por usuários de um único país'' descreveria uma cloud privada de uma empresa local."
    },
    "keyConcept": "Conceito: 3 modelos = public, private/on-prem, hybrid.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: 3 modelos = public, private/on-prem, hybrid?",
     "Quais cenários reais aplicam Conceito: 3 modelos = public, private/on-prem, hybrid?",
     "Como AWS se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["deployment-models","public-cloud"]'::jsonb, 'ai-draft', 'active', now(), now()
)
