INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-056', 'aws-clf', 'Uma empresa de mídia quer rodar workloads VMware existentes na AWS sem reescrever para EC2 nativo, mantendo vSphere/vSAN/NSX. Qual serviço AWS habilita esse padrão?',
  '[{"id":"A","text":"AWS Lambda"},{"id":"B","text":"AWS Elastic Beanstalk"},{"id":"C","text":"Amazon S3"},{"id":"D","text":"VMware Cloud on AWS"}]'::jsonb, 'D',
