INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-057', 'aws-clf', 'Qual descreve corretamente ''private cloud'' (também chamada on-premises cloud)?',
  '[{"id":"A","text":"Infra exclusiva de uma organização, on-prem ou hosted, sem multi-tenancy externa"},{"id":"B","text":"AWS dedicada para um único cliente, exclusiva por SLA"},{"id":"C","text":"Apenas acessível em uma única região geográfica"},{"id":"D","text":"Uma combinação obrigatória de cloud pública + on-prem"}]'::jsonb, 'A',
  '{
    "summary": "Private cloud = infra dedicada a uma única organização, geralmente on-prem com OpenStack/VMware.",
    "whyCorrect": "Private cloud = infra dedicada a uma única organização, geralmente on-prem com OpenStack/VMware. Não é multi-tenant. AWS não é private cloud (multi-tenant por design).",
    "whyWrong": {
     "B": "AWS NÃO é private cloud — é public cloud multi-tenant por design. AWS oferece isolamento LÓGICO (VPC, IAM, encryption) e algumas opções de tenancy dedicada (Dedicated Hosts, Dedicated Instances) mas a infra subjacente é compartilhada entre clientes. ''Private cloud'' refere-se a deploy on-prem (OpenStack, VMware) exclusivo de uma organização.",
     "C": "Private cloud pode ser acessível de qualquer geografia — depende da configuração de rede da organização, não do modelo. Não há restrição inerente a uma região geográfica. Esta opção mistura conceitos não relacionados.",
     "D": "Private cloud SOZINHA é um modelo válido — não exige combinação com cloud pública. Hybrid é o modelo que combina obrigatoriamente os dois. Private pura existe (empresa com OpenStack on-prem e zero cloud pública)."
    },
    "keyConcept": "Conceito: 3 modelos de deployment = public, private, hybrid.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: 3 modelos de deployment = public, private, hybrid?",
     "Quais cenários reais aplicam Conceito: 3 modelos de deployment = public, private, hybrid?",
     "Como VMware se compara com alternativas?"
    ]
   }'::jsonb,
