INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-058', 'aws-clf', 'Qual é a definição correta de Total Cost of Ownership (TCO) no contexto de avaliar migração para AWS?',
  '[{"id":"A","text":"Apenas o custo de hardware comprado"},{"id":"B","text":"Soma de todos os custos diretos e indiretos ao longo do ciclo de vida (hardware, software, energia, real estate, equipe, downtime, suporte)"},{"id":"C","text":"Custo mensal previsto na fatura AWS apenas"},{"id":"D","text":"Apenas o salário da equipe de DevOps"}]'::jsonb, 'B',
  '{
    "summary": "TCO completo inclui CapEx (servidores, racks, real estate) + OpEx (energia, refrigeração, equipe, licenças, manutenção, downtime, segurança física).",
    "whyCorrect": "TCO completo inclui CapEx (servidores, racks, real estate) + OpEx (energia, refrigeração, equipe, licenças, manutenção, downtime, segurança física). AWS substitui várias categorias dessas, daí a comparação é multi-dimensional.",
    "whyWrong": {
     "A": "Hardware sozinho é fração.",
     "C": "Fatura AWS é só uma parte.",
     "D": "Salário sozinho é fração."
    },
    "keyConcept": "Conceito: TCO é holístico, não custo único.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: TCO é holístico, não custo único?",
     "Quais cenários reais aplicam Conceito: TCO é holístico, não custo único?",
     "Como TCO se compara com alternativas?"
    ]
   }'::jsonb,
