INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-059', 'aws-clf', 'Um CIO quer comparar o custo de continuar no DC próprio vs migrar para AWS ao longo de 5 anos. Qual ferramenta AWS é desenhada especificamente para essa análise?',
  '[{"id":"A","text":"AWS Cost Explorer"},{"id":"B","text":"AWS Budgets"},{"id":"C","text":"AWS Pricing Calculator (com inputs de uso projetado)"},{"id":"D","text":"AWS Trusted Advisor"}]'::jsonb, 'C',
