INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-060', 'aws-clf', 'Em uma análise CapEx vs OpEx, qual afirmação descreve corretamente a natureza do gasto com AWS?',
  '[{"id":"A","text":"AWS gera CapEx, pois o cliente compra a infra"},{"id":"B","text":"AWS gera tanto CapEx quanto OpEx em partes iguais"},{"id":"C","text":"AWS não gera nem CapEx nem OpEx, é considerado ''investimento intangível''"},{"id":"D","text":"AWS gera OpEx, pois o cliente paga pelo uso variável sem ser dono do hardware"}]'::jsonb, 'D',
