INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-061', 'aws-clf', 'Uma empresa monta análise de TCO comparando DC próprio (servidores totalmente amortizados em 5 anos, equipe enxuta, baixo crescimento) com AWS On-Demand. AWS sai mais caro. Qual conclusão é mais defensável?',
  '[{"id":"A","text":"Para workloads ultra-estáveis com hardware amortizado, DC próprio pode ter TCO menor; AWS ganha em flexibilidade, agility, time-to-market e elimina risco de capacity planning errado"},{"id":"B","text":"AWS é sempre mais cara que DC próprio"},{"id":"C","text":"TCO em AWS é sempre menor independente do cenário"},{"id":"D","text":"TCO não é métrica relevante para nuvem"}]'::jsonb, 'A',
  '{
    "summary": "Realidade: nem sempre AWS é mais barata em TCO direto — workloads estáticos com hardware amortizado podem custar menos on-prem.",
    "whyCorrect": "Realidade: nem sempre AWS é mais barata em TCO direto — workloads estáticos com hardware amortizado podem custar menos on-prem. O valor de AWS combina TCO + benefícios não-financeiros (agility, elasticidade, redução de risco).",
    "whyWrong": {
     "B": "Afirmações absolutas (sempre mais cara/mais barata) são falsas.",
     "C": "TCO em AWS NÃO é sempre menor — esta é falsa promessa de marketing simplista. Workloads ultra-estáveis 24/7 com hardware totalmente amortizado em DC já existente podem custar menos on-prem. O valor de AWS está na combinação TCO + agility + redução de risco + time-to-market, não em garantia universal de menor preço.",
     "D": "TCO É métrica altamente relevante para nuvem — CFOs usam TCO para justificar migrações, otimizações de cost. AWS publica calculadoras TCO oficialmente. Dizer que TCO é irrelevante é factualmente errado e contradiz prática estabelecida de cloud financial management (FinOps)."
    },
    "keyConcept": "Conceito: TCO é uma das dimensões, não a única.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: TCO é uma das dimensões, não a única?",
     "Quais cenários reais aplicam Conceito: TCO é uma das dimensões, não a única?",
     "Como AWS se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'best-practice', '["tco","finance","trade-off"]'::jsonb, 'ai-draft', 'active', now(), now()
)
