INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-062', 'aws-clf', 'Quais categorias de custo on-prem o cliente DEIXA de pagar ao migrar 100% para AWS public cloud?',
  '[{"id":"A","text":"Salários de desenvolvedores que escrevem a aplicação"},{"id":"B","text":"Hardware de servidor, energia, refrigeração, real estate do DC, equipe de operação física"},{"id":"C","text":"Licenças de software de aplicação proprietária (ex: licença SAP do cliente)"},{"id":"D","text":"Custos de marketing do produto que roda na cloud"}]'::jsonb, 'B',
  '{
    "summary": "Categorias eliminadas: hardware, energia, refrigeração, espaço físico, equipe de DC (data center engineers, electricians).",
    "whyCorrect": "Categorias eliminadas: hardware, energia, refrigeração, espaço físico, equipe de DC (data center engineers, electricians). Diluídas no preço AWS via economies of scale.",
    "whyWrong": {
     "A": "escrevem a app. [extra: Devs continuam]",
     "C": "Licenças de app proprietária do cliente continuam (BYOL ou nova licença).",
     "D": "Marketing é outro centro de custo."
    },
    "keyConcept": "Conceito: AWS substitui infra física, não toda a stack de negócio.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: AWS substitui infra física, não toda a stack de negócio?",
