INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-063', 'aws-clf', 'Um CFO comenta que prefere CapEx pois pode depreciar ao longo de anos e melhora o EBITDA. Qual é uma resposta tecnicamente correta sobre OpEx em AWS?',
  '[{"id":"A","text":"OpEx em AWS é sempre superior a CapEx em qualquer cenário"},{"id":"B","text":"AWS oferece opção de capitalizar gastos como CapEx por padrão"},{"id":"C","text":"OpEx em AWS aparece como despesa operacional no período em que é consumido, melhorando alinhamento com a receita gerada e eliminando risco de obsolescência"},{"id":"D","text":"EBITDA é irrelevante para análise de TCO em cloud"}]'::jsonb, 'C',
  '{
    "summary": "OpEx por consumo casa custo com receita (matching principle), evita CapEx sunk em hardware que pode ficar obsoleto, e libera capital para investimento no negócio.",
    "whyCorrect": "OpEx por consumo casa custo com receita (matching principle), evita CapEx sunk em hardware que pode ficar obsoleto, e libera capital para investimento no negócio. Trade-off real: CapEx reduz despesa de período via depreciação; OpEx aumenta despesa imediata mas dá flexibilidade.",
    "whyWrong": {
     "D": "EBITDA é métrica legítima.",
     "A": "OpEx NÃO é sempre superior a CapEx em qualquer cenário — workloads ultra-estáveis com hardware amortizado podem ter CapEx menor. Trade-off depende de contexto (volatilidade de demanda, capital disponível, depreciação tributária). Afirmação absoluta é falsa.",
     "B": "AWS NÃO oferece opção de capitalizar gastos como CapEx por padrão — o pricing é fundamentalmente OpEx (pay-per-use). Compromissos longos (SP/RI) podem ser tratados pelo contador como prepaid expense amortizada, mas isso é decisão contábil do cliente, não feature da AWS."
    },
    "keyConcept": "Conceito: decisão CapEx/OpEx é multi-fatorial.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: decisão CapEx/OpEx é multi-fatorial?",
     "Quais cenários reais aplicam Conceito: decisão CapEx/OpEx é multi-fatorial?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'best-practice', '["tco","capex-opex","finance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
