INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-064', 'aws-clf', 'Qual elemento NÃO faz parte do cálculo de TCO típico para comparar AWS vs DC próprio?',
  '[{"id":"A","text":"Custo de energia e refrigeração do DC"},{"id":"B","text":"Custo de equipe dedicada à operação de hardware físico"},{"id":"C","text":"Custo de depreciação de hardware ao longo de 3-5 anos"},{"id":"D","text":"Receita gerada pela aplicação que roda na infra"}]'::jsonb, 'D',
  '{
    "summary": "TCO captura custos — não receitas.",
    "whyCorrect": "TCO captura custos — não receitas. Receita gerada entra em análise de ROI/payback, não TCO.",
    "whyWrong": {
     "A": "Energia, refrigeração, equipe de ops e depreciação são todos componentes válidos de TCO.",
     "B": "Custo de equipe dedicada à operação de hardware físico É parte legítima de TCO de DC próprio — sysadmins, engenheiros de DC, operadores. Migrar para AWS elimina ou reduz drasticamente essa equipe. (Item correto: C — receita é elemento de ROI, não TCO).",
     "C": "Depreciação de hardware ao longo de 3-5 anos É elemento legítimo de TCO de DC próprio — captura o custo amortizado do CapEx inicial. Em AWS, equivalente seria os compromissos de SP/RI. (Item correto: C — receita gerada pela aplicação não é custo, é benefício, fica em ROI)."
    },
    "keyConcept": "Conceito: TCO = só lado do custo; ROI = custo vs benefício.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: TCO = só lado do custo; ROI = custo vs benefício?",
     "Quais cenários reais aplicam Conceito: TCO = só lado do custo; ROI = custo vs benefício?",
     "Como TCO se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["tco","calculation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
