INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-065', 'aws-clf', 'Um gerente de produto pergunta ''qual é a diferença entre AWS Region e Availability Zone?''. Qual é a resposta tecnicamente correta?',
  '[{"id":"A","text":"Region é uma localização geográfica com múltiplas AZs (datacenters fisicamente isolados); AZ é um conjunto de 1+ datacenters dentro da Region, com energia/rede/refrigeração independentes"},{"id":"B","text":"Region é o mesmo que AZ, apenas nome diferente"},{"id":"C","text":"Region é um datacenter físico único; AZ é uma sala dentro dele"},{"id":"D","text":"Region é um conceito lógico apenas; AZs não existem fisicamente"}]'::jsonb, 'A',
  '{
    "summary": "Region = área geográfica (ex: sa-east-1 em São Paulo, BR) com múltiplas AZs (≥3 tipicamente).",
    "whyCorrect": "Region = área geográfica (ex: sa-east-1 em São Paulo, BR) com múltiplas AZs (≥3 tipicamente). AZ = um ou mais DCs fisicamente isolados (km de distância em alguns casos), com falhas independentes.",
    "whyWrong": {
     "B": "Region ≠ AZ.",
     "C": "Region não é um único DC.",
     "D": "AZs SÃO entidades físicas concretas — cada AZ é um ou mais data centers reais com prédios, energia, rede, refrigeração e backups independentes. AWS publica esses fatos em white papers (mesmo sem revelar localizações exatas por segurança). Dizer que são ''lógicas'' contradiz a documentação oficial."
    },
    "keyConcept": "Conceito: hierarquia AWS = Region > AZ > DC.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: hierarquia AWS = Region > AZ > DC?",
     "Quais cenários reais aplicam Conceito: hierarquia AWS = Region > AZ > DC?",
     "Como BR se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["global-infra","region","az"]'::jsonb, 'ai-draft', 'active', now(), now()
)
