INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-066', 'aws-clf', 'Uma equipe quer reduzir latência de assets estáticos (imagens, CSS, JS) para usuários globais sem mover origem de us-east-1. Qual componente da Global Infrastructure atende melhor?',
  '[{"id":"A","text":"Availability Zones adicionais"},{"id":"B","text":"Edge Locations (via Amazon CloudFront)"},{"id":"C","text":"AWS Outposts"},{"id":"D","text":"AWS Wavelength"}]'::jsonb, 'B',
  '{
    "summary": "Edge Locations (~600+ globalmente) servem cache de CloudFront perto do usuário — ideal para conteúdo estático cacheável.",
    "whyCorrect": "Edge Locations (~600+ globalmente) servem cache de CloudFront perto do usuário — ideal para conteúdo estático cacheável. Reduz latência sem replicar origem.",
    "whyWrong": {
     "C": "Outposts é AWS no DC do cliente.",
     "D": "Wavelength é 5G edge para apps móveis ultra-low latency.",
     "A": "AZs adicionais reduzem latência apenas marginalmente (intra-Region) — não resolvem o problema de usuários em outros continentes alcançando us-east-1. Multi-AZ é HA dentro de uma Region; latência global exige distribuição via Edge Locations (CDN) ou Regions múltiplas."
    },
    "keyConcept": "Conceito: hierarquia = Region > AZ > Local Zone > Edge Location > Wavelength.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: hierarquia = Region > AZ > Local Zone > Edge Location > Wavelength?",
