INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-067', 'aws-clf', 'Uma empresa de games quer servir compute com latência de um dígito de milissegundos para jogadores em Los Angeles, mas a Region mais próxima (us-west-2) está em Oregon. Qual componente da Global Infrastructure resolve?',
  '[{"id":"A","text":"Edge Location para cache estático"},{"id":"B","text":"Mais AZs em us-west-2"},{"id":"C","text":"AWS Local Zones (ex: Los Angeles Local Zone)"},{"id":"D","text":"AWS Storage Gateway"}]'::jsonb, 'C',
  '{
