INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-069', 'aws-clf', 'Qual quantidade típica MÍNIMA de Availability Zones existe em uma AWS Region nova lançada nos últimos anos?',
  '[{"id":"A","text":"3 AZs"},{"id":"B","text":"1 AZ"},{"id":"C","text":"10 AZs"},{"id":"D","text":"Varia entre 1 e 2 AZs"}]'::jsonb, 'A',
  '{
    "summary": "AWS lança Regions novas com mínimo de 3 AZs para garantir quorum em sistemas distribuídos (RDS Multi-AZ, Aurora, DynamoDB global tables) e resiliência.",
    "whyCorrect": "AWS lança Regions novas com mínimo de 3 AZs para garantir quorum em sistemas distribuídos (RDS Multi-AZ, Aurora, DynamoDB global tables) e resiliência. Algumas regions têm 4-6 AZs.",
    "whyWrong": {
     "B": "Regions AWS modernas exigem MÍNIMO de 3 AZs — não 1. Com 1 AZ não há resiliência multi-AZ nativa nem quorum para sistemas distribuídos (RDS Multi-AZ, Aurora). Algumas Regions antigas (pré-2018) lançaram com 2 AZs, mas o padrão atual é 3+.",
     "C": "10 AZs não é mínimo nem típico — é número que apenas Regions muito grandes podem ter (us-east-1 tem 6, us-west-2 tem 4). O MÍNIMO para nova Region é 3 AZs para garantir quorum e Multi-AZ HA.",
     "D": "A política atual da AWS é mínimo de 3 AZs para Regions novas — não varia entre 1 e 2. Regions antigas (pré-2018) podem ter 2 AZs por motivos históricos, mas qualquer lançamento moderno tem 3+."
    },
    "keyConcept": "Conceito: 3+ AZs é padrão moderno.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: 3+ AZs é padrão moderno?",
     "Quais cenários reais aplicam Conceito: 3+ AZs é padrão moderno?",
     "Como AWS se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["global-infra","az","regions"]'::jsonb, 'ai-draft', 'active', now(), now()
)
