INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-070', 'aws-clf', 'Quais critérios devem orientar a escolha de uma AWS Region para um workload?',
  '[{"id":"A","text":"Apenas o preço mais baixo"},{"id":"B","text":"Latência aos usuários, compliance/soberania de dados, disponibilidade de serviços específicos, preço, sustentabilidade"},{"id":"C","text":"Sempre a Region mais antiga (us-east-1) por estabilidade"},{"id":"D","text":"Sempre a Region geograficamente mais próxima ao escritório"}]'::jsonb, 'B',
  '{
    "summary": "Decisão multi-fatorial: (1) latência aos usuários reais, (2) compliance/soberania (GDPR, LGPD), (3) services disponibilizados na Region (nem todos lançam simultaneamente), (4) preço (varia por Region), (5) mix de energia renovável.",
    "whyCorrect": "Decisão multi-fatorial: (1) latência aos usuários reais, (2) compliance/soberania (GDPR, LGPD), (3) services disponibilizados na Region (nem todos lançam simultaneamente), (4) preço (varia por Region), (5) mix de energia renovável.",
    "whyWrong": {
     "C": "Single-factor decisions falham. us-east-1 é maior mas tem histórico de outages grandes.",
     "D": "Proximidade ao escritório é irrelevante",
     "A": "Escolher Region apenas pelo preço mais baixo ignora fatores críticos: latência ao usuário (UX), compliance/soberania (GDPR pode exigir EU), disponibilidade de serviços (nem todos lançam em todas as Regions simultaneamente), sustentabilidade. Pricing isolado é critério incompleto e potencialmente ilegal (LGPD)."
    },
    "keyConcept": "Conceito: matriz de decisão.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: matriz de decisão?",
     "Quais cenários reais aplicam Conceito: matriz de decisão?",
     "Como GDPR se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["global-infra","region-selection"]'::jsonb, 'ai-draft', 'active', now(), now()
)
