INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-071', 'aws-clf', 'Uma empresa configura RDS Multi-AZ. Qual é o benefício PRINCIPAL desse setup em termos de Global Infrastructure?',
  '[{"id":"A","text":"Reduz latência para usuários em outros continentes"},{"id":"B","text":"Reduz custo do RDS pela metade"},{"id":"C","text":"Failover automático para uma standby replica em outra AZ caso a AZ primária falhe"},{"id":"D","text":"Permite escalar leitura ilimitadamente"}]'::jsonb, 'C',
  '{
    "summary": "Multi-AZ = standby síncrona em AZ diferente; failover automático em ~60-120s se primária cair.",
    "whyCorrect": "Multi-AZ = standby síncrona em AZ diferente; failover automático em ~60-120s se primária cair. Foco é alta disponibilidade dentro de uma Region.",
    "whyWrong": {
     "A": "Latência cross-continente exige cross-Region (Read Replicas globais ou Aurora Global).",
     "B": "Custo dobra (não cai).",
     "D": "Multi-AZ no RDS NÃO escala leitura — a standby é síncrona e NÃO atende reads (exceto em Aurora). Para escalar leitura, o construto é Read Replicas (assíncronas, podem ser em mesma Region ou cross-Region). Multi-AZ foca exclusivamente em HA via failover, não em scale-out."
    },
    "keyConcept": "Conceito: Multi-AZ = HA intra-Region; cross-Region = DR/disaster recovery.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: Multi-AZ = HA intra-Region; cross-Region = DR/disaster recovery?",
     "Quais cenários reais aplicam Conceito: Multi-AZ = HA intra-Region; cross-Region = DR/disaster recovery?",
     "Como AZ se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["global-infra","multi-az","rds"]'::jsonb, 'ai-draft', 'active', now(), now()
)
