INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-072', 'aws-clf', 'Uma equipe de mídia precisa que vídeos sejam servidos com baixa latência globalmente, MAS o origin S3 fica em us-east-1. Qual padrão de Global Infrastructure resolve?',
  '[{"id":"A","text":"Replicar o S3 manualmente em todas as 30+ Regions"},{"id":"B","text":"Usar AWS Outposts em cada país"},{"id":"C","text":"Mudar para AWS Wavelength"},{"id":"D","text":"Amazon CloudFront com Edge Locations em frente do origin S3"}]'::jsonb, 'D',
  '{
    "summary": "CloudFront cacheia conteúdo em Edge Locations próximas dos usuários — primeira request pega de us-east-1, subsequentes da edge.",
    "whyCorrect": "CloudFront cacheia conteúdo em Edge Locations próximas dos usuários — primeira request pega de us-east-1, subsequentes da edge. Reduz latência global sem replicar manualmente.",
    "whyWrong": {
     "A": "Replicar S3 em 30+ Regions é caro/complexo [extra: cross-Region replication é para DR, não CDN.]",
     "B": "Outposts é DC do cliente.",
     "C": "Wavelength é 5G edge."
