INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-073', 'aws-clf', 'Uma empresa de banco precisa que dados de clientes brasileiros NUNCA saiam do território nacional por exigência da LGPD/BACEN. Qual ação de Global Infrastructure atende esse requisito?',
  '[{"id":"A","text":"Deploy em sa-east-1 (São Paulo) e configurar IAM/policies para impedir replicação cross-region"},{"id":"B","text":"Deploy em us-east-1 e confiar na criptografia"},{"id":"C","text":"Deploy em qualquer Region e usar CloudFront"},{"id":"D","text":"Soberania de dados não é configurável na AWS"}]'::jsonb, 'A',
  '{
    "summary": "Region sa-east-1 fica fisicamente no Brasil.",
    "whyCorrect": "Region sa-east-1 fica fisicamente no Brasil. Combinar com SCPs (Organizations) e bucket policies que negam cross-region replication garante que dados permaneçam locais.",
    "whyWrong": {
     "B": "us-east-1 é EUA criptografia não muda jurisdição.",
     "C": "CloudFront tem edges no exterior.",
     "D": "Soberania É configurável via Region selection + guardrails."
    },
    "keyConcept": "Conceito: Region selection é o controle primário de soberania.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: Region selection é o controle primário de soberania?",
     "Quais cenários reais aplicam Conceito: Region selection é o controle primário de soberania?",
     "Como SCPs se compara com alternativas?"
    ]
   }'::jsonb,
