INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-074', 'aws-clf', 'Qual diferença existe entre ''Edge Location'' e ''Regional Edge Cache'' no CloudFront?',
  '[{"id":"A","text":"São o mesmo conceito, nomes diferentes"},{"id":"B","text":"Edge Locations são o primeiro tier de cache próximo do usuário; Regional Edge Caches são uma camada intermediária maior entre Edge Locations e o origin, melhorando hit ratio para conteúdo menos popular"},{"id":"C","text":"Regional Edge Cache só existe em us-east-1"},{"id":"D","text":"Edge Locations só servem conteúdo dinâmico"}]'::jsonb, 'B',
  '{
    "summary": "CloudFront tem 2 tiers: ~600+ Edge Locations + ~13 Regional Edge Caches.",
    "whyCorrect": "CloudFront tem 2 tiers: ~600+ Edge Locations + ~13 Regional Edge Caches. Quando miss na Edge, vai para Regional Edge Cache (maior, retém objetos mais tempo); só vai para origin se miss nos dois. Aumenta hit ratio e reduz egress.",
    "whyWrong": {
     "D": "Edge Locations servem dinâmico e estático.",
     "A": "Edge Locations e Regional Edge Caches são CONCEITOS DISTINTOS com papéis diferentes no CloudFront — não são sinônimos. Edge Locations (~600+) são o tier mais próximo do usuário; Regional Edge Caches (~13) são o tier intermediário com cache maior e duração mais longa.",
     "C": "Regional Edge Caches estão distribuídos globalmente em ~13 localizações estratégicas (não apenas em us-east-1). Eles cobrem regiões geográficas amplas servindo múltiplas Edge Locations. Concentrar em us-east-1 derrotaria o propósito de reduzir latência global."
    },
    "keyConcept": "Conceito: 2-tier cache hierarchy.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: 2-tier cache hierarchy?",
     "Quais cenários reais aplicam Conceito: 2-tier cache hierarchy?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["global-infra","cloudfront","edge-cache"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
