INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-075', 'aws-clf', 'Uma equipe precisa de DR cross-region para um workload crítico em us-east-1. Qual padrão Global Infrastructure é apropriado?',
  '[{"id":"A","text":"Adicionar mais AZs em us-east-1"},{"id":"B","text":"Habilitar CloudFront na frente da app"},{"id":"C","text":"Replicação para us-west-2 (Region geograficamente isolada, falhas independentes)"},{"id":"D","text":"Comprar mais Reserved Instances"}]'::jsonb, 'C',
  '{
    "summary": "DR cross-region protege contra falha de uma Region inteira (eventos raros mas catastróficos: us-east-1 já teve outages multi-AZ).",
    "whyCorrect": "DR cross-region protege contra falha de uma Region inteira (eventos raros mas catastróficos: us-east-1 já teve outages multi-AZ). Patterns: Pilot Light, Warm Standby, Multi-Region Active-Active.",
    "whyWrong": {
     "A": "Mais AZs em us-east-1 não protege contra falha de Region.",
     "B": "CloudFront não é DR.",
     "D": "Reserved Instances são compromisso de pricing — não fornecem disaster recovery. RIs em us-east-1 continuam afetadas se us-east-1 cair. DR cross-region exige replicação de dados, infra e capacidade em outra Region, ortogonal a pricing model."
    },
    "keyConcept": "Conceito: HA = multi-AZ; DR = multi-Region.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: HA = multi-AZ; DR = multi-Region?",
     "Quais cenários reais aplicam Conceito: HA = multi-AZ; DR = multi-Region?",
     "Como DR se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["global-infra","dr","cross-region"]'::jsonb, 'ai-draft', 'active', now(), now()
)
