INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-076', 'aws-clf', 'Após uma migração, a equipe relata que usuários em São Paulo veem latência de 200ms em uma app rodando em us-east-1. Qual ajuste de Global Infrastructure resolve mais diretamente?',
  '[{"id":"A","text":"Aumentar o tamanho da instância EC2"},{"id":"B","text":"Habilitar EBS encryption"},{"id":"C","text":"Adicionar uma read replica RDS na mesma Region us-east-1"},{"id":"D","text":"Replicar a app em sa-east-1 (São Paulo) ou usar CloudFront/Global Accelerator"}]'::jsonb, 'D',
  '{
    "summary": "Latência geográfica é problema físico (velocidade da luz).",
    "whyCorrect": "Latência geográfica é problema físico (velocidade da luz). Solução: aproximar compute do usuário via Region local (sa-east-1) ou edge (CloudFront para estático, Global Accelerator para dinâmico).",
    "whyWrong": {
     "A": "Instância maior não reduz RTT cross-continent.",
     "B": "Encryption adiciona ~0ms.",
     "C": "Replica na mesma Region não muda latência para SP."
    },
    "keyConcept": "Conceito: latência geográfica → arquitetura geográfica.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: latência geográfica → arquitetura geográfica?",
     "Quais cenários reais aplicam Conceito: latência geográfica → arquitetura geográfica?"
    ]
   }'::jsonb,
