INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-077', 'aws-clf', 'Qual afirmação é VERDADEIRA sobre custos de transferência de dados entre componentes da Global Infrastructure?',
  '[{"id":"A","text":"Tráfego entre AZs dentro de uma Region é cobrado (geralmente $0.01/GB cada direção); cross-Region e egress para internet também são cobrados"},{"id":"B","text":"Tráfego entre AZs dentro de uma Region é gratuito"},{"id":"C","text":"Toda transferência de dados na AWS é gratuita"},{"id":"D","text":"Apenas tráfego entrando na AWS (ingress) é cobrado"}]'::jsonb, 'A',
  '{
    "summary": "Modelo geral: ingress (entrada) gratuito; egress (saída para internet) cobrado; entre AZs cobrado (~$0.01/GB cada lado, ou seja $0.02 round-trip); cross-Region cobrado; mesma AZ via IP privado gratuito; CloudFront tem tarifa própria.",
    "whyCorrect": "Modelo geral: ingress (entrada) gratuito; egress (saída para internet) cobrado; entre AZs cobrado (~$0.01/GB cada lado, ou seja $0.02 round-trip); cross-Region cobrado; mesma AZ via IP privado gratuito; CloudFront tem tarifa própria.",
    "whyWrong": {
     "B": "Inter-AZ NÃO é gratuito (erro comum). Nem tudo é gratuito.",
     "D": "Egress é o cobrado, não ingress.",
     "C": "Nem toda transferência é gratuita — esta opção contradiz a realidade do pricing AWS. AWS cobra: egress para internet, cross-AZ, cross-Region, NAT Gateway traffic. Apenas alguns padrões são free (ingress, traffic dentro da mesma AZ via IP privado, alguns endpoints específicos). É um vetor frequente de cost surprise."
    },
    "keyConcept": "Conceito crítico para arquitetura: minimizar cross-AZ chatty traffic.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito crítico para arquitetura: minimizar cross-AZ chatty traffic?",
     "Quais cenários reais aplicam Conceito crítico para arquitetura: minimizar cross-AZ chatty traffic?",
     "Como AZs se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["global-infra","data-transfer","cost"]'::jsonb, 'ai-draft', 'active', now(), now()
)
