INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-078', 'aws-clf', 'Após implementar uma arquitetura multi-Region active-active, a equipe nota custos altos de cross-Region replication. Qual princípio de Cloud Concepts ajuda a justificar (ou repensar) esse investimento?',
  '[{"id":"A","text":"Cost optimization é o único pilar que importa"},{"id":"B","text":"Reliability vs Cost trade-off — multi-Region active-active aumenta resiliência ao custo de complexidade e data transfer; só vale se SLO justifica"},{"id":"C","text":"Multi-Region active-active é sempre obrigatório"},{"id":"D","text":"Cross-Region replication é gratuita"}]'::jsonb, 'B',
  '{
    "summary": "Multi-Region active-active vale para workloads tier-0 com SLO de 99.99%+, payments globais, etc.",
    "whyCorrect": "Multi-Region active-active vale para workloads tier-0 com SLO de 99.99%+, payments globais, etc. Para workloads tier-2/3, multi-AZ + backup cross-Region já basta. Decisão é trade-off Reliability × Cost × Complexity.",
    "whyWrong": {
     "A": "Cost não é o único pilar.",
     "C": "Active-active não é universal.",
     "D": "Replication cobra."
    },
    "keyConcept": "Conceito: Well-Architected reconhece trade-offs entre pilares.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: Well-Architected reconhece trade-offs entre pilares?",
     "Quais cenários reais aplicam Conceito: Well-Architected reconhece trade-offs entre pilares?",
     "Como SLO se compara com alternativas?"
    ]
   }'::jsonb,
