INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-080', 'aws-clf', 'Uma equipe quer aplicar o princípio do Well-Architected ''design for failure'' considerando falhas em níveis múltiplos da Global Infrastructure. Qual ordem de mitigação é correta do menor ao maior blast radius?',
  '[{"id":"A","text":"Failure de Region → Failure de AZ → Failure de instância"},{"id":"B","text":"Apenas considerar failure de Region é suficiente"},{"id":"C","text":"Falhas em AWS são impossíveis, não precisa planejar"},{"id":"D","text":"Failure de instância (Auto Scaling) → Failure de AZ (Multi-AZ) → Failure de Region (Multi-Region DR)"}]'::jsonb, 'D',
  '{
    "summary": "Ordem natural: instância (mais comum, mitigada por ASG + health checks) → AZ (rara mas acontece, mitigada por Multi-AZ) → Region (eventos raros catastróficos, mitigada por Multi-Region DR).",
    "whyCorrect": "Ordem natural: instância (mais comum, mitigada por ASG + health checks) → AZ (rara mas acontece, mitigada por Multi-AZ) → Region (eventos raros catastróficos, mitigada por Multi-Region DR). Cada camada tem custo crescente.",
    "whyWrong": {
     "B": "Considerar só Region ignora falhas mais frequentes.",
     "C": "AWS tem falhas (us-east-1 outages históricas)",
     "A": "A ordem está invertida — Region failure (raro, catastrófico, máximo blast radius) deve ser endereçado por ÚLTIMO no design, depois de instance e AZ failures. Começar por Region é over-engineering para problemas mais comuns. Defesa em profundidade trata o menor blast radius primeiro (instância) e escala para fora."
    },
    "keyConcept": "Conceito: defesa em profundidade na Global Infrastructure.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Conceito: defesa em profundidade na Global Infrastructure?",
     "Quais cenários reais aplicam Conceito: defesa em profundidade na Global Infrastructure?",
     "Como ASG se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'best-practice', '["global-infra","reliability","blast-radius"]'::jsonb, 'ai-draft', 'active', now(), now()
)
