INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-001', 'aws-clf', 'Uma empresa quer reduzir a pegada de carbono dos seus workloads AWS. Após uma análise, decidem mover jobs batch que rodam de madrugada para a região eu-west-1 (Irlanda, alta % de energia renovável) em vez de manter em us-east-1. Qual pilar do Well-Architected Framework guia essa decisão?',
  '[{"id":"A","text":"Sustainability"},{"id":"B","text":"Cost Optimization"},{"id":"C","text":"Operational Excellence"},{"id":"D","text":"Performance Efficiency"}]'::jsonb, 'A',
  '{
    "summary": "O pilar Sustainability (adicionado em 2021) orienta escolhas que minimizem impacto ambiental, incluindo Region Selection por matriz energética.",
    "whyCorrect": "Sustainability tem como design principle ''Select Regions based on both business needs and sustainability goals''. Regiões com maior fração de energia renovável (eu-west-1, eu-north-1, ca-central-1) reduzem a pegada de carbono do workload. É o único pilar que trata explicitamente de impacto ambiental.",
    "whyWrong": {
     "B": "Cost Optimization seria correto se o critério principal fosse preço por hora — eu-west-1 normalmente é mais cara que us-east-1, então ''mover por custo'' contradiz a premissa.",
     "C": "Operational Excellence trataria de runbooks, observabilidade e processos. Move workload por questão operacional (proximidade do time de operação, por exemplo) é OE, não a premissa aqui.",
     "D": "Performance Efficiency justificaria mudança de região para reduzir latência ao usuário final ou para acesso a tipos de instância específicos — não é o motivo descrito."
    },
    "keyConcept": "Well-Architected — Pilar Sustainability (6º pilar, 2021)",
    "compareWith": [
     "Cost Optimization vs Sustainability",
     "Performance Efficiency"
    ],
    "realWorldContext": "Empresas com metas ESG/Net Zero (ex: compromisso de carbono neutro até 2030) usam esse critério ao escolher região AWS.",
    "commonMistakes": "Confundir ''região mais barata'' (Cost) com ''região mais verde'' (Sustainability) — nem sempre coincidem.",
    "tutorSeeds": [
     "Quais regiões AWS têm maior fração de energia renovável publicada?",
     "Como o Customer Carbon Footprint Tool ajuda a medir essa pegada?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["well-architected","sustainability","region-selection"]'::jsonb, 'ai-draft', 'active', now(), now()
)
