INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-002', 'aws-clf', 'No pilar Sustainability, qual métrica é mais alinhada ao design principle ''maximize utilization'' para reduzir impacto ambiental?',
  '[{"id":"A","text":"Tempo médio de resposta em ms das APIs"},{"id":"B","text":"Taxa média de utilização de CPU acima de 60% nas instâncias EC2"},{"id":"C","text":"Disponibilidade mensal em % (SLA)"},{"id":"D","text":"Custo por transação em USD"}]'::jsonb, 'B',
  '{
    "summary": "Utilização alta de CPU/memória significa menos hardware ocioso por unidade de trabalho — é o KPI direto de ''maximize utilization''.",
    "whyCorrect": "Sustainability define explicitamente: ''right size each workload to maximize utilization''. Instâncias com 10% de CPU desperdiçam energia para o mesmo trabalho; consolidar para 60-80% reduz a quantidade de hardware ativo proporcional ao output, diminuindo emissões.",
    "whyWrong": {
     "A": "Latência é métrica do pilar Performance Efficiency, não Sustainability. Reduzir latência pode até aumentar consumo (mais réplicas, mais cache).",
     "C": "Disponibilidade é métrica do pilar Reliability (SLA, RTO, RPO). Aumentar disponibilidade frequentemente aumenta footprint (Multi-AZ, Multi-Region).",
     "D": "Custo por transação é métrica de Cost Optimization. Correlacionado mas não idêntico — workload pode ser barato e ainda ineficiente energeticamente (instância subutilizada com Savings Plan)."
    },
    "keyConcept": "Sustainability — proxy metrics: utilization, transactions per kWh",
    "compareWith": [
     "Performance Efficiency (latência)",
     "Cost Optimization (USD/transação)"
    ],
    "realWorldContext": "Customer Carbon Footprint Tool reporta kgCO2eq por serviço; combinado com utilização permite calcular kgCO2 por transação."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["well-architected","sustainability","utilization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
