INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-003', 'aws-clf', 'Uma equipe implementa retrospectivas mensais, post-mortems sem culpa após incidentes e atualiza runbooks automaticamente quando descobre um novo modo de falha. Esse comportamento é a essência de qual design principle do pilar Operational Excellence?',
  '[{"id":"A","text":"Perform operations as code"},{"id":"B","text":"Make frequent, small, reversible changes"},{"id":"C","text":"Learn from all operational failures"},{"id":"D","text":"Anticipate failure"}]'::jsonb, 'C',
  '{
    "summary": "''Learn from all operational failures'' é o feedback loop que post-mortems e atualização de runbooks materializam.",
    "whyCorrect": "Operational Excellence lista 5 design principles; ''Learn from all operational failures'' significa compartilhar aprendizados entre times, transformar incidente em melhoria de processo/automação. Post-mortem blameless + runbook update é o padrão canônico desse princípio.",
    "whyWrong": {
     "A": "''Perform operations as code'' significa IaC (CloudFormation/CDK) e runbooks executáveis — comportamento relacionado mas o cenário descreve aprendizado, não codificação.",
     "B": "''Make frequent, small, reversible changes'' é sobre deploy contínuo, feature flags, blue/green — não é o foco do cenário (que é retrospectiva e post-mortem).",
     "D": "''Anticipate failure'' descreve game days e chaos engineering — proativo, enquanto o cenário descreve reativo (aprender após falha já ocorrida)."
    },
    "keyConcept": "Operational Excellence — design principles (5)",
    "compareWith": [
     "Anticipate failure (proativo)",
     "Learn from failures (reativo)"
    ],
    "realWorldContext": "Empresas como Etsy, Netflix popularizaram blameless post-mortems como ritual de OE.",
    "tutorSeeds": [
     "Qual a diferença entre game day e chaos engineering?",
     "Como medir maturidade de OE numa equipe?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["well-architected","operational-excellence","feedback-loops"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
