INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-005', 'aws-clf', 'Uma startup brasileira atende usuários no Brasil e gasta R$ 80k/mês em sa-east-1. O CFO sugere migrar tudo para us-east-1 (até 30% mais barato). Considerando o trade-off entre Cost Optimization e Performance Efficiency, qual é a perda esperada?',
  '[{"id":"A","text":"Latência ao usuário final sobe ~120ms (RTT BR↔Virginia), degradando UX em chamadas API síncronas"},{"id":"B","text":"A Sustainability Pillar proíbe esse tipo de movimento"},{"id":"C","text":"Não há diferença prática — todas as regiões AWS têm a mesma latência"},{"id":"D","text":"Os dados do cliente ficam ilegíveis fora do Brasil"}]'::jsonb, 'A',
  '{
    "summary": "Mover de sa-east-1 para us-east-1 reduz custo mas adiciona ~120ms de RTT, degradando Performance Efficiency.",
    "whyCorrect": "A latência São Paulo↔Virginia é ~115-130ms RTT (fibra submarina). Para APIs síncronas (login, checkout) isso é perceptível ao usuário; para batch noturno, irrelevante. É o trade-off clássico Cost vs Performance que o Well-Architected Framework força a explicitar.",
    "whyWrong": {
     "B": "Sustainability não proíbe escolhas — apenas orienta. Curiosamente, us-east-1 historicamente tinha menor fração de renovável que eu-west-1, mas isso não ''proíbe'' o movimento.",
     "C": "Falso. Latência inter-region varia de 10ms (regiões próximas) a 250ms+ (extremos como sa-east-1↔ap-southeast-2).",
     "D": "Dados não ficam ''ilegíveis'' — criptografia funciona em qualquer região. O ponto sensível seria conformidade LGPD/residência, não legibilidade."
    },
    "keyConcept": "Region selection — 5 fatores (latência, custo, compliance, features, sustainability)",
    "compareWith": [
     "Cost Optimization",
     "Data residency (LGPD)"
    ],
    "realWorldContext": "Decisão recorrente em fintechs BR — manter core em sa-east-1 (latência + Bacen) e usar us-east-1 para analytics/ML (custo)."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["well-architected","performance-efficiency","region-selection"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
