INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-006', 'aws-clf', 'Uma equipe quer aplicar ''Stop guessing capacity'' no pilar Performance Efficiency. Qual mecanismo AWS é a manifestação mais direta desse princípio?',
  '[{"id":"A","text":"Reserved Instances de 3 anos com upfront total"},{"id":"B","text":"EC2 Auto Scaling com target tracking baseado em métricas reais (CPU, requests)"},{"id":"C","text":"AWS Budgets com alertas em $X mensais"},{"id":"D","text":"Trusted Advisor com checagem semanal"}]'::jsonb, 'B',
  '{
    "summary": "Auto Scaling provisiona capacidade dinamicamente em função da demanda real — fim do ''chute'' de capacidade.",
    "whyCorrect": "''Stop guessing capacity'' é resolvido por elasticidade: o sistema responde a métricas reais (CPU > 70% adiciona instância, < 30% remove). Target tracking é a forma mais alinhada porque mantém o sistema na meta sem oversize prévio.",
    "whyWrong": {
     "A": "Reserved Instance de 3 anos é o oposto — você compromete capacidade fixa antecipadamente, exatamente o ''guessing'' que se quer evitar.",
     "C": "Budgets é controle financeiro reativo (alerta quando gasto passa limite); não ajusta capacidade.",
     "D": "Trusted Advisor é advisory (recomenda right-sizing), mas é manual e periódico — não é elasticidade automática."
    },
    "keyConcept": "Elasticity — provisionamento reativo à demanda",
    "compareWith": [
     "Reserved Instance (commitment)",
     "Auto Scaling (elasticity)"
    ],
    "realWorldContext": "Black Friday em e-commerce — sem Auto Scaling, ou super-provisiona (caro) ou cai (perda de receita).",
    "tutorSeeds": [
     "Qual a diferença entre scalability e elasticity?",
     "Quando usar target tracking vs step scaling?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'best-practice', '["well-architected","performance-efficiency","elasticity"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
