INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-007', 'aws-clf', 'Uma empresa adota ''mechanical sympathy'' do pilar Performance Efficiency escolhendo Graviton (ARM) em vez de x86 para um workload Java stateless. Qual benefício esperado alinha-se diretamente a esse princípio?',
  '[{"id":"A","text":"Garantia de compatibilidade binária 100% com qualquer software"},{"id":"B","text":"Backup automático cross-region"},{"id":"C","text":"Melhor relação preço/desempenho por escolher a tecnologia certa para o workload"},{"id":"D","text":"Conformidade automática com LGPD"}]'::jsonb, 'C',
  '{
    "summary": "Mechanical sympathy: escolher hardware/instance type que mais combina com o workload. Graviton oferece até 40% melhor preço/desempenho para workloads compatíveis.",
    "whyCorrect": "''Use the technologies that align with what you are trying to achieve'' — Graviton (ARM Neoverse) é otimizado para workloads stateless e Java/Go modernos, entregando ~40% melhor preço/desempenho. É a aplicação direta do design principle.",
    "whyWrong": {
     "A": "Graviton (ARM) NÃO é binário-compatível com x86; software precisa de build ARM. A ''compatibilidade 100%'' é falsa e contradiz o ponto.",
     "B": "Backup cross-region é tema de Reliability/DR, não de mechanical sympathy.",
     "D": "LGPD é compliance, não relacionado à escolha de arquitetura de CPU."
    },
    "keyConcept": "Performance Efficiency — mechanical sympathy",
    "compareWith": [
     "Graviton vs x86 (Intel/AMD)",
     "Inferentia vs GPU"
    ],
    "realWorldContext": "Snap, Twitter (X), Pinterest migraram fleets significativas para Graviton com ganhos relevantes de custo."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["well-architected","performance-efficiency","graviton"]'::jsonb, 'ai-draft', 'active', now(), now()
)
