INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-008', 'aws-clf', 'Qual design principle do pilar Security do Well-Architected Framework é diretamente representado pela prática de cifrar dados tanto em repouso (KMS, EBS encryption) quanto em trânsito (TLS, VPN)?',
  '[{"id":"A","text":"Apply security at all layers"},{"id":"B","text":"Enable traceability"},{"id":"C","text":"Prepare for security events"},{"id":"D","text":"Protect data in transit and at rest"}]'::jsonb, 'D',
  '{
    "summary": "''Protect data in transit and at rest'' é o princípio que mapeia 1:1 a prática descrita.",
    "whyCorrect": "Esse design principle exige cifrar dados sensíveis em ambos os estados — repouso (KMS, S3 SSE, EBS encryption) e trânsito (TLS, VPN, mTLS). É o nome literal do princípio.",
    "whyWrong": {
     "A": "''Apply security at all layers'' (defense in depth) é mais amplo — inclui edge (WAF), VPC (SGs, NACLs), instância (host), app, dados. Cifragem é parte, não o todo.",
     "B": "''Enable traceability'' fala de CloudTrail, Config, GuardDuty — auditoria, não cifragem.",
     "C": "''Prepare for security events'' é incident response — runbooks, automação de containment."
    },
    "keyConcept": "Security — design principles (7)",
    "compareWith": [
     "Defense in depth",
     "Least privilege",
     "Encryption"
    ],
    "realWorldContext": "PCI-DSS, HIPAA e LGPD todos exigem cifragem em trânsito e repouso para dados sensíveis."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["well-architected","security","encryption"]'::jsonb, 'ai-draft', 'active', now(), now()
)
