INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-009', 'aws-clf', 'Após um incidente, a equipe percebe que não tinha logs suficientes para reconstruir quem fez o quê. Habilitar CloudTrail em todas as contas e ingerir no Security Hub é a aplicação direta de qual design principle do pilar Security?',
  '[{"id":"A","text":"Enable traceability"},{"id":"B","text":"Implement a strong identity foundation"},{"id":"C","text":"Automate security best practices"},{"id":"D","text":"Keep people away from data"}]'::jsonb, 'A',
  '{
    "summary": "''Enable traceability'' = monitor, alert, audit ações e mudanças — exatamente o que CloudTrail + Security Hub entregam.",
    "whyCorrect": "Esse princípio exige logs de ação (CloudTrail), logs de configuração (Config), detecção (GuardDuty) e agregação (Security Hub) para reconstruir eventos. Falta de logs no incidente é falha clara nesse princípio.",
    "whyWrong": {
     "B": "''Strong identity foundation'' é IAM/SSO/MFA — quem é o caller; não é sobre rastreio do que ele fez.",
     "C": "''Automate security best practices'' é IaC/automação (Security Hub auto-remediation) — relacionado mas o cenário descreve a falta de visibilidade, não de automação.",
     "D": "''Keep people away from data'' é segregação (acesso via APIs, não bastion); o cenário não trata de acesso humano direto."
    },
    "keyConcept": "Security — traceability (audit, monitor, alert)",
    "compareWith": [
     "CloudTrail (API calls)",
     "Config (resource state)",
     "GuardDuty (threats)"
    ],
    "realWorldContext": "Post-mortem típico após incidente sempre exige timeline reconstruída via CloudTrail Lake."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["well-architected","security","logging"]'::jsonb, 'ai-draft', 'active', now(), now()
)
