INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-010', 'aws-clf', 'O pilar Reliability tem o design principle ''Test recovery procedures''. Qual prática operacional é a manifestação mais fiel desse princípio?',
  '[{"id":"A","text":"Aumentar a vida útil dos backups para 7 anos"},{"id":"B","text":"Game days que injetam falhas controladas em produção/staging para validar runbooks de recuperação"},{"id":"C","text":"Mover todos os recursos para a região mais barata"},{"id":"D","text":"Adquirir Reserved Instances de 3 anos"}]'::jsonb, 'B',
  '{
    "summary": "Game days exercitam runbooks de DR em condições próximas do real — única forma de garantir que a recuperação realmente funciona.",
    "whyCorrect": "''Test recovery procedures'' diferencia ter um runbook de saber que ele funciona. Game days (chaos engineering) injetam falhas (terminar AZ, derrubar RDS, latência) e verificam se o sistema/equipe recupera no RTO acordado. Sem teste, runbook é teatro.",
    "whyWrong": {
     "A": "Reter backups por mais tempo é retenção, não teste de recuperação. Backup sem restore testado é falsa segurança.",
     "C": "Custo de região não tem relação com testar recuperação.",
     "D": "Reserved Instance é financeiro/comprometimento, não DR test."
    },
    "keyConcept": "Reliability — test recovery, chaos engineering",
    "compareWith": [
     "Game day",
     "Chaos engineering",
     "DR drill"
    ],
    "realWorldContext": "Netflix popularizou com Chaos Monkey/Simian Army; AWS oferece Fault Injection Service (FIS) para esses experimentos."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["well-architected","reliability","game-days"]'::jsonb, 'ai-draft', 'active', now(), now()
)
