INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-011', 'aws-clf', 'Uma equipe quer aplicar ''Automatically recover from failure'' (Reliability). Qual mecanismo AWS é o exemplo mais direto desse princípio?',
  '[{"id":"A","text":"AWS Budgets com alerta em 80%"},{"id":"B","text":"Trusted Advisor checks semanais"},{"id":"C","text":"EC2 Auto Recovery (substitui instância falha automaticamente, mantém IP)"},{"id":"D","text":"AWS Marketplace subscription"}]'::jsonb, 'C',
  '{
    "summary": "EC2 Auto Recovery (e Auto Scaling self-healing) substitui automaticamente instâncias falhas — recuperação sem intervenção humana.",
    "whyCorrect": "''Automatically recover from failure'' = sistema detecta falha (CloudWatch alarm), age (substitui instância, falha-over RDS) sem humano. EC2 Auto Recovery, Auto Scaling self-healing e RDS Multi-AZ failover são manifestações canônicas.",
    "whyWrong": {
     "A": "Budgets alerta sobre gasto, não recupera falha.",
     "B": "Trusted Advisor recomenda melhorias; não age automaticamente.",
     "D": "Marketplace é catálogo de software — irrelevante."
    },
    "keyConcept": "Reliability — auto-recovery / self-healing",
    "compareWith": [
     "EC2 Auto Recovery",
     "ASG health checks",
     "RDS Multi-AZ failover"
    ],
    "realWorldContext": "Health checks de ASG + ELB removem instância unhealthy do tráfego e provisionam nova em minutos."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["well-architected","reliability","auto-recovery"]'::jsonb, 'ai-draft', 'active', now(), now()
)
