INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-012', 'aws-clf', 'Qual design principle do pilar Cost Optimization é a base para a prática de tagging consistente em todos os recursos AWS?',
  '[{"id":"A","text":"Adopt a consumption model"},{"id":"B","text":"Measure overall efficiency"},{"id":"C","text":"Stop spending money on undifferentiated heavy lifting"},{"id":"D","text":"Analyze and attribute expenditure"}]'::jsonb, 'D',
  '{
    "summary": "''Analyze and attribute expenditure'' exige saber quem/qual workload gera cada custo — tags são o mecanismo.",
    "whyCorrect": "Sem tags consistentes (Environment, CostCenter, Project, Owner), o Cost and Usage Report não consegue atribuir gasto a equipes/produtos. Tagging é pré-requisito desse design principle e habilita showback/chargeback (FinOps).",
    "whyWrong": {
     "A": "''Adopt a consumption model'' = pay-as-you-go vs comprar capacidade. Tagging não é o mecanismo desse princípio.",
     "B": "''Measure overall efficiency'' = output de negócio / custo (ex: USD por pedido). Tags ajudam mas o princípio é a métrica, não o tag em si.",
     "C": "''Stop spending on undifferentiated heavy lifting'' = usar managed services em vez de operar infra própria. Não é tagging."
    },
    "keyConcept": "Cost Optimization — cost allocation tags",
    "compareWith": [
     "AWS Cost Categories",
     "Cost Allocation Tags",
     "AWS Budgets per tag"
    ],
    "realWorldContext": "Empresas com 50+ contas usam SCPs para enforce de tags obrigatórios (tag policies em Organizations).",
    "tutorSeeds": [
     "Como ativar cost allocation tags no Billing console?",
     "Qual a diferença entre AWS-generated tags e user-defined tags?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["well-architected","cost-optimization","tagging"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
