INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-013', 'aws-clf', 'O design principle ''Adopt a consumption model'' (Cost Optimization) implica diretamente em qual mudança de pensamento?',
  '[{"id":"A","text":"Pagar apenas pelos recursos efetivamente consumidos, desligando-os quando não usados"},{"id":"B","text":"Comprar capacidade pico antecipada para evitar throttling"},{"id":"C","text":"Substituir todos os recursos por Reserved Instances de 3 anos"},{"id":"D","text":"Manter um buffer fixo de 30% sempre provisionado"}]'::jsonb, 'A',
  '{
    "summary": "''Adopt a consumption model'' = pague pelo uso real, desligue o que não usa (dev nights/weekends, scale-down).",
    "whyCorrect": "O princípio é literalmente: ''pay only for the computing resources you require''. Implica em automação de start/stop em horários não úteis, serverless on-demand, scale-down agressivo. É a aplicação prática do pay-as-you-go.",
    "whyWrong": {
     "B": "Comprar capacidade pico é o anti-padrão do data center tradicional — contradiz ''consumption model''.",
     "C": "Reserved Instance de 3 anos é commitment-based, não consumption-based; faz sentido para baseline mas não é o princípio em si.",
     "D": "Buffer fixo de 30% é overprovisioning — gasta com capacidade ociosa."
    },
    "keyConcept": "Cost Optimization — consumption model",
    "compareWith": [
     "On-Demand vs Reserved vs Savings Plans vs Spot"
    ],
    "realWorldContext": "Lambda, Fargate, Aurora Serverless são exemplos extremos de consumption — você paga só pelo request/ms."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["well-architected","cost-optimization","consumption-model"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
