INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-014', 'aws-clf', 'Uma equipe está fazendo Well-Architected Review e identifica que o workload tem alta utilização (Sustainability), bom RTO (Reliability), mas gasta 2x mais que o necessário. Qual ferramenta AWS é mais alinhada para guiar a remediação no pilar Cost Optimization?',
  '[{"id":"A","text":"AWS GuardDuty"},{"id":"B","text":"AWS Compute Optimizer + Cost Explorer Rightsizing recommendations"},{"id":"C","text":"AWS Config Conformance Pack"},{"id":"D","text":"Amazon Inspector"}]'::jsonb, 'B',
  '{
    "summary": "Compute Optimizer + Cost Explorer Rightsizing identificam instâncias super-dimensionadas — exatamente o problema de ''gasta 2x mais''.",
    "whyCorrect": "Compute Optimizer usa ML para analisar métricas (CPU, memória, rede) e recomendar instance type/size ideal. Cost Explorer rightsizing complementa identificando instâncias ociosas. É o caminho direto para reduzir custo sem perder performance.",
    "whyWrong": {
     "A": "GuardDuty é detecção de ameaças (Security), não custo.",
     "C": "Config Conformance Pack avalia compliance de configuração — pode incluir regras de custo, mas é mais amplo e indireto.",
     "D": "Inspector é vulnerability scanning — Security, não Cost."
    },
    "keyConcept": "Cost Optimization — rightsizing tooling",
    "compareWith": [
     "Compute Optimizer",
     "Cost Explorer",
     "Trusted Advisor cost checks"
    ],
    "realWorldContext": "Empresas costumam encontrar 20-30% de economia só em rightsizing inicial."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["well-architected","cost-optimization","rightsizing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
