INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-015', 'aws-clf', 'Uma empresa com 300 aplicações on-prem está planejando migração para AWS. Avaliam que 40 apps são SaaS comerciais (Salesforce, Workday) que podem ser substituídos. Qual estratégia das 6 Rs aplica-se?',
  '[{"id":"A","text":"Rehost (lift-and-shift)"},{"id":"B","text":"Replatform (lift-tinker-and-shift)"},{"id":"C","text":"Repurchase (drop-and-shop)"},{"id":"D","text":"Refactor / Re-architect"}]'::jsonb, 'C',
  '{
    "summary": "Repurchase = trocar app on-prem por SaaS comercial equivalente (CRM próprio → Salesforce).",
    "whyCorrect": "Repurchase (também chamado ''drop-and-shop'') significa abandonar o software atual em favor de um SaaS de terceiros. CRM próprio vira Salesforce; ERP vira Workday; HR vira BambooHR. É a estratégia certa quando há SaaS maduro substituindo o legado.",
    "whyWrong": {
     "A": "Rehost = lift-and-shift, mover VM como está para EC2. Aplicaria se a empresa quisesse manter o software, só mudar de infra.",
     "B": "Replatform = pequenas otimizações na migração (Oracle on-prem → RDS for Oracle). Mantém o software, troca a infra/plataforma.",
     "D": "Refactor = reescrever para cloud-native. Aplicaria se decidissem reescrever o CRM para serverless em vez de comprar SaaS."
    },
    "keyConcept": "Migration — 6 Rs (Retire, Retain, Rehost, Relocate, Replatform, Repurchase, Refactor)",
    "compareWith": [
     "Repurchase vs Refactor",
     "Rehost vs Replatform"
    ],
    "realWorldContext": "Empresas frequentemente fazem mix: rehost 60%, replatform 25%, repurchase 10%, refactor 5%.",
    "tutorSeeds": [
     "Como o MAP (Migration Acceleration Program) financia esses movimentos?",
     "Qual a diferença entre Retire e Retain?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["migration","6rs","repurchase"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
