INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-016', 'aws-clf', 'Durante o assessment de migração, identifica-se que 15 apps são legacy (mainframe COBOL) sem uso ativo nos últimos 18 meses, mas ainda ligados. A estratégia recomendada nas 6 Rs é:',
  '[{"id":"A","text":"Retain (manter como está, revisitar no futuro)"},{"id":"B","text":"Rehost (mover para EC2 sem alteração)"},{"id":"C","text":"Refactor (reescrever em Lambda)"},{"id":"D","text":"Retire (desligar)"}]'::jsonb, 'D',
  '{
    "summary": "Retire = desligar apps sem uso real. Frequentemente 10-20% do portfólio cai aqui no assessment.",
    "whyCorrect": "Apps sem uso por 18 meses são candidatos óbvios a Retire. Migrar (qualquer ''R'') consome esforço; desligar economiza tudo. O assessment de portfolio sempre prioriza identificar Retire antes de planejar as outras estratégias.",
    "whyWrong": {
     "A": "Retain seria para apps que precisam continuar on-prem por compliance/legacy não migrável ainda — mas aqui o app não tem uso, então retain é desperdício.",
     "B": "Rehost gastaria esforço de migração para algo que ninguém usa.",
     "C": "Refactor é o maior investimento; jamais para app sem uso."
    },
    "keyConcept": "Migration — Retire vs Retain",
    "compareWith": [
     "Retire (desligar)",
     "Retain (manter sem migrar)"
    ],
    "realWorldContext": "Portfolio assessment típico (TSO Logic, Migration Evaluator) sempre destaca % de Retire potencial — economia imediata."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["migration","6rs","retire"]'::jsonb, 'ai-draft', 'active', now(), now()
)
