INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-017', 'aws-clf', 'Uma equipe usa AWS Application Migration Service (MGN) para migrar 50 VMs VMware on-prem para EC2 com mudanças mínimas. Qual das 6 Rs essa abordagem materializa?',
  '[{"id":"A","text":"Rehost (lift-and-shift)"},{"id":"B","text":"Refactor"},{"id":"C","text":"Repurchase"},{"id":"D","text":"Retire"}]'::jsonb, 'A',
  '{
    "summary": "AWS MGN replica VMs em block-level e converte em instâncias EC2 — automatiza rehost em escala.",
    "whyCorrect": "MGN (antigo CloudEndure Migration) faz replicação contínua de VMs on-prem para EC2 e permite cutover com downtime mínimo. Como mantém o SO/app inalterados, é a definição de Rehost (lift-and-shift).",
    "whyWrong": {
     "B": "Refactor exigiria reescrever o app (ex: monolito → microservices). MGN não toca o app.",
     "C": "Repurchase exigiria trocar por SaaS. MGN não compra nada novo.",
     "D": "Retire desliga; MGN migra."
    },
    "keyConcept": "Migration — MGN (Application Migration Service)",
    "compareWith": [
     "MGN (rehost)",
     "DMS (database migration)",
     "DataSync (file transfer)"
    ],
    "realWorldContext": "MGN é a ferramenta padrão de rehost em massa — usada em programas MAP grandes."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["migration","6rs","rehost","mgn"]'::jsonb, 'ai-draft', 'active', now(), now()
)
