INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-018', 'aws-clf', 'O AWS Migration Acceleration Program (MAP) é estruturado em 3 fases. A fase em que se prioriza apps, define business case e cria landing zone é:',
  '[{"id":"A","text":"Assess"},{"id":"B","text":"Mobilize"},{"id":"C","text":"Migrate \u0026 Modernize"},{"id":"D","text":"Operate"}]'::jsonb, 'B',
  '{
    "summary": "MAP tem 3 fases: Assess (avaliar prontidão), Mobilize (planejar + landing zone), Migrate & Modernize (executar).",
    "whyCorrect": "Mobilize é a fase intermediária onde se define o business case detalhado, prioriza waves de apps, cria a landing zone (Control Tower, redes, contas), capacita o time e remove blockers organizacionais. É o ''plano de batalha'' antes da migração começar.",
    "whyWrong": {
     "A": "Assess é a fase inicial — descobrir o portfólio, calcular TCO, identificar 6 Rs por app. Vem ANTES de mobilize.",
     "C": "Migrate & Modernize é a execução em waves — vem DEPOIS de mobilize.",
     "D": "Operate não é fase formal do MAP; é o estado pós-migração (BAU em cloud)."
    },
    "keyConcept": "AWS MAP — Assess / Mobilize / Migrate & Modernize",
    "compareWith": [
     "Assess (descobrir)",
     "Mobilize (planejar)",
     "Migrate (executar)"
    ],
    "realWorldContext": "MAP fornece créditos AWS e Professional Services para reduzir custo da migração em troca de commitment de gasto pós-migração."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["migration","map","phases"]'::jsonb, 'ai-draft', 'active', now(), now()
)
