INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-019', 'aws-clf', 'Uma empresa quer agrupar e visualizar o progresso de migração de centenas de servidores em waves. Qual serviço AWS é desenhado especificamente para isso?',
  '[{"id":"A","text":"AWS Systems Manager"},{"id":"B","text":"AWS Trusted Advisor"},{"id":"C","text":"AWS Migration Hub"},{"id":"D","text":"AWS CloudFormation StackSets"}]'::jsonb, 'C',
  '{
    "summary": "Migration Hub é o painel único para acompanhar progresso de migração através de MGN, DMS, Application Discovery Service.",
    "whyCorrect": "Migration Hub agrega dados de discovery, tracking de waves, status de cada server/app, e integra com MGN, DMS e parceiros. É o ''mission control'' de migração — desenhado exatamente para o cenário descrito.",
    "whyWrong": {
     "A": "Systems Manager é gestão operacional de fleet (patching, Run Command, Parameter Store) — pós-migração, não para tracking de migração.",
     "B": "Trusted Advisor faz checks de best practices em conta — não trata de migração.",
     "D": "StackSets é deploy multi-account de CFN templates — útil para landing zone, não para tracking."
    },
    "keyConcept": "Migration Hub — visualização unificada",
    "compareWith": [
     "Migration Hub (tracking)",
     "MGN (execução)",
     "ADS (discovery)"
    ],
    "realWorldContext": "Em programas MAP grandes (1000+ servers), Migration Hub é onde o CIO acompanha % de waves concluídas semanalmente."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["migration","migration-hub"]'::jsonb, 'ai-draft', 'active', now(), now()
