INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-020', 'aws-clf', 'Uma empresa quer migrar Oracle on-prem para Aurora PostgreSQL na AWS. Qual combinação correta de estratégia (6 Rs) + serviço de migração?',
  '[{"id":"A","text":"Rehost + MGN"},{"id":"B","text":"Repurchase + AWS Marketplace"},{"id":"C","text":"Retire + AWS Backup"},{"id":"D","text":"Refactor + AWS Schema Conversion Tool (SCT) + Database Migration Service (DMS)"}]'::jsonb, 'D',
  '{
    "summary": "Trocar engine de Oracle para PostgreSQL exige refactor de schema/PL-SQL e migração de dados — SCT + DMS é o caminho canônico.",
    "whyCorrect": "Mudar de Oracle para Aurora PostgreSQL muda a engine (SQL dialect, stored procedures, tipos) — isso é Refactor (não Replatform que mantém engine). SCT converte schema e código PL/SQL para PL/pgSQL; DMS replica dados continuamente até cutover.",
    "whyWrong": {
     "A": "Rehost manteria Oracle (rodando em EC2). Não cobre a mudança de engine para PostgreSQL.",
     "B": "Repurchase seria trocar por SaaS comercial (ex: trocar CRM por Salesforce). Não se aplica a database engine swap.",
     "C": "Retire desliga; o cenário quer manter o sistema, só trocar o backend de DB."
    },
    "keyConcept": "Migration — heterogeneous DB migration (SCT + DMS)",
    "compareWith": [
     "Replatform (Oracle → RDS for Oracle)",
     "Refactor (Oracle → Aurora PostgreSQL)"
    ],
    "realWorldContext": "Movimento clássico de empresas fugindo de licenças Oracle — economia significativa de licensing.",
    "tutorSeeds": [
     "Por que mudar engine é Refactor e não Replatform?",
     "Como DMS faz CDC (change data capture)?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["migration","refactor","dms","sct"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
