INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-021', 'aws-clf', 'Uma empresa avalia TCO (Total Cost of Ownership) de manter on-prem vs migrar para AWS. Qual componente é tipicamente subestimado no on-prem ao comparar com AWS pay-as-you-go?',
  '[{"id":"A","text":"Custo de energia, refrigeração, espaço de rack, segurança física e equipe de operação 24x7"},{"id":"B","text":"Custo das licenças de software"},{"id":"C","text":"Custo dos servidores físicos"},{"id":"D","text":"Custo da internet corporativa"}]'::jsonb, 'A',
  '{
    "summary": "Os ''custos invisíveis'' (energia, refrigeração, espaço, equipe de ops) são os mais subestimados no TCO on-prem.",
    "whyCorrect": "Hardware é fácil de contabilizar (nota fiscal). Já energia (kWh), refrigeração (HVAC), espaço físico (m² ou rack-units), segurança física, e principalmente headcount de operação 24x7 (sysadmin, network engineer, DC tech) somam frequentemente 2-3x o valor do hardware ao longo do ciclo de vida. AWS embute tudo isso no preço por hora.",
    "whyWrong": {
     "B": "Licenças de software são tipicamente bem contabilizadas porque vêm em contratos anuais visíveis ao financeiro.",
     "C": "Servidores físicos são item de imobilizado registrado contabilmente — visível.",
     "D": "Internet corporativa é OpEx mensal recorrente, geralmente bem tracked."
    },
    "keyConcept": "TCO — custos diretos vs indiretos",
    "compareWith": [
     "TCO (total cost)",
     "ROI (retorno do investimento)"
    ],
    "realWorldContext": "AWS Pricing Calculator e Migration Evaluator ajudam a quantificar esses custos invisíveis para business case.",
    "tutorSeeds": [
     "Qual a diferença entre TCO e ROI?",
     "Como o Migration Evaluator coleta dados on-prem?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["pricing","tco","on-prem"]'::jsonb, 'ai-draft', 'active', now(), now()
)
