INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-022', 'aws-clf', 'Qual a diferença prática mais importante entre Reserved Instances (RI) e Savings Plans (SP)?',
  '[{"id":"A","text":"RI é mais barato em 100% dos casos"},{"id":"B","text":"RI é commitment a tipo/family específicos de instância; Savings Plans (Compute) é commitment em $/hora flexível através de family, size, region e até serviço (EC2/Fargate/Lambda)"},{"id":"C","text":"Savings Plans só funciona em sa-east-1"},{"id":"D","text":"RI exige upfront total obrigatório; SP nunca exige upfront"}]'::jsonb, 'B',
  '{
    "summary": "Compute Savings Plans dá flexibilidade que RI clássicas não dão — mesmo desconto, sem amarração a instance type.",
    "whyCorrect": "Standard RI compromete você com instance family + region (e às vezes size). Compute Savings Plans compromete em $/hora gasto em compute, e o desconto aplica automaticamente em EC2 (qualquer family/size/region), Fargate e Lambda. É commitment financeiro, não técnico — daí flexibilidade superior.",
    "whyWrong": {
     "A": "RI Standard tem desconto ligeiramente maior (~72%) que Compute SP (~66%) em troca da rigidez. ''Mais barato em 100% dos casos'' é falso e ignora o trade-off.",
     "C": "Savings Plans funciona em todas as regiões.",
     "D": "Ambos oferecem 3 opções: All Upfront, Partial Upfront, No Upfront. Não é um critério distintivo."
    },
    "keyConcept": "Pricing — commitment-based discounts",
    "compareWith": [
     "Standard RI",
     "Convertible RI",
     "Compute SP",
     "EC2 Instance SP"
    ],
    "realWorldContext": "Recomendação atual da AWS: Savings Plans é o default por flexibilidade; RI permanece para casos específicos (ex: RDS reservations não existem como SP)."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'best-practice', '["pricing","ri","savings-plans"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
