INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-023', 'aws-clf', 'Spot Instances oferecem até 90% de desconto vs On-Demand. Qual workload é o caso de uso INCORRETO para Spot?',
  '[{"id":"A","text":"Batch processing tolerante a interrupção (ETL noturno, ML training com checkpointing)"},{"id":"B","text":"Renderização de vídeo em fleet de instâncias paralelas"},{"id":"C","text":"Banco de dados de produção single-instance hospedando estado crítico"},{"id":"D","text":"CI/CD runners stateless"}]'::jsonb, 'C',
  '{
    "summary": "Spot pode ser interrompida com 2 min de aviso — inviável para banco de dados stateful single-instance.",
    "whyCorrect": "Banco de dados de produção single-instance perderia conexões, transações in-flight e potencialmente dados se interrompido. Spot é desenhado para workloads tolerantes a interrupção, sem estado crítico local. Database stateful é o anti-padrão.",
    "whyWrong": {
     "A": "Batch tolerante a interrupção com checkpointing é o caso de uso canônico de Spot — perdeu instância, retoma do último checkpoint.",
     "B": "Renderização em fleet stateless é ideal para Spot — perde um frame, refaz; cada nó é independente.",
     "D": "CI/CD runners stateless são perfeitos — se interrompido, job é retomado em outro runner."
    },
    "keyConcept": "Spot — workloads tolerantes a interrupção",
    "compareWith": [
     "Spot (interrompível)",
     "On-Demand (estável)",
     "Reserved (commitment)"
    ],
    "realWorldContext": "Empresas como Pinterest e Lyft rodam grande parte do ML training em Spot Fleet com economia de 60-80%."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["pricing","spot","interruption"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
