INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-024', 'aws-clf', 'O conceito ''Right Sizing'' no AWS Cost Optimization Hub refere-se primariamente a:',
  '[{"id":"A","text":"Aumentar instâncias para evitar throttling"},{"id":"B","text":"Mudar todas as instâncias para o maior tipo disponível"},{"id":"C","text":"Apagar instâncias antigas após 1 ano"},{"id":"D","text":"Ajustar tipo/tamanho de instância ao perfil real de uso (CPU/memória) — frequentemente reduzir de m5.2xlarge para m5.xlarge"}]'::jsonb, 'D',
  '{
    "summary": "Right sizing = casar tipo/tamanho de instância ao uso real, geralmente reduzindo para evitar desperdício.",
    "whyCorrect": "Right sizing analisa métricas (CPU médio < 20%, memória < 30%) e recomenda instância menor ou family diferente (ex: compute-heavy → general purpose). É a primeira otimização de custo recomendada — frequentemente 20-30% de economia imediata.",
    "whyWrong": {
     "A": "''Aumentar para evitar throttling'' é resposta a problema de performance, não right sizing. Right sizing pode aumentar OU reduzir, mas com base em dados.",
     "B": "Mudar tudo para o maior tipo é over-provisioning extremo — oposto de right sizing.",
     "C": "Apagar instâncias antigas é cleanup; right sizing ajusta dimensão de instâncias ativas."
    },
    "keyConcept": "Cost Optimization — right sizing",
    "compareWith": [
     "Right sizing",
     "Scheduling (stop/start)",
     "Spot conversion"
    ],
    "realWorldContext": "Compute Optimizer e Cost Explorer Rightsizing Recommendations são as ferramentas nativas."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["pricing","rightsizing","cost-optimization-hub"]'::jsonb, 'ai-draft', 'active', now(), now()
)
