INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-025', 'aws-clf', 'Uma equipe quer estimar o custo de uma arquitetura ANTES de provisionar (estimativa para business case). Qual ferramenta é a correta?',
  '[{"id":"A","text":"AWS Pricing Calculator"},{"id":"B","text":"AWS Cost Explorer"},{"id":"C","text":"AWS Budgets"},{"id":"D","text":"Cost and Usage Report (CUR)"}]'::jsonb, 'A',
  '{
    "summary": "Pricing Calculator é PRÉ-provisionamento (estimativa); as outras ferramentas são PÓS (consumo real).",
    "whyCorrect": "Pricing Calculator permite montar uma arquitetura virtual (10 EC2 m5.large + RDS db.m5.xlarge + 500GB S3...) e calcular custo mensal estimado. É a ferramenta para business case, RFPs, comparação de cenários — antes de gastar 1 centavo.",
    "whyWrong": {
     "B": "Cost Explorer analisa gasto histórico e tendências — só funciona com consumo real já gerado.",
     "C": "Budgets define limites e alertas sobre consumo real — não estima.",
     "D": "CUR é o arquivo detalhado de consumo real (por hora, por recurso) — também post-fact."
    },
    "keyConcept": "Pricing tooling — pre-provisioning vs post-consumption",
    "compareWith": [
     "Pricing Calculator (estimar)",
     "Cost Explorer (analisar)",
     "Budgets (controlar)"
    ],
    "realWorldContext": "Toda proposta comercial de migração AWS começa com Pricing Calculator para gerar TCO comparativo."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["pricing","calculator"]'::jsonb, 'ai-draft', 'active', now(), now()
)
