INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-026', 'aws-clf', 'O AWS Cost Optimization Hub (lançado em 2023) tem qual propósito diferenciado em relação ao Cost Explorer?',
  '[{"id":"A","text":"Substitui o billing console"},{"id":"B","text":"Consolida recomendações de economia (rightsizing, idle, savings plans, graviton) de várias ferramentas AWS num único console, com priorização e potencial de economia quantificado"},{"id":"C","text":"Faz pagamento automático da fatura"},{"id":"D","text":"É um marketplace de cursos de finanças"}]'::jsonb, 'B',
  '{
