INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-027', 'aws-clf', 'Qual a diferença correta entre TCO e ROI no contexto de migração para nuvem?',
  '[{"id":"A","text":"São sinônimos"},{"id":"B","text":"TCO mede latência; ROI mede throughput"},{"id":"C","text":"TCO mede o custo total acumulado de uma solução ao longo do tempo; ROI mede o retorno (benefício / investimento) gerado pela mesma solução"},{"id":"D","text":"TCO mede uptime; ROI mede MTTR"}]'::jsonb, 'C',
  '{
    "summary": "TCO = custo total. ROI = (ganho - custo) / custo. TCO é input do cálculo de ROI.",
    "whyCorrect": "TCO soma todos os custos (hardware, software, energia, pessoal, manutenção) ao longo de um período. ROI compara o benefício gerado (receita adicional, custo evitado, produtividade) contra o investimento. Migrar para AWS pode reduzir TCO E aumentar ROI ao mesmo tempo.",
    "whyWrong": {
     "A": "São complementares mas distintos.",
     "B": "Latência/throughput são métricas de performance, não financeiras.",
     "D": "Uptime/MTTR são métricas de reliability, não financeiras."
    },
    "keyConcept": "Financial — TCO vs ROI",
    "compareWith": [
     "TCO (total cost)",
     "ROI (return on investment)",
     "Payback period"
    ],
    "realWorldContext": "Business case típico mostra: ''AWS reduz TCO em 30% E acelera time-to-market em 50% → ROI positivo em 18 meses''."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["pricing","tco","roi"]'::jsonb, 'ai-draft', 'active', now(), now()
)
