INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-029', 'aws-clf', 'FinOps tem 3 princípios fundamentais. Qual reflete corretamente um deles aplicado em AWS?',
  '[{"id":"A","text":"Todos da empresa participam: engenharia, finanças e negócio colaboram em decisões de custo (não só finance dita)"},{"id":"B","text":"Apenas o time financeiro decide gastos de cloud"},{"id":"C","text":"Engenharia não deve ver dados de custo"},{"id":"D","text":"Cloud é gratuito por padrão"}]'::jsonb, 'A',
  '{
    "summary": "FinOps é cultura cross-funcional: engenheiros veem custo do que constroem, finanças entende cloud, negócio vê ROI por feature.",
    "whyCorrect": "Princípio FinOps Foundation: ''Teams need to collaborate''. Engenharia, finanças e produto compartilham dashboards de custo, definem KPIs juntos (USD por pedido, custo por cliente). Sem isso, finanças reclama de fatura e engenharia ignora.",
    "whyWrong": {
     "B": "Anti-padrão FinOps clássico — finance dita sem entender cloud, engenharia ignora sem ver impacto.",
     "C": "FinOps prega o contrário: ''tornar custo visível para quem decide'' (engenheiros que provisionam).",
     "D": "Cloud cobra por uso; afirmação falsa."
    },
    "keyConcept": "FinOps — collaboration, ownership, real-time decisions",
    "compareWith": [
     "FinOps",
     "Cloud Financial Management (AWS)"
    ],
    "realWorldContext": "Empresas maduras têm ''FinOps practitioner'' role e cost dashboards expostos em times de engenharia.",
    "tutorSeeds": [
     "Quais são as 3 fases do FinOps lifecycle (Inform/Optimize/Operate)?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["finops","cloud-financial-management"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
