INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-030', 'aws-clf', 'Qual é a diferença entre showback e chargeback em cloud financial management?',
  '[{"id":"A","text":"São sinônimos exatos"},{"id":"B","text":"Showback mostra custo atribuído por equipe/produto sem cobrança interna; chargeback efetivamente debita o orçamento do business unit consumidor"},{"id":"C","text":"Showback é cobrar 2x; chargeback é cobrar 1x"},{"id":"D","text":"Showback é privado; chargeback é público na internet"}]'::jsonb, 'B',
  '{
    "summary": "Showback informa sem cobrar; chargeback transfere o custo para o orçamento da BU consumidora.",
    "whyCorrect": "Showback é o estágio inicial: o time vê ''você consumiu USD 12k este mês'' mas o pagamento sai do orçamento central de TI. Chargeback evolui isso: o orçamento da BU é efetivamente debitado, criando pressão real de otimização. Empresas costumam começar em showback e migrar para chargeback conforme maturidade.",
    "whyWrong": {
     "A": "São conceitualmente diferentes — show vs charge.",
     "C": "Não tem nada a ver com cobrar 2x.",
     "D": "Não é sobre privacidade da informação."
    },
    "keyConcept": "FinOps — showback vs chargeback",
    "compareWith": [
     "Showback (visibility)",
     "Chargeback (financial accountability)"
    ],
    "realWorldContext": "Cost Allocation Tags + Cost Categories permitem implementar tanto showback quanto chargeback baseado em tags por BU/projeto."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["finops","showback","chargeback"]'::jsonb, 'ai-draft', 'active', now(), now()
)
