INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-031', 'aws-clf', 'Uma empresa quer implementar tagging strategy robusta. Qual prática é a mais aderente aos princípios de cloud financial management?',
  '[{"id":"A","text":"Cada engenheiro escolhe livremente seus próprios tags"},{"id":"B","text":"Nenhum tag — agrupar tudo manualmente no Excel"},{"id":"C","text":"Tags obrigatórios enforced via Tag Policies (Organizations) + SCP que nega criação de recursos sem tags requeridas (Environment, CostCenter, Owner)"},{"id":"D","text":"Apenas tagear instâncias EC2; demais serviços não precisam"}]'::jsonb, 'C',
  '{
    "summary": "Tagging requer enforcement automático (Tag Policies + SCP), não confiança em disciplina manual.",
    "whyCorrect": "Tag Policies definem schema (chaves válidas + valores permitidos); SCP em Organizations pode negar criação de recurso sem tags requeridas (ec2:RunInstances com condition aws:RequestTag/Environment). Combinação garante 100% de cobertura — sem isso, tagging vira esforço fútil.",
    "whyWrong": {
     "A": "Tags livres geram caos: ''env=prod'' vs ''Environment=production'' vs ''ENV=PROD'' tornam relatórios inúteis.",
     "B": "Não tagear inviabiliza atribuição de custo — anti-padrão absoluto.",
     "D": "Restringir a EC2 deixa lacunas enormes (S3, Lambda, RDS, DynamoDB)."
    },
    "keyConcept": "Tagging governance — enforce + standardize",
    "compareWith": [
     "Tag Policies",
     "SCP",
     "AWS Config rules (tag compliance)"
    ],
    "realWorldContext": "Tag spread (variações de chave/valor) é o problema #1 de FinOps em empresas grandes."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["finops","tagging","governance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
