INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-032', 'aws-clf', 'Cost Categories no AWS Cost Management servem para:',
  '[{"id":"A","text":"Substituir o conceito de conta AWS"},{"id":"B","text":"Aplicar descontos automáticos"},{"id":"C","text":"Mover instâncias entre regiões"},{"id":"D","text":"Agrupar dimensões de custo (contas, serviços, tags) em categorias lógicas customizadas (ex: ''Plataforma Pagamentos'', ''Marketing Stack'') para reports e Budgets"}]'::jsonb, 'D',
  '{
    "summary": "Cost Categories cria dimensões lógicas próprias para enxergar custo de jeitos que não dependem de hierarquia de contas/serviço.",
    "whyCorrect": "Cost Categories permite definir regras (ex: ''se conta = X OU tag Product = checkout, então categoria = Pagamentos'') e usar essa categoria em Cost Explorer, Budgets e CUR. Resolve casos em que a estrutura organizacional não bate com a hierarquia de contas AWS.",
    "whyWrong": {
     "A": "Não substitui conta — é camada lógica sobre contas e tags.",
     "B": "Não aplica desconto — apenas agrupa custo.",
     "C": "Não move recursos."
    },
    "keyConcept": "Cost Categories — lógicas custom de agrupamento",
    "compareWith": [
     "Cost Allocation Tags",
     "Cost Categories",
     "Organizational Units"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["finops","cost-categories"]'::jsonb, 'ai-draft', 'active', now(), now()
)
