INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-033', 'aws-clf', 'Uma empresa precisa ter dados de cidadãos UE armazenados fisicamente no continente europeu por GDPR. Qual critério de seleção de Region é mais relevante?',
  '[{"id":"A","text":"Compliance \u0026 data residency — escolher região europeia (eu-central-1, eu-west-1, etc.) que ofereça residência de dados"},{"id":"B","text":"Escolher a região mais barata globalmente"},{"id":"C","text":"Escolher a região com mais serviços em GA"},{"id":"D","text":"Escolher a região mais recente lançada"}]'::jsonb, 'A',
  '{
    "summary": "GDPR/LGPD/data residency dominam a decisão quando há requisito legal.",
    "whyCorrect": "Region selection tem 5 fatores: latência, custo, compliance, features disponíveis, sustainability. Em casos de regulação (GDPR), compliance/data residency é hard constraint — outros fatores são secundários. Dados em região UE são pré-requisito legal.",
    "whyWrong": {
     "B": "Custo é fator, mas não passa por cima de obrigação legal.",
     "C": "Disponibilidade de serviços importa para arquitetura, não para residência.",
     "D": "Idade da região é irrelevante; algumas regiões antigas são as melhores escolhas."
    },
    "keyConcept": "Region selection — 5 fatores",
    "compareWith": [
     "Latência",
     "Custo",
     "Compliance",
     "Features",
     "Sustainability"
    ],
    "realWorldContext": "Empresas SaaS oferecem ''EU-only deployment'' como SKU separado para clientes regulados."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["global-infrastructure","region-selection","compliance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
