INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-034', 'aws-clf', 'Qual é a diferença correta entre Availability Zone (AZ), Local Zone (LZ) e Wavelength Zone (WL)?',
  '[{"id":"A","text":"Todos são sinônimos"},{"id":"B","text":"AZ = data center isolado dentro de uma região (sub-ms entre AZs); LZ = extensão metropolitana para latência ultra-baixa em metrópoles (sub-10ms ao usuário); WL = AZ embutido na rede 5G de telecoms (ultra-baixa latência mobile)"},{"id":"C","text":"AZ é em satélite; LZ é submarino; WL é em terra"},{"id":"D","text":"AZ é só compute; LZ é só storage; WL é só database"}]'::jsonb, 'B',
  '{
    "summary": "AZ é o tijolo base regional; LZ aproxima compute/storage de metrópoles; WL coloca compute dentro da rede 5G.",
    "whyCorrect": "Cada uma resolve um problema de latência diferente. AZ = isolamento de falha + sub-ms para HA intra-region. LZ (ex: LA, Boston, Miami) = colocar compute/storage perto de usuário em cidade sem região (sub-10ms). WL = compute integrada à rede 5G da Verizon/Vodafone/KDDI — ideal para AR/VR mobile, gaming low-latency.",
    "whyWrong": {
     "A": "São conceitos distintos com propósitos distintos.",
     "C": "Nenhum é satélite/submarino — todos são infra terrestre.",
     "D": "Todos oferecem compute + storage (não exclusivos por serviço)."
    },
    "keyConcept": "Global Infrastructure — AZ vs LZ vs WL",
    "compareWith": [
     "AZ (sub-ms intra-region)",
     "LZ (sub-10ms metro)",
     "WL (5G mobile)"
    ],
    "realWorldContext": "Netflix/Disney usam LZ para reduzir latência em mercados sem região; gaming usa WL via parceria com operadoras 5G."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["global-infrastructure","az","local-zones","wavelength"]'::jsonb, 'ai-draft', 'active', now(), now()
)
