INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-035', 'aws-clf', 'AWS Outposts entrega:',
  '[{"id":"A","text":"Backup grátis ilimitado"},{"id":"B","text":"Cluster de Kubernetes gratuito"},{"id":"C","text":"Hardware AWS gerenciado dentro do data center do cliente (on-prem), permitindo rodar serviços AWS (EC2, EBS, RDS) localmente com a mesma API/consistência da cloud"},{"id":"D","text":"VPN automática para todos"}]'::jsonb, 'C',
  '{
    "summary": "Outposts é hardware AWS instalado no DC do cliente — cloud APIs operando on-prem para baixa latência ou data residency local.",
    "whyCorrect": "Outposts vem como rack(s) entregue(s) e instalado(s) pela AWS no DC do cliente. Você usa as mesmas APIs (EC2, EBS, S3 on Outposts, RDS) que na cloud, controlado pelo control plane regional. Casos típicos: latência sub-ms a sistemas legados, data residency super-estrita (sem internet permitida).",
    "whyWrong": {
     "A": "Outposts não é backup nem gratuito — tem custo recorrente significativo.",
     "B": "EKS pode rodar em Outposts, mas Outposts não é ''Kubernetes grátis''.",
     "D": "Não é serviço de VPN."
    },
    "keyConcept": "Hybrid — Outposts (AWS no on-prem)",
    "compareWith": [
     "Outposts (hardware on-prem)",
     "Wavelength (5G)",
     "Local Zones (metro)"
    ],
    "realWorldContext": "Hospitais, plantas industriais e exchanges financeiras usam Outposts quando latência ou compliance proíbem ir para Region."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["global-infrastructure","outposts","hybrid"]'::jsonb, 'ai-draft', 'active', now(), now()
)
