INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-036', 'aws-clf', 'Qual é a diferença prática entre Outposts e Wavelength?',
  '[{"id":"A","text":"Outposts é só em satélite; Wavelength é em terra"},{"id":"B","text":"Outposts é gratuito; Wavelength cobra USD 1/mês"},{"id":"C","text":"Outposts é só para banco; Wavelength é só para varejo"},{"id":"D","text":"Outposts vive dentro do DC do cliente; Wavelength vive dentro do data center da operadora de telecom 5G, otimizado para aplicações mobile com latência ultra-baixa"}]'::jsonb, 'D',
  '{
    "summary": "Outposts vai no DC do cliente; Wavelength vai no DC da operadora 5G (Verizon, Vodafone, etc.).",
    "whyCorrect": "Ambos são extensões da AWS, mas localizações distintas: Outposts atende cenários on-prem (latência a sistemas locais, residência de dados); Wavelength atende mobile/5G (apps em smartphones precisam de latência sub-10ms ao backend — colocar backend dentro da rede 5G da operadora elimina hops).",
    "whyWrong": {
     "A": "Nenhum é satélite — Outposts e WL são instalações físicas terrestres.",
     "B": "Ambos têm custo; nenhum é gratuito.",
     "C": "Não há restrição por setor."
    },
    "keyConcept": "Outposts vs Wavelength — local of placement",
    "compareWith": [
     "Outposts (customer DC)",
     "Wavelength (telco DC)"
    ],
    "realWorldContext": "AR/VR mobile, gaming online e edge AI mobile são casos típicos de Wavelength."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["global-infrastructure","outposts","wavelength"]'::jsonb, 'ai-draft', 'active', now(), now()
)
