INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-037', 'aws-clf', 'AWS Local Zones (ex: us-west-2-lax-1a em Los Angeles) são úteis principalmente quando:',
  '[{"id":"A","text":"O usuário final está numa metrópole sem Region completa próxima e precisa latência sub-10ms a serviços de compute/storage (ex: media editing, real-time gaming, ML inference local)"},{"id":"B","text":"Precisa de backup off-site barato"},{"id":"C","text":"Quer rodar batch noturno barato"},{"id":"D","text":"Precisa de auto-scaling tradicional"}]'::jsonb, 'A',
  '{
    "summary": "Local Zone aproxima compute/storage ao usuário urbano, alcançando sub-10ms onde a Region mais próxima ficaria a 30-50ms.",
    "whyCorrect": "Local Zones existem em cidades como LA, Boston, Miami, Houston, etc. Cada uma é como uma extensão da region pai (us-west-2 para LAX). Ideal para workloads sensíveis a latência local: edição de vídeo colaborativa, gaming, ML inference em dispositivos da metrópole.",
    "whyWrong": {
     "B": "Backup off-site é caso de S3 cross-region ou Glacier — LZ é caro para isso.",
     "C": "Batch noturno é insensível a latência — usar Region é mais barato.",
     "D": "Auto-scaling funciona em Region; não é diferencial da LZ."
    },
    "keyConcept": "Local Zones — latência metro",
    "compareWith": [
     "AZ (intra-region)",
     "Local Zone (metro)",
     "Wavelength (5G)"
    ],
    "realWorldContext": "Estúdios em Hollywood usam us-west-2-lax para edição de vídeo colaborativa em tempo real."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["global-infrastructure","local-zones"]'::jsonb, 'ai-draft', 'active', now(), now()
)
