INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-038', 'aws-clf', 'Quantas Availability Zones, no mínimo, cada AWS Region tem?',
  '[{"id":"A","text":"1 AZ por Region"},{"id":"B","text":"3 AZs isoladas fisicamente (geralmente, mínimo de 3 para resiliência)"},{"id":"C","text":"100 AZs por Region"},{"id":"D","text":"AZs são opcionais e podem não existir"}]'::jsonb, 'B',
  '{
    "summary": "Cada Region AWS tem no mínimo 3 AZs isoladas (algumas têm 6+).",
    "whyCorrect": "AWS exige mínimo de 3 AZs por Region para viabilizar quorum-based replication (databases distribuídos), HA real e tolerância a falha de AZ inteira. Algumas Regions (us-east-1, eu-west-1) têm 6+ AZs.",
    "whyWrong": {
     "A": "1 AZ por Region seria SPOF — não é o design AWS.",
     "C": "Nenhuma Region tem 100 AZs; é número exagerado.",
     "D": "AZs são o tijolo fundamental — sempre existem."
    },
    "keyConcept": "Global Infrastructure — AZ count per Region",
    "compareWith": [
     "3 AZs (mínimo)",
     "Multi-AZ services (RDS, ELB)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["global-infrastructure","az"]'::jsonb, 'ai-draft', 'active', now(), now()
)
