INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-039', 'aws-clf', 'Edge Locations (CloudFront PoPs) servem para:',
  '[{"id":"A","text":"Hospedar bancos de dados primários"},{"id":"B","text":"Rodar workloads de ML training"},{"id":"C","text":"Cache de conteúdo e terminação TLS próximos ao usuário final, melhorando latência e reduzindo carga em origem"},{"id":"D","text":"Substituir AZs"}]'::jsonb, 'C',
  '{
    "summary": "Edge Locations são PoPs do CloudFront/Route 53/Global Accelerator — caching + DNS + entrada de tráfego perto do usuário.",
    "whyCorrect": "Edge Locations existem em 400+ cidades; CloudFront usa para servir conteúdo cacheado (imagens, vídeos, JS, JSON) próximos ao usuário. Beneficia latência (primeira resposta) e custo (menos egress da origem).",
    "whyWrong": {
     "A": "Bancos primários ficam em Region (RDS, Aurora) — edge não tem capacidade nem propósito.",
     "B": "ML training pesado roda em GPU clusters em Region, não no edge.",
     "D": "Edge complementa AZs/Regions, não substitui."
    },
    "keyConcept": "Edge Locations — CloudFront PoPs",
    "compareWith": [
     "Region",
     "AZ",
     "Edge Location"
    ],
    "realWorldContext": "Streaming (Netflix, Prime Video) e e-commerce dependem fortemente do edge para reduzir TTFB."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["global-infrastructure","edge","cloudfront"]'::jsonb, 'ai-draft', 'active', now(), now()
)
