INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-040', 'aws-clf', 'Uma empresa quer entender ''cloud computing service models''. Qual exemplo NÃO é representativo de PaaS (Platform as a Service) em AWS?',
  '[{"id":"A","text":"AWS Elastic Beanstalk"},{"id":"B","text":"AWS App Runner"},{"id":"C","text":"AWS Lambda (na visão broad de PaaS / FaaS)"},{"id":"D","text":"Amazon EC2"}]'::jsonb, 'D',
  '{
    "summary": "EC2 é IaaS clássico (instância de VM crua); Beanstalk/App Runner/Lambda são PaaS (deploy de código, AWS gerencia o resto).",
    "whyCorrect": "EC2 expõe a VM diretamente — você gerencia SO, patching, runtime, scaling. É o exemplo canônico de IaaS na AWS. PaaS, por contraste, esconde o SO/runtime e foca em deploy de aplicação (Beanstalk faz isso para apps web; App Runner para containers; Lambda para funções).",
    "whyWrong": {
     "A": "Beanstalk é PaaS — você faz upload do código (Java, Python, Node) e ele provisiona EC2+ELB+ASG por baixo. Exemplo válido.",
     "B": "App Runner é PaaS para containers — você dá imagem, AWS gerencia tudo (rede, scaling, deploy).",
     "C": "Lambda é frequentemente classificado como FaaS (subconjunto de PaaS na taxonomia ampla); válido como exemplo de ''gerenciado pela plataforma''."
    },
    "keyConcept": "Cloud service models — IaaS vs PaaS vs SaaS",
    "compareWith": [
     "EC2 (IaaS)",
     "Beanstalk/App Runner/Lambda (PaaS)",
     "WorkMail/Connect (SaaS)"
    ],
    "realWorldContext": "Decisão típica: usar Beanstalk para acelerar deploy vs EC2 puro para controle granular."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["service-models","iaas","paas"]'::jsonb, 'ai-draft', 'active', now(), now()
)
