INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-041', 'aws-clf', 'Qual exemplo de SaaS em AWS é correto?',
  '[{"id":"A","text":"Amazon WorkMail e Amazon Chime — software de produtividade entregue como serviço, sem você gerenciar infra"},{"id":"B","text":"Amazon EC2"},{"id":"C","text":"AWS Lambda"},{"id":"D","text":"Amazon VPC"}]'::jsonb, 'A',
  '{
    "summary": "WorkMail (email) e Chime (videoconferência) são software finais — o usuário consome o app, AWS gerencia tudo embaixo.",
    "whyCorrect": "SaaS = software pronto para uso final, sem provisionar infra/runtime/deployment. WorkMail e Chime se enquadram (concorrem com Gmail/Zoom). Connect (call center) também é exemplo.",
    "whyWrong": {
     "B": "EC2 é IaaS — você administra VM.",
     "C": "Lambda é PaaS/FaaS — você administra código.",
     "D": "VPC é IaaS de rede — infra crua."
    },
    "keyConcept": "Cloud service models — SaaS",
    "compareWith": [
     "WorkMail/Chime/Connect (SaaS)",
     "Beanstalk (PaaS)",
     "EC2 (IaaS)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["service-models","saas"]'::jsonb, 'ai-draft', 'active', now(), now()
)
