INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-042', 'aws-clf', 'Migrando de on-prem para IaaS na AWS, qual responsabilidade do cliente é a maior área de mudança comparada a SaaS?',
  '[{"id":"A","text":"IaaS e SaaS têm o mesmo modelo de responsabilidade"},{"id":"B","text":"Em IaaS o cliente ainda gerencia SO, patching, runtime, app, dados; em SaaS o cliente só gerencia configuração e dados próprios"},{"id":"C","text":"Em IaaS a AWS gerencia tudo até o app"},{"id":"D","text":"Em SaaS o cliente gerencia o kernel"}]'::jsonb, 'B',
  '{
    "summary": "Quanto mais ''as a Service'', menor a parcela do cliente: IaaS = muita responsabilidade; SaaS = quase nenhuma.",
    "whyCorrect": "IaaS abstrai hardware/virtualização mas o cliente ainda mantém SO, patches, runtimes, app e dados. SaaS entrega tudo pronto — cliente só configura settings e gerencia seus dados/usuários. PaaS fica no meio (cliente gerencia código + dados; AWS gerencia SO/runtime).",
    "whyWrong": {
     "A": "Modelos são distintos em responsabilidade — esse é um dos conceitos centrais.",
     "C": "Em IaaS a AWS gerencia até hypervisor; SO e acima é com o cliente.",
     "D": "Em SaaS o cliente não toca em kernel — só usa o software."
    },
    "keyConcept": "Service models — shared responsibility por camada",
    "compareWith": [
     "IaaS responsibility",
     "PaaS responsibility",
     "SaaS responsibility"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["service-models","shared-responsibility"]'::jsonb, 'ai-draft', 'active', now(), now()
)
