INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-043', 'aws-clf', 'Qual exemplo abaixo é INCORRETO ao classificar serviço AWS em modelo de implantação cloud?',
  '[{"id":"A","text":"Cloud nativo: app feito 100% em AWS managed services (Lambda, DynamoDB, API Gateway)"},{"id":"B","text":"Hybrid: app que estende para AWS via Outposts ou Direct Connect mantendo parte on-prem"},{"id":"C","text":"Multi-cloud: apenas quando o app roda exclusivamente em mainframe"},{"id":"D","text":"On-prem only: app totalmente em DC físico próprio, sem nuvem"}]'::jsonb, 'C',
  '{
    "summary": "Multi-cloud = usar 2+ provedores cloud (AWS + Azure, ou AWS + GCP), nada a ver com mainframe.",
    "whyCorrect": "A definição de Multi-cloud é distribuir cargas entre múltiplos provedores cloud para evitar lock-in, atender compliance, ou usar diferenciais (BigQuery no GCP + AWS para resto). ''Mainframe'' é hardware on-prem, oposto de cloud.",
    "whyWrong": {
     "A": "Definição correta de cloud nativo.",
     "B": "Definição correta de hybrid (cloud + on-prem coexistindo).",
     "D": "Definição correta de on-prem only."
    },
    "keyConcept": "Deployment models — cloud / hybrid / on-prem / multi-cloud",
    "compareWith": [
     "Cloud-native",
     "Hybrid",
     "Multi-cloud"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["service-models","deployment-models"]'::jsonb, 'ai-draft', 'active', now(), now()
)
