INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-044', 'aws-clf', 'AWS Wavelength é particularmente útil para qual caso?',
  '[{"id":"A","text":"Backup off-site mensal"},{"id":"B","text":"Big Data analytics noturno"},{"id":"C","text":"Email corporativo"},{"id":"D","text":"Aplicações mobile com latência ultra-baixa via 5G — AR/VR, gaming online, veículos autônomos conectados"}]'::jsonb, 'D',
  '{
    "summary": "Wavelength integra compute AWS à rede 5G — reduz latência mobile-to-cloud para single-digit ms.",
    "whyCorrect": "Em 5G, o gargalo de latência sai do core e vai para o backbone até a Region; Wavelength elimina esses hops colocando compute no edge da rede do telco. AR/VR mobile, gaming e veículos autônomos exigem essa latência ultra-baixa.",
    "whyWrong": {
     "A": "Backup tolera segundos/minutos — Wavelength é overkill caro.",
     "B": "Big Data noturno não é sensível a latência.",
     "C": "Email é insensível a latência."
    },
    "keyConcept": "Wavelength — 5G edge compute",
    "compareWith": [
     "Wavelength",
     "Local Zones",
     "Outposts"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["global-infrastructure","wavelength","5g"]'::jsonb, 'ai-draft', 'active', now(), now()
)
