INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-045', 'aws-clf', 'Uma equipe precisa rodar workload com latência sub-ms entre componentes (HFT — high-frequency trading). Em vez de Multi-AZ, escolhem Cluster Placement Group dentro de uma AZ. Qual conceito justifica essa escolha?',
  '[{"id":"A","text":"Placement groups (Cluster) co-localizam instâncias em rack próximo dentro da AZ — minimiza latência inter-instância e maximiza throughput de rede"},{"id":"B","text":"Placement groups aumentam o tamanho de disco"},{"id":"C","text":"Placement groups dão desconto financeiro automático"},{"id":"D","text":"Placement groups movem instâncias para outra Region"}]'::jsonb, 'A',
  '{
    "summary": "Cluster Placement Group co-localiza instâncias em hardware próximo dentro da mesma AZ — latência mínima e bandwidth máximo.",
    "whyCorrect": "Para HFT, HPC, ML training cluster, latência inter-nó é crítica. Cluster Placement Group instrui a AWS a alocar as instâncias em rack próximo (mesmo data center hall) na mesma AZ, com até 100 Gbps de rede. Trade-off: aumenta risco se a AZ inteira falhar.",
    "whyWrong": {
     "B": "Não tem relação com tamanho de disco — é colocação física.",
     "C": "Não é mecanismo de pricing.",
     "D": "Não move entre regions — opera dentro de AZ."
    },
    "keyConcept": "Placement Groups — Cluster vs Spread vs Partition",
    "compareWith": [
     "Cluster (low latency)",
     "Spread (anti-affinity)",
     "Partition (big data)"
    ],
    "realWorldContext": "HFT e ML training de modelos grandes (LLMs) dependem fortemente de Cluster Placement."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["global-infrastructure","placement-groups"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
