INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-046', 'aws-clf', 'Qual afirmação sobre AWS Region pairs (regiões geograficamente próximas) é correta?',
  '[{"id":"A","text":"Todas as regiões AWS são automaticamente pareadas 1:1 e fundidas operacionalmente"},{"id":"B","text":"AWS oferece pares de regiões frequentemente usadas em conjunto para DR — ex: us-east-1 ↔ us-west-2, eu-west-1 ↔ eu-central-1, sa-east-1 ↔ us-east-1 — com latência conhecida e replicação otimizada"},{"id":"C","text":"Regions pairs implicam failover automático sem configuração do cliente"},{"id":"D","text":"Region pair é o mesmo que AZ pair"}]'::jsonb, 'B',
  '{
    "summary": "Region pairs são pares populares para DR, mas o cliente que escolhe e configura o pareamento; não é automático.",
    "whyCorrect": "Não existe ''pair oficial'' obrigatório como no Azure, mas há pares praticados pelo mercado por latência/compliance (us-east-1 ↔ us-west-2 nos EUA; sa-east-1 ↔ us-east-1 para BR). O cliente é responsável por configurar a replicação.",
    "whyWrong": {
     "A": "Regions são isoladas por design; não há fusão automática.",
     "C": "Failover é responsabilidade do cliente — configurar Route 53 health checks, replicação, runbooks.",
     "D": "Region pair é entre regions (geograficamente distantes); AZ é dentro de region (sub-ms)."
    },
    "keyConcept": "Region pairs — DR pattern (cliente-driven)",
    "compareWith": [
     "Multi-AZ",
     "Multi-Region",
     "Region pair (convenção)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'best-practice', '["global-infrastructure","region-pairs","dr"]'::jsonb, 'ai-draft', 'active', now(), now()
)
