INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-047', 'aws-clf', 'Uma empresa brasileira atende usuários BR e Argentina. Em qual região AWS é mais aderente colocar workload primário considerando latência regional?',
  '[{"id":"A","text":"ap-northeast-1 (Tokyo)"},{"id":"B","text":"eu-north-1 (Estocolmo)"},{"id":"C","text":"sa-east-1 (São Paulo) — mais próxima geográfica, latência aceitável para BR e AR"},{"id":"D","text":"af-south-1 (Cape Town)"}]'::jsonb, 'C',
  '{
    "summary": "sa-east-1 é a região AWS mais próxima de usuários no Brasil e Argentina.",
    "whyCorrect": "sa-east-1 (São Paulo) entrega ~20ms para BR e ~40ms para AR. Alternativas no Hemisfério Norte ou Oriente adicionam 100-300ms RTT — degradação severa de UX.",
    "whyWrong": {
     "A": "Tokyo está a >250ms do BR — inviável para apps interativos.",
     "B": "Estocolmo a 200ms+ do BR — também inviável.",
     "D": "Cape Town tem latência razoável (~150ms BR), mas pior que sa-east-1."
    },
    "keyConcept": "Region selection — latência geográfica",
    "compareWith": [
     "sa-east-1 (BR)",
     "us-east-1 (US East)",
     "eu-west-1 (EU)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["global-infrastructure","region-selection"]'::jsonb, 'ai-draft', 'active', now(), now()
)
