INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-048', 'aws-clf', 'Sobre seleção de Region considerando ''feature availability'', qual afirmação é correta?',
  '[{"id":"A","text":"Todos os serviços AWS estão sempre disponíveis em todas as regiões no dia do lançamento"},{"id":"B","text":"Region selection nunca depende de features"},{"id":"C","text":"Serviços AWS só funcionam em us-east-1"},{"id":"D","text":"Nem todos os serviços AWS lançam simultaneamente em todas as regiões — alguns serviços novos podem demorar meses/anos para chegar em regiões menores, impactando arquitetura"}]'::jsonb, 'D',
  '{
    "summary": "Feature parity entre regions varia — us-east-1 e us-west-2 recebem novidades primeiro; regiões menores demoram.",
    "whyCorrect": "us-east-1 (Virginia) é a ''home region'' onde quase tudo lança primeiro; outras regiões grandes (us-west-2, eu-west-1) seguem em meses; regiões menores (sa-east-1, ap-south-1) podem levar mais tempo. Isso é critério real em region selection — workload que precisa de X feature pode forçar escolha de region específica.",
    "whyWrong": {
     "A": "Falso — disparidade é fato conhecido.",
     "B": "Feature availability é um dos 5 critérios canônicos de region selection.",
     "C": "Múltiplas regiões oferecem serviços; us-east-1 é só uma delas."
    },
    "keyConcept": "Region selection — feature availability",
    "compareWith": [
     "Latência",
     "Custo",
     "Compliance",
     "Features",
     "Sustainability"
    ],
    "realWorldContext": "Bedrock e novidades de IA lançam primeiro em us-east-1/us-west-2; clientes BR precisam decidir entre latência e features novas."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["global-infrastructure","region-selection","feature-parity"]'::jsonb, 'ai-draft', 'active', now(), now()
)
