INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-050', 'aws-clf', 'Qual perspectiva do AWS CAF é a mais alinhada com programa de upskilling/reskilling dos funcionários, criação de Cloud Center of Excellence (CCoE) e mudança cultural?',
  '[{"id":"A","text":"Security Perspective"},{"id":"B","text":"People Perspective"},{"id":"C","text":"Platform Perspective"},{"id":"D","text":"Operations Perspective"}]'::jsonb, 'B',
  '{
