INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-051', 'aws-clf', 'Uma equipe pergunta como modernizar arquitetura, adotar IaC, definir padrões de microservices. Qual perspectiva do CAF é mais aderente?',
  '[{"id":"A","text":"People Perspective"},{"id":"B","text":"Business Perspective"},{"id":"C","text":"Platform Perspective"},{"id":"D","text":"Security Perspective"}]'::jsonb, 'C',
  '{
    "summary": "Platform Perspective trata de plataforma técnica: arquitetura, padrões de modernização, IaC, CI/CD.",
    "whyCorrect": "Platform Perspective inclui capabilities: platform architecture, data architecture, platform engineering, modern application development. IaC, microservices patterns, plataforma de developers caem aqui.",
    "whyWrong": {
     "A": "People é cultura.",
     "B": "Business é valor para o negócio, ROI.",
     "D": "Security é controles de segurança."
    },
    "keyConcept": "AWS CAF — Platform Perspective",
    "compareWith": [
     "Platform (técnico)",
     "Operations (operacional)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["caf","platform"]'::jsonb, 'ai-draft', 'active', now(), now()
)
