INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-052', 'aws-clf', 'O CAF descreve estágios de maturidade de adoção. Qual sequência é correta?',
  '[{"id":"A","text":"Build → Deploy → Operate → Retire"},{"id":"B","text":"Plan → Code → Test → Ship"},{"id":"C","text":"Buy → Train → Migrate → Sunset"},{"id":"D","text":"Envision → Align → Launch → Scale"}]'::jsonb, 'D',
  '{
    "summary": "CAF Transformation Phases: Envision (visão), Align (alinhar capabilities), Launch (pilotos), Scale (escalar pela organização).",
    "whyCorrect": "Esses são os 4 estágios oficiais de transformação no CAF — começa identificando oportunidades, alinha as 6 perspectivas, executa pilotos para validar, e escala lições aprendidas em larga escala.",
    "whyWrong": {
     "A": "Build/Deploy/Operate/Retire é ciclo de vida de software, não fases CAF.",
     "B": "Plan/Code/Test/Ship é DevOps, não CAF.",
     "C": "Não é terminologia CAF."
    },
    "keyConcept": "AWS CAF — Transformation Phases",
    "compareWith": [
     "Envision",
     "Align",
     "Launch",
     "Scale"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["caf","transformation-phases"]'::jsonb, 'ai-draft', 'active', now(), now()
)
