INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-053', 'aws-clf', 'Qual afirmação sobre Security Perspective do CAF é correta?',
  '[{"id":"A","text":"Trata de controles de segurança (IAM, threat detection, response, compliance) como capability transversal à transformação cloud"},{"id":"B","text":"É exclusivamente sobre firewall físico"},{"id":"C","text":"Trata apenas de backup de dados"},{"id":"D","text":"Não está incluída no CAF"}]'::jsonb, 'A',
  '{
    "summary": "Security Perspective cobre identidade, detecção, resposta, controles preventivos — visão holística de segurança.",
    "whyCorrect": "Security Perspective inclui capabilities: identity and access, threat detection, infrastructure protection, data protection, incident response, application security. É uma das 6 perspectivas oficiais.",
    "whyWrong": {
     "B": "Firewall físico é pequeno subset; perspective é muito mais ampla.",
     "C": "Backup é capability menor; perspective cobre muito mais.",
     "D": "Está sim incluída — é uma das 6 perspectivas."
    },
    "keyConcept": "AWS CAF — Security Perspective"
   }'::jsonb,
