INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-056', 'aws-clf', 'Uma estratégia de DR define RTO de 4 horas e RPO de 1 hora. Qual padrão DR é o melhor encaixe (sem over-engineering)?',
  '[{"id":"A","text":"Backup \u0026 Restore — backups em outra region, restaurar do zero"},{"id":"B","text":"Warm Standby — cópia funcional reduzida sempre rodando"},{"id":"C","text":"Multi-Site Active-Active — duas regions em produção full simultaneamente"},{"id":"D","text":"Pilot Light — réplicas mínimas em outra region (DB replicado, app desligado); ao falhar, sobe capacidade rapidamente"}]'::jsonb, 'D',
  '{
    "summary": "Pilot Light é o padrão para RTO horas + RPO sub-hora — DB replicado em standby, app desligado mas pronto para subir.",
    "whyCorrect": "Pilot Light mantém os componentes críticos mínimos sempre rodando (banco com replicação contínua → RPO baixo) e desliga compute (app, workers). Em falha, sobe compute rapidamente — atinge RTO de horas. Mais barato que Warm Standby, mais rápido que Backup & Restore.",
    "whyWrong": {
     "A": "Backup & Restore tipicamente RTO 24h+; não atende 4h sem rasgar o budget.",
     "B": "Warm Standby atende RTO menor (minutos) mas é mais caro — over-engineering se 4h basta.",
     "C": "Multi-Site Active-Active atende RTO < 1min e RPO próximo de zero; muito caro para RTO 4h."
    },
    "keyConcept": "DR strategies — 4 padrões oficiais",
    "compareWith": [
     "Backup & Restore (24h+)",
     "Pilot Light (horas)",
     "Warm Standby (minutos)",
     "Active-Active (segundos)"
    ],
    "realWorldContext": "Whitepaper oficial ''Disaster Recovery of Workloads on AWS'' formaliza esses 4 padrões.",
    "tutorSeeds": [
     "Como o DRS (Elastic Disaster Recovery) acelera pilot light?",
     "Qual a diferença entre RTO e RPO?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["dr","rto-rpo","pilot-light"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
