INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-057', 'aws-clf', 'Qual definição é correta para RTO e RPO?',
  '[{"id":"A","text":"RTO = tempo máximo aceitável para restaurar serviço após falha. RPO = janela máxima aceitável de perda de dados (tempo entre último backup e o evento)"},{"id":"B","text":"RTO e RPO são sinônimos"},{"id":"C","text":"RTO = retention period; RPO = retention period offset"},{"id":"D","text":"RTO é em USD; RPO é em latência"}]'::jsonb, 'A',
  '{
    "summary": "RTO = quão rápido recupera. RPO = quanto dado pode perder.",
    "whyCorrect": "RTO (Recovery Time Objective) é tempo de downtime aceitável. RPO (Recovery Point Objective) é a quantidade de dados que podemos perder, medida em tempo. Backup a cada 1h → RPO máximo 1h. São conceitos ortogonais e ambos guiam escolha de padrão DR.",
    "whyWrong": {
     "B": "São distintos.",
     "C": "Retention é período de retenção de backup — conceito diferente.",
     "D": "Não são em USD nem latência."
    },
    "keyConcept": "DR — RTO vs RPO",
    "compareWith": [
     "RTO (downtime)",
     "RPO (data loss window)",
     "MTTR (mean time to recover)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["dr","rto-rpo"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
  options       = EXCLUDED.options,
