INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-058', 'aws-clf', 'Uma fintech crítica precisa RTO < 1 minuto e RPO próximo de zero para o core bancário. Qual estratégia DR é a adequada?',
  '[{"id":"A","text":"Backup \u0026 Restore com snapshots semanais"},{"id":"B","text":"Multi-Site Active-Active — ambas regions operam em produção; falha em uma é absorvida pela outra com falha-over instantâneo via Route 53"},{"id":"C","text":"Pilot Light"},{"id":"D","text":"Snapshot diário via Backup"}]'::jsonb, 'B',
  '{
    "summary": "Multi-Site Active-Active é o único padrão que entrega RTO < 1 min e RPO ~ 0 — preço: complexidade e custo dobrados.",
    "whyCorrect": "Em Active-Active, ambas regions atendem tráfego em produção (load balanced via Route 53 ou Global Accelerator). Em falha de uma, a outra absorve tráfego sem precisar ''subir'' nada — RTO é o tempo de DNS/health check (~30s). Replicação síncrona/quasi-síncrona alcança RPO próximo a zero.",
    "whyWrong": {
     "A": "Backup semanal teria RPO de até 7 dias — incompatível com fintech.",
     "C": "Pilot Light tem RTO de horas; não atende 1 min.",
     "D": "Snapshot diário = RPO até 24h."
    },
    "keyConcept": "DR — Multi-Site Active-Active",
    "compareWith": [
     "Pilot Light",
     "Warm Standby",
     "Active-Active"
    ],
    "realWorldContext": "Bancos centrais, exchanges e pagamentos críticos justificam custo de Active-Active."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["dr","multi-site","active-active"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
