INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-059', 'aws-clf', 'Qual diferença prática entre Pilot Light e Warm Standby?',
  '[{"id":"A","text":"São sinônimos exatos"},{"id":"B","text":"Pilot Light é cross-cloud; Warm Standby é dentro de uma region"},{"id":"C","text":"Pilot Light mantém apenas core mínimo rodando (DB replicado, compute desligado); Warm Standby mantém uma cópia funcional reduzida em escala (DB + algumas instâncias ativas), pronta para escalar imediatamente"},{"id":"D","text":"Pilot Light é só Lambda; Warm Standby é só EC2"}]'::jsonb, 'C',
  '{
    "summary": "Pilot Light = compute desligado; Warm Standby = compute reduzido sempre ativo. Diferença é tempo de start.",
    "whyCorrect": "Pilot Light tem RTO maior (precisa subir compute do zero, talvez 30-60 min); Warm Standby tem RTO menor (poucos minutos para escalar de tamanho reduzido para full). Warm Standby custa mais (compute rodando idle), mas dispensa procedimento de boot.",
    "whyWrong": {
     "A": "São padrões distintos.",
     "B": "Ambos são intra-AWS, geralmente entre regions.",
     "D": "Não há limitação por tipo de compute."
    },
    "keyConcept": "DR — escala dos componentes em standby",
    "compareWith": [
     "Pilot Light (RTO horas)",
     "Warm Standby (RTO minutos)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["dr","pilot-light","warm-standby"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
