INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-060', 'aws-clf', 'AWS Elastic Disaster Recovery (DRS) é positionado para qual cenário?',
  '[{"id":"A","text":"Substituir IAM"},{"id":"B","text":"Backup de S3 objects apenas"},{"id":"C","text":"Migrar de Oracle para PostgreSQL"},{"id":"D","text":"Implementar Pilot Light/Warm Standby para servers (físicos, virtuais ou EC2) com replicação contínua block-level para uma region de recovery, e failover em minutos"}]'::jsonb, 'D',
  '{
    "summary": "DRS replica continuamente servers para AWS e habilita failover/recovery em minutos.",
    "whyCorrect": "DRS (antigo CloudEndure Disaster Recovery) replica volumes em block-level para storage staging em AWS; em falha do source, instanciações EC2 são lançadas no target em minutos — atendendo Pilot Light/Warm Standby. Suporta source on-prem, em outras clouds, ou EC2.",
    "whyWrong": {
     "A": "Não substitui IAM (gestão de identidade).",
     "B": "S3 backup é AWS Backup; DRS é para servers.",
     "C": "Mudança de engine de DB é SCT + DMS."
    },
    "keyConcept": "DR tooling — AWS Elastic Disaster Recovery (DRS)",
    "compareWith": [
     "DRS (DR)",
     "MGN (migração one-time)",
     "AWS Backup (snapshot)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["dr","drs","elastic-disaster-recovery"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
