INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-061', 'aws-clf', 'Uma empresa migrou para AWS e descobre que custos crescem 15% ao mês sem crescimento equivalente de receita. Ao investigar, encontram instâncias zombie (idle 0% CPU 24/7) e volumes EBS unattached. Qual prática é a aplicação direta de cloud economics nesse cenário?',
  '[{"id":"A","text":"Eliminar capacity idle — recursos não utilizados em cloud ainda geram custo (diferente de DC físico onde idle apenas desperdiça energia, não fatura)"},{"id":"B","text":"Manter os recursos pois ''já foram pagos''"},{"id":"C","text":"Não mexer porque a empresa tem Reserved Instances"},{"id":"D","text":"Migrar para multi-cloud para diluir custo"}]'::jsonb, 'A',
  '{
    "summary": "Em cloud, recurso idle continua faturando — diferente do CapEx on-prem que é sunk cost. Eliminação é ação direta de economics.",
    "whyCorrect": "On-prem, hardware idle desperdiça energia mas não cobra hora a hora; cloud cobra por tempo provisionado independente de uso. Idle = perda direta de dinheiro. Identificar (Trusted Advisor, Cost Explorer) e eliminar é uma das primeiras ações de FinOps.",
    "whyWrong": {
     "B": "Cloud não tem ''já foram pagos'' — pay-as-you-go.",
     "C": "RI cobre baseline; idle gera waste mesmo com RI (você paga RI E não usa).",
     "D": "Multi-cloud aumenta complexidade, não resolve idle."
    },
    "keyConcept": "Cloud economics — eliminar idle capacity",
    "compareWith": [
     "On-prem (CapEx sunk cost)",
     "Cloud (OpEx contínuo)"
    ],
    "realWorldContext": "Trusted Advisor ''Idle Load Balancers'' e ''Unattached EBS'' são checks gratuitos comuns."
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["cloud-economics","idle-capacity"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
