INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-062', 'aws-clf', 'O princípio de ''economies of scale'' aplicado à AWS significa que:',
  '[{"id":"A","text":"AWS dá desconto progressivo individual baseado em volume de cada cliente"},{"id":"B","text":"Como AWS atende milhões de clientes, seu custo unitário (servidor, rede, energia) é menor que o de qualquer cliente individual — esse desconto é repassado em preços que tendem a cair ao longo do tempo"},{"id":"C","text":"Quanto maior a empresa cliente, mais barato fica por hora"},{"id":"D","text":"AWS subsidiza clientes pequenos cobrando mais dos grandes"}]'::jsonb, 'B',
  '{
    "summary": "Economies of scale: AWS compra hardware/energia em escala global e repassa preço unitário baixo a todos os clientes.",
    "whyCorrect": "AWS já fez 100+ reduções de preço desde 2006 — reflexo direto desse princípio. Fornecedores que tentassem replicar a infra AWS pagariam preço muito maior por servidor/kWh.",
    "whyWrong": {
     "A": "Há descontos por commitment (RI, SP, EDP), mas o princípio de economies of scale fala do preço base de tabela, não desconto individual.",
     "C": "Preço por hora é igual independente do tamanho do cliente (na tabela pública).",
     "D": "AWS não subsidia entre clientes — é o mesmo preço público."
    },
    "keyConcept": "Cloud economics — economies of scale",
    "compareWith": [
     "Economies of scale (base price)",
     "EDP (volume discount contratual)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["cloud-economics","economies-of-scale"]'::jsonb, 'ai-draft', 'active', now(), now()
)
