INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-063', 'aws-clf', 'Por que pay-as-you-go beneficia especialmente startups vs CapEx tradicional?',
  '[{"id":"A","text":"Garante lucro à startup"},{"id":"B","text":"Pay-as-you-go é mais caro que CapEx em 100% dos casos"},{"id":"C","text":"Elimina compra antecipada de capacidade; startup paga só pelo uso real e escala conforme tração — reduzindo investimento inicial e risco de over/under-provisioning"},{"id":"D","text":"Startups não devem usar cloud"}]'::jsonb, 'C',
  '{
    "summary": "Pay-as-you-go elimina barreira de entrada CapEx; startup começa com USD 100/mês e cresce com a receita.",
    "whyCorrect": "Sem cloud, startup precisaria de USD 100k+ adiantados em servidores. Com cloud, paga USD 50-500/mês inicialmente e escala junto com clientes. Reduz risco financeiro e permite experimentar/pivotar sem hardware encalhado.",
    "whyWrong": {
     "A": "Cloud não ''garante lucro'' — apenas reduz custo de infra inicial.",
     "B": "Pay-as-you-go pode ser mais caro em workload estável de longo prazo (vs RI/SP); ''mais caro em 100% dos casos'' é falso.",
     "D": "Absurdo — startups são os maiores beneficiários de cloud."
    },
    "keyConcept": "Cloud economics — pay-as-you-go e barreira de entrada",
    "compareWith": [
     "CapEx (compra antecipada)",
     "OpEx (pago pelo uso)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["cloud-economics","pay-as-you-go"]'::jsonb, 'ai-draft', 'active', now(), now()
)
