INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-064', 'aws-clf', 'Uma startup tem workload com pico de 1000 req/s à noite e 50 req/s de manhã. Qual prática de cloud economics endereça esse padrão?',
  '[{"id":"A","text":"Provisionar 1000 req/s 24x7 para garantir performance"},{"id":"B","text":"Manter zero capacidade reserva"},{"id":"C","text":"Comprar Reserved Instance para o pico"},{"id":"D","text":"Auto Scaling + Spot Instances para picos previsíveis — paga só pelo necessário em cada hora, evitando provisionar para o pior caso"}]'::jsonb, 'D',
  '{
    "summary": "Match supply to demand — Auto Scaling escala baseado em métricas; Spot reduz custo do pico variável.",
    "whyCorrect": "Cloud economics prega ''match supply to demand''. Workload com variação 20x precisa de Auto Scaling para evitar pagar pico durante baseline. Spot complementa para picos previsíveis com custo reduzido.",
    "whyWrong": {
     "A": "Provisionar pico 24x7 desperdiça 95% do tempo — anti-padrão de cloud economics.",
     "B": "Zero reserva causa scaling lag — degradação de UX durante ramp up.",
     "C": "RI para pico só faz sentido se o pico for previsível 24x7 — não é o caso."
    },
    "keyConcept": "Cloud economics — match supply to demand",
    "compareWith": [
     "Static provisioning",
     "Auto Scaling",
     "Spot Fleet"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["cloud-economics","auto-scaling","spot"]'::jsonb, 'ai-draft', 'active', now(), now()
)
