INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-065', 'aws-clf', 'Qual é o custo escondido mais comum de não fazer governança de cloud (Cost Optimization Hub + tagging) em empresas grandes?',
  '[{"id":"A","text":"Cloud sprawl — equipes provisionando recursos sem accountability, gerando 20-40% de desperdício invisível na fatura mensal"},{"id":"B","text":"AWS bloqueia novas contas automaticamente"},{"id":"C","text":"Tempo de boot da EC2 aumenta"},{"id":"D","text":"Não há custo escondido"}]'::jsonb, 'A',
  '{
    "summary": "Cloud sprawl é o crescimento descontrolado de recursos sem visibilidade — 20-40% de desperdício é típico em empresas sem FinOps.",
    "whyCorrect": "Sem tagging + accountability, equipes provisionam recursos para testes, esquecem, deixam ligados. Sem cost attribution, ninguém é responsável. Estudos de FinOps Foundation mostram 20-40% de waste em empresas imaturas.",
    "whyWrong": {
     "B": "AWS não bloqueia contas por falta de governança.",
     "C": "Tempo de boot não tem relação com governança.",
     "D": "Cloud sprawl é o custo escondido clássico — afirmar inexistência é falso."
    },
    "keyConcept": "Cloud economics — cloud sprawl",
    "compareWith": [
     "Cloud sprawl",
     "FinOps governance",
     "Tagging strategy"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["cloud-economics","cloud-sprawl"]'::jsonb, 'ai-draft', 'active', now(), now()
)
