INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-066', 'aws-clf', 'Qual é o efeito de longo prazo, segundo cloud economics, de migrar de DC próprio (CapEx pesado) para AWS (OpEx)?',
  '[{"id":"A","text":"Perda total de controle sobre dados"},{"id":"B","text":"Aumento de flexibilidade financeira e maior capacidade de experimentação — falhas são mais baratas (provisionar e desligar) e aprendizado acelera"},{"id":"C","text":"Custo sempre maior em qualquer cenário"},{"id":"D","text":"Empresa fica obrigada a usar apenas AWS para sempre"}]'::jsonb, 'B',
  '{
    "summary": "CapEx→OpEx libera capital + reduz custo de experimentação — efeito de longo prazo é cultura mais ágil.",
    "whyCorrect": "Provisionar e descartar com cliques transforma economia de fail-fast. Em CapEx, errar significa hardware encalhado por anos. Em OpEx, errar é desligar a instância. Resultado: mais experimentos, mais inovação.",
    "whyWrong": {
     "A": "Controle de dados continua do cliente (Shared Responsibility).",
     "C": "Cenários têm trade-offs; nem sempre cloud é mais caro nem mais barato.",
     "D": "Não há lock-in obrigatório — cliente pode migrar para outra cloud ou voltar para on-prem."
    },
    "keyConcept": "Cloud economics — CapEx vs OpEx (efeito cultural)",
    "compareWith": [
     "CapEx (compromisso longo)",
     "OpEx (flexibilidade)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["cloud-economics","capex-opex","experimentation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
