INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-067', 'aws-clf', 'Uma estratégia DR ''Backup & Restore'' é adequada para qual perfil de workload?',
  '[{"id":"A","text":"Core bancário tier-1"},{"id":"B","text":"Trading platform de bolsa"},{"id":"C","text":"Workloads não-críticos (intranet interna, dev/test, relatórios mensais) onde RTO de 24h+ é aceitável e custo é prioridade"},{"id":"D","text":"Sistema de prontuário hospitalar em UTI"}]'::jsonb, 'C',
  '{
    "summary": "Backup & Restore é mais barato mas RTO em horas/dia — só para workloads que toleram downtime longo.",
    "whyCorrect": "Backup & Restore mantém só snapshots em outra region. Restaurar exige criar VPC, infra, banco do snapshot — leva horas. Aceitável para intranet, dev/test, BI mensal onde 24-48h de downtime não inviabiliza o negócio.",
    "whyWrong": {
     "A": "Core bancário tier-1 exige Multi-Site Active-Active.",
     "B": "Trading exige RTO de segundos — Active-Active.",
     "D": "Prontuário UTI é tier-1 — RTO em horas inaceitável (risco de vida)."
    },
    "keyConcept": "DR — Backup & Restore (RTO em horas)",
    "compareWith": [
     "Backup & Restore",
     "Pilot Light",
     "Warm Standby",
     "Active-Active"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["dr","backup-restore"]'::jsonb, 'ai-draft', 'active', now(), now()
)
