INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-068', 'aws-clf', 'Uma empresa adota DR Multi-Region usando read replicas cross-region do Aurora + S3 Cross-Region Replication + Route 53 com health checks. Qual padrão DR esse stack mais se aproxima?',
  '[{"id":"A","text":"Backup \u0026 Restore"},{"id":"B","text":"Single-Site Single-AZ"},{"id":"C","text":"Local Zones DR"},{"id":"D","text":"Pilot Light ou Warm Standby — a depender de se há capacity de compute também rodando (warm) ou só DB replicado (pilot)"}]'::jsonb, 'D',
  '{
    "summary": "Réplica contínua de dados + Route 53 com health checks é o padrão Pilot Light/Warm Standby (sem compute ativo = pilot; com compute ativo = warm).",
    "whyCorrect": "Réplica de DB contínua atinge RPO baixo; Route 53 health check faz failover de DNS. Se compute estiver desligado no DR site = Pilot Light. Se compute estiver rodando em escala reduzida = Warm Standby. RTO típico: minutos a horas.",
    "whyWrong": {
     "A": "Backup & Restore não usa replicação contínua; usa snapshots periódicos.",
     "B": "Single-Site Single-AZ é o oposto de DR — sem redundância.",
     "C": "Local Zones DR não é padrão DR clássico (LZ é para latência metro)."
    },
    "keyConcept": "DR padrões — identificar pela ferramenta",
    "compareWith": [
     "Pilot Light",
     "Warm Standby"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["dr","pilot-light","warm-standby"]'::jsonb, 'ai-draft', 'active', now(), now()
)
