INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-069', 'aws-clf', 'Sobre a estratégia de migração ''Relocate'' (sétima R, oficial desde 2020), qual descrição é correta?',
  '[{"id":"A","text":"Mover infraestrutura virtualizada para AWS sem comprar hardware nem mudar OS (ex: VMware Cloud on AWS, vSphere → AWS sem refactor) — versão ainda mais ''lift'' que Rehost"},{"id":"B","text":"Sinônimo de Retire"},{"id":"C","text":"Mover dados entre buckets S3"},{"id":"D","text":"Sinônimo de Refactor"}]'::jsonb, 'A',
  '{
    "summary": "Relocate move VMs/clusters inteiros para AWS sem alterar hypervisor (VMware Cloud on AWS é caso clássico).",
    "whyCorrect": "Relocate (7ª R) é mais ''lift'' ainda que Rehost — mantém até o hypervisor (VMware) operando dentro da AWS via VMware Cloud on AWS. Ideal para datacenters VMware que querem sair de hardware próprio mas não querem re-instanciar VMs em EC2.",
    "whyWrong": {
     "B": "Retire é desligar, oposto.",
     "C": "S3 transfer é DataSync, não migração de portfolio.",
     "D": "Refactor é reescrever, oposto de relocate."
    },
    "keyConcept": "Migration — 7 Rs (Retire/Retain/Rehost/Relocate/Replatform/Repurchase/Refactor)",
    "compareWith": [
     "Rehost (EC2)",
     "Relocate (VMware Cloud)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["migration","7rs","relocate"]'::jsonb, 'ai-draft', 'active', now(), now()
)
