INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-070', 'aws-clf', 'Uma empresa quer migrar 500GB de banco MySQL on-prem para RDS MySQL na AWS com downtime mínimo. Qual serviço é a escolha canônica?',
  '[{"id":"A","text":"AWS Snowball Edge"},{"id":"B","text":"AWS Database Migration Service (DMS) com CDC (change data capture) para sincronizar continuamente até o cutover"},{"id":"C","text":"AWS Direct Connect com cópia manual"},{"id":"D","text":"AWS S3 Glacier"}]'::jsonb, 'B',
  '{
    "summary": "DMS faz carga inicial + CDC contínuo — downtime de cutover cai para minutos.",
    "whyCorrect": "DMS suporta full load + ongoing replication via CDC. Você liga DMS, ele copia 500GB iniciais, depois replica mudanças continuamente. Cutover: pausa app, espera DMS drenar, vira DNS para RDS. Downtime tipicamente sub-5min.",
    "whyWrong": {
     "A": "Snowball Edge é para volumes massivos (TB-PB) sem conectividade; 500GB cabe em conexão normal e DMS.",
     "C": "Direct Connect é conectividade dedicada, não ferramenta de migração de DB.",
     "D": "Glacier é archive storage, não migração de DB."
    },
    "keyConcept": "Migration — DMS + CDC",
    "compareWith": [
     "DMS (DB)",
     "MGN (server)",
     "DataSync (file)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["migration","dms","cdc"]'::jsonb, 'ai-draft', 'active', now(), now()
)
