INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-071', 'aws-clf', 'Uma empresa precisa mover 5 PB de dados de DC on-prem para S3 e tem apenas 100 Mbps de internet (transferência tomaria meses). Qual serviço resolve melhor?',
  '[{"id":"A","text":"AWS DataSync via internet"},{"id":"B","text":"Upload manual via console S3"},{"id":"C","text":"AWS Snowball Edge ou Snowmobile — dispositivos físicos enviados ao cliente para copiar dados localmente e devolvidos à AWS"},{"id":"D","text":"AWS Lambda"}]'::jsonb, 'C',
  '{
    "summary": "Para PBs com banda limitada, dispositivos físicos (Snow Family) são mais rápidos que internet.",
    "whyCorrect": "Em 100 Mbps, 5 PB levaria ~12 anos. Snowball Edge (até 80 TB cada) ou Snowmobile (truck com 100 PB) movem dados em dias, não anos. AWS calcula tempo break-even: quando supera ~2 semanas via rede, Snow vence.",
    "whyWrong": {
     "A": "DataSync via internet ainda esbarra nos 100 Mbps — não resolve.",
     "B": "Upload manual é inviável em volume.",
     "D": "Lambda não transfere dados massivos."
    },
    "keyConcept": "Migration — Snow Family",
    "compareWith": [
     "Snowcone (8TB)",
     "Snowball Edge (80TB)",
     "Snowmobile (100PB)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["migration","snowball","data-transfer"]'::jsonb, 'ai-draft', 'active', now(), now()
)
