INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-072', 'aws-clf', 'Application Discovery Service (ADS) é usado em qual fase do programa MAP?',
  '[{"id":"A","text":"Operate"},{"id":"B","text":"Decommission"},{"id":"C","text":"Backup"},{"id":"D","text":"Assess — coleta inventário on-prem (servers, dependências, performance) para alimentar 6 Rs decisions e TCO"}]'::jsonb, 'D',
  '{
    "summary": "ADS coleta inventário detalhado para decidir o que migrar e como — fase Assess do MAP.",
    "whyCorrect": "ADS instala agente (ou usa agentless) nos servers on-prem para descobrir CPU, memória, network connections, dependências entre apps. Esses dados feed Migration Hub e Migration Evaluator para business case e priorização de waves.",
    "whyWrong": {
     "A": "Operate é pós-migração, não descoberta.",
     "B": "Decommission é fim do ciclo, não descoberta.",
     "C": "ADS não é backup."
    },
    "keyConcept": "Migration — ADS na fase Assess",
    "compareWith": [
     "ADS (discovery)",
     "Migration Evaluator (TCO)",
     "Migration Hub (tracking)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["migration","ads","assess"]'::jsonb, 'ai-draft', 'active', now(), now()
)
