INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-073', 'aws-clf', 'Qual estratégia das 6 Rs é frequentemente a MAIS rápida de executar (menor esforço de engenharia) mas resulta em menor ''cloud-nativeness''?',
  '[{"id":"A","text":"Rehost (lift-and-shift) — mover VM como está; rápido mas não aproveita managed services"},{"id":"B","text":"Refactor — reescrever para serverless"},{"id":"C","text":"Repurchase"},{"id":"D","text":"Retire"}]'::jsonb, 'A',
  '{
    "summary": "Rehost é o caminho mais rápido para a cloud (semanas), mas mantém arquitetura legada — você não ''usa'' cloud, só ''roda em'' cloud.",
    "whyCorrect": "Rehost via MGN move VM-as-is para EC2 em dias/semanas, com risco baixo. Trade-off: você não ganha benefícios de managed services (RDS auto-failover, Lambda escala) — fica com VM tradicional rodando em EC2. Muitas empresas fazem rehost primeiro e modernizam depois.",
    "whyWrong": {
     "B": "Refactor é o oposto — mais cloud-native, mais lento (meses-anos).",
     "C": "Repurchase pode ser rápido (subscribe SaaS), mas exige migração de dados/integração.",
     "D": "Retire é instantâneo, mas só se aplica a apps inúteis."
    },
    "keyConcept": "Migration — speed vs cloud-nativeness trade-off",
    "compareWith": [
     "Rehost (rápido)",
     "Refactor (cloud-native)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'best-practice', '["migration","rehost","trade-offs"]'::jsonb, 'ai-draft', 'active', now(), now()
)
