INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-074', 'aws-clf', 'Qual perspectiva do AWS CAF é responsável por desenhar e operar a landing zone (multi-account architecture, baseline de redes, guardrails)?',
  '[{"id":"A","text":"People Perspective"},{"id":"B","text":"Platform Perspective (em colaboração com Governance e Security)"},{"id":"C","text":"Business Perspective"},{"id":"D","text":"Não está coberto pelo CAF"}]'::jsonb, 'B',
  '{
    "summary": "Landing zone é capability principal de Platform Perspective, com Governance e Security definindo guardrails.",
    "whyCorrect": "Platform Perspective inclui ''platform architecture'' e ''platform engineering'' — landing zone (Control Tower, Organizations, Account Factory, baseline VPCs) cai aqui. Governance define políticas (SCPs); Security define controles (GuardDuty, Security Hub baseline).",
    "whyWrong": {
     "A": "People é cultura, não arquitetura.",
     "C": "Business é estratégia, não arquitetura.",
     "D": "Está coberto — é tema central de Platform."
    },
    "keyConcept": "CAF — landing zone em Platform Perspective",
    "compareWith": [
     "Platform (arquitetura)",
     "Governance (políticas)",
     "Security (controles)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'best-practice', '["caf","landing-zone","platform"]'::jsonb, 'ai-draft', 'active', now(), now()
)
