INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-075', 'aws-clf', 'Sobre ''Stop guessing capacity'' aplicado a databases gerenciados, qual serviço é o exemplo mais alinhado?',
  '[{"id":"A","text":"RDS db.r5.24xlarge sempre provisionado em capacity máxima"},{"id":"B","text":"EC2 i3.metal com DB instalado manualmente"},{"id":"C","text":"Aurora Serverless v2 — escala automaticamente CPU/memória do DB em segundos baseado em carga real, sem provisionar instance size fixo"},{"id":"D","text":"DynamoDB com capacity 1000 RCU/WCU fixo"}]'::jsonb, 'C',
  '{
    "summary": "Aurora Serverless v2 escala vertical/horizontal de DB sem intervenção — manifesto de ''stop guessing capacity'' em databases.",
    "whyCorrect": "Aurora Serverless v2 mede carga e ajusta ACU (Aurora Capacity Units) em segundos. Sem chutar instance size. Workloads imprevisíveis (apps SaaS multi-tenant, dev/test, sazonais) usam para evitar over/under-provisioning.",
    "whyWrong": {
     "A": "Provisionar capacity máxima é guessing extremo — opposite of the principle.",
     "B": "EC2 i3.metal com DB instalado é unmanaged e ainda exige guessing.",
     "D": "DynamoDB Provisioned capacity fixa também exige guessing — DynamoDB On-Demand seria alinhado."
    },
    "keyConcept": "Performance Efficiency — serverless databases",
    "compareWith": [
     "Aurora Serverless v2",
     "DynamoDB On-Demand"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["well-architected","performance-efficiency","aurora-serverless"]'::jsonb, 'ai-draft', 'active', now(), now()
)
