INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-076', 'aws-clf', 'Sobre o pilar Cost Optimization, qual prática melhor descreve ''Stop spending money on undifferentiated heavy lifting''?',
  '[{"id":"A","text":"Comprar mais servidores físicos"},{"id":"B","text":"Contratar mais sysadmins"},{"id":"C","text":"Construir o próprio sistema operacional"},{"id":"D","text":"Substituir operação manual de banco (patching, backup, replicação) por RDS managed, liberando o time para focar em lógica de negócio"}]'::jsonb, 'D',
  '{
    "summary": "Managed services eliminam operação de baixo valor — o time foca em diferencial competitivo.",
    "whyCorrect": "''Undifferentiated heavy lifting'' são tarefas que não diferenciam seu produto (patching, backup, replicação de DB) mas consomem recursos. RDS, Lambda, DynamoDB absorvem isso. Custo reduzido + velocidade aumentada.",
    "whyWrong": {
     "A": "Comprar mais servers é exatamente o oposto — assumir mais heavy lifting.",
     "B": "Mais sysadmins amplifica heavy lifting humano.",
     "C": "Construir OS próprio é maximum undifferentiated heavy lifting."
    },
    "keyConcept": "Cost Optimization — managed services",
    "compareWith": [
     "Self-managed (heavy lifting)",
     "Managed (focus on business)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'best-practice', '["well-architected","cost-optimization","managed-services"]'::jsonb, 'ai-draft', 'active', now(), now()
)
