INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-077', 'aws-clf', 'Uma equipe configura RDS Multi-AZ e em testes confirma failover automático em ~60s. Isso é a aplicação direta de qual design principle do Reliability Pillar?',
  '[{"id":"A","text":"Automatically recover from failure"},{"id":"B","text":"Foundations: limit-management"},{"id":"C","text":"Scale horizontally"},{"id":"D","text":"Manage change in automation"}]'::jsonb, 'A',
  '{
    "summary": "RDS Multi-AZ é auto-recovery clássico — falha do primary, secundário promove sem intervenção.",
    "whyCorrect": "Multi-AZ mantém standby síncrono em outra AZ. CloudWatch detecta falha, RDS faz failover (60-120s) e endpoint passa a apontar para o novo primary. Cliente nem percebe (além de breve interrupção de conexão).",
    "whyWrong": {
     "B": "Foundations trata de quotas/limits — não é o foco aqui.",
     "C": "Scale horizontally é sobre adicionar réplicas para throughput, não failover.",
     "D": "Manage change in automation é IaC/deployment automation, não auto-recovery."
    },
    "keyConcept": "Reliability — automatically recover from failure",
    "compareWith": [
     "Multi-AZ (failover automático)",
     "Read Replica (scaling)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["well-architected","reliability","rds-multi-az"]'::jsonb, 'ai-draft', 'active', now(), now()
)
