INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-078', 'aws-clf', 'Qual afirmação sobre ''Throughput'' vs ''Latency'' no contexto de Performance Efficiency é correta?',
  '[{"id":"A","text":"São sinônimos exatos"},{"id":"B","text":"Throughput é volume de trabalho por unidade de tempo (req/s, MB/s); Latency é o tempo de resposta de uma operação individual (ms). Sistemas podem ter alto throughput e alta latência simultaneamente (ex: batch)"},{"id":"C","text":"Throughput é medido em ms; Latency em req/s"},{"id":"D","text":"Alta throughput sempre implica baixa latency"}]'::jsonb, 'B',
  '{
    "summary": "Throughput e latência são ortogonais. Pipeline batch ETL pode ter alto throughput e alta latência por job.",
    "whyCorrect": "Throughput = vazão (quantos req/s). Latency = tempo de uma req individual. Sistemas podem ser otimizados para um sem afetar o outro positivamente — batch ETL processa TB/h (alto throughput) mas cada job leva 30 min (alta latência por job). API REST otimiza latência (ms por req).",
    "whyWrong": {
     "A": "São métricas distintas.",
     "C": "Invertido: throughput é vol/tempo; latency é tempo.",
     "D": "Falso — podem ser independentes (batch é exemplo)."
    },
    "keyConcept": "Performance — throughput vs latency",
    "compareWith": [
     "Throughput (vol/s)",
     "Latency (s/req)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["well-architected","performance-efficiency","metrics"]'::jsonb, 'ai-draft', 'active', now(), now()
)
