INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-079', 'aws-clf', 'Qual é um exemplo de PaaS em AWS que NÃO é Beanstalk, Lambda ou App Runner?',
  '[{"id":"A","text":"Amazon Glacier"},{"id":"B","text":"Amazon VPC"},{"id":"C","text":"Amazon Lightsail — bundles pré-configurados de compute + storage + networking + DNS com pricing fixo simples; abstrai detalhes de VPC/EC2 para devs solo"},{"id":"D","text":"Amazon Route 53"}]'::jsonb, 'C',
  '{
    "summary": "Lightsail é o ''easy mode'' da AWS — bundles fixos abstraindo complexidade. Frequentemente classificado como PaaS-leve.",
    "whyCorrect": "Lightsail entrega VPS-like com compute + storage + networking + DNS em bundle de preço fixo. Esconde VPC, SGs, route tables — dev solo só vê ''Instance LAMP $5/mês''. É PaaS-style para small workloads.",
    "whyWrong": {
     "A": "Glacier é storage archive — IaaS de storage.",
     "B": "VPC é IaaS de rede.",
     "D": "Route 53 é DNS gerenciado — mais perto de SaaS-leve, mas não é o exemplo canônico de PaaS."
    },
    "keyConcept": "Service models — Lightsail (PaaS-leve)",
    "compareWith": [
     "Lightsail (bundles)",
     "EC2 (granular)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["service-models","lightsail","paas"]'::jsonb, 'ai-draft', 'active', now(), now()
)
