INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v2-080', 'aws-clf', 'Sobre seleção de Region considerando ''sustainability'', qual estatística reportada pela AWS é mais relevante para FinOps + ESG?',
  '[{"id":"A","text":"AWS publica o número total de funcionários"},{"id":"B","text":"AWS divulga lucro por região"},{"id":"C","text":"AWS proíbe medição de emissões"},{"id":"D","text":"Customer Carbon Footprint Tool reporta emissões em kgCO2eq por serviço/region/mês, permitindo correlacionar custo e pegada de carbono"}]'::jsonb, 'D',
  '{
    "summary": "Customer Carbon Footprint Tool (CCFT) é a métrica oficial AWS de emissões — input direto para metas ESG.",
    "whyCorrect": "CCFT, lançado em 2022 no Billing console, reporta emissões em kgCO2eq por serviço, region, mês. Permite empresas com metas Net Zero reportar Scope 3 (emissões de fornecedores) com dados verificáveis.",
    "whyWrong": {
     "A": "Headcount não é métrica sustentável relevante para FinOps.",
     "B": "Lucro por region não é divulgado por AWS e não é métrica sustentável.",
     "C": "Falso — AWS publica e incentiva medição de emissões."
    },
    "keyConcept": "Sustainability — Customer Carbon Footprint Tool (CCFT)",
    "compareWith": [
     "CCFT (medir)",
     "Region selection (otimizar)"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["well-architected","sustainability","carbon-footprint"]'::jsonb, 'ai-draft', 'active', now(), now()
)
