INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-001', 'aws-clf', 'Uma operadora de telecom no Brasil está construindo um serviço de realidade aumentada para visitantes em estádios da Copa, exigindo latência fim-a-fim menor que 10 ms entre o dispositivo 5G e a aplicação. Qual variante da infraestrutura global AWS foi projetada exatamente para esse caso?',
  '[{"id":"A","text":"AWS Wavelength Zones"},{"id":"B","text":"AWS Local Zones"},{"id":"C","text":"Edge Locations do CloudFront"},{"id":"D","text":"Regional Edge Caches"}]'::jsonb, 'A',
  '{
    "summary": "Wavelength Zones embarcam compute/storage AWS dentro do datacenter da operadora 5G, eliminando o salto até a Region para apps de ultra-baixa latência móvel.",
    "whyCorrect": "AWS Wavelength foi desenhada especificamente para edge mobile 5G: a infraestrutura fica fisicamente no datacenter da operadora (Verizon, Vodafone, KDDI, SK Telecom, Bell Canada), de modo que o tráfego 5G não precisa atravessar a internet pública até a Region. Casos típicos: AR/VR em estádios, jogos em nuvem móvel, veículos conectados.",
    "whyWrong": {
     "B": "Local Zones aproximam compute de cidades específicas (Los Angeles, Miami, São Paulo metro), mas para tráfego que entra pela internet — não estão embarcadas na rede 5G da operadora.",
     "C": "Edge Locations CloudFront fazem cache de conteúdo HTTP/S — não rodam EC2/EKS/EBS arbitrários e não estão na rede da operadora 5G.",
     "D": "Regional Edge Caches são camada intermediária do CloudFront (entre POPs e origem), focados em hit ratio de cache, não em compute de baixa latência."
    },
    "keyConcept": "Wavelength Zone — compute embarcado em datacenter 5G",
    "compareWith": [
     "Wavelength vs Local Zone",
     "Edge Location vs Wavelength"
    ],
    "realWorldContext": "Verizon usa Wavelength em estádios da NFL para apps de estatísticas em tempo real para fãs.",
    "commonMistakes": "Achar que ''edge'' é tudo a mesma coisa — Edge Location (CDN), Local Zone (metro), Wavelength (5G), Outposts (on-prem) servem propósitos distintos.",
    "tutorSeeds": [
     "Quais operadoras têm Wavelength Zones no Brasil ou América Latina?",
     "Como fica o roteamento BGP entre Wavelength e a Region parent?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["global-infra","wavelength","5g","edge"]'::jsonb, 'ai-draft', 'active', now(), now()
)
