INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-002', 'aws-clf', 'Um banco de varejo brasileiro precisa rodar uma aplicação que, por exigência regulatória do BACEN, deve manter os dados fisicamente dentro da sede do banco em São Paulo. A equipe ainda quer usar APIs AWS nativas para gerenciar a infraestrutura. Qual opção atende a esse requisito mantendo o plano de controle AWS?',
  '[{"id":"A","text":"AWS Local Zone São Paulo"},{"id":"B","text":"AWS Outposts (rack) instalado no datacenter do banco"},{"id":"C","text":"VPC peering entre sa-east-1 e datacenter on-premises via VPN"},{"id":"D","text":"AWS Direct Connect dedicado para sa-east-1"}]'::jsonb, 'B',
  '{
    "summary": "AWS Outposts é hardware AWS gerenciado entregue e instalado no datacenter do cliente, mantendo dados localmente mas usando APIs AWS nativas.",
    "whyCorrect": "Outposts (rack 42U ou server 1U/2U) atende exatamente esse caso: o hardware fica fisicamente no datacenter do cliente (atendendo soberania de dados/regulação), mas é gerenciado pela AWS via plano de controle de uma Region parent. EC2, EBS, S3 on Outposts, RDS, EKS rodam localmente.",
    "whyWrong": {
     "A": "Local Zone São Paulo é infraestrutura AWS num datacenter AWS metropolitano — os dados ficam num site AWS, não no datacenter do banco.",
     "C": "VPC peering + VPN conecta a nuvem ao on-prem, mas exigiria o banco gerenciar todo o stack on-prem (sem APIs AWS nativas para EC2/EBS lá).",
     "D": "Direct Connect é só um link de rede privado para a Region — não traz hardware nem APIs AWS para dentro do datacenter."
    },
    "keyConcept": "AWS Outposts — extensão da AWS para datacenter do cliente",
    "compareWith": [
     "Outposts rack vs Outposts server",
     "Outposts vs Local Zone",
     "Outposts vs Snowball Edge"
    ],
    "realWorldContext": "Bancos centrais e operadoras de saúde com requisitos LGPD/HIPAA estritos usam Outposts para manter PII no perímetro físico.",
    "commonMistakes": "Pensar que Outposts é responsabilidade 100% do cliente — é shared responsibility, AWS gerencia hardware/firmware/atualizações.",
    "tutorSeeds": [
     "Quais serviços AWS rodam nativamente no Outposts hoje?",
     "Qual a diferença entre Outposts rack e Outposts servers?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["global-infra","outposts","data-residency","hybrid"]'::jsonb, 'ai-draft', 'active', now(), now()
)
