INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-003', 'aws-clf', 'Sobre Edge Locations do CloudFront e o SLA da Region, qual afirmação está CORRETA?',
  '[{"id":"A","text":"Edge Locations contam para o cálculo de uptime da Region em que estão fisicamente localizadas"},{"id":"B","text":"Edge Locations herdam o SLA da Region parent automaticamente"},{"id":"C","text":"Edge Locations têm um SLA próprio do CloudFront (99,9% mensal) e não impactam o SLA da Region"},{"id":"D","text":"Edge Locations não têm SLA — são best-effort"}]'::jsonb, 'C',
  '{
    "summary": "Edge Locations pertencem ao serviço CloudFront e têm SLA próprio. Não fazem parte do escopo de uma Region nem do SLA da Region.",
    "whyCorrect": "CloudFront tem Service Level Agreement próprio (99.9% mensal de disponibilidade) que cobre os POPs (Edge Locations) globalmente. Uma indisponibilidade num Edge não viola o SLA da Region — são camadas independentes. Regions são compostas só de AZs.",
    "whyWrong": {
     "A": "Edge Locations não são parte de uma Region — uma Region é definida pelas suas AZs (mínimo 3 AZs).",
     "B": "Não há herança automática de SLA; cada serviço AWS define o seu próprio acordo de nível de serviço.",
     "D": "CloudFront tem SLA formal de 99.9%/99.0% mensal, não é best-effort."
    },
    "keyConcept": "Region = AZs apenas; Edge Locations são camada separada",
    "compareWith": [
     "Region SLA vs CloudFront SLA",
     "AZ vs Edge Location"
    ],
    "realWorldContext": "Equipes que dependem só de CloudFront sem origin em Region elegível ainda precisam observar o SLA do CloudFront separadamente.",
    "commonMistakes": "Tratar ''tudo da AWS'' como um SLA unificado — cada serviço (S3, EC2, RDS, CloudFront) tem SLA próprio.",
    "tutorSeeds": [
     "Quais são as cláusulas exatas do SLA do CloudFront?",
     "Como o SLA composto de múltiplos serviços é calculado?"
    ]
   }'::jsonb,
