INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-004', 'aws-clf', 'Uma empresa de mídia precisa transmitir o final de um reality show ao vivo para 50 milhões de espectadores no Brasil. Eles usam MediaLive na Region sa-east-1 e CloudFront para distribuição. Quem garante a baixa latência percebida pelos espectadores em cidades como Manaus, Belém e Cuiabá?',
  '[{"id":"A","text":"Availability Zones adicionais em sa-east-1"},{"id":"B","text":"Local Zones em Manaus, Belém e Cuiabá"},{"id":"C","text":"Wavelength Zones em parceria com operadoras"},{"id":"D","text":"Edge Locations do CloudFront espalhadas pelo Brasil"}]'::jsonb, 'D',
  '{
    "summary": "Para distribuição massiva de conteúdo HTTP/HLS, os Edge Locations do CloudFront fazem cache do stream próximo do espectador, reduzindo latência percebida.",
    "whyCorrect": "CloudFront tem POPs (Edge Locations) em São Paulo, Rio, Fortaleza, Brasília, entre outras — para HLS/DASH live streaming, o segmento é servido do Edge mais próximo do espectador. Isso é o caso canônico de uso: distribuição global de conteúdo HTTP.",
    "whyWrong": {
     "A": "Mais AZs em sa-east-1 ajudam HA do MediaLive, mas não reduzem latência para espectadores em capitais distantes — eles ainda precisariam atravessar a internet até São Paulo.",
     "B": "Local Zones servem para apps interativas (gaming, VFX, mídia profissional) — não são a ferramenta para distribuição de conteúdo via cache HTTP.",
     "C": "Wavelength serve apps móveis 5G de ultra-baixa latência — broadcast HLS para 50M é caso de CDN clássico."
    },
    "keyConcept": "CloudFront Edge Location — CDN para distribuição HTTP global",
    "compareWith": [
     "Edge Location vs Local Zone para mídia",
     "CloudFront vs Global Accelerator"
    ],
    "realWorldContext": "Globoplay, GloboPlay+ e outras plataformas usam CloudFront com MediaLive/MediaPackage para finais de reality e Copa.",
    "commonMistakes": "Achar que ''baixa latência'' sempre = Wavelength/Local Zone. Para mídia HTTP, CDN é a resposta certa.",
    "tutorSeeds": [
     "Como funciona o origin shield do CloudFront para reduzir carga na origem?",
     "Qual a diferença entre CloudFront e Global Accelerator para latência?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["global-infra","cloudfront","edge","media"]'::jsonb, 'ai-draft', 'active', now(), now()
)
