INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-005', 'aws-clf', 'Qual variante da infraestrutura global AWS é projetada para clientes do governo dos EUA com workloads classificados, isolada fisicamente das Regions comerciais e operada apenas por cidadãos americanos?',
  '[{"id":"A","text":"AWS GovCloud (US-East e US-West)"},{"id":"B","text":"AWS Regions us-east-1 e us-west-2"},{"id":"C","text":"AWS Outposts"},{"id":"D","text":"AWS Local Zones nos Estados Unidos"}]'::jsonb, 'A',
  '{
    "summary": "AWS GovCloud é uma partição isolada (us-gov-east-1, us-gov-west-1) para workloads sensíveis do governo americano, com acesso restrito a US persons.",
    "whyCorrect": "GovCloud é uma partição separada (ARNs começam com arn:aws-us-gov:), com isolamento físico/lógico das Regions comerciais, suporte a ITAR/FedRAMP High, DoD SRG IL2-5, CJIS, e é operada exclusivamente por US citizens. Conta separada do AWS comercial.",
    "whyWrong": {
     "B": "Regions comerciais us-east-1/us-west-2 não atendem requisitos ITAR/CJIS por padrão e não têm restrição de operação por nacionalidade.",
     "C": "Outposts é hardware AWS no datacenter do cliente — não é uma partição soberana.",
     "D": "Local Zones são extensões metro das Regions comerciais, sem isolamento para classified workloads."
    },
    "keyConcept": "Partições AWS — aws (comercial), aws-us-gov (GovCloud), aws-cn (China)",
    "compareWith": [
     "Partição comercial vs GovCloud vs China"
    ],
    "realWorldContext": "DoD, NASA, e contratantes federais como Lockheed Martin usam GovCloud para missões classificadas.",
    "commonMistakes": "Achar que GovCloud é só uma Region ''normal'' com mais compliance — é uma partição totalmente separada com endpoints próprios.",
    "tutorSeeds": [
     "Quais compliance frameworks o GovCloud atende?",
     "Como funciona o billing/conta no GovCloud?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["global-infra","govcloud","compliance","partitions"]'::jsonb, 'ai-draft', 'active', now(), now()
)
