INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-006', 'aws-clf', 'AWS Regions na China (Beijing e Ningxia) têm uma característica única em relação às Regions comerciais. Qual é?',
  '[{"id":"A","text":"São operadas diretamente pela AWS Inc. com staff americano local"},{"id":"B","text":"São operadas por parceiros chineses (Sinnet em Beijing, NWCD em Ningxia) e exigem conta separada"},{"id":"C","text":"Estão na mesma partição da aws comercial, apenas com endpoints diferenciados"},{"id":"D","text":"São idênticas às Regions globais, sujeitas aos mesmos termos de uso"}]'::jsonb, 'B',
  '{
    "summary": "Por exigência legal chinesa, as Regions na China são operadas por parceiros locais com conta separada (partição aws-cn).",
    "whyCorrect": "Beijing Region é operada pela Sinnet, Ningxia pela NWCD (Ningxia Western Cloud Data Technology). Por regulação chinesa, cloud providers estrangeiros não podem operar diretamente — daí o modelo de parceria. Clientes precisam de conta AWS China separada, ARN com prefixo aws-cn.",
    "whyWrong": {
     "A": "AWS Inc. não opera diretamente — são operadas por parceiros chineses.",
     "C": "Estão em partição separada (aws-cn), não na partição comercial (aws).",
     "D": "Termos de uso e contrato são diferentes — contrato com Sinnet/NWCD, não com AWS Inc."
    },
    "keyConcept": "Partição aws-cn — operação local obrigatória",
    "compareWith": [
     "aws vs aws-cn vs aws-us-gov"
    ],
    "realWorldContext": "Empresas multinacionais com operação na China (ex: SaaS B2B) precisam estabelecer entidade local e conta AWS China separada.",
    "commonMistakes": "Tentar usar conta AWS global para acessar recursos em cn-north-1 — não funciona, é partição isolada.",
    "tutorSeeds": [
     "Quais serviços AWS estão disponíveis nas Regions da China?",
     "Como funciona transferência de dados entre AWS China e AWS global?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["global-infra","china","partitions","compliance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
