INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-007', 'aws-clf', 'Uma startup quer rodar um app de baixa latência só para usuários de Miami e Orlando, mas o serviço precisa de instâncias EC2 GPU para inferência de ML em tempo real (visão computacional). Qual opção da infraestrutura global é mais adequada?',
  '[{"id":"A","text":"Edge Location de CloudFront em Miami"},{"id":"B","text":"Region us-east-1 (N. Virginia) — está ''perto o suficiente''"},{"id":"C","text":"AWS Local Zone em Miami"},{"id":"D","text":"AWS Wavelength Zone — Miami é cidade grande"}]'::jsonb, 'C',
  '{
    "summary": "Local Zones permitem rodar EC2 (incluindo GPUs) próximo a populações específicas, ideal para apps de baixa latência metro.",
    "whyCorrect": "AWS Local Zone Miami (e Local Zones em geral) é exatamente o caso: rodar EC2 (inclusive tipos GPU), EBS, ELB, RDS, ECS, EKS próximo de uma cidade específica, conectado à Region parent (us-east-1). Latência single-digit ms para usuários da metro.",
    "whyWrong": {
     "A": "Edge Locations não rodam EC2 GPU — fazem cache HTTP e funções Lambda@Edge limitadas.",
     "B": "us-east-1 fica em N. Virginia — ~50-70ms para Miami, muito para inferência em tempo real.",
     "D": "Wavelength serve para apps 5G mobile, não para web/PC normal. Local Zone é mais adequada para o caso descrito."
    },
    "keyConcept": "Local Zone — extensão metro da Region com EC2 completo",
    "compareWith": [
     "Local Zone vs Wavelength vs Edge Location"
    ],
    "realWorldContext": "Estúdios de Hollywood usam Local Zone LA para renderização de VFX com baixa latência aos artistas.",
    "commonMistakes": "Achar que Local Zone é só ''mini-Region'' — tem subset de serviços, não todos.",
    "tutorSeeds": [
     "Quais serviços AWS rodam dentro de uma Local Zone?",
     "Como o tráfego entre Local Zone e Region parent é cobrado?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["global-infra","local-zone","low-latency"]'::jsonb, 'ai-draft', 'active', now(), now()
)
