INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-008', 'aws-clf', 'Sobre Availability Zones (AZs) dentro de uma Region, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"AZs num Region compartilham o mesmo datacenter físico para reduzir latência"},{"id":"B","text":"Cada AZ é um único rack dentro de um datacenter AWS"},{"id":"C","text":"Apenas Regions premium têm múltiplas AZs; as menores têm AZ única"},{"id":"D","text":"AZs são datacenters isolados em distância física (geralmente dezenas de km), interligados por fibra dedicada de baixa latência"}]'::jsonb, 'D',
  '{
    "summary": "Cada AZ é um ou mais datacenters fisicamente separados (10s de km), com energia/refrigeração/network independentes, interligados por fibra com latência <2 ms.",
    "whyCorrect": "AWS define AZ como um ou mais datacenters discretos com energia, networking e conectividade redundantes. Separação física é dezenas de quilômetros para resistir a falhas localizadas (incêndio, enchente), mas próxima o suficiente para latência intra-AZ <2 ms.",
    "whyWrong": {
     "A": "AZs no mesmo datacenter aniquilariam a proposta de isolamento de falhas.",
     "B": "AZ não é um rack — é um ou mais datacenters completos.",
     "C": "Todas as Regions AWS comerciais têm no mínimo 3 AZs (modelo padrão de design)."
    },
    "keyConcept": "AZ — fault domain isolado, interligação por fibra <2 ms",
    "compareWith": [
     "AZ vs Region",
     "AZ vs datacenter único"
    ],
    "realWorldContext": "Multi-AZ deployments do RDS replicam sincronamente entre 2 AZs para tolerar falha de DC inteiro.",
    "commonMistakes": "Confundir AZ com ''andar do prédio'' ou ''sala de servidores'' — é datacenter independente.",
    "tutorSeeds": [
     "Como é a topologia de rede entre AZs (latência típica)?",
     "Por que AWS usa AZ-id (use1-az1) em vez de só o nome (us-east-1a)?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["global-infra","availability-zone","fault-tolerance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
