INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-010', 'aws-clf', 'Sobre AWS Outposts servers (1U/2U) vs Outposts racks (42U), qual diferença é CORRETA?',
  '[{"id":"A","text":"Outposts servers oferecem os mesmos serviços que Outposts racks, com mesma capacidade"},{"id":"B","text":"Outposts servers são menores (1U/2U), com subset reduzido de serviços (EC2, ECS, EBS local), ideais para sites remotos como fábricas e lojas"},{"id":"C","text":"Outposts racks só podem ser instalados em datacenters AWS, não no cliente"},{"id":"D","text":"Outposts servers exigem datacenter dedicado de 50m²; racks não"}]'::jsonb, 'B',
  '{
    "summary": "Outposts servers (1U/2U) são form factor pequeno para sites com pouco espaço (lojas, fábricas, branches), com subset de serviços. Racks são para datacenters reais.",
    "whyCorrect": "Outposts servers atendem casos onde 42U seria exagero: lojas de varejo, fábricas, plataformas marítimas, branches bancárias. Oferecem EC2, ECS, EBS local, mas não todos os serviços do rack. Racks são entregues para datacenters tradicionais.",
    "whyWrong": {
     "A": "Capacidades diferentes — servers têm menos compute/storage e subset menor de serviços.",
     "C": "Outposts racks são instalados no cliente — esse é o propósito.",
     "D": "É o oposto — servers cabem em qualquer rack 19''; racks exigem mais infraestrutura."
    },
    "keyConcept": "Outposts servers vs racks — form factor",
    "compareWith": [
     "Outposts servers vs racks",
     "Outposts vs Snowball Edge"
    ],
    "realWorldContext": "Redes de farmácia como CVS instalam Outposts servers em centenas de lojas para processamento local de receitas.",
    "commonMistakes": "Confundir Outposts servers com Snowball Edge — Snowball é appliance de migração de dados, Outposts é compute permanente.",
    "tutorSeeds": [
     "Quais cargas de trabalho típicas rodam em Outposts servers vs racks?",
     "Como funciona o failover se a conexão com a Region parent cair?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["global-infra","outposts","hybrid"]'::jsonb, 'ai-draft', 'active', now(), now()
)
