INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-011', 'aws-clf', 'Quantas Availability Zones, no mínimo, uma AWS Region comercial tem na arquitetura padrão atual da AWS?',
  '[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"5"}]'::jsonb, 'C',
  '{
    "summary": "AWS exige no mínimo 3 AZs para uma Region comercial, possibilitando quorum em sistemas como Aurora e MSK.",
    "whyCorrect": "Desde anos atrás, AWS lança novas Regions com no mínimo 3 AZs. Esse mínimo permite quorum de 2-de-3 em sistemas distribuídos (Aurora storage layer, Amazon MSK, S3), sustentando alta disponibilidade mesmo com perda de uma AZ inteira.",
    "whyWrong": {
     "A": "Region com 1 AZ não permitiria HA — não atende padrão AWS.",
     "B": "2 AZs não permitem quorum simples — split-brain em caso de partição.",
     "D": "Algumas Regions têm 5+ AZs (us-east-1 tem 6), mas não é o mínimo padrão."
    },
    "keyConcept": "Region — mínimo 3 AZs para quorum",
    "compareWith": [
     "Region com 3 AZs vs 6 AZs (us-east-1)"
    ],
    "realWorldContext": "Para deploy Aurora cluster (writer + 2 read replicas em 3 AZs), você precisa mínimo de 3 AZs.",
    "commonMistakes": "Achar que 2 AZs bastam para HA — só com quorum (3) o sistema sobrevive a falha sem split-brain.",
    "tutorSeeds": [
     "Quais Regions têm mais AZs hoje?",
     "Por que us-east-1 tem 6 AZs e sa-east-1 tem 3?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["global-infra","availability-zone","region"]'::jsonb, 'ai-draft', 'active', now(), now()
)
