INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-012', 'aws-clf', 'Um CTO está escolhendo Region para uma nova aplicação. Quais fatores fazem parte dos critérios canônicos de seleção de Region segundo a AWS? Selecione a opção mais completa.',
  '[{"id":"A","text":"Apenas preço por hora de EC2"},{"id":"B","text":"Cor do logo da Region e idade do datacenter"},{"id":"C","text":"Apenas conformidade de dados (LGPD, GDPR)"},{"id":"D","text":"Latência, conformidade/soberania de dados, preço, disponibilidade de serviços e sustentabilidade"}]'::jsonb, 'D',
  '{
    "summary": "AWS lista 5 critérios de Region selection: latência aos usuários, conformidade/regulação, preço, disponibilidade de serviços e (desde 2021) sustentabilidade.",
    "whyCorrect": "A documentação oficial enumera: (1) Latency — proximidade aos usuários; (2) Compliance — leis de soberania; (3) Pricing — varia entre Regions; (4) Service availability — nem todo serviço lança em todas as Regions ao mesmo tempo; (5) Sustainability — matriz energética e pegada de carbono.",
    "whyWrong": {
     "A": "Reduzir a só preço ignora compliance, latência e disponibilidade de serviços — pode ser barato e ilegal.",
     "B": "Distratorial humorístico — não são critérios reais.",
     "C": "Compliance é importante, mas não único; ignora latência, custo, etc."
    },
    "keyConcept": "Region selection — 5 critérios canônicos",
    "compareWith": [
     "Region selection: cost-driven vs compliance-driven"
    ],
    "realWorldContext": "Empresas com clientes em UE escolhem eu-west-1/eu-central-1 (GDPR) em vez de us-east-1 mesmo que mais cara.",
    "commonMistakes": "Escolher us-east-1 ''porque é mais barata'' sem considerar latência aos usuários e regulação local.",
    "tutorSeeds": [
     "Como o Customer Carbon Footprint Tool ajuda na decisão por sustentabilidade?",
     "Quais serviços costumam demorar mais a lançar em sa-east-1?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'best-practice', '["global-infra","region-selection"]'::jsonb, 'ai-draft', 'active', now(), now()
)
