INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-013', 'aws-clf', 'Qual dos seguintes é um design principle GENERAL do Well-Architected Framework (aplicável a TODOS os pilares)?',
  '[{"id":"A","text":"Stop guessing your capacity needs"},{"id":"B","text":"Implement strong identity foundation"},{"id":"C","text":"Optimize over time"},{"id":"D","text":"Use multiple Availability Zones"}]'::jsonb, 'A',
  '{
    "summary": "Os General Design Principles do Well-Architected (introdução) incluem: stop guessing capacity, test at production scale, automate, allow for evolutionary architecture, drive arch via data, improve via game days.",
    "whyCorrect": "''Stop guessing your capacity needs'' é um dos 7 General Design Principles listados na introdução do Well-Architected Framework — aplicável a todos pilares. Auto Scaling/elasticity materializam esse princípio.",
    "whyWrong": {
     "B": "Strong identity foundation é design principle ESPECÍFICO do pilar Security.",
     "C": "''Optimize over time'' é princípio do pilar Sustainability (especificamente Region selection, etc.).",
     "D": "Multi-AZ é prática concreta, não um princípio geral nomeado."
    },
    "keyConcept": "Well-Architected — General Design Principles (7 princípios cross-pilar)",
    "compareWith": [
     "General principles vs pillar-specific principles"
    ],
    "realWorldContext": "Empresas que migram de on-prem para AWS aplicam ''stop guessing capacity'' substituindo dimensionamento estático por Auto Scaling.",
    "commonMistakes": "Confundir princípio geral com princípio de um pilar específico (cada pilar tem seu próprio conjunto).",
    "tutorSeeds": [
     "Quais são os 7 General Design Principles completos?",
     "Como ''game days'' se encaixam nesse contexto?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["well-architected","design-principles"]'::jsonb, 'ai-draft', 'active', now(), now()
)
