INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-014', 'aws-clf', 'Uma empresa SaaS multi-tenant quer revisar a arquitetura sob a ótica específica de isolamento de tenants, billing per-tenant e onboarding automatizado. Qual lens do Well-Architected é mais aplicável?',
  '[{"id":"A","text":"Serverless Applications Lens"},{"id":"B","text":"SaaS Lens"},{"id":"C","text":"Financial Services Industry Lens"},{"id":"D","text":"Machine Learning Lens"}]'::jsonb, 'B',
  '{
    "summary": "SaaS Lens cobre práticas específicas para arquiteturas multi-tenant: isolamento, tenant onboarding, métricas/billing per-tenant, identity per-tenant.",
    "whyCorrect": "A SaaS Lens do Well-Architected aborda tópicos canônicos de SaaS: tenant isolation models (silo, pool, hybrid), tenant identity, metering/billing, deployment per tenant. É a lens-pergunta certa para SaaS.",
    "whyWrong": {
     "A": "Serverless Lens trata de Lambda/API Gateway/Step Functions, mas não cobre o domínio multi-tenant específico.",
     "C": "FSI Lens trata de bancos/seguradoras (compliance financeiro), não multi-tenancy genérico.",
     "D": "ML Lens trata de pipelines ML (treino, deploy, monitoring), não SaaS multi-tenant."
    },
    "keyConcept": "Well-Architected Lenses — extensões por domínio",
    "compareWith": [
     "SaaS Lens vs Serverless Lens",
     "FSI Lens vs Healthcare Lens"
    ],
    "realWorldContext": "Empresas como Salesforce, Zendesk e Shopify aplicam SaaS Lens nas suas plataformas.",
    "commonMistakes": "Pensar que ''serverless'' = ''SaaS'' — uma plataforma SaaS pode ser serverless, mas tem requisitos multi-tenant adicionais.",
    "tutorSeeds": [
     "Quais são as 9+ Lenses do Well-Architected hoje?",
     "Como combinar múltiplas Lenses (SaaS + Serverless) na revisão?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["well-architected","lens","saas","multi-tenant"]'::jsonb, 'ai-draft', 'active', now(), now()
)
