INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-015', 'aws-clf', 'Sobre o AWS Well-Architected Tool (ferramenta no Console), qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"É um serviço pago por workload analisado"},{"id":"B","text":"Substitui o AWS Trusted Advisor para auditoria de conta"},{"id":"C","text":"É gratuito e permite revisar workloads contra os 6 pilares e gerar planos de melhoria"},{"id":"D","text":"Só está disponível para clientes Enterprise Support"}]'::jsonb, 'C',
  '{
    "summary": "AWS Well-Architected Tool é gratuito, disponível no Console, e permite revisar workloads contra pilares + Lenses, gerar relatórios e tracking de melhorias.",
    "whyCorrect": "WA Tool é um serviço no Console (gratuito) onde você define um workload, responde checklist por pilar/lens, e o sistema gera High Risk Issues (HRIs) e Medium Risk Issues (MRIs) com plano de melhoria. Suporta múltiplas Lenses (SaaS, Serverless, etc).",
    "whyWrong": {
     "A": "É gratuito — sem cobrança por workload.",
     "B": "Trusted Advisor e WA Tool são complementares: Trusted Advisor olha conta inteira (real-time checks); WA Tool faz revisão arquitetural manual de workload.",
     "D": "Disponível para todas as contas, independente do plano de suporte."
    },
    "keyConcept": "Well-Architected Tool — gratuito, no Console",
    "compareWith": [
     "WA Tool vs Trusted Advisor"
    ],
    "realWorldContext": "Times de arquitetura agendam revisões trimestrais de workloads no WA Tool e tratam HRIs como backlog técnico.",
    "commonMistakes": "Achar que WA Tool é automático — exige preencher questionário manualmente.",
    "tutorSeeds": [
     "Como o WA Tool calcula a contagem de HRIs?",
     "Como exportar relatório do WA Tool em PDF?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["well-architected","wa-tool"]'::jsonb, 'ai-draft', 'active', now(), now()
)
