INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-016', 'aws-clf', 'Pilar Reliability tem como design principle ''Test recovery procedures''. Qual técnica AWS é referência canônica desse princípio?',
  '[{"id":"A","text":"Code review obrigatório em PRs"},{"id":"B","text":"Backup automático no S3 Glacier"},{"id":"C","text":"Monitoring com CloudWatch dashboards"},{"id":"D","text":"Game Days e Chaos Engineering com AWS Fault Injection Service (FIS)"}]'::jsonb, 'D',
  '{
    "summary": "Game Days e Chaos Engineering (com AWS Fault Injection Service) testam ativamente os procedimentos de recuperação injetando falhas controladas.",
    "whyCorrect": "Reliability pillar pede ''test recovery procedures'' — não basta ter runbook, é preciso exercitar. AWS FIS injeta falhas (kill EC2, network latency, API errors) para validar que o sistema se recupera. Game Days são exercícios planejados onde a equipe simula incidentes.",
    "whyWrong": {
     "A": "Code review trata de qualidade de código antes do deploy, não de recuperação.",
     "B": "Backup é parte da recuperação, mas não testa o procedimento — só armazena dados.",
     "C": "Monitoring detecta problema, mas não valida recovery."
    },
    "keyConcept": "Chaos Engineering — testar recovery proativamente",
    "compareWith": [
     "FIS vs Chaos Monkey",
     "Game Day vs DR drill"
    ],
    "realWorldContext": "Netflix popularizou Chaos Monkey; AWS lançou FIS em 2021 como serviço gerenciado equivalente.",
    "commonMistakes": "Achar que ''ter backup'' = recovery testado. Backup sem teste de restore é placebo.",
    "tutorSeeds": [
     "Quais experimentos típicos rodam em AWS FIS?",
     "Como integrar FIS em pipeline CI/CD?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["well-architected","reliability","chaos-engineering","fis"]'::jsonb, 'ai-draft', 'active', now(), now()
)
