INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-017', 'aws-clf', 'Qual dos 6 pilares do Well-Architected Framework tem como design principle específico ''Implement a strong identity foundation''?',
  '[{"id":"A","text":"Security"},{"id":"B","text":"Operational Excellence"},{"id":"C","text":"Reliability"},{"id":"D","text":"Cost Optimization"}]'::jsonb, 'A',
  '{
    "summary": "Strong identity foundation é design principle #1 do pilar Security — princípio de least privilege, separação de duties, identidade centralizada.",
    "whyCorrect": "Security pillar lista 7 design principles, sendo o primeiro ''Implement a strong identity foundation'' (princípio de least privilege, evitar long-lived credentials, identidade central via IAM Identity Center).",
    "whyWrong": {
     "B": "Op Excellence trata de operação (runbooks, observabilidade, IaC).",
     "C": "Reliability trata de recovery, fault isolation, scalability.",
     "D": "Cost Optimization trata de pricing model, right-sizing, expenditure awareness."
    },
    "keyConcept": "Security Pillar — 7 design principles, identity foundation #1",
    "compareWith": [
     "Security DP vs Reliability DP"
    ],
    "realWorldContext": "Empresas implementam IAM Identity Center (ex-SSO) como base de identidade federada para o princípio.",
    "commonMistakes": "Confundir ''security'' com só ''encryption'' — identity é a base.",
    "tutorSeeds": [
     "Quais são os 7 design principles do Security Pillar?",
     "Como AWS recomenda zero trust no Security Pillar?"
    ]
   }'::jsonb,
