INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-018', 'aws-clf', 'Sobre o pilar Sustainability (adicionado em 2021), qual NÃO é um de seus design principles?',
  '[{"id":"A","text":"Understand your impact"},{"id":"B","text":"Maximize uptime to 100%"},{"id":"C","text":"Establish sustainability goals"},{"id":"D","text":"Maximize utilization"}]'::jsonb, 'B',
  '{
    "summary": "Maximizar uptime para 100% NÃO é um princípio de Sustainability — pertenceria mais a Reliability, e tampouco é alcançável.",
    "whyCorrect": "Os 6 design principles do Sustainability pillar são: Understand your impact, Establish sustainability goals, Maximize utilization, Anticipate and adopt new more efficient hw/sw, Use managed services, Reduce downstream impact of cloud workloads. ''Maximize uptime'' não está nessa lista.",
    "whyWrong": {
     "A": "É de fato um dos 6 design principles do Sustainability.",
     "C": "É um dos 6 — definir metas SMART de redução de impacto ambiental.",
     "D": "Sim — maximizar utilização (CPU, storage, network) reduz waste e portanto pegada."
    },
    "keyConcept": "Sustainability — 6 design principles",
    "compareWith": [
     "Sustainability DPs vs Reliability DPs"
    ],
    "realWorldContext": "Empresas usam Customer Carbon Footprint Tool para medir e definir metas (DP #1 e #2).",
    "commonMistakes": "Confundir Reliability (uptime) com Sustainability (uso eficiente de recursos).",
    "tutorSeeds": [
     "Quais são os 6 design principles do Sustainability detalhados?",
     "Como ''use managed services'' reduz pegada?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["well-architected","sustainability","design-principles"]'::jsonb, 'ai-draft', 'active', now(), now()
)
