INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-019', 'aws-clf', 'Performance Efficiency tem como design principle ''go global in minutes''. Qual serviço AWS materializa diretamente esse princípio?',
  '[{"id":"A","text":"AWS Trusted Advisor"},{"id":"B","text":"AWS Cost Explorer"},{"id":"C","text":"Multi-Region deployment com CloudFront e Route 53 latency-based routing"},{"id":"D","text":"AWS Backup"}]'::jsonb, 'C',
  '{
    "summary": "Deploy multi-Region com CloudFront global e Route 53 latency-based é a materialização canônica de ''go global in minutes''.",
    "whyCorrect": "O princípio reflete a capacidade de a nuvem permitir presença global em minutos via Regions, AZs, Edge Locations, CloudFront, e roteamento por latência (Route 53). Não exige construir DCs em cada continente.",
    "whyWrong": {
     "A": "Trusted Advisor faz checks na conta — não tem relação direta com global reach.",
     "B": "Cost Explorer analisa gastos — não está no escopo de Performance Efficiency.",
     "D": "AWS Backup faz gestão de backups — não é sobre alcance global."
    },
    "keyConcept": "Go global in minutes — design principle de Performance Efficiency",
    "compareWith": [
     "Performance Efficiency DPs vs Reliability DPs"
    ],
    "realWorldContext": "Startups SaaS expandem para Ásia/Europa com poucos cliques (deploy em ap-southeast-1, eu-west-1 + CloudFront).",
    "commonMistakes": "Confundir ''go global'' com latência só — envolve presença e conformidade também.",
    "tutorSeeds": [
     "Quais os 5 design principles do Performance Efficiency?",
     "Como Route 53 latency-based routing funciona internamente?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["well-architected","performance-efficiency","global"]'::jsonb, 'ai-draft', 'active', now(), now()
)
