INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-020', 'aws-clf', 'Operational Excellence cita ''perform operations as code'' como design principle. Qual prática NÃO se encaixa nesse princípio?',
  '[{"id":"A","text":"Infrastructure as Code com CloudFormation ou CDK"},{"id":"B","text":"Runbooks executáveis via AWS Systems Manager Automation"},{"id":"C","text":"Pipelines CI/CD com CodePipeline"},{"id":"D","text":"Configuração manual da console por engenheiro on-call em cada incidente"}]'::jsonb, 'D',
  '{
    "summary": "Configuração manual é o oposto de ''operations as code'' — viola o princípio por introduzir erro humano e impedir reprodutibilidade.",
    "whyCorrect": "''Operations as code'' significa tratar runbooks, infraestrutura e procedures como software (versionados, testados, auditáveis). Click-ops em incidente é exatamente o anti-padrão que o princípio combate.",
    "whyWrong": {
     "A": "IaC é a essência do princípio — definir infra como código versionável.",
     "B": "SSM Automation transforma runbooks em código executável.",
     "C": "CI/CD automatiza deploys — encaixa diretamente no princípio."
    },
    "keyConcept": "Operations as Code — IaC, runbooks-as-code, CI/CD",
    "compareWith": [
     "Click-ops vs Ops-as-code"
    ],
    "realWorldContext": "Equipes maduras proíbem mudança manual em produção via SCPs (Service Control Policies) que bloqueiam IAM de usuário humano em prod.",
    "commonMistakes": "Achar que ''só código de infra basta'' — runbooks operacionais também precisam ser código.",
    "tutorSeeds": [
     "Quais ferramentas AWS suportam runbooks-as-code?",
     "Como medir maturidade em Operations as Code?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["well-architected","operational-excellence","iac"]'::jsonb, 'ai-draft', 'active', now(), now()
)
