INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-021', 'aws-clf', 'Cost Optimization tem ''Adopt a consumption model'' como design principle. Qual prática viola esse princípio?',
  '[{"id":"A","text":"Reservar 100 EC2 on-demand ''só por garantia'' rodando 24/7 mesmo com tráfego intermitente"},{"id":"B","text":"Usar Spot Instances para jobs batch interrompíveis"},{"id":"C","text":"Auto Scaling baseado em CloudWatch metrics"},{"id":"D","text":"Lambda para workloads event-driven"}]'::jsonb, 'A',
  '{
    "summary": "Manter 100 EC2 sempre ligadas ''por garantia'' é over-provisioning — viola ''pague pelo que usar''.",
    "whyCorrect": "Consumption model = pague pelo que usa. Manter capacidade ociosa 24/7 ''por garantia'' é o anti-padrão clássico de on-premises trazido pra nuvem, anula o benefício elástico.",
    "whyWrong": {
     "B": "Spot é o exemplo perfeito de consumption — paga quando há capacidade ociosa.",
     "C": "Auto Scaling ajusta capacidade à demanda — encaixe direto do princípio.",
     "D": "Lambda cobra por invocação/ms — pure consumption model."
    },
    "keyConcept": "Consumption model — pay-as-you-go, evite over-provisioning",
    "compareWith": [
     "On-demand vs Reserved vs Spot pricing"
    ],
    "realWorldContext": "Empresas que migram lift-and-shift sem reotimizar frequentemente acabam pagando mais que on-prem por isso.",
    "commonMistakes": "Achar que ''reserva'' é sempre econômica — só compensa para baseline previsível.",
    "tutorSeeds": [
     "Quais os 5 design principles do Cost Optimization?",
     "Quando Savings Plans são melhores que Reserved Instances?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'best-practice', '["well-architected","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
