INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-022', 'aws-clf', 'Uma empresa de saúde precisa de revisão arquitetural com foco em PHI (Protected Health Information), HIPAA e segurança de paciente. Qual Lens do Well-Architected é diretamente aplicável?',
  '[{"id":"A","text":"Financial Services Lens"},{"id":"B","text":"Healthcare Industry Lens"},{"id":"C","text":"Government Lens"},{"id":"D","text":"IoT Lens"}]'::jsonb, 'B',
  '{
    "summary": "Healthcare Industry Lens cobre HIPAA, PHI, interoperabilidade FHIR/HL7, e telemedicina.",
    "whyCorrect": "AWS publica uma Healthcare Industry Lens específica para workloads de saúde, abordando HIPAA-eligible services, padrões FHIR/HL7, dados de paciente, e práticas de telessaúde.",
    "whyWrong": {
     "A": "FSI Lens é para bancos/seguradoras — regulação financeira distinta.",
     "C": "Government Lens trata de FedRAMP, FISMA — não cobre PHI especificamente.",
     "D": "IoT Lens trata de dispositivos conectados — não é foco em saúde."
    },
    "keyConcept": "Healthcare Industry Lens — HIPAA, PHI, FHIR",
    "compareWith": [
     "Healthcare Lens vs FSI Lens"
    ],
    "realWorldContext": "Hospitais como Cleveland Clinic e plataformas de telessaúde usam essa Lens para auditoria.",
    "commonMistakes": "Achar que ''compliance HIPAA'' = só usar serviços HIPAA-eligible — a Lens cobre arquitetura completa.",
    "tutorSeeds": [
     "Quais serviços AWS são HIPAA-eligible hoje?",
     "Como funciona o BAA (Business Associate Agreement) entre AWS e cliente de saúde?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["well-architected","lens","healthcare","hipaa"]'::jsonb, 'ai-draft', 'active', now(), now()
)
