INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-023', 'aws-clf', 'Sobre Shared Responsibility Model aplicado ao Amazon S3, qual responsabilidade é do CLIENTE (não da AWS)?',
  '[{"id":"A","text":"Patch do sistema operacional dos servidores físicos que armazenam objetos"},{"id":"B","text":"Durabilidade dos 11 noves (99,999999999%) dos dados armazenados"},{"id":"C","text":"Configurar bucket policies, criptografia em repouso (SSE-KMS) e bloqueio de acesso público"},{"id":"D","text":"Gerenciar a infraestrutura física dos datacenters S3"}]'::jsonb, 'C',
  '{
    "summary": "No S3, AWS cuida da infra/durabilidade; cliente cuida de policies, criptografia opcional, ACLs, classificação dos dados e quem acessa.",
    "whyCorrect": "S3 é serviço gerenciado: AWS opera hardware, OS, durabilidade. Cliente é responsável por security IN the cloud — bucket policies, KMS keys, Block Public Access, S3 Object Lock, versioning, e classificação dos dados.",
    "whyWrong": {
     "A": "Patch de OS dos servidores é AWS — cliente não tem acesso a esse nível.",
     "B": "Durabilidade é compromisso AWS via design do S3 (multi-AZ por padrão).",
     "D": "Infraestrutura física é 100% AWS."
    },
    "keyConcept": "Shared Responsibility — S3 (managed service)",
    "compareWith": [
     "S3 vs EC2 shared responsibility",
     "Security OF cloud vs IN cloud"
    ],
    "realWorldContext": "Vazamentos de S3 quase sempre vêm de bucket público mal configurado — responsabilidade do cliente.",
    "commonMistakes": "Achar que AWS criptografa automaticamente todo objeto — depende de configuração; bucket pode ter encryption padrão habilitada.",
    "tutorSeeds": [
     "Como S3 Block Public Account-level funciona?",
     "Qual a diferença entre SSE-S3, SSE-KMS e SSE-C?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["shared-responsibility","s3","security"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
