INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-024', 'aws-clf', 'No Amazon RDS for PostgreSQL, qual responsabilidade é da AWS (não do cliente)?',
  '[{"id":"A","text":"Configurar regras do parameter group para max_connections"},{"id":"B","text":"Definir schema das tabelas e queries SQL"},{"id":"C","text":"Gerenciar usuários e roles dentro do banco"},{"id":"D","text":"Aplicar minor version patches da engine PostgreSQL conforme janela de manutenção"}]'::jsonb, 'D',
  '{
    "summary": "Em RDS, AWS gerencia a engine, OS e patching. Cliente cuida de schema, queries, usuários do banco e parameter groups.",
    "whyCorrect": "RDS é managed database service: AWS aplica patches do OS, da engine (minor automatic upgrades opcional), faz backups, gerencia replication multi-AZ. Cliente não acessa SSH/RDP da instância — só interage via endpoint SQL e API.",
    "whyWrong": {
     "A": "Parameter groups e tuning são do cliente.",
     "B": "Schema/queries são cargo do cliente (DBA/dev).",
     "C": "Usuários SQL e GRANTs são do cliente."
    },
    "keyConcept": "Shared Responsibility — RDS (managed DB)",
    "compareWith": [
     "RDS vs PostgreSQL em EC2 (self-managed)"
    ],
    "realWorldContext": "Empresas escolhem RDS sobre EC2+PostgreSQL para terceirizar patching e backups.",
    "commonMistakes": "Achar que RDS faz tuning automático — não faz: parameter groups, índices, e queries são do cliente.",
    "tutorSeeds": [
     "Como funciona o auto minor version upgrade no RDS?",
     "Qual a diferença entre RDS e Aurora em termos de shared responsibility?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["shared-responsibility","rds","managed-service"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
