INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-025', 'aws-clf', 'Em AWS Lambda (serverless), qual responsabilidade NÃO é do cliente?',
  '[{"id":"A","text":"Patch da runtime (Node.js, Python, etc.) e do sistema operacional do worker"},{"id":"B","text":"O código da função e suas dependências (libs)"},{"id":"C","text":"IAM execution role da função"},{"id":"D","text":"Configuração de VPC, security groups e variáveis de ambiente da função"}]'::jsonb, 'A',
  '{
    "summary": "Em Lambda, AWS gerencia runtime, OS, scaling. Cliente cuida do código, dependências, IAM role e configurações de execução.",
    "whyCorrect": "Lambda é o exemplo mais ''managed'' do modelo. AWS patches a runtime (Node 20, Python 3.12), OS, mantém versionamento de runtimes (com deprecation notices). Cliente só fornece o código + config.",
    "whyWrong": {
     "B": "Código e libs são 100% cliente.",
     "C": "IAM execution role é configurada pelo cliente.",
     "D": "VPC config, SGs e env vars são responsabilidade do cliente."
    },
    "keyConcept": "Shared Responsibility — Lambda (serverless)",
    "compareWith": [
     "Lambda vs Fargate vs EC2 shared responsibility"
    ],
    "realWorldContext": "Funções Lambda em runtime deprecada são bloqueadas para nova criação após data anunciada — cliente precisa migrar.",
    "commonMistakes": "Achar que ''patch da lib'' do código também é AWS — não, dependências são do cliente.",
    "tutorSeeds": [
     "Como Lambda lida com deprecation de runtime?",
     "Qual a fronteira do shared responsibility no Lambda layers?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["shared-responsibility","lambda","serverless"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
