INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-026', 'aws-clf', 'Em AWS Fargate (ECS/EKS serverless containers), comparado a ECS em EC2, qual diferença de shared responsibility é CORRETA?',
  '[{"id":"A","text":"Em Fargate, o cliente continua gerenciando a EC2 host"},{"id":"B","text":"Em Fargate, AWS gerencia o host (compute infra), enquanto em ECS-on-EC2 o cliente gerencia patching/OS das EC2"},{"id":"C","text":"Não há diferença — ambos exigem manter o OS atualizado"},{"id":"D","text":"Fargate exige SSH na container para atualizações"}]'::jsonb, 'B',
  '{
    "summary": "Fargate elimina a responsabilidade pela EC2 host: AWS provisiona, patcha e escala compute. Em ECS-on-EC2, cliente ainda cuida dos worker nodes.",
    "whyCorrect": "Fargate é ''serverless containers'': não há EC2 visível para o cliente, AWS gerencia toda a infra subjacente. Em ECS-on-EC2 (launch type EC2), o cliente provisiona ECS-optimized AMI EC2s, atualiza-as, monitora capacidade.",
    "whyWrong": {
     "A": "Em Fargate o cliente NÃO gerencia EC2 — essa é a diferença chave.",
     "C": "Há diferença grande — não são equivalentes.",
     "D": "Fargate não suporta SSH em containers (é runtime gerenciado)."
    },
    "keyConcept": "Fargate vs ECS-on-EC2 — fronteira de responsabilidade",
    "compareWith": [
     "Fargate vs Lambda",
     "ECS launch types"
    ],
    "realWorldContext": "Times pequenos preferem Fargate para reduzir overhead operacional; times grandes com workloads custosos podem economizar com ECS-on-EC2 + Spot.",
    "commonMistakes": "Achar que Fargate é só ''mais caro'' — paga-se pela abstração e redução de toil operacional.",
    "tutorSeeds": [
     "Quando ECS-on-EC2 é mais econômico que Fargate?",
     "Como funciona o pricing do Fargate (vCPU + memória + segundos)?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["shared-responsibility","fargate","ecs","containers"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
