INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-027', 'aws-clf', 'Em uma instância EC2 com Amazon Linux 2023, qual responsabilidade é do CLIENTE?',
  '[{"id":"A","text":"Manter o hypervisor Nitro atualizado"},{"id":"B","text":"Garantir a integridade física do servidor"},{"id":"C","text":"Aplicar patches de segurança do sistema operacional (yum/dnf update)"},{"id":"D","text":"Gerenciar o firmware do servidor físico"}]'::jsonb, 'C',
  '{
    "summary": "EC2 é IaaS: AWS gerencia hypervisor/hardware; cliente é responsável por OS guest, patches, agents, software instalado.",
    "whyCorrect": "Patches do OS guest são responsabilidade do cliente em EC2 — usando AWS Systems Manager Patch Manager, SSM Run Command, ou processos próprios. Esse é o exemplo canônico do ''security IN the cloud''.",
    "whyWrong": {
     "A": "Hypervisor Nitro é AWS.",
     "B": "Segurança física é AWS.",
     "D": "Firmware do servidor é AWS."
    },
    "keyConcept": "Shared Responsibility — EC2 (IaaS)",
    "compareWith": [
     "EC2 vs Fargate vs Lambda — quanto AWS gerencia"
    ],
    "realWorldContext": "Vulnerabilidades como Log4Shell exigem o cliente atualizar pacotes no OS — AWS não faz isso na EC2.",
    "commonMistakes": "Achar que AWS aplica security patches automaticamente em EC2 — não aplica, é responsabilidade do cliente.",
    "tutorSeeds": [
     "Como AWS Systems Manager Patch Manager automatiza patching?",
     "Qual a diferença de shared responsibility entre EC2 e Lightsail?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["shared-responsibility","ec2","patching"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
