INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-028', 'aws-clf', 'Em DynamoDB (serverless NoSQL), qual responsabilidade é do CLIENTE?',
  '[{"id":"A","text":"Sharding e particionamento físico dos dados nos hosts"},{"id":"B","text":"Patching do storage engine SSD"},{"id":"C","text":"Replicação automática entre AZs dentro da Region"},{"id":"D","text":"Capacity mode (on-demand vs provisioned), design de partition key, criptografia opcional via CMK"}]'::jsonb, 'D',
  '{
    "summary": "Em DynamoDB, cliente escolhe capacity mode, design da partition key, criptografia via KMS e configurações de tabela. AWS cuida da infra distribuída.",
    "whyCorrect": "DynamoDB é serverless por design. O cliente é responsável por: design de chave primária (partition key + sort key), escolha entre on-demand e provisioned throughput, indexes, criptografia (default ou KMS CMK), e TTL.",
    "whyWrong": {
     "A": "Sharding físico é 100% AWS — abstraído do cliente.",
     "B": "Storage engine é AWS.",
     "C": "Replicação multi-AZ é automática (AWS), 3 réplicas por padrão."
    },
    "keyConcept": "Shared Responsibility — DynamoDB",
    "compareWith": [
     "DynamoDB vs RDS shared responsibility"
    ],
    "realWorldContext": "Hot partition é problema comum quando partition key é mal escolhida — cliente deve redesenhar (não é problema da AWS).",
    "commonMistakes": "Achar que DynamoDB ''resolve tudo'' — mau design de chave gera throttling.",
    "tutorSeeds": [
     "Como funciona o auto-sharding em DynamoDB?",
     "Quando usar on-demand vs provisioned capacity?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["shared-responsibility","dynamodb","nosql"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
