INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-029', 'aws-clf', 'Uma empresa instala AWS Outposts no datacenter. Sobre shared responsibility nesse cenário, qual é VERDADEIRA?',
  '[{"id":"A","text":"AWS continua responsável por hardware, firmware, hipervisor e atualizações do Outposts; cliente é responsável pelo ambiente físico (energia, refrigeração, rede), OS guest, e dados"},{"id":"B","text":"Como o hardware está no DC do cliente, toda a responsabilidade passa a ser do cliente"},{"id":"C","text":"Cliente abre o rack e instala atualizações com técnicos locais"},{"id":"D","text":"AWS instala mas não dá suporte após entrega"}]'::jsonb, 'A',
  '{
    "summary": "Outposts mantém o modelo shared responsibility AWS, com fronteira ajustada: cliente provê espaço físico, energia, refrigeração e rede; AWS opera o hardware/firmware/software.",
    "whyCorrect": "AWS continua dona do hardware Outposts. Atualizações são empurradas pela AWS via Region parent (via service link). Cliente fornece o site físico segundo specs (energia redundante, refrigeração, conexão de rede), e gerencia OS guest/dados (como faz em EC2).",
    "whyWrong": {
     "B": "Hardware/software do Outposts continua AWS — cliente não cuida disso.",
     "C": "Cliente não acessa hardware do Outposts — fica lacrado, atualizações são remotas.",
     "D": "AWS dá suporte e gerencia o Outposts continuamente após instalação."
    },
    "keyConcept": "Outposts — shared responsibility com cliente fornecendo site",
    "compareWith": [
     "Outposts vs Snowball Edge — modelo de responsabilidade"
    ],
    "realWorldContext": "Customer Care AWS coordena instalação inicial e troca de unidades defeituosas no Outposts.",
    "commonMistakes": "Achar que ''no meu DC, eu mando'' — não, AWS continua dona do stack.",
    "tutorSeeds": [
     "Quais especificações de site são exigidas para Outposts rack?",
     "Como funciona o service link entre Outposts e Region parent?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["shared-responsibility","outposts","hybrid"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
