INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-030', 'aws-clf', 'Para qualquer serviço AWS, qual responsabilidade SEMPRE permanece com o CLIENTE, independente do tipo (IaaS, PaaS, serverless)?',
  '[{"id":"A","text":"Manter o hardware físico funcionando"},{"id":"B","text":"Gerenciar quem acessa os dados, classificação dos dados e configuração de IAM"},{"id":"C","text":"Gerenciar o hypervisor"},{"id":"D","text":"Operar os datacenters"}]'::jsonb, 'B',
  '{
    "summary": "Identidade, acesso e classificação de dados sempre são do cliente — é o núcleo do ''security IN the cloud''.",
    "whyCorrect": "Independente do modelo (EC2, Lambda, S3, Fargate), o cliente sempre é responsável por: quem acessa (IAM users/roles/policies), como acessa (MFA, federation), e o que está armazenado (classificação, encryption keys quando aplicável).",
    "whyWrong": {
     "A": "Hardware é sempre AWS.",
     "C": "Hypervisor é AWS.",
     "D": "Datacenter ops é AWS."
    },
    "keyConcept": "Customer responsibility — sempre: identity, access, data classification",
    "compareWith": [
     "Security OF cloud (AWS) vs IN cloud (cliente)"
    ],
    "realWorldContext": "98%+ dos vazamentos AWS reportados são misconfiguration de IAM/S3 — sempre responsabilidade do cliente.",
    "commonMistakes": "Achar que ''AWS é seguro'' = ''minha conta é segura'' — modelo compartilhado exige diligência do cliente.",
    "tutorSeeds": [
     "Quais ferramentas AWS ajudam a validar IAM (least privilege)?",
     "Como Macie ajuda na classificação de dados sensíveis?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'best-practice', '["shared-responsibility","iam","security"]'::jsonb, 'ai-draft', 'active', now(), now()
)
