INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-031', 'aws-clf', 'Uma empresa precisa de RTO de 1 hora e RPO de 5 minutos para um sistema crítico. Qual estratégia de DR é mais adequada (e custo-eficiente)?',
  '[{"id":"A","text":"Backup and Restore"},{"id":"B","text":"Pilot Light"},{"id":"C","text":"Warm Standby"},{"id":"D","text":"Multi-Site Active-Active"}]'::jsonb, 'C',
  '{
    "summary": "Warm Standby mantém uma versão scaled-down rodando na Region de DR, permitindo escalar em minutos. Atende RTO de 1h e RPO baixo.",
    "whyCorrect": "Warm Standby = stack DR sempre rodando, em escala reduzida, com replicação contínua. Failover envolve apenas escalar (Auto Scaling) — RTO típico 10-60 min. Replicação contínua dá RPO baixo (minutos).",
    "whyWrong": {
     "A": "Backup and Restore tem RTO de horas/dias — não atende 1h.",
     "B": "Pilot Light tem só DB/storage rodando; precisa subir compute do zero — RTO maior, normalmente algumas horas.",
     "D": "Multi-Site Active-Active atinge RTO/RPO próximos de zero, mas é o mais caro — overspec para esse requisito."
    },
    "keyConcept": "DR strategies — 4 estratégias canônicas",
    "compareWith": [
     "Backup/Restore vs Pilot Light vs Warm Standby vs Multi-Site"
    ],
    "realWorldContext": "E-commerces médios escolhem Warm Standby como sweet spot custo/RTO.",
    "commonMistakes": "Sempre escolher Multi-Site achando que ''melhor'' é sempre melhor — custa muito mais que o necessário.",
    "tutorSeeds": [
     "Quais as quatro estratégias de DR oficiais da AWS?",
     "Como AWS Elastic Disaster Recovery (DRS) implementa Warm Standby?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["disaster-recovery","rto","rpo","warm-standby"]'::jsonb, 'ai-draft', 'active', now(), now()
)
