INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-032', 'aws-clf', 'Sobre a estratégia de DR ''Pilot Light'', qual é a característica DEFINIDORA?',
  '[{"id":"A","text":"Todo o stack está rodando em produção em duas Regions, com tráfego balanceado entre elas"},{"id":"B","text":"Apenas backups armazenados em S3, sem nada rodando na Region de DR"},{"id":"C","text":"Uma versão scaled-down do stack inteiro está sempre rodando na Region de DR"},{"id":"D","text":"Componentes de dados (DB, storage) estão replicados e prontos, mas compute está desligado — sobe sob demanda no failover"}]'::jsonb, 'D',
  '{
    "summary": "Pilot Light = camada de dados (DB, replication) sempre rodando; compute desligado e provisionado sob demanda no failover.",
    "whyCorrect": "A metáfora é literal: ''piloto'' (chama mínima) aceso (DB replicando) e o restante (compute) ligado só quando necessário. RTO típico 10s de minutos a poucas horas, RPO baixo (replicação contínua de DB).",
    "whyWrong": {
     "A": "É Multi-Site Active-Active.",
     "B": "É Backup and Restore.",
     "C": "É Warm Standby (scaled-down running)."
    },
    "keyConcept": "Pilot Light — DB ativo, compute dormindo",
    "compareWith": [
     "Pilot Light vs Warm Standby — diferença chave: compute"
    ],
    "realWorldContext": "Bancos médios usam Pilot Light para apps secundários (menos críticos que core banking).",
    "commonMistakes": "Confundir Pilot Light com Warm Standby — diferença é se compute está ligado ou não.",
    "tutorSeeds": [
     "Como acelerar o failover de Pilot Light com AMIs pré-construídas?",
     "Qual o impacto típico do custo de Pilot Light vs Backup/Restore?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["disaster-recovery","pilot-light"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
