INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-033', 'aws-clf', 'Um sistema de trading financeiro exige RTO próximo de zero e RPO próximo de zero (zero perda de dados aceita). Qual estratégia é adequada e qual seu trade-off principal?',
  '[{"id":"A","text":"Multi-Site Active-Active — atende, mas custa significativamente mais (replicação síncrona ou quase, infra dupla)"},{"id":"B","text":"Backup and Restore — barato e simples"},{"id":"C","text":"Pilot Light — bom equilíbrio"},{"id":"D","text":"Não é possível atingir RTO/RPO zero na nuvem"}]'::jsonb, 'A',
  '{
    "summary": "Multi-Site Active-Active mantém stack completo rodando em múltiplas Regions com tráfego ativo, atingindo RTO/RPO próximos de zero — ao custo de infra duplicada e complexidade.",
    "whyCorrect": "Para trading, RTO/RPO próximos de zero exigem Active-Active: tráfego balanceado entre Regions (Route 53 latency/weighted), DB com replicação síncrona ou quase (ex: DynamoDB Global Tables, Aurora Global Database). Trade-off: custos 2x+ infra, complexidade arquitetural (consistency, conflict resolution).",
    "whyWrong": {
     "B": "Backup/Restore tem RTO de horas — inaceitável para trading.",
     "C": "Pilot Light tem RTO em minutos — muito para trading high-frequency.",
     "D": "É possível chegar muito próximo de zero (não exatamente zero — leis da física), mas o exam usa ''próximo de zero'' como sinônimo prático."
    },
    "keyConcept": "Multi-Site Active-Active — RTO/RPO mínimos com maior custo",
    "compareWith": [
     "Active-Active vs Active-Passive Warm Standby"
    ],
    "realWorldContext": "B3, NYSE e exchanges similares operam multi-Region active-active com replicação síncrona em distância limitada.",
    "commonMistakes": "Achar que ''RTO/RPO zero é grátis'' — é o mais caro dos 4 modelos.",
    "tutorSeeds": [
     "Qual a diferença entre Aurora Global Database e DynamoDB Global Tables para active-active?",
     "Como resolver conflitos de escrita em DBs multi-Region?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["disaster-recovery","multi-site","active-active"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
