INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-034', 'aws-clf', 'RTO e RPO se referem a o quê, respectivamente?',
  '[{"id":"A","text":"RTO = tempo de resposta; RPO = ranking de prioridade"},{"id":"B","text":"RTO = quanto tempo aceitável para recuperar o serviço; RPO = quanto de dados (em tempo) é aceitável perder"},{"id":"C","text":"RTO = total de objetos perdidos; RPO = perda de processamento"},{"id":"D","text":"RTO = retorno sobre o investimento; RPO = retorno sobre operação"}]'::jsonb, 'B',
  '{
    "summary": "RTO = Recovery Time Objective (tempo aceitável de downtime). RPO = Recovery Point Objective (quanto de dados é aceitável perder).",
    "whyCorrect": "RTO mede o ''tempo de recovery alvo'' (ex: 1h) — quanto o serviço pode ficar indisponível. RPO mede o ''ponto de recovery alvo'' (ex: 5 min) — perda aceitável medida em tempo de dados (ex: replicação contínua = RPO segundos; backup diário = RPO 24h).",
    "whyWrong": {
     "A": "RTO não é response time; RPO não é ranking.",
     "C": "Definição inventada.",
     "D": "Retorno sobre investimento é ROI, não RTO."
    },
    "keyConcept": "RTO vs RPO — definições canônicas",
    "compareWith": [
     "RTO vs MTTR",
     "RPO vs frequência de backup"
    ],
    "realWorldContext": "SLA contratuais com clientes B2B costumam ter RTO/RPO explícitos por workload.",
    "commonMistakes": "Confundir RTO (tempo de recovery) com tempo de resposta de API.",
    "tutorSeeds": [
     "Como medir RTO de fato em um Game Day?",
     "Qual a relação entre RPO e frequência de snapshots EBS?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["disaster-recovery","rto","rpo"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
