INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-035', 'aws-clf', 'Uma empresa quer reduzir custos de DR sem comprometer significativamente RTO. Atualmente tem Backup/Restore (RTO ~12h, RPO ~24h). Quer chegar a RTO ~4h. Qual é o próximo passo lógico?',
  '[{"id":"A","text":"Manter Backup/Restore — basta automatizar mais"},{"id":"B","text":"Pular direto para Multi-Site Active-Active"},{"id":"C","text":"Migrar para Pilot Light com replicação contínua do DB e AMIs pré-construídas"},{"id":"D","text":"Migrar para on-premises para reduzir RTO"}]'::jsonb, 'C',
  '{
    "summary": "Pilot Light é o próximo passo natural: traz a camada de dados sempre ativa, com infra de compute pronta para subir — RTO em horas, RPO em minutos.",
    "whyCorrect": "Para escalar de Backup/Restore (RTO horas/dias) para algo melhor sem o custo de Warm Standby ou Multi-Site, Pilot Light é o passo natural. Mantém DB replicado, AMIs/CloudFormation prontos, e provisiona compute apenas no failover.",
    "whyWrong": {
     "A": "Automação ajuda, mas o RTO de Backup/Restore continua na casa de horas a um dia.",
     "B": "Multi-Site é overshoot — custos altos para o requisito de 4h.",
     "D": "On-prem não reduz RTO; é menos elástico que cloud."
    },
    "keyConcept": "Escalada DR — Backup → Pilot Light → Warm Standby → Multi-Site",
    "compareWith": [
     "Pilot Light vs Warm Standby — custos"
    ],
    "realWorldContext": "Empresas tipicamente sobem na escala conforme maturidade DR e criticidade do workload.",
    "commonMistakes": "Pular direto para Multi-Site Active-Active sem justificativa de negócio — desperdício.",
    "tutorSeeds": [
     "Qual o custo relativo aproximado de cada estratégia DR?",
     "Como AWS DRS (Elastic Disaster Recovery) simplifica essa migração?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["disaster-recovery","pilot-light","trade-off"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
