INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-036', 'aws-clf', 'Um banco quer escolher uma estratégia DR baseado em RPO=0. Qual NÃO é uma estratégia viável para atingir RPO=0?',
  '[{"id":"A","text":"Replicação síncrona entre AZs (ex: RDS Multi-AZ) dentro da mesma Region"},{"id":"B","text":"DynamoDB com Multi-AZ por padrão na Region"},{"id":"C","text":"Aurora Multi-AZ writer com sync replica na mesma Region"},{"id":"D","text":"Aurora Global Database em modo de leitura cross-Region (replicação assíncrona)"}]'::jsonb, 'D',
  '{
    "summary": "Aurora Global Database faz replicação assíncrona cross-Region (latência típica <1s, mas não síncrona) — RPO próximo de zero, não exatamente zero.",
    "whyCorrect": "Replicação assíncrona inerentemente tem alguma janela onde dados podem se perder (a transação foi confirmada em uma Region mas ainda não replicou para a outra). Aurora Global Database tem RPO segundos, não zero. Para RPO=0 estrito, é preciso replicação síncrona (limitada a curta distância).",
    "whyWrong": {
     "A": "RDS Multi-AZ usa replicação síncrona entre AZs — RPO=0 alcançável.",
     "B": "DynamoDB replica síncrono dentro da Region (3 réplicas em AZs distintas) — RPO=0.",
     "C": "Aurora dentro da Region usa storage compartilhado replicado 6 vezes em 3 AZs — sync, RPO=0."
    },
    "keyConcept": "RPO=0 exige replicação síncrona (latência limita distância)",
    "compareWith": [
     "Sync replication intra-Region vs async cross-Region"
    ],
    "realWorldContext": "Bancos críticos mantêm RPO=0 dentro de uma Region (multi-AZ) e aceitam RPO em segundos cross-Region.",
    "commonMistakes": "Achar que ''global = RPO=0'' — replicação cross-Region é tipicamente assíncrona.",
    "tutorSeeds": [
     "Qual a latência típica do Aurora Global Database?",
     "Por que replicação síncrona cross-Region é impraticável?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["disaster-recovery","rpo","replication"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
