INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-037', 'aws-clf', 'Sobre a estratégia ''Backup and Restore'', qual afirmação está CORRETA?',
  '[{"id":"A","text":"Tem o menor custo entre as 4 estratégias e o maior RTO"},{"id":"B","text":"Tem o maior custo e o menor RTO"},{"id":"C","text":"Garante RPO=0 automaticamente"},{"id":"D","text":"É a estratégia recomendada para sistemas de trading financeiro"}]'::jsonb, 'A',
  '{
    "summary": "Backup/Restore tem o menor custo (só armazenagem de backup) e o maior RTO (horas a dias para reidratar tudo).",
    "whyCorrect": "Backup and Restore: apenas snapshots/backups armazenados (ex: S3, Backup Vault). No failover, é preciso provisionar infra do zero, restaurar backups, validar. RTO típico de horas a dias. Custo mínimo entre estratégias.",
    "whyWrong": {
     "B": "É o oposto — menor custo, maior RTO.",
     "C": "RPO depende da frequência de backup (ex: diário = RPO 24h).",
     "D": "Para trading, RTO de horas é inaceitável — Multi-Site é o padrão."
    },
    "keyConcept": "Backup/Restore — barato e lento",
    "compareWith": [
     "Backup/Restore vs Pilot Light — custos e RTOs"
    ],
    "realWorldContext": "Workloads dev/test e sistemas de baixa criticidade usam Backup/Restore como estratégia DR.",
    "commonMistakes": "Achar que basta ter backup para estar ''safe'' — sem teste de restore, é placebo.",
    "tutorSeeds": [
     "Como AWS Backup centraliza políticas de backup?",
     "Como validar restores periodicamente?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["disaster-recovery","backup-restore"]'::jsonb, 'ai-draft', 'active', now(), now()
)
