INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-038', 'aws-clf', 'Em DR multi-Region, qual serviço AWS centraliza políticas de backup cross-Region/cross-account?',
  '[{"id":"A","text":"Amazon S3 Glacier Deep Archive"},{"id":"B","text":"AWS Backup"},{"id":"C","text":"AWS Storage Gateway"},{"id":"D","text":"EBS snapshot copy manual"}]'::jsonb, 'B',
  '{
    "summary": "AWS Backup é o serviço central de políticas de backup com suporte multi-account/multi-Region via Backup Vaults.",
    "whyCorrect": "AWS Backup centraliza policies para RDS, DynamoDB, EBS, EFS, FSx, EC2, Storage Gateway, S3, Aurora, etc. Suporta cross-Region copy automático e cross-account via AWS Organizations. Vault Lock dá WORM (write-once-read-many) para compliance.",
    "whyWrong": {
     "A": "Glacier Deep Archive é tier de storage, não orquestrador de backup.",
     "C": "Storage Gateway estende S3 para on-prem — não é o orquestrador de backup.",
     "D": "EBS snapshot manual cross-Region funciona mas não é centralizado/programático para múltiplos serviços."
    },
    "keyConcept": "AWS Backup — orquestração central, multi-service",
    "compareWith": [
     "AWS Backup vs DLM (Data Lifecycle Manager)"
    ],
    "realWorldContext": "Empresas com 100s de contas usam AWS Backup com Organizations para política unificada de backup.",
    "commonMistakes": "Confundir AWS Backup (orquestrador) com S3/Glacier (storage destino).",
    "tutorSeeds": [
     "Quais recursos AWS Backup suporta hoje?",
     "Como AWS Backup Vault Lock implementa WORM?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["disaster-recovery","aws-backup"]'::jsonb, 'ai-draft', 'active', now(), now()
)
