INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-039', 'aws-clf', 'Sobre o AWS Cloud Adoption Framework (CAF), qual lista contém as 6 perspectives (em qualquer ordem)?',
  '[{"id":"A","text":"Cost, Speed, Security, Reliability, Performance, Sustainability"},{"id":"B","text":"Strategy, Tactics, Execution, Monitoring, Optimization, Reporting"},{"id":"C","text":"Business, People, Governance, Platform, Security, Operations"},{"id":"D","text":"Plan, Build, Test, Deploy, Operate, Optimize"}]'::jsonb, 'C',
