INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-043', 'aws-clf', 'No CAF, qual transformation domain é referenciado quando a empresa fala de ''mudar o modelo de negócio com IA generativa para criar nova fonte de receita''?',
  '[{"id":"A","text":"Technology"},{"id":"B","text":"Process"},{"id":"C","text":"Business"},{"id":"D","text":"People (organizational)"}]'::jsonb, 'C',
  '{
    "summary": "CAF identifica 4 transformation domains: Technology, Process, Organization, Product. ''Novo modelo de negócio/receita'' é Business/Product transformation.",
    "whyCorrect": "CAF v3 distingue 4 transformation domains: Technology (mudar arquitetura), Process (mudar como operar), Organization (mudar pessoas/estrutura), Product (mudar modelo de negócio, criar novos produtos/receitas).",
    "whyWrong": {
     "A": "Technology trata de stack/arquitetura, não modelo de negócio.",
     "B": "Process trata de fluxos de trabalho, não modelo de receita.",
     "D": "Organization trata de estrutura organizacional, não receita."
    },
    "keyConcept": "CAF Transformation Domains — Technology, Process, Organization, Product",
    "compareWith": [
     "Transformation domains vs perspectives"
    ],
    "realWorldContext": "Startups que pivotam para AI-native estão fazendo Product transformation.",
    "commonMistakes": "Confundir transformation domains (4) com perspectives (6) — são dimensões diferentes do CAF.",
    "tutorSeeds": [
