INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-045', 'aws-clf', 'Uma empresa está fazendo assessment usando o CAF. Eles identificam que TI tem maturidade alta, mas a área de negócio não tem visão clara do valor da nuvem. Qual perspective deve receber mais atenção?',
  '[{"id":"A","text":"Business — alinhar valor e estratégia"},{"id":"B","text":"Platform — alinhar tecnologia"},{"id":"C","text":"Operations — melhorar operação"},{"id":"D","text":"Security — fortalecer segurança"}]'::jsonb, 'A',
  '{
    "summary": "Business perspective trata de strategy management, portfolio management, innovation management, product management — onde TI alinha-se ao valor de negócio.",
    "whyCorrect": "Business perspective conecta investimento em nuvem ao valor de negócio: strategy, portfolio mgmt, innovation, product mgmt, business insights, data monetization, data science. É onde ''qual valor a nuvem traz'' é discutido.",
    "whyWrong": {
     "B": "Platform já é forte (TI maduro) — não é o gap.",
     "C": "Operations é detalhe operacional, não estratégico.",
     "D": "Security é importante, mas não resolve falta de visão de valor."
    },
    "keyConcept": "CAF Business — alinhar valor e estratégia",
    "compareWith": [
     "Business vs Governance"
    ],
    "realWorldContext": "Empresas que migram ''pelo lift-and-shift'' sem aplicar Business perspective frequentemente não capturam todo o ROI.",
    "commonMistakes": "Pular Business perspective achando que ''TI cuida'' — gap de alinhamento é frequente.",
    "tutorSeeds": [
     "Quais capabilities completas estão em Business?",
     "Como medir valor da nuvem em KPIs de negócio?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["caf","business"]'::jsonb, 'ai-draft', 'active', now(), now()
)
