INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-046', 'aws-clf', 'Sobre as ''6 perspectives'' do CAF, são frequentemente agrupadas em quais dois conjuntos?',
  '[{"id":"A","text":"Strategic e Tactical"},{"id":"B","text":"Foundational (Business, People, Governance) e Technical (Platform, Security, Operations)"},{"id":"C","text":"Internal e External"},{"id":"D","text":"Functional e Cross-functional"}]'::jsonb, 'B',
  '{
    "summary": "CAF agrupa Business/People/Governance como foundational (não-técnicas) e Platform/Security/Operations como technical.",
    "whyCorrect": "Foundational perspectives focam em pessoas, processos e negócio. Technical perspectives focam em tecnologia, segurança e operação. Esse agrupamento canônico aparece na documentação oficial CAF.",
    "whyWrong": {
     "A": "Distractor inventado.",
     "C": "Não é assim que CAF organiza.",
     "D": "Não é a terminologia CAF."
