INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-047', 'aws-clf', 'Uma empresa decide migrar uma aplicação Java monolítica de servidor on-prem para EC2 com mínimas alterações de código. Qual dos 7 Rs descreve melhor essa estratégia?',
  '[{"id":"A","text":"Refactor (Re-architect)"},{"id":"B","text":"Replatform"},{"id":"C","text":"Rehost (Lift-and-Shift)"},{"id":"D","text":"Repurchase"}]'::jsonb, 'C',
  '{
    "summary": "Rehost (Lift-and-Shift) = mover o aplicativo para a nuvem sem alteração de código, frequentemente com VM-to-VM (Application Migration Service / MGN).",
    "whyCorrect": "Rehost é a estratégia mais simples e rápida: pega a VM atual e replica para EC2 (geralmente via AWS MGN). ''Mínimas alterações de código'' é a marca registrada do lift-and-shift. RTO de migração rápido, mas não captura benefícios de cloud-native.",
    "whyWrong": {
     "A": "Refactor envolve reescrever para cloud-native (ex: monolito → microserviços) — muito mais que ''mínimas alterações''.",
     "B": "Replatform (lift-tinker-shift) envolve algumas otimizações sem mudar arquitetura (ex: trocar self-managed DB por RDS).",
     "D": "Repurchase = drop-and-shop, trocar por SaaS (ex: migrar CRM para Salesforce)."
    },
    "keyConcept": "Migration 7 Rs — Rehost (Lift-and-Shift)",
    "compareWith": [
     "Rehost vs Replatform vs Refactor"
    ],
    "realWorldContext": "Empresas em prazo apertado de desocupar DC usam Rehost para sair rápido e otimizar depois.",
    "commonMistakes": "Confundir Rehost com Replatform — diferença está em quanto se mexe na arquitetura.",
    "tutorSeeds": [
     "Quais ferramentas AWS apoiam Rehost (AWS MGN)?",
     "Quando Rehost é a errada apesar de mais rápida?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["migration","7rs","rehost"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
