INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-048', 'aws-clf', 'Uma empresa decide migrar do Microsoft SQL Server self-hosted para Amazon Aurora PostgreSQL, mudando engine mas mantendo a aplicação. Qual dos 7 Rs descreve melhor essa migração?',
  '[{"id":"A","text":"Rehost"},{"id":"B","text":"Refactor"},{"id":"C","text":"Repurchase"},{"id":"D","text":"Replatform"}]'::jsonb, 'D',
  '{
    "summary": "Replatform (Lift-Tinker-Shift) = ajustes pontuais para aproveitar nuvem sem refazer arquitetura. Trocar engine de DB (SQL Server → Aurora) é caso clássico.",
    "whyCorrect": "Replatform faz ''tinker'': otimizações pontuais (mudar engine, trocar para serviço gerenciado, ajustar storage), mantendo a arquitetura essencial da aplicação. Migrar de SQL Server para Aurora PostgreSQL com AWS DMS + SCT é replatform clássico.",
    "whyWrong": {
     "A": "Rehost manteria o SQL Server, apenas em EC2.",
     "B": "Refactor envolveria reescrever a aplicação (ex: monolito → microserviços).",
     "C": "Repurchase seria substituir por SaaS comercial."
    },
    "keyConcept": "Replatform — lift-tinker-shift",
    "compareWith": [
     "Replatform vs Refactor — quanto se muda"
    ],
    "realWorldContext": "AWS DMS + SCT são ferramentas canônicas para esse tipo de replatform de DB.",
    "commonMistakes": "Achar que ''qualquer mudança de DB'' é refactor — só vira refactor se reescrever app inteira.",
    "tutorSeeds": [
     "Como AWS Schema Conversion Tool (SCT) facilita replatform de DB?",
     "Quais ganhos típicos justificam replatform de SQL Server para Aurora?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["migration","7rs","replatform"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
