INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-049', 'aws-clf', 'Uma empresa identifica que um software ERP legacy não traz mais valor e seu suporte foi descontinuado. Decide simplesmente desligá-lo. Qual dos 7 Rs aplica?',
  '[{"id":"A","text":"Retire"},{"id":"B","text":"Retain"},{"id":"C","text":"Relocate"},{"id":"D","text":"Repurchase"}]'::jsonb, 'A',
  '{
    "summary": "Retire = decomissionar app que não traz valor. Auditoria do portfólio frequentemente identifica 10-20% de apps que podem ser eliminados.",
    "whyCorrect": "Retire significa simplesmente desligar/decomissionar. Em portfólio de migração, identificar apps que não trazem mais valor (low usage, redundantes, EOL) e retire é economia imediata.",
    "whyWrong": {
     "B": "Retain = manter on-prem por enquanto (não migrar ainda) — diferente de desligar.",
     "C": "Relocate = mover infra (ex: VMware HCX) sem mudar app.",
     "D": "Repurchase = substituir por SaaS."
    },
    "keyConcept": "Retire — eliminar do portfólio",
    "compareWith": [
     "Retire vs Retain"
    ],
    "realWorldContext": "Portfólio assessment com AWS Application Discovery Service identifica candidatos a Retire.",
    "commonMistakes": "Confundir Retire (desligar) com Retain (manter on-prem temporariamente).",
    "tutorSeeds": [
     "Como AWS Application Discovery Service apoia auditoria de portfólio?",
     "Quais sinais indicam que app é candidato a Retire?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["migration","7rs","retire"]'::jsonb, 'ai-draft', 'active', now(), now()
)
