INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-051', 'aws-clf', 'A AWS Migration Acceleration Program (MAP) é uma iniciativa que ajuda clientes a migrar para AWS. O MAP organiza a migração em 3 fases principais. Quais são?',
  '[{"id":"A","text":"Plan, Execute, Optimize"},{"id":"B","text":"Discover, Migrate, Deprecate"},{"id":"C","text":"Assess, Mobilize, Migrate \u0026 Modernize"},{"id":"D","text":"Backup, Cutover, Validate"}]'::jsonb, 'C',
  '{
    "summary": "MAP organiza-se em 3 fases: Assess (avaliação/business case), Mobilize (planejamento/landing zone), Migrate & Modernize (execução).",
    "whyCorrect": "Assess fase usa Migration Evaluator/TCO para business case. Mobilize estabelece landing zone (Control Tower), CCoE, skill plan. Migrate & Modernize executa em waves com 7 Rs.",
    "whyWrong": {
     "A": "Não é a terminologia MAP.",
     "B": "Não é MAP.",
     "D": "Confunde com procedimento de cutover, não fases macro."
    },
    "keyConcept": "MAP — Assess → Mobilize → Migrate & Modernize",
    "compareWith": [
     "MAP vs CAF — escopos"
    ],
    "realWorldContext": "Grandes migrações empresariais (1000+ servers) usam MAP com partners do APN.",
    "commonMistakes": "Confundir MAP (programa comercial) com CAF (framework).",
    "tutorSeeds": [
     "Quais financial incentives AWS oferece através do MAP?",
     "Como Migration Evaluator funciona?"
    ]
   }'::jsonb,
