INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-052', 'aws-clf', 'Sobre AWS Pricing Calculator e AWS Migration Evaluator (antigo TSO Logic), qual diferença é CORRETA?',
  '[{"id":"A","text":"Ambas fazem a mesma coisa — duas marcas de uma ferramenta única"},{"id":"B","text":"Pricing Calculator é só para EC2; Migration Evaluator é só para S3"},{"id":"C","text":"Migration Evaluator só funciona para AWS GovCloud"},{"id":"D","text":"Pricing Calculator estima custo de uso AWS futuro; Migration Evaluator analisa ambiente on-prem e gera business case comparativo (on-prem vs AWS)"}]'::jsonb, 'D',
  '{
    "summary": "Pricing Calculator = estima custo do que você vai usar no AWS. Migration Evaluator = analisa on-prem e compara com TCO em AWS para business case.",
    "whyCorrect": "Pricing Calculator (calculator.aws) é forward-looking: você desenha um deployment e estima custo. Migration Evaluator (ex-TSO Logic) coleta inventário on-prem (via collector ou import), normaliza e mostra: ''se você rodasse isso em AWS, custaria X'' — ferramenta de business case pré-migração.",
    "whyWrong": {
     "A": "São ferramentas distintas com propósitos diferentes.",
     "B": "Ambas cobrem múltiplos serviços.",
     "C": "Migration Evaluator não é restrita ao GovCloud."
    },
    "keyConcept": "Pricing Calculator vs Migration Evaluator",
    "compareWith": [
     "Pricing Calculator vs TCO Calculator (legado)"
    ],
    "realWorldContext": "Sales engineers AWS usam Migration Evaluator para gerar business case antes de propostas de migração.",
    "commonMistakes": "Achar que Pricing Calculator faz TCO on-prem vs AWS — não, é só forward estimate.",
    "tutorSeeds": [
     "Como Migration Evaluator coleta dados on-prem?",
     "Como o antigo TCO Calculator se relaciona com essas ferramentas?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["migration","tco","pricing-calculator"]'::jsonb, 'ai-draft', 'active', now(), now()
)
