INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-053', 'aws-clf', 'TCO (Total Cost of Ownership) em comparação on-prem vs AWS deve considerar quais custos do lado on-prem? Selecione o conjunto mais completo.',
  '[{"id":"A","text":"Servidores, storage, networking, energia, refrigeração, espaço físico, equipe de operação, licenças, manutenção, depreciação, redundância"},{"id":"B","text":"Apenas o custo de aquisição dos servidores"},{"id":"C","text":"Apenas energia elétrica e refrigeração"},{"id":"D","text":"Apenas licenças de software"}]'::jsonb, 'A',
  '{
    "summary": "TCO on-prem inclui CapEx (hardware) e OpEx (energia, espaço, refrigeração, equipe, licenças, manutenção, depreciação, redundância para HA).",
    "whyCorrect": "Comparações TCO honestas incluem todos os custos diretos e indiretos: hardware, licenciamento, energia, refrigeração, datacenter (espaço/aluguel), equipe (admin, segurança, networking), manutenção, depreciação, redundância (DR site), conectividade.",
    "whyWrong": {
     "B": "Olhar só servidor ignora 60%+ dos custos reais.",
     "C": "Energia e refrigeração são parte, mas só parte.",
     "D": "Licenças são parte, mas só parte."
    },
    "keyConcept": "TCO completo — CapEx + OpEx + custos ocultos",
    "compareWith": [
     "TCO on-prem vs OpEx AWS"
    ],
    "realWorldContext": "Auditorias TCO frequentemente revelam que custos ''invisíveis'' (espaço, equipe) representam 40-50% do total on-prem.",
    "commonMistakes": "Comparar só preço do servidor com EC2 — ignora todo o stack de TCO.",
    "tutorSeeds": [
     "Como calcular custo de equipe alocada a operação?",
     "Como mensurar custo de redundância DR on-prem?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["migration","tco"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
