INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-054', 'aws-clf', 'Uma empresa migra para a nuvem e elimina o datacenter. Como esse movimento afeta CapEx vs OpEx?',
  '[{"id":"A","text":"Aumenta CapEx, reduz OpEx"},{"id":"B","text":"Reduz CapEx (eliminação de compra de servidores/redes), aumenta OpEx (pagamento por uso AWS)"},{"id":"C","text":"Não afeta nenhum dos dois"},{"id":"D","text":"Aumenta ambos"}]'::jsonb, 'B',
  '{
    "summary": "Mover para nuvem transforma despesas fixas (CapEx — comprar servidores) em despesas variáveis (OpEx — pagar por uso).",
    "whyCorrect": "Uma das vantagens canônicas da nuvem (''trade capital expense for variable expense''): em vez de investir milhões em hardware (CapEx que deprecia), você paga conforme o uso (OpEx) que vai direto para a P&L como despesa operacional.",
    "whyWrong": {
     "A": "É o oposto: CapEx cai, OpEx sobe.",
     "C": "Afeta significativamente ambas categorias contábeis.",
     "D": "Não faz sentido — CapEx tipicamente diminui."
    },
    "keyConcept": "CapEx vs OpEx — trocar fixo por variável",
    "compareWith": [
     "CapEx vs OpEx — implicações fiscais"
    ],
    "realWorldContext": "CFOs valorizam essa mudança para preservar caixa para investimentos estratégicos.",
    "commonMistakes": "Achar que nuvem ''reduz tudo'' — reduz CapEx, mas pode aumentar OpEx total dependendo do workload.",
    "tutorSeeds": [
     "Quais as implicações fiscais de CapEx vs OpEx?",
     "Em quais casos o TCO em nuvem é maior que on-prem?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'best-practice', '["pricing","capex","opex"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
