INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-055', 'aws-clf', 'Sobre ''economies of scale'' como vantagem da nuvem AWS, qual é a explicação CORRETA?',
  '[{"id":"A","text":"Cada cliente AWS consegue economia individual usando muitos serviços"},{"id":"B","text":"Apenas Enterprise customers conseguem economias de escala"},{"id":"C","text":"AWS agrega o uso de milhões de clientes, conseguindo poder de compra/operação superior — passa parte dessa economia em preços menores aos clientes"},{"id":"D","text":"Economies of scale só existem em Regions americanas"}]'::jsonb, 'C',
  '{
    "summary": "AWS atinge economia de escala agregando uso de milhões de clientes, traduzindo em hardware mais barato, energia eficiente e preços menores repassados aos clientes (price drops históricos).",
    "whyCorrect": "AWS lista ''massive economies of scale'' como uma das 6 vantagens da nuvem. Pelo volume agregado, AWS negocia hardware/energia em escala muito maior que qualquer cliente individual, repassa parte (price reductions têm sido constantes — 100+ desde 2006).",
    "whyWrong": {
     "A": "Economia individual de um cliente é distinta — a vantagem é agregada.",
     "B": "Todos clientes se beneficiam, não só Enterprise.",
     "D": "Aplica-se a todas as Regions globalmente."
    },
    "keyConcept": "Economies of scale — vantagem agregada",
    "compareWith": [
     "Economies of scale vs trade fixed for variable"
    ],
    "realWorldContext": "Históricamente AWS reduz preços de S3, EC2, EBS em ciclos — repassando economias.",
    "commonMistakes": "Confundir economia de escala individual com economia de escala agregada.",
    "tutorSeeds": [
     "Quais as 6 vantagens canônicas da nuvem AWS?",
     "Quantas reduções de preço AWS já fez desde 2006?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["pricing","economies-of-scale"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
