INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-056', 'aws-clf', 'Uma fintech provisiona constantemente ''capacidade extra'' on-prem ''por garantia'' de não faltar nos picos. Qual vantagem da nuvem ataca diretamente esse problema?',
  '[{"id":"A","text":"Trade fixed expense for variable expense"},{"id":"B","text":"Massive economies of scale"},{"id":"C","text":"Increase speed and agility"},{"id":"D","text":"Stop guessing capacity"}]'::jsonb, 'D',
  '{
    "summary": "''Stop guessing capacity'' é a vantagem canônica que ataca exatamente o problema de over-provisioning ''por garantia''.",
    "whyCorrect": "On-prem força ''guessing'' — você compra capacidade fixa antes de saber demanda. Nuvem permite escalar elasticamente: pague baseline + escala conforme tráfego. Auto Scaling, Lambda, DynamoDB on-demand materializam isso.",
    "whyWrong": {
     "A": "Variable expense é benefício relacionado, mas a essência aqui é parar de ''adivinhar capacidade''.",
     "B": "Economies of scale é benefício de pricing agregado, não de elasticidade.",
     "C": "Speed/agility é sobre lançar features, não dimensionamento."
    },
    "keyConcept": "Stop guessing capacity — elasticidade",
    "compareWith": [
     "6 vantagens — relacionamentos entre elas"
    ],
    "realWorldContext": "E-commerces no Black Friday escalam 10x em horas via Auto Scaling — impossível on-prem em prazo.",
    "commonMistakes": "Confundir com ''variable expense'' — relacionados mas distintos.",
    "tutorSeeds": [
     "Como Auto Scaling materializa essa vantagem em EC2?",
     "Quais são as 6 vantagens completas listadas pela AWS?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["cloud-advantages","elasticity"]'::jsonb, 'ai-draft', 'active', now(), now()
)
