INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-057', 'aws-clf', 'Uma startup de saúde quer lançar produto em UE, Brasil e Japão em 2 meses. Qual vantagem da nuvem habilita isso?',
  '[{"id":"A","text":"Go global in minutes"},{"id":"B","text":"Stop spending money running and maintaining data centers"},{"id":"C","text":"Trade fixed expense for variable expense"},{"id":"D","text":"Massive economies of scale"}]'::jsonb, 'A',
  '{
    "summary": "''Go global in minutes'' descreve exatamente a capacidade de subir presença em múltiplos países sem construir DCs.",
    "whyCorrect": "Para lançar produto em 3 continentes sem nuvem, exigia DCs locais (meses de construção). Com AWS, basta deployar em eu-west-1, sa-east-1, ap-northeast-1 (com CloudFront + Route 53 latency routing). Minutos vs anos.",
    "whyWrong": {
     "B": "É benefício real, mas não é o ponto sobre alcance global.",
     "C": "OpEx é relacionado mas não foco.",
     "D": "Economies of scale não fala de alcance global."
    },
    "keyConcept": "Go global in minutes — presença mundial sem CapEx",
    "compareWith": [
     "6 vantagens da nuvem"
    ],
    "realWorldContext": "Spotify, Slack e Airbnb escalaram global desde cedo via AWS Regions múltiplas.",
    "commonMistakes": "Confundir com ''massive economies of scale'' (questão de pricing).",
    "tutorSeeds": [
     "Como Route 53 latency-based routing seleciona Region?",
     "Quais regulações precisam ser checadas ao ''go global''?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["cloud-advantages","global"]'::jsonb, 'ai-draft', 'active', now(), now()
)
