INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-058', 'aws-clf', 'Uma empresa de mídia desenvolve um app novo e quer experimentar features rapidamente, falhar barato e iterar. Qual vantagem da nuvem suporta diretamente essa cultura?',
  '[{"id":"A","text":"Stop guessing capacity"},{"id":"B","text":"Increase speed and agility"},{"id":"C","text":"Stop spending money running data centers"},{"id":"D","text":"Trade fixed for variable"}]'::jsonb, 'B',
  '{
    "summary": "''Increase speed and agility'' captura a habilidade de provisionar recursos em minutos para experimentar, falhar barato e iterar rápido.",
    "whyCorrect": "Provisionar VM/DB/cluster em minutos (vs semanas em on-prem) habilita experimentação rápida — pilar de cultura DevOps/agile. Reduz custo do erro (recursos descartáveis).",
    "whyWrong": {
     "A": "Stop guessing capacity é mais sobre dimensionamento que sobre velocidade de inovação.",
     "C": "Não foca em velocidade de iteração.",
     "D": "OpEx vs CapEx é financeiro, não é sobre velocidade."
    },
    "keyConcept": "Speed and agility — experimentação rápida",
    "compareWith": [
     "6 vantagens — relacionamentos"
    ],
    "realWorldContext": "Netflix faz milhares de deploys/dia — só possível por velocidade de provisioning.",
    "commonMistakes": "Confundir ''agility'' com ''global'' — são vantagens distintas.",
    "tutorSeeds": [
     "Como CloudFormation/CDK aceleram experimentação?",
     "Como AWS suporta cultura DevOps?"
    ]
   }'::jsonb,
