INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-059', 'aws-clf', 'Sobre SLAs compostos: um serviço A tem SLA 99,9% e depende de um serviço B com SLA 99,9% (em série). Qual o SLA efetivo combinado aproximado?',
  '[{"id":"A","text":"99,9% (o pior dos dois)"},{"id":"B","text":"100% (ambos garantem)"},{"id":"C","text":"99,8% (multiplicação: 0,999 × 0,999 = 0,998)"},{"id":"D","text":"99,99% (média dos dois)"}]'::jsonb, 'C',
  '{
    "summary": "SLAs em série multiplicam-se: 99,9% × 99,9% = 99,8% (aproximadamente). Quanto mais serviços em cadeia, pior o SLA efetivo.",
    "whyCorrect": "Em sistemas em série, a disponibilidade composta é o produto: 0.999 * 0.999 = 0.998001 ≈ 99,8%. Essa é a ''matemática da disponibilidade'' fundamental — quanto mais dependências em série, mais baixo o SLA efetivo do sistema.",
    "whyWrong": {
     "A": "Não é o pior dos dois — é multiplicação.",
     "B": "100% não é alcançável e SLA não ''soma''.",
     "D": "Não é média aritmética."
    },
    "keyConcept": "SLA composto em série — multiplicação de probabilidades",
    "compareWith": [
     "SLA em série vs paralelo"
    ],
    "realWorldContext": "Sistemas modernos têm 10+ dependências (API GW, Lambda, RDS, S3, KMS), cada com SLA — composto pode cair para 99,5% ou menos.",
    "commonMistakes": "Pegar o SLA do pior componente e achar que é o SLA do sistema — está errado.",
    "tutorSeeds": [
     "Como melhorar SLA composto via redundância (paralelo)?",
     "Como o SLA paralelo é calculado matematicamente?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["sla","availability"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
