INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-060', 'aws-clf', 'Por que a AWS NÃO oferece SLA de 100% para serviços como EC2 ou S3?',
  '[{"id":"A","text":"Porque a AWS é insegura"},{"id":"B","text":"Porque AWS prefere garantir 95%"},{"id":"C","text":"Porque o cliente não pediu"},{"id":"D","text":"Porque 100% não é alcançável pelas leis da física e operação — qualquer evento natural, falha de hardware ou de software pode ocorrer; SLAs são compromissos realistas com créditos"}]'::jsonb, 'D',
  '{
    "summary": "100% uptime não existe — qualquer sistema tem possibilidade de falha. SLAs são compromissos realistas com créditos quando descumpridos.",
    "whyCorrect": "Mesmo com triplicação de redundância, sempre há cenários de falha (terremoto regional, bug em software, ataque). AWS oferece SLAs como 99,9%, 99,95%, 99,99% — compromissos altos mas realistas. Não cumprir = crédito (não reembolso integral).",
    "whyWrong": {
     "A": "Não tem a ver com insegurança.",
     "B": "EC2 SLA é 99,99%, não 95%.",
     "C": "Não é questão de pedido."
    },
    "keyConcept": "SLA — 100% é impossível, créditos como remédio",
    "compareWith": [
     "SLA EC2 vs S3 vs Lambda"
    ],
    "realWorldContext": "Apenas serviços de propósito muito específico (controle aéreo) buscam ''5 noves'' e mesmo eles falham.",
    "commonMistakes": "Esperar reembolso de receita perdida em violação de SLA — recebe-se apenas crédito de serviço.",
    "tutorSeeds": [
     "Como reivindicar SLA credit na AWS?",
     "Quais SLAs são mais altos: EC2 ou S3?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["sla","uptime"]'::jsonb, 'ai-draft', 'active', now(), now()
)
