INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-061', 'aws-clf', 'Para melhorar disponibilidade composta de um sistema, dois componentes redundantes em PARALELO (cada com 99,9%) atingem qual disponibilidade aproximada?',
  '[{"id":"A","text":"99,9999% (1 - (1-0,999) × (1-0,999) = 1 - 0,000001)"},{"id":"B","text":"99,8% (multiplicação)"},{"id":"C","text":"100%"},{"id":"D","text":"99,9% (igual a um único)"}]'::jsonb, 'A',
  '{
    "summary": "Em paralelo, indisponibilidades se multiplicam (1-p)^n: dois 99,9% em paralelo dão ~99,9999% (6 noves), pois ambos precisam falhar simultaneamente.",
    "whyCorrect": "Sistemas em paralelo (redundância): falham só quando todos componentes falham. P(falha total) = (1-0,999)² = 0,001² = 0,000001 → Disponibilidade = 1 - 0,000001 = 99,9999%. Redundância em paralelo melhora SLA dramaticamente.",
    "whyWrong": {
     "B": "Multiplicação é para SÉRIE (cadeia de dependência), não paralelo.",
     "C": "100% nunca alcançável, mas paralelo se aproxima muito.",
     "D": "Redundância paralela melhora muito o SLA agregado."
    },
    "keyConcept": "SLA em paralelo — 1 - (1-p)^n",
    "compareWith": [
     "SLA série (multiplicar) vs paralelo (complemento ao produto)"
    ],
    "realWorldContext": "Multi-AZ em RDS, S3 (cross-region), Aurora — todas usam paralelismo para boost de SLA.",
    "commonMistakes": "Aplicar fórmula de série em paralelo (ou vice-versa).",
    "tutorSeeds": [
     "Como combinar série e paralelo em sistemas complexos?",
     "Quais arquiteturas AWS são série e quais são paralelo?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["sla","availability","redundancy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
