INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-062', 'aws-clf', 'Uma arquitetura tem API Gateway (99,95%) → Lambda (99,95%) → DynamoDB (99,999%). Qual SLA composto aproximado em série?',
  '[{"id":"A","text":"99,999%"},{"id":"B","text":"~99,899% (multiplicação dos três)"},{"id":"C","text":"100%"},{"id":"D","text":"99,95% (média)"}]'::jsonb, 'B',
  '{
    "summary": "0,9995 × 0,9995 × 0,99999 ≈ 0,99899 ou ~99,899%. Multiplicação de probabilidades em série.",
    "whyCorrect": "Em cadeia de dependência: 0.9995 * 0.9995 * 0.99999 ≈ 0.99899. Mostra como mesmo serviços com altos SLAs individuais somam para SLA composto menor.",
    "whyWrong": {
     "A": "Não é o melhor dos três.",
     "C": "Nunca 100%.",
     "D": "Não é média aritmética."
    },
    "keyConcept": "SLA composto em série — sempre piora",
    "compareWith": [
     "SLA composto série vs paralelo"
    ],
    "realWorldContext": "Equipes SLO-aware modelam o error budget composto da arquitetura, não só de cada peça.",
    "commonMistakes": "Reportar ''SLA do sistema = SLA do pior serviço'' — está errado.",
    "tutorSeeds": [
     "Como AWS Resilience Hub apoia análise de SLA composto?",
     "Como definir Error Budget baseado em SLA composto?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["sla","availability"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
