INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-063', 'aws-clf', 'O AWS Trusted Advisor tem 5 categorias de checks. Quais são?',
  '[{"id":"A","text":"Security, Backups, Monitoring, Costs, Compliance"},{"id":"B","text":"Reliability, Cost, Sustainability, Performance, Operations"},{"id":"C","text":"Cost Optimization, Performance, Security, Fault Tolerance, Service Limits"},{"id":"D","text":"EC2, S3, RDS, Lambda, IAM"}]'::jsonb, 'C',
  '{
    "summary": "Trusted Advisor categorias: Cost Optimization, Performance, Security, Fault Tolerance, Service Limits (agora ''Service Quotas'').",
    "whyCorrect": "Trusted Advisor faz checks automatizados em 5 categorias canônicas. Clientes Basic/Developer Support têm acesso a subset limitado (alguns Security + Service Limits); Business e Enterprise têm acesso completo a todos os checks.",
    "whyWrong": {
     "A": "Lista inventada — ''Backups'' não é categoria do TA.",
     "B": "Mistura com pilares Well-Architected.",
     "D": "São serviços, não categorias."
    },
    "keyConcept": "Trusted Advisor — 5 categorias canônicas",
    "compareWith": [
     "Trusted Advisor categorias vs Well-Architected pilares"
    ],
    "realWorldContext": "Trusted Advisor recomenda Reserved Instances baseado em padrão de uso (cost optimization).",
    "commonMistakes": "Confundir Trusted Advisor com Well-Architected Tool.",
    "tutorSeeds": [
     "Quais checks são gratuitos no Basic Support?",
     "Como acionar checks via API do TA?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["trusted-advisor"]'::jsonb, 'ai-draft', 'active', now(), now()
)
