INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-064', 'aws-clf', 'O AWS Health Dashboard tem duas visões. Quais?',
  '[{"id":"A","text":"Cost Health e Security Health"},{"id":"B","text":"Dev Health e Prod Health"},{"id":"C","text":"Real-time Health e Historical Health"},{"id":"D","text":"Service Health (público, status global da AWS) e Account Health (personalizado, eventos que afetam sua conta)"}]'::jsonb, 'D',
  '{
    "summary": "AWS Health Dashboard combina Service Health (status público dos serviços AWS) e Account Health (eventos personalizados afetando recursos da sua conta).",
    "whyCorrect": "Service Health (ex-Status Page público) mostra incidentes globais por Region/serviço. Account Health (ex-Personal Health Dashboard) mostra eventos que afetam SUA conta especificamente (ex: instance scheduled retirement, maintenance window).",
    "whyWrong": {
     "A": "Não é a estrutura do Health Dashboard.",
     "B": "Não é dividido por ambiente.",
     "C": "Não é organizado por tempo."
    },
    "keyConcept": "AWS Health Dashboard — Service Health vs Account Health",
    "compareWith": [
     "Health Dashboard vs Trusted Advisor"
    ],
    "realWorldContext": "Equipes integram AWS Health Events com EventBridge para automatizar resposta (ex: criar ticket Jira em maintenance).",
    "commonMistakes": "Achar que ''AWS Status Page'' é só pública — Account Health é a parte personalizada.",
    "tutorSeeds": [
     "Como integrar AWS Health com EventBridge?",
     "Quais tipos de eventos aparecem em Account Health?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["aws-health","monitoring"]'::jsonb, 'ai-draft', 'active', now(), now()
)
