INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-065', 'aws-clf', 'Sobre FinOps na nuvem AWS, qual é a sequência canônica das 3 fases do framework FinOps?',
  '[{"id":"A","text":"Inform → Optimize → Operate"},{"id":"B","text":"Plan → Execute → Verify"},{"id":"C","text":"Discover → Save → Report"},{"id":"D","text":"Tag → Bill → Charge"}]'::jsonb, 'A',
  '{
    "summary": "FinOps Framework define 3 fases: Inform (visibilidade), Optimize (otimização), Operate (operação contínua).",
    "whyCorrect": "FinOps Foundation define 3 fases recursivas: Inform (tagging, alocação, métricas, dashboards), Optimize (right-sizing, RI/Savings Plans, Spot), Operate (governance, automação, cultura).",
    "whyWrong": {
     "B": "Não é a terminologia FinOps.",
     "C": "Não é o framework.",
     "D": "Tagging é parte do Inform, não a sequência completa."
    },
    "keyConcept": "FinOps — Inform → Optimize → Operate",
    "compareWith": [
     "FinOps phases vs DevOps phases"
    ],
    "realWorldContext": "Empresas maduras maintém FinOps team com práticas das 3 fases continuamente.",
    "commonMistakes": "Tratar FinOps como projeto único — é processo contínuo.",
    "tutorSeeds": [
     "Quais práticas específicas estão em cada fase?",
     "Como AWS Cost Explorer apoia a fase Inform?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["finops","cost-management"]'::jsonb, 'ai-draft', 'active', now(), now()
)
