INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-066', 'aws-clf', 'Em cloud financial management, qual diferença entre ''showback'' e ''chargeback''?',
  '[{"id":"A","text":"Showback e chargeback são sinônimos"},{"id":"B","text":"Showback exibe custos por unidade (departamento/time/projeto) sem cobrar internamente; chargeback efetivamente cobra a unidade pelo uso"},{"id":"C","text":"Showback é só para Enterprise; chargeback é para todos"},{"id":"D","text":"Showback usa USD; chargeback usa BRL"}]'::jsonb, 'B',
  '{
    "summary": "Showback = transparência de custos sem transferência financeira. Chargeback = transferência financeira efetiva (débito interno) para a unidade consumidora.",
    "whyCorrect": "Showback dá visibilidade (''seu time gastou X em S3'') sem afetar orçamento. Chargeback transfere o valor para o budget do time consumidor — força accountability financeira. Ambos exigem tagging rigoroso (cost allocation tags).",
    "whyWrong": {
     "A": "São conceitos distintos.",
     "C": "Não tem relação com plano de support.",
     "D": "Não tem relação com moeda."
    },
    "keyConcept": "Showback vs Chargeback — accountability financeira",
    "compareWith": [
     "Cost allocation tags — pré-requisito"
    ],
    "realWorldContext": "Empresas começam com showback (cultura) e depois evoluem para chargeback (accountability).",
    "commonMistakes": "Achar que tagging sozinho já é chargeback — exige processo financeiro também.",
    "tutorSeeds": [
     "Como AWS Cost Categories simplifica showback/chargeback?",
     "Quais tags são essenciais para alocação?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["finops","showback","chargeback"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
