INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-067', 'aws-clf', 'O AWS Customer Carbon Footprint Tool faz o quê?',
  '[{"id":"A","text":"Calcula custo financeiro mensal"},{"id":"B","text":"Faz auditoria de IAM"},{"id":"C","text":"Mostra emissões de carbono (MTCO2e) atribuídas ao uso AWS da conta, com tendências e projeções até 100% renovável"},{"id":"D","text":"Otimiza Reserved Instances"}]'::jsonb, 'C',
  '{
    "summary": "Customer Carbon Footprint Tool exibe emissões de CO2 equivalente atribuídas ao uso AWS, por Region/serviço/mês, com projeção de redução conforme AWS atinge metas de renováveis.",
    "whyCorrect": "Ferramenta gratuita no Console (Billing & Cost Management) que mostra Metric Tons CO2 Equivalent (MTCO2e) por mês, broken down por Region e tipo de serviço. Inclui visualização da redução projetada conforme AWS migra para 100% energia renovável (meta 2025).",
    "whyWrong": {
     "A": "Cost Explorer faz custo.",
     "B": "IAM Access Analyzer faz auditoria IAM.",
     "D": "Compute Optimizer trata de RI."
    },
    "keyConcept": "Customer Carbon Footprint Tool — emissões em MTCO2e",
    "compareWith": [
     "Carbon Footprint vs Cost Explorer"
    ],
    "realWorldContext": "Empresas com metas ESG/Net Zero usam essa ferramenta para reporting de pegada de carbono digital.",
    "commonMistakes": "Achar que é pago — é gratuito.",
    "tutorSeeds": [
     "Como AWS calcula emissões atribuídas por cliente?",
     "Qual a meta de energia renovável da AWS para 2025?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["sustainability","carbon-footprint"]'::jsonb, 'ai-draft', 'active', now(), now()
)
