INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-071', 'aws-clf', 'AWS Skill Builder é o quê?',
  '[{"id":"A","text":"Marketplace de cursos só pagos"},{"id":"B","text":"Programa exclusivo para empresas Enterprise"},{"id":"C","text":"Plataforma on-demand de cursos AWS — tier gratuito e Individual/Team paid subscriptions"},{"id":"D","text":"Substituto do AWS re/Start"}]'::jsonb, 'C',
  '{
    "summary": "AWS Skill Builder (skillbuilder.aws) é a plataforma central de treinamento AWS on-demand com tier gratuito (600+ cursos) e Subscriptions Individual/Team (com labs, Game-Based learning).",
    "whyCorrect": "Skill Builder é hub on-demand de treinamento AWS. Tier gratuito tem 600+ cursos digitais. Subscription Individual ($29/mês) e Team adicionam AWS Labs, AWS Jam (gamificado), Cloud Quest, e exam prep oficial.",
