INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-073', 'aws-clf', 'Uma empresa precisa rodar simulações científicas com 10.000 cores que duram 8h e podem ser interrompidas. Qual vantagem da nuvem é melhor aproveitada e por qual modelo de pricing?',
  '[{"id":"A","text":"Trade fixed for variable + Spot Instances"},{"id":"B","text":"Stop spending money on data centers + On-Demand"},{"id":"C","text":"Massive economies of scale + Reserved Instances"},{"id":"D","text":"Go global in minutes + Savings Plans"}]'::jsonb, 'A',
  '{
    "summary": "10.000 cores por 8h interrompíveis é caso clássico de Spot — pague só pelo uso (variable expense) com desconto até 90%.",
    "whyCorrect": "Workload elástico, interrompível e de curta duração combina perfeitamente com ''trade fixed for variable'' (paga só pelo uso) + Spot pricing (até 90% off vs On-Demand). HPC, render farms, ML training são casos canônicos.",
    "whyWrong": {
     "B": "DC não é o ponto — variabilidade do uso é.",
     "C": "RI exige 1-3 anos de commitment — péssimo para job de 8h.",
     "D": "Savings Plans tem commitment — não casa com workload pontual."
    },
    "keyConcept": "Trade fixed for variable + Spot pricing",
    "compareWith": [
     "Spot vs On-Demand vs RI vs Savings Plans"
    ],
    "realWorldContext": "Pesquisadores acadêmicos usam EC2 Spot para HPC barato — milhares de cores por horas a $0.01/hora.",
    "commonMistakes": "Achar que RI é sempre mais barato — depende do padrão de uso.",
    "tutorSeeds": [
     "Como Spot Instances podem ser interrompidas? Como mitigar?",
     "Quais workloads são candidatos a Spot?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["cloud-advantages","spot","hpc"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
