INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-074', 'aws-clf', 'Uma empresa B2B de educação está expandindo de SP para EUA e Europa. Por que escolher múltiplas Regions AWS é vantagem competitiva, e qual benefício da nuvem ela explora?',
  '[{"id":"A","text":"Apenas redução de custos"},{"id":"B","text":"''Go global in minutes'' — entrar em mercados rapidamente, com baixa latência, atendendo compliance local (GDPR/CCPA/LGPD), sem CapEx de DCs"},{"id":"C","text":"Apenas para reduzir SLAs"},{"id":"D","text":"Para aumentar custos por design"}]'::jsonb, 'B',
  '{
    "summary": "Múltiplas Regions habilitam entrada em mercados com baixa latência local + compliance regional (GDPR/CCPA/LGPD) sem CapEx — exemplo canônico de ''go global in minutes''.",
    "whyCorrect": "Entrar em UE/EUA exige (i) latência aceitável (regional presence), (ii) compliance (dados de UE em UE), (iii) capital baixo (sem DCs). Múltiplas Regions AWS resolvem tudo isso em minutos. Vantagem competitiva: time-to-market local.",
    "whyWrong": {
     "A": "Reduz CapEx, mas a vantagem principal aqui é alcance.",
     "C": "Não reduz SLA — pode até melhorar.",
     "D": "Não é o objetivo."
    },
    "keyConcept": "Go global in minutes — Regions + compliance",
    "compareWith": [
     "Multi-Region vs Multi-AZ"
    ],
    "realWorldContext": "Empresas como Nubank, Stripe, Shopify usam múltiplas Regions para expansão global rápida e compliance.",
    "commonMistakes": "Achar que basta abrir conta — compliance local exige design arquitetural.",
    "tutorSeeds": [
     "Quais regulações de soberania de dados afetam essa decisão?",
     "Como Route 53 latency routing decide qual Region servir?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["cloud-advantages","global","compliance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
