INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-075', 'aws-clf', 'Uma equipe de DevOps quer parar de gerenciar racks, energia, refrigeração e patches de OS host para focar em diferenciação de produto. Qual vantagem da nuvem expressa essa motivação?',
  '[{"id":"A","text":"Massive economies of scale"},{"id":"B","text":"Stop guessing capacity"},{"id":"C","text":"Stop spending money running and maintaining data centers"},{"id":"D","text":"Trade fixed for variable"}]'::jsonb, 'C',
  '{
    "summary": "''Stop spending money running and maintaining data centers'' é a vantagem canônica de focar em produto em vez de infra.",
    "whyCorrect": "Essa vantagem captura a desalocação de tempo/energia em ''undifferentiated heavy lifting'' (DC ops) para se focar em produto. AWS cuida de hardware/energia/refrigeração; cliente foca em código/customer.",
    "whyWrong": {
     "A": "Economies of scale é sobre pricing agregado.",
     "B": "Stop guessing trata de dimensionamento.",
     "D": "OpEx vs CapEx é financeiro, não foco operacional."
    },
    "keyConcept": "Undifferentiated heavy lifting — foco em diferenciação",
    "compareWith": [
     "6 vantagens — relacionamentos"
    ],
    "realWorldContext": "Empresas pequenas conseguem alcance de gigantes ao não construir DC própria.",
    "commonMistakes": "Confundir com ''trade fixed for variable'' — relacionados mas distintos.",
    "tutorSeeds": [
     "Quais as 6 vantagens completas?",
     "Como mensurar tempo gasto em ''heavy lifting'' vs diferenciação?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["cloud-advantages","focus"]'::jsonb, 'ai-draft', 'active', now(), now()
)
