INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-076', 'aws-clf', 'AWS Marketplace e AWS Service Catalog: qual diferença é CORRETA?',
  '[{"id":"A","text":"São o mesmo serviço com nomes diferentes"},{"id":"B","text":"Marketplace é interno; Service Catalog é externo"},{"id":"C","text":"Marketplace é gratuito; Service Catalog cobra por item"},{"id":"D","text":"Marketplace = vendors externos (3rd party software/SaaS, AMIs, containers); Service Catalog = produtos internos aprovados pela empresa para self-service controlado"}]'::jsonb, 'D',
  '{
    "summary": "Marketplace = catálogo de software de vendors externos (Splunk, Trend Micro, etc.) com billing integrado. Service Catalog = catálogo INTERNO de produtos aprovados pela TI para self-service em IaC (CloudFormation).",
    "whyCorrect": "Marketplace é loja AWS para SaaS, AMIs, containers de terceiros — billing unificado na fatura AWS. Service Catalog é ferramenta interna: TI publica produtos CloudFormation pre-aprovados (ex: ''EC2 com compliance corp X'') que devs/teams consomem self-service.",
    "whyWrong": {
     "A": "Serviços distintos com propósitos diferentes.",
     "B": "É o oposto — Marketplace é externo, Service Catalog é interno.",
     "C": "Pricing depende do produto, não é regra fixa."
    },
    "keyConcept": "Marketplace (3rd party) vs Service Catalog (interno)",
    "compareWith": [
     "Marketplace vs Service Catalog vs Quick Starts"
    ],
    "realWorldContext": "Empresas com governança forte usam Service Catalog para que devs só lancem recursos pré-aprovados.",
    "commonMistakes": "Confundir os dois — uma é loja externa, outra é catálogo interno.",
    "tutorSeeds": [
     "Como Service Catalog usa CloudFormation por baixo?",
     "Como Marketplace integra billing à fatura AWS?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["marketplace","service-catalog","governance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
