INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-077', 'aws-clf', 'Uma empresa quer configurar uma ''landing zone'' multi-account com governance, security baselines e SSO. Qual serviço AWS facilita esse setup?',
  '[{"id":"A","text":"AWS Control Tower"},{"id":"B","text":"AWS CodeCommit"},{"id":"C","text":"AWS Lambda"},{"id":"D","text":"AWS Workspaces"}]'::jsonb, 'A',
