INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-078', 'aws-clf', 'Sobre AWS Service Catalog, qual benefício é mais valorizado por times de governança?',
  '[{"id":"A","text":"É gratuito e ilimitado"},{"id":"B","text":"Permite que devs lancem recursos pré-aprovados em self-service, garantindo compliance sem ticket manual à TI"},{"id":"C","text":"Faz backup automático"},{"id":"D","text":"Otimiza custos automaticamente"}]'::jsonb, 'B',
