INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-079', 'aws-clf', 'Trusted Advisor: um cliente com AWS Basic Support tem acesso a quais checks?',
  '[{"id":"A","text":"Todos os checks de todas as 5 categorias"},{"id":"B","text":"Nenhum check"},{"id":"C","text":"Subset de checks: alguns de Security (ex: S3 bucket permissions, security groups) e todos de Service Limits/Quotas"},{"id":"D","text":"Apenas Cost Optimization"}]'::jsonb, 'C',
  '{
    "summary": "Basic e Developer Support têm acesso a 7 Trusted Advisor core checks (foco Security e Service Limits). Business e Enterprise têm acesso completo a todos os checks.",
    "whyCorrect": "Os 7 core checks disponíveis para Basic/Developer cobrem: S3 Bucket Permissions, Security Groups - Specific Ports Unrestricted, IAM Use, MFA on Root Account, EBS Public Snapshots, RDS Public Snapshots e Service Limits. Para acesso completo, é preciso Business+.",
    "whyWrong": {
     "A": "Acesso completo só com Business ou Enterprise.",
     "B": "Tem alguns checks gratuitos.",
     "D": "Cost Optimization completo só com Business+."
    },
    "keyConcept": "Trusted Advisor — checks por plano de support",
    "compareWith": [
     "Basic vs Business support — Trusted Advisor"
    ],
    "realWorldContext": "Mesmo contas Basic conseguem detectar S3 público via Trusted Advisor core checks.",
    "commonMistakes": "Achar que Basic Support não tem benefício de Trusted Advisor — tem subset valioso.",
    "tutorSeeds": [
     "Quais são exatamente os 7 core checks do TA?",
     "Quando vale upgrade para Business só pelos checks adicionais?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["trusted-advisor","aws-support"]'::jsonb, 'ai-draft', 'active', now(), now()
)
