INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-cc-v3-080', 'aws-clf', 'Uma fintech opera em sa-east-1 e quer adicionar Region us-east-1 como DR. Eles tagueam todos os recursos por ''Environment'' (prod/dev) e ''Owner'' (team). Qual conjunto de práticas AWS materializa boa governance financeira nesse cenário multi-Region?',
  '[{"id":"A","text":"Apenas usar Cost Explorer manualmente uma vez ao mês"},{"id":"B","text":"Bloquear tags e usar apenas total da fatura"},{"id":"C","text":"Pagar conta consolidada sem analisar"},{"id":"D","text":"Cost allocation tags (Environment, Owner), AWS Cost Explorer + Cost Categories para agregação, Budgets com alertas, Cost Anomaly Detection, e Compute Optimizer para right-sizing"}]'::jsonb, 'D',
  '{
    "summary": "Boa governance financeira multi-Region combina tagging consistente, agregação via Cost Categories, alertas via Budgets, detecção de anomalias e otimização via Compute Optimizer.",
    "whyCorrect": "O stack completo de FinOps na AWS inclui: (1) cost allocation tags para alocação por team/env, (2) Cost Categories para agrupar gastos em hierarquias business-friendly, (3) Budgets para alertas em thresholds, (4) Cost Anomaly Detection para spikes inesperados (ML), (5) Compute Optimizer para recomendar right-sizing/Savings Plans.",
    "whyWrong": {
     "A": "Manual mensal não pega anomalias em tempo real.",
     "B": "Sem tagging, alocação por team é impossível.",
     "C": "Não é prática — é negligência financeira."
    },
    "keyConcept": "FinOps stack — tags + categorias + budgets + anomaly + optimizer",
    "compareWith": [
     "Manual review vs automated FinOps"
    ],
    "realWorldContext": "Equipes FinOps maduras automatizam estes 5 controles via IaC e dashboards.",
    "commonMistakes": "Achar que basta Cost Explorer — sem tags consistentes, ele é cego para alocação.",
    "tutorSeeds": [
     "Como Cost Anomaly Detection usa ML para alertar spikes?",
     "Quais tags devem ser obrigatórias em uma tagging strategy?"
    ]
   }'::jsonb,
  'Cloud Concepts', 'Cloud Concepts', 'hard', 'best-practice', '["finops","cost-management","multi-region","governance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
