INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-001', 'aws-clf', 'Uma fintech migra um serviço crítico para Amazon EC2 rodando Ubuntu 22.04. Durante revisão de segurança, o auditor pergunta quem aplica patches do kernel quando uma CVE crítica é divulgada. Considerando o AWS Shared Responsibility Model para EC2, qual é a divisão correta?',
  '[{"id":"A","text":"O cliente é responsável pelo patching do guest OS, incluindo kernel"},{"id":"B","text":"AWS aplica patches automaticamente em todas as AMIs em execução"},{"id":"C","text":"AWS patcha o kernel; o cliente patcha apenas userland"},{"id":"D","text":"Patching é coberto pelo plano de suporte Business ou superior"}]'::jsonb, 'A',
  '{
    "summary": "Em EC2 o guest OS — incluindo kernel, libs e apps — é responsabilidade do cliente (''security IN the cloud''); AWS cuida do hardware, hypervisor e patches do host.",
    "whyCorrect": "Em EC2 o guest OS — incluindo kernel, libs e apps — é responsabilidade do cliente (''security IN the cloud''); AWS cuida do hardware, hypervisor e patches do host.",
    "whyWrong": {
     "B": "AWS não toca em instâncias em execução do cliente",
     "C": "não há split entre kernel e userland",
     "D": "planos de suporte não incluem patching operacional."
    },
    "keyConcept": "Regra: quanto menos managed o serviço, mais responsabilidade do cliente — EC2 é IaaS.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: quanto menos managed o serviço, mais responsabilidade do cliente — EC2 é IaaS?",
     "Quais cenários reais aplicam Regra: quanto menos managed o serviço, mais responsabilidade do cliente — EC2 é IaaS?",
     "Como EC2 se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["shared-responsibility","ec2","patching"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
