INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-002', 'aws-clf', 'Uma empresa usa Amazon RDS for PostgreSQL em modo Multi-AZ. Quem é responsável pela aplicação de patches do engine PostgreSQL e do sistema operacional subjacente da instância RDS?',
  '[{"id":"A","text":"O cliente, pois é IaaS"},{"id":"B","text":"AWS para SO e engine; o cliente apenas agenda a janela de manutenção"},{"id":"C","text":"O cliente, conectando-se via SSH à instância RDS"},{"id":"D","text":"AWS apenas para SO; engine PostgreSQL é do cliente"}]'::jsonb, 'B',
  '{
    "summary": "RDS é managed service: AWS gerencia SO subjacente, patches de engine e replicação Multi-AZ; cliente escolhe versão, agenda janela e gerencia dados/schema.",
    "whyCorrect": "RDS é managed service: AWS gerencia SO subjacente, patches de engine e replicação Multi-AZ; cliente escolhe versão, agenda janela e gerencia dados/schema.",
    "whyWrong": {
     "A": "RDS não é IaaS",
     "D": "patches de engine são responsabilidade da AWS dentro da versão escolhida.",
     "C": "Em Amazon RDS, o cliente NÃO tem acesso SSH ao host — a AWS bloqueia esse acesso porque o SO é managed. Toda interação é via endpoint do banco (porta 5432 do PostgreSQL) ou via Parameter Groups/Option Groups. Esta opção seria correta para um banco rodando em EC2 self-managed, onde o cliente tem SSH e patcha tudo."
    },
    "keyConcept": "Regra: managed DB → AWS cuida do plumbing, cliente cuida do dado.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: managed DB → AWS cuida do plumbing, cliente cuida do dado?",
     "Quais cenários reais aplicam Regra: managed DB → AWS cuida do plumbing, cliente cuida do dado?",
     "Como RDS se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["shared-responsibility","rds","managed-service"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
