INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-003', 'aws-clf', 'Uma equipe de desenvolvimento deploya uma função AWS Lambda escrita em Python 3.12 que processa eventos do Amazon SQS. Pelo Shared Responsibility Model, qual responsabilidade permanece com o cliente?',
  '[{"id":"A","text":"Patching do runtime Python 3.12 fornecido pela AWS"},{"id":"B","text":"Patching do sistema operacional onde a função executa"},{"id":"C","text":"Código da função, dependências em camadas e permissões IAM da execution role"},{"id":"D","text":"Manter o firewall do host onde a função roda"}]'::jsonb, 'C',
  '{
    "summary": "Em Lambda, AWS gerencia SO, runtime e infra; cliente é responsável pelo código, libs empacotadas, configuração e IAM.",
    "whyCorrect": "Em Lambda, AWS gerencia SO, runtime e infra; cliente é responsável pelo código, libs empacotadas, configuração e IAM.",
    "whyWrong": {
     "D": "cliente não tem acesso ao host nem firewall dele.",
     "A": "O runtime Python 3.12 em Lambda é fornecido e mantido pela AWS — patches de segurança do interpreter Python e libs nativas são aplicados pelo serviço automaticamente. O cliente apenas escolhe a versão do runtime; quando uma versão é deprecated, a AWS notifica e exige upgrade. Esta opção seria correta para Python instalado manualmente em EC2.",
     "B": "Lambda é fully managed — o cliente não tem acesso nem visibilidade do SO subjacente onde a função executa (Firecracker microVM). AWS patcha o SO, kernel e runtime sem intervenção do cliente. Esta opção seria correta para EC2 (IaaS), onde o cliente é dono do guest OS."
    },
    "keyConcept": "Regra: serverless → cliente cuida só do ''in the function''.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: serverless → cliente cuida só do ''in the function''?",
     "Quais cenários reais aplicam Regra: serverless → cliente cuida só do ''in the function''?",
     "Como AWS se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["shared-responsibility","lambda","serverless"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
