INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-006', 'aws-clf', 'Um auditor pergunta quem é responsável pela segurança física dos datacenters onde rodam workloads AWS de uma empresa brasileira na região sa-east-1. Qual a resposta correta?',
  '[{"id":"A","text":"O cliente, pois contratou a região sa-east-1"},{"id":"B","text":"AWS, pois faz parte da ''security OF the cloud''"},{"id":"C","text":"Compartilhada: AWS controla acesso físico, cliente audita o local presencialmente"},{"id":"D","text":"Cliente, se contratar plano Enterprise Support"}]'::jsonb, 'B',
  '{
    "summary": "Segurança física, controle de acesso a datacenters, energia, refrigeração e descarte de hardware são 100% AWS — ''security OF the cloud''.",
    "whyCorrect": "Segurança física, controle de acesso a datacenters, energia, refrigeração e descarte de hardware são 100% AWS — ''security OF the cloud''.",
    "whyWrong": {
     "C": "planos de suporte não dão acesso físico",
     "A": "Contratar uma região AWS é apenas escolher onde os workloads rodam — não transfere a responsabilidade da segurança física dos datacenters para o cliente. AWS mantém controle exclusivo do acesso físico em todas as regiões (comerciais, GovCloud, China). O cliente paga por uso, mas o controle físico permanece com a AWS.",
     "D": "Planos de suporte (Basic, Developer, Business, Enterprise) afetam o nível de assistência técnica recebida — não alteram o Shared Responsibility Model. Mesmo em Enterprise Support, a segurança física continua 100% AWS; nenhum plano dá ao cliente acesso aos datacenters."
    },
    "keyConcept": "Princípio fundacional do Shared Responsibility Model.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Princípio fundacional do Shared Responsibility Model?",
     "Quais cenários reais aplicam Princípio fundacional do Shared Responsibility Model?",
     "Como AWS se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'recall', '["shared-responsibility","physical-security"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
