INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-007', 'aws-clf', 'Uma empresa usa Amazon DynamoDB em modo on-demand. Quem é responsável por escalar a infraestrutura subjacente e por configurar criptografia em repouso, respectivamente?',
  '[{"id":"A","text":"Cliente escala; cliente habilita encryption"},{"id":"B","text":"AWS escala; AWS habilita encryption e bloqueia o cliente de mudar"},{"id":"C","text":"AWS escala; cliente habilita encryption (já vem ligada por padrão)"},{"id":"D","text":"Cliente escala via Auto Scaling Group; AWS habilita encryption"}]'::jsonb, 'C',
  '{
    "summary": "DynamoDB on-demand escala throughput automaticamente (AWS-managed); encryption at rest é habilitada por padrão e o cliente pode escolher entre AWS owned, AWS managed ou customer managed KMS keys.",
    "whyCorrect": "DynamoDB on-demand escala throughput automaticamente (AWS-managed); encryption at rest é habilitada por padrão e o cliente pode escolher entre AWS owned, AWS managed ou customer managed KMS keys.",
    "whyWrong": {
     "A": "Cliente não escala DynamoDB on-demand",
     "B": "cliente pode mudar a key.",
     "D": "DynamoDB é serverless — não há Auto Scaling Groups, instâncias EC2 ou capacidade visível para o cliente escalar. Em modo on-demand, o próprio DynamoDB ajusta throughput automaticamente; em provisioned, o cliente define RCU/WCU mas não toca em servidor. Auto Scaling Group é construto exclusivo do EC2."
    },
    "keyConcept": "Regra: managed → AWS cuida da infra; configurações de segurança são do cliente (mas defaults seguros).",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: managed → AWS cuida da infra; configurações de segurança são do cliente (mas defaults seguros)?",
     "Quais cenários reais aplicam Regra: managed → AWS cuida da infra; configurações de segurança são do cliente (mas defaults seguros)?",
     "Como AWS-managed se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["shared-responsibility","dynamodb","encryption"]'::jsonb, 'ai-draft', 'active', now(), now()
)
