INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-008', 'aws-clf', 'Em uma arquitetura híbrida via AWS Direct Connect, a equipe questiona quem é responsável pela criptografia do tráfego que sai do datacenter on-premises até chegar ao roteador AWS. Qual a resposta correta?',
  '[{"id":"A","text":"AWS criptografa automaticamente todo tráfego do Direct Connect"},{"id":"B","text":"Compartilhada: AWS criptografa na ida, cliente na volta"},{"id":"C","text":"Não é necessário pois o link é dedicado e fisicamente isolado"},{"id":"D","text":"O cliente, usando MACsec ou um VPN sobre o Direct Connect"}]'::jsonb, 'D',
  '{
    "summary": "Direct Connect é link dedicado mas não criptografado por padrão; cliente pode habilitar MACsec (em portas suportadas) ou rodar um Site-to-Site VPN sobre o DX para encryption in transit.",
    "whyCorrect": "Direct Connect é link dedicado mas não criptografado por padrão; cliente pode habilitar MACsec (em portas suportadas) ou rodar um Site-to-Site VPN sobre o DX para encryption in transit.",
    "whyWrong": {
     "A": "AWS não criptografa o tráfego do cliente sem solicitação",
     "C": "''dedicado'' não significa criptografado.",
     "B": "Direct Connect é um link L2/L3 simétrico — não há diferença de tratamento entre ''ida'' e ''volta''. Se há criptografia, ela cobre o tráfego bidirecionalmente (MACsec opera nas portas do link; VPN sobre DX cifra ambos os sentidos). Esta opção é tecnicamente incoerente."
    },
    "keyConcept": "Regra: encryption in transit em DX → cliente.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: encryption in transit em DX → cliente?",
     "Quais cenários reais aplicam Regra: encryption in transit em DX → cliente?",
     "Como MACsec se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["shared-responsibility","direct-connect","encryption-in-transit"]'::jsonb, 'ai-draft', 'active', now(), now()
)
