INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-010', 'aws-clf', 'Uma equipe usa Amazon S3 com SSE-S3 (chaves gerenciadas pela AWS). Quem é responsável pela rotação das chaves de criptografia e quem garante a durabilidade dos dados criptografados?',
  '[{"id":"A","text":"Cliente roda script de rotação; AWS garante durabilidade"},{"id":"B","text":"AWS rotaciona as chaves; AWS garante durabilidade"},{"id":"C","text":"Cliente rotaciona; cliente faz backup cross-region"},{"id":"D","text":"AWS rotaciona; cliente garante durabilidade ativando versioning"}]'::jsonb, 'B',
  '{
    "summary": "Em SSE-S3 a AWS gerencia totalmente as chaves (criação, rotação, proteção); a durabilidade 11 9s do S3 também é garantida pela AWS independentemente da classe de encryption.",
    "whyCorrect": "Em SSE-S3 a AWS gerencia totalmente as chaves (criação, rotação, proteção); a durabilidade 11 9s do S3 também é garantida pela AWS independentemente da classe de encryption.",
    "whyWrong": {
     "D": "backups e versioning são camadas adicionais opcionais, não substituem durabilidade nativa.",
     "A": "Em SSE-S3, a AWS rotaciona as chaves automaticamente — não há script do cliente. O cliente não tem visibilidade nem controle das chaves. Esta opção descreveria uma má interpretação do modelo SSE-S3. Para o cliente rotacionar manualmente, seria necessário SSE-KMS com CMK customer-managed.",
     "C": "Durabilidade dos 11 9s do S3 é garantida pela AWS independente de configuração do cliente — o objeto é replicado entre AZs internamente. Cross-region replication é defesa adicional contra desastre regional, mas não é prerequisito de durabilidade. SSE-S3 não exige nem é compatível com ''rotação manual''."
    },
    "keyConcept": "Regra: SSE-S3 = zero gestão de chaves para o cliente.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: SSE-S3 = zero gestão de chaves para o cliente?",
     "Quais cenários reais aplicam Regra: SSE-S3 = zero gestão de chaves para o cliente?",
     "Como SSE-S3 se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["shared-responsibility","s3","encryption","sse-s3"]'::jsonb, 'ai-draft', 'active', now(), now()
)
