INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-013', 'aws-clf', 'Uma empresa tem 200 colaboradores que precisam de acesso a múltiplas contas AWS de produção e desenvolvimento. Em vez de criar IAM users em cada conta, qual serviço AWS oferece SSO centralizado com integração ao provedor de identidade corporativo?',
  '[{"id":"A","text":"AWS IAM Identity Center (sucessor do AWS SSO)"},{"id":"B","text":"Amazon Cognito User Pools"},{"id":"C","text":"AWS Directory Service Simple AD"},{"id":"D","text":"AWS Secrets Manager com rotação automática"}]'::jsonb, 'A',
  '{
    "summary": "IAM Identity Center integra com Active Directory, Okta, Google Workspace via SAML 2.0 e fornece acesso centralizado a múltiplas contas AWS via permission sets.",
    "whyCorrect": "IAM Identity Center integra com Active Directory, Okta, Google Workspace via SAML 2.0 e fornece acesso centralizado a múltiplas contas AWS via permission sets.",
    "whyWrong": {
     "B": "Cognito é para autenticação de usuários finais em apps",
     "C": "Simple AD é diretório managed para EC2/RDS, não SSO multi-account",
     "D": "Secrets Manager guarda segredos, não autentica humanos."
    },
    "keyConcept": "Padrão AWS para identidade corporativa multi-account.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão AWS para identidade corporativa multi-account?",
     "Quais cenários reais aplicam Padrão AWS para identidade corporativa multi-account?",
     "Como IAM se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["iam","identity-center","sso","multi-account"]'::jsonb, 'ai-draft', 'active', now(), now()
)
