INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-014', 'aws-clf', 'Um desenvolvedor precisa que uma aplicação em EC2 publique mensagens em uma fila SQS. Qual é a forma mais segura recomendada pela AWS para conceder essa permissão?',
  '[{"id":"A","text":"Criar IAM user e armazenar access keys em arquivo no disco da instância"},{"id":"B","text":"Anexar uma IAM role à instância via instance profile com permissão sqs:SendMessage"},{"id":"C","text":"Liberar a fila SQS publicamente via resource policy"},{"id":"D","text":"Compartilhar a senha do IAM admin com a aplicação"}]'::jsonb, 'B',
  '{
    "summary": "Instance profiles entregam credenciais temporárias rotacionadas via IMDS — sem secret persistente.",
    "whyCorrect": "Instance profiles entregam credenciais temporárias rotacionadas via IMDS — sem secret persistente.",
    "whyWrong": {
     "A": "Access keys em disco são anti-pattern",
     "C": "fila pública viola least privilege e expõe ao mundo",
     "D": "Compartilhar credenciais de admin com uma aplicação é o pior anti-padrão de segurança: dá poder ilimitado, é difícil rotacionar, vaza facilmente em logs/disco e auditoria fica impossível (chamadas aparecem como o admin humano, não como a app). Aplicações devem usar credenciais de IAM role com escopo mínimo via instance profile."
    },
    "keyConcept": "Regra: workloads usam roles, nunca long-lived keys.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: workloads usam roles, nunca long-lived keys?",
     "Quais cenários reais aplicam Regra: workloads usam roles, nunca long-lived keys?",
     "Como IMDS se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["iam","instance-profile","ec2","least-privilege"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
