INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-015', 'aws-clf', 'Uma empresa quer que desenvolvedores tenham acesso temporário a recursos AWS apenas durante o expediente, com elevação por aprovação. Qual recurso IAM se encaixa melhor para credenciais temporárias com escopo limitado?',
  '[{"id":"A","text":"IAM users com senha que expira a cada 8 horas"},{"id":"B","text":"Access keys do root user rotacionadas diariamente"},{"id":"C","text":"IAM roles assumidas via AWS STS (sts:AssumeRole)"},{"id":"D","text":"Service-linked roles criadas automaticamente pelos serviços"}]'::jsonb, 'C',
  '{
    "summary": "Roles via STS retornam credenciais temporárias (15min a 12h), com policies anexadas e auditáveis no CloudTrail.",
    "whyCorrect": "Roles via STS retornam credenciais temporárias (15min a 12h), com policies anexadas e auditáveis no CloudTrail.",
    "whyWrong": {
     "B": "root nunca deve ter access keys",
     "D": "service-linked roles servem para o próprio serviço AWS atuar em nome do cliente, não para humanos.",
     "A": "IAM users com senha de expiração curta ainda são credenciais long-lived (a chave/senha persiste no disco/cofre do usuário) e não fornecem escopo limitado por sessão. Para acesso temporário com escopo e elevação por aprovação, o padrão é roles assumidas via STS, que retornam credenciais com TTL curto e auditoria por sessão. Senhas curtas são fricção sem ganho real de segurança."
    },
    "keyConcept": "Padrão de just-in-time access.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão de just-in-time access?",
     "Quais cenários reais aplicam Padrão de just-in-time access?",
     "Como STS se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["iam","sts","temporary-credentials"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
