INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-016', 'aws-clf', 'Uma startup tem 5 desenvolvedores que precisam das mesmas permissões em S3 e CloudWatch Logs. Qual é a abordagem mais eficiente de gerenciar essas permissões no IAM?',
  '[{"id":"A","text":"Anexar policies inline iguais em cada IAM user manualmente"},{"id":"B","text":"Criar 5 roles iguais e fazer os users assumirem cada um a sua"},{"id":"C","text":"Compartilhar credenciais de um único IAM user entre os 5"},{"id":"D","text":"Criar um IAM group com a policy necessária e adicionar os 5 users ao group"}]'::jsonb, 'D',
  '{
    "summary": "IAM groups permitem agrupar users e anexar policies uma vez — mudanças propagam para todos os membros.",
    "whyCorrect": "IAM groups permitem agrupar users e anexar policies uma vez — mudanças propagam para todos os membros.",
    "whyWrong": {
     "A": "Inline por user duplica esforço",
     "B": "5 roles iguais é overkill",
     "C": "compartilhar credenciais viola accountability e CloudTrail mostraria mesmo identificador."
    },
    "keyConcept": "Best practice: groups para permissões por função/role organizacional.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Best practice: groups para permissões por função/role organizacional?",
     "Quais cenários reais aplicam Best practice: groups para permissões por função/role organizacional?",
     "Como IAM se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["iam","groups","best-practices"]'::jsonb, 'ai-draft', 'active', now(), now()
)
