INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-018', 'aws-clf', 'Uma policy IAM contém um Allow para s3:* e a SCP da Organization nega s3:DeleteBucket. Quando o usuário tenta deletar um bucket, o que acontece?',
  '[{"id":"A","text":"A ação é permitida pois a IAM policy é mais específica"},{"id":"B","text":"A ação é negada — Deny explícito da SCP sempre prevalece"},{"id":"C","text":"Depende do tag aplicado ao bucket"},{"id":"D","text":"Aplica a policy criada mais recentemente"}]'::jsonb, 'B',
  '{
    "summary": "Avaliação IAM é: Deny explícito > Allow explícito > Deny implícito.",
    "whyCorrect": "Avaliação IAM é: Deny explícito > Allow explícito > Deny implícito. SCP com Deny corta o galho independente do que a IAM policy permita.",
    "whyWrong": {
     "A": "IAM policy não ''sobrepõe'' SCP tags só influenciam se a policy usa condition keys",
     "C": "Tags não alteram automaticamente a precedência de Deny — só importam se a policy contiver Condition explicitamente referenciando a tag. Sem essa condition, o Deny da SCP em s3:DeleteBucket aplica-se a todos os buckets, independente de tag. Esta opção seria relevante apenas com ABAC bem definido.",
     "D": "Avaliação IAM não tem semântica de ''policy mais recente vence'' — a ordem cronológica é irrelevante. O motor avalia todas as policies aplicáveis e aplica precedence: Deny explícito > Allow explícito > Deny implícito (default). Não há tiebreak por data."
    },
    "keyConcept": "Regra: efeito efetivo = interseção entre IAM, SCP, permission boundary, resource policy e session policies.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: efeito efetivo = interseção entre IAM, SCP, permission boundary, resource policy e session policies?",
     "Quais cenários reais aplicam Regra: efeito efetivo = interseção entre IAM, SCP, permission boundary, resource policy e session policies?",
     "Como IAM se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["iam","scp","policy-evaluation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
