INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-019', 'aws-clf', 'Após um quase-incidente, a equipe decidiu exigir MFA para qualquer ação em IAM users com permissões administrativas. Qual mecanismo IAM aplica essa exigência de MFA na própria policy?',
  '[{"id":"A","text":"Habilitar MFA no console e a policy é aplicada automaticamente"},{"id":"B","text":"Usar uma SCP global com Deny se IP for público"},{"id":"C","text":"Adicionar Condition aws:MultiFactorAuthPresent na policy"},{"id":"D","text":"Marcar a policy como ''MFA-only'' na role"}]'::jsonb, 'C',
  '{
    "summary": "Condition keys aws:MultiFactorAuthPresent / aws:MultiFactorAuthAge permitem exigir MFA por ação na policy.",
    "whyCorrect": "Condition keys aws:MultiFactorAuthPresent / aws:MultiFactorAuthAge permitem exigir MFA por ação na policy.",
    "whyWrong": {
     "A": "Habilitar MFA não força uso para chamadas de API sem condition",
     "D": "não existe atributo ''MFA-only'' nativo em role.",
     "B": "SCP com Deny baseado em IP público é controle de origem de rede, não de presença de MFA — bloqueia chamadas vindas de fora da empresa mas permite chamadas internas sem MFA. Não atende o requisito ''exigir MFA para ações administrativas''. SCP de IP seria correto para ''permitir só de IPs corporativos''."
    },
    "keyConcept": "Padrão: combinar MFA Required no IAM + sts:GetSessionToken com MFA token.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão: combinar MFA Required no IAM + sts:GetSessionToken com MFA token?",
     "Quais cenários reais aplicam Padrão: combinar MFA Required no IAM + sts:GetSessionToken com MFA token?",
     "Como MFA se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'best-practice', '["iam","mfa","condition-keys"]'::jsonb, 'ai-draft', 'active', now(), now()
)
