INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-020', 'aws-clf', 'Uma desenvolvedora precisa que uma função Lambda leia objetos de um bucket S3 em outra conta AWS. Qual abordagem cumpre o cross-account access de forma idiomática?',
  '[{"id":"A","text":"Tornar o bucket público para facilitar a leitura"},{"id":"B","text":"Compartilhar access keys do IAM user da outra conta com a Lambda"},{"id":"C","text":"Replicar o bucket inteiro para a conta da Lambda"},{"id":"D","text":"Lambda execution role com sts:AssumeRole numa role da outra conta + bucket policy permitindo essa role"}]'::jsonb, 'D',
  '{
    "summary": "Padrão cross-account: role na conta destino com trust policy aceitando a role da origem; a Lambda assume essa role via STS e usa as credenciais temporárias.",
    "whyCorrect": "Padrão cross-account: role na conta destino com trust policy aceitando a role da origem; a Lambda assume essa role via STS e usa as credenciais temporárias. Bucket policy adicional permite a role destino.",
    "whyWrong": {
     "A": "Bucket público é furo de segurança replicação é overkill para leitura.",
     "B": "access keys cruzadas viola least privilege e accountability",
     "C": "Cross-Region/Cross-Account Replication copia o bucket inteiro para a conta da Lambda — caro (custo de armazenamento duplicado), introduz lag de replicação e duplica superfície de ataque. Para apenas LER objetos sob demanda, o padrão correto é cross-account com role assumida; replicação seria justificada por requisito de DR ou data residency, não por acesso pontual."
    },
    "keyConcept": "Regra: cross-account = role assumida, não credenciais compartilhadas.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: cross-account = role assumida, não credenciais compartilhadas?",
     "Quais cenários reais aplicam Regra: cross-account = role assumida, não credenciais compartilhadas?",
     "Como STS se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["iam","cross-account","sts","lambda"]'::jsonb, 'ai-draft', 'active', now(), now()
)
