INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-021', 'aws-clf', 'Uma policy IAM tem efeito Allow para ec2:* mas o usuário recebe AccessDenied ao tentar iniciar uma instância. CloudTrail mostra que a chamada foi explicitamente negada por uma SCP. O que isso indica?',
  '[{"id":"A","text":"A SCP é avaliada antes da IAM policy e impede a ação no nível da conta"},{"id":"B","text":"A IAM policy está mal escrita e precisa de aspas duplas"},{"id":"C","text":"O usuário não habilitou MFA"},{"id":"D","text":"EC2 está fora de suporte naquela região"}]'::jsonb, 'A',
  '{
    "summary": "SCPs definem o teto máximo de permissões para principals dentro da conta; qualquer Deny da SCP bloqueia mesmo que IAM permita.",
    "whyCorrect": "SCPs definem o teto máximo de permissões para principals dentro da conta; qualquer Deny da SCP bloqueia mesmo que IAM permita.",
    "whyWrong": {
     "D": "suporte de serviço não negaria via SCP.",
     "B": "AccessDenied por SCP é uma decisão de autorização do plano IAM/Organizations — não tem relação com sintaxe JSON da policy. Se houvesse erro de sintaxe, a policy não seria salva pelo IAM. CloudTrail registra ''explicitly denied by SCP'', que é diagnostic definitivo de bloqueio por Organization-level policy.",
     "C": "MFA está ausente da causa raiz: a SCP nega explicitamente a ação, independentemente de MFA. Habilitar MFA não removeria o Deny da SCP. Esta opção seria relevante se o erro fosse ''this action requires MFA'', vindo de uma policy com aws:MultiFactorAuthPresent condition."
    },
    "keyConcept": "Regra: efeito final é interseção entre todos os layers de policy (SCP ∩ IAM ∩ boundary ∩ resource ∩ session).",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: efeito final é interseção entre todos os layers de policy (SCP ∩ IAM ∩ boundary ∩ resource ∩ session)?",
     "Quais cenários reais aplicam Regra: efeito final é interseção entre todos os layers de policy (SCP ∩ IAM ∩ boundary ∩ resource ∩ session)?",
     "Como SCPs se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'troubleshoot', '["iam","scp","troubleshoot"]'::jsonb, 'ai-draft', 'active', now(), now()
)
