INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-024', 'aws-clf', 'Uma policy IAM customer-managed foi criada com ''Resource'': ''*'' para acesso a S3. A equipe de segurança classifica isso como risco. Qual prática reduz esse risco mantendo a funcionalidade?',
  '[{"id":"A","text":"Adicionar versão 2012-10-17 à policy"},{"id":"B","text":"Mudar Effect de Allow para Allow-Specific"},{"id":"C","text":"Encriptar a policy com KMS"},{"id":"D","text":"Trocar Resource:* por ARNs específicos dos buckets necessários"}]'::jsonb, 'D',
  '{
    "summary": "Resource:* dá permissão em todos os buckets da conta; limitar a ARNs específicos aplica least privilege ao nível de recurso.",
    "whyCorrect": "Resource:* dá permissão em todos os buckets da conta; limitar a ARNs específicos aplica least privilege ao nível de recurso.",
    "whyWrong": {
     "A": "Version 2012-10-17 é apenas formato",
     "B": "não há ''Allow-Specific''",
     "C": "Policies IAM são objetos JSON públicos dentro da conta — não há mecanismo de criptografá-las com KMS, e isso não reduziria o risco da Resource:* (a permissão continua sendo amplíssima). Risco de Resource:* é semântico (escopo da permissão), não de confidencialidade do documento da policy."
    },
    "keyConcept": "Padrão: restringir Action E Resource ao mínimo necessário.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão: restringir Action E Resource ao mínimo necessário?",
     "Quais cenários reais aplicam Padrão: restringir Action E Resource ao mínimo necessário?",
     "Como ARNs se compara com alternativas?"
    ]
   }'::jsonb,
