INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-025', 'aws-clf', 'Uma empresa quer permitir que pipelines do GitHub Actions deployem para a AWS sem armazenar access keys long-lived nos secrets do repositório. Qual mecanismo IAM resolve isso?',
  '[{"id":"A","text":"OIDC provider no IAM + role assumida pelo GitHub Actions"},{"id":"B","text":"Criar IAM user dedicado com policy ampla e armazenar keys em GitHub Secrets"},{"id":"C","text":"Compartilhar a senha do root via secret encriptado"},{"id":"D","text":"Configurar GitHub Actions como service-linked role"}]'::jsonb, 'A',
  '{
    "summary": "Configurar token.actions.githubusercontent.com como OIDC provider no IAM permite que jobs do GitHub Actions assumam roles via STS — sem keys persistentes.",
    "whyCorrect": "Configurar token.actions.githubusercontent.com como OIDC provider no IAM permite que jobs do GitHub Actions assumam roles via STS — sem keys persistentes.",
    "whyWrong": {
     "B": "Keys long-lived em secrets é o anti-pattern que se quer eliminar",
     "C": "root jamais",
     "D": "service-linked role é para serviços AWS internos atuarem em nome do cliente."
    },
    "keyConcept": "Padrão moderno: federated identity para CI/CD.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão moderno: federated identity para CI/CD?",
