INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-026', 'aws-clf', 'Uma empresa tem 30 contas AWS organizadas em diferentes departamentos. Qual serviço AWS permite gerenciar todas centralmente, com consolidated billing, criação automatizada de contas e aplicação de políticas?',
  '[{"id":"A","text":"AWS IAM Identity Center"},{"id":"B","text":"AWS Organizations"},{"id":"C","text":"AWS Resource Access Manager"},{"id":"D","text":"AWS Config Aggregator"}]'::jsonb, 'B',
  '{
    "summary": "Organizations é o serviço de multi-account: consolidated billing, OUs, SCPs, criação programática de contas.",
    "whyCorrect": "Organizations é o serviço de multi-account: consolidated billing, OUs, SCPs, criação programática de contas.",
    "whyWrong": {
     "A": "IAM Identity Center cuida de acesso de pessoas",
     "D": "Config Aggregator agrega findings de Config.",
     "C": "AWS Resource Access Manager (RAM) compartilha recursos específicos (Subnets, Transit Gateways, License Manager configurations) entre contas — não gerencia hierarquia multi-account, billing consolidado, criação de contas ou SCPs. RAM seria a resposta para ''compartilhar uma subnet entre duas contas''; gerenciamento multi-account central é Organizations."
    },
    "keyConcept": "Padrão: Organizations é a base; outros serviços se integram a ele.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão: Organizations é a base; outros serviços se integram a ele?",
     "Quais cenários reais aplicam Padrão: Organizations é a base; outros serviços se integram a ele?",
     "Como OUs se compara com alternativas?"
    ]
   }'::jsonb,
