INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-029', 'aws-clf', 'Em uma Organization existem OUs separadas para Prod, Dev e Sandbox. A equipe quer permissões diferentes por OU. Onde aplicar uma SCP que afete apenas as contas-membro da OU Sandbox?',
  '[{"id":"A","text":"Anexar a SCP diretamente à OU Sandbox"},{"id":"B","text":"Anexar a SCP à root da Organization"},{"id":"C","text":"Anexar a SCP a cada IAM user das contas Sandbox"},{"id":"D","text":"Aplicar via Resource Access Manager"}]'::jsonb, 'A',
  '{
    "summary": "SCPs podem ser anexadas à root, OU ou conta individual; escopo herda para baixo.",
    "whyCorrect": "SCPs podem ser anexadas à root, OU ou conta individual; escopo herda para baixo. Anexar à OU Sandbox afeta exatamente suas contas-filhas.",
    "whyWrong": {
     "B": "Anexar na root afeta tudo SCPs não vão em IAM users (são policies da Organization, não IAM)",
     "C": "SCPs são anexadas a containers organizacionais (root, OU, conta) — NÃO a IAM users diretamente. SCP define o teto de uma conta inteira; IAM users dessa conta recebem permissões via IAM policy/groups/roles, e a SCP é aplicada implicitamente. Anexar SCP a user não existe na API.",
     "D": "Resource Access Manager (RAM) compartilha RECURSOS (subnets, TGW) entre contas — não aplica policies de permissão. RAM não tem mecanismo de Deny por OU. Para limitar permissões em uma OU, a ferramenta é SCP em Organizations; RAM é orthogonal."
    },
    "keyConcept": "Padrão: aplique SCP no menor escopo que cumpre o requisito.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão: aplique SCP no menor escopo que cumpre o requisito?",
     "Quais cenários reais aplicam Padrão: aplique SCP no menor escopo que cumpre o requisito?",
     "Como SCPs se compara com alternativas?"
    ]
