INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-041', 'aws-clf', 'Uma empresa armazena dados sensíveis em S3 e quer criptografia em repouso usando chaves gerenciadas pela AWS sem custo extra de KMS. Qual opção atende?',
  '[{"id":"A","text":"SSE-S3 (server-side encryption com chaves S3-managed)"},{"id":"B","text":"SSE-KMS com customer managed key"},{"id":"C","text":"SSE-C com chaves fornecidas pelo cliente"},{"id":"D","text":"Client-side encryption antes do upload"}]'::jsonb, 'A',
  '{
    "summary": "SSE-S3 usa chaves totalmente gerenciadas pelo S3, AES-256, sem custo adicional além do armazenamento.",
    "whyCorrect": "SSE-S3 usa chaves totalmente gerenciadas pelo S3, AES-256, sem custo adicional além do armazenamento.",
    "whyWrong": {
     "D": "client-side encryption exige libs e gestão pelo cliente.",
     "B": "SSE-KMS com customer managed key adiciona custo de KMS: $1/mês por CMK + $0.03 por 10.000 requests de cifragem/decifragem — o que pode ser significativo em buckets de alto throughput. SSE-KMS oferece audit detalhado e controle de policy, mas o requisito explícito é ''sem custo extra de KMS''.",
     "C": "SSE-C exige que o cliente FORNEÇA a chave em cada PUT/GET via header — é o cliente quem gerencia o material criptográfico (rotação, armazenamento, distribuição). Adiciona complexidade operacional grande e não usa ''chaves gerenciadas pela AWS'' como o requisito pede. SSE-C seria correto para ''cliente quer manter chaves fora da AWS mas usar S3''."
    },
    "keyConcept": "Regra: opção padrão sem custo extra → SSE-S3; auditoria/controle mais fino → SSE-KMS.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: opção padrão sem custo extra → SSE-S3; auditoria/controle mais fino → SSE-KMS?",
     "Quais cenários reais aplicam Regra: opção padrão sem custo extra → SSE-S3; auditoria/controle mais fino → SSE-KMS?",
     "Como SSE-S3 se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["encryption","s3","sse-s3"]'::jsonb, 'ai-draft', 'active', now(), now()
)
