INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-042', 'aws-clf', 'A equipe precisa auditar cada chamada de Encrypt/Decrypt de uma chave KMS específica usada para proteger dados financeiros. Qual combinação entrega essa visibilidade?',
  '[{"id":"A","text":"AWS-managed key (aws/s3) + AWS Config"},{"id":"B","text":"Customer managed CMK no KMS + CloudTrail registrando KMS data events"},{"id":"C","text":"SSE-S3 + AWS Trusted Advisor"},{"id":"D","text":"AWS Shield Advanced + GuardDuty"}]'::jsonb, 'B',
  '{
    "summary": "Customer managed CMK dá controle de policy e rotação; CloudTrail registra automaticamente todas as KMS API calls (Encrypt, Decrypt, GenerateDataKey, etc.) — auditoria completa.",
    "whyCorrect": "Customer managed CMK dá controle de policy e rotação; CloudTrail registra automaticamente todas as KMS API calls (Encrypt, Decrypt, GenerateDataKey, etc.) — auditoria completa.",
    "whyWrong": {
     "A": "AWS-managed keys têm controle limitado Config detecta config drift mas não chamadas",
     "C": "Trusted Advisor é dicas",
     "D": "Shield/GuardDuty cobrem outras camadas."
    },
    "keyConcept": "Padrão: auditoria fina de uso de chave → CMK + CloudTrail.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão: auditoria fina de uso de chave → CMK + CloudTrail?",
     "Quais cenários reais aplicam Padrão: auditoria fina de uso de chave → CMK + CloudTrail?",
     "Como CMK se compara com alternativas?"
    ]
   }'::jsonb,
