INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-043', 'aws-clf', 'Uma equipe precisa de FIPS 140-2 Level 3 com HSM single-tenant dedicado, sob controle exclusivo do cliente para geração de chaves de TLS. Qual serviço AWS atende?',
  '[{"id":"A","text":"AWS KMS com AWS managed key"},{"id":"B","text":"AWS Secrets Manager"},{"id":"C","text":"AWS CloudHSM"},{"id":"D","text":"AWS Certificate Manager Private CA"}]'::jsonb, 'C',
  '{
    "summary": "CloudHSM é HSM dedicado FIPS 140-2 Level 3 onde o cliente controla 100% das chaves (AWS não tem acesso).",
    "whyCorrect": "CloudHSM é HSM dedicado FIPS 140-2 Level 3 onde o cliente controla 100% das chaves (AWS não tem acesso).",
    "whyWrong": {
     "B": "Secrets Manager guarda segredos, não é HSM",
     "D": "ACM Private CA emite certificados, não substitui HSM.",
     "A": "AWS managed key no KMS (aws/serviço) é multi-tenant — a chave é compartilhada logicamente com outros clientes da AWS e a key policy é controlada pela AWS, não pelo cliente. Não atende o requisito de HSM single-tenant sob controle exclusivo. KMS standard é FIPS 140-2 Level 3 em alguns endpoints, mas não é dedicated HSM."
    },
    "keyConcept": "Regra: HSM dedicado single-tenant → CloudHSM; gestão de chaves padrão → KMS.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: HSM dedicado single-tenant → CloudHSM; gestão de chaves padrão → KMS?",
     "Quais cenários reais aplicam Regra: HSM dedicado single-tenant → CloudHSM; gestão de chaves padrão → KMS?",
     "Como HSM se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["encryption","cloudhsm","fips"]'::jsonb, 'ai-draft', 'active', now(), now()
)
