INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-044', 'aws-clf', 'Um arquiteto quer ativar encryption at rest em todos os volumes EBS criados na conta, sem depender da equipe lembrar de marcar a opção. Qual configuração resolve?',
  '[{"id":"A","text":"Configurar uma SCP que negue ec2:CreateVolume"},{"id":"B","text":"Adicionar uma tag ''Encrypted=true'' em cada volume"},{"id":"C","text":"Habilitar AWS Shield Advanced na conta"},{"id":"D","text":"Ativar EBS encryption by default na região via console/CLI"}]'::jsonb, 'D',
  '{
    "summary": "EBS encryption by default é setting por região: a partir daí, todo novo volume e snapshot são criptografados com a chave default ou customer-managed.",
    "whyCorrect": "EBS encryption by default é setting por região: a partir daí, todo novo volume e snapshot são criptografados com a chave default ou customer-managed.",
    "whyWrong": {
     "A": "SCP negando CreateVolume impede criação, não força encryption",
     "C": "Shield é DDoS.",
     "B": "Tag em volume é apenas metadata — não cifra dados nem altera o flag ''Encrypted'' do volume. Mesmo com a tag ''Encrypted=true'', se a opção de criptografia não foi marcada na criação, o volume permanecerá em plaintext. Para garantir encryption sem confiar em processo manual, é necessário EBS encryption by default no nível da região."
    },
    "keyConcept": "Padrão: ''encryption by default'' como guardrail.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão: ''encryption by default'' como guardrail?",
     "Quais cenários reais aplicam Padrão: ''encryption by default'' como guardrail?",
     "Como EBS se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["encryption","ebs","by-default"]'::jsonb, 'ai-draft', 'active', now(), now()
)
