INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-045', 'aws-clf', 'Uma empresa precisa decidir entre SSE-KMS e SSE-S3 para um bucket. O requisito é poder revogar acesso em massa a todos os objetos cifrados desativando uma única chave. Qual opção atende?',
  '[{"id":"A","text":"SSE-KMS com customer managed CMK"},{"id":"B","text":"SSE-S3 (S3-managed key)"},{"id":"C","text":"SSE-C (chave do cliente em cada request)"},{"id":"D","text":"Plaintext com bucket policy restritiva"}]'::jsonb, 'A',
  '{
    "summary": "CMK no KMS pode ser disabled/scheduled for deletion — desativá-la torna todos os objetos efetivamente ilegíveis até reativação.",
    "whyCorrect": "CMK no KMS pode ser disabled/scheduled for deletion — desativá-la torna todos os objetos efetivamente ilegíveis até reativação.",
    "whyWrong": {
     "C": "SSE-S3 não dá controle de chave ao cliente SSE-C exige enviar chave em cada request (não dá kill switch central)",
     "D": "plaintext não cifra.",
     "B": "SSE-S3 usa chaves totalmente gerenciadas pelo S3 — o cliente não tem visibilidade da chave nem pode desativá-la. Não há ''kill switch'' criptográfico em SSE-S3. Para revogar acesso em massa, seria necessário uma CMK que o cliente possa disable; isso requer SSE-KMS com customer managed key."
    },
    "keyConcept": "Padrão: ''kill switch'' criptográfico = CMK no KMS.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão: ''kill switch'' criptográfico = CMK no KMS?",
     "Quais cenários reais aplicam Padrão: ''kill switch'' criptográfico = CMK no KMS?",
     "Como CMK se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["encryption","kms","cmk","revocation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
