INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-048', 'aws-clf', 'Uma startup quer cifrar dados em uma tabela DynamoDB usando chave que só ela controla, para conformidade contratual com cliente enterprise. Qual configuração atende?',
  '[{"id":"A","text":"Desabilitar a encryption nativa e cifrar via Lambda trigger"},{"id":"B","text":"Usar SSE-C com chave em cada PutItem"},{"id":"C","text":"Habilitar Macie no bucket de origem"},{"id":"D","text":"DynamoDB encryption com customer managed KMS key"}]'::jsonb, 'D',
  '{
    "summary": "DynamoDB suporta 3 níveis: AWS owned (default), AWS managed (aws/dynamodb), customer managed CMK — este último dá controle total de policy, rotação e revogação.",
    "whyCorrect": "DynamoDB suporta 3 níveis: AWS owned (default), AWS managed (aws/dynamodb), customer managed CMK — este último dá controle total de policy, rotação e revogação.",
    "whyWrong": {
     "A": "Não é possível desabilitar encryption em DynamoDB (sempre ligada)",
     "C": "Macie é descoberta em S3.",
     "B": "SSE-C (server-side encryption com customer-provided key) não é suportado pelo DynamoDB — é uma opção exclusiva do S3. DynamoDB suporta apenas as três opções de KMS (AWS owned, AWS managed, customer managed). Para chave sob controle exclusivo do cliente, a resposta é customer managed CMK no KMS."
    },
    "keyConcept": "Regra: chave sob controle do cliente → customer managed CMK.",
    "tutorSeeds": [
