INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-049', 'aws-clf', 'Um app uploadou arquivos para S3 mas o cliente exige que a AWS jamais tenha acesso ao material criptográfico das chaves. Qual abordagem atende esse requisito?',
  '[{"id":"A","text":"Client-side encryption antes do upload, com chaves gerenciadas fora da AWS"},{"id":"B","text":"SSE-S3 com AES-256"},{"id":"C","text":"SSE-KMS com aws/s3 key"},{"id":"D","text":"Ativar Block Public Access no bucket"}]'::jsonb, 'A',
  '{
    "summary": "Client-side encryption (ex.: AWS Encryption SDK com chave em CloudHSM ou KMS External Key Store) cifra antes do upload; o S3 recebe apenas ciphertext.",
    "whyCorrect": "Client-side encryption (ex.: AWS Encryption SDK com chave em CloudHSM ou KMS External Key Store) cifra antes do upload; o S3 recebe apenas ciphertext.",
    "whyWrong": {
     "D": "Block Public Access controla exposição, não confidencialidade frente à AWS.",
     "B": "SSE-S3 usa AES-256 com chaves gerenciadas pela AWS — a AWS tem acesso ao material criptográfico (é quem rotaciona). Não atende o requisito ''AWS jamais ter acesso ao material das chaves''. SSE-S3 é o oposto: zero gestão de chave pelo cliente.",
     "C": "SSE-KMS com a chave aws/s3 (AWS managed key) é multi-tenant e o material criptográfico fica sob controle da AWS — não atende ''AWS jamais ter acesso''. Mesmo SSE-KMS com customer managed key tem a chave dentro do KMS AWS (a menos que use External Key Store). Client-side encryption é a única forma de garantir que apenas ciphertext chegue à AWS."
    },
    "keyConcept": "Padrão: ''AWS never sees plaintext keys'' → client-side ou KMS XKS.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão: ''AWS never sees plaintext keys'' → client-side ou KMS XKS?",
     "Quais cenários reais aplicam Padrão: ''AWS never sees plaintext keys'' → client-side ou KMS XKS?",
     "Como AWS Encryption se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["encryption","client-side","kms-xks"]'::jsonb, 'ai-draft', 'active', now(), now()
)
