INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-050', 'aws-clf', 'Em transit entre serviços AWS na mesma região, parte do tráfego (ex.: dentro de Nitro System) já é cifrado por padrão. Qual a melhor postura para um arquiteto seguir?',
  '[{"id":"A","text":"Desligar TLS para reduzir overhead de CPU"},{"id":"B","text":"Confiar na encryption AWS-side mas habilitar TLS em todas as conexões app-level também"},{"id":"C","text":"Usar somente IPv6 que é cifrado por design"},{"id":"D","text":"Confiar no SG do EC2 como única camada"}]'::jsonb, 'B',
  '{
    "summary": "Defense in depth: AWS cifra parte do tráfego intra-region, mas o cliente é responsável por encryption in transit no nível de aplicação (TLS, mTLS) para garantir confidencialidade ponta-a-ponta independente da camada AWS.",
    "whyCorrect": "Defense in depth: AWS cifra parte do tráfego intra-region, mas o cliente é responsável por encryption in transit no nível de aplicação (TLS, mTLS) para garantir confidencialidade ponta-a-ponta independente da camada AWS.",
    "whyWrong": {
     "A": "Desligar TLS reduz overhead mas viola compliance",
     "C": "IPv6 não é cifrado por design",
     "D": "Security Group filtra acesso de rede (IP/porta) — não fornece confidencialidade do payload. SG impede conexões não autorizadas mas não cifra dados em trânsito; um atacante na mesma subnet com SG permissivo veria tráfego plaintext. SG é uma camada de defesa, mas não substitui TLS para encryption in transit."
    },
    "keyConcept": "Padrão: in transit encryption em todos os hops controláveis.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão: in transit encryption em todos os hops controláveis?",
     "Quais cenários reais aplicam Padrão: in transit encryption em todos os hops controláveis?",
     "Como AWS se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["encryption","in-transit","tls","defense-in-depth"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
