INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-051', 'aws-clf', 'Uma equipe precisa armazenar credenciais de banco de dados que serão rotacionadas automaticamente a cada 30 dias, com integração nativa ao RDS. Qual serviço atende melhor?',
  '[{"id":"A","text":"AWS Systems Manager Parameter Store (Standard, SecureString)"},{"id":"B","text":"Variáveis de ambiente do EC2"},{"id":"C","text":"AWS Secrets Manager"},{"id":"D","text":"Bucket S3 privado com SSE-KMS"}]'::jsonb, 'C',
  '{
    "summary": "Secrets Manager faz rotação automática nativa para RDS, Redshift, DocumentDB (Lambda built-in) e suporta rotação custom; entrega via API IAM-protegida.",
    "whyCorrect": "Secrets Manager faz rotação automática nativa para RDS, Redshift, DocumentDB (Lambda built-in) e suporta rotação custom; entrega via API IAM-protegida.",
    "whyWrong": {
     "A": "Parameter Store SecureString armazena segredos mas não rotaciona automaticamente sem build custom",
     "B": "Variáveis de ambiente em EC2 ficam em plaintext acessíveis a qualquer processo da instância (incluindo logs e core dumps); não rotacionam automaticamente; não auditam acessos; e qualquer comprometimento do host expõe credenciais. É anti-padrão para qualquer secret sensível, especialmente credenciais de banco.",
     "D": "Bucket S3 com SSE-KMS dá at-rest encryption e IAM-based access, mas não tem rotação automática nativa integrada ao RDS — exigiria pipeline custom (Lambda + EventBridge) para girar senha no RDS e atualizar o objeto. Reinventaria o que Secrets Manager já oferece pronto. S3 seria correto para artefatos grandes, não para secrets pequenos com rotação."
    },
    "keyConcept": "Regra: rotação automática + integração managed → Secrets Manager; segredos simples sem rotação → Parameter Store.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: rotação automática + integração managed → Secrets Manager; segredos simples sem rotação → Parameter Store?",
     "Quais cenários reais aplicam Regra: rotação automática + integração managed → Secrets Manager; segredos simples sem rotação → Parameter Store?",
     "Como RDS se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["secrets","secrets-manager","rotation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
