INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-052', 'aws-clf', 'Uma startup quer guardar API keys de terceiros gratuitamente, sem necessidade de rotação automática nem high-throughput. Qual opção é mais econômica?',
  '[{"id":"A","text":"AWS Secrets Manager"},{"id":"B","text":"AWS CloudHSM dedicado"},{"id":"C","text":"DynamoDB com SSE-KMS"},{"id":"D","text":"AWS Systems Manager Parameter Store SecureString (Standard tier)"}]'::jsonb, 'D',
  '{
    "summary": "Parameter Store Standard SecureString é gratuito (até quota), cifrado via KMS, simples de usar para segredos estáticos.",
    "whyCorrect": "Parameter Store Standard SecureString é gratuito (até quota), cifrado via KMS, simples de usar para segredos estáticos.",
    "whyWrong": {
     "A": "Secrets Manager cobra por segredo/mês + chamadas [extra: desnecessário sem rotação]",
     "B": "CloudHSM é caro e overkill",
     "C": "DynamoDB exige montar acesso e cifrar manualmente."
    },
    "keyConcept": "Regra: ''segredo simples sem rotação'' → Parameter Store Standard.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: ''segredo simples sem rotação'' → Parameter Store Standard?",
     "Quais cenários reais aplicam Regra: ''segredo simples sem rotação'' → Parameter Store Standard?",
