INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-053', 'aws-clf', 'Uma aplicação em Lambda precisa ler uma senha do banco de dados a cada cold start. A equipe está preocupada com custo de chamadas ao Secrets Manager. Qual abordagem reduz custo mantendo segurança?',
  '[{"id":"A","text":"Usar AWS Parameters and Secrets Lambda Extension (cache local) ou cache em memória entre invocações"},{"id":"B","text":"Hardcoded em variável de ambiente sem encryption"},{"id":"C","text":"Embedded na imagem da Lambda em texto plano"},{"id":"D","text":"Lido do IAM user access key armazenado no S3"}]'::jsonb, 'A',
  '{
    "summary": "A Lambda extension da AWS cacheia segredos localmente; warm starts reaproveitam o cache, reduzindo chamadas ao Secrets Manager.",
    "whyCorrect": "A Lambda extension da AWS cacheia segredos localmente; warm starts reaproveitam o cache, reduzindo chamadas ao Secrets Manager. Em memória do container Lambda também funciona entre invocações warm.",
    "whyWrong": {
     "B": "env vars sem encryption violam best practice",
     "C": "embedded em imagem não rotaciona",
     "D": "access key no S3 é múltiplo anti-pattern."
    },
    "keyConcept": "Padrão: cache + rotação na origem.",
    "tutorSeeds": [
