INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-054', 'aws-clf', 'Após audit, descobriu-se uma senha hardcoded em código no GitHub público. Qual sequência de resposta é a mais correta?',
  '[{"id":"A","text":"Tornar o repositório privado e ignorar o leak"},{"id":"B","text":"Rotacionar credenciais imediatamente, remover do histórico Git e migrar para Secrets Manager"},{"id":"C","text":"Aguardar rotação automática semestral"},{"id":"D","text":"Adicionar a credencial a um .gitignore"}]'::jsonb, 'B',
  '{
    "summary": "Credencial exposta deve ser tratada como comprometida — rotacionar imediatamente, varrer logs CloudTrail por uso indevido, remover do histórico (git filter-repo) e migrar para um secret store.",
    "whyCorrect": "Credencial exposta deve ser tratada como comprometida — rotacionar imediatamente, varrer logs CloudTrail por uso indevido, remover do histórico (git filter-repo) e migrar para um secret store.",
    "whyWrong": {
     "A": "Tornar privado não remove o histórico já público",
     "C": "aguardar é negligência",
     "D": "gitignore não retira o commit do histórico."
    },
    "keyConcept": "Padrão de incident response: contain, eradicate, recover.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão de incident response: contain, eradicate, recover?",
     "Quais cenários reais aplicam Padrão de incident response: contain, eradicate, recover?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'troubleshoot', '["secrets","incident-response","rotation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
