INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-055', 'aws-clf', 'Uma equipe quer cross-account access a um segredo do Secrets Manager (segredo na conta A, app na conta B). Qual configuração atende sem replicar o segredo?',
  '[{"id":"A","text":"Tornar o secret público"},{"id":"B","text":"Replicar o secret manualmente via script diário"},{"id":"C","text":"Resource policy no secret + KMS key policy permitindo a role da conta B"},{"id":"D","text":"Compartilhar IAM user credentials da conta A com a conta B"}]'::jsonb, 'C',
  '{
    "summary": "Cross-account a um secret exige resource policy no próprio secret permitindo o principal da outra conta E a KMS key policy permitir Decrypt para esse principal (KMS é parte essencial).",
    "whyCorrect": "Cross-account a um secret exige resource policy no próprio secret permitindo o principal da outra conta E a KMS key policy permitir Decrypt para esse principal (KMS é parte essencial).",
    "whyWrong": {
     "A": "Secret público é catastrofe",
     "B": "Replicar secret via script diário introduz janela de inconsistência (até 24h de drift entre contas), duplica superfície de ataque (secret em duas contas), exige IAM cross-account no script e ainda paga 2x storage. É anti-padrão quando Secrets Manager suporta cross-account nativamente via resource policy.",
     "D": "Compartilhar IAM user credentials é o pior anti-padrão de cross-account: credenciais long-lived em outra conta, sem audit de quem usou, sem rotação fácil. O modelo idiomático AWS para cross-account é sempre role assumida via STS ou, no caso de secrets, resource policy + KMS key policy."
    },
    "keyConcept": "Padrão: resource policy + KMS key policy juntas.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão: resource policy + KMS key policy juntas?",
     "Quais cenários reais aplicam Padrão: resource policy + KMS key policy juntas?",
     "Como KMS se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["secrets","cross-account","kms"]'::jsonb, 'ai-draft', 'active', now(), now()
)
