INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-056', 'aws-clf', 'Uma equipe configurou um Security Group permitindo TCP 22 de qualquer IP (0.0.0.0/0) para administração SSH. Qual problema isso representa e qual ajuste é recomendado?',
  '[{"id":"A","text":"Nenhum, pois SG é stateful e bloqueia ataques"},{"id":"B","text":"Resolve com Block Public Access do S3"},{"id":"C","text":"É padrão recomendado pela AWS"},{"id":"D","text":"Exposição global do SSH; restringir a IPs corporativos ou usar AWS Systems Manager Session Manager"}]'::jsonb, 'D',
  '{
    "summary": "Expor SSH ao mundo aumenta drasticamente brute force e exploração; melhor restringir CIDR ou eliminar o SG SSH usando Session Manager (acesso sem porta aberta, audit no CloudTrail).",
    "whyCorrect": "Expor SSH ao mundo aumenta drasticamente brute force e exploração; melhor restringir CIDR ou eliminar o SG SSH usando Session Manager (acesso sem porta aberta, audit no CloudTrail).",
    "whyWrong": {
     "A": "SG stateful trata fluxo de retorno, não bloqueia ataques na porta aberta",
     "B": "Block Public Access é S3",
     "C": "AWS não recomenda SSH aberto ao mundo em nenhuma documentação oficial — pelo contrário, todos os Well-Architected Security pillars e Trusted Advisor sinalizam 0.0.0.0/0 em porta 22 como risco. AWS recomenda Session Manager (sem porta SSH aberta) ou, no mínimo, restrição a IPs corporativos."
    },
    "keyConcept": "Padrão: zero open SSH; Session Manager > Bastion > IP allowlist.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão: zero open SSH; Session Manager > Bastion > IP allowlist?",
     "Quais cenários reais aplicam Padrão: zero open SSH; Session Manager > Bastion > IP allowlist?",
     "Como SSH se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["network","security-group","ssh","session-manager"]'::jsonb, 'ai-draft', 'active', now(), now()
)
