INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-057', 'aws-clf', 'Qual é a diferença operacional principal entre Security Group e Network ACL em uma VPC AWS?',
  '[{"id":"A","text":"SG é stateful (associado a ENI); NACL é stateless (subnet-level, regras de allow e deny ordenadas)"},{"id":"B","text":"SG é subnet-level; NACL é ENI-level"},{"id":"C","text":"SG só permite TCP; NACL permite todos protocolos"},{"id":"D","text":"SG é gratuito; NACL é pago"}]'::jsonb, 'A',
  '{
    "summary": "SG: stateful (respostas automáticas), anexado a ENI/instância, apenas allows.",
    "whyCorrect": "SG: stateful (respostas automáticas), anexado a ENI/instância, apenas allows. NACL: stateless (precisa regras de ida e volta), aplicada na subnet, allows e denies por número.",
    "whyWrong": {
     "C": "ambos suportam protocolos",
     "B": "É o oposto: SG é anexado a ENI/instância (instance-level), enquanto NACL é aplicada na subnet (subnet-level). A confusão é comum porque ambos atuam em rede, mas o escopo é distinto: SG protege workload específico; NACL protege todos os recursos da subnet uniformemente.",
     "D": "Tanto Security Groups quanto Network ACLs são features gratuitas da VPC — não há cobrança por criar, anexar ou processar regras. O que tem custo é o uso de NAT Gateway, VPC Endpoints, Traffic Mirroring etc., mas não SG/NACL em si."
    },
    "keyConcept": "Regra: SG = primeira linha (instance-level), NACL = filtro coarse-grained (subnet-level).",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: SG = primeira linha (instance-level), NACL = filtro coarse-grained (subnet-level)?",
     "Quais cenários reais aplicam Regra: SG = primeira linha (instance-level), NACL = filtro coarse-grained (subnet-level)?",
     "Como SG se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["network","security-group","nacl","vpc"]'::jsonb, 'ai-draft', 'active', now(), now()
)
