INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-060', 'aws-clf', 'Uma empresa quer que instâncias EC2 em subnet privada acessem o S3 sem passar pela internet nem por NAT Gateway. Qual recurso atende?',
  '[{"id":"A","text":"Internet Gateway dedicada"},{"id":"B","text":"VPN Site-to-Site"},{"id":"C","text":"Elastic IP no S3"},{"id":"D","text":"VPC Gateway Endpoint para S3"}]'::jsonb, 'D',
  '{
    "summary": "VPC Endpoints para S3 (Gateway type) e DynamoDB permitem acesso privado via PrivateLink-like, sem internet, sem custo de Gateway Endpoint e sem NAT — só uma rota na route table.",
    "whyCorrect": "VPC Endpoints para S3 (Gateway type) e DynamoDB permitem acesso privado via PrivateLink-like, sem internet, sem custo de Gateway Endpoint e sem NAT — só uma rota na route table.",
    "whyWrong": {
     "A": "IGW seria o oposto de ''sem internet''",
     "B": "VPN Site-to-Site conecta on-premises a VPC — não é o caminho para uma instância EC2 alcançar S3. Mesmo se configurada, ainda passaria por internet ou exigiria DX. O padrão AWS-native para acesso privado a S3 desde uma VPC é VPC Gateway Endpoint, sem custo, com simples entrada na route table.",
     "C": "Elastic IP é endereço IPv4 público alocado a uma ENI (EC2, NAT GW, ENI específica) — não pode ser anexado a S3, que é um serviço regional sem ENI. Conceitualmente incoerente: S3 não tem ''IP'' a alocar. Para acesso privado, o construto é Endpoint, não EIP."
    },
    "keyConcept": "Padrão: S3/DynamoDB privados → Gateway Endpoint; outros serviços → Interface Endpoint (PrivateLink).",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão: S3/DynamoDB privados → Gateway Endpoint; outros serviços → Interface Endpoint (PrivateLink)?",
     "Quais cenários reais aplicam Padrão: S3/DynamoDB privados → Gateway Endpoint; outros serviços → Interface Endpoint (PrivateLink)?",
     "Como VPC se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["network","vpc-endpoint","privatelink","s3"]'::jsonb, 'ai-draft', 'active', now(), now()
)
