INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-061', 'aws-clf', 'Uma equipe configurou NACL com regra 100 allow TCP 443 e regra 200 deny TCP 443. O que acontece com tráfego HTTPS chegando?',
  '[{"id":"A","text":"É permitido — NACL avalia regras por ordem de número, menor primeiro"},{"id":"B","text":"É negado — deny sempre prevalece"},{"id":"C","text":"É enfileirado para revisão manual"},{"id":"D","text":"Vai para o SG decidir"}]'::jsonb, 'A',
  '{
    "summary": "NACL processa regras em ordem numérica crescente e a primeira que dá match é aplicada — regra 100 (allow) vence regra 200 (deny).",
    "whyCorrect": "NACL processa regras em ordem numérica crescente e a primeira que dá match é aplicada — regra 100 (allow) vence regra 200 (deny).",
    "whyWrong": {
     "B": "Ao contrário de SG/IAM, NACL não tem ''deny implícito'' nem ''deny sempre prevalece''",
     "C": "NACL é stateless e processa regras automaticamente em ordem numérica — não há mecanismo de ''enfileirar para revisão manual''. Avaliação é em microssegundos, sem human-in-the-loop. Esta opção é tecnicamente incoerente com o funcionamento de NACL.",
     "D": "SG é avaliado independentemente da NACL — ambos precisam permitir o tráfego para que ele passe. A NACL decide com base nas próprias regras (allow 100 ganha), e só depois o SG é consultado. Não há delegação de decisão da NACL para o SG; cada camada decide separadamente."
    },
    "keyConcept": "Regra: NACL avaliação = primeira match por número crescente; default deny no final.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: NACL avaliação = primeira match por número crescente; default deny no final?",
     "Quais cenários reais aplicam Regra: NACL avaliação = primeira match por número crescente; default deny no final?",
     "Como NACL se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'troubleshoot', '["network","nacl","rule-evaluation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
