INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-063', 'aws-clf', 'Uma instância EC2 em subnet privada não consegue alcançar a internet para baixar pacotes. A subnet tem rota 0.0.0.0/0 para uma NAT Gateway, mas o download falha. Qual checagem é mais provável de resolver?',
  '[{"id":"A","text":"Trocar a NAT Gateway por Internet Gateway na subnet privada"},{"id":"B","text":"Adicionar Elastic IP à instância privada"},{"id":"C","text":"Confirmar que a NAT Gateway está em subnet pública com rota para IGW e SG do EC2 permite egress"},{"id":"D","text":"Habilitar VPC Flow Logs e esperar resolver sozinho"}]'::jsonb, 'C',
  '{
    "summary": "NAT Gateway exige subnet pública (com rota a IGW) para conseguir egressar; SG do EC2 deve permitir egress 0.0.0.0/0; NACL idem.",
    "whyCorrect": "NAT Gateway exige subnet pública (com rota a IGW) para conseguir egressar; SG do EC2 deve permitir egress 0.0.0.0/0; NACL idem. Falha típica é NAT em subnet privada.",
    "whyWrong": {
     "A": "IGW em subnet privada deixa de ser privada EIP na instância privada não dá internet (faltaria IGW)",
     "D": "Flow Logs apenas observa.",
     "B": "Elastic IP exige Internet Gateway na route table da subnet para funcionar — se a subnet é privada (sem IGW), o EIP fica anexado mas inútil. Além disso, a empresa explicitamente quer manter a instância privada usando NAT GW; adicionar EIP destrói o desenho de rede. EIP seria a solução para ''tornar a instância pública'', não para corrigir egress via NAT."
    },
    "keyConcept": "Padrão: NAT GW em subnet pública + rota privada apontando pra ela.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão: NAT GW em subnet pública + rota privada apontando pra ela?",
     "Quais cenários reais aplicam Padrão: NAT GW em subnet pública + rota privada apontando pra ela?",
     "Como NAT se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'troubleshoot', '["network","nat-gateway","routing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
