INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-072', 'aws-clf', 'Uma startup quer reduzir custo de segurança e escolher entre GuardDuty e Inspector. As ameaças foco são reconnaissance, exfiltration e instâncias comprometidas comunicando com C2. Qual escolha é melhor?',
  '[{"id":"A","text":"Inspector, pois cobre CVE em pacotes"},{"id":"B","text":"Os dois fazem a mesma coisa"},{"id":"C","text":"Nenhum cobre exfiltration; precisa de WAF"},{"id":"D","text":"GuardDuty, pois detecta runtime anomalies de comportamento de rede e API"}]'::jsonb, 'D',
  '{
    "summary": "GuardDuty é o serviço de threat detection runtime que cobre exatamente recon, exfiltration e C2 communication via análise de Flow Logs/CloudTrail/DNS.",
    "whyCorrect": "GuardDuty é o serviço de threat detection runtime que cobre exatamente recon, exfiltration e C2 communication via análise de Flow Logs/CloudTrail/DNS.",
    "whyWrong": {
     "A": "Inspector escaneia CVE em packages",
     "B": "GuardDuty e Inspector cobrem dimensões completamente distintas: GuardDuty é runtime threat detection (análise comportamental de CloudTrail/Flow Logs/DNS via ML); Inspector é vulnerability assessment estático (CVEs em pacotes do EC2/ECR/Lambda). Não são intercambiáveis nem redundantes — são complementares.",
     "C": "GuardDuty cobre exfiltration nativamente — uma das principais categorias de finding é ''Exfiltration:EC2/DNSDataExfiltration'', ''Backdoor:EC2/C&CActivity''. WAF é proteção L7 para apps web (SQLi, XSS) — não detecta exfiltração de dados de instâncias EC2. Confundir os escopos."
    },
    "keyConcept": "Regra: runtime threats → GuardDuty; vulnerability posture → Inspector.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: runtime threats → GuardDuty; vulnerability posture → Inspector?",
     "Quais cenários reais aplicam Regra: runtime threats → GuardDuty; vulnerability posture → Inspector?",
     "Como DNS se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["threat-detection","guardduty","inspector"]'::jsonb, 'ai-draft', 'active', now(), now()
)
