INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-074', 'aws-clf', 'Uma EC2 começa a fazer port scan para IPs aleatórios na internet. GuardDuty gera um finding ''Recon:EC2/PortProbeUnprotectedPort''. Qual é o significado e ação correta?',
  '[{"id":"A","text":"É um falso positivo do GuardDuty; ignorar"},{"id":"B","text":"A instância pode estar comprometida; isolar via SG quarentena e investigar com Detective"},{"id":"C","text":"Aumentar instance type para resolver"},{"id":"D","text":"Mover para outra região"}]'::jsonb, 'B',
  '{
    "summary": "Recon de port probe outbound é forte indicador de comprometimento; resposta: isolar via SG sem ingress/egress, snapshot do EBS para forensics, investigar com Detective e remediar.",
    "whyCorrect": "Recon de port probe outbound é forte indicador de comprometimento; resposta: isolar via SG sem ingress/egress, snapshot do EBS para forensics, investigar com Detective e remediar.",
    "whyWrong": {
     "A": "GuardDuty findings desse tipo merecem investigação séria",
     "D": "mudar região não remove o atacante na imagem.",
     "C": "Instance type controla CPU/memória/network bandwidth — não tem relação com comportamento malicioso de port scanning saindo da instância. Upgrade de tipo continuaria com a mesma instância comprometida, agora com mais recursos para o atacante usar. A resposta é contenção (isolar) e investigação forense, não scaling vertical."
    },
    "keyConcept": "Padrão de IR: contain → eradicate → recover → lessons learned.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão de IR: contain → eradicate → recover → lessons learned?",
     "Quais cenários reais aplicam Padrão de IR: contain → eradicate → recover → lessons learned?",
     "Como SG se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'troubleshoot', '["threat-detection","guardduty","incident-response"]'::jsonb, 'ai-draft', 'active', now(), now()
)
