INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-079', 'aws-clf', 'Após habilitar Trail padrão, a equipe não vê eventos de S3 GetObject/PutObject. Qual ajuste necessário?',
  '[{"id":"A","text":"Aumentar retenção do bucket destino"},{"id":"B","text":"Mudar região do Trail para us-east-1"},{"id":"C","text":"Habilitar Data Events para S3 no Trail (por padrão só Management Events são logados)"},{"id":"D","text":"Ativar versioning no bucket destino"}]'::jsonb, 'C',
