INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-082', 'aws-clf', 'Uma equipe quer reter logs de aplicação em CloudWatch Logs por 7 anos com custo otimizado. Qual configuração ajuda?',
  '[{"id":"A","text":"Manter retention ''never expire'' no CloudWatch"},{"id":"B","text":"Definir retention da log group e exportar logs antigos para S3 com lifecycle para Glacier"},{"id":"C","text":"Apagar logs trimestralmente para reduzir custo"},{"id":"D","text":"Mover log groups para Glacier diretamente"}]'::jsonb, 'B',
  '{
    "summary": "CloudWatch Logs cobra por GB ingest+storage; para retenção longa, exportar para S3 (mais barato) com lifecycle para Glacier/Deep Archive otimiza custo, mantendo logs disponíveis.",
    "whyCorrect": "CloudWatch Logs cobra por GB ingest+storage; para retenção longa, exportar para S3 (mais barato) com lifecycle para Glacier/Deep Archive otimiza custo, mantendo logs disponíveis.",
    "whyWrong": {
     "A": "''never expire'' no CW Logs é caro a longo prazo",
     "C": "apagar viola requisito CW Logs não move direto para Glacier",
     "D": "Não há mecanismo de ''mover log group para Glacier diretamente'' — CloudWatch Logs e S3 Glacier são serviços distintos. O fluxo correto é exportar logs de CW Logs para S3 (via Subscription Filter ou Export Task) e então aplicar lifecycle no bucket movendo para Glacier/Deep Archive. CloudWatch Logs não tem tier de armazenamento frio nativo."
    },
    "keyConcept": "Padrão: hot logs em CW (recente), cold em S3 Glacier.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão: hot logs em CW (recente), cold em S3 Glacier?",
     "Quais cenários reais aplicam Padrão: hot logs em CW (recente), cold em S3 Glacier?",
     "Como GB se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["logging","cloudwatch-logs","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
