INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-084', 'aws-clf', 'Para monitorar uma aplicação custom em EC2 com métricas específicas (ex.: backlog de fila interna), qual serviço AWS recebe e armazena essas métricas?',
  '[{"id":"A","text":"AWS CloudTrail"},{"id":"B","text":"AWS Config"},{"id":"C","text":"AWS X-Ray (apenas)"},{"id":"D","text":"Amazon CloudWatch — custom metrics via PutMetricData ou CW agent"}]'::jsonb, 'D',
