INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-085', 'aws-clf', 'A equipe habilitou Config em uma conta e quer adicionar uma regra ''s3-bucket-public-read-prohibited'' para detectar buckets públicos automaticamente. Qual descreve melhor essa rule?',
  '[{"id":"A","text":"Managed Config Rule pré-construída pela AWS que avalia compliance dos buckets"},{"id":"B","text":"Uma policy IAM que bloqueia s3:PutBucketAcl"},{"id":"C","text":"Um SCP da Organization"},{"id":"D","text":"Uma macro do CloudFormation"}]'::jsonb, 'A',
  '{
    "summary": "Config tem catálogo de managed rules pré-prontas (detective, não preventive) que avaliam recursos contra best practices da AWS e marcam NON_COMPLIANT.",
    "whyCorrect": "Config tem catálogo de managed rules pré-prontas (detective, não preventive) que avaliam recursos contra best practices da AWS e marcam NON_COMPLIANT.",
    "whyWrong": {
     "B": "IAM policy bloqueia ação, Config rule detecta state",
     "D": "macro CFN é template processing.",
     "C": "SCP é controle preventivo no plano IAM — bloqueia chamadas de API antes de executarem. Não ''detecta'' nem ''avalia compliance'' de recursos existentes; só impede ação. Para descobrir buckets públicos existentes, é necessário detective control (Config rule, Macie, Access Analyzer). SCP seria correto para ''impedir alguém de tornar bucket público no futuro''."
    },
    "keyConcept": "Regra: detection com Config rules; prevention com SCP/IAM/permission boundaries.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: detection com Config rules; prevention com SCP/IAM/permission boundaries?",
     "Quais cenários reais aplicam Regra: detection com Config rules; prevention com SCP/IAM/permission boundaries?",
     "Como AWS se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["logging","config","managed-rules"]'::jsonb, 'ai-draft', 'active', now(), now()
)
