INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-086', 'aws-clf', 'Uma empresa quer permitir que funcionários acessem o console AWS com suas credenciais corporativas do Active Directory on-premises. Qual abordagem atende sem replicar usuários no IAM?',
  '[{"id":"A","text":"Criar IAM users espelhando cada usuário do AD"},{"id":"B","text":"IAM Identity Center com SAML 2.0 federado ao AD on-prem (AD Connector ou ADFS)"},{"id":"C","text":"Compartilhar root credentials por equipe"},{"id":"D","text":"Amazon Cognito User Pools com import de usuários"}]'::jsonb, 'B',
  '{
    "summary": "IAM Identity Center suporta federação SAML 2.0 com IdP corporativo (AD, Okta, Ping); usuários autenticam no IdP e recebem credenciais temporárias via STS para AWS.",
    "whyCorrect": "IAM Identity Center suporta federação SAML 2.0 com IdP corporativo (AD, Okta, Ping); usuários autenticam no IdP e recebem credenciais temporárias via STS para AWS.",
    "whyWrong": {
     "C": "root compartilhado é catastrófico",
     "D": "Espelhar usuários no IAM duplica admin e quebra single source of truth Cognito é para usuários finais de app, não funcionários no console.",
     "A": "Criar IAM users espelhando cada usuário do AD é exatamente o anti-padrão que o requisito quer evitar: duplica identity store, exige sincronização manual de senhas, sem SSO real, sem MFA centralizado, sem deprovisioning automático ao desligar funcionário. Federação SAML elimina toda essa duplicação."
