INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-087', 'aws-clf', 'Uma aplicação mobile precisa autenticar usuários finais via Google, Apple ou email/senha, e dar a eles tokens para acessar uma API. Qual serviço AWS é recomendado?',
  '[{"id":"A","text":"IAM Identity Center"},{"id":"B","text":"AWS Directory Service Managed Microsoft AD"},{"id":"C","text":"Amazon Cognito User Pools + Identity Pools"},{"id":"D","text":"IAM users criados para cada usuário final do app"}]'::jsonb, 'C',
