INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-088', 'aws-clf', 'Qual é a principal diferença entre AWS IAM Identity Center e Amazon Cognito do ponto de vista de público-alvo?',
  '[{"id":"A","text":"São o mesmo serviço com nomes diferentes"},{"id":"B","text":"Identity Center não suporta SAML; Cognito sim"},{"id":"C","text":"Cognito é apenas backend; Identity Center é frontend"},{"id":"D","text":"Identity Center é para workforce (funcionários acessando AWS/apps); Cognito é para customer-facing (usuários finais de app)"}]'::jsonb, 'D',
  '{
    "summary": "Identity Center substitui AWS SSO e foca em workforce/B2E (funcionários acessando contas AWS e apps SaaS).",
    "whyCorrect": "Identity Center substitui AWS SSO e foca em workforce/B2E (funcionários acessando contas AWS e apps SaaS). Cognito foca em CIAM (customer identity) para apps web/mobile.",
