INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-091', 'aws-clf', 'Uma empresa europeia precisa garantir que dados de cidadãos UE permaneçam armazenados em regiões dentro do EEA por exigência GDPR. Qual prática AWS endereça esse requisito de data residency?',
