INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-099', 'aws-clf', 'Qual dos pilares do AWS Well-Architected Framework foca explicitamente em identidade, detecção, proteção de dados, IR e proteção de infra?',
  '[{"id":"A","text":"Cost Optimization Pillar"},{"id":"B","text":"Performance Efficiency Pillar"},{"id":"C","text":"Security Pillar"},{"id":"D","text":"Reliability Pillar"}]'::jsonb, 'C',
  '{
    "summary": "Security Pillar do Well-Architected cobre identity & access management, detection, infra protection, data protection (encryption), incident response e application security.",
    "whyCorrect": "Security Pillar do Well-Architected cobre identity & access management, detection, infra protection, data protection (encryption), incident response e application security.",
    "whyWrong": {
     "A": "Cost Optimization foca em custo",
     "B": "Performance em latência/throughput",
     "D": "Reliability em disponibilidade."
    },
    "keyConcept": "Regra: cada pilar tem foco distinto; security tem o seu próprio.",
