INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-100', 'aws-clf', 'Uma equipe quer simular ataques e exercícios de chaos engineering em segurança (game days) sem violar termos de uso. Qual é a postura AWS em relação a pentests da própria infraestrutura do cliente?',
  '[{"id":"A","text":"É proibido qualquer teste de segurança em workloads AWS"},{"id":"B","text":"Só permitido com Enterprise Support"},{"id":"C","text":"Cliente deve testar em outra cloud para não infringir"},{"id":"D","text":"AWS permite pentests em serviços eligíveis sem aprovação prévia, dentro de regras publicadas"}]'::jsonb, 'D',
  '{
    "summary": "AWS publica Customer Service Policy for Penetration Testing: clientes podem testar serviços eligíveis (EC2, RDS, CloudFront, ALB, Lambda, etc.) sem aprovação prévia, desde que sigam regras (não DDoS, não atacar infra alheia).",
    "whyCorrect": "AWS publica Customer Service Policy for Penetration Testing: clientes podem testar serviços eligíveis (EC2, RDS, CloudFront, ALB, Lambda, etc.) sem aprovação prévia, desde que sigam regras (não DDoS, não atacar infra alheia).",
    "whyWrong": {
     "C": "testar em outra cloud não é necessário nem ajuda.",
     "A": "AWS PERMITE pentests em serviços eligíveis sem aprovação prévia — esta opção é factualmente errada. A política está publicada (Customer Service Policy for Penetration Testing) e cobre EC2, RDS, CloudFront, ALB, Lambda, etc. Não é proibido; é regulado.",
     "B": "Permissão para pentests é universal em qualquer plano de suporte (Basic incluído), desde que o cliente respeite as regras publicadas (sem DDoS, sem atacar infra de outros tenants, sem técnicas que comprometam o serviço). Enterprise Support agrega TAM e SLA, mas não é prerequisito para realizar testes de segurança autorizados."
    },
    "keyConcept": "Padrão: game day, red team e pentests são parte de Well-Architected Security.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Padrão: game day, red team e pentests são parte de Well-Architected Security?",
     "Quais cenários reais aplicam Padrão: game day, red team e pentests são parte de Well-Architected Security?",
     "Como AWS se compara com alternativas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["incident-response","pentest","game-day"]'::jsonb, 'ai-draft', 'active', now(), now()
)
