INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-107', 'aws-clf', 'Em uma Organization recém-criada, ao habilitar ''all features'' (em vez de ''consolidated billing only''), o que muda em termos de capacidade de governança?',
  '[{"id":"A","text":"Nada — é apenas uma flag de billing"},{"id":"B","text":"Cria automaticamente contas Audit e Log Archive"},{"id":"C","text":"Habilita SCPs, integração com serviços (Config, GuardDuty, Security Hub) e delegated administrator"},{"id":"D","text":"Migra a Organization para GovCloud"}]'::jsonb, 'C',
  '"(a) Há mudança funcional grande, não apenas billing. (b) ''All features'' destrava SCPs, trusted access para serviços (habilitando coleta org-wide), delegated administrator e RAM cross-account. (c) Quem cria essas contas é Control Tower, não ''all features'' sozinho. (d) Sem migração de partição. Regra: para qualquer guardrail real, ''all features'' é pré-requisito; ''consolidated billing only'' é modo legado."'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["organizations","all-features"]'::jsonb, 'ai-draft', 'active', now(), now()
)
