INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-110', 'aws-clf', 'Uma empresa usa Okta como IdP corporativo. Quer que (i) usuários e grupos do Okta sejam refletidos em Identity Center automaticamente e (ii) login no portal AWS use credenciais do Okta. Quais protocolos cobrem cada requisito?',
  '[{"id":"A","text":"(i) SAML 2.0; (ii) SCIM"},{"id":"B","text":"(i) SCIM; (ii) SAML 2.0"},{"id":"C","text":"(i) OAuth2; (ii) OpenID Connect"},{"id":"D","text":"(i) LDAP; (ii) Kerberos"}]'::jsonb, 'B',
  '"(a) Inverso. (b) Correto: SCIM (System for Cross-domain Identity Management) faz o provisionamento de usuários/grupos do Okta → Identity Center; SAML 2.0 é usado no fluxo de autenticação (assertion do IdP). (c) OIDC é alternativa para apps, não o padrão Identity Center. (d) LDAP/Kerberos são para AD on-prem, não SaaS IdP. Regra: SCIM = sync de diretório; SAML = auth de sessão."'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["iam-identity-center","scim","saml"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
