INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-136', 'aws-clf', 'GuardDuty emitiu um finding ''UnauthorizedAccess:IAMUser/MaliciousIPCaller.Custom'' indicando que uma access key está sendo usada de um IP em threat intel customizado. A equipe quer que esse finding dispare automaticamente revogação da access key. Qual fluxo é idiomático?',
  '[{"id":"A","text":"GuardDuty desativa a chave automaticamente"},{"id":"B","text":"CloudTrail revoga após 5 falhas"},{"id":"C","text":"Macie processa o finding"},{"id":"D","text":"EventBridge rule capturando o finding do GuardDuty → Lambda que chama iam:UpdateAccessKey (Inactive) ou SSM runbook"}]'::jsonb, 'D',
  '"(a) Correto. GuardDuty publica findings em EventBridge; rule filtra por type e dispara remediação automatizada — Lambda, SSM Automation runbook ou Step Functions. Auto-remediation é o pattern security-as-code central da AWS. (b) GuardDuty é detection only — não muda nada. (c) CloudTrail é log only. (d) Macie é descoberta de PII, não IAM. Regra: GuardDuty + EventBridge + Lambda/SSM = ciclo detect→respond."'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["threat-detection","guardduty","eventbridge","auto-remediation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
