INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-153', 'aws-clf', 'AWS European Sovereign Cloud é uma região soberana anunciada para clientes europeus. Qual é a diferença operacional principal em relação a regiões ''standard'' da AWS?',
  '[{"id":"A","text":"Operada por entidade legal europeia com pessoal residente na UE, isolada do plano de controle global da AWS; dados, metadados e operações permanecem dentro da UE"},{"id":"B","text":"É apenas uma região com nome diferente, mesmo controle global"},{"id":"C","text":"Só hospeda Lambda"},{"id":"D","text":"Não permite uso de S3"}]'::jsonb, 'A',
  '"(a) Correto. Sovereign Cloud (assim como GovCloud para US gov) é fisicamente e operacionalmente isolada do resto da AWS — entidade legal local, staff local, controle de acesso restrito. Atende requisitos de soberania mais rigorosos que regiões padrão. (b) Há diferença operacional substancial. (c) Catálogo de serviços é amplo, não restrito. (d) S3 está presente. Regra: sovereign region = isolamento legal + operacional, não só geográfico."'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'recall', '["data-residency","sovereign-cloud","europe"]'::jsonb, 'ai-draft', 'active', now(), now()
)
