INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-158', 'aws-clf', 'Compliance — Qual recurso AWS substitui a necessidade de o cliente assinar NDAs ad-hoc para baixar relatórios de auditoria SOC, ISO e PCI?',
  '[{"id":"A","text":"AWS Trust Center"},{"id":"B","text":"AWS Artifact — portal self-service onde cliente aceita NDA online e baixa relatórios sob NDA AWS-customer"},{"id":"C","text":"AWS Health Dashboard"},{"id":"D","text":"AWS Marketplace"}]'::jsonb, 'B',
  '"(a) Correto. Artifact é o portal central de compliance documents — agreements (BAA, GDPR DPA) e reports (SOC 1/2/3, ISO 27001, PCI AoC). Cliente aceita NDA digitalmente; download imediato. (b) Trust Center é portal público de marketing/posture; sem reports sob NDA. (c) Health é status de serviços. (d) Marketplace é catálogo de SaaS. Regra: Artifact = papelada de compliance; Trust Center = transparência pública."'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'recall', '["compliance","artifact","audit"]'::jsonb, 'ai-draft', 'active', now(), now()
)
