INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v3-002', 'aws-clf', 'Uma organização com 30 contas AWS quer impedir que qualquer usuário em qualquer conta-membro consiga desabilitar o CloudTrail — independente das policies IAM individuais. Qual mecanismo aplicar?',
  '[{"id":"A","text":"Anexar uma deny policy a todos os IAM users em todas as contas"},{"id":"B","text":"Criar uma Service Control Policy (SCP) na Organization que negue cloudtrail:StopLogging e cloudtrail:DeleteTrail"},{"id":"C","text":"Habilitar MFA Delete nos buckets de logs do CloudTrail"},{"id":"D","text":"Configurar Permission Boundary em cada role administrativa"}]'::jsonb, 'B',
  '{
    "summary": "SCP é o controle preventivo a nível de organização — limita o que QUALQUER principal de uma conta pode fazer.",
    "whyCorrect": "SCP define o teto máximo de permissões para uma conta inteira dentro do AWS Organizations. Mesmo o root da conta-membro fica limitado pela SCP. Um deny explícito em cloudtrail:StopLogging/DeleteTrail/UpdateTrail garante que ninguém — admin, dev, root — consiga desligar a trilha.",
    "whyWrong": {
     "A": "Inviável em escala — cada conta nova exige nova policy, e usuários novos escapam. Não cobre o root user. Não é o mecanismo correto para política organizacional.",
     "C": "MFA Delete protege contra remoção de objetos no S3 (logs já gravados) — não impede que o CloudTrail seja PARADO antes de gravar novos eventos.",
     "D": "Permission Boundary atua por identidade — exige aplicação manual em cada role, e não cobre root user da conta."
    },
    "keyConcept": "SCP — guardrail preventivo a nível de Organization Unit ou conta",
    "compareWith": [
     "SCP vs IAM Policy",
     "SCP vs Permission Boundary",
     "Preventive vs Detective controls"
    ],
    "realWorldContext": "Guardrails obrigatórios em empresas reguladas (PCI, HIPAA) — proteger CloudTrail e Config é prática padrão.",
    "commonMistakes": "Pensar que SCP CONCEDE permissões — ela apenas limita. Identidades ainda precisam de policies concedendo permissões.",
    "tutorSeeds": [
     "Qual a precedência entre SCP e IAM Policy?",
     "Como Control Tower aplica SCPs automaticamente?"
    ]
   }'::jsonb,
  'Organizations / SCP', 'Security & Compliance', 'medium', 'best-practice', '["organizations","scp","cloudtrail","guardrail"]'::jsonb, 'ai-draft', 'active', now(), now()
)
