INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v3-003', 'aws-clf', 'Uma aplicação rodando em EC2 precisa ler objetos de um bucket S3. Qual é a abordagem recomendada pela AWS para conceder essa permissão de forma segura?',
  '[{"id":"A","text":"Criar um IAM user, gerar access keys e armazenar em /etc/aws/credentials na instância"},{"id":"B","text":"Tornar o bucket público para leitura"},{"id":"C","text":"Anexar uma IAM Role à instância EC2 (instance profile) com policy de s3:GetObject"},{"id":"D","text":"Compartilhar as credenciais da conta root com a aplicação"}]'::jsonb, 'C',
  '{
    "summary": "IAM Role com instance profile entrega credenciais temporárias via metadata service — sem segredos em disco.",
    "whyCorrect": "Quando uma role é anexada à instância EC2 via instance profile, o SDK obtém credenciais TEMPORÁRIAS rotacionadas automaticamente do Instance Metadata Service (IMDS). Sem keys em disco, sem rotação manual, sem risco de vazamento de chaves de longa duração.",
    "whyWrong": {
     "A": "Access keys de IAM user em disco = anti-padrão crítico. Vazam em backups, snapshots, logs. Não rotacionam automaticamente. Auditoria confunde quem realmente acessou.",
     "B": "Bucket público expõe os dados ao mundo inteiro — não restringe à aplicação. Quebra princípio de menor privilégio.",
     "D": "Credenciais root nunca devem ser usadas em aplicações — o root deve ficar bloqueado com MFA e usado só para tarefas excepcionais."
    },
    "keyConcept": "IAM Roles para serviços AWS — credenciais temporárias via STS",
    "compareWith": [
     "IAM Role vs IAM User access key",
     "Instance Profile vs assumed role via STS"
    ],
    "realWorldContext": "Padrão obrigatório em todo workload EC2/ECS/Lambda em produção.",
    "commonMistakes": "Confundir ''role'' com ''user'' — role não tem senha nem keys permanentes; é assumida e gera credenciais temporárias.",
    "tutorSeeds": [
     "Como o IMDSv2 melhora a segurança contra SSRF?",
     "Como o SDK descobre as credenciais automaticamente?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'easy', 'best-practice', '["iam","ec2","instance-profile","roles"]'::jsonb, 'ai-draft', 'active', now(), now()
)
