INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v3-004', 'aws-clf', 'Uma empresa quer que seus 500 funcionários façam login na AWS usando o mesmo identity provider corporativo (Azure AD/Okta) e que recebam permissões diferentes conforme o time. Qual serviço AWS é o mais indicado?',
  '[{"id":"A","text":"Criar 500 IAM users e organizá-los em groups"},{"id":"B","text":"Amazon Cognito User Pool com 500 usuários"},{"id":"C","text":"Compartilhar a credencial root entre os funcionários"},{"id":"D","text":"AWS IAM Identity Center (sucessor do AWS SSO) federado ao IdP corporativo, com permission sets por grupo"}]'::jsonb, 'D',
  '{
    "summary": "IAM Identity Center centraliza acesso federado a múltiplas contas AWS com permission sets.",
    "whyCorrect": "IAM Identity Center (antigo AWS SSO) federa com IdPs externos (Azure AD, Okta, Google Workspace, Active Directory) via SAML/SCIM. Você define permission sets uma vez e atribui a grupos sincronizados do IdP. Usuários fazem login no portal SSO e acessam contas AWS com role temporária — zero IAM users de longo prazo.",
    "whyWrong": {
     "A": "500 IAM users = inviável: gestão manual de senhas, rotação de keys, offboarding falho, sem SSO real. Anti-padrão para força de trabalho corporativa.",
     "B": "Cognito é para identidades de USUÁRIOS FINAIS de aplicações (clientes externos), não para acesso administrativo à AWS pela força de trabalho.",
     "C": "Compartilhar root quebra auditoria, viola best practices e é proibido por compliance."
    },
    "keyConcept": "IAM Identity Center — federation centralizada para workforce identities multi-conta",
    "compareWith": [
     "IAM Identity Center vs IAM Users",
     "IAM Identity Center vs Cognito"
    ],
    "realWorldContext": "Padrão de mercado para qualquer empresa com >10 funcionários e múltiplas contas AWS (Landing Zone / Control Tower).",
    "commonMistakes": "Confundir Cognito com Identity Center — Cognito é para app users (B2C), Identity Center é para workforce (B2E).",
    "tutorSeeds": [
     "Como SCIM provisiona usuários do Azure AD para Identity Center?",
     "Como permission sets viram roles nas contas-membro?"
    ]
   }'::jsonb,
  'IAM Identity Center', 'Security & Compliance', 'medium', 'scenario', '["identity-center","sso","federation","workforce"]'::jsonb, 'ai-draft', 'active', now(), now()
)
