INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v3-005', 'aws-clf', 'Um app mobile precisa permitir que usuários finais (clientes do app) façam login com Google/Facebook/Apple e recebam credenciais AWS temporárias para fazer upload direto no S3. Qual combinação de serviços é a correta?',
  '[{"id":"A","text":"Cognito User Pool (autenticação) + Identity Pool (credenciais AWS temporárias via STS)"},{"id":"B","text":"IAM users criados dinamicamente para cada cliente do app"},{"id":"C","text":"IAM Identity Center federado a cada provedor social"},{"id":"D","text":"Roles assumidas diretamente pelo app via access key embedada no binário"}]'::jsonb, 'A',
  '{
    "summary": "Cognito User Pool autentica; Identity Pool troca o token por credenciais AWS temporárias.",
    "whyCorrect": "User Pool é o diretório de usuários (login com email/senha, MFA, ou federação social). Identity Pool (Federated Identities) recebe o token JWT do User Pool ou de IdPs sociais e chama STS para devolver credenciais AWS temporárias scoped a uma role — ideal para upload S3 direto, acesso a DynamoDB, etc.",
    "whyWrong": {
     "B": "IAM users não escalam para milhões de clientes; cada user consome quota e exige rotação manual de keys.",
     "C": "Identity Center é para workforce corporativa, não para customer identity (B2C). Não suporta logins sociais para clientes externos do app.",
     "D": "Embedar access key em binário móvel = vazamento garantido em minutos (reverse engineering)."
    },
    "keyConcept": "Cognito User Pool vs Identity Pool — autenticação vs autorização AWS",
    "compareWith": [
     "User Pool vs Identity Pool",
     "Cognito vs IAM Identity Center"
    ],
    "realWorldContext": "Padrão para apps mobile/web B2C que precisam acessar S3/DynamoDB diretamente do cliente.",
    "commonMistakes": "Achar que User Pool dá credenciais AWS — não dá: ele só autentica. É o Identity Pool que entrega credenciais via STS.",
    "tutorSeeds": [
     "Como configurar role autenticada vs unauthenticada no Identity Pool?",
     "Quando preferir API Gateway + Cognito authorizer ao invés de S3 direto?"
    ]
   }'::jsonb,
  'Cognito', 'Security & Compliance', 'medium', 'scenario', '["cognito","user-pool","identity-pool","federation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
