INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v3-006', 'aws-clf', 'Uma aplicação na Conta A precisa ler dados de uma tabela DynamoDB na Conta B. Qual é a forma recomendada de conceder esse acesso cross-account?',
  '[{"id":"A","text":"Criar um IAM user na Conta B e compartilhar access keys com a Conta A"},{"id":"B","text":"Criar uma IAM Role na Conta B com trust policy permitindo sts:AssumeRole pela Conta A; a aplicação na Conta A chama STS AssumeRole"},{"id":"C","text":"Tornar a tabela DynamoDB pública"},{"id":"D","text":"Replicar todos os dados para a Conta A periodicamente via S3"}]'::jsonb, 'B',
  '{
    "summary": "Cross-account access usa role na conta-alvo com trust policy + STS AssumeRole.",
    "whyCorrect": "A Conta B cria uma role com trust policy permitindo a Conta A (Principal: arn:aws:iam::ACCOUNT_A:root ou role específica) chamar sts:AssumeRole. A aplicação na Conta A chama STS AssumeRole nessa role e recebe credenciais temporárias para acessar o DynamoDB da Conta B. Sem keys permanentes cross-account.",
    "whyWrong": {
     "A": "Access keys cross-account = anti-padrão. Difícil rotacionar, fácil vazar, sem audit trail claro de QUEM da Conta A usou.",
     "C": "DynamoDB não tem ''público'' no sentido S3 — e mesmo se tivesse, expor dados ao mundo todo viola menor privilégio.",
     "D": "Replicação periódica não resolve acesso em tempo real, gera custo dobrado e divergência de dados."
    },
    "keyConcept": "STS AssumeRole — federation cross-account com credenciais temporárias",
    "compareWith": [
     "AssumeRole vs AssumeRoleWithSAML vs AssumeRoleWithWebIdentity"
    ],
    "realWorldContext": "Padrão em Landing Zones multi-conta: workloads em contas de produto assumem roles em contas de logging/security.",
    "commonMistakes": "Esquecer que ambas as policies (trust na role + permissions na role + permission no caller) precisam permitir a operação.",
    "tutorSeeds": [
     "Como o ExternalId previne confused deputy?",
     "Qual o tempo máximo de credenciais STS?"
    ]
   }'::jsonb,
  'STS / Cross-account', 'Security & Compliance', 'medium', 'scenario', '["sts","assume-role","cross-account","iam"]'::jsonb, 'ai-draft', 'active', now(), now()
)
