INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v3-007', 'aws-clf', 'Em uma policy IAM, qual é a precedência de avaliação quando há um Allow explícito em uma identity-based policy e um Deny explícito em uma SCP?',
  '[{"id":"A","text":"Allow vence — identity policy tem precedência sobre SCP"},{"id":"B","text":"Depende da ordem cronológica em que foram criadas"},{"id":"C","text":"Deny explícito SEMPRE vence — a ação é negada"},{"id":"D","text":"A primeira policy avaliada (alfabética) vence"}]'::jsonb, 'C',
  '{
    "summary": "Em IAM, deny explícito sempre vence sobre qualquer allow.",
    "whyCorrect": "A lógica de avaliação IAM é: (1) tudo é negado por padrão; (2) allow explícito libera; (3) deny explícito SOBREPÕE qualquer allow — em qualquer policy (identity, resource, SCP, boundary, session policy). SCP com Deny bloqueia a ação mesmo que a identity policy permita.",
    "whyWrong": {
     "A": "Identity policy NÃO tem precedência sobre SCP. SCP é um guardrail superior aplicado pela Organization.",
     "B": "Ordem cronológica é irrelevante — a avaliação é determinística por tipo de policy, não por timestamp.",
     "D": "Ordem alfabética não tem papel algum na avaliação IAM."
    },
    "keyConcept": "Lógica de avaliação IAM — deny explícito vence allow explícito",
    "compareWith": [
     "Identity policy vs Resource policy vs SCP vs Boundary"
    ],
    "realWorldContext": "Base de qualquer auditoria de permissões — entender que um deny escondido em qualquer camada bloqueia tudo.",
    "commonMistakes": "Achar que o usuário-admin com ''*'':''*'' bypassa SCPs — não bypassa. SCP atua antes.",
    "tutorSeeds": [
     "Quais tipos de policy existem na AWS?",
     "Como debugar ''AccessDenied'' inesperado?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'medium', 'recall', '["iam","policy-evaluation","deny","scp"]'::jsonb, 'ai-draft', 'active', now(), now()
)
