INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v3-009', 'aws-clf', 'Qual das opções descreve corretamente o uso de IAM Groups?',
  '[{"id":"A","text":"Groups são containers de IAM users — anexam-se policies ao group e todos os users membros herdam as permissões"},{"id":"B","text":"Groups podem ser usados como Principal em uma resource policy"},{"id":"C","text":"Groups podem assumir roles e receber credenciais temporárias via STS"},{"id":"D","text":"Groups podem ser aninhados (group dentro de group)"}]'::jsonb, 'A',
  '{
    "summary": "IAM Group é container de users para anexar policies coletivamente — não é principal, não assume role, não aninha.",
    "whyCorrect": "Group é um agrupamento administrativo de users. Você anexa policies AO group e todos os users membros herdam. Simplifica gestão de permissões para times.",
    "whyWrong": {
     "B": "Group NÃO é Principal — não aparece em resource-based policies. Use o ARN do user/role.",
     "C": "Groups NÃO assumem roles. Apenas users e serviços (via role) podem chamar AssumeRole.",
     "D": "IAM não suporta nested groups — diferente de AD/LDAP."
    },
    "keyConcept": "IAM Group — agrupamento de users para herança de policies",
    "compareWith": [
     "IAM Group vs IAM Role",
     "IAM Group vs Identity Center Group"
    ],
    "realWorldContext": "Bom para organizar dev/qa/prod groups com policies diferentes; ainda assim, o ideal moderno é Identity Center + permission sets.",
    "commonMistakes": "Confundir Group com Role — Role é assumível e tem trust policy; Group é só container.",
    "tutorSeeds": [
     "Por que IAM não permite nested groups?",
     "Diferença prática entre Group e Identity Center Group?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'easy', 'recall', '["iam","groups","users"]'::jsonb, 'ai-draft', 'active', now(), now()
)
