INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v3-010', 'aws-clf', 'Uma equipe de auditoria precisa de acesso somente-leitura a TODAS as 20 contas da AWS Organization para investigar configurações de segurança. Qual é a abordagem mais escalável e segura?',
  '[{"id":"A","text":"Criar IAM users de auditoria em cada uma das 20 contas"},{"id":"B","text":"Definir um permission set ReadOnlyAccess no IAM Identity Center e atribuí-lo ao grupo de auditoria, dando acesso federado a todas as contas"},{"id":"C","text":"Compartilhar credenciais root das 20 contas via vault"},{"id":"D","text":"Habilitar console access público em todas as contas"}]'::jsonb, 'B',
  '{
    "summary": "Identity Center + permission set ReadOnlyAccess é a abordagem padrão para acesso federado multi-conta.",
    "whyCorrect": "Você define um permission set baseado na AWS managed policy ReadOnlyAccess uma única vez, atribui ao grupo de auditoria (sincronizado do IdP), e seleciona as 20 contas — Identity Center provisiona roles automaticamente em cada conta. Auditores fazem SSO uma vez e navegam entre contas no portal.",
    "whyWrong": {
     "A": "20 users separados = 20 pontos de gestão, sem SSO, alto risco de offboarding falho.",
     "C": "Compartilhar root = catastrófico para auditoria (perda de não-repúdio) e proibido por compliance.",
     "D": "Console público = não existe; e mesmo se existisse, expor console à internet sem auth é absurdo."
    },
    "keyConcept": "Identity Center multi-account access via permission sets",
    "compareWith": [
     "Identity Center vs SAML federation direta com IAM"
    ],
    "realWorldContext": "Padrão em Control Tower / Landing Zone — auditores recebem acesso ReadOnly multi-conta em minutos.",
    "commonMistakes": "Atribuir AdministratorAccess para auditoria — viola menor privilégio; ReadOnlyAccess é suficiente.",
    "tutorSeeds": [
     "Diferença entre ReadOnlyAccess e ViewOnlyAccess?",
     "Como customizar um permission set?"
    ]
   }'::jsonb,
  'IAM Identity Center', 'Security & Compliance', 'medium', 'best-practice', '["identity-center","permission-sets","audit","multi-account"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
