INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v3-011', 'aws-clf', 'Qual afirmação sobre o usuário root da conta AWS está CORRETA?',
  '[{"id":"A","text":"O root user pode ser deletado após criar um IAM admin"},{"id":"B","text":"O root user pode ser limitado por IAM Permission Boundary"},{"id":"C","text":"O root user pode ser limitado por SCPs aplicadas à conta-membro dentro de uma Organization"},{"id":"D","text":"O root user pode receber MFA mas não pode ser limitado por IAM policies anexadas a ele"}]'::jsonb, 'C',
  '{
    "summary": "Root é limitado por SCPs em conta-membro de uma Organization; é o único controle preventivo eficaz contra root.",
    "whyCorrect": "Em contas-membro de uma AWS Organization (não na conta de gerenciamento), SCPs definem o teto de permissões — e isso inclui o root user. É o único mecanismo que pode prevenir ações do root.",
    "whyWrong": {
     "A": "Root user NÃO pode ser deletado — está vinculado à conta para sempre. Pode-se apenas remover keys e bloquear com MFA.",
     "B": "Permission Boundary não se aplica ao root — apenas a users e roles IAM.",
     "D": "IAM policies anexadas ao root são IGNORADAS — root tem permissão implícita total. SCP é a única forma."
    },
    "keyConcept": "Root user — só limitável via SCP em conta-membro",
    "compareWith": [
     "Root vs IAM admin",
     "SCP root effect"
    ],
    "realWorldContext": "Best practice: habilitar MFA hardware no root, guardar credenciais offline, e bloquear root via SCP na Organization para ações comuns.",
    "commonMistakes": "Achar que o root respeita IAM policies — não respeita.",
    "tutorSeeds": [
     "Quais tarefas exigem root user obrigatoriamente?",
     "Como AWS Organizations bloqueia o root via SCP?"
    ]
   }'::jsonb,
  'Root account', 'Security & Compliance', 'hard', 'recall', '["root","scp","best-practices"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
