INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v3-012', 'aws-clf', 'Quais tarefas EXIGEM o uso do usuário root da conta AWS e não podem ser delegadas a um IAM user?',
  '[{"id":"A","text":"Criar EC2 instances e configurar security groups"},{"id":"B","text":"Criar IAM users e policies"},{"id":"C","text":"Configurar CloudTrail e Config"},{"id":"D","text":"Alterar o plano de suporte AWS, fechar a conta, mudar email/senha do root e habilitar MFA no próprio root"}]'::jsonb, 'D',
  '{
    "summary": "Tarefas administrativas únicas da conta exigem root — operação cotidiana, não.",
    "whyCorrect": "Apenas o root pode: mudar email/senha da conta, mudar plano de suporte, fechar a conta, transferir Route 53 entre contas, registrar como vendedor no Marketplace, criar CloudFront key pairs legacy, restaurar permissões de IAM user que se trancou. Operação normal NUNCA precisa de root.",
    "whyWrong": {
     "A": "EC2 e SG são operações cotidianas — IAM users com policy adequada fazem.",
     "B": "Criar IAM users é função do admin IAM, não exige root.",
     "C": "CloudTrail/Config são configuráveis por admin IAM."
    },
    "keyConcept": "Root user — tarefas exclusivas vs delegáveis",
    "compareWith": [
     "Root vs IAM Admin"
    ],
    "realWorldContext": "Best practice CIS: root só usado uma vez por ano (ou nunca) para tarefas exclusivas.",
    "commonMistakes": "Usar root no dia-a-dia ''porque é mais simples'' — viola não-repúdio, expõe credenciais críticas.",
    "tutorSeeds": [
     "Lista completa de tarefas root-only?",
     "Como recuperar acesso ao root se perder MFA?"
    ]
   }'::jsonb,
  'Root account', 'Security & Compliance', 'easy', 'recall', '["root","best-practices"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
