INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v3-013', 'aws-clf', 'Uma engenheira recebeu erro ''AccessDenied'' ao tentar listar objetos em um bucket S3 — apesar de ter ListBucket via IAM policy. Investigando, descobre uma bucket policy com Deny explícito para o ARN dela. Quem vence?',
  '[{"id":"A","text":"A bucket policy vence — Deny explícito sobrepõe qualquer Allow"},{"id":"B","text":"A IAM policy vence — Allow tem precedência sobre Deny da bucket policy"},{"id":"C","text":"Depende de qual foi criada por último"},{"id":"D","text":"Resource policies sempre são ignoradas se a identity policy concede"}]'::jsonb, 'A',
  '{
    "summary": "Deny explícito em qualquer policy (identity ou resource) sempre vence.",
    "whyCorrect": "A lógica unificada de avaliação IAM combina identity policy e resource policy via união lógica para Allow, mas QUALQUER deny explícito (em qualquer lado) sobrepõe. A bucket policy com Deny derruba o acesso mesmo com IAM policy permitindo.",
    "whyWrong": {
     "B": "Allow nunca vence Deny.",
     "C": "Ordem cronológica é irrelevante.",
     "D": "Resource policies não são ignoradas — elas se unem à identity policy para definir o efetivo."
    },
    "keyConcept": "Avaliação combinada identity policy + resource policy",
    "compareWith": [
     "IAM policy vs Bucket policy",
     "Explicit deny vs implicit deny"
    ],
    "realWorldContext": "Cenário típico de debugging: ''tenho permissão mas dá AccessDenied'' — quase sempre é resource policy ou SCP.",
    "commonMistakes": "Esquecer de checar bucket policy ao debugar acesso S3.",
    "tutorSeeds": [
     "Como o IAM Policy Simulator ajuda?",
     "Diferença entre identity-based e resource-based policy?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'medium', 'troubleshoot', '["iam","bucket-policy","deny","policy-evaluation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
