INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v3-014', 'aws-clf', 'Em qual cenário a AWS recomenda usar AWS STS GetSessionToken ao invés de AssumeRole?',
  '[{"id":"A","text":"Para cross-account access entre Account A e Account B"},{"id":"B","text":"Para emitir credenciais temporárias para um IAM user (incluindo MFA) que precisa fazer chamadas mais privilegiadas"},{"id":"C","text":"Para federar usuários SAML do Active Directory"},{"id":"D","text":"Para EC2 instance profile"}]'::jsonb, 'B',
  '{
    "summary": "GetSessionToken retorna credenciais temporárias para um IAM user existente — útil para MFA-step-up.",
    "whyCorrect": "GetSessionToken é chamado por um IAM user para receber credenciais temporárias da PRÓPRIA identidade, geralmente após MFA — usado quando uma operação exige MFA e o user precisa de credenciais temporárias MFA-authenticated. Não envolve role nem outra conta.",
    "whyWrong": {
     "A": "Cross-account é AssumeRole.",
     "C": "SAML federation é AssumeRoleWithSAML.",
     "D": "EC2 instance profile usa AssumeRole nos bastidores via metadata service."
    },
    "keyConcept": "STS API matrix — GetSessionToken vs AssumeRole vs AssumeRoleWithSAML vs AssumeRoleWithWebIdentity",
    "compareWith": [
     "GetSessionToken vs GetFederationToken"
    ],
    "realWorldContext": "CLI scripts que precisam executar ações MFA-protected (ex: deletar bucket MFA-Delete).",
    "commonMistakes": "Confundir GetSessionToken com AssumeRole — são casos diferentes.",
    "tutorSeeds": [
     "Quando usar GetFederationToken?",
     "Como aws sts get-session-token integra com aws cli MFA?"
    ]
   }'::jsonb,
  'STS', 'Security & Compliance', 'hard', 'recall', '["sts","session-token","mfa"]'::jsonb, 'ai-draft', 'active', now(), now()
)
