INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v3-015', 'aws-clf', 'Uma empresa quer aplicar guardrails preventivos (impedir uso de regiões não-aprovadas) e detectivos (alertar não-conformidades) em todas as suas contas AWS automaticamente. Qual serviço AWS oferece esse pacote integrado de Landing Zone?',
  '[{"id":"A","text":"AWS Config sozinho"},{"id":"B","text":"AWS Service Catalog"},{"id":"C","text":"AWS Control Tower"},{"id":"D","text":"AWS Trusted Advisor"}]'::jsonb, 'C',
  '{
    "summary": "Control Tower provê Landing Zone com SCPs (preventive) e Config rules (detective) prontas.",
    "whyCorrect": "Control Tower automatiza Landing Zone multi-conta com guardrails — preventive (via SCPs aplicadas a OUs) e detective (via AWS Config rules). Tem dashboard centralizado e suporta personalização (custom guardrails) e Account Factory para provisionar novas contas conformes.",
    "whyWrong": {
     "A": "Config sozinho cobre apenas detective; não aplica preventive via SCP nem orquestra Landing Zone.",
     "B": "Service Catalog distribui produtos aprovados a usuários — não é Landing Zone com guardrails.",
     "D": "Trusted Advisor dá recomendações (cost, performance, security) mas não aplica guardrails preventivos."
    },
    "keyConcept": "Control Tower — Landing Zone com guardrails preventive + detective",
    "compareWith": [
     "Control Tower vs Organizations vs Config"
    ],
    "realWorldContext": "Empresas que adotam multi-conta começam com Control Tower para ter Landing Zone em horas, não meses.",
    "commonMistakes": "Achar que Control Tower é alternativa ao Organizations — ele USA Organizations por baixo.",
    "tutorSeeds": [
     "Diferença entre mandatory, strongly recommended e elective guardrails?",
     "Account Factory vs CreateAccount API?"
    ]
   }'::jsonb,
  'Control Tower / Organizations', 'Security & Compliance', 'medium', 'scenario', '["control-tower","landing-zone","guardrails","organizations"]'::jsonb, 'ai-draft', 'active', now(), now()
)
