INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-001', 'aws-clf', 'Uma fintech mantém uma conta AWS chamada ''data-lake-prod'' onde residem dados sensíveis. Um time de analytics em outra conta (''analytics-dev'') precisa ler objetos S3 do data lake. Qual combinação mínima de policies é necessária para que um IAM role em ''analytics-dev'' assuma um role em ''data-lake-prod'' e leia esses objetos?',
  '[{"id":"A","text":"Trust policy no role de ''data-lake-prod'' permitindo o principal de ''analytics-dev'' E identity policy do principal-origem com sts:AssumeRole"},{"id":"B","text":"Apenas uma identity policy no role de ''analytics-dev'' permitindo sts:AssumeRole"},{"id":"C","text":"Bucket policy pública no bucket S3 do data lake"},{"id":"D","text":"SCP em ''data-lake-prod'' liberando acesso cross-account"}]'::jsonb, 'A',
  '{
    "summary": "AssumeRole cross-account exige duas pontas: trust policy permitindo o principal-origem + identity policy do principal-origem com sts:AssumeRole no ARN-alvo.",
    "whyCorrect": "O fluxo cross-account exige confiança bilateral: (1) o role-alvo em ''data-lake-prod'' precisa de uma trust policy declarando como Principal a conta/role/usuário de ''analytics-dev''; (2) o principal de ''analytics-dev'' precisa de uma identity policy com Action ''sts:AssumeRole'' e Resource sendo o ARN do role-alvo. Sem qualquer uma das duas, o AssumeRole falha com AccessDenied.",
    "whyWrong": {
     "B": "Apenas a identity policy permite chamar AssumeRole, mas STS rejeita se a trust policy do role-alvo não confiar no principal de origem.",
     "C": "Bucket policy pública expõe ao mundo inteiro e quebra menor privilégio — não é o mecanismo de delegação cross-account com role assumption.",
     "D": "SCP é um guardrail organizacional que LIMITA permissões, nunca concede acesso. Não substitui trust policy."
    },
    "keyConcept": "Cross-account role assumption — confiança bilateral (trust + identity policy)",
    "compareWith": [
     "sts:AssumeRole vs Resource-based policy direta",
     "Trust policy vs Identity policy"
    ],
    "realWorldContext": "Padrão para data lakes corporativos com contas segregadas por ambiente/time.",
    "commonMistakes": "Esquecer da identity policy do lado de origem — só a trust policy não basta.",
    "tutorSeeds": [
     "Como STS valida ambos os lados em uma chamada AssumeRole?",
     "O que muda se eu usar resource policy do S3 diretamente em vez de role assumption?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'medium', 'scenario', '["iam","sts","assume-role","cross-account"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
