INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-004', 'aws-clf', 'Em uma policy IAM, qual condition key garante que a chamada à API só seja permitida se o usuário tiver feito login com MFA (autenticação multifator) ativa naquela sessão?',
  '[{"id":"A","text":"aws:SourceIp"},{"id":"B","text":"aws:PrincipalOrgID"},{"id":"C","text":"aws:SecureTransport"},{"id":"D","text":"aws:MultiFactorAuthPresent"}]'::jsonb, 'D',
  '{
    "summary": "aws:MultiFactorAuthPresent retorna true quando a sessão atual foi autenticada com MFA.",
    "whyCorrect": "A condition key aws:MultiFactorAuthPresent é booleana e fica true quando o caller passou pelo MFA challenge na obtenção das credenciais temporárias. Usar ''Bool'': {''aws:MultiFactorAuthPresent'':''true''} em um Allow força MFA, e em um Deny com ''BoolIfExists'' false bloqueia chamadas sem MFA.",
    "whyWrong": {
     "A": "aws:SourceIp restringe por IP de origem, não por presença de MFA.",
     "B": "aws:PrincipalOrgID limita por organização do AWS Organizations, não por MFA.",
     "C": "aws:SecureTransport exige TLS (HTTPS) na chamada — proteção do transporte, não autenticação MFA."
    },
    "keyConcept": "Condition keys IAM globais — controle fino por contexto da requisição",
    "compareWith": [
     "MultiFactorAuthPresent vs MultiFactorAuthAge",
     "BoolIfExists vs Bool"
    ],
    "realWorldContext": "Política comum: exigir MFA para operações sensíveis (deletar buckets, criar IAM users).",
    "commonMistakes": "Usar ''Bool'' em vez de ''BoolIfExists'' em policies de deny — sessões de role assumption sem MFA podem retornar a chave como ausente, e a condição falha de forma inesperada.",
    "tutorSeeds": [
     "Quando usar BoolIfExists em vez de Bool?",
     "Como forçar MFA para AssumeRole?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'medium', 'recall', '["iam","condition-keys","mfa"]'::jsonb, 'ai-draft', 'active', now(), now()
)
