INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-005', 'aws-clf', 'Considere a lógica de avaliação de policies IAM da AWS. Um usuário tem uma identity policy com Allow para s3:GetObject, mas a SCP da Organization aplicada à conta nega s3:*. Qual é o resultado efetivo da chamada?',
  '[{"id":"A","text":"Deny — SCP deny atua como guardrail superior e bloqueia qualquer tentativa"},{"id":"B","text":"Allow — a identity policy do usuário tem precedência sobre SCPs"},{"id":"C","text":"Allow — SCPs não se aplicam a operações de leitura"},{"id":"D","text":"Depende — se o usuário tiver MFA ativo, o Allow prevalece"}]'::jsonb, 'A',
  '{
    "summary": "Na lógica IAM: explicit Deny > explicit Allow > implicit Deny. SCP é avaliada antes da identity policy e seu Deny barra tudo.",
    "whyCorrect": "A ordem de avaliação é: (1) SCP do AWS Organizations define o teto da conta — se houver Deny, encerra com Deny; (2) Resource policy + Identity policy + Permission Boundary + Session policy se interseccionam. Como SCP nega s3:*, a operação termina em Deny independente do que a identity policy diga.",
    "whyWrong": {
     "B": "Identity policy nunca sobrepõe SCP — SCP é guardrail organizacional acima.",
     "C": "SCPs aplicam-se a TODAS as APIs alcançadas pelas identidades da conta (com pequenas exceções como root tasks específicas), incluindo leitura.",
     "D": "MFA não anula SCP — é uma condição adicional, não um override."
    },
    "keyConcept": "Policy evaluation logic — SCP é avaliada primeiro e age como teto",
    "compareWith": [
     "SCP vs Permission Boundary vs Identity Policy",
     "Explicit Deny vs Implicit Deny"
    ],
    "realWorldContext": "Times de plataforma usam SCPs para garantir que nenhuma conta-membro consiga, por exemplo, criar recursos fora da região permitida ou desativar logging.",
    "commonMistakes": "Imaginar que policies se somam democraticamente — SCP age como teto/guardrail, não como mais um voto.",
    "tutorSeeds": [
     "Qual a diferença entre SCP allow-list e deny-list?",
     "Como SCP interage com root user da conta-membro?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'hard', 'scenario', '["iam","policy-evaluation","scp"]'::jsonb, 'ai-draft', 'active', now(), now()
)
