INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-006', 'aws-clf', 'Uma equipe de segurança quer que IAM users só consigam fazer chamadas à API AWS a partir do range de IPs corporativos (203.0.113.0/24). Qual condition key usar na policy?',
  '[{"id":"A","text":"aws:VpcSourceIp"},{"id":"B","text":"aws:SourceIp"},{"id":"C","text":"aws:SourceVpc"},{"id":"D","text":"aws:SourceArn"}]'::jsonb, 'B',
  '{
    "summary": "aws:SourceIp restringe chamadas à API por IP público de origem do caller.",
    "whyCorrect": "aws:SourceIp avalia o IP público do cliente que está chamando a API. Combinada com IpAddress: {''aws:SourceIp'':[''203.0.113.0/24'']}, a policy só permite a operação se a requisição vier daquele range — clássica para limitar acesso a partir da rede corporativa via NAT/VPN.",
    "whyWrong": {
     "A": "aws:VpcSourceIp só se aplica quando a chamada vem por VPC endpoint, não para tráfego saindo de IPs externos.",
     "C": "aws:SourceVpc compara com o ID do VPC de origem (também via VPC endpoint), não com range de IP arbitrário.",
     "D": "aws:SourceArn identifica o ARN do recurso de origem em chamadas serviço-a-serviço (ex: SNS chamando Lambda), não o IP do cliente humano."
    },
    "keyConcept": "Condition key aws:SourceIp — restrição por IP público de origem",
    "compareWith": [
     "aws:SourceIp vs aws:VpcSourceIp",
     "SourceIp vs SourceArn"
    ],
    "realWorldContext": "Empresas que mantêm VPN corporativa usam essa policy para garantir que IAM users só funcionem dentro do perímetro.",
    "commonMistakes": "Aplicar aws:SourceIp esperando que ele valide IPs internos de VPC — para isso existe aws:VpcSourceIp via VPC endpoint policy.",
    "tutorSeeds": [
     "O que muda quando a chamada passa por VPC endpoint?",
     "Como combinar SourceIp com MFA na mesma policy?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'medium', 'best-practice', '["iam","condition-keys","source-ip"]'::jsonb, 'ai-draft', 'active', now(), now()
)
