INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-007', 'aws-clf', 'Em qual cenário a chamada STS apropriada é AssumeRoleWithSAML (em vez de AssumeRole ou AssumeRoleWithWebIdentity)?',
  '[{"id":"A","text":"App mobile com login Google quer acessar S3"},{"id":"B","text":"Workload on-prem com certificado X.509"},{"id":"C","text":"Usuário corporativo autentica em um IdP SAML 2.0 (ADFS, PingFederate) e quer credenciais AWS temporárias"},{"id":"D","text":"EC2 instance assumindo o role do seu instance profile"}]'::jsonb, 'C',
  '{
    "summary": "AssumeRoleWithSAML troca uma SAML assertion (de IdP SAML 2.0) por credenciais temporárias AWS.",
    "whyCorrect": "AssumeRoleWithSAML é específica para federation via SAML 2.0 — IdPs como ADFS, Okta SAML, PingFederate, Shibboleth. O IdP emite uma SAML assertion, o cliente troca por credenciais com sts:AssumeRoleWithSAML. O role precisa ter o SAML provider como Principal na trust policy.",
    "whyWrong": {
     "A": "Login com Google é OIDC/OAuth — usa AssumeRoleWithWebIdentity (ou um Cognito Identity Pool).",
     "B": "Workload com X.509 usa IAM Roles Anywhere, não SAML.",
     "D": "Instance profile usa um mecanismo interno (IMDS) — o SDK chama AssumeRole implícito, mas não é AssumeRoleWithSAML."
    },
    "keyConcept": "STS API family — AssumeRole / WithSAML / WithWebIdentity / GetSessionToken / GetFederationToken",
    "compareWith": [
     "AssumeRoleWithSAML vs AssumeRoleWithWebIdentity",
     "SAML 2.0 vs OIDC"
    ],
    "realWorldContext": "Empresas que ainda usam AD on-prem federam via ADFS+SAML; cloud-native preferem OIDC.",
    "commonMistakes": "Confundir SAML (XML, enterprise) com OIDC/OAuth (JSON, social/mobile) — usam APIs STS diferentes.",
    "tutorSeeds": [
     "O que entra no Principal de uma trust policy para SAML?",
     "Quando preferir Identity Center em vez de federar IAM diretamente?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'medium', 'recall', '["iam","sts","saml","federation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
