INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-008', 'aws-clf', 'Uma empresa quer garantir que recursos AWS só possam ser criados em regiões aprovadas (us-east-1 e sa-east-1). Qual condition key global é mais adequada para essa SCP?',
  '[{"id":"A","text":"aws:RequestRegion"},{"id":"B","text":"aws:Region"},{"id":"C","text":"aws:TargetRegion"},{"id":"D","text":"aws:RequestedRegion"}]'::jsonb, 'D',
  '{
    "summary": "aws:RequestedRegion é a condition key oficial para restringir chamadas a regiões específicas.",
    "whyCorrect": "aws:RequestedRegion contém o código da região (ex: ''us-east-1'') na qual a chamada está sendo feita. Em uma SCP com Deny + StringNotEquals: {''aws:RequestedRegion'':[''us-east-1'',''sa-east-1'']}, qualquer chamada fora dessas regiões é bloqueada. É o controle padrão para data residency.",
    "whyWrong": {
     "A": "aws:RequestRegion não existe como key oficial AWS — o nome correto é aws:RequestedRegion.",
     "B": "aws:Region não é uma condition key global válida na documentação.",
     "C": "aws:TargetRegion não é uma condition key reconhecida — é um nome inventado."
    },
    "keyConcept": "Region restriction via SCP usando aws:RequestedRegion",
    "compareWith": [
     "SCP region restriction vs Service-specific region setting"
    ],
    "realWorldContext": "Empresas brasileiras com LGPD frequentemente restringem para sa-east-1 + us-east-1 apenas, bloqueando criação acidental em outras regiões.",
    "commonMistakes": "Esquecer de excluir serviços globais (IAM, CloudFront, Route 53) da restrição — eles aparecem como us-east-1 ou sem região, e a SCP pode quebrá-los se não tratado.",
    "tutorSeeds": [
     "Quais serviços AWS são globais e como tratá-los em SCP de region restriction?",
     "Como combinar SCP de região com exceções para break-glass?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'medium', 'best-practice', '["iam","scp","condition-keys","region"]'::jsonb, 'ai-draft', 'active', now(), now()
)
