INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-009', 'aws-clf', 'Qual afirmação sobre IAM Permission Boundaries é correta?',
  '[{"id":"A","text":"Permission Boundary define o MÁXIMO de permissões efetivas, mas não concede nada por si só"},{"id":"B","text":"Permission Boundary CONCEDE permissões adicionais ao principal"},{"id":"C","text":"Permission Boundary substitui a necessidade de identity policies"},{"id":"D","text":"Permission Boundary só funciona em IAM groups, não em users ou roles"}]'::jsonb, 'A',
  '{
    "summary": "Permission Boundary é teto — a permissão efetiva é a interseção da identity policy com a boundary. Sem identity policy concedendo, não há acesso.",
    "whyCorrect": "Permission Boundary é uma policy especial anexada a um user ou role que define o LIMITE MÁXIMO. A permissão efetiva é a interseção: se a boundary permite s3:* e a identity policy permite só s3:GetObject, o efetivo é s3:GetObject. Boundary não concede — só limita.",
    "whyWrong": {
     "B": "Boundary nunca concede; é puramente limitante.",
     "C": "Sem identity policy concedendo, o principal não tem permissão alguma — boundary não substitui o Allow explícito.",
     "D": "Boundaries só funcionam em IAM users e roles — NÃO existem em groups."
    },
    "keyConcept": "Permission Boundary — teto, não fonte de Allow",
    "compareWith": [
     "Permission Boundary vs SCP vs Identity Policy"
    ],
    "realWorldContext": "Padrão para delegated admin: time de plataforma define boundary; admins de produto podem criar roles dentro do limite.",
    "commonMistakes": "Achar que anexar uma boundary com s3:* permite leitura — sem identity policy permitindo s3:GetObject, ainda é Deny.",
    "tutorSeeds": [
     "Qual a diferença entre boundary e SCP na prática?",
     "Como impor que toda role criada tenha uma boundary anexada?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'medium', 'recall', '["iam","permission-boundary"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
