INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-010', 'aws-clf', 'Um time DevOps configura tags obrigatórias em todos os recursos. Qual condition key permite escrever uma policy que só permite criar uma EC2 instance se a request tiver a tag ''CostCenter'' com valor não-vazio?',
  '[{"id":"A","text":"aws:ResourceTag/CostCenter"},{"id":"B","text":"aws:RequestTag/CostCenter"},{"id":"C","text":"aws:PrincipalTag/CostCenter"},{"id":"D","text":"ec2:Tag/CostCenter"}]'::jsonb, 'B',
  '{
    "summary": "aws:RequestTag/<key> avalia as tags enviadas NA REQUISIÇÃO de criação. aws:ResourceTag avalia tags JÁ aplicadas no recurso existente.",
    "whyCorrect": "Para forçar que toda criação venha com a tag CostCenter, usa-se aws:RequestTag/CostCenter combinada com aws:TagKeys (para garantir presença da chave). Em uma policy: ''Condition'': {''StringEquals'': {''aws:RequestTag/CostCenter'': [''*'']}, ''ForAllValues:StringEquals'': {''aws:TagKeys'': [''CostCenter'', ...]}}.",
    "whyWrong": {
     "A": "aws:ResourceTag avalia tags JÁ existentes em um recurso (útil para operações em recursos já criados), não tags enviadas no momento da criação.",
     "C": "aws:PrincipalTag avalia tags no usuário/role chamador, não no recurso.",
     "D": "ec2:Tag não é a condition key global correta — usa-se as keys aws:RequestTag/aws:ResourceTag, que funcionam para múltiplos serviços."
    },
    "keyConcept": "Tag-based access control (TBAC/ABAC) — RequestTag, ResourceTag, PrincipalTag, TagKeys",
    "compareWith": [
     "aws:RequestTag vs aws:ResourceTag",
     "ABAC vs RBAC"
    ],
    "realWorldContext": "Empresas grandes impõem tagging governance via IAM/SCP para garantir billing por centro de custo.",
    "commonMistakes": "Usar ResourceTag para policies de criação — só RequestTag avalia a tag no momento da CreateAction.",
    "tutorSeeds": [
     "Como funciona ABAC no AWS?",
     "Por que aws:TagKeys precisa de ForAllValues?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'hard', 'scenario', '["iam","condition-keys","tags","abac"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
