INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-011', 'aws-clf', 'Em um cenário cross-account, qual mecanismo do AWS Organizations permite restringir a comunicação cross-account APENAS para principals dentro da mesma organização (impedindo até principals de contas externas de acessar resources mesmo com permissões)?',
  '[{"id":"A","text":"Region restriction via aws:RequestedRegion"},{"id":"B","text":"Tag policy obrigando tags por organização"},{"id":"C","text":"Condition key aws:PrincipalOrgID em resource policies"},{"id":"D","text":"AWS Config rule org-membership-check"}]'::jsonb, 'C',
  '{
    "summary": "aws:PrincipalOrgID em resource policies (S3, KMS, etc.) limita acesso a principals da mesma AWS Organization, mesmo que outras contas tenham IAM allow.",
    "whyCorrect": "aws:PrincipalOrgID contém o ID da organização do principal chamador. Usada em uma bucket policy ou key policy com StringEquals: {''aws:PrincipalOrgID'':''o-xxxxx''}, ela garante que apenas accounts dentro daquela organização possam acessar o recurso — bloqueia 100% de contas externas, mesmo com IAM allow do lado de origem.",
    "whyWrong": {
     "A": "aws:RequestedRegion restringe por região da chamada, não por organização.",
     "B": "Tag policies governam consistência de tags entre contas, não autorização cross-account.",
     "D": "Não existe uma Config rule oficial ''org-membership-check'' que funcione como controle preventivo em resource policies."
    },
    "keyConcept": "aws:PrincipalOrgID — guardrail de perímetro organizacional em resource policies",
    "compareWith": [
     "aws:PrincipalOrgID vs aws:SourceAccount",
     "Data perimeter pattern"
    ],
    "realWorldContext": "Componente central do ''data perimeter'' AWS: combina aws:PrincipalOrgID + aws:ResourceOrgID + aws:SourceVpc/Vpce para confinar recursos.",
    "commonMistakes": "Confundir com aws:PrincipalAccount — esse limita a UMA conta, enquanto PrincipalOrgID permite todas as contas da Organization.",
    "tutorSeeds": [
     "Como construir um data perimeter completo na AWS?",
     "Qual a diferença entre PrincipalOrgID e ResourceOrgID?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'hard', 'scenario', '["iam","organizations","data-perimeter"]'::jsonb, 'ai-draft', 'active', now(), now()
)
