INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-012', 'aws-clf', 'Qual STS API é usada para gerar credenciais temporárias para um usuário IAM PRÓPRIO (não federado) que precisa, por exemplo, executar uma operação que exige MFA?',
  '[{"id":"A","text":"GetFederationToken"},{"id":"B","text":"AssumeRole"},{"id":"C","text":"DecodeAuthorizationMessage"},{"id":"D","text":"GetSessionToken"}]'::jsonb, 'D',
  '{
    "summary": "GetSessionToken gera credenciais temporárias para um IAM user existente — comum para gating de MFA em CLI.",
    "whyCorrect": "GetSessionToken é chamada por um IAM user (com suas long-term credentials) para obter credenciais TEMPORÁRIAS que podem incluir um MFA serial+code. Útil quando o usuário precisa MFA para uma operação sensível via CLI/SDK e sua identity policy exige aws:MultiFactorAuthPresent=true.",
    "whyWrong": {
     "A": "GetFederationToken é usada por uma aplicação IAM user de back-end para gerar credenciais para usuários FEDERADOS (não-IAM), entregando sessions limitadas — caso diferente.",
     "B": "AssumeRole gera credenciais assumindo um ROLE, não credenciais do próprio user.",
     "C": "DecodeAuthorizationMessage só decodifica mensagens de erro de autorização codificadas — não emite credenciais."
    },
    "keyConcept": "STS APIs — GetSessionToken para self-MFA do IAM user; AssumeRole para role assumption",
    "compareWith": [
     "GetSessionToken vs GetFederationToken vs AssumeRole"
    ],
    "realWorldContext": "Engenheiros que precisam fazer ''aws s3 rb'' (delete bucket) com policy exigindo MFA usam aws sts get-session-token --serial-number ... --token-code ...",
    "commonMistakes": "Tentar usar AssumeRole para entregar MFA ao próprio user — esse é o caminho de role, não de session token do user.",
    "tutorSeeds": [
     "Qual a duração padrão das credenciais de GetSessionToken?",
     "Por que GetFederationToken não permite chamadas IAM?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'hard', 'recall', '["iam","sts","mfa","session-token"]'::jsonb, 'ai-draft', 'active', now(), now()
)
