INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-014', 'aws-clf', 'Qual é a diferença fundamental entre uma ''identity-based policy'' e uma ''resource-based policy'' no IAM?',
  '[{"id":"A","text":"Identity-based é JSON; resource-based é YAML"},{"id":"B","text":"Identity-based é anexada a um user/role/group e define o que ESSE principal pode fazer; resource-based é anexada a um recurso (S3 bucket, KMS key, etc.) e define quem pode acessá-lo"},{"id":"C","text":"Resource-based só funciona em S3"},{"id":"D","text":"Identity-based exige MFA; resource-based não"}]'::jsonb, 'B',
  '{
    "summary": "Identity-based responde ''o que esse principal pode fazer''. Resource-based responde ''quem pode acessar esse recurso''.",
    "whyCorrect": "Identity-based policies (managed/inline) são anexadas a um IAM identity (user, role, group) e listam permissões. Resource-based policies são anexadas diretamente a um recurso (S3 bucket policy, KMS key policy, SNS topic policy, Lambda resource policy, etc.) e listam quais principals podem acessar — incluindo principals de outras contas, o que viabiliza cross-account sem AssumeRole em alguns casos.",
    "whyWrong": {
     "A": "Ambas são JSON; diferença não é de formato.",
     "C": "Vários serviços suportam resource-based: S3, KMS, Lambda, SNS, SQS, ECR, Secrets Manager, IAM roles (trust policy), etc.",
     "D": "MFA é uma condition independente; não é o que diferencia identity de resource-based."
    },
    "keyConcept": "Identity-based vs Resource-based policies — perspectivas complementares",
    "compareWith": [
     "Identity-based vs Resource-based",
     "Resource-based vs ACL"
    ],
    "realWorldContext": "Cross-account S3: bucket policy (resource-based) lista principal da conta B; identity policy do principal de B permite s3:GetObject.",
    "commonMistakes": "Achar que basta resource-based — cross-account exige Allow nos DOIS lados (resource policy + identity policy do caller).",
    "tutorSeeds": [
     "Quando preferir resource-based em vez de role assumption?",
     "Como uma trust policy de role se classifica?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'easy', 'recall', '["iam","policy-types"]'::jsonb, 'ai-draft', 'active', now(), now()
)
