INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-015', 'aws-clf', 'Um arquiteto precisa decidir se entrega acesso S3 a outra conta via (1) bucket policy direta ou (2) IAM Role com AssumeRole. Qual cenário favorece a bucket policy direta SEM AssumeRole?',
  '[{"id":"A","text":"Quando é necessário acessar mais de um bucket em outras contas com um único set de credentials"},{"id":"B","text":"Quando se quer evitar bucket policies completamente"},{"id":"C","text":"Quando é necessário que o caller mantenha sua identidade original nos logs do CloudTrail e nas object ownership, sem trocar de contexto de credentials"},{"id":"D","text":"Quando o bucket é privado e tem Object Lock ativo"}]'::jsonb, 'C',
  '{
    "summary": "Bucket policy direta preserva a identidade original do caller no CloudTrail e em object ownership; AssumeRole troca o contexto para o role assumido.",
    "whyCorrect": "Com bucket policy concedendo acesso ao principal da outra conta, o caller usa SUAS credenciais — o CloudTrail no bucket loga seu ARN original, e objetos criados pertencem ao caller (importante para ''bucket owner enforced'' settings). Com AssumeRole, o contexto vira o role assumido (perdendo a identidade original), e tradicionalmente os objetos pertenciam ao role.",
    "whyWrong": {
     "A": "AssumeRole é exatamente útil para múltiplos recursos via um único set de temporary credentials — não é diferencial da bucket policy.",
     "B": "Bucket policy é justamente o que o item descreve — não ''evitá-las''.",
     "D": "Object Lock é ortogonal à decisão entre resource policy vs AssumeRole."
    },
    "keyConcept": "Resource-based policy direta preserva identidade; AssumeRole troca contexto",
    "compareWith": [
     "Bucket policy cross-account vs AssumeRole pattern",
     "Bucket owner enforced setting"
    ],
    "realWorldContext": "Data lakes que precisam atribuir custos/auditoria por usuário externo preferem bucket policy direta.",
    "commonMistakes": "Tratar as duas abordagens como equivalentes — elas têm efeitos diferentes em logging e ownership.",
    "tutorSeeds": [
     "Como o setting ''Bucket owner enforced'' impacta cross-account?",
     "Quando AssumeRole é obrigatório (não tem resource policy disponível)?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'hard', 'scenario', '["iam","s3","cross-account","bucket-policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
