INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-016', 'aws-clf', 'Um IAM user tem (a) identity policy permitindo s3:GetObject em qualquer bucket; (b) permission boundary permitindo só s3:ListBucket. Qual operação o user consegue executar?',
  '[{"id":"A","text":"Apenas s3:GetObject"},{"id":"B","text":"Apenas s3:ListBucket"},{"id":"C","text":"Ambas — boundaries somam permissões"},{"id":"D","text":"Nenhuma — a interseção é vazia"}]'::jsonb, 'D',
  '{
    "summary": "A permissão efetiva é a INTERSEÇÃO entre identity policy e permission boundary. {s3:GetObject} ∩ {s3:ListBucket} = ∅.",
    "whyCorrect": "Boundary atua como teto. Para uma ação ser permitida, ela precisa estar Allow na identity policy E no escopo da boundary. Se a identity policy permite GetObject mas a boundary só inclui ListBucket, GetObject está fora do teto (Deny por boundary); e ListBucket está fora da identity policy (Deny implícito por falta de Allow). Resultado: nenhuma das duas funciona.",
    "whyWrong": {
     "A": "GetObject está fora da boundary — bloqueado.",
     "B": "ListBucket está fora da identity policy — sem Allow, é Deny implícito.",
     "C": "Boundary nunca soma — só limita."
    },
    "keyConcept": "Permission Boundary — interseção, não união",
    "compareWith": [
     "Boundary efetivo vs Identity policy efetivo"
    ],
    "realWorldContext": "Erro comum de delegated admin: boundary muito restrita causa Deny inesperado mesmo com identity policy generosa.",
    "commonMistakes": "Imaginar que boundary ''soma'' permissões — é estritamente teto.",
    "tutorSeeds": [
     "Como debugar Deny por boundary no IAM policy simulator?",
     "Diferença prática entre boundary e SCP para o efetivo?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'hard', 'scenario', '["iam","permission-boundary","policy-evaluation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
