INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-018', 'aws-clf', 'Qual afirmação sobre IAM access keys de um IAM user é VERDADEIRA?',
  '[{"id":"A","text":"Access keys têm rotação automática a cada 30 dias por padrão"},{"id":"B","text":"Um user pode ter no máximo duas access keys ativas simultaneamente, para facilitar rotação sem downtime"},{"id":"C","text":"Access keys nunca expiram, mesmo quando o user é desativado"},{"id":"D","text":"Access keys são automaticamente rotacionadas pelo IAM Access Analyzer"}]'::jsonb, 'B',
  '{
    "summary": "Cada IAM user pode ter até 2 access keys ativas — desenhado para rotação manual sem downtime (cria nova, troca, desativa antiga).",
    "whyCorrect": "O limite de 2 access keys por user existe especificamente para permitir rotação segura: cria-se uma segunda key, atualiza-se a aplicação para usá-la, valida, depois desativa e deleta a primeira. Não há rotação automática nativa de access keys de IAM user — daí a recomendação de migrar para roles + STS.",
    "whyWrong": {
     "A": "Não há rotação automática nativa — é manual.",
     "C": "Access keys ficam atreladas ao user; ao deletar/desativar o user, as keys também perdem validade.",
     "D": "Access Analyzer DETECTA keys ociosas; não rotaciona automaticamente."
    },
    "keyConcept": "Access keys — limite de 2 ativas para rotação manual; sem rotação automática",
    "compareWith": [
     "Access key vs Temporary credentials via STS"
    ],
    "realWorldContext": "Best practice 2025: substituir IAM users com access keys por IAM Identity Center + AssumeRole; quando inevitável, rotacionar a cada 90 dias.",
    "commonMistakes": "Esperar rotação automática nativa — não existe para access keys de IAM user; só temporary credentials via STS rotacionam sozinhas.",
    "tutorSeeds": [
     "Como detectar access keys não rotacionadas há mais de 90 dias?",
     "Como migrar de IAM user com keys para Identity Center?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'easy', 'recall', '["iam","access-keys","rotation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
