INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-019', 'aws-clf', 'Quando o IAM avalia uma chamada, qual a ordem correta de precedência das decisões?',
  '[{"id":"A","text":"Implicit Allow \u003e Explicit Allow \u003e Explicit Deny"},{"id":"B","text":"Explicit Allow \u003e Explicit Deny \u003e Implicit Deny"},{"id":"C","text":"Explicit Deny \u003e Explicit Allow \u003e Implicit Deny"},{"id":"D","text":"Todas as policies se somam democraticamente, sem precedência"}]'::jsonb, 'C',
  '{
    "summary": "Explicit Deny SEMPRE vence. Sem Allow explícito, é Implicit Deny.",
    "whyCorrect": "A lógica IAM é: começa em Implicit Deny (default). Qualquer Allow explícito (identity, resource, etc.) muda para Allow. Mas QUALQUER Deny explícito (em qualquer policy aplicável — SCP, boundary, identity, resource, session) vence e gera Deny final. Por isso a regra: Deny > Allow > Implicit Deny.",
    "whyWrong": {
     "A": "Não existe ''Implicit Allow'' no IAM — o default é Implicit Deny.",
     "B": "Deny explícito vence Allow explícito — não o contrário.",
     "D": "Existe precedência clara; policies não se democratizam."
    },
    "keyConcept": "Policy evaluation logic — explicit Deny vence sempre",
    "compareWith": [
     "IAM evaluation logic vs Kubernetes RBAC evaluation"
    ],
    "realWorldContext": "Usado em SCPs para guardrails fortes que mesmo admins não conseguem furar.",
    "commonMistakes": "Achar que adicionar mais Allows resolve um Deny — só remover/condicionar o Deny resolve.",
    "tutorSeeds": [
     "Como o IAM Policy Simulator mostra essa lógica?",
     "Qual a única exceção (root user em conta-membro com SCP)?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'easy', 'recall', '["iam","policy-evaluation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
