INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-020', 'aws-clf', 'Em uma session policy passada via AssumeRole (parâmetro Policy do API), qual o efeito sobre as permissões da sessão resultante?',
  '[{"id":"A","text":"Adiciona permissões além das que o role já tem"},{"id":"B","text":"Substitui completamente a policy do role"},{"id":"C","text":"Tem efeito apenas em produção"},{"id":"D","text":"Restringe as permissões a uma interseção com a policy do role (não pode conceder mais)"}]'::jsonb, 'D',
  '{
    "summary": "Session policies só RESTRINGEM — a sessão efetiva é a interseção da role policy com a session policy.",
    "whyCorrect": "Quando AssumeRole é chamado com o parâmetro Policy (inline session policy), as credenciais resultantes têm permissões = role identity policy ∩ session policy. Nunca concede além do que o role já tem. Útil para entregar credenciais com menos privilégio a um sub-componente.",
    "whyWrong": {
     "A": "Session policy nunca adiciona — só restringe.",
     "B": "Não substitui; é interseção.",
     "C": "Efeito é universal, não depende de ambiente."
    },
    "keyConcept": "Session policy — interseção restritiva, never expansão",
    "compareWith": [
     "Session policy vs Permission Boundary",
     "Identity policy do role vs Session policy"
    ],
    "realWorldContext": "API Gateway Lambda authorizers, brokers de credenciais e CLI wrappers que entregam credenciais com escopo reduzido a um workload específico.",
    "commonMistakes": "Tentar ampliar permissões via session policy — não dá; precisa atualizar a policy do role.",
    "tutorSeeds": [
     "Diferença prática entre session policy e permission boundary?",
     "Como passar uma session policy via SDK?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'hard', 'recall', '["iam","sts","session-policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
