INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-021', 'aws-clf', 'Uma engenheira tenta usar a CLI: ''aws sts assume-role --role-arn arn:aws:iam::222:role/DevOps --role-session-name x'' e recebe ''AccessDenied: User is not authorized to perform: sts:AssumeRole on resource ...''. Onde investigar primeiro?',
  '[{"id":"A","text":"Identity policy do user/role caller — falta Allow para sts:AssumeRole com Resource = ARN do role-alvo"},{"id":"B","text":"Trust policy do role DevOps na conta 222"},{"id":"C","text":"VPC endpoint para STS"},{"id":"D","text":"KMS key policy da conta 222"}]'::jsonb, 'A',
  '{
    "summary": "A mensagem ''User is not authorized to perform sts:AssumeRole'' indica que a IDENTITY policy do caller não permite a ação.",
    "whyCorrect": "Quando o erro vem do lado de origem (''User is not authorized to perform sts:AssumeRole''), o IAM rejeitou ANTES de chegar ao role-alvo — falta Allow na identity policy do caller. Se a trust policy do role-alvo é que estivesse errada, a mensagem seria diferente (algo como ''cannot be assumed by this principal'').",
    "whyWrong": {
     "B": "Erro de trust policy aparece com outra mensagem (''not authorized to be assumed by''); aqui o erro é claro sobre o caller.",
     "C": "VPC endpoint para STS é otimização; sua ausência não dispara esse erro específico de autorização.",
     "D": "KMS é irrelevante para o handshake de AssumeRole."
    },
    "keyConcept": "Diagnóstico de erros AssumeRole — distinguir lado origem vs lado destino",
    "compareWith": [
     "Erro de identity policy vs erro de trust policy"
    ],
    "realWorldContext": "Erro recorrente em pipelines CI/CD com OIDC: o role de execução não tem sts:AssumeRole na identity policy.",
    "commonMistakes": "Sair editando a trust policy do role-alvo quando o problema está na identity policy do caller.",
    "tutorSeeds": [
     "Como ler a mensagem completa do AccessDenied?",
     "Como o policy simulator ajuda a diagnosticar?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'medium', 'troubleshoot', '["iam","sts","assume-role","troubleshoot"]'::jsonb, 'ai-draft', 'active', now(), now()
)
