INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-022', 'aws-clf', 'Qual ação NÃO pode ser executada por uma SCP da AWS Organizations?',
  '[{"id":"A","text":"Negar a criação de recursos em regiões não aprovadas"},{"id":"B","text":"Conceder permissões a um IAM user que não tem nenhuma identity policy"},{"id":"C","text":"Negar mudanças no CloudTrail organization trail"},{"id":"D","text":"Limitar quais services podem ser usados na conta-membro"}]'::jsonb, 'B',
  '{
    "summary": "SCP é um GUARDRAIL — limita o que principals podem fazer, mas NUNCA concede permissões.",
    "whyCorrect": "SCPs definem o teto máximo de permissões disponíveis para principals da conta. Sem identity policy concedendo, o user não tem acesso a nada — SCP não cria Allow. As outras opções são todas usos canônicos de SCP (deny de região, deny de mudança em logging, allow-list de services).",
    "whyWrong": {
     "A": "Region restriction via SCP é caso clássico (com aws:RequestedRegion).",
     "C": "SCP protegendo CloudTrail é guardrail recomendado em landing zones.",
     "D": "Allow-list de services via SCP é também uso comum."
    },
    "keyConcept": "SCP — só limita, nunca concede",
    "compareWith": [
     "SCP vs Identity Policy",
     "SCP vs Permission Boundary"
    ],
    "realWorldContext": "Control Tower aplica conjuntos pré-definidos de SCPs para guardrails padronizados.",
    "commonMistakes": "Esperar que SCP ''libere'' uma ação — só identity policies (e resource policies) concedem.",
    "tutorSeeds": [
     "Como Control Tower mantém o conjunto de SCPs?",
     "Por que SCP não afeta o root account de uma management account?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'easy', 'recall', '["iam","scp","organizations"]'::jsonb, 'ai-draft', 'active', now(), now()
)
