INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-023', 'aws-clf', 'Em um cenário com Federation via OIDC (GitHub Actions chamando AWS), qual STS API é usada?',
  '[{"id":"A","text":"AssumeRole"},{"id":"B","text":"AssumeRoleWithSAML"},{"id":"C","text":"AssumeRoleWithWebIdentity"},{"id":"D","text":"GetCallerIdentity"}]'::jsonb, 'C',
  '{
    "summary": "AssumeRoleWithWebIdentity troca um JWT/OIDC token por credenciais AWS temporárias.",
    "whyCorrect": "GitHub Actions emite um OIDC JWT identificando o workflow; o AWS Identity Provider (configurado com a URL do GitHub OIDC) valida o token, e sts:AssumeRoleWithWebIdentity retorna credenciais temporárias. É o padrão recomendado para CI/CD — elimina access keys long-lived em segredos do GitHub.",
    "whyWrong": {
     "A": "AssumeRole simples é para principals IAM existentes (cross-account user/role).",
     "B": "SAML é para IdPs SAML 2.0 (ADFS), não OIDC.",
     "D": "GetCallerIdentity só retorna ARN/Account do caller; não emite credenciais."
    },
    "keyConcept": "AssumeRoleWithWebIdentity — OIDC/JWT to AWS credentials",
    "compareWith": [
     "WithWebIdentity (OIDC) vs WithSAML (SAML 2.0)",
     "GitHub OIDC vs Long-lived access keys"
    ],
    "realWorldContext": "Best practice 2024+ para CI/CD com GitHub Actions, GitLab, Bitbucket — zero secrets de AWS no repositório.",
    "commonMistakes": "Configurar como SAML — OIDC e SAML usam APIs e Principal types diferentes na trust policy.",
    "tutorSeeds": [
     "Como restringir o OIDC trust ao repositório/branch?",
     "Quais condition keys especiais para OIDC?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'medium', 'scenario', '["iam","sts","oidc","github-actions"]'::jsonb, 'ai-draft', 'active', now(), now()
)
