INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-024', 'aws-clf', 'Qual o limite máximo de duração para credenciais temporárias retornadas por AssumeRole?',
  '[{"id":"A","text":"15 minutos, fixo"},{"id":"B","text":"24 horas, sempre"},{"id":"C","text":"Permanente, até revogação manual"},{"id":"D","text":"Configurável de 15 minutos até 12 horas (limitado por MaxSessionDuration do role)"}]'::jsonb, 'D',
  '{
    "summary": "AssumeRole permite duração entre 15 minutos e até o MaxSessionDuration do role (máx 12h).",
    "whyCorrect": "Cada IAM role tem um atributo MaxSessionDuration (default 1h, máximo 12h). O caller especifica DurationSeconds no AssumeRole; o STS aceita valor entre 900 (15min) e o MaxSessionDuration do role. AssumeRoleWithSAML e WithWebIdentity também respeitam 12h máx. GetSessionToken vai até 36h em alguns casos, mas AssumeRole especificamente cap em 12h.",
    "whyWrong": {
     "A": "15 minutos é o mínimo, não o fixo.",
     "B": "24h é incorreto para AssumeRole.",
     "C": "Credenciais STS sempre expiram — não há credencial temporária permanente."
    },
    "keyConcept": "Duração de credenciais STS — configurable, cap em 12h para AssumeRole",
    "compareWith": [
     "AssumeRole 12h vs GetSessionToken 36h",
     "DurationSeconds vs MaxSessionDuration"
    ],
    "realWorldContext": "Pipelines longos (build de monorepo) configuram MaxSessionDuration alto; consoles humanos normalmente 1h.",
    "commonMistakes": "Pedir DurationSeconds maior que MaxSessionDuration do role — STS retorna ValidationError.",
    "tutorSeeds": [
     "Como configurar MaxSessionDuration?",
     "Quando preferir credenciais curtas vs longas?"
    ]
   }'::jsonb,
  'IAM', 'Security & Compliance', 'medium', 'recall', '["iam","sts","session-duration"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
