INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-025', 'aws-clf', 'Qual é o papel central do AWS IAM Identity Center (sucessor do AWS SSO)?',
  '[{"id":"A","text":"Fornecer login único (SSO) federado a múltiplas contas AWS e aplicações SaaS, com permission sets que viram IAM roles na conta-alvo"},{"id":"B","text":"Hospedar máquinas virtuais para login centralizado"},{"id":"C","text":"Substituir o IAM por completo, tornando contas-membro sem IAM"},{"id":"D","text":"Gerenciar certificados X.509 corporativos"}]'::jsonb, 'A',
  '{
    "summary": "Identity Center é a camada de SSO para contas AWS + aplicações; usa permission sets que se materializam como IAM roles federadas em cada conta.",
    "whyCorrect": "Identity Center fornece um portal único onde usuários (do diretório próprio, AD Connector ou IdP externo) escolhem uma combinação de conta+permission set e recebem credenciais temporárias via federation SAML. Cada permission set se materializa como uma IAM role com prefixo ''AWSReservedSSO_'' na conta-alvo.",
    "whyWrong": {
     "B": "Não hospeda VMs — é serviço de identidade gerenciado.",
     "C": "Não substitui IAM; usa IAM como camada de execução. Permission sets viram roles IAM.",
     "D": "Não é PKI/CA; isso é ACM/ACM Private CA."
    },
    "keyConcept": "Identity Center — federation hub sobre IAM, com permission sets → IAM roles",
    "compareWith": [
     "Identity Center vs IAM Federation manual",
     "Permission Set vs IAM Role"
    ],
    "realWorldContext": "Substituiu o antigo AWS SSO; é a recomendação atual para multi-account access humano.",
    "commonMistakes": "Pensar que Identity Center elimina IAM — ele se ASSENTA sobre IAM; roles ainda existem.",
    "tutorSeeds": [
     "Como o portal do Identity Center descobre as contas disponíveis?",
     "Como permission sets se materializam em IAM roles?"
    ]
   }'::jsonb,
  'Identity Center', 'Security & Compliance', 'easy', 'recall', '["identity-center","sso","federation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
