INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-026', 'aws-clf', 'Uma empresa quer usar Okta como IdP corporativo e dar aos engenheiros acesso a 30 contas AWS via SSO. Qual a abordagem recomendada?',
  '[{"id":"A","text":"Criar IAM users em cada uma das 30 contas e sincronizar manualmente com Okta"},{"id":"B","text":"Configurar Okta como external Identity Provider no AWS IAM Identity Center via SAML/SCIM e definir permission sets"},{"id":"C","text":"Compartilhar as credenciais do root user com Okta"},{"id":"D","text":"Configurar bucket policies em S3 para integrar com Okta"}]'::jsonb, 'B',
  '{
    "summary": "Identity Center + external IdP (Okta) via SAML/SCIM é o padrão moderno para SSO multi-account.",
    "whyCorrect": "Identity Center suporta IdPs externos (Okta, Azure AD/Entra ID, Google Workspace, Ping) via SAML 2.0 para autenticação e SCIM 2.0 para provisionamento automático de users/groups. Você define permission sets uma vez e atribui a groups Okta — cada usuário Okta acessa o portal AWS, escolhe conta+role, e recebe credenciais temporárias.",
    "whyWrong": {
     "A": "Cria-se overhead massivo, sincronização frágil e access keys de longa duração — anti-padrão.",
     "C": "Compartilhar root credentials é falha grave de segurança.",
     "D": "Bucket policies não autenticam usuários corporativos."
    },
    "keyConcept": "Identity Center external IdP — SAML para auth, SCIM para provisioning",
    "compareWith": [
     "Identity Center com IdP externo vs Identity Center directory próprio"
    ],
    "realWorldContext": "Padrão da maioria das empresas médias/grandes: AD/Entra ID/Okta como source of truth, Identity Center como broker para AWS.",
    "commonMistakes": "Configurar SAML sem SCIM — sem SCIM, users/groups precisam ser criados manualmente no Identity Center.",
    "tutorSeeds": [
     "Diferença entre SAML e SCIM?",
     "Por que SCIM importa para revogar acesso quando alguém deixa a empresa?"
    ]
   }'::jsonb,
  'Identity Center', 'Security & Compliance', 'medium', 'scenario', '["identity-center","okta","saml","scim"]'::jsonb, 'ai-draft', 'active', now(), now()
)
