INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-027', 'aws-clf', 'O que é um ''permission set'' no AWS IAM Identity Center?',
  '[{"id":"A","text":"Um grupo de IAM users"},{"id":"B","text":"Um certificado SSL para o portal SSO"},{"id":"C","text":"Uma coleção de policies (AWS managed e/ou inline) que, quando atribuída a um usuário/grupo em uma conta-membro, materializa-se como uma IAM role com essas permissões"},{"id":"D","text":"Um cluster de servidores de autenticação"}]'::jsonb, 'C',
  '{
    "summary": "Permission set = template de policies que vira uma IAM role na conta-alvo quando atribuído.",
    "whyCorrect": "Permission set é definido uma vez no Identity Center e contém: AWS managed policies, customer managed policies (com nome igual em cada conta-alvo), inline policy, permission boundary, session duration. Ao atribuir um permission set a um (account, group/user), o Identity Center cria automaticamente uma IAM role na conta-alvo com prefixo ''AWSReservedSSO_<permission-set-name>_<hash>''.",
    "whyWrong": {
     "A": "Não é um grupo — é um conjunto de policies.",
     "B": "Não é um certificado SSL.",
     "D": "Não é infraestrutura física — é uma abstração de policy."
    },
    "keyConcept": "Permission Set — template de policies materializado como IAM role",
    "compareWith": [
     "Permission Set vs IAM Role direta",
     "Permission Set assignment vs group membership"
    ],
    "realWorldContext": "Permission sets típicos: AdministratorAccess, ReadOnly, PowerUser, Billing, etc.",
    "commonMistakes": "Tentar editar a IAM role criada manualmente — Identity Center sobrescreve. Sempre editar via permission set.",
    "tutorSeeds": [
     "Como o Identity Center sincroniza alterações em permission sets para todas as contas?",
     "O que acontece com sessões ativas quando você muda um permission set?"
    ]
   }'::jsonb,
  'Identity Center', 'Security & Compliance', 'medium', 'recall', '["identity-center","permission-set"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
