INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-028', 'aws-clf', 'Qual a diferença fundamental entre IAM Identity Center e federation IAM tradicional (criar IAM SAML provider em cada conta)?',
  '[{"id":"A","text":"Identity Center é pago, federation IAM é grátis"},{"id":"B","text":"Federation IAM tradicional não funciona com Okta"},{"id":"C","text":"Identity Center exige Active Directory on-prem"},{"id":"D","text":"Identity Center centraliza autenticação e permissões em UMA configuração que se propaga para todas as contas; federation IAM tradicional exige configurar SAML provider + roles em CADA conta separadamente"}]'::jsonb, 'D',
  '{
    "summary": "Identity Center elimina a duplicação por conta; federation IAM tradicional exige configurar IdP + roles em cada conta-membro.",
    "whyCorrect": "Com federation IAM tradicional, você precisa criar o SAML Identity Provider e os roles federados em cada conta. Com Identity Center, configura-se uma vez no nível da Organization e os permission sets se propagam para todas as contas atribuídas. Reduz drasticamente o overhead operacional e mantém consistência.",
    "whyWrong": {
     "A": "Identity Center é gratuito (você paga só os recursos AWS subjacentes). Federation IAM também é gratuita.",
     "B": "Federation IAM tradicional funciona com qualquer IdP SAML 2.0, incluindo Okta — só é mais trabalhosa.",
     "C": "Identity Center pode usar diretório próprio, AD Connector OU IdP externo — não exige AD on-prem."
    },
    "keyConcept": "Identity Center centraliza; federation IAM tradicional duplica por conta",
    "compareWith": [
     "Identity Center vs IAM SAML federation",
     "Single-account SAML vs Organization-wide SSO"
    ],
    "realWorldContext": "Empresas com mais de 5 contas geralmente migram da federation IAM tradicional para Identity Center.",
    "commonMistakes": "Manter federation IAM tradicional em ambientes multi-account novos — Identity Center é a recomendação atual.",
    "tutorSeeds": [
     "Como migrar de IAM SAML federation para Identity Center?",
     "Em que casos federation IAM tradicional ainda faz sentido?"
    ]
   }'::jsonb,
  'Identity Center', 'Security & Compliance', 'medium', 'recall', '["identity-center","federation","comparison"]'::jsonb, 'ai-draft', 'active', now(), now()
)
