INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-029', 'aws-clf', 'Em uma empresa com Azure AD/Entra ID como diretório corporativo, qual protocolo o Identity Center usa para automaticamente sincronizar users e groups (provisionamento) do Entra ID?',
  '[{"id":"A","text":"SCIM 2.0"},{"id":"B","text":"LDAP"},{"id":"C","text":"OAuth 2.0"},{"id":"D","text":"Kerberos"}]'::jsonb, 'A',
  '{
    "summary": "SCIM 2.0 é o protocolo padrão para provisioning automático de users/groups entre IdP e Identity Center.",
    "whyCorrect": "SCIM (System for Cross-domain Identity Management) é o padrão IETF para provisionamento automático. Entra ID/Okta/Google Workspace publicam mudanças de users e groups via SCIM 2.0 para o endpoint do Identity Center, que mantém o cache local sincronizado. Sem SCIM, you''d precisaria criar users manualmente.",
    "whyWrong": {
     "B": "LDAP é protocolo de diretório; não é o canal de provisionamento entre IdPs SaaS e Identity Center.",
     "C": "OAuth 2.0 é autorização para acesso a APIs, não provisioning de usuários.",
     "D": "Kerberos é autenticação em redes corporativas Windows; irrelevante aqui."
    },
    "keyConcept": "SCIM 2.0 — protocolo de provisioning entre IdP e Identity Center",
    "compareWith": [
     "SCIM (provisioning) vs SAML (auth)",
     "Manual user creation vs SCIM"
    ],
    "realWorldContext": "Quando um funcionário deixa a empresa, o Entra ID desativa a conta e o SCIM propaga em minutos para o Identity Center, revogando acesso AWS automaticamente.",
    "commonMistakes": "Confundir SCIM com SAML — SAML autentica (login), SCIM provisiona (cadastro).",
    "tutorSeeds": [
     "Como debugar problemas de SCIM no Entra ID?",
     "Quais atributos do user são sincronizados?"
    ]
   }'::jsonb,
  'Identity Center', 'Security & Compliance', 'medium', 'scenario', '["identity-center","scim","entra-id"]'::jsonb, 'ai-draft', 'active', now(), now()
)
