INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-030', 'aws-clf', 'Como um usuário corporativo do Identity Center acessa o AWS CLI em sua máquina?',
  '[{"id":"A","text":"Recebe access keys long-lived por email"},{"id":"B","text":"Configura um SSO profile com ''aws configure sso'', faz login no navegador, e o CLI obtém credenciais temporárias automaticamente"},{"id":"C","text":"Compartilha as credenciais com colegas via Slack"},{"id":"D","text":"Usa apenas via Console web, CLI não é suportado"}]'::jsonb, 'B',
  '{
    "summary": "aws configure sso configura um profile que aciona login no browser e armazena credenciais temporárias localmente, renovadas via refresh tokens.",
    "whyCorrect": "O fluxo CLI v2 com SSO: o usuário roda ''aws configure sso'', informa start URL e região do Identity Center; o CLI abre o navegador para login federado; ao autorizar, o CLI obtém um access token; chamadas subsequentes (''aws s3 ls --profile xxx'') usam o token para AssumeRoleWithSAML/CreateToken e obtêm credenciais temporárias — renovadas automaticamente até a session duration.",
    "whyWrong": {
     "A": "Não há access keys long-lived no Identity Center.",
     "C": "Compartilhar credenciais é violação de política e gera auditoria suja.",
     "D": "CLI é totalmente suportado e é o caminho recomendado."
    },
    "keyConcept": "AWS CLI v2 + Identity Center SSO — credenciais temporárias automáticas",
    "compareWith": [
     "aws configure sso vs aws configure (long-lived keys)"
    ],
    "realWorldContext": "Engenheiros têm múltiplos profiles, um por conta+role, e usam ''--profile prod-readonly'' nos comandos.",
    "commonMistakes": "Tentar usar CLI v1 com SSO — só v2 suporta nativamente.",
    "tutorSeeds": [
     "Onde o CLI armazena os tokens localmente?",
     "Como configurar profile padrão para SSO?"
    ]
   }'::jsonb,
  'Identity Center', 'Security & Compliance', 'medium', 'best-practice', '["identity-center","cli","sso"]'::jsonb, 'ai-draft', 'active', now(), now()
)
