INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-031', 'aws-clf', 'Qual o impacto de revogar um usuário no IdP externo (ex: desativar conta Okta) sobre o acesso AWS via Identity Center?',
  '[{"id":"A","text":"Nenhum — o usuário continua acessando AWS até a expiração natural das credenciais"},{"id":"B","text":"O usuário é deletado de todas as IAM roles em todas as contas"},{"id":"C","text":"Imediato em tentativas futuras de login; sessions ativas continuam até expirar (configurável via Permission Set session duration)"},{"id":"D","text":"Requer reboot manual de cada conta-membro"}]'::jsonb, 'C',
  '{
    "summary": "Revogar no IdP bloqueia novos logins imediatamente; sessions já emitidas continuam até expirarem (até 12h).",
    "whyCorrect": "Quando o IdP desativa um user, novas autenticações falham — o usuário não consegue mais logar no portal Identity Center. PORÉM credenciais temporárias já emitidas (válidas até o session duration definido no permission set) continuam válidas até expirar. Para revogar imediatamente, há a operação ''DeleteSession'' do Identity Center que invalida sessions ativas.",
    "whyWrong": {
     "A": "Login novo já falha imediatamente após sync SCIM.",
     "B": "Permission sets/IAM roles não são deletados — eles permanecem; só esse usuário deixa de poder assumi-los.",
     "D": "Não há reboot envolvido."
    },
    "keyConcept": "Revogação imediata para login vs sessions ativas com lifetime curto",
    "compareWith": [
     "Session duration short (1h) vs long (12h) — trade-off entre UX e segurança"
    ],
    "realWorldContext": "Por isso recomenda-se session duration curta (1-4h) em contas de produção sensíveis — limita janela de exposição pós-revogação.",
    "commonMistakes": "Achar que desativar no IdP encerra sessions já abertas — não encerra automaticamente.",
    "tutorSeeds": [
     "Como forçar logout imediato de todas as sessions de um user?",
     "Trade-off entre session duration longa e segurança?"
    ]
   }'::jsonb,
  'Identity Center', 'Security & Compliance', 'hard', 'scenario', '["identity-center","revocation","session-duration"]'::jsonb, 'ai-draft', 'active', now(), now()
)
