INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-032', 'aws-clf', 'Além de federar acesso a contas AWS, o Identity Center também pode entregar SSO para:',
  '[{"id":"A","text":"Apenas serviços AWS, nada mais"},{"id":"B","text":"Apenas RDS databases"},{"id":"C","text":"Apenas Workspaces"},{"id":"D","text":"Aplicações SaaS com SAML/OIDC pré-integradas (ex: Salesforce, Slack, Office 365) — chamadas ''customer-managed applications'' ou ''cloud applications''"}]'::jsonb, 'D',
  '{
    "summary": "Identity Center também entrega SSO para apps SaaS externas via SAML/OIDC, não só para contas AWS.",
    "whyCorrect": "O Identity Center mantém um catálogo de cloud applications pré-integradas (Salesforce, Slack, Office 365, Box, Dropbox, etc.) e permite adicionar ''customer-managed applications'' SAML. O usuário acessa o portal e clica num app para fazer SSO. Isso transforma o Identity Center num pequeno Okta — usável como IdP corporativo lite.",
    "whyWrong": {
     "A": "Não é apenas AWS — também SaaS.",
     "B": "Não é especificamente RDS.",
     "C": "Não é apenas Workspaces."
    },
    "keyConcept": "Identity Center — SSO para AWS + apps SaaS via SAML/OIDC",
    "compareWith": [
     "Identity Center como mini-Okta vs Okta full enterprise"
    ],
    "realWorldContext": "Empresas pequenas que não querem pagar Okta usam o Identity Center como IdP central — gratuito, suficiente para casos básicos.",
    "commonMistakes": "Ignorar essa capability e achar que Identity Center serve só para AWS.",
    "tutorSeeds": [
     "Como adicionar uma cloud application?",
     "Quando Identity Center não é suficiente e precisa de Okta/Azure AD?"
    ]
   }'::jsonb,
  'Identity Center', 'Security & Compliance', 'medium', 'recall', '["identity-center","saas","applications"]'::jsonb, 'ai-draft', 'active', now(), now()
)
