INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-033', 'aws-clf', 'Uma empresa quer aplicar uma permission boundary obrigatória em todos os permission sets criados no Identity Center. Isso é possível?',
  '[{"id":"A","text":"Sim, cada permission set pode incluir uma ''permissions boundary'' configurada explicitamente, que vira boundary da IAM role gerada"},{"id":"B","text":"Não, permission sets ignoram permission boundaries"},{"id":"C","text":"Sim, mas só via SCP"},{"id":"D","text":"Apenas para permission sets de read-only"}]'::jsonb, 'A',
  '{
    "summary": "Permission sets suportam configurar uma permissions boundary; ela é aplicada à IAM role gerada na conta-alvo.",
    "whyCorrect": "Na criação/edição de um permission set, você pode anexar uma AWS managed policy ou customer managed policy como ''permissions boundary''. Quando o Identity Center materializa o permission set em uma IAM role na conta-alvo, essa boundary é anexada à role — limitando o teto efetivo conforme a regra padrão de boundaries.",
    "whyWrong": {
     "B": "Permission sets aceitam boundaries — útil para defesa em profundidade.",
     "C": "SCP é diferente — atua no nível da Organization. Boundary é IAM-level. Ambos podem coexistir.",
     "D": "Não há restrição por tipo de permission set."
    },
    "keyConcept": "Permission set + permissions boundary — boundary aplicada à IAM role gerada",
    "compareWith": [
     "Permission set boundary vs SCP",
     "Defense in depth com múltiplas camadas"
    ],
    "realWorldContext": "Em ambientes regulados, boundary obrigatório protege contra erros em permission set policies muito amplas.",
    "commonMistakes": "Achar que boundary e SCP fazem o mesmo — SCP é organizacional, boundary é por identidade IAM.",
    "tutorSeeds": [
     "Como customer managed policy boundary precisa existir em cada conta-alvo?",
     "Trade-off entre boundary no permission set vs SCP organization-wide?"
    ]
   }'::jsonb,
  'Identity Center', 'Security & Compliance', 'hard', 'best-practice', '["identity-center","permission-boundary","defense-in-depth"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
