INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-035', 'aws-clf', 'No Identity Center, qual é a diferença entre ''AWS account access'' e ''application access''?',
  '[{"id":"A","text":"Não há diferença — é o mesmo conceito"},{"id":"B","text":"Application access é apenas para apps mobile"},{"id":"C","text":"AWS account access usa permission sets que viram IAM roles federadas; application access entrega SSO para apps SaaS via SAML/OIDC sem IAM roles AWS"},{"id":"D","text":"AWS account access é gratuito; application access é pago"}]'::jsonb, 'C',
  '{
    "summary": "AWS account access usa IAM roles federadas; application access entrega SSO para SaaS externas, sem envolver IAM.",
    "whyCorrect": "São duas dimensões distintas do mesmo Identity Center: (1) AWS account access — atribuição de permission sets a contas, materializando IAM roles federadas que dão acesso a APIs AWS; (2) Application access — SSO para apps SaaS (Salesforce, Slack, Office 365), via SAML 2.0 ou OIDC, sem qualquer IAM role envolvida.",
    "whyWrong": {
     "A": "São mecanismos distintos com fluxos diferentes.",
     "B": "Application access funciona para web/desktop também.",
     "D": "Identity Center é gratuito em ambos os casos."
    },
    "keyConcept": "Identity Center — dois domínios de SSO: contas AWS + applications",
    "compareWith": [
     "Account access (IAM roles) vs Application access (SAML/OIDC apps)"
    ],
    "realWorldContext": "Uma startup pode usar Identity Center para AWS + Slack + Notion + Google Workspace, eliminando senhas separadas.",
    "commonMistakes": "Pensar que ''app access'' também envolve IAM role — não envolve; é federação direta com a app.",
    "tutorSeeds": [
     "Como configurar uma app SAML customizada?",
     "Limite de quantas applications são suportadas?"
    ]
   }'::jsonb,
  'Identity Center', 'Security & Compliance', 'medium', 'recall', '["identity-center","application-access"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
