INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-036', 'aws-clf', 'Identity Center exige AWS Organizations?',
  '[{"id":"A","text":"Não, funciona em conta única isolada também"},{"id":"B","text":"Não, mas precisa de Control Tower"},{"id":"C","text":"Apenas para empresas com mais de 100 contas"},{"id":"D","text":"Sim, requer AWS Organizations com all features habilitadas; e por padrão é configurado na management account ou em uma ''delegated admin account''"}]'::jsonb, 'D',
  '{
    "summary": "Identity Center exige AWS Organizations (all features) e geralmente roda na management account ou em uma delegated admin account.",
    "whyCorrect": "Por design, Identity Center se integra com AWS Organizations para descobrir contas e atribuir permission sets — exige ''all features'' habilitado. Pode ser habilitado na management account; recomenda-se delegar via ''delegated administrator'' para uma conta especializada de identidades, isolando da management.",
    "whyWrong": {
     "A": "Em conta única isolada, Identity Center não consegue alcançar outras contas — só faz sentido em Organizations.",
     "B": "Control Tower não é exigência (embora frequentemente venham juntos).",
     "C": "Sem limite mínimo de contas — qualquer Organization."
    },
    "keyConcept": "Identity Center dependency — AWS Organizations (all features)",
    "compareWith": [
     "Identity Center na management vs delegated admin"
    ],
    "realWorldContext": "Best practice: delegated admin para isolar gestão de identidades da management account (que deve ser mínima).",
    "commonMistakes": "Habilitar Identity Center na management e depois lutar para migrar — preferir delegated admin desde o início.",
    "tutorSeeds": [
     "Como configurar delegated administrator para Identity Center?",
     "O que é ''all features'' no Organizations?"
    ]
   }'::jsonb,
  'Identity Center', 'Security & Compliance', 'medium', 'best-practice', '["identity-center","organizations","delegated-admin"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
