INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-038', 'aws-clf', 'No Identity Center, qual a diferença entre ''Identity Center directory'' (próprio) e ''AD Connector / Active Directory'' como identity source?',
  '[{"id":"A","text":"Não há diferença prática"},{"id":"B","text":"Identity Center directory é diretório próprio gerenciado pela AWS; AD Connector conecta a um AD on-premises ou AWS Managed Microsoft AD"},{"id":"C","text":"AD Connector só funciona com Linux"},{"id":"D","text":"Identity Center directory é apenas para usuários gratuitos"}]'::jsonb, 'B',
  '{
    "summary": "Identity Center suporta 3 sources: diretório próprio (Identity Center), AD (Connector ou Managed Microsoft AD), ou external IdP (Okta/Entra/Google).",
    "whyCorrect": "O ''Identity Center directory'' é um diretório gerenciado pela AWS, suficiente para times pequenos sem AD. Já a opção ''Active Directory'' integra com AD existente — via AD Connector (proxy para AD on-prem) ou AWS Managed Microsoft AD (AD gerenciado na AWS). External IdP (Okta etc.) é o terceiro modo, via SAML+SCIM.",
    "whyWrong": {
     "A": "Há diferenças significativas em fonte de verdade, sync, password policies.",
     "C": "AD Connector funciona com qualquer cliente Windows/Linux/etc.",
     "D": "Não há distinção ''paga vs gratuita'' nesse contexto."
    },
    "keyConcept": "Identity Center identity sources — Identity Center directory / AD / External IdP",
    "compareWith": [
     "Identity Center directory vs AD Connector vs external IdP"
    ],
    "realWorldContext": "Empresas com AD legado escolhem AD Connector ou Managed AD; cloud-native escolhem Okta/Entra; startups simples usam Identity Center directory.",
    "commonMistakes": "Tentar trocar identity source depois de muitos usuários — operação delicada que pode quebrar SSO; planejar desde o início.",
    "tutorSeeds": [
     "Como migrar de Identity Center directory para Okta?",
     "Quando preferir AD Connector vs Managed AD?"
    ]
   }'::jsonb,
  'Identity Center', 'Security & Compliance', 'medium', 'recall', '["identity-center","identity-source","active-directory"]'::jsonb, 'ai-draft', 'active', now(), now()
)
