INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-039', 'aws-clf', 'Qual a diferença fundamental entre Amazon Cognito User Pool e Identity Pool?',
  '[{"id":"A","text":"Não há diferença, são sinônimos"},{"id":"B","text":"User Pool é para mobile, Identity Pool é para web"},{"id":"C","text":"User Pool autentica usuários (login/signup, emite JWT tokens); Identity Pool autoriza acesso a recursos AWS (troca um identity token por credenciais AWS temporárias via STS)"},{"id":"D","text":"User Pool é pago, Identity Pool é grátis"}]'::jsonb, 'C',
  '{
    "summary": "User Pool = autenticação (login → JWT). Identity Pool = autorização AWS (JWT → credenciais AWS temporárias).",
    "whyCorrect": "São responsabilidades diferentes que podem ser usadas juntas. User Pool é um diretório de usuários — gerencia signup, signin, MFA, recuperação de senha, e emite JWT (ID token + Access token). Identity Pool (Federated Identities) recebe um token de identidade (do User Pool, Google, Facebook, SAML) e troca por credenciais AWS temporárias via STS, permitindo o cliente chamar APIs AWS diretamente.",
    "whyWrong": {
     "A": "São produtos distintos com APIs diferentes.",
     "B": "Ambos funcionam em qualquer plataforma.",
     "D": "Ambos têm tiers gratuitos e cobrança baseada em MAU/uso."
    },
    "keyConcept": "Cognito — User Pool (authn) vs Identity Pool (authz para AWS)",
    "compareWith": [
     "JWT do User Pool vs Credenciais AWS do Identity Pool",
     "Cognito vs Auth0"
    ],
    "realWorldContext": "App mobile que faz upload S3: User Pool faz signin → JWT; Identity Pool troca JWT por credenciais AWS → SDK chama s3:PutObject direto do device.",
    "commonMistakes": "Achar que User Pool sozinho dá credenciais AWS — não dá; precisa Identity Pool para acessar APIs AWS diretas.",
    "tutorSeeds": [
     "Quando dispensar Identity Pool e usar API Gateway+Lambda?",
     "Quais providers o Identity Pool aceita?"
    ]
   }'::jsonb,
  'Cognito', 'Security & Compliance', 'medium', 'recall', '["cognito","user-pool","identity-pool"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
