INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-040', 'aws-clf', 'Em um Cognito User Pool, qual é a diferença prática entre o ID token e o Access token?',
  '[{"id":"A","text":"Não há diferença, são sinônimos"},{"id":"B","text":"ID token é para mobile, Access token para web"},{"id":"C","text":"ID token expira em 1 dia, Access token nunca expira"},{"id":"D","text":"ID token contém claims sobre a identidade do usuário (email, nome) — para a aplicação saber quem é; Access token autoriza chamadas a recursos protegidos (APIs, endpoints) — para apresentar como bearer"}]'::jsonb, 'D',
  '{
    "summary": "ID token responde ''quem é o user?'' (OIDC). Access token responde ''que recursos pode acessar?'' (OAuth 2.0).",
    "whyCorrect": "Padrão OIDC/OAuth: o ID token é destinado à aplicação cliente — contém claims (sub, email, name) para identificar o usuário, NÃO deve ser enviado a APIs. O Access token (geralmente JWT no Cognito) é destinado a APIs protegidas — apresentado como Authorization: Bearer; identifica scopes/grupos. Refresh token (terceiro) é usado para renovar os dois sem novo login.",
    "whyWrong": {
     "A": "São tokens distintos com propósitos definidos pelo padrão OIDC.",
     "B": "Ambos funcionam em qualquer plataforma.",
     "C": "Ambos têm TTL configurável (default 1h); refresh token vai mais longe."
    },
    "keyConcept": "OIDC tokens — ID (identidade) vs Access (autorização) vs Refresh (renovação)",
    "compareWith": [
     "ID token vs Access token",
     "OIDC vs OAuth 2.0"
    ],
    "realWorldContext": "API Gateway com Cognito authorizer valida Access token; frontend usa ID token para mostrar nome do usuário.",
    "commonMistakes": "Enviar ID token para APIs em vez de Access token — antipattern de OIDC, viola separation of concerns.",
    "tutorSeeds": [
     "Como configurar TTL de cada token?",
     "Como rotacionar tokens com refresh?"
    ]
   }'::jsonb,
  'Cognito', 'Security & Compliance', 'medium', 'recall', '["cognito","jwt","oidc"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
