INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-041', 'aws-clf', 'Uma app mobile usa Cognito Identity Pool com ''unauthenticated identities'' habilitado. O que isso significa para a segurança?',
  '[{"id":"A","text":"Usuários anônimos (sem login) recebem credenciais AWS temporárias com permissões definidas por uma ''unauthenticated IAM role''"},{"id":"B","text":"O Identity Pool não funciona mais"},{"id":"C","text":"Todas as requests são bloqueadas até o login"},{"id":"D","text":"Somente admins podem usar a app"}]'::jsonb, 'A',
  '{
    "summary": "Unauthenticated identities permitem credenciais AWS para usuários anônimos via uma IAM role específica de ''guest'' — útil mas deve ter permissões muito restritas.",
    "whyCorrect": "Quando ativo, qualquer cliente que invoca o Identity Pool sem token recebe credenciais temporárias mapeadas para a ''unauthenticated role''. Boa para casos como ''leitura pública via app'' (read-only no DynamoDB de produtos, por exemplo) — mas exige IAM policy minimalista, pois qualquer um na internet obtém credenciais.",
    "whyWrong": {
     "B": "Continua funcionando — é uma feature.",
     "C": "Justamente o oposto: permite chamadas sem login.",
     "D": "Não tem relação com admins."
    },
    "keyConcept": "Identity Pool — autenticadas e não-autenticadas como roles distintas",
    "compareWith": [
     "Authenticated role vs Unauthenticated role"
    ],
    "realWorldContext": "Apps com ''modo guest'' (Pinterest, Quora antes do login) usam unauthenticated identities para permitir browsing limitado.",
    "commonMistakes": "Atribuir permissões amplas à role unauth — vaza acesso ao mundo. Sempre principle of least privilege.",
    "tutorSeeds": [
     "Como auditar a role unauth do Identity Pool?",
     "Quando desabilitar unauth identities?"
    ]
   }'::jsonb,
  'Cognito', 'Security & Compliance', 'medium', 'best-practice', '["cognito","identity-pool","unauthenticated"]'::jsonb, 'ai-draft', 'active', now(), now()
)
