INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-042', 'aws-clf', 'Quais providers de identidade um Cognito Identity Pool aceita como sources?',
  '[{"id":"A","text":"Apenas Cognito User Pool"},{"id":"B","text":"Cognito User Pool, social (Google/Facebook/Apple/Amazon), OIDC genérico, SAML 2.0, e tokens de desenvolvedor customizados"},{"id":"C","text":"Apenas Google"},{"id":"D","text":"Apenas AWS IAM users"}]'::jsonb, 'B',
  '{
    "summary": "Identity Pool aceita múltiplos identity providers — Cognito User Pool, social, OIDC, SAML, developer authenticated.",
    "whyCorrect": "Identity Pool é desenhado para federar várias fontes de identidade em um único ''pool'' de credenciais AWS. Aceita: (1) Cognito User Pool, (2) Login with Amazon, (3) Facebook, (4) Google, (5) Apple, (6) OIDC genérico, (7) SAML 2.0, (8) ''developer authenticated'' (back-end customizado que verifica login proprietário e chama GetOpenIdTokenForDeveloperIdentity).",
    "whyWrong": {
     "A": "User Pool é uma opção entre várias.",
     "C": "Google é só uma das opções.",
     "D": "IAM users não são providers para Cognito Identity Pool."
    },
    "keyConcept": "Cognito Identity Pool — federation hub multi-provider",
    "compareWith": [
     "Cognito Identity Pool vs Identity Center"
    ],
    "realWorldContext": "Apps consumer com login social + opção de email/senha (User Pool) usam Identity Pool unificando os dois.",
    "commonMistakes": "Confundir ''login with Cognito'' (User Pool) com ''Cognito Identity Pool'' — são camadas distintas.",
    "tutorSeeds": [
     "Como configurar Google como provider?",
     "O que é developer authenticated identity?"
    ]
   }'::jsonb,
  'Cognito', 'Security & Compliance', 'easy', 'recall', '["cognito","identity-pool","providers"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
