INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-043', 'aws-clf', 'Uma feature ''Advanced Security'' do Cognito User Pool inclui:',
  '[{"id":"A","text":"VPN integrada"},{"id":"B","text":"Backup automático para Glacier"},{"id":"C","text":"Detecção de credenciais comprometidas (cruzando senhas com bases de vazamentos) e risk-based adaptive authentication (challenge baseado em risco da sessão)"},{"id":"D","text":"Substituição de IAM"}]'::jsonb, 'C',
  '{
    "summary": "Advanced Security do User Pool oferece compromised credentials check + adaptive authentication baseada em risco.",
    "whyCorrect": "Feature paga do Cognito User Pool. Inclui: (1) Compromised credentials — checa se a senha do user aparece em vazamentos conhecidos (similar ao haveibeenpwned), bloqueando uso; (2) Adaptive authentication — analisa sinais (IP, device, location) para classificar risco da tentativa de login e disparar MFA ou bloqueio.",
    "whyWrong": {
     "A": "Não há VPN no Cognito.",
     "B": "Não é serviço de backup.",
     "D": "Não substitui IAM."
    },
    "keyConcept": "Cognito User Pool Advanced Security — defensive layer contra account takeover",
    "compareWith": [
     "Cognito Advanced Security vs WAF + reCAPTCHA"
    ],
    "realWorldContext": "Apps consumer com risco de ATO (fintechs, marketplaces) habilitam essa feature para mitigar credential stuffing.",
    "commonMistakes": "Imaginar que vem incluso na tier gratuita — é cobrança adicional baseada em MAU.",
    "tutorSeeds": [
     "Como configurar adaptive authentication?",
     "Custo das advanced security features?"
    ]
   }'::jsonb,
  'Cognito', 'Security & Compliance', 'medium', 'scenario', '["cognito","advanced-security","user-pool"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
