INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-044', 'aws-clf', 'Como validar um JWT emitido pelo Cognito User Pool em uma API back-end (sem depender do Cognito a cada request)?',
  '[{"id":"A","text":"Chamar a API admin do Cognito a cada requisição (AdminGetUser)"},{"id":"B","text":"Confiar no token cegamente"},{"id":"C","text":"Apenas Cognito pode validar seus próprios tokens"},{"id":"D","text":"Verificar a assinatura do JWT usando o JWKS (JSON Web Key Set) público do User Pool, validar claims (iss, aud, exp, token_use)"}]'::jsonb, 'D',
  '{
    "summary": "Validar JWT do Cognito = baixar JWKS público, verificar assinatura RS256, checar iss/aud/exp/token_use.",
    "whyCorrect": "Cognito publica JWKS público em ''https://cognito-idp.<region>.amazonaws.com/<userPoolId>/.well-known/jwks.json''. A API backend baixa essa chave pública (com cache), verifica a assinatura RS256 do JWT, e valida claims: ''iss'' bate com o User Pool, ''aud'' (ID token) ou ''client_id'' (Access token) bate com a app, ''exp'' não passou, ''token_use'' é ''id'' ou ''access'' conforme esperado.",
    "whyWrong": {
     "A": "Chamar API admin a cada request mata performance e quota.",
     "B": "Tokens não validados são vetor crítico — sempre verificar assinatura e claims.",
     "C": "JWT é projetado para validação stateless pelo recipient — não precisa Cognito online."
    },
    "keyConcept": "JWT validation — assinatura via JWKS + claims (iss/aud/exp/token_use)",
    "compareWith": [
     "Validação offline (JWKS) vs Online (introspection)"
    ],
    "realWorldContext": "API Gateway Cognito Authorizer faz isso automaticamente; código próprio usa libs como aws-jwt-verify.",
    "commonMistakes": "Esquecer de validar ''token_use'' e aceitar ID token onde só Access token deveria entrar (ou vice-versa).",
    "tutorSeeds": [
     "Como cachear JWKS apropriadamente?",
     "Diferença entre RS256 e HS256 e por que Cognito usa RS256?"
    ]
   }'::jsonb,
  'Cognito', 'Security & Compliance', 'hard', 'best-practice', '["cognito","jwt","jwks","validation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
