INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-045', 'aws-clf', 'Qual a melhor forma de habilitar MFA TOTP (autenticador app) em um Cognito User Pool?',
  '[{"id":"A","text":"Configurar MFA como ''Optional'' ou ''Required'' no User Pool com TOTP (Time-based One-Time Password) e/ou SMS como método"},{"id":"B","text":"MFA não é suportado no Cognito"},{"id":"C","text":"MFA só funciona via email"},{"id":"D","text":"Cognito força MFA por padrão em todas as User Pools"}]'::jsonb, 'A',
  '{
    "summary": "Cognito User Pool suporta MFA TOTP (Google Authenticator) e SMS, configurável como Optional ou Required.",
    "whyCorrect": "Na criação ou edição do User Pool, MFA pode ser: ''Off'', ''Optional'' (user decide), ''Required'' (forçado). Métodos suportados: TOTP (Authenticator apps via QR code) e SMS. Best practice atual: TOTP > SMS (SMS está depreciado por riscos SIM swap). O fluxo gera um secret no setup e o user verifica com o código gerado pelo app.",
    "whyWrong": {
     "B": "MFA é totalmente suportado.",
     "C": "Email não é método MFA suportado no Cognito.",
     "D": "Padrão é ''Off''; precisa configurar manualmente."
    },
    "keyConcept": "Cognito MFA — TOTP (preferido) e SMS, Optional ou Required",
    "compareWith": [
     "TOTP vs SMS — segurança",
     "Cognito MFA vs aplicativo MFA externo"
    ],
    "realWorldContext": "Apps com dados sensíveis (financial, health) tornam MFA Required; consumer apps deixam Optional.",
    "commonMistakes": "Confiar em SMS-only — vulnerável a SIM swap. TOTP é o caminho.",
    "tutorSeeds": [
     "Como funciona o setup TOTP no Cognito hosted UI?",
     "Por que SMS está sendo depreciado?"
    ]
   }'::jsonb,
  'Cognito', 'Security & Compliance', 'easy', 'best-practice', '["cognito","mfa","totp"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
