INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-046', 'aws-clf', 'Uma empresa quer permitir login com SAML 2.0 (ADFS corporativo) em uma app SaaS que usa Cognito User Pool. Como configurar?',
  '[{"id":"A","text":"Substituir o User Pool pelo Identity Center"},{"id":"B","text":"Adicionar o IdP SAML como ''federated identity provider'' no User Pool e configurar atribute mapping para os campos do Cognito"},{"id":"C","text":"Criar um IAM SAML Provider"},{"id":"D","text":"Não é possível usar SAML com Cognito"}]'::jsonb, 'B',
  '{
    "summary": "Cognito User Pool aceita SAML 2.0 e OIDC como federated identity providers — basta cadastrar o IdP no User Pool.",
    "whyCorrect": "No User Pool, adiciona-se um identity provider SAML informando a metadata XML do IdP corporativo. Define-se attribute mapping (NameID → username, email → email, etc.). O hosted UI do Cognito então mostra opção ''Continue with [IdP]'' que redireciona ao ADFS para autenticação, retornando ao Cognito que emite o JWT.",
    "whyWrong": {
     "A": "Substituir muda toda arquitetura; Cognito + SAML resolve sem migrar.",
     "C": "IAM SAML provider é para federar diretamente em IAM (assumir IAM roles), não para o fluxo do Cognito User Pool.",
     "D": "É totalmente possível e bem documentado."
    },
    "keyConcept": "Cognito User Pool federation — SAML e OIDC suportados como IdPs",
    "compareWith": [
     "Cognito SAML vs IAM SAML federation"
    ],
    "realWorldContext": "Apps B2B que precisam aceitar login corporativo dos clientes (cada cliente com seu ADFS) usam esse pattern.",
    "commonMistakes": "Confundir Cognito SAML com IAM SAML federation — Cognito emite JWT para a app, IAM emite credenciais AWS.",
    "tutorSeeds": [
     "Como mapear atributos SAML para Cognito?",
     "Multi-tenancy: como rotear users para o IdP correto?"
    ]
   }'::jsonb,
  'Cognito', 'Security & Compliance', 'medium', 'scenario', '["cognito","saml","federation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
