INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-047', 'aws-clf', 'Um cliente mobile autentica via Cognito User Pool e depois quer fazer upload direto a um S3 bucket usando o SDK. Qual é o fluxo correto?',
  '[{"id":"A","text":"Cliente envia o JWT do User Pool diretamente para S3 como Authorization header"},{"id":"B","text":"Cliente usa IAM user com access keys embedadas"},{"id":"C","text":"Cliente envia o ID token para o Cognito Identity Pool via GetCredentialsForIdentity; Identity Pool troca por credenciais AWS temporárias (STS); SDK usa essas credenciais para chamar s3:PutObject"},{"id":"D","text":"S3 não suporta upload de mobile"}]'::jsonb, 'C',
  '{
    "summary": "Fluxo: User Pool → JWT → Identity Pool → credenciais AWS temporárias → SDK chama S3 direto.",
    "whyCorrect": "S3 não aceita JWT diretamente — sua API exige assinatura SigV4 com credenciais AWS. O Identity Pool é a peça que troca o JWT por credenciais AWS via STS (com a IAM role associada definindo o que o usuário pode fazer no S3). O SDK no mobile usa as credenciais temporárias para chamadas SigV4 normais.",
    "whyWrong": {
     "A": "S3 não autentica via JWT do Cognito — exige credenciais AWS via SigV4.",
     "B": "Access keys embedadas em app móvel = vaza no APK/IPA; antipattern crítico.",
     "D": "Suporta perfeitamente — é o caso de uso clássico do Identity Pool."
    },
    "keyConcept": "Cognito User Pool + Identity Pool — bridge entre OIDC e AWS SigV4",
    "compareWith": [
     "Upload direto via Identity Pool vs Upload via API Gateway+Lambda"
    ],
    "realWorldContext": "Apps de fotos (Instagram-like) usam esse pattern para upload direto sem onerar back-end.",
    "commonMistakes": "Tentar passar o JWT direto para S3 — não funciona, S3 só fala SigV4.",
    "tutorSeeds": [
     "Como restringir IAM role do Identity Pool a um prefixo S3 do próprio user?",
     "Vantagem de upload direto vs proxy via API Gateway?"
    ]
   }'::jsonb,
  'Cognito', 'Security & Compliance', 'hard', 'scenario', '["cognito","identity-pool","s3","mobile"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
