INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-048', 'aws-clf', 'No Cognito Identity Pool, qual feature permite restringir o IAM role atribuído via ''role mapping rules'' baseadas em claims do token (ex: usuários com claim ''department=engineering'' recebem role X, demais role Y)?',
  '[{"id":"A","text":"Token introspection"},{"id":"B","text":"Advanced security"},{"id":"C","text":"STS Federation Token"},{"id":"D","text":"Rules-based role selection (role mapping rules)"}]'::jsonb, 'D',
  '{
    "summary": "Identity Pool ''role mapping rules'' permitem selecionar IAM role baseado em claims do token JWT.",
    "whyCorrect": "Na configuração do Identity Pool, em ''Authentication providers'', você pode definir ''rules'' que avaliam claims do token (ex: ''custom:department = engineering'' → role A; senão role B). É o mecanismo para entregar permissões distintas conforme atributos do usuário, sem múltiplos Identity Pools.",
    "whyWrong": {
     "A": "Token introspection é um endpoint OAuth — não a feature.",
     "B": "Advanced security é do User Pool, não roteamento de role.",
     "C": "GetFederationToken é STS API distinta, não relacionada ao role mapping."
    },
    "keyConcept": "Cognito Identity Pool role mapping rules — claims → role selection",
    "compareWith": [
     "Role mapping rules vs Multiple Identity Pools"
    ],
    "realWorldContext": "Apps com tiers (free/pro/enterprise) entregam permissões S3 diferentes via role mapping.",
    "commonMistakes": "Criar múltiplos Identity Pools quando role mapping rules resolve com uma única configuração.",
    "tutorSeeds": [
     "Como configurar rule com múltiplas condições?",
     "Performance impact de muitas rules?"
    ]
   }'::jsonb,
  'Cognito', 'Security & Compliance', 'hard', 'scenario', '["cognito","identity-pool","role-mapping"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
