INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-049', 'aws-clf', 'Qual a diferença entre AWS managed key, Customer managed key e AWS owned key no KMS?',
  '[{"id":"A","text":"AWS owned key é gerenciada pela AWS, invisível e gratuita; AWS managed key (aws/\u003cservice\u003e) é gerenciada pela AWS mas visível na sua conta e usada por integração de serviço; Customer managed key é totalmente sua — você cria, configura policy, rotation, e paga $1/mês por chave"},{"id":"B","text":"Não há diferença prática"},{"id":"C","text":"Customer managed key é gratuita"},{"id":"D","text":"AWS owned key é a única que pode ser exportada"}]'::jsonb, 'A',
  '{
    "summary": "Owned (invisível/grátis) < Managed (visível, gerenciada pela AWS, grátis a chave) < Customer Managed (controle total, $1/mês).",
    "whyCorrect": "AWS owned key: usada internamente por serviços AWS, não aparece na sua conta, gratuita, sem controle. AWS managed key (prefixo ''aws/...'', ex: aws/s3): visível na sua conta, mas a AWS gerencia rotation/policy, grátis a chave (cobra requests). Customer managed key (CMK): você cria, define key policy, escolhe rotation, $1/mês por chave + requests. Mais controle, mais responsabilidade.",
    "whyWrong": {
     "B": "Há diferenças significativas em controle, custo e visibilidade.",
     "C": "Customer managed key cobra $1/mês por chave.",
     "D": "Nenhuma key KMS pode ser exportada (a material da chave fica no HSM)."
    },
    "keyConcept": "KMS key types — owned < managed < customer-managed (controle crescente)",
    "compareWith": [
     "AWS owned vs managed vs customer-managed"
    ],
    "realWorldContext": "Workloads sensíveis preferem customer managed para controlar key policy, rotation explícita e auditoria CloudTrail completa.",
    "commonMistakes": "Achar que managed key permite custom key policy — não permite; quem precisa de controle vai para customer managed.",
    "tutorSeeds": [
     "Quando vale o $1/mês da customer managed?",
     "Como saber se um serviço está usando uma owned key vs managed?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'medium', 'recall', '["kms","key-types"]'::jsonb, 'ai-draft', 'active', now(), now()
)
