INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-050', 'aws-clf', 'Sobre rotação de chaves KMS, qual afirmação é correta?',
  '[{"id":"A","text":"Todas as chaves KMS rotacionam diariamente"},{"id":"B","text":"AWS managed keys rotacionam automaticamente (~anualmente); Customer managed keys têm rotation opcional configurável (anual por padrão quando habilitada); chaves assimétricas e imported key material NÃO suportam rotation automática"},{"id":"C","text":"Rotation só é possível com CloudHSM"},{"id":"D","text":"Customer managed keys NÃO suportam rotation"}]'::jsonb, 'B',
  '{
    "summary": "AWS managed: rotation automática anual. Customer managed: opcional (default 1 ano, configurável). Chaves assimétricas e imported: SEM rotation auto.",
    "whyCorrect": "AWS managed keys passaram a rodar automaticamente uma vez por ano (anteriormente 3 anos). Customer managed keys têm rotation OPCIONAL — quando ativada, default é 1 ano (configurável entre 90 dias e 7 anos). Chaves assimétricas (RSA/ECC) e chaves com key material importado NÃO suportam rotation automática — precisa rotacionar manualmente.",
    "whyWrong": {
     "A": "Não é diária; é anual (managed) ou configurada (customer).",
     "C": "CloudHSM é serviço separado para FIPS 140-3 Level 3 — não é requisito para rotation.",
     "D": "Customer managed keys SUPORTAM rotation (opcional)."
    },
    "keyConcept": "Key rotation — automática (anual) para AWS managed e symmetric customer; manual para assimétricas/importadas",
    "compareWith": [
     "Rotation automática vs manual",
     "Symmetric vs asymmetric key rotation"
    ],
    "realWorldContext": "Compliance PCI DSS exige rotation periódica de chaves — KMS rotation automática facilita evidência.",
    "commonMistakes": "Habilitar rotation em chave assimétrica e esperar funcionar — não funciona, precisa criar nova chave manualmente.",
    "tutorSeeds": [
     "O que acontece com dados criptografados quando a chave roda?",
     "Como ver a key version atual?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'medium', 'recall', '["kms","rotation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
