INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-051', 'aws-clf', 'Qual a relação entre key policy e IAM policy no KMS?',
  '[{"id":"A","text":"IAM policy sempre prevalece sobre key policy"},{"id":"B","text":"Key policy é opcional"},{"id":"C","text":"Key policy é OBRIGATÓRIA em toda KMS key — sem permissão na key policy, IAM policy sozinha não basta (com exceção limitada: a ''default key policy'' delega para IAM)"},{"id":"D","text":"Não existe key policy no KMS"}]'::jsonb, 'C',
  '{
    "summary": "Key policy é mandatória; é a principal fonte de autorização da chave. IAM policy sozinha só funciona se a key policy delegar para IAM (via Allow IAM principals).",
    "whyCorrect": "Toda KMS key tem uma key policy obrigatória — não há chave sem policy. O ''default key policy'' contém uma declaração ''Enable IAM User Permissions'' que delega à IAM (permite IAM policies da conta). Se essa declaração for removida ou nunca incluída, IAM policies sozinhas não dão acesso — precisa Allow explícito na key policy. Cross-account é sempre via key policy + IAM policy do caller.",
    "whyWrong": {
     "A": "Não — em KMS, sem permissão na key policy, IAM allow não basta (exceto via ''Enable IAM User Permissions'' que delega).",
     "B": "Key policy é mandatória e criada automaticamente.",
     "D": "Existe e é central no modelo KMS."
    },
    "keyConcept": "Key policy mandatória; IAM via delegation explícita (''Enable IAM User Permissions'')",
    "compareWith": [
     "Key policy vs IAM policy",
     "Default key policy vs custom"
    ],
    "realWorldContext": "Quando engenheiros removem o ''Enable IAM'' por engano, ninguém mais consegue usar a chave — recovery exige operação de suporte AWS.",
    "commonMistakes": "Deletar a declaração ''Enable IAM User Permissions'' sem entender o impacto — pode bloquear até o root user.",
    "tutorSeeds": [
     "Como recuperar uma chave bloqueada por key policy?",
     "Diferença entre default key policy e custom?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'hard', 'recall', '["kms","key-policy","iam-policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
