INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-053', 'aws-clf', 'O que é envelope encryption no KMS?',
  '[{"id":"A","text":"Padrão onde os dados são criptografados com uma Data Encryption Key (DEK) gerada pelo KMS via GenerateDataKey; a DEK em si é criptografada pela KMS key e armazenada junto aos dados; para decriptar, o KMS decripta a DEK e o cliente decripta os dados localmente"},{"id":"B","text":"Padrão de envio em envelopes físicos"},{"id":"C","text":"API que envia objetos S3 inteiros para o KMS"},{"id":"D","text":"Substituto do TLS"}]'::jsonb, 'A',
  '{
    "summary": "Envelope encryption = DEK criptografa dados localmente; KMS criptografa a DEK. Escala para arquivos grandes sem trafegar dados via KMS.",
    "whyCorrect": "GenerateDataKey retorna: (1) DEK em plaintext (para criptografar localmente), (2) DEK criptografada (encryptedDataKey, para guardar com os dados). Cliente: usa DEK plaintext para criptografar arquivo, descarta a plaintext da memória, armazena encryptedDataKey junto. Para decriptar: chama Decrypt(encryptedDataKey) → KMS retorna DEK plaintext → cliente decripta o arquivo. Beneficia escala (arquivos grandes não vão até o KMS) e limita exposição da master key.",
    "whyWrong": {
     "B": "Não tem nada com envelopes físicos.",
     "C": "S3 nunca envia objetos inteiros para KMS — usa envelope.",
     "D": "Não substitui TLS — são camadas distintas (transport vs at-rest)."
    },
    "keyConcept": "Envelope encryption — DEK local + KMS encrypted DEK",
    "compareWith": [
     "GenerateDataKey vs Encrypt direto",
     "Envelope encryption vs Direct encryption"
    ],
    "realWorldContext": "S3 SSE-KMS, EBS, RDS — todos usam envelope encryption por debaixo dos panos.",
    "commonMistakes": "Tentar criptografar objetos grandes diretamente com KMS Encrypt API — limite de 4 KB por chamada; envelope é a forma correta.",
    "tutorSeeds": [
     "Limite de 4 KB do Encrypt API?",
     "Como o SDK cliente implementa envelope automaticamente?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'medium', 'recall', '["kms","envelope-encryption","data-key"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
