INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-054', 'aws-clf', 'Para que serve uma KMS multi-Region key?',
  '[{"id":"A","text":"Permite usar a chave fora da AWS"},{"id":"B","text":"Permite replicar a mesma chave (com mesmo key material e key ID) em múltiplas regiões, permitindo decriptar em uma região o que foi criptografado em outra — útil para DR e workloads multi-region"},{"id":"C","text":"Substitui a necessidade de IAM"},{"id":"D","text":"Permite chaves de mais de 256 bits"}]'::jsonb, 'B',
  '{
    "summary": "Multi-Region keys: replicas com mesmo key material em outras regiões — ciphertext criado em uma região decripta em outra.",
    "whyCorrect": "Multi-Region keys têm key ID compartilhado entre primary key (us-east-1) e replicas (eu-west-1, sa-east-1, etc.). Cada replica tem sua própria key policy/grants/aliases, mas o key material é o mesmo. Ciphertext criado em qualquer região pode ser decriptado em outra — eliminando o problema de ''região onde a chave está''. Útil para DR, replicação cross-region S3/DynamoDB, multi-region apps.",
    "whyWrong": {
     "A": "KMS keys nunca saem da AWS (HSM-bound). Multi-Region é só dentro da AWS.",
     "C": "Não substitui IAM.",
     "D": "Tamanho da chave é independente do multi-Region."
    },
    "keyConcept": "Multi-Region keys — replicas com mesmo key material entre regiões",
    "compareWith": [
     "Multi-Region keys vs Single-Region keys + cross-region copy"
    ],
    "realWorldContext": "S3 Cross-Region Replication com SSE-KMS exige multi-Region keys para o bucket destino conseguir decriptar.",
    "commonMistakes": "Esperar que uma single-region key seja acessível em outra região — não é; tem que ser explícita multi-Region ou copiar dados decriptados.",
    "tutorSeeds": [
     "Como replicar uma key existente como multi-Region?",
     "Custo de multi-Region key replicas?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'medium', 'scenario', '["kms","multi-region","disaster-recovery"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
