INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-055', 'aws-clf', 'O que é um KMS grant e quando preferir usá-lo em vez de modificar a key policy?',
  '[{"id":"A","text":"Grant substitui IAM completamente"},{"id":"B","text":"Grant é o mesmo que key policy"},{"id":"C","text":"Grant é uma autorização temporária e programática para um principal usar uma KMS key — útil para conceder acesso a serviços AWS (como EBS criando volumes encriptados) sem modificar a key policy global; suporta constraints e expiração"},{"id":"D","text":"Grant só funciona em chaves assimétricas"}]'::jsonb, 'C',
  '{
    "summary": "KMS Grant é autorização granular e temporária para uma key — preferível quando você precisa de Allow sutil e dinâmico sem editar a key policy.",
    "whyCorrect": "Grant é uma alternativa à key policy para delegar uso a um principal específico (geralmente AWS service ou role) com escopo restrito: operações permitidas (Encrypt, Decrypt, GenerateDataKey), constraints (encryption context obrigatório), e expiração opcional. Útil quando, por exemplo, EBS precisa criptografar um volume on-the-fly em nome do user — o serviço cria um grant temporário, usa, retorna. Não polui a key policy com Allows transientes.",
    "whyWrong": {
     "A": "Não substitui IAM nem key policy; é complementar.",
     "B": "Não é o mesmo — grants são autônomos e podem ter expiração; key policy é estática.",
     "D": "Funciona em symmetric e asymmetric keys."
    },
    "keyConcept": "KMS Grant — autorização programática granular e temporária",
    "compareWith": [
     "Grant vs Key policy statement",
     "Grant vs IAM policy"
    ],
    "realWorldContext": "EBS, Lambda environment variables encryption, RDS — todos usam grants internamente para encriptar em nome do user.",
    "commonMistakes": "Acumular grants antigos não usados — afetam quota da chave; revisar e revogar regularmente.",
    "tutorSeeds": [
     "Diferença entre CreateGrant e atualizar key policy?",
     "O que é EncryptionContext em um grant?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'hard', 'scenario', '["kms","grants"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
