INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-056', 'aws-clf', 'Uma empresa quer permitir que principals da conta B usem uma KMS key da conta A. Qual é o setup correto?',
  '[{"id":"A","text":"Apenas key policy permitindo conta B"},{"id":"B","text":"Tornar a chave pública"},{"id":"C","text":"KMS não suporta cross-account"},{"id":"D","text":"Key policy na conta A permitindo principal da conta B (Allow em kms:Decrypt etc.) + IAM policy na conta B no principal-origem permitindo kms:Decrypt na ARN da chave"}]'::jsonb, 'D',
  '{
    "summary": "Cross-account KMS = key policy na conta A (Allow conta B) + IAM policy na conta B no caller. Os dois lados.",
    "whyCorrect": "Como em qualquer cross-account AWS, é necessário Allow em ambos os lados: (1) key policy na conta A deve listar o principal da conta B (pode ser '':root'' para a conta inteira) com Allow nas operações necessárias; (2) IAM policy do principal na conta B precisa de Allow para essas mesmas operações na ARN da KMS key. Sem qualquer um dos dois, falha.",
    "whyWrong": {
     "A": "Sem identity policy na conta B, o principal ainda precisa de Allow IAM para chamar kms:* na ARN remota.",
     "B": "Não é assim que KMS funciona — não há flag ''public''.",
     "C": "KMS suporta cross-account perfeitamente."
    },
    "keyConcept": "Cross-account KMS — key policy (conta-dona) + IAM policy (conta-caller)",
    "compareWith": [
     "Cross-account S3 vs Cross-account KMS"
    ],
    "realWorldContext": "Data lakes com S3 SSE-KMS cross-account exigem essa configuração para a conta consumidora decriptar objetos.",
    "commonMistakes": "Configurar só a key policy e esquecer da IAM policy do lado caller — falha silenciosamente com AccessDenied.",
    "tutorSeeds": [
     "Como debugar Access Denied em cross-account KMS?",
     "Pode-se usar grants em vez de key policy para cross-account?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'hard', 'scenario', '["kms","cross-account","key-policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
