INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-057', 'aws-clf', 'Qual API KMS é usada para criptografar um pequeno payload (até 4 KB) diretamente, sem envelope encryption?',
  '[{"id":"A","text":"Encrypt"},{"id":"B","text":"GenerateDataKey"},{"id":"C","text":"Sign"},{"id":"D","text":"Verify"}]'::jsonb, 'A',
  '{
    "summary": "Encrypt API criptografa payloads até 4 KB diretamente; acima disso, usar envelope encryption via GenerateDataKey.",
    "whyCorrect": "kms:Encrypt aceita até 4 KB de plaintext e retorna o ciphertext correspondente. Para volumes maiores, o padrão é GenerateDataKey + criptografia local com a DEK. Encrypt é usado em casos como criptografar senhas curtas, tokens, secrets pequenos.",
    "whyWrong": {
     "B": "GenerateDataKey gera uma DEK para envelope encryption, não criptografa payload diretamente.",
     "C": "Sign é para chaves assimétricas — gera assinatura digital, não criptografia.",
     "D": "Verify valida assinatura digital."
    },
    "keyConcept": "KMS Encrypt — payload pequeno (<=4 KB); GenerateDataKey — envelope para grande",
    "compareWith": [
     "Encrypt vs GenerateDataKey",
     "4 KB limit"
    ],
    "realWorldContext": "Secrets Manager usa Encrypt direto quando o secret é pequeno; serviços que lidam com arquivos maiores usam envelope.",
    "commonMistakes": "Tentar Encrypt em payload maior que 4 KB — falha. Sempre envelope para arquivos.",
    "tutorSeeds": [
     "Como o SDK cliente abstrai essa escolha?",
     "Por que o limite de 4 KB?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'medium', 'recall', '["kms","encrypt-api","payload-limit"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
