INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-058', 'aws-clf', 'Sobre encryption context no KMS, qual afirmação está correta?',
  '[{"id":"A","text":"Encryption context é o conteúdo cifrado"},{"id":"B","text":"Encryption context é um map de key-value passado em Encrypt/Decrypt — não é segredo, mas é incluído em logs CloudTrail e DEVE bater no Decrypt (é AAD — Additional Authenticated Data)"},{"id":"C","text":"Encryption context é a chave KMS"},{"id":"D","text":"Encryption context é opcional e ignorado"}]'::jsonb, 'B',
  '{
    "summary": "Encryption context = AAD (Additional Authenticated Data). Mapas de contexto que devem casar no Decrypt; aparecem em CloudTrail; melhoram auditoria e segurança.",
    "whyCorrect": "Encryption context é um map opcional (ex: {''tenant'': ''acme'', ''purpose'': ''invoice''}). NÃO é criptografado nem secreto, mas: (1) é autenticado — Decrypt falha se context não casar; (2) aparece em logs CloudTrail, melhorando rastreabilidade; (3) pode ser usado em key policy conditions (kms:EncryptionContext:tenant=acme). Boa prática em workloads multi-tenant.",
    "whyWrong": {
     "A": "Não é o conteúdo cifrado.",
     "C": "Não é a chave; é metadata associada.",
     "D": "Não é ignorado — é autenticado e logado."
    },
    "keyConcept": "Encryption context — AAD não-secreto, autenticado, logado",
    "compareWith": [
     "Encryption context vs Tags",
     "AAD em criptografia simétrica AEAD"
    ],
    "realWorldContext": "S3 SSE-KMS usa o bucket/key automaticamente como encryption context — falha cross-bucket protection.",
    "commonMistakes": "Esperar que encryption context cifre algo — apenas autentica.",
    "tutorSeeds": [
     "Como usar encryption context em key policy conditions?",
     "Diferença entre AAD e dado cifrado?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'hard', 'recall', '["kms","encryption-context","aad"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
