INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-059', 'aws-clf', 'Um engenheiro recebe erro ''ThrottlingException'' em chamadas KMS muito frequentes. Qual o limite default e como mitigá-lo?',
  '[{"id":"A","text":"Não há limites no KMS"},{"id":"B","text":"Limite é 1 chamada por hora"},{"id":"C","text":"Default é ~5.500–10.000 req/s por região (varia por API/região); mitigar via caching de DEKs no SDK (envelope encryption reduz chamadas), distribuir carga entre múltiplas keys, ou solicitar aumento de quota via Service Quotas"},{"id":"D","text":"Aumentar TLS cipher suite"}]'::jsonb, 'C',
  '{
    "summary": "KMS tem quotas por região por API. Mitigação: cache de DEKs, múltiplas keys, ou aumento via Service Quotas.",
    "whyCorrect": "KMS tem cryptographic operations quota (Encrypt/Decrypt/GenerateDataKey/etc.) por região — varia: tipicamente ~5.500-10.000 req/s em us-east-1 para chaves simétricas. Quando bate o teto, retorna ThrottlingException. Mitigação correta: (a) envelope encryption — cacheia DEK e usa localmente, reduzindo chamadas; (b) distribuir entre múltiplas KMS keys; (c) solicitar aumento via Service Quotas.",
    "whyWrong": {
     "A": "Há limites; ignorar causa throttling.",
     "B": "Limite muito maior que isso.",
     "D": "TLS cipher suite é irrelevante para throttling de API KMS."
    },
    "keyConcept": "KMS quotas e mitigation — caching + sharding",
    "compareWith": [
     "KMS quotas vs S3 quotas",
     "Envelope encryption como otimização"
    ],
    "realWorldContext": "Pipelines de dados massivos (Spark, EMR) atingem facilmente o limite — caching de DEK por particão é prática padrão.",
    "commonMistakes": "Tentar fazer Decrypt por linha de dataset — esgota quota; usar envelope com DEK cacheada por chunk.",
    "tutorSeeds": [
     "Como o AWS Encryption SDK cacheia DEKs?",
     "Como pedir aumento de quota?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'hard', 'troubleshoot', '["kms","throttling","quotas"]'::jsonb, 'ai-draft', 'active', now(), now()
)
