INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-060', 'aws-clf', 'Qual é a diferença entre KMS keys e CloudHSM?',
  '[{"id":"A","text":"Não há diferença"},{"id":"B","text":"CloudHSM é mais barato sempre"},{"id":"C","text":"KMS é só para EBS"},{"id":"D","text":"KMS é multi-tenant managed (FIPS 140-3 Level 3 com HSM dedicado opcional); CloudHSM é single-tenant — você controla um HSM dedicado, com acesso direto via PKCS#11/JCE/OpenSSL, ideal para compliance que exige HSM dedicado exclusivo"}]'::jsonb, 'D',
  '{
    "summary": "KMS = managed multi-tenant (com HSMs validados); CloudHSM = dedicado single-tenant que você administra (PKCS#11/JCE/OpenSSL).",
    "whyCorrect": "KMS é serviço gerenciado multi-tenant — AWS opera os HSMs (validados FIPS 140-2/3) e você usa API simples. CloudHSM entrega um cluster HSM dedicado APENAS para sua conta — você administra (usuários HSM, partições), e apps acessam via PKCS#11, JCE, OpenSSL. Mais controle, mais custo (~$1.45/h por HSM), exigido em compliance específicos como certos requisitos da PCI HSM, FIPS 140-3 Level 3 com tenant único.",
    "whyWrong": {
     "A": "Diferenças significativas em tenancy, integração e custo.",
     "B": "CloudHSM é muito mais caro que KMS na maioria dos casos.",
     "C": "KMS é genérico — usado por S3, RDS, EBS, Lambda, Secrets Manager, etc."
    },
    "keyConcept": "KMS (managed multi-tenant) vs CloudHSM (dedicated single-tenant)",
    "compareWith": [
     "KMS vs CloudHSM — controle, custo, tenancy"
    ],
    "realWorldContext": "Bancos com requisito de ''HSM exclusivo'' por regulação escolhem CloudHSM; maioria das empresas usa KMS.",
    "commonMistakes": "Escolher CloudHSM por overengineering quando KMS atende — custo desnecessário e overhead operacional.",
    "tutorSeeds": [
     "Pode-se integrar KMS com CloudHSM (custom key store)?",
     "Quando regulação realmente exige HSM dedicado?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'medium', 'recall', '["kms","cloudhsm","comparison"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
