INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-061', 'aws-clf', 'Qual o tempo mínimo de espera para deletar uma KMS key, e por que existe esse waiting period?',
  '[{"id":"A","text":"Entre 7 e 30 dias (configurável, default 30) — para permitir recuperação caso dados criptografados com a chave sejam descobertos depois (uma vez deletada, dados são irrecuperáveis)"},{"id":"B","text":"Imediato"},{"id":"C","text":"1 ano"},{"id":"D","text":"Apenas com aprovação da AWS"}]'::jsonb, 'A',
  '{
    "summary": "Schedule key deletion: 7-30 dias de espera (default 30). Permite cancelar caso descubra dados ainda dependentes da chave.",
    "whyCorrect": "Chamar ScheduleKeyDeletion não deleta imediatamente — agenda para após um waiting period configurável (7-30 dias, default 30). Durante esse período, a chave fica em estado ''Pending Deletion'' e não pode criptografar/decriptar. Pode-se cancelar via CancelKeyDeletion. Esse design existe porque, uma vez deletada, qualquer dado criptografado com ela fica permanentemente inacessível.",
    "whyWrong": {
     "B": "Não é imediata — sempre tem waiting period.",
     "C": "Máximo é 30 dias.",
     "D": "Não exige aprovação AWS."
    },
    "keyConcept": "KMS scheduled deletion — 7-30 dias para safety",
    "compareWith": [
     "ScheduleKeyDeletion vs DisableKey",
     "Pending Deletion state vs Disabled state"
    ],
    "realWorldContext": "Engenheiros que removem keys ''limpando recursos'' às vezes descobrem dependências depois — o waiting period salva vidas.",
    "commonMistakes": "Esperar deletar imediato — não dá; durante pendência a chave não funciona mais para crypto operations.",
    "tutorSeeds": [
     "Como auditar dependências antes de schedule deletion?",
     "DisableKey vs ScheduleKeyDeletion?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'medium', 'recall', '["kms","deletion","lifecycle"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
