INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-062', 'aws-clf', 'Sobre KMS asymmetric keys, qual afirmação é correta?',
  '[{"id":"A","text":"Asymmetric keys são gratuitas"},{"id":"B","text":"Suportam pares RSA (2048/3072/4096) e ECC (NIST P-256/P-384/P-521 e SECG secp256k1); usados para sign/verify e encrypt/decrypt (RSA); rotation automática NÃO é suportada"},{"id":"C","text":"Asymmetric keys rotacionam automaticamente como as symmetric"},{"id":"D","text":"Asymmetric keys são deprecadas"}]'::jsonb, 'B',
  '{
    "summary": "KMS asymmetric: RSA + ECC suportados; sign/verify e encrypt/decrypt (RSA); SEM rotation automática.",
    "whyCorrect": "KMS asymmetric keys suportam: RSA 2048/3072/4096 e ECC P-256/P-384/P-521/SECG_P256K1. Casos de uso: digital signatures (sign/verify), key exchange, encrypt/decrypt para casos de troca com partes externas (RSA). Diferente das symmetric, NÃO suportam rotation automática — você precisa criar uma nova key e rotacionar manualmente, atualizando consumidores.",
    "whyWrong": {
     "A": "Não são gratuitas — mesmo preço ($1/mês cada).",
     "C": "Não suportam rotation automática.",
     "D": "Não são deprecadas — são recurso ativo do KMS."
    },
    "keyConcept": "KMS asymmetric keys — RSA/ECC, sign/verify ou encrypt, sem auto-rotation",
    "compareWith": [
     "KMS symmetric vs asymmetric — casos de uso"
    ],
    "realWorldContext": "JWT signing com KMS, document signing, integração com sistemas externos que esperam chave pública.",
    "commonMistakes": "Tentar usar asymmetric key para volume de criptografia massivo — performance e custo são muito piores que symmetric envelope encryption.",
    "tutorSeeds": [
     "Quando preferir asymmetric vs symmetric KMS key?",
     "Como exportar a public key?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'hard', 'recall', '["kms","asymmetric","rsa","ecc"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
