INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-063', 'aws-clf', 'Uma empresa quer usar uma key material gerada por ela própria (não pela AWS) em uma KMS key. Que feature suporta isso?',
  '[{"id":"A","text":"É proibido"},{"id":"B","text":"Só via CloudHSM"},{"id":"C","text":"Imported key material (BYOK — Bring Your Own Key) — você gera a key material on-prem/HSM, importa no KMS, e usa via APIs normais; rotation automática NÃO é suportada para imported"},{"id":"D","text":"Multi-Region keys"}]'::jsonb, 'C',
  '{
    "summary": "Imported key material (BYOK) permite trazer key material externo para uma KMS key. Sem rotation automática.",
    "whyCorrect": "Você gera key material externamente (HSM corporativo, processo manual com PRNG validado), e importa no KMS via duas etapas: GetParametersForImport (recebe wrapping public key) → ImportKeyMaterial (envia material wrapped). A chave funciona como qualquer KMS key. Você pode setar expiração da key material. Rotation automática NÃO é suportada — precisa importar nova material manualmente.",
    "whyWrong": {
     "A": "Não é proibido — é feature oficial chamada BYOK.",
     "B": "Funciona em KMS regular, não só CloudHSM.",
     "D": "Multi-Region é outra feature ortogonal."
    },
    "keyConcept": "KMS Imported key material (BYOK) — compliance ou key origin externa",
    "compareWith": [
     "BYOK vs KMS-generated keys",
     "BYOK rotation manual vs auto"
    ],
    "realWorldContext": "Bancos/compliances que exigem ''key generated outside cloud provider'' usam BYOK.",
    "commonMistakes": "Esperar rotation automática em imported key — não funciona.",
    "tutorSeeds": [
     "Como gerar key material para BYOK corretamente?",
     "Trade-offs de BYOK vs AWS-generated?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'hard', 'scenario', '["kms","byok","imported-key"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
