INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-064', 'aws-clf', 'Qual o efeito de adicionar ''kms:ViaService'' como condition em uma key policy?',
  '[{"id":"A","text":"Habilita acesso a todos os serviços"},{"id":"B","text":"Faz a chave funcionar entre contas"},{"id":"C","text":"Habilita auto-rotation"},{"id":"D","text":"Restringe o uso da chave a chamadas feitas em nome do user POR um serviço AWS específico (ex: kms:ViaService = s3.us-east-1.amazonaws.com) — útil para garantir que a chave só sirva para S3, e não chamada direta pela API"}]'::jsonb, 'D',
  '{
    "summary": "kms:ViaService restringe uso da key a chamadas feitas por um serviço AWS específico (no fluxo on-behalf-of).",
    "whyCorrect": "kms:ViaService é uma condition key que avalia o serviço AWS que está fazendo a chamada KMS em nome do usuário (ex: S3 chamando kms:GenerateDataKey ao colocar objeto SSE-KMS). Com Condition: {''StringEquals'': {''kms:ViaService'': ''s3.us-east-1.amazonaws.com''}}, a chave só funciona via S3 — chamadas diretas via API KMS pelo mesmo principal falham. Limita o blast radius.",
    "whyWrong": {
     "A": "Faz justamente o oposto — restringe.",
     "B": "Não influencia cross-account diretamente.",
     "C": "Não muda rotation."
    },
    "keyConcept": "kms:ViaService — restringe via service que faz a chamada on-behalf-of",
    "compareWith": [
     "kms:ViaService vs aws:SourceService",
     "Limit blast radius via condition keys"
    ],
    "realWorldContext": "Padrão para chaves dedicadas: ''esta chave é exclusiva para S3 sse-kms''; auditoria fica clara.",
    "commonMistakes": "Esquecer de incluir todos os services necessários no StringEquals — pode quebrar workflows quando o serviço esperado muda.",
    "tutorSeeds": [
     "Quais services suportam aparecer em kms:ViaService?",
     "Diferença de kms:ViaService e kms:CallerAccount?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'hard', 'scenario', '["kms","key-policy","via-service"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
