INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-065', 'aws-clf', 'Uma equipe descobre que uma KMS customer managed key foi disabled (não scheduled for deletion). Qual o impacto?',
  '[{"id":"A","text":"Operações criptográficas (Encrypt/Decrypt/GenerateDataKey) falham; dados criptografados com a chave ficam temporariamente inacessíveis ATÉ a chave ser re-enabled — reversível"},{"id":"B","text":"A chave continua funcionando normalmente"},{"id":"C","text":"Os dados criptografados são perdidos para sempre"},{"id":"D","text":"A chave é deletada imediatamente"}]'::jsonb, 'A',
  '{
    "summary": "DisableKey é reversível. Operações cripto falham até EnableKey ser chamado. Dados não são perdidos.",
    "whyCorrect": "Disable key coloca a chave em estado ''Disabled'' — operações de Encrypt/Decrypt/GenerateDataKey retornam DisabledException. Re-enable (kms:EnableKey) torna tudo operacional de novo. Diferente de ScheduleKeyDeletion (que apaga após 7-30 dias), Disable é totalmente reversível e útil para ''pausar'' uma chave (ex: durante incident response).",
    "whyWrong": {
     "B": "Operações cripto falham — chave disabled bloqueia.",
     "C": "Dados não são perdidos; basta re-enable.",
     "D": "Disable não deleta."
    },
    "keyConcept": "DisableKey — pausa reversível, sem perda de dados",
    "compareWith": [
     "DisableKey vs ScheduleKeyDeletion"
    ],
    "realWorldContext": "Em incident response: ''desabilita a chave suspeita'' para conter, investiga, depois habilita ou rotaciona.",
    "commonMistakes": "Confundir Disable com Delete — Disable é seguro/reversível, Delete inicia waiting period.",
    "tutorSeeds": [
     "Quando preferir Disable em vez de Delete?",
     "Pode-se disable uma AWS managed key?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'medium', 'scenario', '["kms","disable-key","incident-response"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
