INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-066', 'aws-clf', 'O que são aliases no KMS e qual seu valor prático?',
  '[{"id":"A","text":"Aliases são chaves duplicadas"},{"id":"B","text":"Aliases (ex: ''alias/prod-billing-key'') são nomes amigáveis para chaves; permitem referenciar a chave por nome estável mesmo quando o key ID muda, e facilitam blue/green key rotation manual (mover alias entre keys)"},{"id":"C","text":"Aliases substituem permissões"},{"id":"D","text":"Aliases são tags"}]'::jsonb, 'B',
  '{
    "summary": "Alias = nome amigável para a key. Útil para legibilidade e rotação manual blue/green (apontar alias para a nova key).",
    "whyCorrect": "Toda KMS key tem um key ID UUID. Um alias é um nome humano-legível (''alias/prod-billing-key'') ligado a uma key. Aplicações podem referenciar a key pelo alias, e em rotação manual de chaves (ex: assimétrica) você cria nova key e move o alias — apps continuam funcionando com o mesmo nome lógico. Aliases são por região (não cross-region exceto multi-Region).",
    "whyWrong": {
     "A": "Não são duplicatas; são ponteiros.",
     "C": "Não influenciam permissões diretamente (embora possam aparecer em condition keys).",
     "D": "Não são tags — são namespace separado."
    },
    "keyConcept": "KMS aliases — abstração de nomes para keys; útil em rotação manual",
    "compareWith": [
     "Alias vs Key ID vs ARN"
    ],
    "realWorldContext": "Apps de produção sempre referenciam alias, nunca key ID — facilita ops sem mudar código.",
    "commonMistakes": "Hardcodar key IDs no código — quando precisa rotacionar, força redeploy. Alias resolve.",
    "tutorSeeds": [
     "Como movimentar alias entre keys?",
     "Aliases podem ser usados em condition keys?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'easy', 'recall', '["kms","alias"]'::jsonb, 'ai-draft', 'active', now(), now()
)
