INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-067', 'aws-clf', 'Em S3 SSE-KMS, quando se faz GetObject em larga escala, pode aparecer custo alto de KMS. Qual feature reduz drasticamente as chamadas KMS por objeto?',
  '[{"id":"A","text":"Desabilitar SSE-KMS"},{"id":"B","text":"Usar SSE-C"},{"id":"C","text":"S3 Bucket Keys — gera uma DEK por bucket (não por objeto), reduzindo chamadas KMS em ~99% e o custo correspondente"},{"id":"D","text":"Mover dados para Glacier"}]'::jsonb, 'C',
  '{
    "summary": "S3 Bucket Keys reutiliza uma DEK por bucket por curto período — corta chamadas KMS em ~99% e custos KMS associados.",
    "whyCorrect": "Sem Bucket Keys, cada PUT/GET com SSE-KMS chama KMS para Encrypt/Decrypt da DEK do objeto. Com Bucket Keys habilitado no bucket, S3 cacheia uma DEK do bucket por janela de tempo curta e a usa para múltiplos objetos — caindo de N chamadas KMS para ~1. Redução típica >99% nos custos KMS e melhora latência. Feature opt-in por bucket.",
    "whyWrong": {
     "A": "Desabilitar SSE-KMS perde a criptografia gerenciada — não é solução.",
     "B": "SSE-C move a gestão para o cliente (overhead), não otimiza.",
     "D": "Glacier é solução de storage tiering, não de custo KMS."
    },
    "keyConcept": "S3 Bucket Keys — reduz chamadas KMS para SSE-KMS em larga escala",
    "compareWith": [
     "SSE-KMS sem bucket key vs com bucket key"
    ],
    "realWorldContext": "Data lakes com milhões de objetos SSE-KMS reduzem custos KMS em milhares de dólares/mês habilitando bucket keys.",
    "commonMistakes": "Não habilitar bucket keys em buckets novos — feature deveria ser default mental.",
    "tutorSeeds": [
     "Como habilitar bucket key em buckets existentes?",
     "Impacto em performance e em auditoria CloudTrail?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'medium', 'scenario', '["kms","s3","bucket-keys"]'::jsonb, 'ai-draft', 'active', now(), now()
)
