INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-068', 'aws-clf', 'Sobre KMS custom key store, qual afirmação é correta?',
  '[{"id":"A","text":"É o mesmo que multi-Region key"},{"id":"B","text":"É uma cópia de backup"},{"id":"C","text":"É uma API obsoleta"},{"id":"D","text":"Permite que as KMS keys tenham key material armazenado em um cluster CloudHSM que você controla (ou em uma external key store), combinando a interface familiar do KMS com a tenancy dedicada do HSM"}]'::jsonb, 'D',
  '{
    "summary": "Custom Key Store conecta KMS a CloudHSM cluster próprio (ou external key store) — interface KMS, key material em HSM dedicado.",
    "whyCorrect": "Custom Key Store (CKS) permite criar KMS keys cujo key material reside em um cluster CloudHSM seu (dedicated tenancy) ou em um External Key Manager via External Key Store (XKS). Apps usam APIs KMS normais — internamente, KMS delega operações cripto ao HSM. Caso de uso: compliance que exige HSM dedicado mas você quer ergonomia do KMS.",
    "whyWrong": {
     "A": "Não é o mesmo que multi-Region key.",
     "B": "Não é backup.",
     "C": "Não é obsoleta — é feature ativa."
    },
    "keyConcept": "Custom Key Store — KMS interface + CloudHSM/external HSM por trás",
    "compareWith": [
     "Default KMS keystore vs Custom Key Store (CloudHSM) vs External Key Store"
    ],
    "realWorldContext": "Empresas com requisito de soberania de chaves (chave nunca sai do data center próprio) usam External Key Store.",
    "commonMistakes": "Esperar performance idêntica ao KMS regular — CKS tem latência maior e quotas reduzidas.",
    "tutorSeeds": [
     "Diferença entre CloudHSM-backed CKS e External Key Store?",
     "Quando External Key Store faz sentido?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'hard', 'recall', '["kms","custom-key-store","cloudhsm"]'::jsonb, 'ai-draft', 'active', now(), now()
)
