INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-069', 'aws-clf', 'Qual evento CloudTrail é gerado quando alguém chama kms:Decrypt em uma chave?',
  '[{"id":"A","text":"Um evento ''Decrypt'' (data event ou management event dependendo da configuração) contendo o caller identity, key ARN, encryption context (quando presente) e resultado — usado para auditoria de uso de chaves"},{"id":"B","text":"Nenhum — chamadas KMS não geram logs CloudTrail"},{"id":"C","text":"Apenas em chaves customer-managed"},{"id":"D","text":"Apenas em multi-Region keys"}]'::jsonb, 'A',
  '{
    "summary": "Toda chamada KMS gera evento CloudTrail (Decrypt, Encrypt, GenerateDataKey, etc.) com caller, key ARN, encryption context e sucesso/falha.",
    "whyCorrect": "KMS API calls são logged no CloudTrail por padrão (management events). Cada Encrypt/Decrypt/GenerateDataKey gera um evento contendo: principal caller, key ARN, encryption context (em texto claro — daí ser ferramenta de auditoria), resultado (Success/AccessDenied), source IP. É a forma canônica de auditar quem usou qual chave para o quê.",
    "whyWrong": {
     "B": "Calls são logged.",
     "C": "Vale para todas as keys.",
     "D": "Não restrito a multi-Region."
    },
    "keyConcept": "KMS + CloudTrail — auditoria nativa de uso de chaves",
    "compareWith": [
     "CloudTrail management events vs data events"
    ],
    "realWorldContext": "Investigações de incidente analisam logs CloudTrail para entender quais chaves foram usadas em qual horário por qual identidade.",
    "commonMistakes": "Assumir que encryption context é cifrado — está em texto claro no log; usar com cautela em dados sensíveis no próprio context.",
    "tutorSeeds": [
     "Como filtrar eventos KMS no CloudTrail Lake?",
     "Custo de armazenar todos os eventos KMS?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'easy', 'recall', '["kms","cloudtrail","audit"]'::jsonb, 'ai-draft', 'active', now(), now()
)
