INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-070', 'aws-clf', 'Uma instância EC2 com role ''AppRole'' tenta decriptar um objeto SSE-KMS no S3 e recebe ''AccessDenied''. O AppRole tem ''s3:GetObject'' allow. Qual é a causa mais provável?',
  '[{"id":"A","text":"S3 está fora do ar"},{"id":"B","text":"Falta permissão kms:Decrypt no AppRole (identity policy) OU a key policy não autoriza o AppRole/uso via S3"},{"id":"C","text":"A região está errada"},{"id":"D","text":"Falta MFA"}]'::jsonb, 'B',
  '{
    "summary": "SSE-KMS exige permissão NO KMS (kms:Decrypt no role + key policy permitindo) ALÉM da permissão S3. AccessDenied SSE-KMS é caso clássico.",
    "whyCorrect": "Para ler objeto SSE-KMS, o caller precisa de DUAS permissões: (1) s3:GetObject na ARN do objeto, (2) kms:Decrypt na chave que criptografou o objeto — concedida via identity policy do role E permitida pela key policy da KMS key. Falta de qualquer uma resulta em AccessDenied. É a causa mais comum de troubleshooting SSE-KMS.",
    "whyWrong": {
     "A": "S3 raramente está fora; AccessDenied é específico.",
     "C": "Região errada gera erro diferente (NoSuchBucket ou conexão).",
     "D": "MFA pode ser, mas não a causa mais provável; primeiro checar KMS perms."
    },
    "keyConcept": "SSE-KMS — duas camadas de permissão (s3 + kms)",
    "compareWith": [
     "SSE-S3 (1 perm) vs SSE-KMS (2 perms)"
    ],
    "realWorldContext": "Erro recorrente quando se migra de SSE-S3 para SSE-KMS sem atualizar IAM/key policies dos consumidores.",
    "commonMistakes": "Só dar s3:GetObject e esquecer kms:Decrypt — AccessDenied vem de KMS, mas a app só vê ''falhou ao ler S3''.",
    "tutorSeeds": [
     "Como CloudTrail ajuda a identificar qual permissão falhou?",
     "Como dar kms:Decrypt para todos os consumidores de um bucket?"
    ]
   }'::jsonb,
  'KMS', 'Security & Compliance', 'medium', 'troubleshoot', '["kms","s3","sse-kms","troubleshoot"]'::jsonb, 'ai-draft', 'active', now(), now()
)
