INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-071', 'aws-clf', 'Quais opções de SSE (Server-Side Encryption) o S3 oferece, e qual a diferença chave?',
  '[{"id":"A","text":"Apenas SSE-S3"},{"id":"B","text":"S3 não oferece SSE"},{"id":"C","text":"SSE-S3 (AES-256 com chave gerenciada pela S3, default), SSE-KMS (KMS key gerenciada por você ou aws/s3), DSSE-KMS (dual-layer KMS, dois layers cripto), SSE-C (chave fornecida pelo cliente em cada request — S3 não armazena)"},{"id":"D","text":"Apenas SSE-C"}]'::jsonb, 'C',
  '{
    "summary": "SSE-S3 (S3 gerencia chave), SSE-KMS (KMS gerencia), DSSE-KMS (dois layers via KMS), SSE-C (cliente envia chave em cada request).",
    "whyCorrect": "S3 oferece quatro modos SSE: (1) SSE-S3 — AES-256, S3 gerencia keys (transparente, default em buckets novos); (2) SSE-KMS — KMS gerencia (CMK ou aws/s3); permite auditoria CloudTrail por chave, key policy fina; (3) DSSE-KMS — dual-layer KMS, dois layers de criptografia para compliance específica (TOP SECRET-ish); (4) SSE-C — cliente passa a chave em cada PUT/GET via header; S3 NUNCA armazena nem loga a chave. Cliente também pode fazer Client-Side encryption (CSE) antes de upload.",
    "whyWrong": {
     "A": "São 4 variantes SSE, não só uma.",
     "B": "S3 sim oferece SSE.",
     "D": "SSE-C é uma das opções, não a única."
    },
    "keyConcept": "S3 SSE variants — quem gerencia a chave (S3 / KMS / Cliente)",
    "compareWith": [
     "SSE-S3 vs SSE-KMS vs SSE-C vs CSE"
    ],
    "realWorldContext": "Default desde 2023: SSE-S3 automático em todo bucket; produção sensível usa SSE-KMS com CMK + bucket key.",
    "commonMistakes": "Achar que SSE-C é mais seguro porque ''cliente controla'' — também significa que se perder a chave, dados são irrecuperáveis; S3 não tem cópia.",
    "tutorSeeds": [
     "Quando exigir DSSE-KMS?",
     "SSE-C vs Client-Side encryption — diferença?"
    ]
   }'::jsonb,
  'Encryption', 'Security & Compliance', 'medium', 'recall', '["s3","sse","encryption"]'::jsonb, 'ai-draft', 'active', now(), now()
)
