INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-072', 'aws-clf', 'Uma empresa quer criptografar uma instância RDS de produção existente (não criptografada). Qual é o caminho correto?',
  '[{"id":"A","text":"Apenas habilitar ''encryption'' na console da instância existente"},{"id":"B","text":"Usar AWS Snowball"},{"id":"C","text":"Migrar para EC2 self-managed"},{"id":"D","text":"Tirar snapshot da instância → copy snapshot WITH encryption (escolhendo KMS key) → restore desse snapshot como NOVA instância encriptada → cutover"}]'::jsonb, 'D',
  '{
    "summary": "RDS encryption só na criação. Para criptografar existente: snapshot → copy-with-encryption → restore → cutover. Não há toggle in-place.",
    "whyCorrect": "RDS encryption (at-rest) só pode ser configurada NA CRIAÇÃO da instância. Para uma instância não criptografada existente: (1) tirar snapshot manual; (2) copy snapshot escolhendo KMS key (snapshot copy permite mudar de unencrypted para encrypted); (3) restore esse snapshot encrypted como uma nova instância; (4) update app para apontar para a nova endpoint e descontinuar a antiga. Multi-AZ failover NÃO converte unencrypted→encrypted.",
    "whyWrong": {
     "A": "Não há toggle in-place no RDS para encryption.",
     "B": "Snowball é para data transfer físico, não relacionado.",
     "C": "Migrar para EC2 é overkill e perde valor gerenciado do RDS."
    },
    "keyConcept": "RDS encryption — só na criação; existing requires snapshot-copy-restore",
    "compareWith": [
     "RDS encryption at-rest vs EBS encryption",
     "Snapshot copy with encryption"
    ],
    "realWorldContext": "Migração comum em auditorias de compliance; downtime depende do tamanho do snapshot e da janela de cutover.",
    "commonMistakes": "Esperar opção de toggle in-place — não existe; precisa o procedimento snapshot-copy-restore.",
    "tutorSeeds": [
     "Como minimizar downtime no cutover?",
     "Aurora se comporta diferente?"
    ]
   }'::jsonb,
  'Encryption', 'Security & Compliance', 'hard', 'scenario', '["rds","encryption","snapshot"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
