INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-074', 'aws-clf', 'Qual a diferença entre AWS Certificate Manager (ACM) público e ACM Private CA?',
  '[{"id":"A","text":"Não há diferença"},{"id":"B","text":"ACM público emite certificados TLS gratuitos confiáveis publicamente (validados via DNS/email), usados em ALB/CloudFront/API Gateway. ACM Private CA é uma autoridade certificadora privada que emite certificados confiados apenas dentro da sua organização (mTLS, service-to-service, microservices), com custo por CA/mês + por certificado"},{"id":"C","text":"ACM Private CA é gratuito"},{"id":"D","text":"ACM público só funciona em us-east-1"}]'::jsonb, 'B',
  '{
    "summary": "ACM público = certs TLS publicamente confiáveis, grátis, para domínios. ACM Private CA = autoridade certificadora privada, pago, para uso interno/mTLS.",
    "whyCorrect": "ACM público: emite certificados X.509 confiados pelos browsers (validation via DNS ou email do dono do domínio); gratuitos quando integrados a ALB, CloudFront, API Gateway, Cognito; renovação automática. ACM Private CA: você opera sua própria autoridade certificadora privada — emite certificados para uso interno (service mesh, mTLS, IoT devices) que só são confiados por quem instala a CA root; cobra ~$400/mês por CA + custo por certificado.",
    "whyWrong": {
     "A": "Diferenças profundas de propósito, custo e confiança.",
     "C": "Private CA é pago.",
     "D": "ACM público funciona em todas as regiões (com nota: CloudFront exige cert em us-east-1)."
    },
    "keyConcept": "ACM público (free, public trust) vs ACM Private CA (paid, private trust)",
    "compareWith": [
     "ACM público vs Private CA",
     "Public CA vs Private CA in PKI"
    ],
    "realWorldContext": "Service mesh com mTLS (App Mesh) frequentemente usa ACM Private CA para emitir certs por workload.",
    "commonMistakes": "Tentar usar ACM público para mTLS service-to-service — não viável porque domínio interno não é validável publicamente.",
    "tutorSeeds": [
     "Quando vale a pena Private CA vs gerenciar OpenSSL próprio?",
     "Como integra ACM Private CA com EKS?"
    ]
   }'::jsonb,
  'Encryption', 'Security & Compliance', 'medium', 'recall', '["acm","private-ca","tls"]'::jsonb, 'ai-draft', 'active', now(), now()
)
