INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-075', 'aws-clf', 'Em um ALB, como forçar que apenas conexões TLS 1.2 ou superior sejam aceitas?',
  '[{"id":"A","text":"Não é configurável"},{"id":"B","text":"Adicionar uma WAF rule"},{"id":"C","text":"Selecionar uma security policy do ALB que exija TLS 1.2+ (ex: ELBSecurityPolicy-TLS13-1-2-2021-06) — security policy define versões TLS e cipher suites aceitas"},{"id":"D","text":"Modificar a chave ACM"}]'::jsonb, 'C',
  '{
    "summary": "Security policy do ALB define versões TLS e ciphers — escolher uma TLS 1.2+ proíbe versões antigas.",
    "whyCorrect": "ALB (e CloudFront, NLB) tem o conceito de ''security policy'' — um pacote pré-definido pela AWS que combina versões TLS suportadas e cipher suites. Para forçar TLS 1.2+, escolhe-se policies como ''ELBSecurityPolicy-TLS13-1-2-2021-06'' (TLS 1.2 e 1.3 com ciphers modernos). Policies legacy (''ELBSecurityPolicy-2016-08'') aceitam TLS 1.0/1.1.",
    "whyWrong": {
     "A": "É totalmente configurável.",
     "B": "WAF inspeciona HTTP camada 7, não negocia TLS.",
     "D": "ACM cert tem chave separada da política TLS."
    },
    "keyConcept": "ALB security policy — versão TLS + cipher suites",
    "compareWith": [
     "Security policy ALB vs CloudFront",
     "TLS 1.2 vs 1.3"
    ],
    "realWorldContext": "PCI DSS exige TLS 1.2+ obrigatório desde 2018 — security policy é o mecanismo de evidência.",
    "commonMistakes": "Manter security policy default antiga em ALBs novos — alguns presets ainda permitem TLS 1.0/1.1.",
    "tutorSeeds": [
     "Qual a diferença entre TLS 1.3 e 1.2?",
     "Como auditar security policy via Config?"
    ]
   }'::jsonb,
  'Encryption', 'Security & Compliance', 'medium', 'best-practice', '["alb","tls","security-policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
