INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-076', 'aws-clf', 'Qual a diferença prática entre AWS Secrets Manager e Parameter Store (SSM) SecureString para armazenar credenciais (ex: senha de RDS)?',
  '[{"id":"A","text":"São idênticos"},{"id":"B","text":"Parameter Store não suporta criptografia"},{"id":"C","text":"Secrets Manager é gratuito"},{"id":"D","text":"Secrets Manager tem rotation built-in (via Lambda), versionamento robusto, replicação cross-region nativa, custa ~$0.40/secret/mês + $0.05/10k API calls. Parameter Store SecureString é mais barato (StandardTier gratuito até 10k params, Advanced ~$0.05/param/mês), mas rotation/versioning é manual via código próprio. Secrets Manager para secrets críticos com rotation; Parameter Store para configs e secrets simples."}]'::jsonb, 'D',
  '{
    "summary": "Secrets Manager: rotation built-in, mais features, $0.40/secret/mês. Parameter Store SecureString: barato/grátis, sem rotation built-in.",
    "whyCorrect": "Decisão baseada em features vs custo: Secrets Manager — rotation automatizada via Lambda (integrada com RDS/Aurora/DocumentDB/Redshift), cross-region replication, fine-grained resource policy, $0.40/secret/mês. Parameter Store SecureString — standard tier gratuito, advanced tier (>4KB ou >10k params ou higher throughput) cobra $0.05/param/mês, NÃO tem rotation built-in. Quando precisar rotation de DB credentials, Secrets Manager paga sozinho.",
    "whyWrong": {
     "A": "Há diferenças significativas em rotation, custo, replicação.",
     "B": "Parameter Store SecureString usa KMS — é criptografado.",
     "C": "Secrets Manager cobra por secret + chamadas."
    },
    "keyConcept": "Secrets Manager (rotation + features) vs Parameter Store (cheap + simples)",
    "compareWith": [
     "Secrets Manager vs Parameter Store",
     "SecureString tier standard vs advanced"
    ],
    "realWorldContext": "DB credentials de produção → Secrets Manager (rotation automática); config flags e API tokens menos críticos → Parameter Store.",
    "commonMistakes": "Pagar Secrets Manager para tudo (até configs estáveis) — Parameter Store standard resolve a maioria dos casos por zero custo.",
    "tutorSeeds": [
     "Como configurar rotation no Secrets Manager para RDS?",
     "Quando vale Advanced tier do Parameter Store?"
    ]
   }'::jsonb,
  'Encryption', 'Security & Compliance', 'medium', 'recall', '["secrets-manager","parameter-store","comparison"]'::jsonb, 'ai-draft', 'active', now(), now()
)
