INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-077', 'aws-clf', 'Como o Secrets Manager realiza rotation automática de senha de RDS sem causar downtime?',
  '[{"id":"A","text":"Usa uma Lambda function de rotation com 4 steps (createSecret, setSecret, testSecret, finishSecret) — fluxo padrão: gera nova senha, atualiza usuário no RDS, testa nova conexão, e só então promove para AWSCURRENT; suporta padrão ''single user'' ou ''two users alternating'' para zero downtime"},{"id":"B","text":"Não tem rotation automática"},{"id":"C","text":"Reboot do RDS"},{"id":"D","text":"Restaura snapshot"}]'::jsonb, 'A',
  '{
    "summary": "Rotation via Lambda em 4 steps (createSecret/setSecret/testSecret/finishSecret); padrão two-users alternating evita downtime.",
    "whyCorrect": "Secrets Manager registra a Lambda de rotation com 4 fases: (1) createSecret — gera nova senha como AWSPENDING; (2) setSecret — atualiza o user no RDS; (3) testSecret — valida conexão; (4) finishSecret — move AWSPENDING para AWSCURRENT. Templates suportam ''single user'' (rotação simples) ou ''two-users alternating'' (alterna entre dois IAM/DB users — ideal para zero downtime). Apps usam o secret name; SDK pega AWSCURRENT mais recente.",
    "whyWrong": {
     "B": "Existe sim rotation automática.",
     "C": "Reboot não rotaciona credenciais.",
     "D": "Restaurar snapshot é restore, não rotation."
    },
    "keyConcept": "Secrets Manager rotation — Lambda em 4 steps; staging labels AWSCURRENT/PENDING/PREVIOUS",
    "compareWith": [
     "Single user vs Two users alternating"
    ],
    "realWorldContext": "RDS Multi-AZ + Secrets Manager rotation com two-users mode = rotação sem disruption.",
    "commonMistakes": "Apps que cachear secret eternamente — quando rotação acontece, app continua com senha antiga; precisa cache TTL ou listener de mudança.",
    "tutorSeeds": [
     "Como apps escolhem entre AWSCURRENT e AWSPENDING?",
     "Como customizar a Lambda de rotation?"
    ]
   }'::jsonb,
  'Encryption', 'Security & Compliance', 'hard', 'scenario', '["secrets-manager","rotation","rds"]'::jsonb, 'ai-draft', 'active', now(), now()
)
