INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-078', 'aws-clf', 'Sobre mTLS (mutual TLS) no API Gateway, qual afirmação é correta?',
  '[{"id":"A","text":"API Gateway não suporta mTLS"},{"id":"B","text":"API Gateway (regional e custom domain HTTP/REST) suporta mTLS — você configura um truststore no S3 contendo CAs confiáveis; clientes apresentam certificate X.509; API Gateway valida contra o truststore antes de processar a request; útil para B2B e IoT"},{"id":"C","text":"mTLS só funciona em ALB"},{"id":"D","text":"mTLS é o mesmo que TLS 1.3"}]'::jsonb, 'B',
  '{
    "summary": "API Gateway suporta mTLS via truststore (S3 com CA bundle); clientes apresentam X.509; útil para B2B/IoT.",
    "whyCorrect": "mTLS é suportado em REST API e HTTP API (regional + custom domain). Configura-se um truststore — bundle PEM com CAs confiáveis armazenado em S3 + versão. API Gateway exige que o cliente apresente um certificate X.509 assinado por uma das CAs; valida antes de processar. Casos de uso: APIs B2B (parceiros têm cert emitido pela sua Private CA), IoT devices (cada device um cert).",
    "whyWrong": {
     "A": "Suporta — desde 2020.",
     "C": "ALB também suporta, mas não exclui API Gateway.",
     "D": "mTLS é mutual authentication; TLS 1.3 é versão do protocolo."
    },
    "keyConcept": "mTLS no API Gateway — truststore em S3 + cert client X.509",
    "compareWith": [
     "mTLS API Gateway vs mTLS ALB",
     "TLS server-only vs mutual"
    ],
    "realWorldContext": "Open Banking (PSD2) e IoT em larga escala usam mTLS como autenticação primária dos clients.",
    "commonMistakes": "Atualizar truststore esperando efeito imediato — precisa update do version no API Gateway para recarregar.",
    "tutorSeeds": [
     "Como rotacionar CAs no truststore sem downtime?",
     "Diferença entre mTLS no API Gateway e Lambda authorizer?"
    ]
   }'::jsonb,
  'Encryption', 'Security & Compliance', 'hard', 'scenario', '["api-gateway","mtls","x509"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
