INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-079', 'aws-clf', 'Em Amazon Aurora, qual afirmação sobre criptografia está correta?',
  '[{"id":"A","text":"Aurora não suporta criptografia at-rest"},{"id":"B","text":"Aurora criptografa por padrão em todas as criações sem ser configurável"},{"id":"C","text":"Aurora cluster pode ser encriptado at-rest (KMS) apenas na criação; logs, backups, snapshots e replicas herdam a configuração; TLS in-transit é suportado e pode ser forçado via parameter group (require_secure_transport = ON)"},{"id":"D","text":"Aurora não suporta TLS"}]'::jsonb, 'C',
  '{
    "summary": "Aurora at-rest encryption só na criação; logs/backups/snapshots herdam. TLS in-transit configurável + forçável via parameter group.",
    "whyCorrect": "Aurora segue o padrão RDS: at-rest encryption configurada na criação do cluster (KMS key obrigatória), aplica-se a storage do cluster, automated backups, snapshots, logs, e read replicas. Para mudar de unencrypted para encrypted, usa-se snapshot → copy with encryption → restore. TLS in-transit usa o cert default do RDS; pode ser FORÇADO via parameter group setando require_secure_transport=ON (MySQL) ou rds.force_ssl=1 (PostgreSQL).",
    "whyWrong": {
     "A": "Suporta — feature padrão.",
     "B": "Pode escolher unencrypted (não recomendado).",
     "D": "Suporta TLS — bem documentado."
    },
    "keyConcept": "Aurora encryption — at-rest na criação + TLS forçável via parameter group",
    "compareWith": [
     "Aurora vs RDS encryption (mesma mecânica)"
    ],
    "realWorldContext": "Compliance exige TLS e at-rest — Aurora atende; parameter group force_ssl é evidência canônica.",
    "commonMistakes": "Confiar que TLS está habilitado mas não FORÇADO — cliente sem SSL ainda consegue conectar; force via parameter group resolve.",
    "tutorSeeds": [
     "Como rotacionar o cert TLS do RDS/Aurora?",
     "Como auditar via Config se require_secure_transport está ON?"
    ]
   }'::jsonb,
  'Encryption', 'Security & Compliance', 'medium', 'best-practice', '["aurora","encryption","tls"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
