INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v4-080', 'aws-clf', 'Uma equipe precisa armazenar uma chave de API de terceiros (Stripe secret key) para ser usada por uma Lambda. Qual é a melhor prática?',
  '[{"id":"A","text":"Hardcodar no código fonte"},{"id":"B","text":"Enviar por email para todos os engineers"},{"id":"C","text":"Commitar em um arquivo .env no Git"},{"id":"D","text":"Salvar no Secrets Manager (ou Parameter Store SecureString se rotation não é necessária), conceder permissão de leitura à execution role da Lambda, e ler em runtime (com cache) — NUNCA em env vars não-encriptadas nem em código"}]'::jsonb, 'D',
  '{
    "summary": "Best practice: secret em Secrets Manager (ou Parameter Store SecureString) + IAM permission para a Lambda execution role + cache em runtime.",
    "whyCorrect": "Padrão correto: armazenar em Secrets Manager (se precisar rotation) ou Parameter Store SecureString (mais barato, sem rotation). A execution role da Lambda recebe Allow para secretsmanager:GetSecretValue (ou ssm:GetParameter + kms:Decrypt). No handler, a Lambda lê em cold start, faz cache em memória, e usa para chamar Stripe. Nunca commitar no código nem deixar em env var em plaintext.",
    "whyWrong": {
     "A": "Hardcodar viola toda boa prática — vaza no repo, snapshot, logs.",
     "B": "Email é canal inseguro e não-auditável.",
     "C": ".env no Git é antipattern crítico — uma vez no Git, considere vazado para sempre."
    },
    "keyConcept": "Secrets handling — Secrets Manager/Parameter Store + IAM role + cache",
    "compareWith": [
     "Secrets Manager vs Parameter Store para esse caso"
    ],
    "realWorldContext": "Lambdas usam Lambda Extension do Secrets Manager para cache automático e reduzir API calls.",
    "commonMistakes": "Setar secret em Lambda environment variable mesmo encrypted — variáveis aparecem em descrição da função (acessível a quem tem ler:GetFunction); secret manager é o caminho.",
    "tutorSeeds": [
     "Como usar o Lambda Extension de Secrets Manager?",
     "Trade-off entre cache curto vs longo no Lambda?"
    ]
   }'::jsonb,
  'Encryption', 'Security & Compliance', 'easy', 'best-practice', '["secrets-manager","lambda","best-practice"]'::jsonb, 'ai-draft', 'active', now(), now()
)
