INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-001', 'aws-clf', 'Uma empresa quer detectar comportamento anômalo em sua conta AWS — instâncias EC2 minerando criptomoeda, credenciais IAM sendo usadas de IPs incomuns e exfiltração de dados via DNS. Qual serviço AWS, totalmente gerenciado, analisa CloudTrail events, VPC Flow Logs e DNS logs continuamente para gerar findings de ameaça?',
  '[{"id":"A","text":"Amazon GuardDuty"},{"id":"B","text":"AWS Security Hub"},{"id":"C","text":"Amazon Macie"},{"id":"D","text":"Amazon Inspector"}]'::jsonb, 'A',
  '{
    "summary": "GuardDuty é o serviço de detecção de ameaças que analisa CloudTrail, VPC Flow Logs e DNS logs nativamente.",
    "whyCorrect": "Amazon GuardDuty consome três fontes de dados sem custo extra de coleta — CloudTrail management/data events, VPC Flow Logs e DNS query logs — e usa machine learning + threat intelligence para gerar findings (CryptoCurrency:EC2/BitcoinTool.B, UnauthorizedAccess:IAMUser/AnomalousBehavior, Backdoor:EC2/DNSDataExfiltration etc.). É habilitado por região, sem agente, e o cliente não precisa armazenar/processar os logs ele mesmo.",
    "whyWrong": {
     "B": "Security Hub agrega findings de múltiplos serviços (incluindo o próprio GuardDuty) e aplica controles de standards (CIS, PCI, AFSBP) — não gera findings de ameaça por análise de logs.",
     "C": "Macie descobre dados sensíveis (PII/PHI/PCI) em buckets S3 — não analisa CloudTrail nem detecta cryptomining.",
     "D": "Inspector faz scan de vulnerabilidades (CVEs) em EC2/ECR/Lambda — não detecta atividade anômala em tempo real."
    },
    "keyConcept": "GuardDuty — threat detection contínua sobre CloudTrail + VPC Flow Logs + DNS logs",
    "compareWith": [
     "GuardDuty vs Security Hub",
     "GuardDuty vs Inspector"
    ],
    "realWorldContext": "Habilitar GuardDuty é uma das primeiras ações de SecOps em qualquer conta AWS — custo proporcional ao volume de eventos analisados.",
    "commonMistakes": "Pensar que GuardDuty precisa que o cliente entregue os logs — ele consome direto, sem custo de ingestão.",
    "tutorSeeds": [
     "Quais tipos de findings o GuardDuty gera?",
     "Como o GuardDuty se integra ao Security Hub?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["guardduty","threat-detection","cloudtrail","vpc-flow-logs"]'::jsonb, 'ai-draft', 'active', now(), now()
)
