INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-002', 'aws-clf', 'Uma organização tem 25 contas em AWS Organizations. O time de SecOps quer agregar todos os findings do GuardDuty em uma única conta de segurança para análise centralizada. Qual é o método recomendado pela AWS?',
  '[{"id":"A","text":"Habilitar GuardDuty manualmente em cada conta e exportar findings via SNS para um Lambda agregador"},{"id":"B","text":"Designar uma conta como GuardDuty delegated administrator via Organizations e habilitar auto-enable para contas-membro"},{"id":"C","text":"Replicar logs de CloudTrail e VPC Flow Logs de todas as contas para a conta de segurança e rodar GuardDuty apenas lá"},{"id":"D","text":"Usar Security Hub apenas — ele detecta ameaças por todas as contas sem precisar GuardDuty individual"}]'::jsonb, 'B',
  '{
    "summary": "GuardDuty multi-account usa delegated administrator do Organizations com auto-enable.",
    "whyCorrect": "A AWS recomenda delegar uma conta-membro como GuardDuty delegated administrator via AWS Organizations. Essa conta passa a habilitar/visualizar GuardDuty em todas as contas-membro automaticamente (auto-enable para contas existentes e novas), recebendo findings centralizados. É o padrão multi-account oficial.",
    "whyWrong": {
     "A": "Funciona mas é frágil — cada conta nova exige passos manuais, SNS+Lambda virou plumbing customizada que duplica o que a feature delegated admin já entrega nativamente.",
     "C": "GuardDuty é por região por conta — copiar logs não é o modelo de operação e perderia contexto de identidade/contas.",
     "D": "Security Hub agrega findings; quem gera findings de ameaça é o GuardDuty. Sem GuardDuty em cada conta, não há detecção."
    },
    "keyConcept": "Delegated administrator — padrão de operação multi-account para serviços de segurança",
    "compareWith": [
     "GuardDuty delegated admin vs invitation model"
    ],
    "realWorldContext": "Padrão usado por Control Tower e arquiteturas Landing Zone — conta Audit/Security é delegated admin de GuardDuty, Security Hub, Config, Macie, Inspector.",
    "commonMistakes": "Habilitar manualmente em cada conta e esquecer das contas novas criadas via Account Factory.",
    "tutorSeeds": [
     "Quais serviços de segurança suportam delegated admin?",
     "Como funciona auto-enable em organizações?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["guardduty","organizations","delegated-admin","multi-account"]'::jsonb, 'ai-draft', 'active', now(), now()
)
