INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-003', 'aws-clf', 'Qual feature do GuardDuty detecta especificamente malware em volumes EBS anexados a EC2 ou ECS Fargate suspeitos?',
  '[{"id":"A","text":"GuardDuty S3 Protection"},{"id":"B","text":"GuardDuty EKS Protection"},{"id":"C","text":"GuardDuty Malware Protection"},{"id":"D","text":"GuardDuty RDS Protection"}]'::jsonb, 'C',
  '{
    "summary": "Malware Protection escaneia volumes EBS de instâncias suspeitas em busca de malware.",
    "whyCorrect": "GuardDuty Malware Protection é uma feature complementar que, ao receber um finding de comportamento suspeito de EC2/ECS Fargate, faz snapshot do volume EBS e escaneia em busca de malware (trojans, mineradores, rootkits) sem agente na instância. É um add-on com custo extra.",
    "whyWrong": {
     "A": "S3 Protection analisa CloudTrail data events de S3 para detectar comportamento anômalo em buckets (download em massa, descoberta).",
     "B": "EKS Protection analisa audit logs do plano de controle Kubernetes para detectar comprometimento de cluster.",
     "D": "RDS Protection (lançado 2023) detecta tentativas suspeitas de login em RDS — não escaneia conteúdo."
    },
    "keyConcept": "GuardDuty Malware Protection — scan agentless de EBS via snapshot",
    "compareWith": [
     "Malware Protection vs Inspector (CVEs)"
    ],
    "realWorldContext": "Útil em pipelines de incident response — quando GuardDuty levanta finding de cryptojacking, automação dispara scan de malware.",
    "commonMistakes": "Confundir Malware Protection com Inspector — Inspector procura vulnerabilidades (CVEs), Malware Protection procura malware ativo.",
    "tutorSeeds": [
     "Qual a diferença entre vulnerability scan e malware scan?",
     "GuardDuty Malware Protection precisa agente?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["guardduty","malware-protection","ebs"]'::jsonb, 'ai-draft', 'active', now(), now()
)
