INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-004', 'aws-clf', 'Um auditor pediu para a empresa demonstrar conformidade com o CIS AWS Foundations Benchmark, com checks automatizados e dashboard de score. Qual serviço entrega isso nativamente?',
  '[{"id":"A","text":"AWS Config sozinho, criando rules customizadas para cada controle CIS"},{"id":"B","text":"Amazon Inspector v2 com regra CIS"},{"id":"C","text":"AWS Audit Manager com framework SOC 2"},{"id":"D","text":"AWS Security Hub habilitando o CIS AWS Foundations Benchmark como standard"}]'::jsonb, 'D',
  '{
    "summary": "Security Hub entrega CIS Benchmark como standard pré-construído com score e checks automatizados.",
    "whyCorrect": "AWS Security Hub oferece standards prontos — CIS AWS Foundations Benchmark, PCI DSS, AWS Foundational Security Best Practices (AFSBP), NIST 800-53. Ao habilitar, ele roda dezenas de controles continuamente (via Config rules por baixo) e exibe um score de conformidade percentual no console. Cada controle pode ser disable/enable e tem remediation guidance.",
    "whyWrong": {
     "A": "Funciona mas reinventa a roda — Security Hub já entrega isso pronto e com score pré-calculado.",
     "B": "Inspector v2 procura vulnerabilidades em workloads (EC2/ECR/Lambda), não avalia controles CIS de configuração de conta.",
     "C": "Audit Manager monta assessments para frameworks (SOC, PCI, HIPAA) coletando evidências — não tem o standard CIS Foundations como score dashboard primário."
    },
    "keyConcept": "Security Hub standards — checks contínuos com score por framework",
    "compareWith": [
     "Security Hub vs Config",
     "Security Hub vs Audit Manager"
    ],
    "realWorldContext": "CIS Benchmark é frequentemente pedido em auditorias — Security Hub entrega esse score ''pronto'' sem trabalho de desenvolvimento.",
    "commonMistakes": "Achar que precisa escrever cada Config rule manualmente — Security Hub já compõe e gerencia.",
    "tutorSeeds": [
     "Quais standards o Security Hub suporta?",
     "Como Security Hub usa Config por baixo?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["security-hub","cis-benchmark","compliance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
