INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-005', 'aws-clf', 'Qual é a diferença fundamental entre Amazon GuardDuty e AWS Security Hub?',
  '[{"id":"A","text":"GuardDuty GERA findings de ameaça (a partir de logs); Security Hub AGREGA findings de múltiplos serviços e aplica controles de standards"},{"id":"B","text":"GuardDuty é pago, Security Hub é grátis"},{"id":"C","text":"GuardDuty é apenas para S3, Security Hub é para a conta toda"},{"id":"D","text":"São o mesmo serviço com nomes diferentes em regiões diferentes"}]'::jsonb, 'A',
  '{
    "summary": "GuardDuty produz findings; Security Hub é o agregador central e aplica controles.",
    "whyCorrect": "GuardDuty é um produtor de findings — analisa logs e gera detecções de ameaça. Security Hub é um consumidor/agregador — recebe findings do GuardDuty, Inspector, Macie, IAM Access Analyzer, Firewall Manager e parceiros (formato ASFF), aplica controles de standards (CIS/PCI/AFSBP) e oferece visão central. Ambos são pagos.",
    "whyWrong": {
     "B": "Ambos são pagos por uso. Security Hub cobra por controles avaliados + findings ingeridos.",
     "C": "Errado — GuardDuty cobre conta toda (não só S3). S3 Protection é uma feature dentro do GuardDuty.",
     "D": "São serviços completamente distintos com papéis diferentes."
    },
    "keyConcept": "GuardDuty (gera findings) vs Security Hub (agrega + aplica controles)",
    "compareWith": [
     "GuardDuty vs Security Hub vs Inspector vs Macie"
    ],
    "realWorldContext": "Arquitetura padrão: GuardDuty/Inspector/Macie geram findings -> Security Hub agrega -> EventBridge envia para SOAR/ticketing.",
    "commonMistakes": "Achar que Security Hub substitui GuardDuty — sem GuardDuty rodando, Security Hub fica sem findings de ameaça para agregar.",
    "tutorSeeds": [
     "O que é ASFF (AWS Security Finding Format)?",
     "Quais serviços integram com Security Hub?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["guardduty","security-hub","comparison"]'::jsonb, 'ai-draft', 'active', now(), now()
)
