INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-006', 'aws-clf', 'Uma fintech precisa descobrir automaticamente buckets S3 que contêm CPFs, números de cartão e e-mails de clientes para priorizar controle de acesso. Qual serviço AWS faz essa descoberta de dados sensíveis usando ML?',
  '[{"id":"A","text":"Amazon Inspector"},{"id":"B","text":"Amazon Macie"},{"id":"C","text":"AWS Glue Data Catalog"},{"id":"D","text":"AWS Audit Manager"}]'::jsonb, 'B',
  '{
    "summary": "Macie é o serviço gerenciado de descoberta de dados sensíveis em S3 usando ML.",
    "whyCorrect": "Amazon Macie usa machine learning e pattern matching para identificar dados sensíveis em buckets S3 — PII (nomes, e-mails, CPF, RG), PHI (saúde), PCI (cartões de crédito), credenciais. Suporta managed data identifiers para padrões brasileiros (CPF, CNPJ) e custom data identifiers (regex). Roda jobs sob demanda ou contínuos.",
    "whyWrong": {
     "A": "Inspector procura vulnerabilidades (CVEs) em EC2/ECR/Lambda — não escaneia conteúdo de objetos S3.",
     "C": "Glue Data Catalog é metadata catalog para data lakes — não classifica sensibilidade.",
     "D": "Audit Manager coleta evidências de controles de compliance — não escaneia objetos."
    },
    "keyConcept": "Macie — descoberta de PII/PHI/PCI em S3 com ML + managed data identifiers",
    "compareWith": [
     "Macie (S3) vs Inspector (vulns) vs Config (config-changes)"
    ],
    "realWorldContext": "LGPD/GDPR exigem inventário de dados pessoais — Macie automatiza esse mapeamento em S3 sem trabalho manual.",
    "commonMistakes": "Achar que Macie escaneia EC2 ou RDS — ele só atua em S3.",
    "tutorSeeds": [
     "Quais managed data identifiers o Macie suporta para Brasil?",
     "Como criar custom data identifier?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["macie","s3","pii","lgpd"]'::jsonb, 'ai-draft', 'active', now(), now()
)
