INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-007', 'aws-clf', 'Sobre Amazon Macie, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"Macie escaneia volumes EBS, RDS e S3 em busca de dados sensíveis"},{"id":"B","text":"Macie analisa CloudTrail events para detectar uso anômalo de IAM"},{"id":"C","text":"Macie escaneia apenas objetos armazenados no Amazon S3"},{"id":"D","text":"Macie é uma feature do GuardDuty e não pode ser habilitado separadamente"}]'::jsonb, 'C',
  '{
    "summary": "Macie é exclusivo para S3 — não escaneia EBS, RDS, EFS nem outros stores.",
    "whyCorrect": "Macie opera EXCLUSIVAMENTE sobre buckets Amazon S3. Para descobrir dados sensíveis em RDS, EBS, DynamoDB ou data lakes externos, é preciso exportar para S3 primeiro ou usar outras ferramentas. Macie tem dois tipos de jobs: gerenciamento de buckets (inventário + status de criptografia/público) e sensitive data discovery (ML scan).",
    "whyWrong": {
     "A": "Falso — apenas S3.",
     "B": "Falso — análise de CloudTrail é função do GuardDuty.",
     "D": "Falso — Macie é serviço independente, habilitado por região."
    },
    "keyConcept": "Macie — escopo exclusivo S3",
    "compareWith": [
     "Macie (S3 PII) vs GuardDuty (logs/threat) vs Inspector (CVEs)"
    ],
    "realWorldContext": "Para dados em RDS, equipes usam soluções de DLP de terceiros ou exportam dumps cifrados para S3 para análise Macie.",
    "commonMistakes": "Achar que Macie scaneia toda a conta — só atua em S3.",
    "tutorSeeds": [
     "Como Macie precifica?",
     "Posso usar Macie em buckets cross-account?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["macie","s3","scope"]'::jsonb, 'ai-draft', 'active', now(), now()
)
