INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-008', 'aws-clf', 'Uma startup quer escanear automaticamente imagens Docker armazenadas no ECR em busca de CVEs antes do deploy. Qual serviço AWS faz isso de forma gerenciada?',
  '[{"id":"A","text":"Amazon GuardDuty"},{"id":"B","text":"AWS Security Hub"},{"id":"C","text":"AWS Config"},{"id":"D","text":"Amazon Inspector v2"}]'::jsonb, 'D',
  '{
    "summary": "Inspector v2 escaneia EC2 (SSM agent), imagens ECR (push + contínuo) e Lambda functions/layers em busca de CVEs.",
    "whyCorrect": "Amazon Inspector v2 (refatorado em 2021) faz scan de vulnerabilidades em três workloads: instâncias EC2 (via SSM agent), imagens de container no ECR (no push e re-scan contínuo) e funções Lambda. Cruza pacotes/dependências com bases CVE públicas e gera findings com CVSS score. Integra com Security Hub.",
    "whyWrong": {
     "A": "GuardDuty detecta ameaças em runtime via logs — não escaneia imagens estáticas.",
     "B": "Security Hub agrega — não escaneia.",
     "C": "Config detecta mudanças de configuração de recursos AWS — não escaneia conteúdo de imagens."
    },
    "keyConcept": "Inspector v2 — vulnerability scan para EC2/ECR/Lambda",
    "compareWith": [
     "Inspector (vulns) vs GuardDuty (threat) vs Macie (PII)"
    ],
    "realWorldContext": "Pipelines CI/CD modernos enviam imagem ao ECR, Inspector escaneia automaticamente, EventBridge bloqueia deploy se há critical CVE.",
    "commonMistakes": "Pensar que Inspector v1 ainda é usado — v1 foi deprecated; v2 é o atual.",
    "tutorSeeds": [
     "Como Inspector se compara a Trivy/Snyk?",
     "Qual é o overhead do SSM agent no EC2 scan?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["inspector","ecr","vulnerability"]'::jsonb, 'ai-draft', 'active', now(), now()
)
