INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-009', 'aws-clf', 'Após um GuardDuty finding apontar credenciais IAM possivelmente comprometidas, um analista quer investigar todas as ações executadas por aquela role nos últimos 30 dias, com timeline gráfico e correlação automática. Qual serviço entrega essa visualização?',
  '[{"id":"A","text":"Amazon Detective"},{"id":"B","text":"AWS CloudTrail Lake"},{"id":"C","text":"Amazon Athena consultando logs do CloudTrail no S3"},{"id":"D","text":"AWS Trusted Advisor"}]'::jsonb, 'A',
  '{
    "summary": "Detective gera grafos de investigação correlacionando CloudTrail, VPC Flow Logs, GuardDuty e EKS audit logs.",
    "whyCorrect": "Amazon Detective ingere automaticamente CloudTrail, VPC Flow Logs, GuardDuty findings e EKS audit logs, e os correlaciona em grafos (entidade -> ação -> entidade) com timelines visuais. Permite drill-down em uma role/IP/instância para ver tudo que fez e com quem interagiu — acelera investigações de segurança.",
    "whyWrong": {
     "B": "CloudTrail Lake permite queries SQL sobre eventos, mas não gera grafos nem correlaciona com Flow Logs/GuardDuty.",
     "C": "Athena permite query SQL ad-hoc — mas exige montar tabelas e queries manualmente, sem visualização gráfica.",
     "D": "Trusted Advisor faz checks de best practices — não é ferramenta de investigação."
    },
    "keyConcept": "Detective — investigação visual com grafos de correlação",
    "compareWith": [
     "Detective vs Security Hub (agrega) vs GuardDuty (gera)"
    ],
    "realWorldContext": "Equipes SOC usam Detective como pivot point: clicar num finding do GuardDuty abre direto o grafo de Detective.",
    "commonMistakes": "Confundir Detective com SIEM — Detective é especializado em correlação AWS, não substitui um SIEM amplo.",
    "tutorSeeds": [
     "Quais log sources Detective ingere?",
     "Como Detective integra com GuardDuty?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["detective","investigation","guardduty"]'::jsonb, 'ai-draft', 'active', now(), now()
)
