INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-010', 'aws-clf', 'Uma equipe de SecOps recebeu um finding do GuardDuty: ''UnauthorizedAccess:IAMUser/ConsoleLoginSuccess.B''. O que esse finding TIPICAMENTE indica?',
  '[{"id":"A","text":"Que um usuário tentou fazer login mas falhou a senha"},{"id":"B","text":"Que um usuário IAM fez login no console com sucesso de um IP/local conhecido por atividade maliciosa"},{"id":"C","text":"Que o MFA do root user foi desabilitado"},{"id":"D","text":"Que um IAM Access Key foi rotacionada com sucesso"}]'::jsonb, 'B',
  '{
    "summary": "ConsoleLoginSuccess.B = login bem-sucedido a partir de IP/ASN marcado como malicioso na threat intel.",
    "whyCorrect": "Os tipos de finding do GuardDuty seguem o padrão ''ThreatPurpose:ResourceType/ThreatName.Variant''. ConsoleLoginSuccess.B indica login no console bem-sucedido cuja origem (IP) figura em listas de threat intelligence usadas pelo GuardDuty (proxies maliciosos, TOR exits, etc.). É um sinal forte de credencial comprometida.",
    "whyWrong": {
     "A": "Falha de login não gera esse finding específico — GuardDuty tem outros findings de brute force.",
     "C": "Desabilitar MFA do root é detectado por outros mecanismos (Config, Security Hub control).",
     "D": "Rotação de access key é evento normal, não gera finding de ameaça."
    },
    "keyConcept": "GuardDuty finding types — padrão Purpose:Resource/Threat.Variant",
    "compareWith": [
     "ConsoleLoginSuccess.B vs CryptoCurrency:EC2/BitcoinTool.B"
    ],
    "realWorldContext": "Resposta padrão: revogar a key, exigir reset de senha + MFA, investigar com Detective.",
    "commonMistakes": "Ignorar findings ''Success'' achando que sucesso é bom — em segurança, login de IP malicioso é o pior cenário.",
    "tutorSeeds": [
     "Quais variantes (.A, .B) existem nos findings?",
     "Como reagir a um finding crítico?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["guardduty","findings","incident-response"]'::jsonb, 'ai-draft', 'active', now(), now()
)
