INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-011', 'aws-clf', 'Sobre a feature GuardDuty S3 Protection, qual descrição é correta?',
  '[{"id":"A","text":"Faz scan de PII em objetos S3 usando ML"},{"id":"B","text":"Aplica Block Public Access automaticamente em todos os buckets"},{"id":"C","text":"Analisa CloudTrail data events de S3 para detectar comportamento anômalo (download massivo, descoberta de buckets, acessos de IPs maliciosos)"},{"id":"D","text":"Cifra automaticamente os objetos no S3 usando KMS"}]'::jsonb, 'C',
  '{
    "summary": "S3 Protection do GuardDuty analisa data events de CloudTrail de S3 para detectar comportamento suspeito.",
    "whyCorrect": "S3 Protection é uma feature do GuardDuty que habilita ingestão de CloudTrail data events para S3 (sem custo extra de ingestão). Detecta padrões como exfiltração (GetObject em massa), reconnaissance (ListBuckets de IPs incomuns), acesso a partir de IPs/ASNs maliciosos. Gera findings tipo ''Stealth:IAMUser/S3ServerAccessLoggingDisabled'' ou ''Exfiltration:S3/AnomalousBehavior''.",
    "whyWrong": {
     "A": "Scan de PII é função do Macie.",
     "B": "S3 Block Public Access é configuração do próprio S3, não do GuardDuty.",
     "D": "Cifra é função do KMS/SSE-S3, não do GuardDuty."
    },
    "keyConcept": "GuardDuty S3 Protection — detecção de comportamento anômalo em S3 via CloudTrail",
    "compareWith": [
     "S3 Protection (GuardDuty/threat) vs Macie (S3/PII discovery)"
    ],
    "realWorldContext": "Habilitada por padrão em contas novas onde GuardDuty está ativo desde 2020.",
    "commonMistakes": "Achar que S3 Protection escaneia conteúdo — ele só analisa eventos de acesso.",
    "tutorSeeds": [
     "Diferença entre S3 Protection e Macie?",
     "Quais findings de S3 Protection?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["guardduty","s3-protection"]'::jsonb, 'ai-draft', 'active', now(), now()
)
