INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-012', 'aws-clf', 'Em um pipeline de DevSecOps, qual combinação de serviços AWS entrega: (1) descoberta de PII em S3, (2) scan de CVEs em imagens ECR, (3) detecção de ameaças em logs e (4) agregação central de findings?',
  '[{"id":"A","text":"Config + Audit Manager + CloudTrail + Trusted Advisor"},{"id":"B","text":"GuardDuty + Macie + Detective + Artifact"},{"id":"C","text":"Inspector + Shield + WAF + Firewall Manager"},{"id":"D","text":"Macie + Inspector + GuardDuty + Security Hub"}]'::jsonb, 'D',
  '{
    "summary": "Cada serviço tem papel específico: Macie (PII em S3), Inspector (CVEs), GuardDuty (threat), Security Hub (agrega).",
    "whyCorrect": "A composição correta dos quatro pilares de detecção é: Macie para sensitive data discovery em S3, Inspector v2 para vulnerability scan de EC2/ECR/Lambda, GuardDuty para threat detection sobre logs, Security Hub como agregador central de findings de todos eles + standards de compliance.",
    "whyWrong": {
     "A": "Config detecta mudanças de configuração, Audit Manager coleta evidências, CloudTrail registra API calls, Trusted Advisor dá best practices — nenhum desses faz PII discovery, CVE scan ou threat detection diretamente.",
     "B": "Detective faz investigação visual, Artifact provê documentos de compliance — não cobrem CVE scan nem agregação central.",
     "C": "Shield e WAF são proteção de rede/aplicação, Firewall Manager gerencia políticas — não cobrem PII nem threat sobre logs."
    },
    "keyConcept": "Os 4 serviços de detecção AWS — Macie, Inspector, GuardDuty, Security Hub",
    "compareWith": [
     "Detection pipeline vs Audit pipeline"
    ],
    "realWorldContext": "Padrão recomendado pelo AWS Well-Architected Security Pillar.",
    "commonMistakes": "Confundir agregador (Security Hub) com produtor de findings (Macie/Inspector/GuardDuty).",
    "tutorSeeds": [
     "Como esses 4 serviços se interconectam?",
     "Qual o custo aproximado de ligar todos?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["detection-stack","security-hub","guardduty","macie","inspector"]'::jsonb, 'ai-draft', 'active', now(), now()
)
