INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-013', 'aws-clf', 'Uma empresa hospeda um Application Load Balancer (ALB) público e quer proteger contra SQL injection, XSS, bots e rate-limiting de IP individual. Qual serviço aplicar em frente ao ALB?',
  '[{"id":"A","text":"AWS WAF com managed rule groups e rate-based rules"},{"id":"B","text":"AWS Shield Standard"},{"id":"C","text":"Amazon GuardDuty"},{"id":"D","text":"AWS Network Firewall"}]'::jsonb, 'A',
  '{
    "summary": "WAF protege L7 (HTTP) com rules de SQLi/XSS/bot + rate-based rules — atua em ALB, CloudFront, API Gateway, AppSync, Cognito, App Runner.",
    "whyCorrect": "AWS WAF é um web application firewall L7 anexado a ALB, CloudFront, API Gateway, AppSync, Cognito User Pool ou App Runner. Oferece managed rule groups (AWS-managed e marketplace) cobrindo OWASP Top 10, bots, IPs reputados, geo match. Rate-based rules limitam requisições por IP num intervalo (ex: 2000 req em 5 min). Suporta CAPTCHA e Challenge actions.",
    "whyWrong": {
     "B": "Shield Standard protege contra DDoS L3/L4 — não inspeciona HTTP nem bloqueia SQLi.",
     "C": "GuardDuty detecta — não bloqueia em frente ao ALB.",
     "D": "Network Firewall protege VPC em nível L3-L7 stateful, mas é para tráfego dentro/saindo da VPC, não em frente a ALB público."
    },
    "keyConcept": "WAF L7 — anexa a CloudFront/ALB/API Gateway/AppSync/Cognito/App Runner",
    "compareWith": [
     "WAF vs Shield vs Network Firewall"
    ],
    "realWorldContext": "Bloqueio de bots scrapers e rate-limit de IP são padrão em e-commerce — WAF entrega isso sem servidor.",
    "commonMistakes": "Achar que WAF protege EC2 direto — precisa de um dos serviços suportados em frente.",
    "tutorSeeds": [
     "Quais managed rule groups são gratuitos?",
     "Como funciona WCU (Web ACL Capacity Unit)?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["waf","alb","application-security"]'::jsonb, 'ai-draft', 'active', now(), now()
)
