INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-014', 'aws-clf', 'Qual afirmação sobre AWS Shield Standard é VERDADEIRA?',
  '[{"id":"A","text":"Custa USD 3.000/mês com commitment de 1 ano"},{"id":"B","text":"É grátis e habilitado automaticamente para todos os clientes AWS, protegendo contra ataques DDoS comuns nas camadas 3 e 4"},{"id":"C","text":"Inclui acesso 24x7 ao DDoS Response Team (DRT)"},{"id":"D","text":"Requer habilitação manual no console"}]'::jsonb, 'B',
  '{
    "summary": "Shield Standard é grátis, automático, e protege contra DDoS L3/L4 comum.",
    "whyCorrect": "AWS Shield Standard é incluso GRATUITAMENTE para todos os clientes AWS, sem habilitação manual. Protege contra os ataques DDoS mais comuns de camada 3 (rede) e 4 (transporte) — SYN floods, UDP reflection, etc. Cobre CloudFront, Route 53 e ALB/NLB automaticamente.",
    "whyWrong": {
     "A": "USD 3.000/mês é o valor mínimo do Shield ADVANCED (com commitment de 1 ano), não do Standard.",
     "C": "DRT é benefício exclusivo do Shield Advanced (e do Enterprise/Business support).",
     "D": "Não requer habilitação — é automático."
    },
    "keyConcept": "Shield Standard — DDoS L3/L4 grátis e automático",
    "compareWith": [
     "Shield Standard vs Shield Advanced"
    ],
    "realWorldContext": "Mesmo sem fazer nada, sua conta AWS já tem proteção contra grande parte dos ataques volumétricos.",
    "commonMistakes": "Achar que Shield exige habilitação — Standard é transparente.",
    "tutorSeeds": [
     "Como Shield protege CloudFront em escala global?",
     "Quando Shield Advanced compensa?"
    ]
   }'::jsonb,
