INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-015', 'aws-clf', 'Qual benefício é EXCLUSIVO do AWS Shield Advanced (e NÃO está no Shield Standard)?',
  '[{"id":"A","text":"Proteção contra SYN floods"},{"id":"B","text":"Proteção L3/L4 automática"},{"id":"C","text":"Cost protection — reembolso de scale-up cobrado durante um ataque DDoS comprovado"},{"id":"D","text":"Integração transparente com CloudFront"}]'::jsonb, 'C',
  '{
    "summary": "Cost protection (reembolso de scale-up durante ataque) é exclusivo do Shield Advanced.",
    "whyCorrect": "Shield Advanced (USD 3.000/mês, commitment de 1 ano) adiciona vários benefícios — proteção contra DDoS L3/L4/L7 mais sofisticada, acesso 24x7 ao DDoS Response Team (DRT), métricas detalhadas no CloudWatch, AWS WAF incluso para recursos protegidos, e cost protection — se durante um ataque seu Auto Scaling, Route 53 ou CloudFront escalou e gerou custo extra, AWS reembolsa.",
    "whyWrong": {
     "A": "SYN flood é coberto também pelo Standard.",
     "B": "Proteção L3/L4 automática já está no Standard.",
     "D": "Integração com CloudFront existe nos dois — Advanced é mais profundo."
    },
    "keyConcept": "Shield Advanced — cost protection + DRT + WAF incluso + métricas detalhadas",
    "compareWith": [
     "Shield Standard (grátis) vs Advanced ($3k/mês)"
    ],
    "realWorldContext": "Empresas que sofreram DDoS e tiveram conta gigante de scale-up frequentemente migram para Advanced pelo cost protection.",
    "commonMistakes": "Achar que Shield Advanced é só ''WAF + mais'' — é WAF + DRT + cost protection + métricas.",
    "tutorSeeds": [
     "O que faz o DDoS Response Team (DRT)?",
     "Como funciona o reembolso na prática?"
    ]
   }'::jsonb,
