INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-016', 'aws-clf', 'Sobre Security Groups (SG) e Network ACLs (NACLs), qual afirmação está CORRETA?',
  '[{"id":"A","text":"SG é stateless e suporta DENY; NACL é stateful e só suporta ALLOW"},{"id":"B","text":"Ambos são stateful e suportam DENY"},{"id":"C","text":"SG opera em nível de subnet; NACL em nível de ENI"},{"id":"D","text":"SG é stateful e suporta apenas ALLOW (sem DENY); NACL é stateless, suporta ALLOW e DENY, e avalia regras por número ordenado"}]'::jsonb, 'D',
  '{
    "summary": "SG: stateful, só ALLOW, em ENI. NACL: stateless, ALLOW+DENY, em subnet, regras numeradas.",
    "whyCorrect": "Security Groups são STATEFUL — a resposta de um tráfego permitido sai automaticamente. Só suportam regras de ALLOW (não existe DENY; o default é deny). Aplicados em ENIs (ENI por instância/serviço). Network ACLs são STATELESS — precisa permitir tráfego de entrada E o retorno (ephemeral ports). Suportam ALLOW e DENY. São avaliados em ordem numérica (regra de menor número primeiro), e existem em nível de SUBNET.",
    "whyWrong": {
     "A": "Invertido — SG é stateful, NACL é stateless.",
     "B": "SG não tem DENY; NACL é stateless.",
     "C": "Invertido — SG é por ENI, NACL é por subnet."
    },
    "keyConcept": "SG (stateful, ALLOW-only, ENI) vs NACL (stateless, ALLOW+DENY ordenado, subnet)",
    "compareWith": [
     "SG vs NACL",
     "Stateful vs stateless firewalls"
    ],
    "realWorldContext": "Use SG como controle primário (granularidade de ENI). Use NACL para bloquear IPs específicos no perímetro da subnet (ex: bloquear pais específicos via DENY).",
    "commonMistakes": "Esquecer de permitir ephemeral ports em NACL (1024-65535 TCP) e perder o tráfego de retorno.",
    "tutorSeeds": [
     "Por que NACL precisa permitir ephemeral ports?",
     "Quando usar DENY em NACL?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["security-group","nacl","vpc","firewall"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
