INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-017', 'aws-clf', 'Um time precisa bloquear um IP específico de atacante em uma subnet inteira, ANTES que o tráfego chegue às instâncias. Qual recurso aplicar?',
  '[{"id":"A","text":"NACL com regra DENY (rule number baixo) bloqueando inbound desse IP"},{"id":"B","text":"Security Group com regra DENY de inbound desse IP"},{"id":"C","text":"WAF com regra de IP block na subnet"},{"id":"D","text":"IAM policy negando o IP"}]'::jsonb, 'A',
  '{
    "summary": "NACL é o único que suporta DENY explícito em nível de subnet.",
    "whyCorrect": "Como NACLs operam em nível de subnet e suportam regras de DENY, são o recurso correto para bloquear um IP específico no perímetro. A regra deve ter número baixo (avaliado primeiro). Security Groups não suportam DENY; WAF atua em camada 7 anexado a ALB/CloudFront; IAM não controla tráfego IP.",
    "whyWrong": {
     "B": "Security Groups não suportam regra DENY.",
     "C": "WAF não atua na subnet — anexa a ALB/CloudFront/etc.",
     "D": "IAM controla quem pode fazer API calls, não filtra pacotes IP."
    },
    "keyConcept": "NACL é o único firewall AWS com DENY em nível de subnet",
    "compareWith": [
     "NACL deny vs SG (sem deny) vs WAF (L7)"
    ],
    "realWorldContext": "Em incidentes de DDoS de IP único, NACL é a forma mais rápida de cortar.",
    "commonMistakes": "Tentar criar DENY em SG e ficar frustrado — não existe.",
    "tutorSeeds": [
     "Como ordenar regras NACL?",
     "NACL aceita CIDR/24?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'troubleshoot', '["nacl","security-group","deny"]'::jsonb, 'ai-draft', 'active', now(), now()
)
