INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-018', 'aws-clf', 'Uma empresa quer auditar todo tráfego IP que entra e sai das ENIs de uma VPC, separando por ACCEPT e REJECT. Qual feature ativar?',
  '[{"id":"A","text":"AWS CloudTrail data events de VPC"},{"id":"B","text":"VPC Flow Logs"},{"id":"C","text":"AWS Config para VPC resources"},{"id":"D","text":"VPC Traffic Mirroring para CloudWatch"}]'::jsonb, 'B',
  '{
    "summary": "VPC Flow Logs capturam metadados (5-tuple + action ACCEPT/REJECT) de tráfego IP em VPC/subnet/ENI.",
    "whyCorrect": "VPC Flow Logs capturam metadados (5-tuple: src/dst IP+port + protocol, bytes, packets, action ACCEPT ou REJECT, timestamps) sobre tráfego IP. Habilitados em VPC inteira, subnet ou ENI. Destinos suportados: CloudWatch Logs, S3 ou Kinesis Data Firehose. Custom format permite incluir mais campos (instance-id, tcp-flags, traffic-type).",
    "whyWrong": {
     "A": "CloudTrail registra API calls da AWS — não captura pacotes de rede.",
     "C": "Config registra mudanças de configuração de recursos (SG rules, subnets) — não tráfego.",
     "D": "Traffic Mirroring copia pacotes completos para inspeção (DPI) — útil mas caro e overkill para auditoria de metadados."
    },
    "keyConcept": "VPC Flow Logs — metadados de tráfego com ACCEPT/REJECT",
    "compareWith": [
     "Flow Logs (metadados) vs Traffic Mirroring (pacotes)"
    ],
    "realWorldContext": "GuardDuty consome Flow Logs nativamente; equipes SecOps fazem Athena queries em Flow Logs para investigação.",
    "commonMistakes": "Esperar ver payload — Flow Logs só dão metadados.",
    "tutorSeeds": [
     "Quando habilitar Flow Logs em ENI específica vs VPC inteira?",
     "Custom format do Flow Logs"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["vpc-flow-logs","audit","network"]'::jsonb, 'ai-draft', 'active', now(), now()
)
