INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-019', 'aws-clf', 'Uma empresa quer inspeção stateful de tráfego (IPS/IDS) entre VPCs em uma arquitetura hub-and-spoke com Transit Gateway, suportando regras Suricata. Qual serviço AWS é ideal?',
  '[{"id":"A","text":"AWS WAF"},{"id":"B","text":"Security Groups expandidas"},{"id":"C","text":"AWS Network Firewall"},{"id":"D","text":"Amazon GuardDuty"}]'::jsonb, 'C',
  '{
    "summary": "Network Firewall = firewall gerenciado L3-L7 stateful para VPC com suporte Suricata.",
    "whyCorrect": "AWS Network Firewall é um firewall gerenciado de rede que oferece inspeção L3-L7 stateful, com suporte a regras no formato Suricata (IPS/IDS open source). É deployado em uma subnet dedicada da VPC, frequentemente em arquitetura hub-and-spoke com Transit Gateway no centro. Suporta domain filtering, intrusion prevention, TLS inspection (recente).",
    "whyWrong": {
     "A": "WAF é L7 HTTP/S — não inspeciona tráfego entre VPCs em camada de rede.",
     "B": "Security Groups são stateful mas não fazem IPS/IDS nem suportam Suricata.",
     "D": "GuardDuty detecta — não inspeciona/bloqueia em linha."
    },
    "keyConcept": "Network Firewall — IPS/IDS gerenciado com regras Suricata em VPC",
    "compareWith": [
     "Network Firewall vs WAF vs SG/NACL"
    ],
    "realWorldContext": "Arquiteturas regulatórias (PCI, healthcare) usam Network Firewall em hub TGW para inspecionar todo tráfego inter-VPC.",
    "commonMistakes": "Confundir com WAF — Network Firewall é para tráfego de rede, WAF para HTTP em frente a ALB.",
    "tutorSeeds": [
     "Como integrar Network Firewall com Transit Gateway?",
     "Suricata rules — formato"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["network-firewall","ips-ids","suricata","transit-gateway"]'::jsonb, 'ai-draft', 'active', now(), now()
)
