INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-020', 'aws-clf', 'Uma fintech precisa permitir acesso a S3 a partir de VPCs privadas SEM passar pela internet pública e SEM trafegar via NAT Gateway. Qual recurso usar?',
  '[{"id":"A","text":"Internet Gateway com regras restritas"},{"id":"B","text":"Direct Connect Gateway"},{"id":"C","text":"Site-to-Site VPN para o S3"},{"id":"D","text":"VPC Gateway Endpoint para S3"}]'::jsonb, 'D',
  '{
    "summary": "VPC Gateway Endpoint roteia tráfego S3/DynamoDB pela rede AWS, sem internet, sem custo de NAT.",
    "whyCorrect": "VPC Gateway Endpoints existem para S3 e DynamoDB — adicionam uma route table entry que aponta para o serviço pela rede privada da AWS. Sem custo de endpoint (Gateway Endpoint é grátis) e sem custo de NAT Gateway/data transfer. Para outros serviços (KMS, SQS, etc.), use Interface Endpoints (PrivateLink, com custo por hora + GB).",
    "whyWrong": {
     "A": "Internet Gateway expõe tráfego à internet pública — exatamente o que se quer evitar.",
     "B": "Direct Connect é circuito dedicado on-prem -> AWS, não relevante para VPC -> S3.",
     "C": "VPN não conecta VPC ao S3 internamente; S3 é serviço público com endpoints privados via PrivateLink/Gateway."
    },
    "keyConcept": "Gateway Endpoint (S3/DynamoDB grátis) vs Interface Endpoint (PrivateLink pago)",
    "compareWith": [
     "Gateway vs Interface endpoint"
    ],
    "realWorldContext": "Padrão obrigatório em arquiteturas PCI/HIPAA — tráfego nunca sai da rede AWS.",
    "commonMistakes": "Pagar NAT Gateway desnecessariamente para tráfego S3.",
    "tutorSeeds": [
     "Quais serviços usam Gateway vs Interface endpoint?",
     "Como restringir acesso via endpoint policy?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["vpc-endpoint","s3","privatelink"]'::jsonb, 'ai-draft', 'active', now(), now()
)
