INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-021', 'aws-clf', 'Uma empresa quer bloquear acesso ao site de IPs fora do Brasil e Argentina. Qual feature do AWS WAF entrega isso?',
  '[{"id":"A","text":"Geo match rule"},{"id":"B","text":"Rate-based rule"},{"id":"C","text":"AWS Managed Rules — Core Rule Set"},{"id":"D","text":"CAPTCHA action"}]'::jsonb, 'A',
  '{
    "summary": "Geo match rule do WAF filtra por país de origem do IP.",
    "whyCorrect": "AWS WAF Geo Match rules bloqueiam (ou permitem) requisições baseado no país do IP de origem (resolvido por banco GeoIP). Para o cenário: criar rule com action BLOCK e country list contendo todos os países EXCETO BR e AR (ou inverter — ALLOW só BR/AR no default block).",
    "whyWrong": {
     "B": "Rate-based limita req/IP num período — não filtra por geografia.",
     "C": "Core Rule Set cobre OWASP Top 10 — não geografia.",
     "D": "CAPTCHA desafia o cliente, não é geo-filter."
    },
    "keyConcept": "Geo match rule — filtragem por país no WAF",
    "compareWith": [
     "Geo match vs rate-based vs managed rules"
    ],
    "realWorldContext": "E-commerces que vendem só para certos países usam geo match para reduzir fraude e bot traffic.",
    "commonMistakes": "Confundir geo match com IP set — IP set é lista explícita; geo match usa GeoIP.",
    "tutorSeeds": [
     "Posso combinar geo match com outras conditions?",
     "GeoIP é 100% preciso?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["waf","geo-match"]'::jsonb, 'ai-draft', 'active', now(), now()
)
