INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-022', 'aws-clf', 'Por quanto tempo o console do CloudTrail mantém o histórico de eventos (Event history) por padrão, SEM criar um Trail customizado?',
  '[{"id":"A","text":"7 dias"},{"id":"B","text":"90 dias"},{"id":"C","text":"30 dias"},{"id":"D","text":"1 ano"}]'::jsonb, 'B',
  '{
    "summary": "CloudTrail Event history (console) retém 90 dias dos últimos management events — para mais, criar Trail para S3.",
    "whyCorrect": "Por padrão, todo evento de management do CloudTrail fica visível no Event history do console por 90 dias, sem custo. Para retenção maior, log file validation, organization-wide ou data events, é preciso criar um Trail explícito que envia eventos para S3 (e opcionalmente CloudWatch Logs/EventBridge).",
    "whyWrong": {
     "A": "7 dias é o default de CloudWatch Logs metrics — não CloudTrail.",
     "C": "30 dias é o padrão de retenção do Config para snapshots curtos.",
     "D": "1 ano não é o padrão do Event history."
    },
    "keyConcept": "CloudTrail Event history — 90 dias grátis no console",
    "compareWith": [
     "Event history (90d console) vs Trail (S3 ilimitado)"
    ],
    "realWorldContext": "Auditorias frequentemente exigem >1 ano de logs — sempre criar Trail to S3 com lifecycle.",
    "commonMistakes": "Achar que sem Trail há retenção infinita — não há.",
    "tutorSeeds": [
     "Como configurar um Trail organization-wide?",
     "Log file validation — para quê?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["cloudtrail","retention"]'::jsonb, 'ai-draft', 'active', now(), now()
)
