INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-023', 'aws-clf', 'Sobre eventos do CloudTrail, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"Management events e data events são ambos cobrados por padrão"},{"id":"B","text":"Data events estão habilitados por padrão para todos os serviços"},{"id":"C","text":"Management events (criar bucket, modificar SG) são GRATUITOS em uma trilha por conta; data events (object-level S3, Lambda invocations) são COBRADOS quando habilitados"},{"id":"D","text":"CloudTrail não registra eventos de read-only — apenas write"}]'::jsonb, 'C',
  '{
    "summary": "Management events grátis (1 trail/conta); data events pagos e desabilitados por padrão.",
    "whyCorrect": "CloudTrail captura management events (operações no plano de controle: CreateBucket, RunInstances, AttachRolePolicy) gratuitamente em uma trail por conta. Data events (S3 object-level GetObject/PutObject, Lambda Invoke, DynamoDB item-level) são extremamente verbosos e cobrados ($0.10 por 100k eventos) — desabilitados por padrão.",
    "whyWrong": {
     "A": "Management events em UMA trail são grátis.",
     "B": "Data events são desabilitados por padrão (custo).",
     "D": "CloudTrail registra read e write events de management."
    },
    "keyConcept": "Management events (free, 1 trail) vs Data events (paid, opt-in)",
    "compareWith": [
     "Management vs Data vs Insights events"
    ],
    "realWorldContext": "Habilitar data events em bucket S3 sensível para auditar quem acessou que objeto — comum em healthcare/financial.",
    "commonMistakes": "Habilitar data events para todo S3 da conta e tomar susto na fatura.",
    "tutorSeeds": [
     "O que são Insights events?",
     "Como filtrar data events por bucket específico?"
    ]
   }'::jsonb,
