INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-024', 'aws-clf', 'Uma equipe de compliance quer garantir que NENHUM log do CloudTrail seja alterado/deletado sem ser detectado, mesmo por um admin malicioso. Qual feature ativar?',
  '[{"id":"A","text":"S3 versioning no bucket de logs"},{"id":"B","text":"CloudTrail Insights events"},{"id":"C","text":"AWS Backup do CloudTrail"},{"id":"D","text":"CloudTrail log file validation (digests + hashes)"}]'::jsonb, 'D',
  '{
    "summary": "Log file validation produz digest files com hashes — qualquer alteração quebra a cadeia de validação.",
    "whyCorrect": "CloudTrail Log file validation, quando habilitada na trail, produz digest files horários assinados que contêm hashes SHA-256 dos log files. Se algum log for alterado ou deletado, a validação falha e o auditor sabe. A CLI `aws cloudtrail validate-logs` faz essa checagem. Complementa Object Lock e SCPs.",
    "whyWrong": {
     "A": "Versioning protege contra overwrite, mas não detecta tampering nem cobre delete completo (precisa MFA Delete).",
     "B": "Insights events detectam anomalias de volume de API calls — não validam integridade de logs.",
     "C": "AWS Backup faz cópias, mas não é validador criptográfico contínuo da cadeia."
    },
    "keyConcept": "CloudTrail log file validation — digests SHA-256 detectam tampering",
    "compareWith": [
     "Log validation vs S3 Object Lock"
    ],
    "realWorldContext": "Exigência de SOX/PCI — combinada com Object Lock (compliance mode) torna logs forensicamente íntegros.",
    "commonMistakes": "Confundir com Object Lock — log validation detecta, Object Lock impede.",
    "tutorSeeds": [
     "Como executar validação de logs via CLI?",
     "Frequência de digest files?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["cloudtrail","log-validation","integrity"]'::jsonb, 'ai-draft', 'active', now(), now()
)
