INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-025', 'aws-clf', 'Uma empresa quer saber se algum Security Group foi modificado nas últimas 24h e ver o estado anterior vs atual. Qual serviço entrega isso nativamente?',
  '[{"id":"A","text":"AWS Config"},{"id":"B","text":"Amazon CloudWatch Metrics"},{"id":"C","text":"AWS Trusted Advisor"},{"id":"D","text":"Amazon Inspector"}]'::jsonb, 'A',
  '{
    "summary": "Config registra mudanças de configuração de recursos AWS com timeline.",
    "whyCorrect": "AWS Config grava snapshots de configuração de recursos AWS suportados (SG, IAM roles, S3 buckets, EBS volumes etc.) e mantém timeline de mudanças com diff (configuration items). Permite responder ''qual era o estado X em momento Y'' e ''quem mudou'' (cruzando com CloudTrail). Rules avaliam compliance contínua.",
    "whyWrong": {
     "B": "CloudWatch Metrics são números — não capturam diff de configuração.",
     "C": "Trusted Advisor dá checks de best practices em snapshot atual — não timeline histórico.",
     "D": "Inspector escaneia vulnerabilidades, não mudanças de configuração."
    },
    "keyConcept": "AWS Config — registro de mudanças de configuração de recursos AWS",
    "compareWith": [
     "Config (state changes) vs CloudTrail (API calls)"
    ],
    "realWorldContext": "Investigações pós-incidente: Config mostra qual era o SG ontem; CloudTrail mostra quem mudou.",
    "commonMistakes": "Confundir Config com CloudTrail — Config = estado de recursos, CloudTrail = API calls.",
    "tutorSeeds": [
     "Como funciona Configuration Recorder?",
     "Config rules managed vs custom"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["config","configuration-changes"]'::jsonb, 'ai-draft', 'active', now(), now()
)
