INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-026', 'aws-clf', 'Sobre AWS Config Rules, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"Config Rules apenas avaliam conformidade; não podem disparar remediação automática"},{"id":"B","text":"Config Rules podem ser managed (AWS-provided) ou custom (Lambda), e podem disparar remediation actions (SSM Automation documents) automaticamente quando recursos ficam non-compliant"},{"id":"C","text":"Config Rules substituem CloudTrail e dispensam coleta de API events"},{"id":"D","text":"Config Rules só funcionam em conjunto com Security Hub"}]'::jsonb, 'B',
  '{
    "summary": "Config Rules avaliam compliance e podem disparar remediation via SSM Automation.",
    "whyCorrect": "AWS Config oferece Managed Rules (200+ pré-construídas: ''s3-bucket-public-read-prohibited'', ''encrypted-volumes'', ''mfa-enabled-for-iam-console-access'' etc.) e Custom Rules (sua lógica em Lambda). Quando uma rule detecta non-compliant, pode disparar remediation action — um SSM Automation document que conserta (ex: aplicar Block Public Access). Conformance packs agrupam múltiplas rules.",
    "whyWrong": {
     "A": "Falso — remediation actions existem e são amplamente usadas.",
     "C": "Falso — Config e CloudTrail são complementares.",
     "D": "Falso — Config funciona standalone."
    },
    "keyConcept": "Config Rules + remediation actions via SSM Automation",
    "compareWith": [
     "Managed vs Custom rules",
     "Conformance packs"
    ],
    "realWorldContext": "Auto-remediation comum: ''s3-bucket-public-read-prohibited'' -> SSM Automation aplica Block Public Access.",
    "commonMistakes": "Achar que Config só relata — também conserta via remediation.",
    "tutorSeeds": [
     "Como criar remediation action?",
     "Quais conformance packs existem para PCI?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["config","rules","remediation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
