INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-027', 'aws-clf', 'Uma auditoria SOC 2 exige coletar evidências de controles automaticamente (snapshots de configuração, logs de acesso, screenshots de console etc.) ao longo do ciclo. Qual serviço AWS é desenhado para esse propósito de assessment de framework?',
  '[{"id":"A","text":"AWS Config"},{"id":"B","text":"AWS Artifact"},{"id":"C","text":"AWS Audit Manager"},{"id":"D","text":"AWS Trusted Advisor"}]'::jsonb, 'C',
  '{
    "summary": "Audit Manager monta assessments de framework e coleta evidências automaticamente.",
    "whyCorrect": "AWS Audit Manager oferece frameworks pré-construídos (SOC 2, PCI DSS, HIPAA, GDPR, NIST, ISO 27001) ou customizados, mapeia controles a fontes de evidência (Config rules, CloudTrail events, Security Hub findings, manual uploads) e coleta as evidências automaticamente ao longo do período de assessment. Gera relatórios prontos para auditor.",
    "whyWrong": {
     "A": "Config rastreia mudanças mas não monta framework de assessment.",
     "B": "Artifact entrega relatórios de compliance da AWS (sobre a AWS), não evidências de SUA aplicação.",
     "D": "Trusted Advisor dá best practices — não framework auditável."
    },
    "keyConcept": "Audit Manager — assessment automatizado de frameworks com evidências",
    "compareWith": [
     "Audit Manager (sua app) vs Artifact (AWS infra)"
    ],
    "realWorldContext": "Empresas em ciclo SOC 2 Type 2 reduzem horas de coleta manual em 60-80% com Audit Manager.",
    "commonMistakes": "Confundir Audit Manager com Artifact — Artifact baixa SOC report da AWS; Audit Manager monta SEU SOC report.",
    "tutorSeeds": [
     "Quais frameworks pré-construídos?",
     "Como integra com Config e Security Hub?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["audit-manager","soc2","compliance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
