INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-028', 'aws-clf', 'O time jurídico precisa do relatório SOC 2 Type II da AWS e do AOC PCI DSS para enviar a um cliente B2B. Qual serviço fornece esses documentos sob demanda?',
  '[{"id":"A","text":"AWS Audit Manager"},{"id":"B","text":"AWS Config"},{"id":"C","text":"AWS Compliance Center"},{"id":"D","text":"AWS Artifact"}]'::jsonb, 'D',
  '{
    "summary": "AWS Artifact = portal self-service para baixar relatórios de compliance e acordos da AWS.",
    "whyCorrect": "AWS Artifact é um portal self-service que fornece, sem custo, acesso a relatórios de compliance da AWS — SOC 1/2/3, PCI DSS AOC (Attestation of Compliance), ISO 27001/17/18, FedRAMP, HIPAA mappings, GDPR DPA, BAA. Também permite aceitar agreements (BAA, NDA) com a AWS programaticamente.",
    "whyWrong": {
     "A": "Audit Manager é para AUDITAR sua própria aplicação — não fornece relatórios da AWS.",
     "B": "Config rastreia configuração — não documentos.",
     "C": "Compliance Center não é um produto AWS oficial — Artifact é o portal."
    },
    "keyConcept": "Artifact — portal de relatórios de compliance da AWS",
    "compareWith": [
     "Artifact (AWS report) vs Audit Manager (sua app)"
    ],
    "realWorldContext": "Quando cliente exige ''me mande o SOC 2 da AWS'' — você baixa em Artifact e envia (sob NDA).",
    "commonMistakes": "Pedir o SOC 2 ao suporte AWS — basta baixar no Artifact.",
    "tutorSeeds": [
     "Quais relatórios estão no Artifact?",
     "Como aceitar BAA HIPAA via Artifact?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["artifact","soc2","pci-dss"]'::jsonb, 'ai-draft', 'active', now(), now()
)
