INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-029', 'aws-clf', 'Sobre o modelo de Shared Responsibility com PCI DSS, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"AWS é PCI DSS Level 1 Service Provider; o cliente é responsável por garantir compliance da sua APLICAÇÃO que processa dados de cartão sobre a infraestrutura AWS"},{"id":"B","text":"Por contratar AWS, a aplicação automaticamente fica PCI DSS compliant"},{"id":"C","text":"PCI DSS é gerenciado integralmente pela AWS, sem responsabilidade do cliente"},{"id":"D","text":"Apenas EC2 e RDS são PCI compliant — outros serviços não"}]'::jsonb, 'A',
  '{
    "summary": "AWS é PCI Level 1 Service Provider; cliente é responsável pela aplicação (compliance OF the cloud vs IN the cloud).",
    "whyCorrect": "AWS é certificada como PCI DSS Level 1 Service Provider — a infraestrutura cumpre PCI. O cliente, ao construir aplicação que processa, armazena ou transmite dados de cartão, é responsável por implementar controles PCI (segmentação de rede, criptografia, logging, gestão de chaves, scan de vulnerabilidade etc.) sobre essa infraestrutura. AOC da AWS está disponível no Artifact.",
    "whyWrong": {
     "B": "Falso — usar AWS não confere PCI automaticamente.",
     "C": "Falso — cliente tem responsabilidades.",
     "D": "Falso — muitos serviços são in-scope; ver PCI DSS compliance page."
    },
    "keyConcept": "Shared Responsibility — AWS compliance OF the cloud, cliente IN the cloud",
    "compareWith": [
     "PCI compliance da AWS vs da aplicação"
    ],
    "realWorldContext": "QSAs (assessors PCI) querem ver AOC da AWS (do Artifact) + controles da aplicação do cliente.",
    "commonMistakes": "Assumir compliance automática — uma das fontes mais comuns de fail em audit.",
    "tutorSeeds": [
     "O que é AOC?",
     "Quais serviços AWS são in-scope para PCI?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["pci-dss","shared-responsibility","compliance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
