INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-030', 'aws-clf', 'Uma startup de healthcare nos EUA quer rodar workload sujeito ao HIPAA na AWS. O que é REQUERIDO?',
  '[{"id":"A","text":"Comprar uma licença HIPAA Premium na AWS Marketplace"},{"id":"B","text":"Assinar um Business Associate Addendum (BAA) com a AWS e usar apenas HIPAA-eligible services para PHI"},{"id":"C","text":"Rodar exclusivamente em região US-Gov"},{"id":"D","text":"Migrar todo PHI para CloudHSM"}]'::jsonb, 'B',
  '{
    "summary": "Para HIPAA: assinar BAA com a AWS (gratuito, via Artifact) + usar apenas HIPAA-eligible services para PHI.",
    "whyCorrect": "Para processar Protected Health Information (PHI) na AWS é necessário (1) aceitar o BAA (Business Associate Addendum) — disponível gratuitamente via AWS Artifact — e (2) usar apenas serviços listados como HIPAA-eligible (lista pública: EC2, S3, RDS, Lambda, KMS, DynamoDB e muitos outros, ~150 serviços). Cliente continua responsável pelos controles HIPAA na aplicação.",
    "whyWrong": {
     "A": "Não existe ''HIPAA Premium'' — BAA é grátis.",
     "C": "US-Gov é para workloads do governo federal — HIPAA não exige.",
     "D": "CloudHSM ajuda mas não é requisito HIPAA."
    },
    "keyConcept": "HIPAA — BAA assinado + HIPAA-eligible services",
    "compareWith": [
     "HIPAA-eligible vs todos serviços AWS"
    ],
    "realWorldContext": "Usar serviço NÃO HIPAA-eligible para PHI viola BAA e regulação.",
    "commonMistakes": "Usar serviço não-eligible (ex: alguns serviços novos) para dados PHI.",
    "tutorSeeds": [
     "Como ver lista de HIPAA-eligible services?",
     "BAA cobre o quê?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["hipaa","baa","compliance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
