INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-031', 'aws-clf', 'Uma empresa quer rodar workload do governo dos EUA que exige FedRAMP Moderate baseline. Qual ação tomar?',
  '[{"id":"A","text":"Usar qualquer região AWS — todas são FedRAMP Moderate"},{"id":"B","text":"Migrar para Outposts em datacenter governamental"},{"id":"C","text":"Usar regiões AWS US-East/West (Standard) para FedRAMP Moderate, ou AWS GovCloud (US) para workloads mais sensíveis até FedRAMP High e ITAR"},{"id":"D","text":"Comprar uma região privada da AWS"}]'::jsonb, 'C',
  '{
    "summary": "Regiões AWS US Standard cobrem FedRAMP Moderate; AWS GovCloud (US) cobre FedRAMP High e ITAR.",
    "whyCorrect": "AWS US East/West têm autorização FedRAMP Moderate para vários serviços, suficiente para a maioria das cargas governamentais ''moderate impact''. AWS GovCloud (US) é uma região isolada operada por US persons com FedRAMP High e suporte a ITAR (controle de exportação) — usado por workloads de defesa, intel, healthcare federal.",
    "whyWrong": {
     "A": "Apenas regiões comerciais US são FedRAMP Moderate — não ''todas''.",
     "B": "Outposts não é a resposta padrão para FedRAMP.",
     "D": "Não existe ''região privada'' comercial."
    },
    "keyConcept": "FedRAMP Moderate (US Standard) vs FedRAMP High + ITAR (GovCloud)",
    "compareWith": [
     "GovCloud vs commercial regions"
    ],
    "realWorldContext": "DoD, NASA, DOJ tipicamente em GovCloud; municípios e agências federais menores em commercial regions com FedRAMP Moderate.",
    "commonMistakes": "Achar que GovCloud é só ''mesma AWS com outra label'' — é fisicamente separado, US persons-only, sem console federation com commercial.",
    "tutorSeeds": [
     "O que é ITAR?",
     "Qual a diferença operacional entre GovCloud e Standard?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["fedramp","govcloud","compliance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
