INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-032', 'aws-clf', 'Para atender LGPD/GDPR e residência de dados, uma empresa quer garantir que dados de clientes brasileiros NUNCA saiam da região São Paulo (sa-east-1). Qual mecanismo é mais eficaz para PREVENIR cópia para outras regiões?',
  '[{"id":"A","text":"Confiar nos desenvolvedores para não copiar manualmente"},{"id":"B","text":"Encriptar com KMS — isso previne cópia"},{"id":"C","text":"Usar S3 Cross-Region Replication"},{"id":"D","text":"Aplicar uma Service Control Policy (SCP) que negue ações em regiões diferentes de sa-east-1, usando a condition aws:RequestedRegion"}]'::jsonb, 'D',
  '{
    "summary": "SCP com condition aws:RequestedRegion limita organização inteira a regiões aprovadas.",
    "whyCorrect": "Service Control Policy (SCP) com condition `aws:RequestedRegion` permite negar todas as ações em regiões diferentes de sa-east-1, exceto serviços globais (IAM, Route 53, CloudFront, Organizations). Aplicada em OU/conta, é guardrail preventivo — nem root consegue burlar. É o mecanismo padrão para data residency.",
    "whyWrong": {
     "A": "Confiança é o oposto de controle técnico.",
     "B": "Criptografia não impede cópia — dados cifrados são copiáveis.",
     "C": "Cross-Region Replication ATIVAMENTE copia para outras regiões — exatamente o que se quer evitar."
    },
    "keyConcept": "SCP com aws:RequestedRegion — controle de data residency",
    "compareWith": [
     "SCP region-deny vs IAM policy"
    ],
    "realWorldContext": "Padrão LGPD/GDPR: SCP impede provisionamento em regiões fora da UE/Brasil.",
    "commonMistakes": "Esquecer serviços globais — precisa exceção para IAM/Route 53/CloudFront.",
    "tutorSeeds": [
     "Quais serviços são globais?",
     "Exemplo de SCP region-deny?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["lgpd","gdpr","scp","data-residency"]'::jsonb, 'ai-draft', 'active', now(), now()
)
