INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-033', 'aws-clf', 'Sobre Penetration Testing (pentest) em recursos AWS, qual afirmação está CORRETA?',
  '[{"id":"A","text":"Para 8 serviços (EC2, RDS, CloudFront, Aurora, API Gateway, Lambda, Lightsail, Beanstalk environments), pentest é PERMITIDO SEM aprovação prévia da AWS, desde que respeitando regras (sem flood/DDoS, sem ferramentas DNS zone walking etc.)"},{"id":"B","text":"É proibido fazer pentest em recursos AWS sem aprovação prévia escrita"},{"id":"C","text":"Pentest só é permitido em GovCloud"},{"id":"D","text":"AWS faz o pentest pelos clientes via suporte"}]'::jsonb, 'A',
  '{
    "summary": "Pentest sem aprovação prévia em 8 serviços é permitido — desde que respeite as regras (no DDoS, no flooding).",
    "whyCorrect": "A AWS publica a Customer Support Policy for Penetration Testing — para 8 serviços (EC2, RDS, CloudFront, Aurora, API Gateway, Lambda + Lambda edge, Lightsail, Elastic Beanstalk environments), o cliente pode fazer pentest em seus próprios recursos SEM aprovação prévia. Regras: proibido DDoS, port flooding, protocol flooding, request flooding, DNS zone walking via Route 53. Para outros serviços ou simulações maiores, contatar AWS Security.",
    "whyWrong": {
     "B": "Falso para os 8 serviços — não precisa aprovação.",
     "C": "Falso — política se aplica a todas as regiões comerciais.",
     "D": "Falso — pentest é responsabilidade do cliente; AWS Marketplace tem parceiros."
    },
    "keyConcept": "Pentest policy — 8 serviços liberados sem aprovação, com regras de fair use",
    "compareWith": [
     "Pentest aprovado vs ações proibidas (DDoS)"
    ],
    "realWorldContext": "Empresas em SOC 2/PCI fazem pentests anuais — política da AWS facilita.",
    "commonMistakes": "Achar que sempre precisa aprovação — para os 8 serviços comuns, não precisa.",
    "tutorSeeds": [
     "Quais ferramentas são proibidas?",
     "Como reportar achados de bug bounty AWS?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["pentest","policy","compliance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
