INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-034', 'aws-clf', 'Qual a diferença ESSENCIAL entre AWS Organizations e AWS Control Tower?',
  '[{"id":"A","text":"São idênticos, com nomes diferentes em regiões diferentes"},{"id":"B","text":"Organizations é o serviço base para gerenciar múltiplas contas (OUs, SCPs, consolidated billing); Control Tower é uma camada de orquestração SOBRE o Organizations que entrega Landing Zone, guardrails preventive/detective prontos e Account Factory automatizado"},{"id":"C","text":"Control Tower substitui Organizations e não pode coexistir"},{"id":"D","text":"Organizations é grátis, Control Tower é pago"}]'::jsonb, 'B',
  '{
    "summary": "Control Tower é Organizations curado — Landing Zone + guardrails + Account Factory.",
    "whyCorrect": "AWS Organizations é o serviço base — gerencia múltiplas contas em árvore de OUs, aplica SCPs, faz consolidated billing. Control Tower opera SOBRE Organizations: provisiona uma Landing Zone (estrutura recomendada com contas Log Archive e Audit), aplica guardrails (preventive via SCPs, detective via Config Rules), automatiza criação de contas via Account Factory (com baseline). Control Tower USA Organizations internamente.",
    "whyWrong": {
     "A": "São produtos distintos com papéis claros.",
     "C": "Control Tower precisa de Organizations — não substitui, complementa.",
     "D": "Organizations e Control Tower têm cobranças (Control Tower pode incluir custos de Config, CloudTrail, SCPs)."
    },
    "keyConcept": "Control Tower = Organizations + Landing Zone + Guardrails + Account Factory",
    "compareWith": [
     "Organizations (base) vs Control Tower (curated)"
    ],
    "realWorldContext": "Greenfield AWS: começar com Control Tower em vez de montar Organizations + Config + CloudTrail manualmente.",
    "commonMistakes": "Querer usar os dois ''separadamente'' — Control Tower já gerencia o Organizations debaixo.",
    "tutorSeeds": [
     "O que são guardrails preventive vs detective?",
     "Como funciona Account Factory?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["control-tower","organizations","landing-zone"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
