INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-035', 'aws-clf', 'No AWS Control Tower, qual é a diferença entre guardrails ''preventive'' e ''detective''?',
  '[{"id":"A","text":"Preventive avisam por e-mail; detective bloqueiam"},{"id":"B","text":"São o mesmo conceito, apenas nomes diferentes"},{"id":"C","text":"Preventive bloqueiam ações via SCP antes de ocorrerem; detective detectam estados não conformes via Config rules e geram alerta"},{"id":"D","text":"Preventive são pagos; detective são grátis"}]'::jsonb, 'C',
  '{
    "summary": "Preventive guardrails = SCPs que bloqueiam; Detective guardrails = Config rules que detectam e reportam.",
    "whyCorrect": "Preventive guardrails são implementados como Service Control Policies (SCPs) que bloqueiam ações proibidas antes de ocorrerem (ex: ''disallow public S3 buckets''). Detective guardrails são Config Rules que detectam estados não conformes e geram findings/alerts via Security Hub e dashboard do Control Tower. Em conjunto formam o controle preventivo + detectivo.",
    "whyWrong": {
     "A": "Invertido — preventive bloqueia, detective detecta.",
     "B": "São conceitos distintos.",
     "D": "Custos não são o critério distintivo."
    },
    "keyConcept": "Preventive (SCP, bloqueia) vs Detective (Config rule, detecta)",
    "compareWith": [
     "Mandatory vs strongly recommended vs elective guardrails"
    ],
    "realWorldContext": "Pelo menos mandatory guardrails são aplicados em todo Landing Zone Control Tower.",
    "commonMistakes": "Achar que detective também bloqueia — só relata.",
    "tutorSeeds": [
     "Quais guardrails são mandatory?",
     "Posso desabilitar mandatory guardrail?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["control-tower","guardrails"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
