INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-036', 'aws-clf', 'Uma empresa quer estratégia multi-conta com isolamento total — produção, staging e desenvolvimento em CONTAS AWS SEPARADAS, gerenciadas centralizadamente. Qual benefício principal essa estratégia entrega?',
  '[{"id":"A","text":"Reduz custo total (sempre mais barato que conta única)"},{"id":"B","text":"Permite usar mais regiões AWS"},{"id":"C","text":"Aumenta a performance das instâncias EC2"},{"id":"D","text":"Isolamento de blast radius (incidente em dev não afeta prod), limites de quota por conta separados, IAM/SCP independentes, billing segregado e simplificação de compliance"}]'::jsonb, 'D',
  '{
    "summary": "Multi-account: isolamento de blast radius, quotas, IAM, billing e compliance — não custo nem performance.",
    "whyCorrect": "A estratégia multi-account separa workloads em contas distintas porque o LIMITE DE FALHA é a conta (quotas, IAM principals, SCP, blast radius). Incidente em dev (acidente, comprometimento, custo runaway) fica contido. Compliance frequentemente exige isolamento (PCI: cardholder data env separado). Billing segregado facilita cost allocation. SCPs aplicam policy diferente por OU/conta.",
    "whyWrong": {
     "A": "Custo não é diretamente reduzido por separar contas — pode até aumentar (NAT Gateway por conta, dados duplicados).",
     "B": "Número de regiões não muda com mais contas.",
     "C": "Performance independe de número de contas."
    },
    "keyConcept": "Multi-account — isolamento de blast radius, quota, IAM, billing, compliance",
    "compareWith": [
     "Multi-account vs multi-VPC em mesma conta"
    ],
    "realWorldContext": "Padrão AWS Well-Architected: contas separadas por workload + contas centrais (log archive, audit, network, shared services).",
    "commonMistakes": "Achar que multi-account economiza — pode até custar mais, mas o trade-off vale por isolamento.",
    "tutorSeeds": [
     "Quantas contas uma empresa média tem?",
     "Como compartilhar VPC entre contas?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["multi-account","isolation","blast-radius"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
