INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-037', 'aws-clf', 'Sobre AWS Backup Vault Lock, qual a diferença entre os modos ''Governance'' e ''Compliance''?',
  '[{"id":"A","text":"Governance: restringe via permissões IAM (admin com permissão especial pode alterar). Compliance: WORM imutável — após período de cooling-off, nem root user pode deletar/encurtar a lock"},{"id":"B","text":"Governance: imutável (WORM), nem root pode deletar. Compliance: pode ser modificado por admin com permissão"},{"id":"C","text":"São idênticos, nomes diferentes"},{"id":"D","text":"Governance é só para EBS; Compliance é só para RDS"}]'::jsonb, 'A',
  '{
    "summary": "Governance = IAM controla; Compliance = WORM imutável (nem root deleta após cooling-off).",
    "whyCorrect": "AWS Backup Vault Lock tem dois modos: GOVERNANCE — permite que principals com permissão IAM apropriada (backup:DeleteRecoveryPoint etc.) alterem/deletem; útil para evitar deleção acidental mas mantém flexibilidade. COMPLIANCE — modo WORM (Write Once Read Many) imutável; após o cooling-off period (mínimo 3 dias), NEM o root user pode encurtar, deletar ou alterar. Padrão para requisitos regulatórios (SEC 17a-4(f), FINRA, CFTC).",
    "whyWrong": {
     "B": "Invertido — Compliance é o WORM imutável.",
     "C": "Modos distintos com governança fundamentalmente diferente.",
     "D": "Vault Lock aplica-se a vault inteira, não a serviço específico."
    },
    "keyConcept": "Vault Lock Compliance = WORM imutável; Governance = controlado por IAM",
    "compareWith": [
     "Backup Vault Lock vs S3 Object Lock"
    ],
    "realWorldContext": "Bancos e healthcare frequentemente exigem Compliance mode para evitar até malicious insider.",
    "commonMistakes": "Habilitar Compliance mode sem cooling-off, descobrir que precisa deletar mas não consegue.",
    "tutorSeeds": [
     "O que é WORM?",
     "Cooling-off period — para quê?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["backup","vault-lock","worm","compliance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
