INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-038', 'aws-clf', 'Sobre AWS Trusted Advisor, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"Todos os checks (incluindo full security checks) estão disponíveis em qualquer plano de suporte"},{"id":"B","text":"Tem 7 checks core gratuitos (security e service limits básicos); o conjunto COMPLETO de checks (Cost Optimization, Performance, Security, Fault Tolerance, Service Limits) requer plano Business ou Enterprise Support"},{"id":"C","text":"É um substituto do Security Hub para multi-account"},{"id":"D","text":"Requer instalação de agent em cada EC2"}]'::jsonb, 'B',
  '{
    "summary": "Trusted Advisor: 7 checks core grátis; conjunto completo requer Business/Enterprise Support.",
    "whyCorrect": "AWS Trusted Advisor faz checks de best practices em 5 pilares (Cost Optimization, Performance, Security, Fault Tolerance, Service Limits). No plano Basic/Developer Support, apenas 7 checks core estão disponíveis (Security Groups - Specific Ports Unrestricted, IAM Use, MFA on Root, S3 Bucket Permissions, Service Limits etc.). Para o conjunto completo (dezenas de checks), é preciso Business Support ($100+/mês) ou Enterprise Support.",
    "whyWrong": {
     "A": "Falso — checks completos exigem upgrade de support.",
     "C": "Trusted Advisor não substitui Security Hub.",
     "D": "Trusted Advisor é agentless."
    },
    "keyConcept": "Trusted Advisor — 7 core checks grátis vs full checks no Business/Enterprise Support",
    "compareWith": [
     "Trusted Advisor (checks) vs Security Hub (findings) vs Config (state)"
    ],
    "realWorldContext": "Empresas pequenas usam os 7 core; empresas em Business Support exploram cost optimization checks (idle EC2, underutilized).",
    "commonMistakes": "Esperar todos os checks sem Business Support.",
    "tutorSeeds": [
     "Quais são os 7 core checks?",
     "Custo do Business Support?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["trusted-advisor","support-plans"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
