INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-039', 'aws-clf', 'Uma empresa quer que times de desenvolvimento provisionem apenas stacks pré-aprovados (templates CloudFormation curados pelo time de plataforma), garantindo compliance. Qual serviço entrega esse ''catálogo self-service''?',
  '[{"id":"A","text":"AWS Marketplace"},{"id":"B","text":"AWS Proton"},{"id":"C","text":"AWS Service Catalog"},{"id":"D","text":"AWS Systems Manager Documents"}]'::jsonb, 'C',
  '{
    "summary": "Service Catalog publica produtos CloudFormation curados como catálogo self-service.",
    "whyCorrect": "AWS Service Catalog permite que administradores publiquem ''produtos'' (CloudFormation templates ou Terraform Cloud configurations) num catálogo, definam constraints (regiões, tags obrigatórias, instance types permitidos) e disponibilizem para usuários launchearem self-service com permissão restrita. Garante que recursos sigam padrões de compliance/arquitetura.",
    "whyWrong": {
     "A": "Marketplace é para software de terceiros — não para templates internos.",
     "B": "Proton é mais voltado a plataformas de microsserviços para devs — overlap mas Service Catalog é o canônico para CLF.",
     "D": "SSM Documents executam ações operacionais, não provisionam stacks."
    },
    "keyConcept": "Service Catalog — produtos CloudFormation curados como catálogo self-service",
    "compareWith": [
     "Service Catalog vs Marketplace vs Proton"
    ],
    "realWorldContext": "Padrão em organizações reguladas — devs só conseguem provisionar via catálogo aprovado.",
    "commonMistakes": "Confundir com Marketplace (software pago de terceiros).",
    "tutorSeeds": [
     "Como publicar um produto no Service Catalog?",
     "Constraints disponíveis"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["service-catalog","governance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
