INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-040', 'aws-clf', 'Sobre certificações SOC (Service Organization Controls), qual a diferença essencial entre SOC 1, SOC 2 e SOC 3?',
  '[{"id":"A","text":"São idênticos, com nomes diferentes"},{"id":"B","text":"SOC 1 é grátis; SOC 2 e SOC 3 são pagos"},{"id":"C","text":"SOC é apenas para bancos europeus"},{"id":"D","text":"SOC 1 cobre controles relevantes para FINANCIAL REPORTING; SOC 2 cobre 5 trust principles (security, availability, processing integrity, confidentiality, privacy); SOC 3 é versão pública/marketing do SOC 2 (sem detalhes confidenciais)"}]'::jsonb, 'D',
  '{
    "summary": "SOC 1: financial reporting. SOC 2: 5 trust principles. SOC 3: versão pública.",
    "whyCorrect": "SOC 1 (SSAE 18) atesta controles relevantes para relatório financeiro do cliente — útil para auditoria SOX. SOC 2 cobre os Trust Service Criteria — Security (obrigatório), Availability, Processing Integrity, Confidentiality, Privacy — voltado para empresas de tecnologia/SaaS. SOC 3 é a versão pública resumida do SOC 2, sem detalhes confidenciais (pode ser publicado abertamente).",
    "whyWrong": {
     "A": "Frameworks distintos com escopos diferentes.",
     "B": "Não é questão de gratuidade.",
     "C": "Falso — AICPA dos EUA, usado globalmente."
    },
    "keyConcept": "SOC 1 (financial) vs SOC 2 (trust principles) vs SOC 3 (público)",
    "compareWith": [
     "SOC Type I (point-in-time) vs Type II (período)"
    ],
    "realWorldContext": "Vendas B2B SaaS frequentemente exigem SOC 2 Type II do fornecedor.",
    "commonMistakes": "Confundir SOC com SOX — SOX é a lei (Sarbanes-Oxley), SOC é o framework de attestation.",
    "tutorSeeds": [
     "O que é Type I vs Type II?",
     "Como AWS publica SOC 2?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'recall', '["soc","compliance-frameworks"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
