INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-041', 'aws-clf', 'Uma multinacional precisa de visão única dos findings de Security Hub das suas 40 contas AWS em múltiplas regiões. Qual feature do Security Hub entrega isso?',
  '[{"id":"A","text":"Security Hub cross-region aggregation com delegated administrator via Organizations agrega findings de múltiplas regiões em uma região central, em uma conta central"},{"id":"B","text":"Security Hub não suporta multi-region/multi-account — precisa de Lambda para agregar"},{"id":"C","text":"Habilitar GuardDuty na conta master"},{"id":"D","text":"Replicar tabelas DynamoDB do Security Hub"}]'::jsonb, 'A',
  '{
    "summary": "Security Hub cross-region aggregation + delegated admin = visão única multi-conta/multi-região.",
    "whyCorrect": "Security Hub suporta nativamente delegated administrator via AWS Organizations para multi-account, e cross-region aggregation que designa uma região como aggregator e replica findings de outras regiões para ela. Combinando, você tem uma única conta + uma única região vendo TUDO da organização.",
    "whyWrong": {
     "B": "Falso — feature nativa existe.",
     "C": "GuardDuty é distinto do Security Hub.",
     "D": "DynamoDB não é interface de Security Hub."
    },
    "keyConcept": "Security Hub delegated admin + cross-region aggregation",
    "compareWith": [
     "Cross-region aggregation vs duplicar consoles"
    ],
    "realWorldContext": "SOC central de uma multinacional usa exatamente essa configuração para single pane of glass.",
    "commonMistakes": "Achar que precisa rolar de região em região manualmente.",
    "tutorSeeds": [
     "Quais limites de cross-region aggregation?",
     "Custo da agregação"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["security-hub","multi-region","delegated-admin"]'::jsonb, 'ai-draft', 'active', now(), now()
)
