INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-042', 'aws-clf', 'Uma equipe recebeu denúncia de que um cliente está sofrendo problema de acesso ao site, mas o WAF (anexado ao CloudFront) parece estar bloqueando alguns IPs legítimos por engano. Qual ferramenta WAF permite TESTAR rules antes de aplicar em produção?',
  '[{"id":"A","text":"Não é possível — WAF rules sempre bloqueiam imediatamente"},{"id":"B","text":"WAF Sampled requests + Count mode (em vez de Block)"},{"id":"C","text":"Trusted Advisor checa WAF rules"},{"id":"D","text":"GuardDuty bloqueia tráfego ruim no WAF"}]'::jsonb, 'B',
  '{
    "summary": "WAF rules têm action Count — registra o match sem bloquear, ideal para validar antes de mudar para Block.",
    "whyCorrect": "WAF suporta action COUNT em cada rule — quando a rule matcha, ela é contabilizada (visível em CloudWatch metrics + sampled requests) mas NÃO bloqueia. Permite testar managed rule groups ou novas custom rules em produção observando false positives antes de mudar action para Block. Sampled requests mostra ~100 requests recentes que matcharam para análise.",
    "whyWrong": {
     "A": "Falso — Count mode existe exatamente para isso.",
     "C": "Trusted Advisor não testa WAF rules.",
     "D": "GuardDuty não interage com WAF rules diretamente."
    },
    "keyConcept": "WAF Count action + sampled requests — teste sem bloqueio",
    "compareWith": [
     "Count vs Block vs Allow vs CAPTCHA"
    ],
    "realWorldContext": "Pratique padrão antes de habilitar qualquer managed rule group em produção.",
    "commonMistakes": "Habilitar Block direto e bloquear usuários legítimos.",
    "tutorSeeds": [
     "Como ler sampled requests?",
     "Quais métricas o WAF emite?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'troubleshoot', '["waf","count-mode","troubleshoot"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
