INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-043', 'aws-clf', 'Uma equipe ligou GuardDuty na região eu-west-1 e está confusa porque não vê findings de atividades em outras regiões. Qual a explicação?',
  '[{"id":"A","text":"GuardDuty é serviço global — deve haver bug"},{"id":"B","text":"Findings demoram 30 dias para aparecer"},{"id":"C","text":"GuardDuty é habilitado e opera por região — para cobertura completa, é preciso habilitar em CADA região da conta onde haja workload (ou usar delegated admin + auto-enable)"},{"id":"D","text":"Falta habilitar S3 Protection"}]'::jsonb, 'C',
  '{
    "summary": "GuardDuty é regional — habilitar em cada região onde há workload.",
    "whyCorrect": "GuardDuty é um serviço REGIONAL — habilitação e findings são por região. Se você só habilitou em eu-west-1, atividades em us-east-1 (ou outras) NÃO são analisadas. Best practice: habilitar em todas as regiões usadas, ou ainda melhor — usar delegated admin do Organizations com auto-enable on all regions, garantindo cobertura mesmo para regiões ''fantasma'' onde alguém pode subir workload.",
    "whyWrong": {
     "A": "GuardDuty não é global.",
     "B": "Findings aparecem em minutos a horas, não 30 dias.",
     "D": "S3 Protection não tem a ver com cobertura regional."
    },
    "keyConcept": "GuardDuty — regional por habilitação, sem visão global automática",
    "compareWith": [
     "Serviços regionais (GuardDuty/Config/Inspector) vs globais (IAM/CloudFront/Route53)"
    ],
    "realWorldContext": "Atacantes frequentemente sobem recursos em regiões não monitoradas (us-gov-west, ap-south) para minerar cripto sem ser detectado.",
    "commonMistakes": "Achar que habilitar em 1 região cobre toda conta.",
    "tutorSeeds": [
     "Como detectar uso de região nova?",
     "SCP para limitar regiões usadas"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'medium', 'troubleshoot', '["guardduty","regional","coverage"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
