INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-044', 'aws-clf', 'Sobre AWS Firewall Manager, qual a função principal?',
  '[{"id":"A","text":"É a versão renomeada do Security Groups"},{"id":"B","text":"Substitui o GuardDuty para detecção de ameaças"},{"id":"C","text":"É um proxy de IDS/IPS open source"},{"id":"D","text":"Gerencia políticas de segurança (WAF rules, Shield Advanced, Security Groups, Network Firewall, Route 53 Resolver DNS Firewall) centralmente entre múltiplas contas e regiões via Organizations"}]'::jsonb, 'D',
  '{
    "summary": "Firewall Manager = política central de WAF/Shield/SG/Network Firewall em multi-account via Organizations.",
    "whyCorrect": "AWS Firewall Manager é um serviço de gestão central de políticas de segurança em escala. Permite ao security team definir UMA política — Web ACL do WAF, proteções Shield Advanced, Security Group baseline, Network Firewall rules, Route 53 Resolver DNS Firewall — e aplicar automaticamente em todas as contas/recursos de uma OU. Requer Organizations habilitada e a conta de Firewall Manager designada como admin.",
    "whyWrong": {
     "A": "Falso — Security Groups continuam existindo como antes.",
     "B": "Falso — Firewall Manager não detecta ameaças por análise.",
     "C": "Falso — não é IDS/IPS open source."
    },
    "keyConcept": "Firewall Manager — gestão central de policies WAF/Shield/SG/Network Firewall",
    "compareWith": [
     "Firewall Manager (policy) vs WAF/Shield (enforcement)"
    ],
    "realWorldContext": "Em organizações 50+ contas, Firewall Manager garante baseline uniforme — não depender de cada conta aplicar manualmente.",
    "commonMistakes": "Confundir Firewall Manager (gerencia policies) com Network Firewall (faz inspeção).",
    "tutorSeeds": [
     "Quais policy types Firewall Manager suporta?",
     "Diferença para SCP?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'hard', 'best-practice', '["firewall-manager","multi-account"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
