INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-sec-v5-045', 'aws-clf', 'Uma equipe terminou de migrar workload sensível para AWS e quer estabelecer um Landing Zone com guardrails, conta de log archive separada, conta de audit, factory de contas — TUDO automatizado em poucos cliques. Qual abordagem é a MAIS rápida e padrão?',
  '[{"id":"A","text":"Habilitar AWS Control Tower em uma conta de management, deixar provisionar a Landing Zone e usar Account Factory para criar contas novas"},{"id":"B","text":"Criar manualmente AWS Organizations + SCPs + Config + CloudTrail + IAM Identity Center separadamente"},{"id":"C","text":"Contratar AWS Professional Services obrigatoriamente"},{"id":"D","text":"Usar apenas AWS Artifact"}]'::jsonb, 'A',
  '{
    "summary": "AWS Control Tower entrega Landing Zone + guardrails + Account Factory + log archive/audit em poucos cliques.",
    "whyCorrect": "AWS Control Tower é a opção mais rápida e padrão para greenfield AWS — provisiona automaticamente uma Landing Zone com Organizations, OUs (Security, Sandbox, Workloads), contas centrais (Log Archive recebendo CloudTrail+Config de todas as contas, Audit com Security Hub/GuardDuty), guardrails mandatory + recommended, IAM Identity Center configurado e Account Factory que cria contas novas com baseline padronizado.",
    "whyWrong": {
     "B": "Funciona mas leva semanas e é propenso a erros — Control Tower automatiza.",
     "C": "ProServ é opção, mas Control Tower entrega o padrão self-service.",
     "D": "Artifact só baixa documentos — não monta Landing Zone."
    },
    "keyConcept": "Control Tower — Landing Zone automatizada para greenfield AWS",
    "compareWith": [
     "Control Tower vs Landing Zone manual"
    ],
    "realWorldContext": "Quase todo greenfield AWS pós-2020 começa com Control Tower em vez de Landing Zone Accelerator manual.",
    "commonMistakes": "Reinventar Landing Zone manualmente e perder semanas com setup já entregue pronto.",
    "tutorSeeds": [
     "O que é Landing Zone Accelerator?",
     "Quais OUs padrão Control Tower cria?"
    ]
   }'::jsonb,
  'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["control-tower","landing-zone","multi-account"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
