INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-001', 'aws-clf', 'Uma equipe precisa escolher um tipo de instância EC2 para um workload de processamento de imagens com alto uso de CPU mas pouca memória. Qual família de instância é a mais adequada?',
  '[{"id":"A","text":"Família C (compute-optimized)"},{"id":"B","text":"Família M (uso geral, balanceada)"},{"id":"C","text":"Família R (memory-optimized)"},{"id":"D","text":"Família T (burstable performance)"}]'::jsonb, 'A',
  '{
    "summary": "Família C (Compute-Optimized) tem maior razão vCPU/preço, ideal para CPU-bound workloads como processamento de mídia, batch e HPC leve.",
    "whyCorrect": "Família C (Compute-Optimized) tem maior razão vCPU/preço, ideal para CPU-bound workloads como processamento de mídia, batch e HPC leve.",
    "whyWrong": {
     "B": "M é balanceada [extra: desperdiça custo quando não usa toda a RAM]",
     "C": "R é memory-optimized para in-memory DB",
     "D": "T é burstable, sofre throttling em uso sustentado."
    },
    "keyConcept": "Regra: matchear família ao gargalo dominante (C=CPU, R=RAM, M=balanceada, T=picos curtos).",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: matchear família ao gargalo dominante (C=CPU, R=RAM, M=balanceada, T=picos curtos)?",
     "Quais cenários reais aplicam Regra: matchear família ao gargalo dominante (C=CPU, R=RAM, M=balanceada, T=picos curtos)?",
     "Como CPU-bound se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["ec2","instance-types","compute"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
