INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-003', 'aws-clf', 'Uma empresa quer pré-instalar uma stack customizada (SO patched + agents internos + libs) e bootar novas instâncias EC2 rapidamente com essa configuração. Qual recurso AWS endereça esse caso?',
  '[{"id":"A","text":"Launch Template apenas"},{"id":"B","text":"User data script que instala tudo no boot"},{"id":"C","text":"Custom AMI (Amazon Machine Image)"},{"id":"D","text":"Systems Manager State Manager"}]'::jsonb, 'C',
  '{
    "summary": "AMI captura snapshot do volume root + metadata — novas instâncias bootam em segundos já com a stack pronta, sem reinstalar nada.",
    "whyCorrect": "AMI captura snapshot do volume root + metadata — novas instâncias bootam em segundos já com a stack pronta, sem reinstalar nada.",
    "whyWrong": {
     "A": "Launch Template referencia uma AMI mas não a substitui",
     "B": "user data instala no boot (lento e propenso a falhas)",
     "D": "SSM State Manager garante configuração após o boot, não acelera."
    },
    "keyConcept": "Regra: imutável + rápido = AMI; mutável + dinâmico = user data/SSM.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: imutável + rápido = AMI; mutável + dinâmico = user data/SSM?",
     "Quais cenários reais aplicam Regra: imutável + rápido = AMI; mutável + dinâmico = user data/SSM?",
     "Como AMI se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["ec2","ami","automation"]'::jsonb, 'ai-draft', 'active', now(), now()
)
