INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-004', 'aws-clf', 'Uma equipe precisa de storage efêmero de altíssima performance (NVMe local) para cache de um job de ML que pode ser recriado a qualquer momento. Qual opção atende?',
  '[{"id":"A","text":"EBS gp3 attachado à instância"},{"id":"B","text":"EBS io2 Block Express"},{"id":"C","text":"EFS montado via NFS"},{"id":"D","text":"Instance Store (storage local efêmero)"}]'::jsonb, 'D',
  '{
    "summary": "Instance Store é storage físico ligado ao host — latência mínima e IOPS altíssimas — mas o dado é perdido se a instância para/falha.",
    "whyCorrect": "Instance Store é storage físico ligado ao host — latência mínima e IOPS altíssimas — mas o dado é perdido se a instância para/falha. Ideal para cache/scratch onde a recriação é trivial.",
    "whyWrong": {
     "B": "gp3/io2 são block storage em rede (resiliente, lento comparado a NVMe local)",
     "A": "EBS gp3 é persistente e baseado em rede (network-attached) — tem latência maior que NVMe local e custa por GB+IOPS provisionados. Para cache de ML que pode ser recriado, EBS é overkill: paga por persistência que não importa e perde performance vs Instance Store. EBS seria correto para dados que devem sobreviver a stop/terminate.",
     "C": "EFS é file system NFS compartilhado e elástico — latência ainda maior que EBS (acessa via rede TCP), throughput variável e custo por GB armazenado. Adequado para acesso compartilhado entre múltiplas instâncias, não para cache local de altíssima performance. EFS seria a resposta se múltiplas instâncias precisassem ler/escrever o mesmo cache."
    },
    "keyConcept": "Regra: ephemeral + speed = Instance Store; persistent = EBS; shared = EFS.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: ephemeral + speed = Instance Store; persistent = EBS; shared = EFS?",
     "Quais cenários reais aplicam Regra: ephemeral + speed = Instance Store; persistent = EBS; shared = EFS?",
     "Como IOPS se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["ec2","instance-store","ebs"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
