INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-005', 'aws-clf', 'Uma aplicação web tem tráfego previsível durante o dia e zero à noite. A equipe quer ajustar automaticamente o número de instâncias EC2. Qual serviço deve ser usado?',
  '[{"id":"A","text":"AWS Auto Scaling Group (ASG) com scaling policies"},{"id":"B","text":"Elastic Load Balancer com health checks"},{"id":"C","text":"AWS Lambda invocando a EC2 API"},{"id":"D","text":"Aumentar instance type via vertical scaling"}]'::jsonb, 'A',
  '{
    "summary": "ASG mantém capacidade desejada, faz scaling horizontal por métricas (CPU, request count, scheduled), substitui instâncias unhealthy e integra com ELB.",
    "whyCorrect": "ASG mantém capacidade desejada, faz scaling horizontal por métricas (CPU, request count, scheduled), substitui instâncias unhealthy e integra com ELB.",
    "whyWrong": {
     "C": "Lambda custom funciona mas reinventa a roda",
     "D": "vertical scaling exige stop/start e não automatiza.",
     "B": "ELB faz LOAD BALANCING (distribui tráfego entre targets healthy) e health checks — não decide quando criar/destruir instâncias. ELB sozinho não escala capacidade; precisa do ASG para isso. ELB seria correto para ''distribuir requisições entre as instâncias existentes'', mas o requisito é ''ajustar AUTOMATICAMENTE o NÚMERO de instâncias''."
    },
    "keyConcept": "Regra: capacidade dinâmica horizontal = ASG; distribuição = ELB; ambos juntos = padrão recomendado.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: capacidade dinâmica horizontal = ASG; distribuição = ELB; ambos juntos = padrão recomendado?",
     "Quais cenários reais aplicam Regra: capacidade dinâmica horizontal = ASG; distribuição = ELB; ambos juntos = padrão recomendado?",
     "Como ASG se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["ec2","auto-scaling","elasticity"]'::jsonb, 'ai-draft', 'active', now(), now()
)
