INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-006', 'aws-clf', 'Uma aplicação HTTP precisa rotear tráfego para diferentes target groups baseado no path da URL (/api/* vs /static/*). Qual tipo de Elastic Load Balancer atende?',
  '[{"id":"A","text":"Network Load Balancer (NLB)"},{"id":"B","text":"Application Load Balancer (ALB)"},{"id":"C","text":"Gateway Load Balancer (GWLB)"},{"id":"D","text":"Classic Load Balancer (CLB)"}]'::jsonb, 'B',
  '{
    "summary": "ALB opera na camada 7 (HTTP/HTTPS) e suporta routing avançado por path, host, header e query string.",
    "whyCorrect": "ALB opera na camada 7 (HTTP/HTTPS) e suporta routing avançado por path, host, header e query string.",
    "whyWrong": {
     "C": "GWLB é para appliances de inspeção",
     "A": "Network Load Balancer opera em camada 4 (TCP/UDP) — não inspeciona conteúdo HTTP nem faz routing por path/host/header. NLB encaminha conexões TCP/UDP por target group baseado em listener (porta), não por URL path. NLB seria correto para ''load balancing TCP de altíssima performance'' ou ''IP estático''.",
     "D": "Classic Load Balancer é a geração legada do ELB — suporta L4/L7 básico mas NÃO faz path-based routing nativo (apenas listener por porta). AWS recomenda migrar de CLB para ALB/NLB. CLB seria ''legado'' não-recomendado mesmo para casos simples atuais."
    },
    "keyConcept": "Regra: L7 + roteamento por conteúdo = ALB; L4 + ultra performance = NLB; appliance insertion = GWLB.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: L7 + roteamento por conteúdo = ALB; L4 + ultra performance = NLB; appliance insertion = GWLB?",
     "Quais cenários reais aplicam Regra: L7 + roteamento por conteúdo = ALB; L4 + ultra performance = NLB; appliance insertion = GWLB?",
     "Como ALB se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["elb","alb","networking"]'::jsonb, 'ai-draft', 'active', now(), now()
)
