INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-007', 'aws-clf', 'Um serviço de gaming precisa de latência ultrabaixa via TCP e IP estático para registro em firewalls de clientes. Qual ELB é o mais adequado?',
  '[{"id":"A","text":"Application Load Balancer (ALB)"},{"id":"B","text":"Gateway Load Balancer (GWLB)"},{"id":"C","text":"Network Load Balancer (NLB)"},{"id":"D","text":"Classic Load Balancer (CLB)"}]'::jsonb, 'C',
  '{
    "summary": "NLB opera em L4 (TCP/UDP/TLS), entrega latência de milissegundos baixos e oferece Elastic IPs estáticos por AZ — perfeito para clientes que precisam allowlist de IPs.",
    "whyCorrect": "NLB opera em L4 (TCP/UDP/TLS), entrega latência de milissegundos baixos e oferece Elastic IPs estáticos por AZ — perfeito para clientes que precisam allowlist de IPs.",
    "whyWrong": {
     "B": "GWLB é para tráfego de inspeção",
     "A": "ALB opera em L7 (HTTP/HTTPS) com latência adicional pelo TLS termination e processamento de headers — tipicamente 20-50ms a mais que NLB. ALB também NÃO oferece IPs estáticos por AZ (usa DNS A records que mudam). Para gaming TCP com latência crítica e IP allowlisting, NLB é o construto correto.",
     "D": "Classic Load Balancer é geração legada e não recomendada para novos workloads. Mesmo se usado, latência e performance ficam aquém do NLB moderno; não tem IPs estáticos garantidos. AWS recomenda NLB para TCP de alta performance, deprecando CLB para casos novos."
    },
    "keyConcept": "Regra: TCP + IP estático + alta performance = NLB.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: TCP + IP estático + alta performance = NLB?",
     "Quais cenários reais aplicam Regra: TCP + IP estático + alta performance = NLB?",
     "Como NLB se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["elb","nlb","networking"]'::jsonb, 'ai-draft', 'active', now(), now()
)
