INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-008', 'aws-clf', 'Uma empresa de segurança quer inserir um appliance virtual de firewall de terceiros no caminho do tráfego que passa por sua VPC. Qual serviço facilita essa inserção transparente?',
  '[{"id":"A","text":"Application Load Balancer com regras avançadas"},{"id":"B","text":"Network Load Balancer com TLS termination"},{"id":"C","text":"AWS WAF"},{"id":"D","text":"Gateway Load Balancer (GWLB)"}]'::jsonb, 'D',
  '{
    "summary": "GWLB usa o protocolo GENEVE para encaminhar tráfego transparentemente a appliances virtuais (IDS/IPS/firewall) com escala automática e healthchecks.",
    "whyCorrect": "GWLB usa o protocolo GENEVE para encaminhar tráfego transparentemente a appliances virtuais (IDS/IPS/firewall) com escala automática e healthchecks.",
    "whyWrong": {
     "A": "ALB inspeciona HTTP em L7 e roteia para targets — não tem mecanismo de inserir um appliance virtual transparentemente no path do tráfego de uma VPC. ALB faria sentido para ''distribuir tráfego HTTP entre múltiplos servidores web'', não para passar todo tráfego de uma subnet por um firewall third-party.",
     "B": "NLB opera em L4 distribuindo conexões TCP/UDP — não tem mecanismo de transparent traffic insertion via GENEVE para appliances de segurança. NLB seria correto para load balancing de um firewall, mas não para inserir o firewall em todo o path de uma VPC de forma transparente.",
     "C": "AWS WAF é firewall L7 managed pela AWS para proteger aplicações web em ALB/CloudFront/API Gateway contra OWASP Top 10 — NÃO é mecanismo para inserir appliance de terceiros. WAF tem regras nativas; GWLB encaminha tráfego a aparências externas (Palo Alto, Fortinet, Check Point, etc.)."
    },
    "keyConcept": "Regra: inserir appliances de terceiros no path = GWLB.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: inserir appliances de terceiros no path = GWLB?",
     "Quais cenários reais aplicam Regra: inserir appliances de terceiros no path = GWLB?",
     "Como GWLB se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["elb","gwlb","security"]'::jsonb, 'ai-draft', 'active', now(), now()
)
