INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-009', 'aws-clf', 'Sobre EC2 Auto Scaling Groups, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"ASGs garantem que o número de instâncias seja exatamente o Desired Capacity, substituindo instâncias unhealthy"},{"id":"B","text":"ASGs fazem somente scaling vertical (mudam o tipo da instância)"},{"id":"C","text":"ASGs requerem obrigatoriamente um ALB associado"},{"id":"D","text":"ASGs só funcionam dentro de uma única AZ"}]'::jsonb, 'A',
  '{
    "summary": "ASG mantém Desired Capacity; instâncias que falham healthcheck (EC2 ou ELB) são terminadas e substituídas.",
    "whyCorrect": "ASG mantém Desired Capacity; instâncias que falham healthcheck (EC2 ou ELB) são terminadas e substituídas. Suporta scaling horizontal automático em múltiplas AZs para HA.",
    "whyWrong": {
     "B": "ASG é horizontal (mais/menos instâncias), não vertical",
     "C": "ASG NÃO requer ALB obrigatoriamente — pode operar sozinho, com NLB, ou com qualquer combinação. ELB é integração comum mas opcional. ASG funciona com qualquer arquitetura, incluindo workers SQS sem balanceador algum.",
     "D": "ASG SUPORTA múltiplas AZs — na verdade, é a configuração recomendada para HA. ASG distribui instâncias entre AZs configuradas e mantém balanceamento. Limitar a uma AZ é antipattern. ASG cross-AZ é base do design ''resilient by default''."
    },
    "keyConcept": "Regra: ASG = self-healing + horizontal scaling + multi-AZ.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: ASG = self-healing + horizontal scaling + multi-AZ?",
     "Quais cenários reais aplicam Regra: ASG = self-healing + horizontal scaling + multi-AZ?",
     "Como ASG se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["ec2","auto-scaling","high-availability"]'::jsonb, 'ai-draft', 'active', now(), now()
)
