INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-012', 'aws-clf', 'Uma equipe precisa fazer um workload de Windows Server licenciado por core físico em conformidade com a licença BYOL do fornecedor. Qual modelo de compra EC2 é necessário?',
  '[{"id":"A","text":"Reserved Instance Standard"},{"id":"B","text":"Spot Instance com hibernation"},{"id":"C","text":"On-Demand t3.large"},{"id":"D","text":"Dedicated Host"}]'::jsonb, 'D',
  '{
    "summary": "Dedicated Host dá visibilidade do servidor físico (sockets, cores) — necessário para licenças BYOL ligadas a hardware (Windows, Oracle, SQL Server).",
    "whyCorrect": "Dedicated Host dá visibilidade do servidor físico (sockets, cores) — necessário para licenças BYOL ligadas a hardware (Windows, Oracle, SQL Server).",
    "whyWrong": {
     "B": "RI/Spot/On-Demand rodam em hardware compartilhado abstrato (Dedicated Instance compartilha host mas não expõe specs) Spot não serve para licenças estáveis.",
     "A": "Reserved Instance Standard é commitment de pricing (1-3 anos) por desconto em On-Demand — NÃO dá visibilidade do hardware físico (sockets/cores) necessária para BYOL. RIs rodam em tenancy padrão (multi-tenant) onde cliente não vê o hardware. RIs seriam corretas para ''reduzir custo de uso steady-state em workload sem requisitos de licenciamento''.",
     "C": "On-Demand t3.large é multi-tenant em hardware compartilhado — cliente não vê sockets/cores, AWS pode mover a instância entre hosts. Não atende requisito de BYOL por core físico. On-Demand seria correto se não houvesse exigência de licenciamento por hardware."
    },
    "keyConcept": "Regra: BYOL por core/socket = Dedicated Host.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: BYOL por core/socket = Dedicated Host?",
     "Quais cenários reais aplicam Regra: BYOL por core/socket = Dedicated Host?",
     "Como BYOL se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["ec2","dedicated-host","licensing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
