INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-013', 'aws-clf', 'Uma startup quer rodar uma função simples acionada por upload em S3 sem gerenciar servidor algum. A função roda em milissegundos. Qual serviço é o mais adequado?',
  '[{"id":"A","text":"AWS Lambda"},{"id":"B","text":"Amazon EC2 com user data"},{"id":"C","text":"AWS Fargate"},{"id":"D","text":"Amazon EKS"}]'::jsonb, 'A',
  '{
    "summary": "Lambda é FaaS: sem servidor para gerenciar, paga por requisições + GB-segundo, integrado nativamente com S3 events.",
    "whyCorrect": "Lambda é FaaS: sem servidor para gerenciar, paga por requisições + GB-segundo, integrado nativamente com S3 events.",
    "whyWrong": {
     "C": "Fargate é serverless mas para containers de longa duração",
     "B": "EC2 com user data exige provisionar instância, mantê-la rodando 24/7 (custo fixo), gerenciar OS, escalar para o pico — não é serverless. Para função simples acionada por evento, EC2 é overkill e antipadrão (paga ociosa). EC2 seria correto para apps que precisam de processo long-running.",
     "D": "Amazon EKS é Kubernetes managed — exige cluster, nodes (ou Fargate), pods, deployments. Para ''função simples acionada por upload'', criar um cluster K8s é desproporcional ao problema. EKS seria correto para arquitetura microsserviços complexa, não para uma função pontual."
    },
    "keyConcept": "Regra: event-driven + curta duração = Lambda.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: event-driven + curta duração = Lambda?",
     "Quais cenários reais aplicam Regra: event-driven + curta duração = Lambda?",
     "Como GB-segundo se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["lambda","serverless","s3-events"]'::jsonb, 'ai-draft', 'active', now(), now()
)
