INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-014', 'aws-clf', 'Sobre o modelo de billing do AWS Lambda, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"Cobra por hora de execução, similar a EC2"},{"id":"B","text":"Cobra por número de invocações e por GB-segundo de duração"},{"id":"C","text":"Cobra fixo mensal por função criada"},{"id":"D","text":"Cobra por largura de banda de saída apenas"}]'::jsonb, 'B',
