INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-015', 'aws-clf', 'Um time observa que a primeira invocação de uma função Lambda após período de inatividade leva ~3 segundos, enquanto subsequentes levam 50 ms. Qual fenômeno está ocorrendo?',
  '[{"id":"A","text":"Throttling por concurrency limit"},{"id":"B","text":"Falha de rede temporária no VPC"},{"id":"C","text":"Cold start (init do ambiente de execução)"},{"id":"D","text":"Erro de permissão IAM cacheado"}]'::jsonb, 'C',
  '{
    "summary": "Cold start ocorre quando Lambda precisa criar um novo execution environment: download do código, init do runtime e execução do código global (fora do handler).",
    "whyCorrect": "Cold start ocorre quando Lambda precisa criar um novo execution environment: download do código, init do runtime e execução do código global (fora do handler). Subsequentes reusam o environment quente.",
    "whyWrong": {
     "A": "Throttling rejeita invocações com 429",
     "B": "erro de rede causa timeout, não slow-start",
     "D": "IAM dá erro de permissão, não latência variável."
    },
