INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-017', 'aws-clf', 'Uma equipe quer rodar uma aplicação em container Docker que sobe sob demanda, sem gerenciar EC2 nem nodes Kubernetes, com billing por uso. Qual serviço é o mais adequado?',
  '[{"id":"A","text":"AWS Fargate"},{"id":"B","text":"Amazon ECS com launch type EC2"},{"id":"C","text":"Amazon EKS no modo self-managed"},{"id":"D","text":"AWS Batch com EC2"}]'::jsonb, 'A',
  '{
    "summary": "Fargate é serverless containers — você define CPU/RAM, ele provisiona e cobra por vCPU-s + GB-s.",
    "whyCorrect": "Fargate é serverless containers — você define CPU/RAM, ele provisiona e cobra por vCPU-s + GB-s. Sem nodes para gerenciar. Funciona com ECS ou EKS.",
    "whyWrong": {
     "C": "EKS self-managed exige operar nodes",
     "D": "Batch é para workloads de batch específicos.",
     "B": "ECS com launch type EC2 exige o cliente gerenciar o cluster de instâncias EC2 (provisioning, scaling, patching dos hosts) — não é ''sem gerenciar EC2''. Cliente paga pelas EC2 mesmo ociosas e é responsável por capacidade. Seria correto se o cliente preferisse controle total sobre os hosts (custo otimizado para workloads steady)."
    },
    "keyConcept": "Regra: containers serverless = Fargate.",
