INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-019', 'aws-clf', 'Sobre AWS Lambda, qual limitação é VERDADEIRA?',
  '[{"id":"A","text":"Suporta apenas linguagens interpretadas (Python, Node.js)"},{"id":"B","text":"Memória mínima é 1 GB"},{"id":"C","text":"Tempo máximo de execução por invocação é 15 minutos"},{"id":"D","text":"Não suporta variáveis de ambiente"}]'::jsonb, 'C',
  '{
    "summary": "Lambda timeout é configurável de 1s a 900s (15 min).",
    "whyCorrect": "Lambda timeout é configurável de 1s a 900s (15 min). Para mais que isso usa-se Step Functions, Fargate ou ECS.",
    "whyWrong": {
     "A": "Suporta Python, Node.js, Java, .NET, Go, Ruby + custom runtimes via container images",
     "B": "memória vai de 128 MB a 10 GB",
     "D": "Lambda SUPORTA variáveis de ambiente (até 4KB total, key/value), com encryption opcional via KMS. São amplamente usadas para configuração (database URL, feature flags). Esta opção é factualmente falsa. A limitação verdadeira é o timeout máximo de 15 minutos."
    },
    "keyConcept": "Regra: workload > 15 min = não-Lambda.",
