INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-025', 'aws-clf', 'Uma equipe usa Amazon ECS e precisa decidir entre launch type EC2 e Fargate. Qual cenário favorece Fargate?',
  '[{"id":"A","text":"Aplicações stateless de tráfego variável onde a equipe quer zero gestão de hosts"},{"id":"B","text":"Workload com GPUs para deep learning training"},{"id":"C","text":"Sistemas que requerem acesso root ao host EC2"},{"id":"D","text":"Workloads que excedem 120 GB de memória por task"}]'::jsonb, 'A',
  '{
    "summary": "Fargate elimina gestão de capacidade (sem nodes, sem patching), ideal para microsserviços com tráfego variável.",
    "whyCorrect": "Fargate elimina gestão de capacidade (sem nodes, sem patching), ideal para microsserviços com tráfego variável.",
    "whyWrong": {
     "C": "host root só em EC2 mode",
     "B": "GPU workloads (deep learning training) requerem instâncias EC2 com GPU específicas (P3, P4, G5) — Fargate NÃO suporta GPU. Para training, launch type EC2 com EKS/ECS e instâncias GPU é mandatório. Fargate seria a escolha errada aqui.",
     "D": "Fargate tem limites de recursos por task: até 16 vCPU e 120GB de memória atualmente. Workloads que excedem 120GB de memória por task NÃO cabem em Fargate, exigindo EC2 launch type com instâncias maiores (R5, X1, etc.). Limite arquitetural de Fargate."
    },
    "keyConcept": "Regra: gestão zero = Fargate; controle total/GPU/hardware specific = EC2.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: gestão zero = Fargate; controle total/GPU/hardware specific = EC2?",
     "Quais cenários reais aplicam Regra: gestão zero = Fargate; controle total/GPU/hardware specific = EC2?"
