INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-027', 'aws-clf', 'Uma equipe quer migrar do ECS para EKS gradualmente, mantendo cargas em Fargate sem nodes. Isso é possível?',
  '[{"id":"A","text":"Não — Fargate só funciona com ECS"},{"id":"B","text":"Sim, mas requer cluster EKS Anywhere on-prem"},{"id":"C","text":"Sim — EKS Fargate executa pods Kubernetes em Fargate sem nodes EC2"},{"id":"D","text":"Não — EKS exige obrigatoriamente node groups EC2"}]'::jsonb, 'C',
