INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-028', 'aws-clf', 'Uma empresa quer armazenar 5 PB de arquivos imutáveis acessados raramente (uma vez por mês) mas com retrieval em segundos quando preciso. Qual storage class S3 é a mais adequada por custo?',
