INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-030', 'aws-clf', 'Uma empresa não sabe prever padrão de acesso de seus objetos S3 (alguns vão ser acessados, outros não) e quer otimização automática sem retrieval fees imprevisíveis. Qual storage class usar?',
  '[{"id":"A","text":"S3 Standard"},{"id":"B","text":"S3 Intelligent-Tiering"},{"id":"C","text":"S3 Glacier Instant Retrieval"},{"id":"D","text":"S3 Standard-IA"}]'::jsonb, 'B',
  '{
    "summary": "Intelligent-Tiering monitora padrão de acesso por objeto e move automaticamente entre tiers (Frequent/Infrequent/Archive Instant/Archive/Deep Archive), sem retrieval fees nas tiers principais — pequena fee de monitoring por objeto.",
    "whyCorrect": "Intelligent-Tiering monitora padrão de acesso por objeto e move automaticamente entre tiers (Frequent/Infrequent/Archive Instant/Archive/Deep Archive), sem retrieval fees nas tiers principais — pequena fee de monitoring por objeto.",
    "whyWrong": {
     "A": "Standard é caro se a maioria é frio Standard-IA cobra retrieval (caro se errar prediction)",
     "C": "Glacier IR é para arquivamento previsível.",
     "D": "S3 Standard-IA é para acesso infrequente PREVISÍVEL (objeto X é raramente acessado) — exige decisão antecipada sobre cada objeto e cobra retrieval fee + minimum 30 dias de storage. Quando o padrão de acesso é DESCONHECIDO, decisão antecipada pode estar errada (objeto frequente em IA pagaria muito retrieval). Intelligent-Tiering elimina essa aposta."
    },
    "keyConcept": "Regra: padrão desconhecido = Intelligent-Tiering.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: padrão desconhecido = Intelligent-Tiering?",
