INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-034', 'aws-clf', 'Sobre Amazon S3, qual afirmação está CORRETA sobre a durabilidade?',
  '[{"id":"A","text":"S3 Standard tem durabilidade de 99.9% (three nines)"},{"id":"B","text":"S3 Standard tem durabilidade de 99.999999999% (eleven nines) por objeto/ano"},{"id":"C","text":"S3 não garante durabilidade — é responsabilidade do cliente replicar"},{"id":"D","text":"S3 tem durabilidade apenas se Versioning estiver habilitado"}]'::jsonb, 'B',
  '{
    "summary": "S3 Standard (e outras classes regionais) oferece 11 noves de durabilidade — equivalente a perda esperada de ~1 objeto a cada 10 milhões em 10 mil anos.",
    "whyCorrect": "S3 Standard (e outras classes regionais) oferece 11 noves de durabilidade — equivalente a perda esperada de ~1 objeto a cada 10 milhões em 10 mil anos. AWS replica objetos em múltiplas AZs internamente.",
    "whyWrong": {
     "A": "classes One Zone têm a mesma durabilidade desde que a AZ não falhe.",
     "D": "Durabilidade é nativa, não depende de Versioning",
     "C": "S3 GARANTE durabilidade nativamente — replicação interna entre múltiplas AZs com checksums automáticos. Cliente não precisa replicar manualmente para ter 11 nines de durabilidade. Esta opção contradiz documentação oficial. Cliente pode adicionar Cross-Region Replication para DR, mas isso é além dos 11 nines básicos."
    },
    "keyConcept": "Regra: durabilidade S3 = 11 nines, padrão da indústria.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: durabilidade S3 = 11 nines, padrão da indústria?",
     "Quais cenários reais aplicam Regra: durabilidade S3 = 11 nines, padrão da indústria?",
     "Como AWS se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["s3","durability","data-protection"]'::jsonb, 'ai-draft', 'active', now(), now()
)
