INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-037', 'aws-clf', 'Uma empresa Windows precisa de compartilhamento SMB com integração Active Directory para instâncias EC2 Windows. Qual serviço escolher?',
  '[{"id":"A","text":"Amazon FSx for Windows File Server"},{"id":"B","text":"Amazon EFS"},{"id":"C","text":"Amazon S3 montado via Storage Gateway"},{"id":"D","text":"Amazon EBS gp3"}]'::jsonb, 'A',
