INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-039', 'aws-clf', 'Uma equipe precisa escolher um volume EBS para um banco de dados MySQL com alto IOPS sustentado (10k+ IOPS) e baixa latência consistente. Qual tipo de volume usar?',
  '[{"id":"A","text":"gp2 (General Purpose SSD v2)"},{"id":"B","text":"gp3 (General Purpose SSD v3)"},{"id":"C","text":"io2 / io2 Block Express (Provisioned IOPS SSD)"},{"id":"D","text":"st1 (Throughput Optimized HDD)"}]'::jsonb, 'C',
  '{
    "summary": "io2/io2 Block Express oferece IOPS provisionados até 256k, latência sub-ms e durabilidade 99.999% — designed para bancos de produção.",
    "whyCorrect": "io2/io2 Block Express oferece IOPS provisionados até 256k, latência sub-ms e durabilidade 99.999% — designed para bancos de produção.",
    "whyWrong": {
     "D": "st1 é HDD throughput (Hadoop/logs), não IOPS.",
     "A": "gp2 (General Purpose SSD v2) tem IOPS atrelados ao tamanho do volume (3 IOPS/GB, max 16k IOPS), com burst credits que podem se esgotar — latência inconsistente sob carga sustentada. Para banco de produção com 10k+ IOPS sustentado, gp2 fica no limite. AWS recomenda migrar gp2 → gp3 ou io2.",
     "B": "gp3 (General Purpose SSD v3) suporta até 16k IOPS (provisionado) e é mais barato que gp2 — bom para muitos workloads de banco, mas para REQUISITO ESPECÍFICO de 10k+ IOPS com latência sub-ms CONSISTENTE em produção crítica, io2 é a escolha purpose-built (até 256k IOPS, 99.999% durabilidade)."
    },
    "keyConcept": "Regra: IOPS extremos e latência crítica = io2; IOPS moderados + baixo custo = gp3.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: IOPS extremos e latência crítica = io2; IOPS moderados + baixo custo = gp3?",
     "Quais cenários reais aplicam Regra: IOPS extremos e latência crítica = io2; IOPS moderados + baixo custo = gp3?",
     "Como IOPS se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["ebs","io2","performance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
