INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-040', 'aws-clf', 'Sobre Amazon EBS, qual afirmação está CORRETA?',
  '[{"id":"A","text":"Volumes EBS podem ser anexados a instâncias em qualquer Region"},{"id":"B","text":"Volumes EBS são globalmente replicados por padrão"},{"id":"C","text":"Volumes EBS não permitem snapshots"},{"id":"D","text":"Volumes EBS são bound a uma única Availability Zone"}]'::jsonb, 'D',
  '{
    "summary": "EBS volumes existem em uma AZ específica — só podem ser attachados a instâncias da mesma AZ.",
    "whyCorrect": "EBS volumes existem em uma AZ específica — só podem ser attachados a instâncias da mesma AZ. Para mover entre AZs/Regions usa-se snapshot (copy snapshot para outra Region).",
    "whyWrong": {
     "B": "Snapshots são padrão e armazenam no S3 gerenciado.",
     "A": "EBS volumes NÃO podem ser anexados a instâncias em outras Regions — são objetos ZONAIS (existem em uma AZ específica de uma Region). Para mover volume entre Regions, é necessário criar snapshot e usar copy snapshot para Region destino, então restaurar. Cross-AZ exige snapshot dentro da mesma Region.",
     "C": "EBS SUPORTA snapshots — é uma das principais features (snapshots são incrementais, armazenados em S3 managed, base para AMIs, replicáveis cross-Region). Esta opção é factualmente errada. Snapshots são padrão de backup AWS."
    },
    "keyConcept": "Regra: EBS = block storage zonal; snapshots = portáveis para Region.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: EBS = block storage zonal; snapshots = portáveis para Region?",
     "Quais cenários reais aplicam Regra: EBS = block storage zonal; snapshots = portáveis para Region?",
     "Como EBS se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["ebs","availability-zone","storage"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
