INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-042', 'aws-clf', 'Sobre EFS storage classes, qual cenário favorece EFS Infrequent Access (EFS IA)?',
  '[{"id":"A","text":"Arquivos acessados muitas vezes por dia"},{"id":"B","text":"Arquivos acessados raramente (menos que mensalmente) que ainda precisam de NFS"},{"id":"C","text":"Workloads que exigem latência sub-millisegundo constante"},{"id":"D","text":"Arquivos que precisam ser deletados a cada hora"}]'::jsonb, 'B',
  '{
    "summary": "EFS IA tem custo de storage até 92% menor que Standard, mas cobra por acesso — ideal para arquivos NFS que ficam frios após período inicial.",
    "whyCorrect": "EFS IA tem custo de storage até 92% menor que Standard, mas cobra por acesso — ideal para arquivos NFS que ficam frios após período inicial. Lifecycle management move automaticamente.",
    "whyWrong": {
     "A": "arquivos efêmeros = não EFS.",
     "C": "Acesso constante = Standard latência ultraconsistente = não-IA",
     "D": "Arquivos deletados a cada hora têm vida útil muito curta — não fazem sentido em EFS IA que cobra por GB armazenado + retrieval fee. Para conteúdo de altíssima rotatividade, EFS Standard ou storage local seria mais apropriado. EFS IA é para arquivos antigos que ainda precisam estar online mas raramente são lidos."
    },
    "keyConcept": "Regra: EFS IA = arquivos antigos/raramente lidos que ainda precisam estar online.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: EFS IA = arquivos antigos/raramente lidos que ainda precisam estar online?",
