INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-049', 'aws-clf', 'Sobre Amazon Aurora, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"Aurora é compatível com MySQL e PostgreSQL, mas não com Oracle ou SQL Server"},{"id":"B","text":"Aurora é compatível com todos os engines do RDS"},{"id":"C","text":"Aurora é NoSQL document-oriented"},{"id":"D","text":"Aurora não suporta replicas de leitura"}]'::jsonb, 'A',
  '{
    "summary": "Aurora é engine cloud-native AWS, wire-compatible com MySQL ou PostgreSQL, com storage distribuído auto-scaling (até 128 TB), 6 cópias em 3 AZs, até 15 read replicas.",
    "whyCorrect": "Aurora é engine cloud-native AWS, wire-compatible com MySQL ou PostgreSQL, com storage distribuído auto-scaling (até 128 TB), 6 cópias em 3 AZs, até 15 read replicas.",
    "whyWrong": {
     "C": "não é NoSQL",
     "D": "Não suporta Oracle/SQL Server (use RDS para isso) suporta muitas replicas com baixa latência.",
     "B": "Aurora é compatível APENAS com MySQL e PostgreSQL — não suporta Oracle, SQL Server, MariaDB ou outros engines. RDS suporta 6 engines (incluindo Aurora MySQL/PG, Oracle, SQL Server, MariaDB, IBM Db2). Aurora é subconjunto especializado, não substituto universal de RDS."
    },
    "keyConcept": "Regra: ''managed MySQL/PG cloud-native premium'' = Aurora.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: ''managed MySQL/PG cloud-native premium'' = Aurora?",
     "Quais cenários reais aplicam Regra: ''managed MySQL/PG cloud-native premium'' = Aurora?",
