INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-050', 'aws-clf', 'Sobre RDS Multi-AZ vs Read Replicas, qual afirmação é CORRETA?',
  '[{"id":"A","text":"Read Replicas fornecem failover automático sync; Multi-AZ é só para escalar leituras"},{"id":"B","text":"Multi-AZ é para alta disponibilidade (failover sync); Read Replicas são para escalar leituras (replicação async)"},{"id":"C","text":"Os dois recursos são idênticos, apenas nomes diferentes"},{"id":"D","text":"Read Replicas não podem existir em outra Region"}]'::jsonb, 'B',
  '{
    "summary": "Multi-AZ mantém standby sync na outra AZ — failover automático em ~60-120s sem mudar endpoint.",
    "whyCorrect": "Multi-AZ mantém standby sync na outra AZ — failover automático em ~60-120s sem mudar endpoint. Read Replicas são async (potencial lag), com endpoint próprio, para offloading de read traffic; podem ser cross-Region.",
    "whyWrong": {
     "A": "Read Replicas não fazem failover automático (precisa promoção manual) Multi-AZ não atende leitura no standby (em RDS legado).",
     "C": "Multi-AZ e Read Replicas são features DISTINTAS com propósitos diferentes — não são sinônimos. Multi-AZ usa replicação síncrona para failover automático (HA), com endpoint único. Read Replicas usam replicação assíncrona para escalar leitura, com endpoints separados. Podem coexistir.",
     "D": "Read Replicas PODEM ser cross-Region — feature suportada nativamente em RDS para DR e atender leitores em outra geografia. Esta opção é factualmente errada. Cross-Region Read Replica é padrão recomendado para baixa latência global de leitura."
    },
    "keyConcept": "Regra: HA = Multi-AZ; Read scale = Read Replicas; ambos podem coexistir.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: HA = Multi-AZ; Read scale = Read Replicas; ambos podem coexistir?",
     "Quais cenários reais aplicam Regra: HA = Multi-AZ; Read scale = Read Replicas; ambos podem coexistir?",
     "Como AZ se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["rds","multi-az","read-replica"]'::jsonb, 'ai-draft', 'active', now(), now()
)
