INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-056', 'aws-clf', 'Uma equipe migrou de RDS MySQL para Aurora MySQL e notou throughput 5x maior nas mesmas instâncias. Por que Aurora tende a ser mais rápido?',
  '[{"id":"A","text":"Aurora reescreve queries automaticamente"},{"id":"B","text":"Aurora roda em chips quânticos"},{"id":"C","text":"Aurora compila MySQL em assembly customizado"},{"id":"D","text":"Aurora usa storage distribuído otimizado, redo log offloaded e cache compartilhado entre nodes"}]'::jsonb, 'D',
  '{
    "summary": "Aurora separa compute de storage; o storage layer aplica redo logs distribuídos em 6 cópias 3 AZs, com cache compartilhado entre instâncias do cluster — reduz drasticamente I/O e network do compute.",
    "whyCorrect": "Aurora separa compute de storage; o storage layer aplica redo logs distribuídos em 6 cópias 3 AZs, com cache compartilhado entre instâncias do cluster — reduz drasticamente I/O e network do compute.",
    "whyWrong": {
     "A": "Não reescreve queries",
     "C": "é fork do MySQL com mods, não compilação especial.",
     "B": "Aurora roda em hardware AWS convencional (Intel/AMD/Graviton, x86_64 ou ARM64) — não usa ''chips quânticos''. Esta opção é absurda. Performance vem de redesign arquitetural (separação compute/storage, redo log offload, distributed log-structured storage), não de hardware exótico."
    },
    "keyConcept": "Regra: Aurora = ''MySQL/PG reimaginado para cloud''.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: Aurora = ''MySQL/PG reimaginado para cloud''?",
     "Quais cenários reais aplicam Regra: Aurora = ''MySQL/PG reimaginado para cloud''?",
     "Como AZs se compara com alternativas?"
    ]
   }'::jsonb,
