INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-057', 'aws-clf', 'Uma equipe roda DynamoDB e tem padrão de tráfego imprevisível (picos abruptos). Quer evitar throttling sem provisionar capacity ociosa. Qual modo de capacity escolher?',
  '[{"id":"A","text":"On-Demand mode"},{"id":"B","text":"Provisioned mode com auto scaling"},{"id":"C","text":"Reserved Capacity"},{"id":"D","text":"DAX Cluster apenas"}]'::jsonb, 'A',
  '{
    "summary": "On-Demand cobra por request (RRU/WRU) sem provisionar — escala instantaneamente para picos.",
    "whyCorrect": "On-Demand cobra por request (RRU/WRU) sem provisionar — escala instantaneamente para picos. Ideal para cargas imprevisíveis ou novos workloads.",
    "whyWrong": {
     "B": "Provisioned auto scaling tem janela de adaptação e pode throttlar em picos abruptos DAX é cache, não capacity mode.",
     "C": "Reserved Capacity é discount em Provisioned",
     "D": "DAX (DynamoDB Accelerator) é cache em memória in-front de DynamoDB — reduz latência de leitura para microssegundos, mas NÃO substitui o modo de capacity da tabela. Cliente ainda precisa escolher Provisioned ou On-Demand para o storage layer. DAX seria adição complementar, não resposta ao problema de capacity."
    },
    "keyConcept": "Regra: imprevisível = On-Demand; previsível e steady = Provisioned (mais barato).",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: imprevisível = On-Demand; previsível e steady = Provisioned (mais barato)?",
     "Quais cenários reais aplicam Regra: imprevisível = On-Demand; previsível e steady = Provisioned (mais barato)?",
     "Como RRU se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["dynamodb","on-demand","capacity"]'::jsonb, 'ai-draft', 'active', now(), now()
)
