INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-061', 'aws-clf', 'Uma empresa quer rodar queries SQL ad-hoc sobre logs em S3 sem provisionar cluster nem ETL. Qual serviço escolher?',
  '[{"id":"A","text":"Amazon Athena"},{"id":"B","text":"Amazon Redshift"},{"id":"C","text":"Amazon EMR"},{"id":"D","text":"Amazon RDS"}]'::jsonb, 'A',
  '{
    "summary": "Athena é query engine serverless baseado em Presto/Trino — query SQL direto sobre S3 (CSV, JSON, Parquet) pagando por TB scaneado.",
    "whyCorrect": "Athena é query engine serverless baseado em Presto/Trino — query SQL direto sobre S3 (CSV, JSON, Parquet) pagando por TB scaneado. Zero infra.",
    "whyWrong": {
     "B": "Redshift exige cluster",
     "C": "Amazon EMR é cluster Hadoop/Spark/Hive managed — exige provisionar cluster (master, core, task nodes), pagar por instâncias ativas, e operacionalizar jobs Spark/Hive. Para ''queries SQL ad-hoc sem cluster'', EMR é overhead enorme. EMR seria correto para ''pipeline ETL pesado com Spark sobre 100TB''.",
     "D": "Amazon RDS é banco relacional gerenciado para OLTP — não escala para queries analíticas sobre TBs em S3. Carregaria os logs no banco (caro e demorado) antes de poder query-lar. RDS seria correto para ''banco transacional de aplicação'', não para análise de logs."
    },
    "keyConcept": "Regra: SQL ad-hoc on S3 + zero infra = Athena; warehouse petabyte = Redshift; ETL/big data complexo = EMR.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: SQL ad-hoc on S3 + zero infra = Athena; warehouse petabyte = Redshift; ETL/big data complexo = EMR?",
     "Quais cenários reais aplicam Regra: SQL ad-hoc on S3 + zero infra = Athena; warehouse petabyte = Redshift; ETL/big data complexo = EMR?",
     "Como SQL se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["athena","s3","analytics"]'::jsonb, 'ai-draft', 'active', now(), now()
)
