INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-067', 'aws-clf', 'Uma empresa quer que instâncias EC2 em subnet privada acessem a internet (para baixar updates) sem serem alcançáveis a partir da internet. Qual recurso usar?',
  '[{"id":"A","text":"Internet Gateway na subnet privada"},{"id":"B","text":"VPC Peering"},{"id":"C","text":"NAT Gateway numa subnet pública, com route table das privadas apontando para ele"},{"id":"D","text":"Direct Connect"}]'::jsonb, 'C',
  '{
    "summary": "NAT Gateway permite tráfego outbound iniciado pela subnet privada para a internet, mas NÃO permite inbound iniciado de fora — ideal para updates, API calls externas.",
    "whyCorrect": "NAT Gateway permite tráfego outbound iniciado pela subnet privada para a internet, mas NÃO permite inbound iniciado de fora — ideal para updates, API calls externas.",
    "whyWrong": {
     "A": "Internet Gateway exige IP público e expõe inbound também",
