INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-068', 'aws-clf', 'Uma empresa tem duas VPCs em Regions diferentes e quer comunicação privada entre elas (sem trânsito pela internet). Qual recurso usar?',
  '[{"id":"A","text":"Public Internet com TLS"},{"id":"B","text":"Direct Connect"},{"id":"C","text":"AWS Outposts"},{"id":"D","text":"Inter-Region VPC Peering"}]'::jsonb, 'D',
  '{
    "summary": "VPC Peering (incluindo inter-Region) cria conexão 1-para-1 privada usando backbone AWS, sem trafegar pela internet.",
    "whyCorrect": "VPC Peering (incluindo inter-Region) cria conexão 1-para-1 privada usando backbone AWS, sem trafegar pela internet. Não é transitivo (peering A↔B + B↔C não dá A↔C).",
    "whyWrong": {
     "A": "Internet pública não atende ''sem internet''",
     "B": "Direct Connect conecta on-prem à AWS",
     "C": "Outposts é rack on-prem."
