INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-069', 'aws-clf', 'Uma empresa tem 30 VPCs e duas conexões VPN, e a malha de peering virou inviável. Qual serviço simplifica esse cenário?',
  '[{"id":"A","text":"AWS Transit Gateway"},{"id":"B","text":"VPC Peering em malha completa"},{"id":"C","text":"Internet Gateway compartilhado"},{"id":"D","text":"AWS Site-to-Site VPN extra"}]'::jsonb, 'A',
  '{
    "summary": "Transit Gateway é hub-and-spoke regional que conecta VPCs, VPNs e Direct Connect — uma única conexão central em vez de malha quadrática de peerings.",
    "whyCorrect": "Transit Gateway é hub-and-spoke regional que conecta VPCs, VPNs e Direct Connect — uma única conexão central em vez de malha quadrática de peerings.",
    "whyWrong": {
     "B": "Malha peering O(n²) é inviável > 10 VPCs",
     "C": "Internet Gateway dá saída para internet pública — não conecta VPCs entre si. IGW não resolve mesh de peering; é mecanismo de egress para internet, conceito ortogonal a connectivity entre VPCs.",
     "D": "VPN Site-to-Site adicional não simplifica o problema — cada VPN ainda conecta DC on-prem a UMA VPC, perpetuando a complexidade de gerenciar N conexões. Para 30 VPCs interconectadas, o hub é a solução escalável (Transit Gateway), não mais túneis VPN ponto-a-ponto."
    },
    "keyConcept": "Regra: >5 VPCs e VPNs = Transit Gateway.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: >5 VPCs e VPNs = Transit Gateway?",
     "Quais cenários reais aplicam Regra: >5 VPCs e VPNs = Transit Gateway?",
     "Como VPCs se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["vpc","transit-gateway","networking"]'::jsonb, 'ai-draft', 'active', now(), now()
)
