INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-070', 'aws-clf', 'Uma empresa precisa de conexão dedicada de 10 Gbps com baixa latência consistente entre seu datacenter e AWS, sem usar a internet. Qual serviço atende?',
  '[{"id":"A","text":"Site-to-Site VPN"},{"id":"B","text":"AWS Direct Connect"},{"id":"C","text":"AWS Client VPN"},{"id":"D","text":"Internet Gateway com TLS"}]'::jsonb, 'B',
  '{
    "summary": "Direct Connect é link físico dedicado (1/10/100 Gbps) entre datacenter do cliente e AWS, com latência baixa consistente e bypass da internet.",
    "whyCorrect": "Direct Connect é link físico dedicado (1/10/100 Gbps) entre datacenter do cliente e AWS, com latência baixa consistente e bypass da internet. Provisionamento leva semanas.",
    "whyWrong": {
     "A": "Site-to-Site VPN usa internet pública (latência variável)",
     "C": "Client VPN é para usuários remotos individuais",
     "D": "IGW+TLS ainda é internet."
    },
    "keyConcept": "Regra: bandwidth dedicada/baixa latência = Direct Connect; rápido e barato = VPN.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: bandwidth dedicada/baixa latência = Direct Connect; rápido e barato = VPN?",
     "Quais cenários reais aplicam Regra: bandwidth dedicada/baixa latência = Direct Connect; rápido e barato = VPN?",
     "Como AWS se compara com alternativas?"
    ]
