INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-071', 'aws-clf', 'Uma startup precisa de VPN site-to-site rápida de configurar, encriptada, para POC com seu on-prem. Qual serviço escolher?',
  '[{"id":"A","text":"AWS Direct Connect"},{"id":"B","text":"AWS Outposts"},{"id":"C","text":"AWS Site-to-Site VPN"},{"id":"D","text":"Storage Gateway"}]'::jsonb, 'C',
