INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-073', 'aws-clf', 'Sobre Amazon Route 53, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"É um serviço DNS gerenciado com routing policies (simple, weighted, latency, failover, geolocation, multivalue)"},{"id":"B","text":"É um serviço de CDN com edge locations"},{"id":"C","text":"É um firewall L7"},{"id":"D","text":"É um serviço de load balancing intra-VPC"}]'::jsonb, 'A',
  '{
    "summary": "Route 53 é DNS authoritativo + registrar + health checks, com 7 routing policies para load balancing, failover e geo.",
    "whyCorrect": "Route 53 é DNS authoritativo + registrar + health checks, com 7 routing policies para load balancing, failover e geo.",
    "whyWrong": {
     "C": "firewall L7 é WAF",
     "D": "LB intra-VPC é ELB.",
     "B": "Route 53 é serviço DNS (porta 53, daí o nome) — NÃO é CDN. Route 53 retorna endereços IP/DNS conforme routing policies, mas não cacheia conteúdo. CDN com edge locations é Amazon CloudFront. Esta opção confunde dois serviços diferentes da AWS."
    },
    "keyConcept": "Regra: DNS na AWS = Route 53; nome reflete porta 53.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: DNS na AWS = Route 53; nome reflete porta 53?",
     "Quais cenários reais aplicam Regra: DNS na AWS = Route 53; nome reflete porta 53?",
     "Como DNS se compara com alternativas?"
    ]
