INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-074', 'aws-clf', 'Uma empresa quer rotear usuários para a Region mais próxima geograficamente automaticamente. Qual routing policy do Route 53 usar?',
  '[{"id":"A","text":"Simple routing"},{"id":"B","text":"Latency-based routing"},{"id":"C","text":"Weighted routing"},{"id":"D","text":"Failover routing"}]'::jsonb, 'B',
  '{
    "summary": "Latency-based routing escolhe Region com menor latência medida ao DNS resolver do cliente — geralmente a mais próxima geograficamente, mas mais preciso que geo.",
    "whyCorrect": "Latency-based routing escolhe Region com menor latência medida ao DNS resolver do cliente — geralmente a mais próxima geograficamente, mas mais preciso que geo.",
    "whyWrong": {
     "A": "Simple é 1 record Geolocation routing usa localização do client mas pode não refletir latência real.",
     "C": "Weighted distribui por peso (canary deploys, A/B)",
     "D": "Failover ativa standby"
    },
    "keyConcept": "Regra: ''mais rápido por cliente'' = Latency.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: ''mais rápido por cliente'' = Latency?",
     "Quais cenários reais aplicam Regra: ''mais rápido por cliente'' = Latency?",
     "Como DNS se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["route53","latency-routing","dns"]'::jsonb, 'ai-draft', 'active', now(), now()
)
