INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-075', 'aws-clf', 'Uma empresa quer servir 90% do tráfego para a versão production e 10% para uma nova versão para canary testing via DNS. Qual routing policy usar?',
  '[{"id":"A","text":"Failover routing"},{"id":"B","text":"Geolocation routing"},{"id":"C","text":"Weighted routing"},{"id":"D","text":"Multivalue routing"}]'::jsonb, 'C',
  '{
    "summary": "Weighted routing permite distribuir tráfego entre records pelo peso (ex: 90/10) — perfeito para canary, A/B, blue/green deploys.",
    "whyCorrect": "Weighted routing permite distribuir tráfego entre records pelo peso (ex: 90/10) — perfeito para canary, A/B, blue/green deploys.",
    "whyWrong": {
     "A": "Failover é ativo-passivo Multivalue retorna múltiplos values para client failover.",
     "B": "Geolocation é por país/continente",
     "D": "Multivalue routing retorna múltiplos IPs em resposta DNS (até 8) e o cliente DNS escolhe um — distribui sem peso explícito (round-robin de facto). Não dá controle de proporção (90/10). Multivalue seria correto para ''load balancing simples de múltiplos endpoints igualmente capazes'', não para canary com proporção específica."
    },
    "keyConcept": "Regra: split por porcentagem = Weighted.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: split por porcentagem = Weighted?",
     "Quais cenários reais aplicam Regra: split por porcentagem = Weighted?"
    ]
   }'::jsonb,
