INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-076', 'aws-clf', 'Sobre Security Group vs Network ACL em VPC, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"Os dois são stateless idênticos"},{"id":"B","text":"NACL é stateful e Security Group stateless"},{"id":"C","text":"Security Group está no nível da Region, NACL no nível global"},{"id":"D","text":"Security Group é stateful (no nível da ENI) e por padrão nega tudo inbound; NACL é stateless (no nível da subnet)"}]'::jsonb, 'D',
  '{
    "summary": "SG: stateful (return traffic auto-permitido), no nível da ENI/instância, default deny inbound + allow outbound, só regras allow.",
    "whyCorrect": "SG: stateful (return traffic auto-permitido), no nível da ENI/instância, default deny inbound + allow outbound, só regras allow. NACL: stateless (precisa regra ida E volta), nível subnet, default permite tudo, suporta allow e deny ordenadas.",
    "whyWrong": {
     "A": "Não são idênticos",
     "B": "SG é stateful",
     "C": "Security Group é objeto regional (atrelado a VPC, que é regional) e NACL também é regional (atrelado a subnet, que é zonal dentro de Region). Nenhum dos dois é ''global''. Esta opção é factualmente errada — os dois são construtos de VPC, dentro do escopo de uma Region."
    },
    "keyConcept": "Regra: SG = firewall de host; NACL = firewall de subnet.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: SG = firewall de host; NACL = firewall de subnet?",
     "Quais cenários reais aplicam Regra: SG = firewall de host; NACL = firewall de subnet?",
     "Como SG se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["vpc","security-group","nacl"]'::jsonb, 'ai-draft', 'active', now(), now()
)
