INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-077', 'aws-clf', 'Uma equipe quer permitir que EC2 em subnet privada acesse S3 sem que o tráfego saia para a internet. Qual recurso usar?',
  '[{"id":"A","text":"VPC Gateway Endpoint para S3"},{"id":"B","text":"NAT Gateway"},{"id":"C","text":"Internet Gateway"},{"id":"D","text":"Direct Connect"}]'::jsonb, 'A',
  '{
    "summary": "Gateway Endpoints (S3 e DynamoDB) permitem acesso privado pela backbone AWS, sem NAT, sem internet, sem cobrança de data transfer extra.",
    "whyCorrect": "Gateway Endpoints (S3 e DynamoDB) permitem acesso privado pela backbone AWS, sem NAT, sem internet, sem cobrança de data transfer extra.",
    "whyWrong": {
     "C": "NAT envia para internet (cara)",
     "D": "Direct Connect é on-prem.",
     "B": "NAT Gateway permite que EC2 em subnet privada saia para INTERNET (incluindo S3 público) — mas o tráfego ainda sai da VPC para internet, gera custo de NAT (~$0.045/h + $0.045/GB) e expõe SLA da rota internet. VPC Gateway Endpoint mantém tráfego inteiramente dentro da rede AWS, sem internet, sem custo de NAT."
    },
    "keyConcept": "Regra: S3/DynamoDB privado = Gateway Endpoint; outros serviços = Interface Endpoint (PrivateLink).",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: S3/DynamoDB privado = Gateway Endpoint; outros serviços = Interface Endpoint (PrivateLink)?",
     "Quais cenários reais aplicam Regra: S3/DynamoDB privado = Gateway Endpoint; outros serviços = Interface Endpoint (PrivateLink)?",
     "Como AWS se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["vpc","vpc-endpoint","s3"]'::jsonb, 'ai-draft', 'active', now(), now()
)
