INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-078', 'aws-clf', 'Sobre Amazon CloudFront, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"Suporta apenas conteúdo estático em S3"},{"id":"B","text":"Suporta TLS/HTTPS, custom domains, cache de conteúdo estático e dinâmico, signed URLs e integração com WAF, Shield, S3"},{"id":"C","text":"Não suporta cache de conteúdo dinâmico"},{"id":"D","text":"Só funciona em uma Region por distribution"}]'::jsonb, 'B',
  '{
    "summary": "CloudFront é CDN global completo: edge locations em 90+ países, suporta múltiplas origins (S3, ALB, EC2, on-prem), signed URLs/cookies, Lambda@Edge/CloudFront Functions, WAF, Shield Standard incluído.",
    "whyCorrect": "CloudFront é CDN global completo: edge locations em 90+ países, suporta múltiplas origins (S3, ALB, EC2, on-prem), signed URLs/cookies, Lambda@Edge/CloudFront Functions, WAF, Shield Standard incluído.",
    "whyWrong": {
     "A": "Suporta qualquer HTTP origin, estático ou dinâmico",
     "C": "CloudFront SUPORTA cache de conteúdo dinâmico — desde 2017 oferece TTL configurável, Cache Behaviors por path, query string forwarding, e Lambda@Edge para lógica dinâmica. Apps dinâmicos podem cachear respostas por segundos para reduzir load no origin. Esta opção contradiz a documentação atual.",
     "D": "CloudFront É CDN global — uma distribution serve usuários de TODAS as edge locations do mundo, sem restrição a uma Region. Origin pode estar em uma Region, mas edge locations distribuem o conteúdo globalmente. Esta opção é factualmente errada."
    },
    "keyConcept": "Regra: CDN AWS = CloudFront, multi-purpose.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: CDN AWS = CloudFront, multi-purpose?",
     "Quais cenários reais aplicam Regra: CDN AWS = CloudFront, multi-purpose?",
     "Como CDN se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["cloudfront","cdn","features"]'::jsonb, 'ai-draft', 'active', now(), now()
)
