INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-080', 'aws-clf', 'Uma aplicação on-prem precisa de tráfego TCP com IP estático e roteamento via backbone AWS para reduzir latência para usuários globais, mesmo para conteúdo NÃO cacheável (jogo online, API). Qual serviço usar?',
  '[{"id":"A","text":"CloudFront"},{"id":"B","text":"Route 53 latency routing"},{"id":"C","text":"AWS PrivateLink"},{"id":"D","text":"AWS Global Accelerator"}]'::jsonb, 'D',
  '{
    "summary": "Global Accelerator entrega 2 IPs estáticos anycast e roteia tráfego TCP/UDP via backbone AWS desde a edge location mais próxima — ideal para conteúdo não-cacheável (gaming, voice, IoT, APIs).",
    "whyCorrect": "Global Accelerator entrega 2 IPs estáticos anycast e roteia tráfego TCP/UDP via backbone AWS desde a edge location mais próxima — ideal para conteúdo não-cacheável (gaming, voice, IoT, APIs).",
    "whyWrong": {
     "A": "CloudFront cacheia (não serve dinâmico mutável)",
     "B": "Route 53 só responde DNS, não roteia",
     "C": "PrivateLink é exposição privada de serviços."
    },
    "keyConcept": "Regra: TCP/UDP global low-latency não-cacheável = Global Accelerator; cacheável = CloudFront.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: TCP/UDP global low-latency não-cacheável = Global Accelerator; cacheável = CloudFront?",
     "Quais cenários reais aplicam Regra: TCP/UDP global low-latency não-cacheável = Global Accelerator; cacheável = CloudFront?",
     "Como IPs se compara com alternativas?"
    ]
   }'::jsonb,
