INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-084', 'aws-clf', 'Uma equipe quer um sistema pub/sub onde uma mensagem é entregue a múltiplos subscribers (Lambda, SQS queue, email, SMS). Qual serviço escolher?',
  '[{"id":"A","text":"Amazon SQS"},{"id":"B","text":"Amazon Kinesis Data Streams"},{"id":"C","text":"AWS Step Functions"},{"id":"D","text":"Amazon SNS"}]'::jsonb, 'D',
  '{
    "summary": "SNS é pub/sub topic-based: 1 publish → fan-out para N subscribers (SQS, Lambda, HTTP, email, SMS, mobile push).",
    "whyCorrect": "SNS é pub/sub topic-based: 1 publish → fan-out para N subscribers (SQS, Lambda, HTTP, email, SMS, mobile push).",
    "whyWrong": {
     "B": "Kinesis é streaming ordered/durable de eventos",
     "C": "Step Functions é orchestration workflow.",
     "A": "SQS é fila ponto-a-ponto entre producer e UM grupo de consumers — não tem fan-out nativo para múltiplos subscribers heterogêneos (Lambda + email + SMS). Padrão clássico é SNS na frente fanning out para SQS + Lambda + email. SQS sozinho seria correto para ''worker queue com 1 conjunto de consumers''."
    },
    "keyConcept": "Regra: fan-out = SNS; fila de trabalho = SQS; stream contínuo = Kinesis.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: fan-out = SNS; fila de trabalho = SQS; stream contínuo = Kinesis?",
     "Quais cenários reais aplicam Regra: fan-out = SNS; fila de trabalho = SQS; stream contínuo = Kinesis?",
     "Como SNS se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["sns","pub-sub","messaging"]'::jsonb, 'ai-draft', 'active', now(), now()
)
