INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-085', 'aws-clf', 'Uma equipe precisa desacoplar producers e consumers numa pipeline de pedidos: producer enfileira mensagens e workers processam quando podem, garantindo at-least-once. Qual serviço usar?',
  '[{"id":"A","text":"Amazon SQS"},{"id":"B","text":"Amazon SNS"},{"id":"C","text":"AWS Lambda direto"},{"id":"D","text":"Amazon CloudWatch Events"}]'::jsonb, 'A',
  '{
    "summary": "SQS é managed message queue: producers enfileiram, consumers fazem poll/long-poll, mensagens visibility timeout, DLQ para falhas, at-least-once delivery (Standard) ou exactly-once (FIFO).",
    "whyCorrect": "SQS é managed message queue: producers enfileiram, consumers fazem poll/long-poll, mensagens visibility timeout, DLQ para falhas, at-least-once delivery (Standard) ou exactly-once (FIFO).",
    "whyWrong": {
     "C": "Lambda direto não armazena se consumer cair",
     "B": "SNS é pub/sub (broadcast 1-para-N) — quando publica, TODOS subscribers recebem. Não é fila de trabalho onde N workers competem por mensagens. Para desacoplar producer e consumers de forma que workers processem on-demand (1 mensagem = 1 worker), SQS é o construto. SNS seria correto para ''notificar múltiplos sistemas do mesmo evento''.",
     "D": "CloudWatch Events (atualmente EventBridge) é roteamento de eventos cron/state-change para targets — não é fila persistente onde workers fazem polling. Eventos têm retry curto e podem perder se target falhar. Para pipeline de pedidos com at-least-once garantido e desacoplamento, SQS é purpose-built."
    },
    "keyConcept": "Regra: queue desacoplada = SQS; broadcast = SNS; orquestração = Step Functions.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: queue desacoplada = SQS; broadcast = SNS; orquestração = Step Functions?",
     "Quais cenários reais aplicam Regra: queue desacoplada = SQS; broadcast = SNS; orquestração = Step Functions?",
     "Como SQS se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["sqs","queue","messaging"]'::jsonb, 'ai-draft', 'active', now(), now()
)
