INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-087', 'aws-clf', 'Uma equipe precisa rotear eventos de múltiplos serviços AWS SaaS para destinos diferentes (Lambda, SQS, ECS), com filtros baseados em conteúdo do evento. Qual serviço usar?',
  '[{"id":"A","text":"Amazon SQS FIFO"},{"id":"B","text":"AWS Step Functions"},{"id":"C","text":"Amazon EventBridge"},{"id":"D","text":"Amazon Kinesis Firehose"}]'::jsonb, 'C',
  '{
    "summary": "EventBridge é serverless event bus com schema registry, suporta eventos AWS, custom e SaaS (Zendesk, Datadog, etc.), regras com pattern matching filtram e roteiam para 20+ targets.",
