INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-090', 'aws-clf', 'Uma equipe precisa enviar SMS de notificação para clientes em vários países. Qual serviço AWS atende diretamente?',
  '[{"id":"A","text":"Amazon SES"},{"id":"B","text":"Tanto SNS quanto Pinpoint suportam SMS"},{"id":"C","text":"Amazon SNS (com endpoint SMS)"},{"id":"D","text":"Amazon Pinpoint"}]'::jsonb, 'B',
  '{
    "summary": "Tanto SNS quanto Pinpoint enviam SMS internacionalmente.",
