INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-091', 'aws-clf', 'Uma equipe precisa de uma API REST gerenciada com authentication, rate limiting, throttling, caching e integração com Lambda. Qual serviço usar?',
  '[{"id":"A","text":"Elastic Load Balancer ALB"},{"id":"B","text":"AWS AppSync"},{"id":"C","text":"Amazon API Gateway"},{"id":"D","text":"AWS App Runner"}]'::jsonb, 'C',
  '{
    "summary": "API Gateway é managed service para REST, HTTP e WebSocket APIs: auth (IAM, Cognito, Lambda Authorizer), rate limiting, throttling, caching, Lambda/HTTP/SQS/etc.",
    "whyCorrect": "API Gateway é managed service para REST, HTTP e WebSocket APIs: auth (IAM, Cognito, Lambda Authorizer), rate limiting, throttling, caching, Lambda/HTTP/SQS/etc. integration, versioning, custom domains.",
    "whyWrong": {
     "B": "AppSync é para GraphQL",
     "D": "App Runner é container hosting.",
     "A": "Elastic Load Balancer ALB é load balancer HTTP/HTTPS — distribui tráfego entre targets. NÃO tem authentication nativa (apenas integração OIDC limitada), NÃO tem rate limiting, NÃO tem caching, NÃO tem usage plans. ALB seria correto para ''distribuir tráfego HTTP entre servidores'', mas API Gateway é purpose-built para APIs gerenciadas."
    },
    "keyConcept": "Regra: API REST gerenciada serverless = API Gateway.",
