INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-098', 'aws-clf', 'Uma equipe precisa de ETL serverless para mover/transformar dados entre S3, Redshift, RDS e criar um catalog. Qual serviço escolher?',
  '[{"id":"A","text":"Amazon EMR"},{"id":"B","text":"AWS Glue"},{"id":"C","text":"AWS Data Pipeline"},{"id":"D","text":"Amazon Athena"}]'::jsonb, 'B',
  '{
    "summary": "Glue é ETL serverless baseado em Spark, com Data Catalog (Hive metastore-compatible), crawlers que descobrem schemas, integração nativa com Athena/Redshift Spectrum/EMR.",
    "whyCorrect": "Glue é ETL serverless baseado em Spark, com Data Catalog (Hive metastore-compatible), crawlers que descobrem schemas, integração nativa com Athena/Redshift Spectrum/EMR. Paga por DPU-hora.",
    "whyWrong": {
     "C": "Data Pipeline é legado (descontinuado para novos casos)",
     "D": "Athena é query, não ETL.",
     "A": "Amazon EMR é cluster Spark/Hadoop managed — poderoso para ETL pesado mas exige gerenciar cluster (instâncias, scaling, configuração). NÃO é serverless por padrão (EMR Serverless existe mas é mais recente e específico). Para ETL com Data Catalog automático, Glue é purpose-built. EMR seria correto para ''controle total do Spark cluster com tuning específico''."
    },
    "keyConcept": "Regra: ETL serverless + catálogo = Glue.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: ETL serverless + catálogo = Glue?",
     "Quais cenários reais aplicam Regra: ETL serverless + catálogo = Glue?",
     "Como ETL se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["glue","etl","analytics"]'::jsonb, 'ai-draft', 'active', now(), now()
)
