INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-099', 'aws-clf', 'Uma equipe quer monitorar fila SQS e auto-escalar consumers ECS conforme o tamanho da fila. Qual abordagem é a mais idiomática?',
  '[{"id":"A","text":"Lambda fazendo polling de 1 em 1 segundo e ajustando ECS manualmente"},{"id":"B","text":"Aumentar a visibility timeout para 12 horas"},{"id":"C","text":"CloudWatch metric ApproximateNumberOfMessagesVisible disparando ECS Service Auto Scaling"},{"id":"D","text":"Habilitar SNS fan-out"}]'::jsonb, 'C',
  '{
    "summary": "Padrão idiomático: SQS emite metric ApproximateNumberOfMessagesVisible para CloudWatch → ECS Service Auto Scaling (target tracking ou step scaling) ajusta task count baseado em backlog.",
    "whyCorrect": "Padrão idiomático: SQS emite metric ApproximateNumberOfMessagesVisible para CloudWatch → ECS Service Auto Scaling (target tracking ou step scaling) ajusta task count baseado em backlog.",
    "whyWrong": {
     "A": "Polling custom reinventa",
     "B": "visibility timeout não escala",
     "D": "SNS fan-out é mecanismo de broadcast pub/sub — não escala consumers baseado em backlog de fila. Habilitar SNS na frente do SQS não muda quantidade de consumers ECS. Esta opção mistura conceitos: fan-out é distribuir 1 mensagem para N subscribers, não escalar workers."
    },
    "keyConcept": "Regra: backlog-driven scaling = CloudWatch metric + ASG/ECS Auto Scaling.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Regra: backlog-driven scaling = CloudWatch metric + ASG/ECS Auto Scaling?",
     "Quais cenários reais aplicam Regra: backlog-driven scaling = CloudWatch metric + ASG/ECS Auto Scaling?",
     "Como SQS se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["sqs","auto-scaling","ecs"]'::jsonb, 'ai-draft', 'active', now(), now()
)
