INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-100', 'aws-clf', 'Uma startup vai construir um app mobile com backend serverless: auth de usuário, API GraphQL, banco NoSQL escalável e storage de imagens. Qual combinação AWS é a mais idiomática?',
  '[{"id":"A","text":"IAM Users + API Gateway REST + RDS MySQL + EBS"},{"id":"B","text":"Cognito + Lambda direto exposto na internet + Aurora + EFS"},{"id":"C","text":"Active Directory + EKS + Redshift + Glacier"},{"id":"D","text":"Cognito + AppSync + DynamoDB + S3"}]'::jsonb, 'D',
  '{
    "summary": "Stack serverless mobile idiomática: Cognito (user pools + identity pools), AppSync (GraphQL com offline sync), DynamoDB (NoSQL scale-to-zero), S3 (object storage com pre-signed URLs).",
    "whyCorrect": "Stack serverless mobile idiomática: Cognito (user pools + identity pools), AppSync (GraphQL com offline sync), DynamoDB (NoSQL scale-to-zero), S3 (object storage com pre-signed URLs). Todos managed, escalam automaticamente, pay-per-use.",
    "whyWrong": {
     "A": "IAM Users não escala para milhões de end-users",
     "B": "Expor Lambda diretamente sem API Gateway/AppSync é anti-padrão (Function URLs existem mas sem auth, throttling, request validation, custom domains adequados). Aurora é overkill para app mobile (paga cluster mínimo mesmo com tráfego baixo). EFS é file system NFS - desnecessário para storage de imagens (S3 é purpose-built, mais barato).",
     "C": "Active Directory é IdP corporativo (workforce) — não é apropriado para usuários finais de app mobile (use Cognito). EKS é Kubernetes managed — overhead enorme para startup pequena (use serverless: AppSync/Lambda). Redshift é data warehouse petabyte — não banco operacional de app (use DynamoDB/Aurora). Glacier é archival — não storage ativo de imagens (use S3)."
    },
    "keyConcept": "Expor Lambda direto sem API Gateway/AppSync é antipadrão; EFS é overkill.",
    "tutorSeeds": [
     "Pode explicar com mais detalhe: Expor Lambda direto sem API Gateway/AppSync é antipadrão; EFS é overkill?",
     "Quais cenários reais aplicam Expor Lambda direto sem API Gateway/AppSync é antipadrão; EFS é overkill?",
     "Como URLs se compara com alternativas?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["serverless","mobile","architecture"]'::jsonb, 'ai-draft', 'active', now(), now()
)
