INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-002', 'aws-clf', 'Uma loja sabe que o pico de tráfego ocorre toda sexta-feira às 20h por causa de uma promoção semanal, e quer garantir que tenha 50 instâncias rodando antes do pico — não depois que ele já começou. Qual estratégia de scaling do ASG melhor atende?',
  '[{"id":"A","text":"Target tracking em CPU = 60%"},{"id":"B","text":"Scheduled scaling configurado para subir desired=50 toda sexta às 19h45"},{"id":"C","text":"Predictive scaling com modelo padrão da AWS"},{"id":"D","text":"Step scaling com threshold de CPU em 40%"}]'::jsonb, 'B',
  '{
    "summary": "Padrão recorrente em horário conhecido = scheduled scaling.",
    "whyCorrect": "Scheduled scaling permite definir uma ação recorrente (cron) que altera MinSize/MaxSize/DesiredCapacity em um horário específico. Garantir 50 instâncias quentes ANTES do pico é exatamente isso — provisionamento proativo baseado em horário.",
    "whyWrong": {
     "A": "Target tracking só reage depois que a CPU sobe — adiciona instâncias durante o pico, sofrendo cold start e potencial degradação no início.",
     "C": "Predictive scaling é também válido (analisa histórico via ML), mas para um padrão tão claro e recorrente, scheduled é mais determinístico e simples. Predictive é melhor quando o padrão tem variação diária mais complexa.",
     "D": "Step scaling continua sendo reativo — só dispara após o threshold ser atingido, não antes."
    },
    "keyConcept": "Auto Scaling proativo (scheduled/predictive) vs reativo (target/step/simple)",
    "compareWith": [
     "Scheduled scaling vs Predictive scaling",
     "Proactive vs Reactive scaling"
    ],
    "realWorldContext": "E-commerce com Black Friday, banco com folha de pagamento mensal, gaming com lançamento de evento.",
    "commonMistakes": "Confiar só em target tracking para picos previsíveis — você paga em latência durante a rampa de boot.",
    "tutorSeeds": [
     "Como combinar scheduled + target tracking no mesmo ASG?",
     "Quando predictive scaling supera scheduled?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["auto-scaling","scheduled-scaling","predictive"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
