INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-003', 'aws-clf', 'Uma aplicação web roda em ALB com target group de EC2. Após adicionar uma nova versão da AMI no Launch Template, novas instâncias entram saudáveis no ALB mas usuários ainda recebem respostas da versão antiga por alguns minutos. Qual recurso do ASG melhor resolve a transição controlada?',
  '[{"id":"A","text":"Suspender o processo Launch e relançar manualmente"},{"id":"B","text":"Setar cooldown de 0 segundos no ASG"},{"id":"C","text":"Instance refresh com MinHealthyPercentage configurado"},{"id":"D","text":"Trocar o ALB por NLB para forçar refresh"}]'::jsonb, 'C',
  '{
    "summary": "Instance refresh é o mecanismo nativo para rollout controlado de novas versões em ASG.",
    "whyCorrect": "Instance refresh substitui instâncias gradualmente respeitando MinHealthyPercentage (ex: 90% saudáveis durante o processo) e warmup. Drena conexões via ALB deregistration delay, sobe a nova, marca saudável, depois encerra a antiga. É o blue/green nativo do ASG.",
    "whyWrong": {
     "A": "Suspender Launch impede novas instâncias — não força substituição das atuais. Você ainda teria a mistura.",
     "B": "Cooldown afeta espaçamento entre scaling actions reativas, não substituição de versão.",
     "D": "Trocar ALB por NLB não tem relação alguma com versionamento de AMI."
    },
    "keyConcept": "ASG Instance Refresh — rollout controlado com MinHealthyPercentage e warmup",
    "compareWith": [
     "Instance refresh vs CodeDeploy Blue/Green",
     "Rolling update vs All-at-once"
    ],
    "realWorldContext": "Deploy de novas AMIs em ASGs de produção, golden image rotation, patching coordenado.",
    "commonMistakes": "Achar que apenas trocar o Launch Template já recicla as instâncias — não recicla, só afeta novos launches.",
    "tutorSeeds": [
     "Como configurar warmup time corretamente?",
     "Diferença entre instance refresh e simplesmente terminar instâncias?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'troubleshoot', '["auto-scaling","instance-refresh","deployment"]'::jsonb, 'ai-draft', 'active', now(), now()
)
