INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-004', 'aws-clf', 'Uma fintech precisa de um load balancer que: termine TLS, faça roteamento por path (/api → backend A, /admin → backend B) e suporte autenticação via Cognito. Qual tipo de ELB atende?',
  '[{"id":"A","text":"Network Load Balancer (NLB)"},{"id":"B","text":"Gateway Load Balancer (GWLB)"},{"id":"C","text":"Classic Load Balancer (CLB)"},{"id":"D","text":"Application Load Balancer (ALB)"}]'::jsonb, 'D',
  '{
    "summary": "Roteamento L7 por path + auth via Cognito = ALB.",
    "whyCorrect": "ALB opera na camada 7 (HTTP/HTTPS), oferece path-based, host-based e header-based routing, termina TLS, integra autenticação nativa com Cognito User Pools e provedores OIDC. É o único ELB com esses três recursos juntos.",
    "whyWrong": {
     "A": "NLB opera em L4 (TCP/UDP/TLS passthrough) — não enxerga path HTTP, não faz auth Cognito. Termina TLS mas sem regras L7.",
     "B": "GWLB é para inserir appliances de segurança no path do tráfego (firewalls, IDS) via GENEVE — não faz roteamento aplicacional.",
     "C": "CLB é legado, suporta básico L4/L7 mas não path-based routing avançado nem integração com Cognito."
    },
    "keyConcept": "ELB types — L7 (ALB), L4 (NLB), bump-in-the-wire (GWLB), legacy (CLB)",
    "compareWith": [
     "ALB vs NLB vs GWLB vs CLB"
    ],
    "realWorldContext": "Microsserviços com rotas REST diferentes apontando para serviços diferentes, autenticação centralizada.",
    "commonMistakes": "Usar NLB para HTTP achando que ''é mais rápido'' — perde routing L7 e integração de auth.",
    "tutorSeeds": [
     "Quando NLB é preferível a ALB?",
     "Como funciona auth Cognito no ALB internamente?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["elb","alb","routing","cognito"]'::jsonb, 'ai-draft', 'active', now(), now()
)
