INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-005', 'aws-clf', 'Um serviço financeiro precisa de load balancer L4 com IP estático, suporte a milhões de RPS, preservação do IP de origem do cliente e endpoints UDP. Qual é o mais adequado?',
  '[{"id":"A","text":"Network Load Balancer (NLB)"},{"id":"B","text":"Application Load Balancer com sticky sessions"},{"id":"C","text":"Gateway Load Balancer"},{"id":"D","text":"API Gateway HTTP API"}]'::jsonb, 'A',
  '{
    "summary": "L4 + IP estático + UDP + escala extrema = NLB.",
    "whyCorrect": "NLB opera na camada 4, fornece um IP estático por AZ (ou Elastic IP), preserva o IP de origem do cliente, suporta TCP/UDP/TLS e escala para milhões de requisições por segundo com latência ultra-baixa. É o único ELB que atende UDP.",
    "whyWrong": {
     "B": "ALB é L7, não suporta UDP, não tem IP estático (usa DNS) e não preserva IP de origem nativamente (precisa de X-Forwarded-For).",
     "C": "GWLB é para tráfego de inspeção via appliances, não para servir um endpoint público de aplicação.",
     "D": "API Gateway HTTP API é para REST HTTPS, não L4 nem UDP."
    },
    "keyConcept": "NLB — L4, IP estático, preservação de IP de origem, UDP",
    "compareWith": [
     "NLB vs ALB para preservar IP cliente",
     "NLB vs Global Accelerator para IP estático global"
    ],
    "realWorldContext": "Gaming UDP, IoT MQTT, sistemas legados que exigem IP allowlist, brokers financeiros.",
    "commonMistakes": "Achar que ALB também tem IP estático — não tem; somente NLB e Global Accelerator.",
    "tutorSeeds": [
     "Como NLB preserva o IP de origem para a EC2?",
     "Quando combinar NLB com Global Accelerator?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["nlb","elb","udp","static-ip"]'::jsonb, 'ai-draft', 'active', now(), now()
)
