INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-006', 'aws-clf', 'Uma aplicação HPC precisa que um conjunto de instâncias EC2 se comunique entre si com a menor latência de rede possível, dentro de uma mesma AZ. Qual placement group é mais adequado?',
  '[{"id":"A","text":"Spread placement group"},{"id":"B","text":"Cluster placement group"},{"id":"C","text":"Partition placement group"},{"id":"D","text":"Multi-AZ placement group"}]'::jsonb, 'B',
  '{
    "summary": "Cluster = instâncias próximas fisicamente para latência mínima.",
    "whyCorrect": "Cluster placement group aloca instâncias em um único rack/AZ próximo, oferecendo alta vazão (até 10 Gbps unicast / 25 Gbps multi-flow) e latência mínima. É a escolha para HPC, MPI, simulações científicas.",
    "whyWrong": {
     "A": "Spread separa cada instância em hardware distinto — maximiza disponibilidade, MINIMIZA proximidade. Latência maior. Limitado a 7 instâncias por AZ.",
     "C": "Partition divide o grupo em até 7 partições isoladas — usado por sistemas distribuídos (Cassandra, HDFS) que toleram falha por partição. Não minimiza latência intra-partição como cluster.",
     "D": "Multi-AZ placement group não existe — placement groups são por AZ por design."
    },
    "keyConcept": "Placement groups — Cluster (latência), Spread (HA), Partition (distribuído)",
    "compareWith": [
     "Cluster vs Spread vs Partition placement groups"
    ],
    "realWorldContext": "Workloads MPI, simulações de fluidos, ML training distribuído com NCCL.",
    "commonMistakes": "Usar cluster pensando que dá HA — é o oposto: tudo num rack significa falha correlacionada.",
    "tutorSeeds": [
     "Por que cluster placement group exige instâncias com Enhanced Networking?",
     "Quando partition placement faz sentido para HDFS?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["ec2","placement-group","hpc"]'::jsonb, 'ai-draft', 'active', now(), now()
)
