INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-007', 'aws-clf', 'Uma equipe usa um cluster Cassandra com 6 nós no EC2 e quer que falha de hardware afete no máximo 1 nó por vez. Qual placement group é o ideal?',
  '[{"id":"A","text":"Cluster placement group"},{"id":"B","text":"Spread placement group"},{"id":"C","text":"Partition placement group (6 partições)"},{"id":"D","text":"Nenhum, basta espalhar manualmente entre AZs"}]'::jsonb, 'C',
  '{
    "summary": "Partition placement isola failure domains — perfeito para Cassandra/HDFS/Kafka.",
    "whyCorrect": "Partition placement group divide as instâncias em partições lógicas (até 7 por AZ), cada uma em hardware independente. Cassandra/HDFS/Kafka mapeiam suas réplicas para partições diferentes — uma falha de rack afeta no máximo uma partição, e o cluster sobrevive.",
    "whyWrong": {
     "A": "Cluster concentra tudo no mesmo rack — falha derruba todos os nós ao mesmo tempo. O oposto do desejado.",
     "B": "Spread também isola, mas limita a 7 instâncias por AZ no total, sem o conceito de mapeamento partição-a-réplica. Funciona para até 7 instâncias críticas; para 6 nós Cassandra, partition oferece visibilidade da topologia.",
     "D": "Espalhar entre AZs ajuda mas não dá controle de partições dentro da AZ, e a latência cross-AZ degrada o cluster Cassandra."
    },
    "keyConcept": "Partition placement group — failure domains para sistemas distribuídos",
    "compareWith": [
     "Partition vs Spread",
     "Partition placement para Cassandra/HDFS/Kafka"
    ],
    "realWorldContext": "Operadores Kubernetes para StatefulSets, brokers Kafka, datanodes HDFS.",
    "commonMistakes": "Não usar a topology API para alinhar réplicas com partições — sem isso, o ganho é parcial.",
    "tutorSeeds": [
     "Como Cassandra usa a partition placement metadata?",
     "Limite de 7 partições por AZ — como contornar?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["ec2","placement-group","partition","distributed-systems"]'::jsonb, 'ai-draft', 'active', now(), now()
)
