INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-008', 'aws-clf', 'Uma empresa tem workload steady-state que roda 24/7 por 3 anos e quer máximo desconto em EC2, aceitando compromisso de capacidade. Qual modelo de compra oferece o maior desconto?',
  '[{"id":"A","text":"Savings Plans Compute (1 ano, no upfront)"},{"id":"B","text":"Spot Instances com fallback para On-Demand"},{"id":"C","text":"On-Demand com cost allocation tags"},{"id":"D","text":"Reserved Instances Standard 3 anos, all upfront"}]'::jsonb, 'D',
  '{
    "summary": "Maior desconto previsível = RI Standard 3y all upfront (até ~72%).",
    "whyCorrect": "Reserved Instances Standard de 3 anos com pagamento all upfront chegam a ~72% de desconto vs On-Demand. É o maior desconto entre opções comprometidas. O workload steady de 3 anos casa perfeitamente.",
    "whyWrong": {
     "A": "Savings Plans 1 ano no upfront dá ~27% — bem menor que RI 3y all upfront. Savings Plans tem flexibilidade maior mas desconto menor para mesmo prazo.",
     "B": "Spot oferece até 90% de desconto mas com interrupções de 2 minutos — não combina com workload 24/7 que exige disponibilidade contínua.",
     "C": "On-Demand é a tarifa cheia — zero desconto, só visibilidade via tags."
    },
    "keyConcept": "Modelos de pricing EC2 — On-Demand, Savings Plans, RIs, Spot, Dedicated",
    "compareWith": [
     "RI Standard vs Convertible",
     "Savings Plans Compute vs EC2 Instance",
     "RI vs Spot"
    ],
    "realWorldContext": "Bases de dados gerenciadas próprias, servidores LDAP, cargas que não tolerarão interrupção por 3 anos.",
    "commonMistakes": "Confundir Savings Plans com RI — SP é mais flexível (família/region) mas com desconto ligeiramente menor por prazo equivalente.",
    "tutorSeeds": [
     "Diferença entre Savings Plans Compute e EC2 Instance SP?",
     "Quando Convertible RI supera Standard RI?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["ec2","pricing","reserved-instances","savings-plans"]'::jsonb, 'ai-draft', 'active', now(), now()
)
