INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-009', 'aws-clf', 'Sobre o comportamento de health checks em um ALB com target group EC2, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"ALB roteia tráfego somente para targets marcados como healthy; targets unhealthy são removidos do pool e podem disparar replacement no ASG"},{"id":"B","text":"Health checks são apenas TCP — ALB não suporta HTTP health check"},{"id":"C","text":"Targets unhealthy continuam recebendo 50% do tráfego para ''aquecimento''"},{"id":"D","text":"ALB health checks só funcionam com instâncias t3.medium ou maiores"}]'::jsonb, 'A',
  '{
    "summary": "Targets só recebem tráfego quando healthy; unhealthy aciona ASG replacement se configurado.",
    "whyCorrect": "O ALB envia health checks HTTP/HTTPS (configuráveis: path, port, intervalo, threshold). Targets que falham N health checks consecutivos são marcados unhealthy e removidos do roteamento. Se o ASG usar ELB health check type, esses unhealthy disparam replacement automático da instância.",
    "whyWrong": {
     "B": "ALB suporta HTTP/HTTPS health checks com path customizável — é o padrão.",
     "C": "Targets unhealthy não recebem tráfego; aquecimento é feito por slow start (recurso separado do target group, opcional).",
     "D": "Não há restrição de tipo de instância para health checks — qualquer EC2 que abra a porta funciona."
    },
    "keyConcept": "ALB health checks + ASG ELB health check type para auto-recovery",
    "compareWith": [
     "ELB health check vs EC2 status check no ASG",
     "Health check vs Slow start"
    ],
    "realWorldContext": "Self-healing — uma instância travada em deadlock é detectada e substituída sem intervenção humana.",
    "commonMistakes": "Configurar threshold muito sensível (1 falha = unhealthy) e ter flapping de targets sob carga.",
    "tutorSeeds": [
     "Diferença entre health check do ALB e status check da EC2?",
     "O que é slow start no target group?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["elb","alb","health-check","asg"]'::jsonb, 'ai-draft', 'active', now(), now()
)
