INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-010', 'aws-clf', 'Uma equipe migra um workload Linux que usa Hyper-V drivers específicos e quer rodar em hardware AWS dedicado, mantendo affinity com o mesmo host físico para licenciamento por socket. Qual opção é a correta?',
  '[{"id":"A","text":"Dedicated Instances"},{"id":"B","text":"Dedicated Hosts"},{"id":"C","text":"Spot Block"},{"id":"D","text":"Capacity Reservations"}]'::jsonb, 'B',
  '{
    "summary": "Visibility do hardware físico + affinity = Dedicated Hosts.",
    "whyCorrect": "Dedicated Hosts dão visibilidade do servidor físico (sockets, cores), permitem host affinity (a instância sempre volta ao mesmo host após stop/start) e suportam BYOL com licenciamento por socket/core (Windows, Oracle, SQL Server). Único modelo que atende licenciamento por hardware físico.",
    "whyWrong": {
     "A": "Dedicated Instances também rodam em hardware dedicado, mas SEM visibilidade do host físico nem affinity — não atende licenciamento por socket.",
     "C": "Spot Block (descontinuado em alguns regions) não tem relação com hardware dedicado.",
     "D": "Capacity Reservations reservam capacidade em uma AZ, mas em hardware compartilhado — sem visibilidade do host físico."
    },
    "keyConcept": "Dedicated Hosts vs Dedicated Instances — visibility e affinity",
    "compareWith": [
     "Dedicated Hosts vs Dedicated Instances",
     "BYOL vs licença AWS-included"
    ],
    "realWorldContext": "Migração de Oracle/SQL Server com licença per-core, compliance que exige tenant isolation.",
    "commonMistakes": "Confundir Dedicated Instances com Hosts — ambos isolam tenant, só Hosts dão visibility/affinity.",
    "tutorSeeds": [
     "Como funciona host affinity após stop/start?",
     "Quando Dedicated Instance é suficiente?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["ec2","dedicated-hosts","licensing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
