INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-011', 'aws-clf', 'Uma equipe pequena tem uma API REST stateless escrita em Python que recebe ~50 requisições por minuto durante o dia útil e zero à noite. A equipe quer o menor esforço operacional e o menor custo possível. Qual serviço é mais indicado?',
  '[{"id":"A","text":"ECS Fargate com ALB"},{"id":"B","text":"EC2 t3.micro em ASG"},{"id":"C","text":"AWS Lambda atrás de API Gateway HTTP API"},{"id":"D","text":"AWS App Runner com container Python"}]'::jsonb, 'C',
  '{
    "summary": "Tráfego intermitente e baixo + zero ops = Lambda + API Gateway HTTP API.",
    "whyCorrect": "Lambda escala de 0 a N automaticamente, paga apenas por invocação + duração (free tier inclui 1M req/mês), zero servidor para gerenciar. API Gateway HTTP API é a opção mais barata e simples para expor Lambda. Para 50 req/min, custo mensal pode ficar em centavos.",
    "whyWrong": {
     "A": "Fargate exige task rodando 24/7 (mesmo idle) custando ~$10-15/mês mínimo. Para 50 req/min essa task fica 99% idle pagando.",
     "B": "EC2 mesmo t3.micro custa ~$7-8/mês e exige patching, ASG, ALB — overhead alto para volume baixo.",
     "D": "App Runner tem scale-to-zero em alguns modos, mas custo de provisioned instance idle ainda existe; menos vantajoso que Lambda para esse perfil."
    },
    "keyConcept": "Lambda vs Fargate vs App Runner vs EC2 — escolha por padrão de carga",
    "compareWith": [
     "Lambda (pay-per-request) vs Fargate (pay-per-task-second)",
     "Scale-to-zero capability"
    ],
    "realWorldContext": "MVPs, APIs internas de baixo volume, webhooks, backends mobile early-stage.",
    "commonMistakes": "Achar que Fargate é ''serverless igual Lambda'' — é serverless de container, mas paga continuamente.",
    "tutorSeeds": [
     "Quando Lambda fica mais caro que Fargate?",
     "App Runner scale-to-zero — quando vale?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["lambda","fargate","app-runner","serverless"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
