INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-012', 'aws-clf', 'Uma equipe migra um monolito Java de 800 MB com tempo de boot de 45 segundos para AWS. A função precisa de 2 vCPUs, 8 GB de RAM e tráfego constante (500 req/s, 24/7). Qual escolha minimiza custo e complexidade operacional?',
  '[{"id":"A","text":"AWS Lambda com SnapStart"},{"id":"B","text":"API Gateway + Lambda com 10 GB de memória"},{"id":"C","text":"App Runner com 1 GB de memória"},{"id":"D","text":"ECS Fargate com 2 tasks ALB-balanced"}]'::jsonb, 'D',
  '{
    "summary": "Tráfego constante + processo pesado de 8 GB = Fargate vence Lambda no custo.",
    "whyCorrect": "Para tráfego constante e alta carga, Lambda fica caro (paga por invocação × duração × memória) — 500 req/s em Lambda com 8 GB seria ordem de centenas de dólares/dia. Fargate roda containers continuamente com custo fixo por task; 2 tasks atendem facilmente 500 req/s, e o boot único de 45s acontece só no deploy.",
    "whyWrong": {
     "A": "SnapStart reduz cold start mas Lambda ainda custa por invocação — em tráfego constante de 500 req/s, é economicamente pior que Fargate. E SnapStart é apenas Java/Python/.NET, ajuda no startup mas não no custo de operação contínua.",
     "B": "10 GB memória em Lambda + alto throughput = custo enorme. Lambda max memory é 10 GB mas isso não muda o problema econômico.",
     "C": "App Runner com 1 GB não atende 8 GB de RAM do workload."
    },
    "keyConcept": "Crossover econômico Lambda → Fargate em workloads de alta utilização",
    "compareWith": [
     "Lambda vs Fargate por utilization",
     "SnapStart escopo de uso"
    ],
    "realWorldContext": "Aplicações JVM legadas, monolitos sendo modernizados parcialmente.",
    "commonMistakes": "Usar Lambda ''por padrão'' sem analisar custo em tráfego constante — pode ser 5-10x mais caro que Fargate.",
    "tutorSeeds": [
     "Qual o ponto de crossover Lambda/Fargate por utilization?",
     "Como SnapStart funciona internamente?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["lambda","fargate","cost-optimization","serverless-tradeoffs"]'::jsonb, 'ai-draft', 'active', now(), now()
)
