INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-013', 'aws-clf', 'Uma equipe quer hospedar uma aplicação web Node.js a partir de um repositório GitHub, com deploy automático em git push, scale-to-zero opcional e HTTPS gerenciado, sem escrever Dockerfile. Qual serviço é mais alinhado?',
  '[{"id":"A","text":"AWS App Runner (com source code)"},{"id":"B","text":"AWS Elastic Beanstalk"},{"id":"C","text":"ECS com Fargate e CodePipeline"},{"id":"D","text":"Lambda com camada Node.js"}]'::jsonb, 'A',
  '{
    "summary": "Code-to-URL sem Dockerfile + scale-to-zero = App Runner.",
    "whyCorrect": "App Runner aceita source code direto do GitHub (Node.js, Python, Java, etc.), constrói a imagem automaticamente, faz deploy contínuo a cada push, gerencia HTTPS e oferece scale-to-zero (provisioned 0 instances). É o serviço mais alinhado com ''do código à URL'' sem ops.",
    "whyWrong": {
     "B": "Elastic Beanstalk também suporta source mas é mais antigo, sem scale-to-zero nativo e expõe mais da infra subjacente (EC2/ASG/ELB).",
     "C": "ECS+Fargate+CodePipeline exige Dockerfile, definição de task, ALB — muito mais cerimônia.",
     "D": "Lambda exige adaptar a aplicação ao modelo de evento (handler), não roda Node.js HTTP server contínuo facilmente sem Lambda Web Adapter."
    },
    "keyConcept": "App Runner — source-to-URL serverless para containers/source",
    "compareWith": [
     "App Runner vs Elastic Beanstalk",
     "App Runner vs Fargate"
    ],
    "realWorldContext": "Sites institucionais, dashboards internos, APIs de baixa-média carga, MVPs.",
    "commonMistakes": "Achar que Elastic Beanstalk e App Runner são o mesmo — EB é PaaS expondo a infra; AR é fully managed.",
    "tutorSeeds": [
     "Quando App Runner não é suficiente (recursos)?",
     "App Runner suporta VPC connector?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["app-runner","serverless","deployment"]'::jsonb, 'ai-draft', 'active', now(), now()
)
