INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-015', 'aws-clf', 'Sobre o modelo de concurrency do AWS Lambda, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"Cada conta tem limite hard de 1000 execuções concorrentes que NÃO pode ser aumentado"},{"id":"B","text":"Provisioned concurrency é gratuita quando não invocada"},{"id":"C","text":"Reserved concurrency garante capacidade dedicada e também limita a função a esse valor máximo"},{"id":"D","text":"Concurrency é por região e por função, sem limite por conta"}]'::jsonb, 'C',
  '{
    "summary": "Reserved concurrency tem duplo papel: reserva E limita.",
    "whyCorrect": "Reserved concurrency reserva N execuções para a função (garantia mínima) e também atua como teto máximo. Útil para isolar funções críticas (garantir capacidade) e para limitar funções que poderiam consumir todo o pool da conta (rate limit downstream).",
    "whyWrong": {
     "A": "O limite default de 1000 por região POR CONTA pode ser aumentado via Service Quotas — não é hard.",
     "B": "Provisioned concurrency cobra por inicialização mantida QUENTE, mesmo sem invocação. Justamente o trade-off: latência baixa em troca de custo continuo.",
     "D": "Concurrency é por região POR CONTA (compartilhada entre funções), não ''sem limite por conta''."
    },
    "keyConcept": "Reserved vs Provisioned concurrency — duplo papel de reserved",
    "compareWith": [
     "Reserved concurrency vs Provisioned concurrency",
     "Account limit vs function limit"
    ],
    "realWorldContext": "Proteger RDS downstream contra avalanche de Lambdas via reserved=10.",
    "commonMistakes": "Confundir reserved (só garante slot, paga por invocação) com provisioned (mantém quente, paga sempre).",
    "tutorSeeds": [
     "Como reserved concurrency protege downstream?",
     "Quando provisioned vale o custo extra?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["lambda","concurrency","limits"]'::jsonb, 'ai-draft', 'active', now(), now()
)
