INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-016', 'aws-clf', 'Uma equipe quer minimizar latência de aplicação Lambda que serve uma API REST pública. Mediram p99 com cold start de 800ms. Querem reduzir para p99 < 100ms sem reescrever a função. Qual ação tem maior impacto?',
  '[{"id":"A","text":"Aumentar memória de 512 MB para 1024 MB"},{"id":"B","text":"Mudar runtime de Python para Go"},{"id":"C","text":"Habilitar X-Ray tracing"},{"id":"D","text":"Habilitar Provisioned Concurrency para a versão atual"}]'::jsonb, 'D',
  '{
    "summary": "Provisioned Concurrency mantém ambientes quentes — elimina cold start.",
    "whyCorrect": "Provisioned Concurrency pré-inicializa N ambientes (containers Lambda) e os mantém quentes. Cold start cai para ~10-20ms (essencialmente inexistente). Para uma API com SLA agressivo, é a ação de maior impacto e sem mudar código.",
    "whyWrong": {
     "A": "Aumentar memória reduz tempo de execução e cold start (proporcional a vCPU), mas ainda permanecerá cold start de centenas de ms em runtimes pesados — não chega a p99 < 100ms.",
     "B": "Mudar runtime é reescrita — viola a restrição ''sem reescrever''. E ainda haveria cold starts (menores, mas presentes).",
     "C": "X-Ray é observability, não reduz latência — pelo contrário, adiciona overhead leve."
    },
    "keyConcept": "Provisioned Concurrency — eliminação de cold start",
    "compareWith": [
     "Provisioned Concurrency vs SnapStart vs Lambda warmup tricks"
    ],
    "realWorldContext": "APIs públicas com SLA, checkout flows, gateways de pagamento.",
    "commonMistakes": "Provisioned em desenvolvimento — custo desnecessário; ative só em produção e em horários de alto tráfego (Application Auto Scaling).",
    "tutorSeeds": [
     "Como auto-scalar Provisioned Concurrency?",
     "SnapStart vs Provisioned — quando usar cada?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'troubleshoot', '["lambda","provisioned-concurrency","cold-start","performance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
