INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-017', 'aws-clf', 'Uma startup avalia Fargate vs App Runner para uma API de baixa carga (10 req/s) em container. Qual diferença é VERDADEIRA?',
  '[{"id":"A","text":"App Runner faz scale-to-zero (provisioned 0); Fargate exige task rodando continuamente"},{"id":"B","text":"Fargate é serverless mas App Runner exige gerenciar EC2 host"},{"id":"C","text":"App Runner não suporta HTTPS; Fargate sim via ALB"},{"id":"D","text":"Fargate suporta deploy do source code, App Runner não"}]'::jsonb, 'A',
  '{
    "summary": "App Runner = scale-to-zero possível; Fargate = task contínua.",
    "whyCorrect": "App Runner suporta modo ''provisioned instances = 0'' onde escala para zero em inatividade (com cold start na primeira req). Fargate exige pelo menos 1 task rodando para responder rápido — sem scale-to-zero nativo.",
    "whyWrong": {
     "B": "App Runner é serverless também; ninguém gerencia EC2 em App Runner.",
     "C": "App Runner provê HTTPS gerenciado nativamente — é uma das suas vantagens.",
     "D": "App Runner suporta deploy DIRETO do source code (Node/Python/Java/etc), Fargate exige imagem container."
    },
    "keyConcept": "App Runner vs Fargate — scale-to-zero e source-to-URL",
    "compareWith": [
     "App Runner vs Fargate vs Lambda"
    ],
    "realWorldContext": "APIs internas de uso esporádico, ambientes de dev/staging.",
    "commonMistakes": "Achar que Fargate é a opção ''mais serverless'' — App Runner é mais alto nível.",
    "tutorSeeds": [
     "App Runner suporta WebSocket?",
     "Quando Fargate vence App Runner em produção?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["app-runner","fargate","serverless-tradeoffs"]'::jsonb, 'ai-draft', 'active', now(), now()
)
