INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-018', 'aws-clf', 'Uma equipe usa Lambda integrado com SQS como event source. Mensagens estão sendo processadas múltiplas vezes inesperadamente. Qual é a causa MAIS provável?',
  '[{"id":"A","text":"SQS Standard sempre entrega exatamente uma vez; o problema é bug do código"},{"id":"B","text":"A função Lambda retorna erro ou timeout, fazendo a mensagem voltar à fila após VisibilityTimeout"},{"id":"C","text":"Lambda automaticamente duplica mensagens para garantir alta disponibilidade"},{"id":"D","text":"É necessário habilitar ''exactly-once delivery'' no Lambda (config padrão é ''at-least-many'')"}]'::jsonb, 'B',
  '{
    "summary": "Lambda + SQS = at-least-once. Erro/timeout = mensagem reaparece após VisibilityTimeout.",
    "whyCorrect": "Lambda+SQS é at-least-once por design. Se a função falhar (erro ou timeout) antes de retornar sucesso, o batch não é deletado da fila e reaparece após o VisibilityTimeout, sendo reprocessado. Soluções: garantir idempotência, ajustar VisibilityTimeout >= timeout do Lambda × 6, configurar maxReceiveCount + DLQ.",
    "whyWrong": {
     "A": "SQS Standard é at-least-once, não exactly-once. Só SQS FIFO oferece exactly-once dentro da janela de deduplicação.",
     "C": "Lambda não ''duplica para HA'' — o que pode haver é processamento paralelo de batches diferentes, não duplicação intencional.",
     "D": "Não existe flag ''exactly-once delivery'' no Lambda — a propriedade vem do tipo de fila (Standard vs FIFO) e da lógica idempotente da função."
    },
    "keyConcept": "Lambda + SQS — at-least-once delivery e VisibilityTimeout",
    "compareWith": [
     "SQS Standard vs FIFO entrega",
     "VisibilityTimeout vs Lambda timeout"
    ],
    "realWorldContext": "Processamento de pagamentos, ingestão de eventos — idempotência é mandatória.",
    "commonMistakes": "Setar VisibilityTimeout < timeout Lambda — garante reprocessamento mesmo quando função ainda está rodando.",
    "tutorSeeds": [
     "Por que VisibilityTimeout >= 6× Lambda timeout?",
     "Como implementar idempotência com DynamoDB?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'troubleshoot', '["lambda","sqs","at-least-once","idempotency"]'::jsonb, 'ai-draft', 'active', now(), now()
)
