INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-019', 'aws-clf', 'Em Amazon ECS, qual é a diferença correta entre task definition e service?',
  '[{"id":"A","text":"Service é o blueprint estático; task definition orquestra deploy"},{"id":"B","text":"Task definition só funciona com EC2 launch type; service só com Fargate"},{"id":"C","text":"Task definition é o ''blueprint'' (imagem, CPU, memória, env vars); service é o orquestrador que mantém N tasks rodando, integra com ALB e faz rolling updates"},{"id":"D","text":"Ambos são iguais — apenas nomes diferentes para o mesmo recurso"}]'::jsonb, 'C',
  '{
    "summary": "Task definition = receita; Service = controller que mantém desired count.",
    "whyCorrect": "Task definition descreve o quê (containers, CPU/mem, networking mode, volumes, env vars, IAM role, ports). Service usa essa task definition e mantém um desired count de tasks rodando, atualiza versões (rolling/blue-green via CodeDeploy), integra com target groups ALB/NLB e Service Discovery.",
    "whyWrong": {
     "A": "Inverte os papéis — task def é blueprint, service é orquestrador.",
     "B": "Task definitions e services funcionam em ambos launch types (EC2 e Fargate). O launch type é uma propriedade.",
     "D": "São recursos distintos com responsabilidades distintas."
    },
    "keyConcept": "ECS — task definition (template) vs task (instância) vs service (controller)",
    "compareWith": [
     "ECS Task vs Pod do K8s",
     "ECS Service vs Deployment do K8s"
    ],
    "realWorldContext": "Microsserviços ECS com 20 services, cada um com sua task definition e auto-scaling independente.",
    "commonMistakes": "Confundir task com task definition — task é a execução, task definition é o JSON do blueprint.",
    "tutorSeeds": [
     "O que é Task Family e versionamento de task definition?",
     "ECS Service vs Standalone Task (RunTask)?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["ecs","task-definition","service"]'::jsonb, 'ai-draft', 'active', now(), now()
)
