INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-020', 'aws-clf', 'Uma equipe migra cargas Kubernetes para AWS e quer evitar gerenciar EC2 worker nodes. Quer rodar pods diretamente em capacidade serverless. Qual configuração é adequada?',
  '[{"id":"A","text":"EKS com Managed Node Groups EC2"},{"id":"B","text":"EKS Self-Managed Nodes"},{"id":"C","text":"ECS com Fargate"},{"id":"D","text":"EKS com Fargate profiles"}]'::jsonb, 'D',
  '{
    "summary": "EKS + Fargate profiles = pods serverless sem gerenciar nodes.",
    "whyCorrect": "EKS Fargate profiles permitem que pods que matchem o seletor (namespace/labels) rodem em capacidade Fargate, sem worker nodes EC2. Você não gerencia EC2, patching, escalonamento de nodes — apenas pods.",
    "whyWrong": {
     "A": "Managed Node Groups EC2 ainda exigem gerenciamento (AWS provê a infra mas você ainda lida com escalonamento de nodes, atualizações de AMI, instance types).",
     "B": "Self-managed é o mais hands-on — você cria EC2, instala kubelet, junta no cluster.",
     "C": "ECS Fargate atende serverless de containers, MAS NÃO é Kubernetes. A questão pede manter K8s."
    },
    "keyConcept": "EKS launch options — Fargate, Managed Node Groups, Self-managed",
    "compareWith": [
     "EKS Fargate vs Managed Node Groups",
     "EKS vs ECS"
    ],
    "realWorldContext": "Migração lift-and-shift de cluster K8s on-prem mantendo manifests, mas sem gerenciar nodes.",
    "commonMistakes": "Esquecer limites do Fargate no EKS — sem DaemonSets, sem privileged pods, sem GPUs.",
    "tutorSeeds": [
     "O que Fargate profile NÃO suporta no EKS?",
     "Como dimensionar mix Fargate + Managed nodes?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["eks","fargate","serverless"]'::jsonb, 'ai-draft', 'active', now(), now()
)
