INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-021', 'aws-clf', 'Uma equipe usa Amazon ECR e quer detectar vulnerabilidades em imagens push (CVE de pacotes do SO e bibliotecas). Qual recurso oferece scan profundo contínuo?',
  '[{"id":"A","text":"ECR Enhanced Scanning (Amazon Inspector)"},{"id":"B","text":"ECR Basic Scanning (Clair)"},{"id":"C","text":"GuardDuty Malware Protection for ECR"},{"id":"D","text":"AWS Config managed rule ecr-image-scan"}]'::jsonb, 'A',
  '{
    "summary": "ECR Enhanced Scanning usa Amazon Inspector para scan contínuo e profundo (SO + linguagens).",
    "whyCorrect": "Enhanced Scanning integra Amazon Inspector, faz scan contínuo de imagens (não só no push), detecta CVE em pacotes do SO (Alpine, Debian, etc.) e bibliotecas de aplicação (npm, pip, Maven, etc.). Cobertura muito mais profunda que Basic.",
    "whyWrong": {
     "B": "Basic Scanning usa CoreOS Clair — só escaneia no push, só CVE de SO, sem cobertura de bibliotecas de linguagem.",
     "C": "GuardDuty Malware Protection é para detecção de malware em volumes EBS (não para CVE de imagem container).",
     "D": "Config rule pode VERIFICAR se scan está habilitado mas não realiza o scan em si."
    },
    "keyConcept": "ECR Basic vs Enhanced Scanning (Inspector integration)",
    "compareWith": [
     "ECR Basic vs Enhanced Scanning",
     "Inspector EC2 vs Inspector ECR"
    ],
    "realWorldContext": "Pipelines DevSecOps com gate de vulnerabilidades antes de promoção a prod.",
    "commonMistakes": "Achar que Basic Scanning detecta CVE em libs Python/Node — só pega SO.",
    "tutorSeeds": [
     "Como configurar threshold de CVE no ECR?",
     "Custos de Enhanced Scanning vs Basic?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["ecr","security","scanning","inspector"]'::jsonb, 'ai-draft', 'active', now(), now()
)
