INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-022', 'aws-clf', 'Uma equipe ECS Fargate quer compartilhar um volume entre dois containers da mesma task. Qual recurso suporta esse compartilhamento?',
  '[{"id":"A","text":"EBS volume diretamente attached à task Fargate"},{"id":"B","text":"Bind mount (volume Docker padrão) na task definition"},{"id":"C","text":"Instance Store da EC2 host"},{"id":"D","text":"S3 montado como filesystem via FUSE"}]'::jsonb, 'B',
  '{
    "summary": "Bind mounts compartilham dados efêmeros entre containers da mesma task Fargate.",
    "whyCorrect": "Bind mounts (volume tipo ''bind'') montam um diretório efêmero da task em múltiplos containers da mesma task — perfeito para sidecar patterns onde, ex., um container baixa config e outro consome. Dados são perdidos quando a task termina.",
    "whyWrong": {
     "A": "EBS attachado a Fargate é recente e suportado, mas o caso pede compartilhamento entre containers da MESMA task — bind mount é o padrão idiomático. EBS é para persistência além da vida da task.",
     "C": "Instance Store de EC2 host não se aplica — Fargate não expõe host.",
     "D": "S3 via FUSE não é nativo nem suportado para ECS Fargate task storage."
    },
    "keyConcept": "ECS volumes — bind mounts (efêmero compartilhado) vs EFS (persistente) vs EBS Fargate",
    "compareWith": [
     "Bind mount vs EFS volume vs EBS volume em ECS"
    ],
    "realWorldContext": "Sidecar de log shipping lendo logs de container principal via volume compartilhado.",
    "commonMistakes": "Esperar persistência em bind mount — dados morrem com a task.",
    "tutorSeeds": [
     "Quando usar EFS volume em ECS?",
     "Limites de tamanho do bind mount no Fargate?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["ecs","fargate","volumes","sidecar"]'::jsonb, 'ai-draft', 'active', now(), now()
)
