INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-023', 'aws-clf', 'Em EKS, uma equipe quer auto-escalar pods baseado em métricas customizadas (ex: msgs em fila SQS). Qual combinação é a padrão?',
  '[{"id":"A","text":"Horizontal Pod Autoscaler (HPA) + Metrics Server apenas"},{"id":"B","text":"Cluster Autoscaler do EKS"},{"id":"C","text":"HPA + KEDA (Kubernetes Event-Driven Autoscaling)"},{"id":"D","text":"AWS Auto Scaling Group no Managed Node Group"}]'::jsonb, 'C',
  '{
    "summary": "HPA + KEDA = autoscaling de pods por eventos externos (SQS, Kafka, etc.).",
    "whyCorrect": "HPA nativo só escala em CPU/memória ou métricas via Metrics Server. KEDA estende HPA com scalers para 50+ fontes (SQS, Kafka, Prometheus, etc.), incluindo scale-to-zero. É o padrão de fato para event-driven autoscaling no K8s.",
    "whyWrong": {
     "A": "Metrics Server só expõe CPU/memória dos pods — não enxerga SQS.",
     "B": "Cluster Autoscaler ajusta o número de NODES, não pods.",
     "D": "ASG do Managed Node Group escala nodes, não pods. E não enxerga SQS diretamente."
    },
    "keyConcept": "Kubernetes autoscaling — HPA (pods), VPA (recursos do pod), Cluster Autoscaler (nodes), KEDA (event-driven)",
    "compareWith": [
     "HPA vs KEDA",
     "Cluster Autoscaler vs Karpenter"
    ],
    "realWorldContext": "Workers consumindo de SQS que precisam escalar de 0 a 100 conforme depth da fila.",
    "commonMistakes": "Confundir HPA com Cluster Autoscaler — operam em camadas diferentes.",
    "tutorSeeds": [
     "KEDA vs HPA com External Metrics — diferença prática?",
     "Karpenter vs Cluster Autoscaler no EKS?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["eks","autoscaling","keda","hpa"]'::jsonb, 'ai-draft', 'active', now(), now()
)
