INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-024', 'aws-clf', 'Uma equipe ECS quer fazer service discovery entre microsserviços sem usar ALB. Cada serviço deve ser resolvível por nome DNS interno. Qual recurso AWS é o nativo para isso?',
  '[{"id":"A","text":"Route 53 público com health checks"},{"id":"B","text":"CloudFront com behaviors por serviço"},{"id":"C","text":"DynamoDB com lookup table"},{"id":"D","text":"AWS Cloud Map (Service Discovery) integrado com ECS"}]'::jsonb, 'D',
  '{
    "summary": "AWS Cloud Map = service discovery DNS nativo do ECS.",
    "whyCorrect": "Cloud Map cria namespaces (públicos ou privados via Route 53) e registra automaticamente tasks ECS com nomes DNS, atualizando entries conforme tasks sobem/descem. Cliente faz lookup do nome e recebe IPs/portas atuais — sem ALB.",
    "whyWrong": {
     "A": "Route 53 público não é apropriado para internal service discovery dinâmico de tasks que sobem/descem frequentemente — Cloud Map é a camada acima do Route 53 privado que automatiza isso.",
     "B": "CloudFront é CDN, sem relação com service discovery.",
     "C": "DynamoDB lookup é solução caseira — não nativa, exige código de cliente."
    },
    "keyConcept": "ECS Service Discovery via AWS Cloud Map",
    "compareWith": [
     "Cloud Map vs ALB para microsserviços",
     "Cloud Map vs Service Mesh (App Mesh)"
    ],
    "realWorldContext": "Comunicação service-to-service sem balanceador L7 intermediário (redução de hop + latência).",
    "commonMistakes": "Achar que ALB é obrigatório para microsserviços — em meshes internos Cloud Map basta.",
    "tutorSeeds": [
     "Quando service mesh supera service discovery puro?",
     "Cloud Map para EKS — mesmo modelo?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["ecs","service-discovery","cloud-map"]'::jsonb, 'ai-draft', 'active', now(), now()
)
