INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-025', 'aws-clf', 'Uma empresa armazena 2 PB de dados em S3 mas não sabe quais objetos serão acessados em que frequência. Quer otimizar custo sem riscos de retrieval fees inesperados. Qual storage class é o melhor padrão?',
  '[{"id":"A","text":"S3 Intelligent-Tiering (com tier de Deep Archive opcional)"},{"id":"B","text":"S3 Standard"},{"id":"C","text":"S3 Glacier Flexible Retrieval"},{"id":"D","text":"S3 One Zone-IA"}]'::jsonb, 'A',
  '{
    "summary": "Padrão desconhecido + zero retrieval fees = Intelligent-Tiering.",
    "whyCorrect": "Intelligent-Tiering monitora padrão de acesso por objeto e move automaticamente entre Frequent, Infrequent (30 dias sem acesso), Archive Instant (90 dias), Archive (90+ dias opt-in) e Deep Archive (180+ dias opt-in). Sem retrieval fees nos tiers padrão. Cobra pequena taxa de monitoramento por objeto.",
    "whyWrong": {
     "B": "Standard é o mais caro para storage — não otimiza nada para 2 PB.",
     "C": "Glacier Flexible Retrieval impõe minutos-horas de retrieval e retrieval fees — risco se padrão for misto.",
     "D": "One Zone-IA pressupõe acesso infrequente E tolerância a perda de AZ. Sem saber o padrão, é arriscado."
    },
    "keyConcept": "S3 Intelligent-Tiering — auto-tiering sem retrieval fees nos tiers padrão",
    "compareWith": [
     "Standard vs Intelligent-Tiering vs Glacier",
     "Auto-tiering vs Lifecycle manual"
    ],
    "realWorldContext": "Data lakes, ML datasets, archives de empresa sem padrões claros.",
    "commonMistakes": "Habilitar opt-in tiers (Archive/Deep Archive) sem entender retrieval times — pode quebrar SLA de leitura.",
    "tutorSeeds": [
     "Como funciona a taxa de monitoramento do IT?",
     "Quando IT NÃO compensa (objetos < 128 KB)?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["s3","intelligent-tiering","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
