INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-026', 'aws-clf', 'Uma equipe precisa de um storage class S3 para dados temporários (logs intermediários) acessados algumas vezes por mês, podendo TOLERAR perda em caso de desastre de uma AZ específica. Qual é o mais econômico?',
  '[{"id":"A","text":"S3 Standard-IA"},{"id":"B","text":"S3 One Zone-IA"},{"id":"C","text":"S3 Glacier Instant Retrieval"},{"id":"D","text":"S3 Standard"}]'::jsonb, 'B',
  '{
    "summary": "Acesso infrequente + tolera falha de AZ = One Zone-IA (até 20% mais barato que Standard-IA).",
    "whyCorrect": "S3 One Zone-IA armazena dados em uma única AZ (vs 3+ em outras classes). Para dados recriáveis ou temporários, custo é ~20% menor que Standard-IA. Acesso infrequente com retrieval rápido e baixas fees.",
    "whyWrong": {
     "A": "Standard-IA também é IA mas multi-AZ — mais caro que One Zone-IA para o mesmo padrão de acesso.",
     "C": "Glacier Instant Retrieval é até mais barato em storage mas tem retrieval fees mais altos e mínimo de 90 dias de armazenamento — penaliza dados temporários.",
     "D": "Standard não otimiza para acesso infrequente."
    },
    "keyConcept": "One Zone-IA — trade durabilidade-de-AZ por custo",
    "compareWith": [
     "Standard-IA (3-AZ) vs One Zone-IA (1-AZ)",
     "One Zone-IA vs Glacier IR"
    ],
    "realWorldContext": "Backups secundários, logs de debug, intermediários de pipeline ETL.",
    "commonMistakes": "Usar One Zone-IA para dados originais únicos — perda de AZ = dados perdidos para sempre.",
    "tutorSeeds": [
     "Por que One Zone-IA tem 99.5% disponibilidade vs 99.9% das outras?",
     "Min storage duration de cada IA class?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["s3","one-zone-ia","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
