INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-027', 'aws-clf', 'Sobre S3 Glacier — Instant Retrieval, Flexible Retrieval e Deep Archive — qual afirmação está CORRETA?',
  '[{"id":"A","text":"Os três têm o mesmo tempo de retrieval (12h); só o preço difere"},{"id":"B","text":"Deep Archive não permite retrieval algum — só restore via Snowball"},{"id":"C","text":"Instant Retrieval entrega objetos em milissegundos (como S3 Standard), Flexible em minutos-horas, Deep Archive em horas (até 12h)"},{"id":"D","text":"Instant Retrieval e Flexible Retrieval são o mesmo serviço com nomes diferentes"}]'::jsonb, 'C',
  '{
    "summary": "Três tiers Glacier com retrieval crescente: ms / minutos-horas / horas.",
    "whyCorrect": "Glacier Instant Retrieval (GIR) entrega em milissegundos como Standard — para dados acessados ~uma vez/trimestre. Flexible Retrieval (antigo Glacier) oferece Expedited (1-5 min), Standard (3-5h), Bulk (5-12h). Deep Archive é o mais barato com retrieval em ~12h (Standard) ou 48h (Bulk).",
    "whyWrong": {
     "A": "Têm tempos muito diferentes — diferença central entre eles.",
     "B": "Deep Archive permite retrieval via S3 (RestoreObject) — Snowball é opcional para grandes volumes.",
     "D": "São distintos: IR é ms; Flexible é minutos-horas. Preços e SLAs diferentes."
    },
    "keyConcept": "Glacier tiers — IR (ms) / Flexible (min-h) / Deep Archive (h)",
    "compareWith": [
     "Glacier IR vs Standard-IA",
     "Glacier Flexible vs Deep Archive"
    ],
    "realWorldContext": "Compliance financeiro/saúde com retenção 7-10 anos = Deep Archive; arquivos ''cold'' com leitura ocasional rápida = IR.",
    "commonMistakes": "Achar ''Glacier = lento'' indiscriminadamente — GIR é instantâneo.",
    "tutorSeeds": [
     "Minimum storage duration de cada tier Glacier?",
     "Custos de retrieval comparados?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["s3","glacier","tiers","retrieval"]'::jsonb, 'ai-draft', 'active', now(), now()
)
