INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-028', 'aws-clf', 'Uma equipe configura S3 Lifecycle Policy para transitar objetos: Standard → Standard-IA (30 dias) → Glacier Flexible (90 dias) → expiration (365 dias). Qual restrição é VERDADEIRA?',
  '[{"id":"A","text":"Não há restrição — qualquer transição é livre"},{"id":"B","text":"Glacier exige que objetos tenham nascido em Glacier; transição é proibida"},{"id":"C","text":"Expiration não pode ocorrer antes de 1000 dias"},{"id":"D","text":"Standard-IA exige objetos com pelo menos 30 dias E tamanho mínimo de 128 KB para a transição fazer sentido (min storage duration de 30 dias)"}]'::jsonb, 'D',
  '{
    "summary": "S3-IA cobra min 30 dias de armazenamento + min 128 KB por objeto.",
    "whyCorrect": "Standard-IA, One Zone-IA e Glacier IR têm minimum storage duration de 30 dias (cobrado mesmo se deletar antes) e minimum billable object size de 128 KB (objetos menores são cobrados como 128 KB). Glacier Flexible tem min de 90 dias; Deep Archive 180 dias. Por isso transitar objeto pequeno cedo pode AUMENTAR custo.",
    "whyWrong": {
     "A": "Há restrições importantes de minimum storage e size.",
     "B": "S3 transita normalmente para Glacier; não exige origem em Glacier.",
     "C": "Expiration pode ocorrer em qualquer prazo configurado (1 dia em diante)."
    },
    "keyConcept": "S3 Lifecycle — minimum storage duration e min billable object size por tier",
    "compareWith": [
     "Min storage duration por storage class",
     "Object size penalties em IA tiers"
    ],
    "realWorldContext": "Logs muito pequenos (<128 KB) podem ficar mais caros em IA do que em Standard.",
    "commonMistakes": "Transitar milhões de objetos pequenos para IA — explode o custo por causa do min 128 KB.",
    "tutorSeeds": [
     "Por que IA tiers cobram min 128 KB?",
     "Como evitar custo extra com objetos pequenos?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["s3","lifecycle","minimum-duration","cost"]'::jsonb, 'ai-draft', 'active', now(), now()
)
