INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-029', 'aws-clf', 'Uma equipe ativa S3 Intelligent-Tiering em um bucket. Qual recurso adicional permite analisar e VISUALIZAR padrões de acesso para decidir lifecycle policies em outros buckets?',
  '[{"id":"A","text":"S3 Analytics — Storage Class Analysis"},{"id":"B","text":"S3 Storage Lens"},{"id":"C","text":"S3 Inventory apenas"},{"id":"D","text":"CloudWatch Metrics for S3"}]'::jsonb, 'A',
  '{
    "summary": "Storage Class Analysis observa padrão de acesso e recomenda lifecycle para Standard-IA.",
    "whyCorrect": "S3 Analytics — Storage Class Analysis monitora padrões de acesso (idade do objeto vs acesso) e produz recomendações para transitar para Standard-IA. Output em CSV exportável e visualizável no console.",
    "whyWrong": {
     "B": "Storage Lens dá analytics organizacional agregado (uso, custo, atividade) mas não recomenda transitions específicas como Analytics.",
     "C": "Inventory lista objetos e metadados (CSV/Parquet) mas não analisa padrões de acesso.",
     "D": "CloudWatch Metrics tem métricas de bucket (BucketSizeBytes, NumberOfObjects) mas não padrão de acesso por objeto."
    },
    "keyConcept": "S3 observability — Storage Lens (org-wide) vs Analytics (per-bucket access pattern) vs Inventory (object list)",
    "compareWith": [
     "Storage Lens vs Storage Class Analysis vs Inventory"
    ],
    "realWorldContext": "FinOps team usando Analytics para justificar lifecycle policies a stakeholders.",
    "commonMistakes": "Confundir Storage Lens com Storage Class Analysis — propósitos diferentes.",
    "tutorSeeds": [
     "Quando Storage Lens é melhor que Analytics?",
     "Inventory uses case com Athena?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["s3","analytics","storage-class-analysis"]'::jsonb, 'ai-draft', 'active', now(), now()
)
