INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-030', 'aws-clf', 'Uma equipe quer impedir que objetos S3 sejam modificados ou deletados por X dias, mesmo por administradores root, para atender compliance financeira (SEC 17a-4). Qual recurso fornece WORM (Write Once Read Many) verificável?',
  '[{"id":"A","text":"S3 Versioning + MFA Delete"},{"id":"B","text":"S3 Object Lock em modo Compliance com retention period"},{"id":"C","text":"S3 Bucket Policy com Deny em DeleteObject"},{"id":"D","text":"IAM Policy com Effect: Deny em s3:DeleteObject"}]'::jsonb, 'B',
  '{
    "summary": "WORM verificável (até root) = S3 Object Lock modo Compliance.",
    "whyCorrect": "Object Lock em modo Compliance impede DELETE/OVERWRITE de versão por X dias — nem root da conta pode contornar. Atende SEC 17a-4(f), FINRA, CFTC. Modo Governance é menos rígido (root pode contornar com bypass permission).",
    "whyWrong": {
     "A": "Versioning + MFA Delete protege contra deleção acidental mas root pode desabilitar MFA Delete — não é WORM verificável.",
     "C": "Bucket Policy pode ser editada por quem tem permissão de s3:PutBucketPolicy (admins) — não é imutável.",
     "D": "IAM Deny pode ser revertido por admins; não atende WORM."
    },
    "keyConcept": "S3 Object Lock — Compliance (imutável) vs Governance (bypass possível)",
    "compareWith": [
     "Object Lock Compliance vs Governance",
     "Object Lock vs Versioning vs MFA Delete"
    ],
    "realWorldContext": "Bancos, corretoras, healthcare records (HIPAA), audit logs imutáveis.",
    "commonMistakes": "Habilitar Object Lock e definir retention errada — não há como remover em Compliance até expirar.",
    "tutorSeeds": [
     "Como funciona Legal Hold em Object Lock?",
     "Object Lock + Cross-Region Replication?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["s3","object-lock","compliance","worm"]'::jsonb, 'ai-draft', 'active', now(), now()
)
