INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-031', 'aws-clf', 'Uma equipe migra para S3 e quer copiar 50 TB de dados on-prem para AWS em poucos dias, com link de internet de 1 Gbps lento e instável. Qual serviço minimiza o tempo?',
  '[{"id":"A","text":"S3 Transfer Acceleration via internet"},{"id":"B","text":"AWS DataSync via VPN"},{"id":"C","text":"AWS Snowball Edge Storage Optimized (físico)"},{"id":"D","text":"Upload manual via aws s3 cp em paralelo"}]'::jsonb, 'C',
  '{
    "summary": "50 TB com link ruim = enviar dispositivo físico (Snowball).",
    "whyCorrect": "Snowball Edge Storage Optimized carrega até 80 TB por device. Você copia localmente (LAN), AWS transporta fisicamente, ingere em S3. Para 50 TB com 1 Gbps real (~500 Mbps efetivo), upload pela internet levaria ~10 dias — Snowball entrega em 1 semana incluindo logística.",
    "whyWrong": {
     "A": "Transfer Acceleration ainda usa o seu link de saída — 1 Gbps lento e instável continua sendo o gargalo.",
     "B": "DataSync acelera vs scripts manuais mas continua dependendo do link 1 Gbps — mesmo problema.",
     "D": "aws s3 cp paralelo é o pior — a CLI nem aproveita Transfer Acceleration sem flag, e o link instável quebra uploads."
    },
    "keyConcept": "AWS Snow Family — Snowcone / Snowball Edge / Snowmobile para migração offline",
    "compareWith": [
     "Snowball vs DataSync vs Direct Connect vs S3 TA"
    ],
    "realWorldContext": "Migração de datacenters legados sem boa conectividade, edge data ingestion de navios/minerações.",
    "commonMistakes": "Insistir em rede para grandes volumes — fisicamente enviar disco vence até ~100 TB.",
    "tutorSeeds": [
     "Quando DataSync vence Snowball?",
     "Snowmobile vs Snowball para escalas PB+?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["s3","snowball","migration"]'::jsonb, 'ai-draft', 'active', now(), now()
)
