INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-032', 'aws-clf', 'Uma aplicação faz uploads de objetos S3 de 8 GB cada. A equipe quer maior throughput e resiliência a falhas durante upload. Qual técnica é recomendada?',
  '[{"id":"A","text":"Aumentar timeout do cliente HTTP"},{"id":"B","text":"Comprimir o objeto antes (gzip)"},{"id":"C","text":"Trocar para S3 One Zone-IA"},{"id":"D","text":"Multipart Upload (paralelizar partes e retomar partes falhas)"}]'::jsonb, 'D',
  '{
    "summary": "Objetos > 100 MB devem usar Multipart Upload por throughput e retomada.",
    "whyCorrect": "Multipart Upload divide o objeto em partes (5 MB-5 GB cada), permite paralelismo (mais throughput) e retomada de partes que falharam sem reenviar tudo. AWS recomenda multipart para objetos > 100 MB; mandatório para > 5 GB.",
    "whyWrong": {
     "A": "Timeout maior só atrasa o erro — não acelera nem dá resiliência a falhas de rede.",
     "B": "Compressão pode ajudar mas não é a técnica idiomática de upload — e pode não comprimir se o conteúdo já for binário/compactado.",
     "C": "Storage class não tem efeito sobre upload performance."
    },
    "keyConcept": "S3 Multipart Upload — paralelismo + retomada + objetos > 5 GB",
    "compareWith": [
     "PUT single-part vs Multipart Upload",
     "Multipart vs Transfer Acceleration"
    ],
    "realWorldContext": "Vídeos brutos de produção, datasets ML, backups de databases.",
    "commonMistakes": "Não abortar multipart uploads incompletos — partes ficam cobrando indefinidamente; configure lifecycle rule para abort incomplete multipart uploads.",
    "tutorSeeds": [
     "Tamanho ótimo de cada parte para vazão máxima?",
     "Multipart Upload + Transfer Acceleration juntos?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["s3","multipart-upload","performance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
