INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-033', 'aws-clf', 'Uma equipe precisa de volume EBS para um banco de dados que sustenta 30.000 IOPS com latência sub-ms consistente e durabilidade extra (99.999%). Qual tipo é o adequado?',
  '[{"id":"A","text":"io2 Block Express"},{"id":"B","text":"gp3"},{"id":"C","text":"st1 (throughput optimized HDD)"},{"id":"D","text":"sc1 (cold HDD)"}]'::jsonb, 'A',
  '{
    "summary": "Alto IOPS + sub-ms + 99.999% durabilidade = io2 Block Express.",
    "whyCorrect": "io2 Block Express suporta até 256.000 IOPS, 4.000 MB/s throughput, latência sub-ms, durabilidade 99.999% (vs 99.8-99.9% das outras famílias). Único EBS com esse SLA de durabilidade. Ideal para bancos críticos.",
    "whyWrong": {
     "B": "gp3 suporta até 16.000 IOPS — insuficiente para 30.000. Durabilidade 99.8-99.9%.",
     "C": "st1 é HDD throughput-optimized — não IOPS. Não cabe.",
     "D": "sc1 é cold HDD para acesso esporádico — totalmente inadequado para DB."
    },
    "keyConcept": "EBS volume types — gp3 vs io2 vs io2 Block Express vs st1 vs sc1",
    "compareWith": [
     "io2 vs io2 Block Express",
     "gp3 vs io2 cost-benefit"
    ],
    "realWorldContext": "Oracle/SQL Server críticos, SAP HANA, NoSQL high-throughput.",
    "commonMistakes": "Usar io2 ou gp3 quando 30k IOPS exige Block Express; ou superprovisionar gp3 pagando sem entregar.",
    "tutorSeeds": [
     "Por que io2 Block Express precisa de Nitro instances?",
