INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-034', 'aws-clf', 'Uma equipe rodava banco em volume gp2 de 500 GB (1.500 IOPS baseline). Migrou para gp3 mantendo 500 GB e config padrão. Qual mudança de performance/custo é VERDADEIRA?',
  '[{"id":"A","text":"gp3 entrega menos IOPS que gp2 nesse tamanho"},{"id":"B","text":"gp3 entrega 3.000 IOPS e 125 MB/s baseline INDEPENDENTE do tamanho, e é ~20% mais barato por GB que gp2"},{"id":"C","text":"gp3 e gp2 são equivalentes em IOPS/preço"},{"id":"D","text":"gp3 só é vantajoso para volumes \u003e 1 TB"}]'::jsonb, 'B',
  '{
    "summary": "gp3 desacopla IOPS/throughput do tamanho — 3k IOPS e 125 MB/s baseline em qualquer GB.",
    "whyCorrect": "gp2 amarra IOPS a tamanho (3 IOPS/GB). gp3 oferece 3.000 IOPS e 125 MB/s baseline para qualquer tamanho, e custa ~20% menos por GB. Pode-se provisionar até 16.000 IOPS / 1.000 MB/s adicionais pagando extra. Ganho duplo: mais IOPS por menos custo no caso de 500 GB.",
    "whyWrong": {
     "A": "gp3 com 3k baseline supera os 1.500 IOPS do gp2 a 500 GB.",
     "C": "Há diferença real — desacoplamento de IOPS e preço menor.",
     "D": "gp3 é vantajoso em quase todos tamanhos — especialmente em volumes pequenos onde gp2 oferece pouco IOPS."
    },
    "keyConcept": "gp3 vs gp2 — desacoplamento de IOPS/throughput do tamanho",
    "compareWith": [
     "gp3 vs gp2",
     "gp3 baseline vs provisioned extra"
    ],
    "realWorldContext": "Migração massiva de gp2 → gp3 para reduzir custo sem perder performance.",
    "commonMistakes": "Não migrar volumes gp2 antigos — está deixando dinheiro na mesa.",
    "tutorSeeds": [
     "Como migrar gp2 → gp3 sem downtime?",
     "Quando gp3 NÃO compensa vs gp2?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["ebs","gp3","gp2","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
