INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-035', 'aws-clf', 'Uma equipe precisa de filesystem NFS compartilhado por 200 EC2 Linux em múltiplas AZs com burst de I/O imprevisível. Qual EFS performance mode + throughput mode é o adequado?',
  '[{"id":"A","text":"Max I/O performance mode + Bursting throughput"},{"id":"B","text":"General Purpose + Provisioned (com 50 MB/s reservados)"},{"id":"C","text":"General Purpose performance mode + Elastic throughput"},{"id":"D","text":"Max I/O + Provisioned"}]'::jsonb, 'C',
  '{
    "summary": "Workload imprevisível com 200 clients = General Purpose + Elastic.",
    "whyCorrect": "General Purpose performance mode oferece latência mais baixa e é recomendado para a maioria dos casos. Elastic throughput escala automaticamente até 10 GB/s read / 3 GB/s write conforme demanda, ideal para padrões imprevisíveis. Sem necessidade de provisionar capacity antes.",
    "whyWrong": {
     "A": "Max I/O é apenas para workloads MUITO paralelos (milhares de clients) e tem latência mais alta. Bursting tem créditos finitos.",
     "B": "Provisioned é determinístico mas paga mesmo sem uso — pior para imprevisível.",
     "D": "Max I/O + Provisioned combina overhead e custo desnecessário."
    },
    "keyConcept": "EFS performance modes (General Purpose vs Max I/O) e throughput modes (Bursting, Provisioned, Elastic)",
    "compareWith": [
     "EFS Elastic vs Provisioned vs Bursting"
    ],
    "realWorldContext": "Web servers compartilhando assets, build farms, ML training data shared.",
    "commonMistakes": "Escolher Max I/O ''para garantir'' — paga mais latência sem necessidade real.",
    "tutorSeeds": [
     "Quando Max I/O é realmente necessário?",
     "Como funcionam burst credits do EFS?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["efs","performance-mode","throughput-mode"]'::jsonb, 'ai-draft', 'active', now(), now()
)
