INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-036', 'aws-clf', 'Uma empresa de mídia precisa de filesystem paralelo de altíssima vazão (centenas de GB/s) integrado com S3 para um workload HPC de processamento de vídeo. Qual variante de FSx é a indicada?',
  '[{"id":"A","text":"FSx for Windows File Server"},{"id":"B","text":"FSx for NetApp ONTAP"},{"id":"C","text":"FSx for OpenZFS"},{"id":"D","text":"FSx for Lustre com link a bucket S3"}]'::jsonb, 'D',
  '{
    "summary": "HPC paralelo + S3 = FSx for Lustre.",
    "whyCorrect": "FSx for Lustre é filesystem POSIX paralelo (Lustre) com vazão de até 1+ TB/s, latência sub-ms, projetado para HPC. Integração nativa com S3 (lazy load + write-back) — perfeito para datasets em S3 que precisam ser processados em paralelo.",
    "whyWrong": {
     "A": "Windows File Server é SMB para cargas Windows — não HPC paralelo.",
     "B": "NetApp ONTAP oferece NFS/SMB enterprise com snapshots, mas não é otimizado para HPC paralelo.",
     "C": "OpenZFS oferece NFS performante com snapshots, mas escala/integração-S3 não é o foco como em Lustre."
    },
    "keyConcept": "FSx variants — Lustre (HPC), Windows (SMB), ONTAP (enterprise multi-protocol), OpenZFS (NFS performante)",
    "compareWith": [
     "FSx Lustre vs ONTAP vs Windows vs OpenZFS"
    ],
    "realWorldContext": "Renderização de filmes, simulações financeiras, ML training de larga escala.",
    "commonMistakes": "Usar EFS para HPC paralelo extremo — EFS não chega às centenas de GB/s do Lustre.",
    "tutorSeeds": [
     "Como funciona o link S3 ↔ Lustre?",
     "Quando ONTAP é melhor que OpenZFS?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["fsx","lustre","hpc"]'::jsonb, 'ai-draft', 'active', now(), now()
)
