INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-037', 'aws-clf', 'Uma equipe SAP usa NetApp on-prem e quer migrar para AWS mantendo features enterprise (snapshots, clones, dedupe, replicação SnapMirror, multi-protocolo NFS/SMB/iSCSI). Qual variante FSx é o match?',
  '[{"id":"A","text":"FSx for NetApp ONTAP"},{"id":"B","text":"FSx for OpenZFS"},{"id":"C","text":"FSx for Lustre"},{"id":"D","text":"EFS Standard"}]'::jsonb, 'A',
  '{
    "summary": "Workload NetApp lift-and-shift = FSx for ONTAP (mesmo ONTAP, multi-protocolo, SnapMirror).",
    "whyCorrect": "FSx for NetApp ONTAP é literalmente o ONTAP da NetApp executado como serviço gerenciado AWS. Suporta NFS, SMB e iSCSI no mesmo filesystem, snapshots/FlexClone, deduplicação, compression, SnapMirror para on-prem. Migração lift-and-shift sem refactor.",
    "whyWrong": {
     "B": "OpenZFS é NFS-only com snapshots, mas sem SMB nativo nem SnapMirror.",
     "C": "Lustre é HPC, não enterprise multi-protocolo.",
     "D": "EFS é NFS-only, não tem features ONTAP."
    },
    "keyConcept": "FSx ONTAP — ONTAP gerenciado AWS com features completas",
    "compareWith": [
     "FSx ONTAP vs OpenZFS",
     "FSx ONTAP vs EFS para casos enterprise"
    ],
    "realWorldContext": "Migração de SAP/Oracle de NetApp on-prem mantendo workflow.",
    "commonMistakes": "Trocar NetApp por EFS — perde quase todas features que justificam NetApp.",
    "tutorSeeds": [
     "SnapMirror para hybrid cloud — como funciona?",
     "FSx ONTAP custo vs benefício vs EFS?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["fsx","netapp-ontap","enterprise"]'::jsonb, 'ai-draft', 'active', now(), now()
)
