INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-038', 'aws-clf', 'Sobre snapshots EBS, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"Snapshots são full sempre — cada snapshot copia o volume inteiro"},{"id":"B","text":"Snapshots são incrementais e armazenados em S3 (gerenciado), permitindo restore em qualquer AZ da mesma Region"},{"id":"C","text":"Snapshots só funcionam em volumes io2"},{"id":"D","text":"Snapshots são armazenados no próprio volume EBS"}]'::jsonb, 'B',
  '{
    "summary": "EBS snapshots são incrementais, no S3 (managed), e restauráveis em qualquer AZ da Region.",
    "whyCorrect": "Snapshots EBS são incrementais — primeiro é full, subsequentes só copiam blocos modificados. Armazenados em buckets S3 gerenciados pela AWS (não visíveis no seu console). Você pode restaurar para qualquer AZ na mesma Region (e copiar cross-Region para DR).",
    "whyWrong": {
     "A": "São incrementais, não full — isso permite snapshots frequentes baratos.",
     "C": "Funcionam para todos os tipos EBS (gp2/gp3/io1/io2/st1/sc1).",
     "D": "Não ficam no volume — ficam em storage S3 gerenciado."
    },
    "keyConcept": "EBS Snapshots — incremental, S3-backed, AZ-mobile",
    "compareWith": [
     "Snapshot vs AMI",
     "Snapshot incremental vs Glacier archive"
    ],
    "realWorldContext": "Backups noturnos automatizados via Data Lifecycle Manager, restore para outra AZ pós-falha.",
    "commonMistakes": "Deletar snapshot inicial sem entender que blocos derivados foram preservados — a AWS preserva blocos necessários automaticamente.",
    "tutorSeeds": [
     "Por que deletar um snapshot incremental não corrompe os outros?",
     "EBS Snapshot Archive — quando usar?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["ebs","snapshot","backup"]'::jsonb, 'ai-draft', 'active', now(), now()
)
