INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-039', 'aws-clf', 'Uma equipe usa S3 e configura Cross-Region Replication (CRR). Após criar a regra, objetos antigos não estão sendo replicados. Qual é a causa?',
  '[{"id":"A","text":"CRR não suporta replicação de objetos antigos em nenhuma circunstância"},{"id":"B","text":"É necessário ativar versionamento no bucket DESTINO apenas"},{"id":"C","text":"CRR só replica objetos criados/modificados APÓS a habilitação; existentes precisam de S3 Batch Replication"},{"id":"D","text":"CRR replica automaticamente todos os objetos imediatamente"}]'::jsonb, 'C',
  '{
    "summary": "CRR só pega objetos novos; existentes exigem S3 Batch Replication.",
    "whyCorrect": "S3 Replication (CRR/SRR) replica apenas objetos criados ou modificados APÓS a habilitação da regra. Para replicar objetos pré-existentes, use S3 Batch Replication (jobs em massa que aplicam regras a objetos antigos).",
    "whyWrong": {
     "A": "Existe solução — Batch Replication.",
     "B": "Versionamento deve estar habilitado em AMBOS os buckets (origem e destino), não só destino.",
     "D": "Replicação é assíncrona e só para objetos novos."
    },
    "keyConcept": "S3 Replication — escopo (novos) + S3 Batch Replication (existentes)",
    "compareWith": [
     "CRR vs SRR",
     "Live replication vs Batch replication"
    ],
    "realWorldContext": "Migração entre regions, DR cross-region, compliance de localização de dados.",
    "commonMistakes": "Habilitar CRR e achar que bucket existente fica sincronizado — não fica até rodar Batch.",
    "tutorSeeds": [
     "Custo de S3 Batch Replication?",
     "RTC (Replication Time Control) — quando usar?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'troubleshoot', '["s3","crr","replication"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
