INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-040', 'aws-clf', 'Uma equipe quer expor um bucket S3 ao on-prem como filesystem NFS, fazendo cache local e write-back para S3. Qual variante de Storage Gateway é a correta?',
  '[{"id":"A","text":"Volume Gateway (Cached mode)"},{"id":"B","text":"Tape Gateway"},{"id":"C","text":"FSx File Gateway"},{"id":"D","text":"File Gateway (Amazon S3 File Gateway)"}]'::jsonb, 'D',
  '{
    "summary": "NFS/SMB on-prem + S3 backend = S3 File Gateway.",
    "whyCorrect": "S3 File Gateway expõe NFS v3/v4.1 e SMB ao on-prem, armazena arquivos como objetos S3 (1 arquivo = 1 objeto), com cache local de blocos frequentes. Write-back assíncrono para S3.",
    "whyWrong": {
     "A": "Volume Gateway expõe iSCSI block storage (não NFS) — usa snapshots EBS no backend.",
     "B": "Tape Gateway emula library VTL para software de backup legado — não NFS.",
     "C": "FSx File Gateway é para FSx Windows on-prem, não para S3."
    },
    "keyConcept": "Storage Gateway variants — S3 File, Volume (cached/stored), Tape, FSx File",
    "compareWith": [
     "S3 File Gateway vs Volume Gateway",
     "Tape Gateway vs Snowball Tape"
    ],
    "realWorldContext": "Apps legados on-prem que esperam NFS mas a empresa quer cloud storage atrás.",
    "commonMistakes": "Achar que Volume Gateway é NFS — é iSCSI block.",
    "tutorSeeds": [
     "Diferença Volume Gateway cached vs stored mode?",
     "S3 File Gateway escreve objetos retroativamente?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["storage-gateway","s3-file-gateway","hybrid"]'::jsonb, 'ai-draft', 'active', now(), now()
)
