INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-041', 'aws-clf', 'Uma startup precisa de banco relacional gerenciado para uma API com tráfego imprevisível (de 5 conexões/min de noite a 500 conexões/seg em picos diários). Quer pagar proporcional ao uso e ter Postgres-compatible. Qual escolha minimiza custo e ops?',
  '[{"id":"A","text":"Aurora PostgreSQL Serverless v2"},{"id":"B","text":"RDS PostgreSQL Single-AZ db.t3.micro"},{"id":"C","text":"RDS PostgreSQL Multi-AZ db.r6g.xlarge fixo"},{"id":"D","text":"EC2 com PostgreSQL self-managed"}]'::jsonb, 'A',
  '{
    "summary": "Tráfego imprevisível + Postgres + escala automática = Aurora Serverless v2.",
    "whyCorrect": "Aurora Serverless v2 escala granularmente em incrementos de 0.5 ACU (Aurora Capacity Units), respondendo a carga em segundos. Para padrões de 5 conn/min a 500/s, ajusta capacidade dinamicamente. Suporta Postgres-compatible. Você paga por ACU-hora consumida.",
    "whyWrong": {
     "B": "RDS t3.micro tem capacidade fixa e baixa — vai falhar nos picos. Sem escala automática.",
     "C": "RDS Multi-AZ r6g.xlarge custa fixo (~$400+/mês) mesmo no vale noturno — desperdício.",
     "D": "Self-managed exige ops 24/7, patching, backup, failover manual."
    },
    "keyConcept": "Aurora Serverless v2 — auto-scaling fino em ACUs",
    "compareWith": [
     "Aurora Serverless v1 vs v2",
     "Aurora Serverless v2 vs RDS provisionado"
    ],
    "realWorldContext": "SaaS multitenant com workload variável, ambientes dev/test que escalam para zero.",
    "commonMistakes": "Confundir v1 (pausável, scale lento) com v2 (sub-segundo scale, sem pause completo).",
    "tutorSeeds": [
     "Como ACU mapeia para CPU/RAM?",
     "Aurora Serverless v2 scale-to-zero existe?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["aurora","serverless-v2","postgres","rds"]'::jsonb, 'ai-draft', 'active', now(), now()
)
