INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-042', 'aws-clf', 'Uma equipe migra um sistema com 80% de leituras e 20% de escritas, baseado em PostgreSQL. Quer escalar leituras horizontalmente sem mudar a aplicação. Qual recurso é o canônico?',
  '[{"id":"A","text":"Multi-AZ deployment com failover automático"},{"id":"B","text":"RDS Read Replicas (até 15 em RDS Postgres, até 15 em Aurora) com endpoint de leitura"},{"id":"C","text":"Sharding manual via app"},{"id":"D","text":"DynamoDB Global Tables"}]'::jsonb, 'B',
  '{
    "summary": "Escala horizontal de leituras = Read Replicas com reader endpoint.",
    "whyCorrect": "Read Replicas replicam assincronamente do primary e servem queries de leitura. Aurora oferece reader endpoint que load-balanceia entre réplicas automaticamente. App usa endpoints separados (writer vs reader) — não precisa lógica de sharding.",
    "whyWrong": {
     "A": "Multi-AZ standby NÃO atende leituras — é apenas para failover. O standby é passivo.",
     "C": "Sharding é complexo e demanda mudança grande de código.",
     "D": "DynamoDB é NoSQL — mudaria o modelo da aplicação Postgres."
    },
    "keyConcept": "Read Replicas vs Multi-AZ — leitura vs HA",
    "compareWith": [
     "Read Replica vs Multi-AZ",
     "Aurora reader endpoint vs RDS read replica endpoints"
    ],
    "realWorldContext": "Apps com painel de relatórios pesados, BI queries que não devem competir com OLTP.",
    "commonMistakes": "Achar que Multi-AZ standby aceita queries de leitura — RDS Multi-AZ tradicional não; Multi-AZ Cluster Deployment (3 instâncias) sim.",
    "tutorSeeds": [
     "RDS Multi-AZ Cluster Deployment — diferenças?",
     "Lag de replicação — como monitorar?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["rds","read-replica","scaling"]'::jsonb, 'ai-draft', 'active', now(), now()
)
