INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-043', 'aws-clf', 'Sobre Aurora vs RDS (MySQL/PostgreSQL), qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"Aurora e RDS são tecnologicamente idênticos; só nome diferente"},{"id":"B","text":"Aurora NÃO suporta read replicas"},{"id":"C","text":"Aurora desacopla compute de storage; storage é shared (cluster volume) de 6 cópias em 3 AZs, com auto-grow até 128 TB"},{"id":"D","text":"Aurora roda em qualquer engine relacional (Oracle, SQL Server, Db2, etc.)"}]'::jsonb, 'C',
  '{
    "summary": "Aurora = storage distribuído (6 cópias / 3 AZs) compartilhado entre instâncias, auto-grow até 128 TB.",
    "whyCorrect": "Aurora reescreveu a camada de storage do MySQL/Postgres como um cluster volume distribuído — 6 cópias em 3 AZs, write quorum 4/6, read quorum 3/6. Storage cresce automaticamente em incrementos de 10 GB até 128 TB. Replicas leem do MESMO storage (sem replicação física como no RDS), reduzindo lag para milissegundos.",
    "whyWrong": {
     "A": "Aurora é arquitetura nova — não é só rebranding.",
     "B": "Aurora SUPORTA até 15 read replicas com lag típico ~10ms.",
     "D": "Aurora suporta apenas MySQL-compatible e PostgreSQL-compatible. Oracle/SQL Server estão em RDS."
    },
    "keyConcept": "Aurora — cluster volume distribuído + reader replicas sem replicação física",
    "compareWith": [
     "Aurora vs RDS MySQL/Postgres",
     "Aurora storage vs EBS-backed RDS"
    ],
    "realWorldContext": "Apps com requisitos de baixo lag entre primary e read replicas, escala storage automática.",
    "commonMistakes": "Achar que Aurora roda Oracle — só MySQL e Postgres compatible.",
    "tutorSeeds": [
     "Por que Aurora tem read replica lag tão baixo?",
     "Custo Aurora vs RDS — quando compensa?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["aurora","storage","architecture"]'::jsonb, 'ai-draft', 'active', now(), now()
)
