INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-044', 'aws-clf', 'Uma equipe DynamoDB tem padrão de carga previsível (1.000 read/s e 500 write/s constantes 24/7). Quer minimizar custo. Qual capacity mode escolher?',
  '[{"id":"A","text":"Provisioned Capacity (com Auto Scaling habilitado opcionalmente)"},{"id":"B","text":"On-Demand"},{"id":"C","text":"Reserved Capacity (RCU/WCU 1 ano)"},{"id":"D","text":"A + C — Provisioned com Reserved Capacity comprado"}]'::jsonb, 'D',
  '{
    "summary": "Carga previsível 24/7 = Provisioned + Reserved Capacity para máximo desconto.",
    "whyCorrect": "Provisioned Capacity é mais barato que On-Demand para cargas previsíveis. Reserved Capacity adiciona até 76% de desconto sobre Provisioned com commit 1 ou 3 anos. Combinação dá menor TCO.",
    "whyWrong": {
     "A": "Sozinho é bom, mas combinar com RC é estritamente melhor para 24/7 previsível.",
     "B": "On-Demand é ~5-7x mais caro que Provisioned em utilização alta constante.",
     "C": "Reserved Capacity é uma camada de desconto sobre Provisioned — não substitui."
    },
    "keyConcept": "DynamoDB capacity modes — Provisioned, On-Demand, Reserved Capacity",
    "compareWith": [
     "Provisioned vs On-Demand DynamoDB",
     "Reserved Capacity ROI calc"
    ],
    "realWorldContext": "Catálogos de e-commerce com tráfego estável, IoT com taxa constante de ingestão.",
    "commonMistakes": "Usar On-Demand ''por simplicidade'' em carga estável — desperdício enorme.",
    "tutorSeeds": [
     "Quando On-Demand vence Provisioned + RC?",
     "DynamoDB Auto Scaling — como funciona?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["dynamodb","capacity","reserved"]'::jsonb, 'ai-draft', 'active', now(), now()
)
