INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-045', 'aws-clf', 'Sobre DynamoDB Streams + Lambda triggers, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"Streams capturam mudanças (INSERT/MODIFY/REMOVE) por 24h; Lambda pode consumir como event source para reagir a alterações"},{"id":"B","text":"Streams armazenam mudanças por 30 dias por padrão"},{"id":"C","text":"Lambda não pode ser invocado por DynamoDB Streams; só por Kinesis"},{"id":"D","text":"Streams capturam apenas DELETEs"}]'::jsonb, 'A',
  '{
    "summary": "DynamoDB Streams = log de mudanças (24h) consumível por Lambda.",
    "whyCorrect": "DynamoDB Streams capturam INSERT/MODIFY/REMOVE em ordem por partition key, retidas por 24h. Lambda pode ser configurado como event source — recebe batches de records e processa (ex: replicar para Elasticsearch, invalidar cache, audit log).",
    "whyWrong": {
     "B": "Retenção é 24h fixo, não 30 dias.",
     "C": "Lambda integra nativamente com DynamoDB Streams há anos.",
     "D": "Captura todos os tipos: INSERT, MODIFY, REMOVE."
    },
    "keyConcept": "DynamoDB Streams — CDC com retenção 24h + Lambda trigger",
    "compareWith": [
     "DynamoDB Streams vs Kinesis Data Streams for DynamoDB",
     "Lambda trigger por DDB Streams vs por EventBridge Pipes"
    ],
    "realWorldContext": "Replicação de dados para search engine, audit trail, cache invalidation.",
    "commonMistakes": "Esperar retenção longa — para >24h, integre com Kinesis Data Streams for DynamoDB (365 dias).",
    "tutorSeeds": [
     "DynamoDB Streams vs Kinesis Data Streams for DynamoDB?",
     "Como garantir ordem global?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["dynamodb","streams","lambda"]'::jsonb, 'ai-draft', 'active', now(), now()
)
