INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-046', 'aws-clf', 'Uma empresa precisa de data warehouse para 200 TB de dados estruturados, com queries complexas (joins, agregações) sobre SQL ANSI, e materializar dashboards de BI sub-segundo. Qual serviço é o canônico?',
  '[{"id":"A","text":"Amazon Athena sobre dados em Parquet em S3"},{"id":"B","text":"Amazon Redshift (com RA3 nodes ou Serverless)"},{"id":"C","text":"Amazon RDS PostgreSQL db.r6g.16xlarge"},{"id":"D","text":"Amazon DynamoDB com GSIs"}]'::jsonb, 'B',
  '{
    "summary": "DW columnar com queries complexas e dashboards sub-segundo = Redshift.",
    "whyCorrect": "Redshift é OLAP columnar MPP otimizado para queries analíticas complexas em escala TB-PB. RA3 desacopla compute de storage; Serverless escala sob demanda. Suporta materialized views, result caching — perfeito para dashboards de BI.",
    "whyWrong": {
     "A": "Athena é serverless query-on-S3, ótimo para ad-hoc, mas para dashboards repetitivos e sub-segundo, Redshift é mais rápido e previsível.",
     "C": "RDS é OLTP transacional — sofre em queries OLAP de TB.",
     "D": "DynamoDB é NoSQL key-value, sem joins/agregações complexas."
    },
    "keyConcept": "Redshift (DW columnar MPP) vs Athena (serverless S3 SQL) vs RDS (OLTP)",
    "compareWith": [
     "Redshift vs Athena",
     "Redshift RA3 vs DC2 vs Serverless"
    ],
    "realWorldContext": "BI corporativo, ETL para dashboards executivos, agregações financeiras.",
    "commonMistakes": "Tentar usar RDS para warehouse — quebra em queries de TB.",
    "tutorSeeds": [
     "Quando Athena vence Redshift?",
     "Redshift Serverless — quando vale a pena?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["redshift","data-warehouse","analytics"]'::jsonb, 'ai-draft', 'active', now(), now()
)
