INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-047', 'aws-clf', 'Uma equipe precisa de cache in-memory com suporte a estruturas avançadas (Sets, Sorted Sets, Streams), persistência opcional e replicação multi-node com failover automático. Qual ElastiCache engine?',
  '[{"id":"A","text":"ElastiCache for Memcached"},{"id":"B","text":"DynamoDB Accelerator (DAX)"},{"id":"C","text":"ElastiCache for Redis (com Multi-AZ replication group)"},{"id":"D","text":"RDS com cache plugin"}]'::jsonb, 'C',
  '{
    "summary": "Estruturas ricas + persistência + failover = ElastiCache for Redis.",
    "whyCorrect": "Redis suporta Strings, Lists, Sets, Sorted Sets, Hashes, Streams, Geospatial, HyperLogLog. Multi-AZ com replicação e failover automático. Persistência opcional (RDB/AOF) ou snapshots. Pub/Sub e Lua scripting nativos.",
    "whyWrong": {
     "A": "Memcached é apenas key-value strings, sem replicação nativa, sem persistência. Mais simples e multi-thread, mas sem features avançadas.",
     "B": "DAX é cache específico para DynamoDB (API DDB), não geral.",
     "D": "RDS não é cache in-memory — é DB relacional."
    },
    "keyConcept": "ElastiCache Redis vs Memcached — features vs simplicidade",
    "compareWith": [
     "Redis (features) vs Memcached (simples, multi-thread)"
    ],
    "realWorldContext": "Session store com TTL, leaderboards (Sorted Sets), rate limiting (Streams), pub/sub real-time.",
    "commonMistakes": "Escolher Memcached por ''ser mais leve'' e depois precisar de features Redis — migrar dá dor.",
    "tutorSeeds": [
     "Por que Memcached é multi-thread e Redis single-thread (até v6)?",
     "Redis cluster mode vs replication group?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["elasticache","redis","memcached"]'::jsonb, 'ai-draft', 'active', now(), now()
)
