INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-048', 'aws-clf', 'Sobre o modelo de leitura do DynamoDB, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"Reads são sempre strongly consistent"},{"id":"B","text":"Não há diferença de custo entre eventually e strongly consistent"},{"id":"C","text":"Strongly consistent reads são gratuitos"},{"id":"D","text":"Reads são eventually consistent por default (1 RCU = 2 reads de até 4 KB); strongly consistent reads custam o dobro (1 RCU = 1 read de 4 KB)"}]'::jsonb, 'D',
  '{
    "summary": "DDB: eventually 2 reads/RCU (default), strongly 1 read/RCU (2x mais caro), transactional 2x ainda.",
    "whyCorrect": "DynamoDB default é eventually consistent: 1 RCU = 2 reads de até 4 KB. Strongly consistent: 1 RCU = 1 read de até 4 KB (2x). Transactional reads: 1 RCU = 0.5 read de até 4 KB (4x). Escolha consciente entre custo/garantia.",
    "whyWrong": {
     "A": "Default é eventually; strongly é opt-in por chamada.",
     "B": "Há diferença explícita: 2x para strongly.",
     "C": "Não são gratuitos — custam o dobro de RCU."
    },
    "keyConcept": "DDB RCU — eventually (2/RCU) vs strongly (1/RCU) vs transactional (0.5/RCU)",
    "compareWith": [
     "Eventually vs Strongly consistent reads",
     "Read vs Write capacity units"
    ],
    "realWorldContext": "Apps OLTP escolhem strongly para read-after-write críticos (ex: saldo bancário) e eventually para leituras tolerantes a stale (timeline social).",
    "commonMistakes": "Usar strongly em tudo — dobra o custo de RCU desnecessariamente.",
    "tutorSeeds": [
     "Quando strongly consistent é mandatório?",
     "Como mensurar RCU consumido por API?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'recall', '["dynamodb","consistency","rcu"]'::jsonb, 'ai-draft', 'active', now(), now()
)
