INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-049', 'aws-clf', 'Uma equipe quer migrar de Cassandra mantendo APIs e drivers CQL. Qual serviço AWS é compatível?',
  '[{"id":"A","text":"Amazon Keyspaces (for Apache Cassandra)"},{"id":"B","text":"DynamoDB"},{"id":"C","text":"Neptune"},{"id":"D","text":"DocumentDB"}]'::jsonb, 'A',
