INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-050', 'aws-clf', 'Uma equipe precisa de banco de séries temporais para métricas IoT (milhões de medições/seg, queries por intervalos de tempo). Qual serviço é o canônico?',
  '[{"id":"A","text":"DynamoDB com sort key timestamp"},{"id":"B","text":"Amazon Timestream"},{"id":"C","text":"RDS PostgreSQL com TimescaleDB extension"},{"id":"D","text":"Athena sobre Parquet"}]'::jsonb, 'B',
  '{
    "summary": "Time-series escala IoT = Amazon Timestream.",
    "whyCorrect": "Timestream é DB serverless purpose-built para time-series — separa storage em memory tier (queries quentes) e magnetic tier (históricos). Linguagem SQL com funções time-series nativas. Escala automaticamente para trilhões de eventos.",
    "whyWrong": {
     "A": "DynamoDB com sort key timestamp funciona em escala menor, mas sofre em queries de range largo e não tem funções time-series nativas.",
     "C": "RDS+TimescaleDB é possível mas exige gerenciar instância e não escala como Timestream.",
     "D": "Athena é batch query — não real-time ingestão de milhões/seg."
    },
    "keyConcept": "Time-series purpose-built — Timestream (vs DynamoDB workaround)",
    "compareWith": [
     "Timestream vs DynamoDB para séries temporais",
     "Timestream tiers (memory vs magnetic)"
    ],
    "realWorldContext": "IoT sensores industriais, métricas de aplicação, telemetria de veículos.",
    "commonMistakes": "Forçar DDB para time-series gigante — explode em RCU e custo.",
    "tutorSeeds": [
     "Como Timestream cobra (writes vs queries)?",
     "Quando InfluxDB self-managed vence Timestream?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["timestream","time-series","iot"]'::jsonb, 'ai-draft', 'active', now(), now()
)
