INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-051', 'aws-clf', 'Uma equipe RDS faz backup automatizado diário (retention 7 dias) e ocasionalmente cria snapshots manuais. Sobre lifecycle desses recursos, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"Ambos persistem indefinidamente após deletar a instância"},{"id":"B","text":"Ambos são deletados automaticamente quando a instância é deletada"},{"id":"C","text":"Backups automatizados são deletados se você deletar a instância RDS sem ''final snapshot''; snapshots manuais persistem até serem explicitamente deletados"},{"id":"D","text":"Snapshots manuais são deletados após 30 dias automaticamente"}]'::jsonb, 'C',
  '{
    "summary": "Automated backups morrem com a instância (a menos que faça final snapshot); manuais persistem.",
    "whyCorrect": "Ao deletar uma instância RDS, automated backups são deletados (a menos que você escolha ''create final snapshot'', que converte em manual). Snapshots manuais persistem até serem explicitamente deletados — útil para arquivamento longo.",
    "whyWrong": {
     "A": "Automated NÃO persistem por padrão após delete da instância.",
     "B": "Manuais persistem.",
     "D": "Não há expiration automática para snapshots manuais."
    },
    "keyConcept": "RDS automated backups vs manual snapshots — lifecycle",
    "compareWith": [
     "Automated backup vs Manual snapshot vs Final snapshot"
    ],
    "realWorldContext": "Compliance que exige retenção 7 anos — deve usar manual snapshots ou export para S3.",
    "commonMistakes": "Deletar instância sem final snapshot esperando que backups automatizados fiquem — não ficam.",
    "tutorSeeds": [
     "Como fazer cross-region snapshot manual?",
     "Export RDS snapshot para S3 — quando vale?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["rds","backup","snapshot"]'::jsonb, 'ai-draft', 'active', now(), now()
)
