INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-052', 'aws-clf', 'Uma equipe RDS Postgres sofre lock contention em transações longas. Qual recurso AWS ajuda a IDENTIFICAR queries problemáticas com waits e top consumers?',
  '[{"id":"A","text":"AWS Config rules para RDS"},{"id":"B","text":"CloudWatch Alarms padrão para CPU"},{"id":"C","text":"AWS Trusted Advisor"},{"id":"D","text":"Amazon RDS Performance Insights"}]'::jsonb, 'D',
  '{
    "summary": "Performance Insights mostra DB load por wait event, top SQL, top users.",
    "whyCorrect": "Performance Insights agrega DB load (Average Active Sessions) por dimensão (SQL, wait event, host, user). Para troubleshoot lock contention, é a ferramenta canônica — mostra exatamente quais queries esperam locks e por quanto tempo.",
    "whyWrong": {
     "A": "Config audita conformidade (ex: backup habilitado?) — não diagnóstico de query.",
     "B": "CPU alarm não revela locks em transações.",
     "C": "Trusted Advisor dá recomendações genéricas, não diagnóstico de DB."
    },
    "keyConcept": "RDS Performance Insights — DB-level APM",
    "compareWith": [
     "Performance Insights vs Enhanced Monitoring",
     "PI vs CloudWatch DB metrics"
    ],
    "realWorldContext": "DBA hunting deadlocks, queries lentas, top consumers.",
    "commonMistakes": "Confundir Enhanced Monitoring (métricas do SO da instância) com Performance Insights (DB-level waits/SQL).",
    "tutorSeeds": [
     "Diferença Performance Insights vs Enhanced Monitoring?",
     "Custo de PI extended retention?"
    ]
