INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-053', 'aws-clf', 'Uma empresa quer conectar 3 VPCs (cada uma em uma Region: us-east-1, sa-east-1, eu-west-1) com roteamento any-to-any. Qual é a solução mais escalável e simples?',
  '[{"id":"A","text":"Transit Gateway com peering inter-Region"},{"id":"B","text":"Full mesh de VPC Peering (3 conexões)"},{"id":"C","text":"Direct Connect entre regions"},{"id":"D","text":"Site-to-Site VPN em malha"}]'::jsonb, 'A',
  '{
    "summary": "TGW + inter-Region peering = hub-and-spoke escalável para multi-Region.",
    "whyCorrect": "Transit Gateway atua como hub regional. Para conectar VPCs em Regions distintas, usa-se TGW peering inter-Region (encryption-in-transit nativa). Escala muito além de 3 VPCs (até milhares). Gerencia rotas centralizadamente.",
    "whyWrong": {
     "B": "VPC Peering full mesh para 3 funciona, mas N(N-1)/2 conexões viram inviável após ~10 VPCs. Cada peering é gerenciado individualmente.",
     "C": "Direct Connect é para on-prem ↔ AWS, não VPC-to-VPC.",
     "D": "VPN em malha entre VPCs AWS é over-engineering — TGW resolve internamente."
    },
    "keyConcept": "VPC Peering vs Transit Gateway — escala e gerenciamento",
    "compareWith": [
     "VPC Peering vs TGW",
     "TGW inter-Region peering vs Cloud WAN"
    ],
    "realWorldContext": "Empresas com presença multi-Region precisando shared services entre Regions.",
    "commonMistakes": "Crescer em VPC Peering até a malha virar inviável — migrar tarde para TGW custa.",
    "tutorSeeds": [
     "Como TGW route tables funcionam?",
     "AWS Cloud WAN vs TGW?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["vpc","transit-gateway","multi-region"]'::jsonb, 'ai-draft', 'active', now(), now()
)
