INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-054', 'aws-clf', 'Uma equipe configura Direct Connect e precisa de virtual interface (VIF) que carregue tráfego para múltiplas VPCs via Transit Gateway. Qual tipo de VIF usar?',
  '[{"id":"A","text":"Private VIF (ligado a um único VGW de uma VPC)"},{"id":"B","text":"Transit VIF (associado ao Direct Connect Gateway, conectando ao TGW)"},{"id":"C","text":"Public VIF (acesso a serviços AWS públicos)"},{"id":"D","text":"Hosted VIF (sublease de outro AWS account)"}]'::jsonb, 'B',
  '{
    "summary": "DX → múltiplas VPCs via TGW = Transit VIF + Direct Connect Gateway.",
    "whyCorrect": "Transit VIF se conecta a Direct Connect Gateway, que por sua vez se associa a Transit Gateway. Um único DX consegue alcançar múltiplas VPCs (mesma ou diferentes Regions) através do TGW. Modelo escalável para múltiplas VPCs.",
    "whyWrong": {
     "A": "Private VIF se liga a um único VGW (Virtual Gateway de uma VPC) — para múltiplas VPCs via TGW não serve.",
     "C": "Public VIF acessa serviços AWS públicos (S3, DynamoDB) sobre DX — não VPC privada.",
     "D": "Hosted VIF é categoria de billing/ownership, não um tipo funcional."
    },
    "keyConcept": "Direct Connect VIFs — Private (1 VPC), Transit (TGW multi-VPC), Public (serviços públicos)",
    "compareWith": [
     "Private VIF vs Transit VIF",
     "DX Gateway vs VGW"
    ],
    "realWorldContext": "Empresa com DX 10 Gbps querendo alcançar 20 VPCs sem 20 VIFs.",
    "commonMistakes": "Tentar conectar TGW via Private VIF — não suportado; precisa de Transit VIF.",
    "tutorSeeds": [
     "DX Gateway — para que serve exatamente?",
     "MACsec em DX — quando usar?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["direct-connect","transit-vif","networking"]'::jsonb, 'ai-draft', 'active', now(), now()
)
