INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-055', 'aws-clf', 'Uma equipe quer rotear usuários para o endpoint mais saudável e mais próximo geograficamente, com failover automático para um endpoint backup. Qual combinação Route 53 atende?',
  '[{"id":"A","text":"Apenas Simple routing"},{"id":"B","text":"Multivalue answer routing"},{"id":"C","text":"Latency-based routing primário + Failover routing secundário usando health checks"},{"id":"D","text":"Weighted routing 50/50"}]'::jsonb, 'C',
  '{
    "summary": "Geo-proximidade + failover = Latency-based + Failover routing com health checks.",
    "whyCorrect": "Route 53 pode aninhar policies: registros principais com Latency-based (resolve para Region de menor RTT) e configurar Failover routing com Primary/Secondary + health checks. Quando primary fica unhealthy, Route 53 responde com secondary automaticamente.",
    "whyWrong": {
     "A": "Simple routing não suporta failover nem geo-proximidade.",
     "B": "Multivalue retorna até 8 IPs aleatórios com health check, mas sem latência geográfica nem primary/secondary.",
     "D": "Weighted 50/50 distribui aleatoriamente — não otimiza latência."
    },
    "keyConcept": "Route 53 routing policies — Simple, Weighted, Latency, Geolocation, Geoproximity, Failover, Multivalue, IP-based",
    "compareWith": [
     "Latency-based vs Geolocation routing",
     "Failover vs Multivalue"
    ],
    "realWorldContext": "DR cross-Region com active-passive, sites globais com região primária.",
    "commonMistakes": "Confundir Geolocation (por país do user) com Latency-based (por RTT real).",
    "tutorSeeds": [
     "Diferença Geolocation vs Geoproximity routing?",
     "Health check tipos no Route 53?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["route53","routing-policies","failover"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
