INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-056', 'aws-clf', 'Sobre Route 53 Geolocation vs Geoproximity routing, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"Geolocation e Geoproximity são sinônimos"},{"id":"B","text":"Geoproximity só funciona com servidores físicos on-prem"},{"id":"C","text":"Geolocation exige uso de Global Accelerator"},{"id":"D","text":"Geolocation roteia com base na localização DO USUÁRIO (country/continent); Geoproximity roteia com base na localização DOS RECURSOS, com bias ajustável"}]'::jsonb, 'D',
  '{
    "summary": "Geolocation = onde o user está; Geoproximity = onde o recurso está (+bias).",
    "whyCorrect": "Geolocation usa o IP do user para decidir o registro (ex: ''usuários da França → endpoint EU''). Geoproximity é diferente: você define a localização do RECURSO (Region AWS ou lat/long de DC on-prem) e o R53 roteia o user mais próximo, com bias ±99 que aumenta/reduz a ''área de influência'' de um endpoint.",
    "whyWrong": {
     "A": "São distintas em parâmetro de decisão.",
     "B": "Geoproximity funciona com Regions AWS e on-prem.",
     "C": "Não há dependência de Global Accelerator."
    },
    "keyConcept": "Geolocation (user-side) vs Geoproximity (resource-side + bias)",
    "compareWith": [
     "Geolocation vs Geoproximity vs Latency-based"
    ],
    "realWorldContext": "Compliance que exige rotear usuários de país X só para Region X (Geolocation); load balance entre DCs próximos com fine-tuning (Geoproximity).",
    "commonMistakes": "Esperar Geolocation responder por proximidade geográfica — não, ela responde por país/continente configurado.",
    "tutorSeeds": [
     "Geoproximity exige Route 53 Traffic Flow?",
     "Como o bias afeta o draw da região?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'recall', '["route53","geolocation","geoproximity"]'::jsonb, 'ai-draft', 'active', now(), now()
)
