INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-057', 'aws-clf', 'Uma equipe quer que EC2 em subnet privada acesse APIs públicas da AWS (S3, DynamoDB) SEM NAT Gateway, mantendo tráfego dentro do backbone AWS. Qual recurso usar?',
  '[{"id":"A","text":"VPC Gateway Endpoint para S3 e DynamoDB"},{"id":"B","text":"VPC Interface Endpoint (PrivateLink)"},{"id":"C","text":"Internet Gateway com route table privada"},{"id":"D","text":"NAT Gateway com VPC Peering"}]'::jsonb, 'A',
  '{
    "summary": "S3 e DynamoDB têm Gateway Endpoints (gratuitos) — sem NAT, sem cobrança de saída.",
    "whyCorrect": "VPC Gateway Endpoint funciona apenas para S3 e DynamoDB. É gratuito, evita NAT Gateway (economiza ~$33/mês + tráfego), e mantém tráfego no backbone AWS. Adiciona uma rota na route table apontando para o endpoint.",
    "whyWrong": {
     "B": "Interface Endpoint (PrivateLink) funciona para muitos serviços, mas para S3 e DDB o Gateway Endpoint é mais simples e gratuito. Interface Endpoint pra S3 existe mas tem custo.",
     "C": "IGW em route table privada não faz sentido — subnet privada é privada por definição.",
     "D": "NAT é exatamente o que queremos evitar. Peering não tem relação."
    },
    "keyConcept": "VPC endpoints — Gateway (S3, DDB grátis) vs Interface (PrivateLink, $$)",
    "compareWith": [
     "Gateway Endpoint vs Interface Endpoint",
     "VPC Endpoint vs NAT Gateway custo"
    ],
    "realWorldContext": "Workloads ETL em EC2 privadas lendo PB de S3 sem pagar NAT egress.",
    "commonMistakes": "Pagar NAT por tráfego S3 desnecessariamente — Gateway Endpoint é grátis.",
    "tutorSeeds": [
     "Quando S3 Interface Endpoint vence Gateway Endpoint?",
     "Como configurar endpoint policy?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["vpc","gateway-endpoint","s3"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
