INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-058', 'aws-clf', 'Uma empresa quer expor um serviço interno (rodando atrás de NLB) para CONSUMIDORES em OUTRA conta AWS, sem peering nem expor à internet. Qual recurso é o canônico?',
  '[{"id":"A","text":"VPC Peering entre as contas"},{"id":"B","text":"AWS PrivateLink — criar VPC Endpoint Service no provider, Interface Endpoint no consumer"},{"id":"C","text":"Direct Connect Gateway"},{"id":"D","text":"Internet Gateway com IP allowlist"}]'::jsonb, 'B',
  '{
    "summary": "Service-to-service cross-account sem peering = PrivateLink (Endpoint Service + Interface Endpoint).",
    "whyCorrect": "PrivateLink permite ao provider criar um VPC Endpoint Service em frente a um NLB, e consumers criam Interface Endpoints na própria VPC que tunelam para o serviço. Sem peering (escalável para milhares de consumers), sem internet, sem overlap de CIDR. Modelo SaaS dentro da AWS.",
    "whyWrong": {
     "A": "VPC Peering exige sem overlap de CIDR e cresce N×M para múltiplos consumers.",
     "C": "Direct Connect Gateway é para on-prem ↔ AWS, não AWS-to-AWS.",
     "D": "Expor à internet com IP allowlist é o oposto do desejado."
    },
    "keyConcept": "AWS PrivateLink — SaaS-style service sharing sem peering",
    "compareWith": [
     "PrivateLink vs VPC Peering",
     "Endpoint Service (provider) vs Interface Endpoint (consumer)"
    ],
    "realWorldContext": "Empresas SaaS oferecendo serviços a clientes na AWS sem expor à internet (Datadog, Snowflake, etc.).",
    "commonMistakes": "Usar VPC Peering quando há muitos consumers — vira inviável; PrivateLink escala melhor.",
    "tutorSeeds": [
     "PrivateLink vs Resource Access Manager?",
     "Custos de Interface Endpoint?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["privatelink","vpc","cross-account"]'::jsonb, 'ai-draft', 'active', now(), now()
)
