INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-059', 'aws-clf', 'Sobre VPC Flow Logs, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"Flow Logs capturam o conteúdo completo (payload) dos pacotes"},{"id":"B","text":"Flow Logs só funcionam em subnet pública"},{"id":"C","text":"Flow Logs capturam metadados de tráfego IP (não payload) e podem ser entregues a CloudWatch Logs, S3 ou Kinesis Data Firehose"},{"id":"D","text":"Flow Logs só capturam tráfego de saída (egress)"}]'::jsonb, 'C',
  '{
    "summary": "Flow Logs = metadata IP (não payload); destinos CWL/S3/KDF.",
    "whyCorrect": "VPC Flow Logs capturam metadados de fluxos IP: source/dest IP, ports, protocolo, bytes, packets, action (ACCEPT/REJECT), timestamp. NÃO capturam payload. Destinos: CloudWatch Logs, S3 (mais barato para grandes volumes) ou Kinesis Data Firehose. Granularidade: VPC, subnet ou ENI.",
    "whyWrong": {
     "A": "Payload completo exige Traffic Mirroring, não Flow Logs.",
     "B": "Funcionam em qualquer subnet (pública ou privada).",
     "D": "Capturam ingress, egress ou ambos (configurável)."
    },
    "keyConcept": "VPC Flow Logs vs Traffic Mirroring — metadata vs payload",
    "compareWith": [
     "Flow Logs vs Traffic Mirroring",
     "Destinos CWL vs S3 vs KDF"
    ],
    "realWorldContext": "Forensics de incidentes, troubleshooting de conectividade, baseline de tráfego para detecção de anomalias.",
    "commonMistakes": "Esperar inspeção de payload em Flow Logs — limitado a metadata; use Traffic Mirroring + Wireshark/Suricata.",
    "tutorSeeds": [
     "Custo CWL vs S3 para Flow Logs em produção?",
     "Custom format para Flow Logs?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["vpc","flow-logs","observability"]'::jsonb, 'ai-draft', 'active', now(), now()
)
