INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-060', 'aws-clf', 'Uma equipe precisa de IPs estáticos globais que façam health-check e anycast para frontends regionais (ALBs/NLBs em 3 Regions). Qual serviço atende?',
  '[{"id":"A","text":"Amazon CloudFront"},{"id":"B","text":"Route 53 com Failover policy"},{"id":"C","text":"NLB com Elastic IP"},{"id":"D","text":"AWS Global Accelerator"}]'::jsonb, 'D',
  '{
    "summary": "IP estático global + anycast + multi-Region failover = Global Accelerator.",
    "whyCorrect": "Global Accelerator provê 2 IPs anycast estáticos roteados ao endpoint regional mais próximo via backbone AWS. Health checks contínuos failover automático entre Regions. Útil para protocolos não-HTTP (gaming, IoT) ou quando precisa IP estático global.",
    "whyWrong": {
     "A": "CloudFront é CDN para HTTP/HTTPS — não dá IP estático nem suporta UDP.",
     "B": "Route 53 Failover usa DNS — clients podem cachear DNS e demorar a perceber failover; sem IP estático.",
     "C": "NLB+EIP é regional, não global; um IP por AZ na Region."
    },
    "keyConcept": "Global Accelerator — IP estático global + anycast routing AWS backbone",
    "compareWith": [
     "Global Accelerator vs CloudFront",
     "GA vs Route 53 latency routing"
    ],
    "realWorldContext": "Apps gaming UDP globais, IoT MQTT, sistemas legacy que exigem IP allowlist.",
    "commonMistakes": "Confundir GA (L4 + IPs estáticos) com CloudFront (L7 HTTP cache).",
    "tutorSeeds": [
     "Quando GA acelera HTTP além do CloudFront?",
     "GA custos vs benefícios?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["global-accelerator","anycast","multi-region"]'::jsonb, 'ai-draft', 'active', now(), now()
)
