INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-061', 'aws-clf', 'Sobre Security Groups (SG) em VPC, qual afirmação está CORRETA?',
  '[{"id":"A","text":"SGs são stateful — resposta de uma conexão permitida pelo inbound é automaticamente permitida no outbound (e vice-versa)"},{"id":"B","text":"SGs são stateless — você precisa permitir explicitamente inbound e outbound separadamente"},{"id":"C","text":"SGs suportam regras de DENY explícito"},{"id":"D","text":"SGs operam na borda da VPC, não em cada ENI"}]'::jsonb, 'A',
  '{
    "summary": "SG stateful: tracking de conexões automático; NACL stateless.",
    "whyCorrect": "Security Groups são stateful — se você permite inbound TCP 443, a resposta saindo é automaticamente permitida sem regra de outbound correspondente. NACLs (Network ACLs) são o oposto: stateless, exigem regras inbound e outbound separadas.",
    "whyWrong": {
     "B": "Stateless é NACL, não SG.",
     "C": "SG só suporta ALLOW (implicit deny); DENY explícito é NACL.",
     "D": "SGs operam em cada ENI (network interface) — granularidade fina."
    },
    "keyConcept": "Security Group (stateful, ALLOW only, per-ENI) vs NACL (stateless, ALLOW+DENY, per-subnet)",
    "compareWith": [
     "SG vs NACL"
    ],
    "realWorldContext": "Microsegmentação dentro da VPC, controlar tráfego entre tiers (web, app, db).",
    "commonMistakes": "Tentar criar ''regra DENY'' em SG — não existe; use NACL ou estruture SGs com referências.",
    "tutorSeeds": [
     "Quando NACL é necessário?",
     "Limite de regras por SG?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["vpc","security-group","stateful"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
