INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-062', 'aws-clf', 'Uma equipe usa NAT Gateway e o custo está explodindo. Investigação mostra que 80% do tráfego de saída é para S3. Qual ação reduz custo SEM perder funcionalidade?',
  '[{"id":"A","text":"Aumentar tamanho do NAT Gateway"},{"id":"B","text":"Criar VPC Gateway Endpoint para S3 e ajustar route tables"},{"id":"C","text":"Trocar NAT Gateway por NAT Instance EC2"},{"id":"D","text":"Mover EC2 para subnet pública"}]'::jsonb, 'B',
  '{
    "summary": "Gateway Endpoint para S3 é grátis e remove tráfego do NAT.",
    "whyCorrect": "VPC Gateway Endpoint para S3 não cobra por hora nem por dados processados. Adicionar à route table direciona tráfego S3 direto via backbone, eliminando o data processing fee do NAT Gateway (~$0.045/GB) — economia massiva quando há TB/mês de tráfego S3.",
    "whyWrong": {
     "A": "NAT GW não tem ''tamanho'' configurável (escala automática); aumentar não muda custo de data.",
     "C": "NAT Instance é gerenciado por você (overhead operacional) e não escala como NAT GW; potencialmente mais caro em escala.",
     "D": "Mover EC2 para subnet pública compromete segurança."
    },
    "keyConcept": "NAT Gateway data processing fee vs VPC Gateway Endpoint (grátis para S3/DDB)",
    "compareWith": [
     "NAT Gateway vs Gateway Endpoint vs Interface Endpoint custo"
    ],
    "realWorldContext": "Datalakes lendo PB/mês de S3 — economias de milhares de dólares com endpoints.",
    "commonMistakes": "Não auditar tráfego NAT periodicamente — alvos óbvios (S3, DDB, ECR, CloudWatch) economizam muito.",
    "tutorSeeds": [
     "Como auditar tráfego NAT por destino via Flow Logs?",
     "ECR pull via Interface Endpoint — vale?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'troubleshoot', '["vpc","nat-gateway","cost-optimization","endpoint"]'::jsonb, 'ai-draft', 'active', now(), now()
)
