INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-063', 'aws-clf', 'Uma equipe usa CloudFront na frente de um bucket S3 estático. Quer impedir que usuários acessem o S3 diretamente (bypass do CDN). Qual é o método RECOMENDADO atualmente?',
  '[{"id":"A","text":"Origin Access Identity (OAI) — método mais antigo e recomendado"},{"id":"B","text":"Bucket público com CloudFront em modo passthrough"},{"id":"C","text":"Origin Access Control (OAC) com bucket policy restringindo a CloudFront distribution"},{"id":"D","text":"IAM Role anexada à distribution"}]'::jsonb, 'C',
  '{
    "summary": "OAC é a versão moderna do OAI — suporta SSE-KMS e mais features.",
    "whyCorrect": "Origin Access Control (OAC) é a forma recomendada desde 2022. Suporta todos os Regions, SSE-KMS, dynamic requests e SigV4. Configura-se com bucket policy condicionando acesso a aws:SourceArn da distribution.",
    "whyWrong": {
     "A": "OAI é legado e ainda funciona, mas a AWS recomenda migrar para OAC. OAI não suporta SSE-KMS e algumas features novas.",
     "B": "Bucket público derrota o propósito de impedir bypass.",
     "D": "IAM Roles não se anexam a CloudFront distributions; o controle é via bucket policy."
    },
    "keyConcept": "CloudFront origin protection — OAC (atual) vs OAI (legado)",
    "compareWith": [
     "OAC vs OAI"
    ],
    "realWorldContext": "Sites estáticos protegidos, distribuição de assets pagos via signed URLs.",
    "commonMistakes": "Continuar criando novos setups com OAI por costume — use OAC para novos projetos.",
    "tutorSeeds": [
     "Como migrar OAI para OAC?",
     "OAC + SSE-KMS — quais permissões na key?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["cloudfront","oac","s3"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
