INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-064', 'aws-clf', 'Uma empresa precisa distribuir vídeos pagos via CloudFront, com URLs válidas apenas por 1 hora e somente para usuários autenticados. Qual recurso é o canônico?',
  '[{"id":"A","text":"Bucket S3 público com lifecycle de 1h"},{"id":"B","text":"API Gateway com Lambda authorizer"},{"id":"C","text":"CORS configurado para bloquear acesso direto"},{"id":"D","text":"Signed URLs ou Signed Cookies do CloudFront"}]'::jsonb, 'D',
  '{
    "summary": "URLs/cookies temporários autenticados no CDN = CloudFront Signed URLs/Cookies.",
    "whyCorrect": "CloudFront Signed URLs (1 arquivo) e Signed Cookies (múltiplos arquivos) permitem assinar requisições com chave privada da conta. O CDN verifica assinatura + policy (expiração, IP allowlist) e nega se inválida. Ideal para vídeo on-demand pago.",
    "whyWrong": {
     "A": "Bucket público + lifecycle não dá controle por usuário nem expiração por URL — só por arquivo.",
     "B": "API Gateway + Lambda authorizer não é o caminho para servir vídeo via CDN — adiciona latência e quebra o cache.",
     "C": "CORS é controle de origin no browser, não autenticação."
    },
    "keyConcept": "CloudFront Signed URLs/Cookies — distribuição privada via CDN",
    "compareWith": [
     "Signed URL vs Signed Cookie",
     "CloudFront SU vs S3 Presigned URL"
    ],
    "realWorldContext": "Netflix-like streaming, conteúdo educacional pago, downloads de software licenciado.",
    "commonMistakes": "Usar S3 presigned URL direto sem CDN — perde benefícios de cache e edge.",
    "tutorSeeds": [
     "Signed URL vs Signed Cookie — quando cada um?",
     "Como rotacionar key pair?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["cloudfront","signed-urls","drm"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
