INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-065', 'aws-clf', 'Uma equipe quer rodar lógica customizada no edge do CloudFront — modificar headers de request, fazer rewrite de URL — com latência mínima e sem invocar Lambda. Qual recurso?',
  '[{"id":"A","text":"CloudFront Functions"},{"id":"B","text":"Lambda@Edge"},{"id":"C","text":"AWS WAF managed rules"},{"id":"D","text":"CloudFront Field-Level Encryption"}]'::jsonb, 'A',
  '{
    "summary": "Edge logic leve (header rewrite, URL rewrite) com sub-ms = CloudFront Functions.",
    "whyCorrect": "CloudFront Functions executa JavaScript no edge (não em Region), latência sub-ms, limite de 1ms CPU + 2MB memória. Ideal para header manipulation, URL rewrites, A/B testing, redirects. Cobra ~$0.10/M invocações (10x mais barato que Lambda@Edge).",
    "whyWrong": {
     "B": "Lambda@Edge é mais poderoso (Node/Python, network calls, longer runtime) mas latência maior (dezenas de ms) e mais caro. Use quando precisar de mais que header manipulation.",
     "C": "WAF é firewall — não rewrite de URLs/headers.",
     "D": "Field-Level Encryption protege campos específicos POST — não rewrite."
    },
    "keyConcept": "Edge compute — CloudFront Functions (leve, sub-ms) vs Lambda@Edge (poderoso, ms)",
    "compareWith": [
     "CloudFront Functions vs Lambda@Edge"
    ],
    "realWorldContext": "Normalização de URL para cache hit ratio, geolocation redirects, A/B test seeding.",
    "commonMistakes": "Usar Lambda@Edge para header simples — overkill caro.",
    "tutorSeeds": [
     "Quais limitações de CloudFront Functions?",
     "Lambda@Edge — origin-request vs viewer-request?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["cloudfront","edge-compute","cloudfront-functions"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
