INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-066', 'aws-clf', 'Sobre Cache Policies e Origin Request Policies do CloudFront, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"São o mesmo recurso com nomes diferentes"},{"id":"B","text":"Cache Policy define o que entra na chave de cache (headers, query strings, cookies considerados); Origin Request Policy define o que é encaminhado à origem (sem afetar cache key)"},{"id":"C","text":"Cache Policy define ACLs de IP permitidos"},{"id":"D","text":"Origin Request Policy só funciona com Lambda@Edge"}]'::jsonb, 'B',
  '{
    "summary": "Cache Policy = chave de cache; Origin Request Policy = o que vai pro backend.",
    "whyCorrect": "Cache Policy determina cache key (TTLs, headers/query/cookies que compõem a chave) — afeta hit ratio. Origin Request Policy determina quais headers/query/cookies são repassados à origem mas SEM entrar na chave de cache. Útil para enviar info ao backend sem fragmentar cache.",
    "whyWrong": {
     "A": "São distintos com propósitos complementares.",
     "C": "ACL de IP é função do WAF/Geo Restrictions, não dessas policies.",
     "D": "Origin Request Policy funciona com qualquer origem, sem Lambda."
    },
    "keyConcept": "CloudFront — Cache Policy (cache key) vs Origin Request Policy (forwarding sem afetar key)",
    "compareWith": [
     "Cache Policy vs Origin Request Policy vs Response Headers Policy"
    ],
    "realWorldContext": "Enviar Authorization header ao backend sem fragmentar cache; cache compartilhado entre users autenticados.",
    "commonMistakes": "Incluir Authorization no Cache Policy — destrói cache (1 cache por user).",
    "tutorSeeds": [
     "Como debugar cache miss inesperado?",
     "Managed cache policies — quais existem?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'recall', '["cloudfront","cache-policy","origin-request-policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
