INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-068', 'aws-clf', 'Uma empresa quer multi-CDN para failover e quer servir conteúdo de POPs em todas as regiões geográficas, incluindo Brasil e África. Sobre a rede edge do CloudFront, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"CloudFront só atende América do Norte e Europa"},{"id":"B","text":"Para usar PoP no Brasil é preciso ativar feature paga ''Brazil Edge''"},{"id":"C","text":"CloudFront não tem cache regional — todos os requests vão à origem"},{"id":"D","text":"CloudFront opera 600+ edge locations e Regional Edge Caches em ~13 cidades; é por padrão global, sem opt-in"}]'::jsonb, 'D',
  '{
    "summary": "CloudFront tem 600+ edges + Regional Edge Caches; global por default.",
    "whyCorrect": "CloudFront possui 600+ edge locations globais e ~13 Regional Edge Caches que ficam entre edges e origem (reduzem carga na origem e melhoram hit ratio). É global por default — Brasil, África, Oriente Médio, todas regiões.",
    "whyWrong": {
     "A": "Cobertura é global.",
     "B": "Não há feature ''Brazil Edge'' paga.",
     "C": "Há Regional Edge Caches por design."
    },
    "keyConcept": "CloudFront topology — Edge Locations + Regional Edge Caches + Origin",
    "compareWith": [
     "Edge cache vs Regional edge cache",
     "CloudFront vs outros CDNs cobertura"
    ],
    "realWorldContext": "Sites com audiência global, downloads de software, vídeo streaming.",
    "commonMistakes": "Configurar Geo Restrictions errado e cortar países sem querer.",
    "tutorSeeds": [
     "Como Regional Edge Cache reduz carga na origem?",
     "Price classes do CloudFront?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["cloudfront","edge-locations","global"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
