INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-069', 'aws-clf', 'Uma equipe quer arquitetura pub/sub onde 1 mensagem dispara N processadores diferentes em paralelo: 1 grava em S3, outro envia email, outro insere no DynamoDB. Cada processador deve ter sua própria fila de retry/DLQ. Qual padrão é o canônico?',
  '[{"id":"A","text":"SNS topic com múltiplas SQS subscriptions (fanout) + Lambda por fila"},{"id":"B","text":"SQS direto chamando os 3 processadores em sequência"},{"id":"C","text":"Lambda chamando outras Lambdas via SDK"},{"id":"D","text":"Kinesis Data Streams com 1 consumer iterando"}]'::jsonb, 'A',
  '{
    "summary": "Padrão SNS→SQS fanout: 1 publish, N consumers desacoplados com suas próprias DLQs.",
    "whyCorrect": "SNS publica em N SQS subscriptions. Cada consumer (Lambda/ECS) lê de SUA fila com retry/DLQ independentes. Falha em um não afeta os outros. Desacoplamento total: adicionar/remover consumer = adicionar/remover subscription.",
    "whyWrong": {
     "B": "SQS direto não faz fanout 1-para-N nativamente.",
     "C": "Lambda chamando Lambda acopla, sem retry/DLQ por destino e sem isolamento de falha.",
     "D": "Kinesis com 1 consumer não dá retry isolado por tipo de processamento."
    },
    "keyConcept": "SNS-SQS fanout pattern — broadcast com desacoplamento e DLQ per consumer",
    "compareWith": [
     "SNS-SQS fanout vs EventBridge",
     "SNS direct to Lambda vs SNS-SQS-Lambda"
    ],
    "realWorldContext": "E-commerce: order placed → email + warehouse + analytics + inventory update.",
    "commonMistakes": "SNS direto para Lambda sem SQS — sem buffer, picos derrubam Lambda; sem DLQ por consumer.",
    "tutorSeeds": [
     "EventBridge fanout — quando supera SNS-SQS?",
     "FIFO fanout — limitações?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["sns","sqs","fanout","pub-sub"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
