INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-070', 'aws-clf', 'Uma equipe precisa rotear eventos baseando em CONTEÚDO (ex: ''só processar quando event.source = stripe E event.type = invoice.paid''), com mapping de schemas e archive opcional. Qual serviço é o adequado?',
  '[{"id":"A","text":"SNS topic com filter policies"},{"id":"B","text":"Amazon EventBridge (com event bus, rules baseadas em JSON pattern, schema registry)"},{"id":"C","text":"SQS com SQS-as-Filter"},{"id":"D","text":"AWS Glue Workflows"}]'::jsonb, 'B',
  '{
    "summary": "Content-based routing + schema registry + archive = EventBridge.",
    "whyCorrect": "EventBridge oferece rules com JSON pattern matching sofisticado (igualdade, prefix, anything-but, numeric ranges), schema registry com discovery e archives para replay. Suporta integração nativa com 100+ SaaS partners (Stripe, Datadog, etc.) e eventos AWS.",
    "whyWrong": {
     "A": "SNS filter policies são mais limitadas (apenas message attributes, sem deep JSON matching) e sem schema registry/archive.",
     "C": "SQS não tem feature de filtering por conteúdo na ingestão.",
     "D": "Glue Workflows é para ETL pipelines, não event routing."
    },
    "keyConcept": "EventBridge — event router com pattern matching, schemas e archive",
    "compareWith": [
     "EventBridge vs SNS — quando cada um",
     "EventBridge Pipes vs Rules"
    ],
    "realWorldContext": "Integração com SaaS partners (Stripe webhooks), arquitetura event-driven multi-conta.",
    "commonMistakes": "Confundir SNS (broadcast simples) com EventBridge (routing inteligente).",
    "tutorSeeds": [
     "EventBridge Pipes — para que serve?",
     "Schema discovery — como ativar?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["eventbridge","event-routing","integration"]'::jsonb, 'ai-draft', 'active', now(), now()
)
