INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-071', 'aws-clf', 'Uma equipe escolhe entre AWS Step Functions Standard e Express workflows. Têm um workflow de 8 horas com human approval no meio e outro de 30 segundos invocado 50k vezes/min para validação rápida. Qual escolha é a correta?',
  '[{"id":"A","text":"Express para ambos — sempre é mais barato"},{"id":"B","text":"Standard para ambos — Express não suporta Lambda"},{"id":"C","text":"Standard para o workflow de 8h (até 1 ano, exactly-once, com human task); Express para o workflow rápido (alta vazão, at-least-once)"},{"id":"D","text":"Step Functions não suporta workflows de horas"}]'::jsonb, 'C',
  '{
    "summary": "Standard = longo, exactly-once, human tasks. Express = curto, alta vazão, at-least-once.",
    "whyCorrect": "Standard suporta até 1 ano de duração, exactly-once execution, history visível, integração com human approval (callback pattern). Express dura até 5 min, sync ou async, otimizado para alta vazão e baixo custo per-execution, at-least-once. Match perfeito para os dois casos.",
    "whyWrong": {
     "A": "Express é mais barato POR EXECUTION mas tem limite de 5 min e não tem exactly-once — não serve para 8h com approval.",
     "B": "Express suporta Lambda perfeitamente.",
     "D": "Standard suporta até 1 ano."
    },
    "keyConcept": "Step Functions — Standard (durabilidade, exactly-once) vs Express (vazão, at-least-once)",
    "compareWith": [
     "Standard vs Express workflow types"
    ],
    "realWorldContext": "Order fulfillment com human approval (Standard); IoT event processing (Express).",
    "commonMistakes": "Usar Standard para tudo — custo explode em workflows curtos de alto volume.",
    "tutorSeeds": [
     "Como combinar Standard chamando nested Express?",
     "Custos comparados em escala?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["step-functions","standard","express"]'::jsonb, 'ai-draft', 'active', now(), now()
)
