INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-072', 'aws-clf', 'Uma equipe quer mensagens com ORDEM garantida por chave de grupo, sem duplicação dentro de 5 minutos, e ainda assim alto throughput. Qual SQS é adequado?',
  '[{"id":"A","text":"SQS Standard com FIFO emulado em código"},{"id":"B","text":"Kinesis Data Streams sempre"},{"id":"C","text":"SNS FIFO sem SQS"},{"id":"D","text":"SQS FIFO com high throughput mode habilitado e MessageGroupId"}]'::jsonb, 'D',
  '{
    "summary": "Ordem por chave + dedupe + alto throughput = SQS FIFO + high throughput mode + MessageGroupId.",
    "whyCorrect": "SQS FIFO garante ordem dentro de um MessageGroupId e dedupe via MessageDeduplicationId (janela 5 min). High Throughput Mode (per-message-group-id ou per-queue) eleva limite de 300 msg/s para até 70.000 msg/s.",
    "whyWrong": {
     "A": "Emular FIFO em Standard é complexo, propenso a erros e não escala bem.",
     "B": "Kinesis é alternativa mas com modelo diferente (streams, partitions, shards) — não é resposta direta à pergunta SQS.",
     "C": "SNS FIFO sem SQS não suporta fanout pesado nem é um destino persistente para processamento."
    },
    "keyConcept": "SQS FIFO — ordem por MessageGroupId, dedupe por MessageDeduplicationId, high throughput mode",
    "compareWith": [
     "SQS Standard vs FIFO",
     "FIFO regular vs High Throughput mode"
    ],
    "realWorldContext": "Processamento de pedidos por cliente em ordem, eventos de account em sequência.",
    "commonMistakes": "Não habilitar high throughput mode e bater no limite de 300 msg/s.",
    "tutorSeeds": [
     "MessageGroupId estratégias?",
     "FIFO dedupe vs idempotência da aplicação?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["sqs","fifo","high-throughput"]'::jsonb, 'ai-draft', 'active', now(), now()
)
