INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-074', 'aws-clf', 'Sobre AppSync (GraphQL gerenciado), qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"AppSync só suporta REST, não GraphQL"},{"id":"B","text":"AppSync suporta queries, mutations e subscriptions (real-time via WebSocket); resolvers podem ir a DynamoDB, Lambda, RDS, HTTP, OpenSearch — usando VTL ou JavaScript"},{"id":"C","text":"AppSync exige rodar servidor GraphQL em EC2"},{"id":"D","text":"AppSync subscriptions são via polling HTTP"}]'::jsonb, 'B',
  '{
    "summary": "AppSync = GraphQL gerenciado com subscriptions real-time e resolvers para múltiplos data sources.",
    "whyCorrect": "AppSync expõe schema GraphQL gerenciado. Resolvers (em VTL ou JavaScript) mapeiam fields a DynamoDB, Lambda, RDS via RDS Data API, HTTP, OpenSearch. Subscriptions usam WebSocket gerenciado para push real-time. Authorization múltipla: IAM, Cognito User Pools, OIDC, API key, Lambda.",
    "whyWrong": {
     "A": "AppSync é GraphQL, não REST.",
     "C": "É serverless — sem EC2.",
     "D": "Subscriptions são WebSocket nativo, não polling."
    },
    "keyConcept": "AppSync — GraphQL managed com real-time subscriptions",
    "compareWith": [
     "AppSync vs API Gateway REST",
     "AppSync vs ECS hosting GraphQL server"
    ],
    "realWorldContext": "Apps mobile com sync offline (DataStore), dashboards real-time, e-commerce com live inventory.",
    "commonMistakes": "Tentar replicar GraphQL em REST API quando AppSync já oferece nativo.",
    "tutorSeeds": [
     "AppSync caching — como funciona?",
     "Pipeline resolvers — para que servem?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["appsync","graphql","real-time"]'::jsonb, 'ai-draft', 'active', now(), now()
)
