INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-076', 'aws-clf', 'Uma empresa analytics precisa decidir entre Athena, Redshift e EMR para um data lake S3 de 50 TB. Querem queries SQL ad-hoc esporádicas, sem dashboards constantes nem ETL pesado contínuo. Qual escolha minimiza ops e custo?',
  '[{"id":"A","text":"Redshift Provisioned cluster ra3.xlplus 24/7"},{"id":"B","text":"EMR cluster Spark sempre rodando"},{"id":"C","text":"RDS PostgreSQL com import S3"},{"id":"D","text":"Athena — serverless, paga por query (TB scaneado), sem cluster para gerenciar"}]'::jsonb, 'D',
  '{
    "summary": "Queries ad-hoc esporádicas em S3 = Athena (serverless, pay-per-scan).",
    "whyCorrect": "Athena é serverless query engine (Presto/Trino) sobre S3. Cobra $5 por TB escaneado. Para uso esporádico, custo é mínimo (sem cluster idle). Com Parquet + particionamento, scans podem cair 90%+. Zero ops.",
    "whyWrong": {
     "A": "Redshift 24/7 paga cluster mesmo idle — mais caro para uso esporádico.",
     "B": "EMR cluster idle é desperdício; ferramentas Spark/Hadoop são overkill para SQL ad-hoc.",
     "C": "RDS não é OLAP — não escala para 50 TB de queries analíticas."
    },
    "keyConcept": "Athena vs Redshift vs EMR — pay-per-query vs cluster contínuo",
    "compareWith": [
     "Athena vs Redshift Serverless",
     "Athena vs EMR (Spark/Presto)"
    ],
    "realWorldContext": "Data exploratory analysis, BI queries esporádicas, troubleshooting de logs.",
    "commonMistakes": "Não usar particionamento + colunar (Parquet) — query scaneia tudo e custo explode.",
    "tutorSeeds": [
     "Athena workgroups e cost controls?",
     "Quando Redshift Serverless vence Athena?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["athena","analytics","data-lake"]'::jsonb, 'ai-draft', 'active', now(), now()
)
