INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-077', 'aws-clf', 'Sobre Amazon SageMaker (plataforma ML completa), qual afirmação é VERDADEIRA no nível CLF?',
  '[{"id":"A","text":"SageMaker oferece um ecossistema completo: notebooks (Studio), training jobs, hyperparameter tuning, model registry, real-time/batch inference endpoints, ground truth labeling — gerenciados sem provisionar EC2 manualmente"},{"id":"B","text":"SageMaker apenas hospeda modelos pré-treinados de fornecedores terceiros"},{"id":"C","text":"SageMaker é exclusivamente para inferência, não treinamento"},{"id":"D","text":"SageMaker não suporta GPUs"}]'::jsonb, 'A',
  '{
    "summary": "SageMaker é plataforma ML end-to-end gerenciada — notebooks, training, tuning, deployment, registry.",
    "whyCorrect": "SageMaker cobre todo o ciclo ML: Studio (notebooks), Training Jobs (spot, distribuído), HPO, Model Registry, Endpoints (real-time multi-model, async, serverless, batch transform), Ground Truth (labeling), Pipelines (MLOps), Feature Store, Clarify, Model Monitor.",
    "whyWrong": {
     "B": "Faz muito além de hostar — treina, tuna, monitora.",
     "C": "Cobre treinamento E inferência.",
     "D": "Suporta CPUs e várias GPUs (incluindo NVIDIA P/G/H series e Trainium/Inferentia)."
    },
    "keyConcept": "SageMaker — plataforma ML end-to-end gerenciada",
    "compareWith": [
     "SageMaker vs EC2 self-managed ML",
     "SageMaker JumpStart vs Bedrock"
    ],
    "realWorldContext": "Times de ML que querem foco no modelo e não na infra; MLOps em scale.",
    "commonMistakes": "Confundir SageMaker (ML platform) com Bedrock (foundation models gerenciados).",
    "tutorSeeds": [
     "SageMaker vs Bedrock — quando cada um?",
     "Inference variants — real-time vs async vs serverless?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["sagemaker","ml","ai"]'::jsonb, 'ai-draft', 'active', now(), now()
)
