INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-078', 'aws-clf', 'Uma equipe usa EventBridge para integrar eventos de Stripe (webhooks) com workflows internos. Quer reprocessar eventos de 1 mês atrás após bug fix. Qual feature do EventBridge permite isso?',
  '[{"id":"A","text":"EventBridge não suporta replay — é necessário rebuildar manualmente"},{"id":"B","text":"EventBridge Archives + Replays"},{"id":"C","text":"DynamoDB Streams na destination"},{"id":"D","text":"CloudTrail event lookup"}]'::jsonb, 'B',
  '{
    "summary": "EventBridge Archive grava eventos e Replay reprocessa do archive.",
    "whyCorrect": "EventBridge Archives armazenam eventos do bus (retenção configurável). Replays selecionam um intervalo de tempo + filtro e reentregam eventos às rules como se fossem novos. Perfeito para corrigir bugs em consumers retroativamente.",
    "whyWrong": {
     "A": "Suporta replay nativamente desde 2020.",
     "C": "DDB Streams não tem relação direta com EventBridge replay.",
     "D": "CloudTrail é audit de API calls AWS, não dos eventos de domínio."
    },
    "keyConcept": "EventBridge Archive + Replay — DR e bug recovery",
    "compareWith": [
     "EB Archives vs S3 dump manual"
    ],
    "realWorldContext": "Bug em consumer downstream — replay últimas N horas após fix.",
    "commonMistakes": "Não ativar archive ''pra economizar'' e perder capacidade de replay quando precisar.",
    "tutorSeeds": [
     "Custo do archive — vale sempre ligar?",
     "Replay impacta rate limits?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["eventbridge","archive","replay"]'::jsonb, 'ai-draft', 'active', now(), now()
)
