INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-079', 'aws-clf', 'Uma equipe consome eventos com Kinesis Data Streams e precisa garantir ordem por chave + retenção de 7 dias + múltiplos consumers independentes. Sobre KDS, qual afirmação é VERDADEIRA?',
  '[{"id":"A","text":"KDS é FIFO global, sem partições"},{"id":"B","text":"Retenção máxima do KDS é 24 horas"},{"id":"C","text":"KDS preserva ordem por shard (partition key); retém até 365 dias (configurável); suporta múltiplos consumers via Enhanced Fan-Out (cada consumer 2 MB/s dedicado)"},{"id":"D","text":"KDS suporta apenas 1 consumer por stream"}]'::jsonb, 'C',
  '{
    "summary": "KDS — ordem por shard, retenção até 365d, Enhanced Fan-Out para N consumers paralelos.",
    "whyCorrect": "KDS divide em shards; ordem garantida apenas dentro de um shard (chave de partição). Retenção default 24h, configurável até 365 dias. Enhanced Fan-Out (EFO) dá a cada consumer 2 MB/s dedicado e push via HTTP/2 — superando o limite clássico de 2 MB/s compartilhado.",
    "whyWrong": {
     "A": "Não é FIFO global — ordem por shard.",
     "B": "Até 365 dias com tier extended.",
     "D": "Suporta múltiplos consumers; EFO é o caminho idiomático moderno."
    },
    "keyConcept": "Kinesis Data Streams — shards, partition key, retention, Enhanced Fan-Out",
    "compareWith": [
     "KDS vs Kinesis Firehose vs MSK",
     "Classic shared throughput vs Enhanced Fan-Out"
    ],
    "realWorldContext": "Ingestão de clickstreams, IoT telemetria, real-time analytics.",
    "commonMistakes": "Usar partition key uniforme → hot shard → throttling.",
    "tutorSeeds": [
     "Como dimensionar número de shards?",
     "On-demand mode do KDS — quando vale?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'recall', '["kinesis","kds","enhanced-fan-out"]'::jsonb, 'ai-draft', 'active', now(), now()
)
