INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v2-080', 'aws-clf', 'Uma equipe precisa entregar streaming de dados a S3, Redshift e OpenSearch com transformação opcional e zero ops de cluster. Qual serviço?',
  '[{"id":"A","text":"Kinesis Data Streams com Lambda customizada"},{"id":"B","text":"Amazon MSK"},{"id":"C","text":"AWS Glue Streaming ETL"},{"id":"D","text":"Amazon Data Firehose (anteriormente Kinesis Data Firehose)"}]'::jsonb, 'D',
  '{
    "summary": "Streaming ETL para S3/Redshift/OpenSearch zero-ops = Data Firehose.",
    "whyCorrect": "Amazon Data Firehose (ex-Kinesis Data Firehose) é serverless: ingere streams, faz batching/compression/transformação opcional (via Lambda) e entrega a S3, Redshift, OpenSearch, Splunk, HTTP endpoints, partners. Zero gerenciamento de cluster ou shards.",
    "whyWrong": {
     "A": "KDS + Lambda exige você gerenciar shards e código de entrega.",
     "B": "MSK é Kafka managed — exige mais ops e configuração de connectors.",
     "C": "Glue Streaming ETL é para ETL Spark — mais pesado e caro para entrega simples."
    },
    "keyConcept": "Data Firehose — delivery stream serverless com transformações",
    "compareWith": [
     "Data Firehose vs KDS vs MSK"
    ],
    "realWorldContext": "Logs de aplicações → S3/OpenSearch, métricas → Splunk, eventos → Snowflake.",
    "commonMistakes": "Usar KDS quando o caso é entrega simples a S3 — Firehose é mais barato e simples.",
    "tutorSeeds": [
     "Buffering size/interval — como dimensionar?",
     "Quando Firehose é caro vs KDS?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["firehose","streaming","delivery"]'::jsonb, 'ai-draft', 'active', now(), now()
)
