INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-001', 'aws-clf', 'Uma fintech precisa rodar workloads de risco em batch que toleram interrupcao e busca reduzir custos em ate 90% sobre On-Demand. Qual opcao de compra do EC2 atende melhor?',
  '[{"id":"A","text":"Spot Instances usando a estrategia capacity-optimized"},{"id":"B","text":"Reserved Instances Standard de 3 anos com pagamento adiantado"},{"id":"C","text":"Dedicated Hosts com licenciamento BYOL"},{"id":"D","text":"On-Demand com Savings Plans Compute"}]'::jsonb, 'A',
  '{
    "summary": "Spot Instances oferecem ate 90% de desconto e sao ideais para workloads tolerantes a interrupcao.",
    "whyCorrect": "Spot Instances usam capacidade ociosa do EC2 com desconto de ate 90% sobre On-Demand. Com capacity-optimized, a AWS escolhe pools com menor probabilidade de interrupcao, reduzindo a chance de receber o aviso de 2 minutos durante o batch.",
    "whyWrong": {
     "B": "Reserved Standard 3 anos da ate 72% de desconto, nao 90%, e exige commitment longo, inadequado para workloads efemeros.",
     "C": "Dedicated Hosts custam mais que On-Demand; servem para compliance/BYOL, nao para reduzir custo.",
     "D": "Savings Plans dao ate 66% de desconto e exigem commitment de 1 ou 3 anos, abaixo dos 90% do Spot."
    },
    "keyConcept": "Spot Instances trocam disponibilidade garantida por desconto agressivo; ideais para batch, CI/CD, analytics e ML training tolerantes a falhas.",
    "compareWith": [
     "On-Demand: full price, sem commitment",
     "Reserved: commitment longo, desconto medio",
     "Savings Plans: flexibilidade entre familias"
    ],
    "realWorldContext": "Fintechs frequentemente rodam Monte Carlo simulations em Spot Fleet com checkpoints em S3.",
    "commonMistakes": "Achar que Spot e sempre interrompido. Com capacity-optimized + diversificacao de pools, interrupcao real e baixa.",
    "tutorSeeds": [
     "Como funciona o aviso de 2 minutos do Spot?",
     "Diferenca entre Spot Fleet e EC2 Fleet."
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["ec2","spot","purchase-options","custo"]'::jsonb, 'ai-draft', 'active', now(), now()
)
