INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-002', 'aws-clf', 'Qual e o tempo de aviso (notification) que o EC2 envia antes de interromper uma Spot Instance?',
  '[{"id":"A","text":"30 segundos"},{"id":"B","text":"2 minutos"},{"id":"C","text":"5 minutos"},{"id":"D","text":"15 minutos"}]'::jsonb, 'B',
  '{
    "summary": "Spot Instances recebem aviso de 2 minutos antes da terminacao via instance metadata e EventBridge.",
    "whyCorrect": "A AWS publica um Spot Instance interruption notice 2 minutos antes da interrupcao, permitindo que a aplicacao faca checkpoint, drenagem de conexoes ou re-encaminhamento de jobs.",
    "whyWrong": {
     "A": "30s nao da tempo suficiente para checkpoint; nao e o valor oficial.",
     "C": "5 minutos e o tempo usado em outros servicos, nao no Spot.",
     "D": "15 minutos e o timeout maximo do Lambda, nao tem relacao com Spot."
    },
    "keyConcept": "Aplicacoes em Spot devem ser stateless ou capazes de salvar estado em 2 minutos.",
    "compareWith": [
     "Lambda timeout max: 15min",
     "ASG cooldown default: 300s"
    ],
    "realWorldContext": "Kubernetes em Spot usa node-termination-handler para drenar pods nos 2 minutos.",
    "commonMistakes": "Confundir aviso de Spot com aviso de manutencao programada do EC2 (que pode ser dias).",
    "tutorSeeds": [
     "Como capturar o spot interruption notice via IMDS?",
     "Spot Fleet vs ASG com mixed instances."
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["ec2","spot","interruption"]'::jsonb, 'ai-draft', 'active', now(), now()
)
