INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-003', 'aws-clf', 'Uma empresa quer commitment de 3 anos em EC2 mas reservar a flexibilidade de mudar de familia de instancia (de M5 para C6i, por exemplo) conforme o workload evolui. Qual opcao escolher?',
  '[{"id":"A","text":"Reserved Instances Standard"},{"id":"B","text":"Capacity Reservations"},{"id":"C","text":"Reserved Instances Convertible"},{"id":"D","text":"Dedicated Hosts"}]'::jsonb, 'C',
  '{
    "summary": "Reserved Instances Convertible permitem trocar familia, OS e tenancy durante o termo, sacrificando parte do desconto.",
    "whyCorrect": "Convertible RI da flexibilidade para trocar familia/tamanho/OS/tenancy (desde que o valor da nova RI seja maior ou igual). Standard RI nao permite essa troca.",
    "whyWrong": {
     "A": "Standard RI da maior desconto (ate 72%) mas trava a familia.",
     "B": "Capacity Reservations garantem capacidade em uma AZ especifica mas nao oferecem desconto sozinhas.",
     "D": "Dedicated Hosts isolam hardware fisico; nao oferecem flexibilidade de familia."
    },
    "keyConcept": "Standard = maior desconto, menos flex. Convertible = menos desconto, mais flex.",
    "compareWith": [
     "Savings Plans Compute: ainda mais flex (cross-region, Lambda, Fargate)"
    ],
    "realWorldContext": "Empresas com roadmap incerto preferem Savings Plans Compute pela flexibilidade total.",
    "commonMistakes": "Achar que Convertible significa converter para outro tipo de RI; na verdade e converter a propria RI durante o termo.",
    "tutorSeeds": [
     "Diferencas entre Savings Plans Compute e EC2 Instance Savings Plans",
     "Como funciona o exchange de Convertible RI"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["ec2","reserved-instances","convertible"]'::jsonb, 'ai-draft', 'active', now(), now()
)
