INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-004', 'aws-clf', 'Um workload de HPC com MPI exige latencia de rede minima entre instancias EC2 e alta largura de banda. Qual placement group e recomendado?',
  '[{"id":"A","text":"Spread placement group"},{"id":"B","text":"Partition placement group"},{"id":"C","text":"Multi-AZ placement group"},{"id":"D","text":"Cluster placement group"}]'::jsonb, 'D',
  '{
    "summary": "Cluster placement group coloca instancias proximas fisicamente na mesma AZ para latencia minima e ate 100 Gbps inter-instance.",
    "whyCorrect": "Cluster agrupa instancias em um unico rack/proximidade fisica numa AZ, otimizando latencia e throughput para HPC, ML training distribuido e workloads acoplados.",
    "whyWrong": {
     "A": "Spread distribui instancias em hardware distinto para isolamento de falha, mas aumenta latencia.",
     "B": "Partition isola grupos em particoes distintas; bom para sistemas distribuidos como HDFS/Cassandra, nao para latencia minima.",
     "C": "Multi-AZ placement group nao existe; placement groups sao por AZ (exceto Spread que pode cross-AZ ate 7 instancias)."
    },
    "keyConcept": "Cluster = latencia, Spread = isolamento de falha, Partition = isolamento por rack para clusters grandes.",
    "compareWith": [
     "EFA (Elastic Fabric Adapter): network bypass kernel para HPC"
    ],
    "realWorldContext": "Treinamento de modelos LLM distribuido usa Cluster + EFA + p4d/p5 instances.",
    "commonMistakes": "Usar Cluster para alta disponibilidade. Cluster concentra risco numa unica falha de hardware.",
    "tutorSeeds": [
     "O que e EFA e quando usar?",
     "Limites de instancias em cada tipo de placement group"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["ec2","placement-group","hpc"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
