INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-005', 'aws-clf', 'Uma aplicacao SAP HANA requer R$ (memoria) muito alta (mais de 1 TB de RAM) por instancia. Qual familia EC2 e mais adequada?',
  '[{"id":"A","text":"Familia X (High memory) ou u (High memory bare metal)"},{"id":"B","text":"Familia C (Compute optimized)"},{"id":"C","text":"Familia T (Burstable)"},{"id":"D","text":"Familia I (Storage optimized)"}]'::jsonb, 'A',
  '{
    "summary": "Instancias X (X1, X2) e u-* (High Memory) sao desenhadas para in-memory databases como SAP HANA, com ate 24 TB de RAM.",
    "whyCorrect": "X1/X2 oferecem ate 4TB RAM; instancias High Memory (u-12tb1, u-24tb1) chegam a 24TB e sao certificadas SAP para HANA.",
    "whyWrong": {
     "B": "Familia C otimiza CPU por dolar, baixa RAM por vCPU, inadequada para HANA.",
     "C": "Familia T burstable e para workloads variaveis pequenos, RAM limitada.",
     "D": "Familia I e storage optimized (NVMe local), nao memoria."
    },
    "keyConcept": "Letras das familias EC2: T=burstable, M=general, C=compute, R=memory, X=extreme memory, I=NVMe storage, D=dense HDD, G/P=GPU, Inf/Trn=AI inference/training.",
    "compareWith": [
     "R5: ate 768GB RAM (general memory)",
     "X2idn: ate 4TB",
     "u-24tb1: ate 24TB"
    ],
    "realWorldContext": "Migracoes de SAP on-premise para AWS usam High Memory instances bare metal.",
    "commonMistakes": "Escolher R5 para HANA grande; R limita em 768GB para R5/R6i.",
    "tutorSeeds": [
     "Mapa de familias EC2 vs casos de uso",
     "Bare metal vs virtualized EC2"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["ec2","instance-family","memory","sap"]'::jsonb, 'ai-draft', 'active', now(), now()
)
