INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-006', 'aws-clf', 'Qual a diferenca principal entre Dedicated Instance e Dedicated Host no EC2?',
  '[{"id":"A","text":"Dedicated Instance permite BYOL (Bring Your Own License) por socket; Dedicated Host nao"},{"id":"B","text":"Dedicated Host expoe sockets/cores fisicos e permite BYOL; Dedicated Instance isola hardware mas sem visibilidade de socket"},{"id":"C","text":"Sao o mesmo produto com nomes diferentes"},{"id":"D","text":"Dedicated Host roda apenas em regioes GovCloud"}]'::jsonb, 'B',
  '{
    "summary": "Dedicated Host expoe sockets/cores para licenciamento BYOL; Dedicated Instance apenas garante hardware dedicado, sem visibilidade detalhada.",
    "whyCorrect": "Dedicated Host permite ver e controlar sockets/cores fisicos, necessario para BYOL Windows Server, SQL Server, Oracle. Dedicated Instance da hardware dedicado por conta mas sem visibilidade detalhada de cores.",
    "whyWrong": {
     "A": "Inverso: BYOL por socket precisa de Dedicated Host.",
     "C": "Sao produtos distintos com casos de uso diferentes.",
     "D": "Ambos rodam em qualquer regiao comercial."
    },
    "keyConcept": "BYOL com licenca por socket exige Dedicated Host. Compliance basica de hardware isolado: Dedicated Instance.",
    "compareWith": [
     "Default tenancy (shared): mais barato"
    ],
    "realWorldContext": "Migracoes de Oracle DB on-prem para AWS frequentemente usam Dedicated Hosts.",
    "commonMistakes": "Achar que Dedicated Instance permite BYOL com licenca por socket.",
    "tutorSeeds": [
     "License Manager AWS",
     "Host Affinity em Dedicated Hosts"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'recall', '["ec2","tenancy","dedicated-host"]'::jsonb, 'ai-draft', 'active', now(), now()
)
