INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-007', 'aws-clf', 'Uma equipe de seguranca quer mitigar ataques SSRF que abusam do Instance Metadata Service do EC2. Qual recomendacao AWS atende isso?',
  '[{"id":"A","text":"Desativar completamente o IMDS"},{"id":"B","text":"Trocar a porta do IMDS"},{"id":"C","text":"Forcar IMDSv2 (token-based) e desabilitar IMDSv1"},{"id":"D","text":"Mover IMDS para uma subnet privada"}]'::jsonb, 'C',
  '{
    "summary": "IMDSv2 exige PUT com token de sessao, mitigando ataques SSRF que apenas fazem GET no endpoint 169.254.169.254.",
    "whyCorrect": "IMDSv2 introduz autenticacao via token de sessao (PUT request retorna token, GET subsequente requer header X-aws-ec2-metadata-token). SSRF tipicos so fazem GET, falhando contra IMDSv2.",
    "whyWrong": {
     "A": "Desativar IMDS quebra acesso de role IAM e User Data; nao e pratico.",
     "B": "O IMDS roda em link-local 169.254.169.254; nao se troca a porta.",
     "D": "IMDS e link-local na instancia, nao roteado em subnets."
    },
    "keyConcept": "IMDSv2 token-based hop limit reduzido a 1 mitiga SSRF em containers e SSRF web apps.",
    "compareWith": [
     "IMDSv1: simples GET, vulneravel a SSRF"
    ],
    "realWorldContext": "O incidente Capital One (2019) explorou IMDSv1 via SSRF. AWS hoje recomenda IMDSv2 obrigatorio.",
    "commonMistakes": "Confiar que apenas Security Groups protegem contra SSRF; SSRF parte de dentro da instancia.",
    "tutorSeeds": [
     "Como configurar IMDSv2 obrigatorio em ASG",
     "Hop limit do IMDS"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["ec2","imds","seguranca"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
