INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-008', 'aws-clf', 'Qual e a diferenca entre Stop, Hibernate e Terminate de uma instancia EC2?',
  '[{"id":"A","text":"Stop e Hibernate sao iguais; ambos apagam a RAM"},{"id":"B","text":"Terminate apenas reinicia; Stop apaga a instancia"},{"id":"C","text":"Hibernate so funciona para instancias com instance store"},{"id":"D","text":"Stop desliga preservando EBS; Hibernate persiste RAM em EBS criptografado; Terminate apaga a instancia"}]'::jsonb, 'D',
  '{
    "summary": "Stop desliga preservando EBS root; Hibernate dumpa RAM no EBS root criptografado; Terminate destroi a instancia e (opcional) o EBS root.",
    "whyCorrect": "Hibernate exige EBS criptografado, RAM ate 150GB (depende do tipo) e familias suportadas. Acelera resumo de aplicacoes com long warm-up.",
    "whyWrong": {
     "A": "Stop apaga RAM, Hibernate persiste. Sao diferentes.",
     "B": "Terminate e destrutivo, nao reinicia.",
     "C": "Hibernate requer EBS root, nao instance store (que e efemero)."
    },
    "keyConcept": "Hibernate = stop preservando estado da memoria; util para JVMs grandes e ML workers.",
    "compareWith": [
     "Reboot: nao muda host fisico",
     "Stop/Start: pode mudar host fisico"
    ],
    "realWorldContext": "Workstations EC2 com aplicacoes pesadas usam Hibernate para retomar rapido.",
    "commonMistakes": "Tentar hibernar instance store ou instancia sem encryption.",
    "tutorSeeds": [
     "Pre-requisitos do Hibernate",
     "Stop-Hibernate vs SnapStart Lambda"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["ec2","hibernate","lifecycle"]'::jsonb, 'ai-draft', 'active', now(), now()
)
