INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-009', 'aws-clf', 'Uma instancia EC2 falha apenas no Instance Status Check (mas passa no System Status Check). Qual a causa mais provavel?',
  '[{"id":"A","text":"Problema no OS/aplicacao da instancia (filesystem corrompido, kernel panic, networking misconfig)"},{"id":"B","text":"Problema no hardware fisico da AWS"},{"id":"C","text":"Falha de rede da AWS"},{"id":"D","text":"Falha na AZ inteira"}]'::jsonb, 'A',
  '{
    "summary": "Instance Status Check verifica o OS/configuracao da instancia; falhar nele indica problema dentro da instancia.",
    "whyCorrect": "Instance Status Check valida que o OS responde, networking interno funciona, etc. Falhar so esse check indica problema dentro da VM (kernel panic, fs corrupt, etc). System Status Check passa = hardware/rede AWS OK.",
    "whyWrong": {
     "B": "Problema de hardware AWS faz System Status Check falhar.",
     "C": "Falha de rede AWS afeta System Status Check.",
     "D": "Falha de AZ inteira faria multiplas instancias e o System Check falhar."
    },
    "keyConcept": "System Status = problema AWS (precisa migrar host). Instance Status = problema seu (precisa corrigir OS).",
    "compareWith": [
     "EBS Status Check",
     "ENA driver issues"
    ],
    "realWorldContext": "Auto Recovery usa System Status Check para migrar instancia automaticamente.",
    "commonMistakes": "Achar que Auto Recovery resolve Instance Status Check; nao resolve, e questao da VM.",
    "tutorSeeds": [
     "Como configurar Auto Recovery",
     "CloudWatch alarms para status checks"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'troubleshoot', '["ec2","status-checks","troubleshoot"]'::jsonb, 'ai-draft', 'active', now(), now()
)
