INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-010', 'aws-clf', 'Como uma equipe pode rodar um script de bootstrap em uma instancia EC2 na primeira boot para instalar pacotes e configurar a aplicacao?',
  '[{"id":"A","text":"Usar IAM Role no boot"},{"id":"B","text":"Usar EC2 User Data com shell script ou cloud-init"},{"id":"C","text":"Usar Snapshot do EBS"},{"id":"D","text":"Usar Placement Group"}]'::jsonb, 'B',
  '{
    "summary": "User Data executa script na primeira boot (por padrao), permitindo bootstrap como apt-get install, configuracao de servico etc.",
    "whyCorrect": "User Data e passado como texto/script ao lancar a instancia e executado como root durante o boot. Suporta shell script, cloud-init directives e PowerShell em Windows.",
    "whyWrong": {
     "A": "IAM Role da permissoes mas nao executa scripts.",
     "C": "Snapshot e backup de disco, nao executa codigo.",
     "D": "Placement Group e topologia de rede."
    },
    "keyConcept": "User Data e a forma nativa de bootstrap; idempotencia depende do script.",
    "compareWith": [
     "AMIs com tudo pre-instalado (golden image)",
     "Systems Manager State Manager"
    ],
    "realWorldContext": "Combinar AMI golden + User Data minimo para customizacao por ambiente.",
    "commonMistakes": "Esperar que User Data rode em cada boot por padrao; por default so na primeira.",
    "tutorSeeds": [
     "cloud-init directives",
     "Como forcar User Data a rodar em cada boot"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["ec2","user-data","bootstrap"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
