INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-011', 'aws-clf', 'Uma empresa quer publicar uma AMI customizada (com software proprietario) para uso interno em multiplas contas AWS da organizacao. Qual abordagem?',
  '[{"id":"A","text":"Publicar como AMI Publica para que qualquer pessoa acesse"},{"id":"B","text":"Publicar como Community AMI sem restricao"},{"id":"C","text":"Compartilhar a AMI Privada com IDs de conta especificas ou via AWS Organizations"},{"id":"D","text":"Publicar no AWS Marketplace com preco zero"}]'::jsonb, 'C',
