INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-012', 'aws-clf', 'Quando devo escolher familia de instancias Inf (Inferentia) ou Trn (Trainium) ao inves de familias G/P (NVIDIA GPU)?',
  '[{"id":"A","text":"Sempre que precisar de qualquer aceleracao de ML"},{"id":"B","text":"Apenas para inferencia de imagem"},{"id":"C","text":"Inf e Trn nao existem ainda"},{"id":"D","text":"Quando custo-beneficio de inferencia/treinamento em chips proprios AWS for melhor que GPU e frameworks suportarem (Neuron SDK)"}]'::jsonb, 'D',
  '{
    "summary": "Inferentia (inferencia) e Trainium (treinamento) sao chips AWS otimizados para ML; reduzem custo se modelo for portado via Neuron SDK.",
    "whyCorrect": "Inf2 e Trn1/Trn2 oferecem custo/desempenho melhor que GPU em workloads suportados (transformers, BERT, GPT-like). Requer compilacao via Neuron SDK.",
    "whyWrong": {
     "A": "Nem todo modelo roda em Inferentia (depende de suporte do Neuron).",
     "B": "Suportam diversos modelos, incluindo NLP, recsys e vision.",
     "C": "Existem desde 2019 (Inf1) / 2022 (Trn1)."
    },
    "keyConcept": "Chips proprios AWS reduzem custo para clientes que adotam o ecossistema Neuron.",
    "compareWith": [
     "P5: NVIDIA H100",
     "G5/G6: NVIDIA A10G/L4",
     "Inf2/Trn2: AWS silicon"
    ],
    "realWorldContext": "Anthropic e parceiros usam Trainium para treinar LLMs em larga escala.",
    "commonMistakes": "Migrar para Inferentia sem validar suporte do modelo no Neuron SDK.",
    "tutorSeeds": [
     "Neuron SDK",
     "SageMaker com Inferentia"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["ec2","ml","inferentia","trainium"]'::jsonb, 'ai-draft', 'active', now(), now()
