INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-014', 'aws-clf', 'Uma startup nao consegue prever spikes de trafego e quer evitar capacity planning. Quer manter custo baixo. Sobre EC2, qual e a abordagem MAIS adequada?',
  '[{"id":"A","text":"Reservar 100 instancias On-Demand"},{"id":"B","text":"Auto Scaling Group com mixed instances policy combinando Spot e On-Demand, com Target Tracking baseado em CPU/requisicoes"},{"id":"C","text":"Comprar Reserved 3 anos para 200 instancias"},{"id":"D","text":"Usar uma instancia X1e gigante"}]'::jsonb, 'B',
  '{
    "summary": "ASG com mixed instances ajusta capacidade dinamicamente usando Spot para barato + On-Demand para baseline.",
    "whyCorrect": "Mixed instances policy permite diversificar tipos de instancia e Spot pools, reduzindo custo e aumentando resiliencia. Target Tracking ajusta automaticamente.",
    "whyWrong": {
     "A": "Capacidade fixa nao escala; desperdicio em vales.",
     "C": "Reservar 200 instancias com commitment 3 anos e arriscado para startup.",
     "D": "Instancia gigante unica = single point of failure."
    },
    "keyConcept": "Elasticidade = ASG dinamico. Custo otimo = mistura Spot + On-Demand.",
    "compareWith": [
     "Predictive scaling para padroes recorrentes"
    ],
    "realWorldContext": "Startups usam ASG mixed para handle spikes virais sem overprovisioning.",
    "commonMistakes": "Usar Simple Scaling com thresholds rigidos; pode oscilar.",
    "tutorSeeds": [
     "Predictive Scaling",
     "Target Tracking vs Step Scaling"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["ec2","asg","mixed-instances","spot"]'::jsonb, 'ai-draft', 'active', now(), now()
)
