INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-015', 'aws-clf', 'O que diferencia Capacity Reservations de Reserved Instances no EC2?',
  '[{"id":"A","text":"Sao identicos"},{"id":"B","text":"Capacity Reservations dao maior desconto"},{"id":"C","text":"Capacity Reservations reservam capacidade em uma AZ especifica mas SEM commitment de desconto; Reserved Instances dao desconto com commitment 1/3 anos"},{"id":"D","text":"Capacity Reservations existem apenas para Windows"}]'::jsonb, 'C',
  '{
    "summary": "Capacity Reservations = garantia de capacidade pagando On-Demand; RI = desconto com commitment.",
    "whyCorrect": "Capacity Reservations garantem que voce conseguira lancar instancias daquele tipo naquela AZ, mas sem desconto inerente (pode combinar com Savings Plans para desconto).",
    "whyWrong": {
     "A": "Sao produtos diferentes.",
     "B": "CR nao tem desconto inerente.",
     "D": "Suporta varios OS."
    },
    "keyConcept": "CR = capacidade fisica garantida. RI/SP = desconto financeiro.",
    "compareWith": [
     "On-Demand Capacity Reservations + Savings Plans"
    ],
    "realWorldContext": "Empresas reservam CR para eventos como Black Friday garantindo lanca em AZ especifica.",
    "commonMistakes": "Confundir CR como otimizacao de custo; e otimizacao de disponibilidade.",
    "tutorSeeds": [
     "Como combinar CR com Savings Plans",
     "Zonal RI vs Regional RI"
    ]
   }'::jsonb,
