INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-016', 'aws-clf', 'O que e EC2 Spot Fleet?',
  '[{"id":"A","text":"Conjunto de instancias Reserved gerenciado por ASG"},{"id":"B","text":"Uma frota de instancias Dedicated"},{"id":"C","text":"Servico de migracao de Spot"},{"id":"D","text":"Solicitacao para lancar conjunto de Spot Instances (e opcionalmente On-Demand) seguindo estrategias de alocacao (lowest-price, capacity-optimized, diversified)"}]'::jsonb, 'D',
  '{
    "summary": "Spot Fleet lanca multiplos Spot Instances diversificados em pools, com estrategias para minimizar custo ou interrupcao.",
    "whyCorrect": "Spot Fleet aceita launch specifications variadas e usa estrategias como capacity-optimized para escolher pools com menor risco de interrupcao.",
    "whyWrong": {
     "A": "Spot Fleet e para Spot, nao Reserved.",
     "B": "Nao tem relacao com Dedicated.",
     "C": "Nao e servico de migracao."
    },
    "keyConcept": "Spot Fleet vs EC2 Fleet: EC2 Fleet e mais novo e recomendado, suporta Spot+On-Demand mais flexivelmente.",
    "compareWith": [
     "EC2 Fleet (recomendado)",
     "ASG com mixed instances"
    ],
    "realWorldContext": "Cluster Kubernetes em Spot frequentemente usa Karpenter ou Spot Fleet/EC2 Fleet.",
