INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-019', 'aws-clf', 'Uma aplicacao precisa de hibernate em EC2 mas o time esqueceu de habilitar uma condicao. Qual e pre-requisito para hibernate?',
  '[{"id":"A","text":"Instance Store como root"},{"id":"B","text":"Tenancy dedicada"},{"id":"C","text":"EBS root criptografado e familia/tamanho suportados (RAM tipicamente ate 150GB)"},{"id":"D","text":"Placement group cluster"}]'::jsonb, 'C',
  '{
    "summary": "Hibernate requer EBS root criptografado, familias suportadas (M3-M5, C3-C5, R3-R5, etc) e RAM <= 150GB tipicamente.",
    "whyCorrect": "Hibernate persiste a RAM no volume EBS root, que precisa ser criptografado. Apenas familias e tamanhos especificos sao suportados.",
    "whyWrong": {
     "A": "Instance store nao persiste, incompativel com hibernate.",
     "B": "Tenancy nao e requisito.",
     "D": "Placement group nao tem relacao."
    },
    "keyConcept": "Hibernate = dump de RAM no EBS criptografado.",
    "compareWith": [
     "Stop normal nao persiste RAM"
    ],
    "realWorldContext": "Dev environments com IDE pesada usam Hibernate para retomar contexto.",
    "commonMistakes": "Esquecer da encryption do EBS root.",
    "tutorSeeds": [
     "Limite de 150GB",
     "Custos de EBS apos hibernate"
    ]
   }'::jsonb,
