INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-020', 'aws-clf', 'Um time precisa garantir que ASG aguarde aplicacao subir antes de marcar instancia como saudavel. Qual recurso usar?',
  '[{"id":"A","text":"Cooldown period"},{"id":"B","text":"Predictive scaling"},{"id":"C","text":"Spot fleet"},{"id":"D","text":"Health check grace period e/ou ELB health checks com lifecycle hooks"}]'::jsonb, 'D',
  '{
    "summary": "Health check grace period adia a verificacao para dar tempo do app subir; lifecycle hooks pausam o estado pending:Wait/Terminating:Wait.",
    "whyCorrect": "Grace period define quanto tempo apos lancamento o ASG ignora falhas de health check. Lifecycle hooks permitem rodar User Data extenso ou registrar em service discovery antes de marcar InService.",
    "whyWrong": {
     "A": "Cooldown evita acoes de scaling em sequencia, nao espera bootstrap.",
     "B": "Predictive scaling antecipa demanda, nao boot.",
     "C": "Spot fleet e modelo de compra."
    },
    "keyConcept": "Grace period + ELB health checks + lifecycle hooks = bootstrap robusto.",
    "compareWith": [
     "Warm pools para pre-bootstrap"
    ],
    "realWorldContext": "Apps Java com warm-up longo usam grace period 300-600s.",
    "commonMistakes": "ELB marcar como unhealthy antes do app subir; ajustar grace period resolve.",
    "tutorSeeds": [
     "Lifecycle hooks",
     "Warm pools ASG"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'troubleshoot', '["asg","health-check","lifecycle"]'::jsonb, 'ai-draft', 'active', now(), now()
)
