INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-021', 'aws-clf', 'O que sao ASG Warm Pools e quando usar?',
  '[{"id":"A","text":"Pool de instancias pre-inicializadas (parado/em-stop) prontas para entrar no ASG rapidamente, reduzindo tempo de scale-out"},{"id":"B","text":"Pool de instancias Reserved pre-pagas"},{"id":"C","text":"Pool de Spot Instances"},{"id":"D","text":"Pool de IPs Elastic"}]'::jsonb, 'A',
  '{
    "summary": "Warm pools mantem instancias pre-inicializadas (em Stopped) para acelerar scale-out em workloads com bootstrap longo.",
    "whyCorrect": "Warm pool permite ter N instancias prontas em estado Stopped/Hibernated. Quando o ASG precisa escalar, transiciona-as rapido para InService, evitando longo cold start.",
    "whyWrong": {
     "B": "Nao tem relacao com Reserved.",
     "C": "Spot tem semantica diferente.",
     "D": "IPs Elastic nao tem warm pool."
    },
    "keyConcept": "Warm Pool = trade entre custo (instancias paradas pagam EBS) e velocidade de escala.",
    "compareWith": [
     "Lambda Provisioned Concurrency: analogo no serverless"
    ],
    "realWorldContext": "Apps Java Spring Boot com warm-up longo se beneficiam de warm pools.",
    "commonMistakes": "Pagar por instancias paradas sem need; warm pool tem custo de EBS.",
    "tutorSeeds": [
     "Lifecycle state Warmed:Hibernated",
     "Custos warm pool"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["asg","warm-pool"]'::jsonb, 'ai-draft', 'active', now(), now()
