INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-022', 'aws-clf', 'Diferenca principal entre ALB e NLB?',
  '[{"id":"A","text":"ALB e mais barato"},{"id":"B","text":"ALB opera em L7 (HTTP/HTTPS), com path/host-based routing; NLB opera em L4 (TCP/UDP/TLS), com altissima performance e latencia minima"},{"id":"C","text":"NLB suporta WebSockets, ALB nao"},{"id":"D","text":"Sao identicos com nomes diferentes"}]'::jsonb, 'B',
  '{
    "summary": "ALB = L7, NLB = L4. ALB roteia por path/host/header; NLB por porta/IP.",
    "whyCorrect": "ALB trabalha em HTTP/HTTPS, faz routing por path, host, query, headers; suporta target Lambda. NLB trabalha em TCP/UDP/TLS, low-latency, milhoes de RPS, IP estatico por AZ.",
    "whyWrong": {
     "A": "NLB e ALB tem precos diferentes; depende do trafego.",
     "C": "Ambos suportam WebSocket.",
     "D": "Sao produtos distintos."
    },
    "keyConcept": "L7 = ALB (inteligencia HTTP). L4 = NLB (performance).",
    "compareWith": [
     "GWLB para appliances de seguranca",
     "CLB legacy"
    ],
    "realWorldContext": "APIs HTTP -> ALB. Gaming/IoT TCP -> NLB.",
    "commonMistakes": "Usar NLB para HTTP path routing; NLB nao olha L7.",
    "tutorSeeds": [
     "Sticky sessions ALB",
     "NLB com IP estatico"
    ]
