INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-025', 'aws-clf', 'O que e cross-zone load balancing e como difere entre ALB e NLB no billing/comportamento?',
  '[{"id":"A","text":"Distribui trafego entre AZs igualmente; em ALB e sempre ON sem custo extra; em NLB e OFF por padrao e habilitar gera custo de transferencia inter-AZ"},{"id":"B","text":"Sempre desligado em ambos"},{"id":"C","text":"Sempre ligado em ambos sem custo"},{"id":"D","text":"Apenas NLB suporta"}]'::jsonb, 'A',
  '{
    "summary": "Cross-zone equilibra requests entre targets de TODAS AZs; ALB e default ON gratis, NLB e default OFF e cobra transferencia inter-AZ se ligado.",
    "whyCorrect": "Cross-zone evita desbalanceamento quando AZs tem targets desiguais. ALB inclui sem custo; NLB cobra data transfer inter-AZ.",
