INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-032', 'aws-clf', 'Sobre memoria do Lambda, qual e o range e como CPU se comporta?',
  '[{"id":"A","text":"128MB a 3008MB; CPU fixa"},{"id":"B","text":"512MB a 10GB; CPU configuravel separadamente"},{"id":"C","text":"1GB minimo; CPU dedicada"},{"id":"D","text":"128MB a 10240MB (10GB); CPU escala proporcionalmente com memoria"}]'::jsonb, 'D',
  '{
    "summary": "Lambda permite de 128MB a 10240MB de memoria em incrementos de 1MB; CPU/IO escalam proporcionalmente.",
    "whyCorrect": "Em 1769MB Lambda recebe ~1 vCPU; mais memoria = mais vCPU. Para CPU-bound, aumentar memoria ajuda mesmo nao precisando.",
    "whyWrong": {
     "A": "Limite antigo era 3008MB, atualizado para 10GB.",
     "B": "Nao se configura CPU separadamente.",
     "C": "Minimo e 128MB."
    },
    "keyConcept": "Tunar memoria do Lambda otimiza custo/latencia via Lambda Power Tuning.",
    "compareWith": [
     "Fargate: CPU e memoria separados"
    ],
    "realWorldContext": "Funcoes de processamento de imagem se beneficiam de mais memoria/CPU.",
