INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-033', 'aws-clf', 'Qual a diferenca entre Provisioned Concurrency e Reserved Concurrency em AWS Lambda?',
  '[{"id":"A","text":"Provisioned mantem execucoes prontas (sem cold start) custando $; Reserved limita maximo de concorrencia simultanea, sem pre-aquecer"},{"id":"B","text":"Sao iguais"},{"id":"C","text":"Reserved e mais caro que Provisioned"},{"id":"D","text":"Provisioned existe apenas em Lambda@Edge"}]'::jsonb, 'A',
  '{
    "summary": "Provisioned Concurrency = ambientes Lambda pre-inicializados (combate cold start); Reserved Concurrency = teto de execucoes simultaneas (protege downstream).",
    "whyCorrect": "Provisioned tem custo extra continuo. Reserved nao custa nada extra mas garante quota dedicada (e nao mais).",
    "whyWrong": {
     "B": "Sao mecanismos distintos.",
     "C": "Provisioned e o que custa extra.",
     "D": "Existe em Lambda regular."
    },
    "keyConcept": "Cold start = Provisioned. Rate limit = Reserved.",
    "compareWith": [
     "Account concurrent limit 1000 default"
    ],
    "realWorldContext": "APIs com SLA estrito usam Provisioned. Funcoes que chamam DB legado usam Reserved para nao saturar.",
    "commonMistakes": "Achar que Reserved acelera cold start; nao acelera.",
    "tutorSeeds": [
     "Auto Scaling de Provisioned",
     "Account-level concurrency"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'recall', '["lambda","provisioned-concurrency","reserved-concurrency"]'::jsonb, 'ai-draft', 'active', now(), now()
)
