INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-047', 'aws-clf', 'Qual o throughput de SQS FIFO sem batching e com batching?',
  '[{"id":"A","text":"30 e 300 msg/s"},{"id":"B","text":"1000 e 10000 msg/s"},{"id":"C","text":"300 msg/s sem batching e 3000 msg/s com batching (modo high throughput chega a 70k+)"},{"id":"D","text":"Ilimitado em ambos"}]'::jsonb, 'C',
  '{
    "summary": "SQS FIFO classico: 300 msg/s sem batch, 3000 com batch (10 msgs/op). High throughput mode chega a dezenas de milhares.",
    "whyCorrect": "FIFO Standard tem 300/3000; high throughput mode permite particionar message groups para escalar mais.",
    "whyWrong": {
     "A": "Numeros incorretos.",
     "B": "Acima do limite default.",
     "D": "Tem limite."
    },
    "keyConcept": "FIFO troca ordem por throughput limitado; Standard nao garante ordem mas e ilimitado.",
    "compareWith": [
     "SQS Standard: virtualmente ilimitado"
    ],
    "realWorldContext": "Pedidos com ordem garantida em e-commerce usam FIFO; eventos analiticos usam Standard.",
    "commonMistakes": "Usar FIFO onde Standard atende.",
    "tutorSeeds": [
     "High throughput mode",
     "Message group ID"
    ]
   }'::jsonb,
