INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-048', 'aws-clf', 'O que e visibility timeout no SQS e qual o valor default?',
  '[{"id":"A","text":"Tempo que mensagem fica visivel apos publish; default 30s"},{"id":"B","text":"Tempo que fica na DLQ"},{"id":"C","text":"Tempo entre polls"},{"id":"D","text":"Tempo que mensagem fica INVISIVEL apos ser recebida por consumer, evitando re-entrega; default 30 segundos"}]'::jsonb, 'D',
  '{
    "summary": "Visibility timeout esconde mensagem apos receive() para o consumer processar; se nao deletar, retorna a fila. Default 30s.",
    "whyCorrect": "Permite at-least-once processing: outro consumer nao pega a mensagem ate timeout expirar.",
    "whyWrong": {
     "A": "E o oposto; fica invisivel.",
     "B": "DLQ tem retention propria.",
     "C": "Long polling e diferente."
    },
    "keyConcept": "Visibility timeout deve ser maior que tempo de processamento; usar ChangeMessageVisibility para extender.",
    "compareWith": [
     "Message retention default 4 dias, max 14"
    ],
    "realWorldContext": "Processamento longo precisa ajustar visibility ou usar ChangeMessageVisibility.",
    "commonMistakes": "Mensagem duplicada por processamento maior que visibility.",
    "tutorSeeds": [
     "ChangeMessageVisibility",
     "DLQ + maxReceiveCount"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["sqs","visibility-timeout"]'::jsonb, 'ai-draft', 'active', now(), now()
)
