INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-049', 'aws-clf', 'Quando uma mensagem do SQS vai para DLQ?',
  '[{"id":"A","text":"Quando excede maxReceiveCount falhas de processamento (entregas sem delete)"},{"id":"B","text":"Depois de 4 dias sem ser lida"},{"id":"C","text":"Imediatamente se houver erro"},{"id":"D","text":"Nunca, DLQ e manual"}]'::jsonb, 'A',
  '{
    "summary": "DLQ recebe mensagens que excederam maxReceiveCount (configurado na fila source) sem terem sido deletadas.",
    "whyCorrect": "Permite isolar mensagens problematicas para investigacao posterior, mantendo throughput da fila principal.",
    "whyWrong": {
     "B": "Apos retention max (14d) sao deletadas.",
     "C": "Erros sao retried ate maxReceiveCount.",
     "D": "E automatico via redrive policy."
    },
    "keyConcept": "DLQ + maxReceiveCount = poison message isolation.",
    "compareWith": [
     "DLQ no Lambda async invoke"
    ],
    "realWorldContext": "Apps em producao sempre tem DLQ + alarm para mensagens nao processadas.",
    "commonMistakes": "Esquecer de criar alarme sobre DLQ; mensagens ficam silenciosamente.",
    "tutorSeeds": [
     "DLQ redrive task",
     "Alarme em ApproximateNumberOfMessagesVisible da DLQ"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["sqs","dlq"]'::jsonb, 'ai-draft', 'active', now(), now()
)
