INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-050', 'aws-clf', 'Diferenca entre Long Polling e Short Polling no SQS?',
  '[{"id":"A","text":"Sao iguais"},{"id":"B","text":"Long polling (ate 20s) reduz API calls e latencia em filas vazias; Short polling (0s) retorna imediatamente, podendo nao trazer mensagens disponiveis"},{"id":"C","text":"Short polling e mais barato"},{"id":"D","text":"Long polling nao retorna mensagens"}]'::jsonb, 'B',
  '{
    "summary": "Long polling com WaitTimeSeconds 1-20 espera mensagens chegar, reduzindo API calls em fila vazia e melhorando latencia.",
    "whyCorrect": "Short polling pode retornar vazio mesmo havendo mensagem (devido a distribuicao SQS); long polling consulta multiplos servidores e e mais eficiente.",
    "whyWrong": {
     "A": "Sao distintos.",
     "C": "Short polling gera mais API calls cobradas.",
     "D": "Long polling retorna mensagens."
    },
    "keyConcept": "ReceiveMessage com WaitTimeSeconds > 0 = long polling.",
    "compareWith": [
     "SNS push: sem polling"
    ],
    "realWorldContext": "Sempre usar long polling em producao.",
    "commonMistakes": "Polling com WaitTimeSeconds 0 e high volume = custo desnecessario.",
    "tutorSeeds": [
     "Max wait time 20s",
     "Combinacao com visibility timeout"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["sqs","polling"]'::jsonb, 'ai-draft', 'active', now(), now()
)
