INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-051', 'aws-clf', 'Qual padrao desacopla um publisher para multiplos consumers heterogeneos com filtragem por consumer?',
  '[{"id":"A","text":"Lambda chamando Lambda"},{"id":"B","text":"DynamoDB Streams para todos"},{"id":"C","text":"Fanout SNS -\u003e multiplas SQS com filter policies; cada consumer le sua fila"},{"id":"D","text":"Kinesis sem consumers"}]'::jsonb, 'C',
  '{
    "summary": "Pattern fanout: SNS publica uma vez, cada subscriber SQS recebe (com filter policy opcional), desacoplando produtor de consumidores.",
    "whyCorrect": "Permite consumidores processarem em ritmo proprio com retries via SQS, sem afetar publisher.",
    "whyWrong": {
     "A": "Acoplamento forte.",
     "B": "DynamoDB Streams e para mudancas em tabelas.",
     "D": "Kinesis precisa de consumers."
    },
    "keyConcept": "Fanout SNS->SQS = padrao classico desacoplamento many-to-many.",
    "compareWith": [
     "EventBridge bus: routing avancado e filtros JSON"
    ],
    "realWorldContext": "Order events publicados em SNS, consumidos por billing, fulfillment, analytics, cada um com SQS.",
    "commonMistakes": "Subscrever Lambdas diretamente em SNS perdendo retries durabilidade.",
    "tutorSeeds": [
     "Filter policies SNS",
     "EventBridge vs SNS para fanout"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["sns","sqs","fanout"]'::jsonb, 'ai-draft', 'active', now(), now()
)
