INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-052', 'aws-clf', 'O que SNS Message Filtering (filter policies) faz?',
  '[{"id":"A","text":"Filtra spam"},{"id":"B","text":"Filtra IPs"},{"id":"C","text":"Substitui WAF"},{"id":"D","text":"Permite que cada subscription receba apenas mensagens cujos atributos batam com um pattern JSON, evitando processamento desnecessario"}]'::jsonb, 'D',
  '{
    "summary": "Filter policies permitem que cada subscriber declare quais mensagens quer receber, baseado em message attributes ou body (com filter por body habilitado).",
    "whyCorrect": "Reduz throughput desnecessario e logica de filtragem no consumer.",
    "whyWrong": {
     "A": "Nao filtra spam.",
     "B": "Nao filtra IPs.",
     "C": "WAF e network."
    },
    "keyConcept": "SNS Filter Policy = SQL-like JSON sobre attributes/body.",
    "compareWith": [
     "EventBridge event patterns"
    ],
    "realWorldContext": "Eventos de pedido com country=BR vao para subscriber de operacoes BR.",
    "commonMistakes": "Filtrar no Lambda em vez de SNS = custo desnecessario.",
    "tutorSeeds": [
     "Numeric/exists/anything-but operators",
     "Filter scope: attributes vs body"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["sns","filter-policy"]'::jsonb, 'ai-draft', 'active', now(), now()
)
