INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-055', 'aws-clf', 'Qual o tempo de retrieval do S3 Glacier Deep Archive em modo Standard e Bulk?',
  '[{"id":"A","text":"5 minutos e 1 hora"},{"id":"B","text":"1 hora e 3 horas"},{"id":"C","text":"12 horas (Standard) e 48 horas (Bulk)"},{"id":"D","text":"15 minutos e 30 minutos"}]'::jsonb, 'C',
  '{
    "summary": "Deep Archive: standard 12h, bulk 48h. Min storage 180 dias.",
    "whyCorrect": "Deep Archive e o tier mais barato para arquivamento de longo prazo (anos) com tempo de retrieval em horas.",
    "whyWrong": {
     "A": "Sao Glacier Flexible (Expedited/Standard).",
     "B": "Standard Glacier Flexible numbers.",
     "D": "Tempos de Glacier Instant Retrieval."
    },
    "keyConcept": "Glacier classes: Instant (ms, min 90d), Flexible (min-h, min 90d), Deep Archive (h, min 180d).",
    "compareWith": [
