INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-068', 'aws-clf', 'Sobre EFS, qual afirmacao e correta?',
  '[{"id":"A","text":"E SMB apenas"},{"id":"B","text":"Nao suporta multi-AZ"},{"id":"C","text":"Substitui RDS"},{"id":"D","text":"E NFS gerenciado, escalavel automaticamente, com modes Standard (multi-AZ) e One Zone, com classes Standard e IA"}]'::jsonb, 'D',
  '{
    "summary": "EFS = NFS gerenciado multi-AZ (Standard) ou single-AZ (One Zone), com lifecycle entre Standard/IA, performance mode bursting/provisioned.",
    "whyCorrect": "Suporta milhares de conexoes concorrentes, ideal para shared FS entre EC2/Fargate/Lambda.",
    "whyWrong": {
     "A": "EFS = NFS. SMB e FSx Windows.",
     "B": "Standard EFS e multi-AZ por padrao.",
     "C": "EFS e file storage; RDS e database."
    },
    "keyConcept": "EFS = NFS gerenciado, escalavel, multi-AZ.",
    "compareWith": [
     "FSx Windows: SMB",
     "FSx Lustre: HPC"
    ],
    "realWorldContext": "WordPress multi-instance com EFS para wp-content compartilhado.",
    "commonMistakes": "Usar EFS para DB transacional; performance e cost desfavoraveis.",
    "tutorSeeds": [
     "Bursting vs Provisioned",
     "Lifecycle para IA"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["efs","nfs"]'::jsonb, 'ai-draft', 'active', now(), now()
)
