INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-069', 'aws-clf', 'Multi-AZ em RDS escala leitura?',
  '[{"id":"A","text":"Nao, standby NAO recebe queries; serve apenas para failover. Para escalar leitura use Read Replicas"},{"id":"B","text":"Sim, distribui queries entre primary e standby"},{"id":"C","text":"Sim, mas so para Aurora"},{"id":"D","text":"Apenas para queries DDL"}]'::jsonb, 'A',
  '{
    "summary": "RDS Multi-AZ classico tem standby sincrono inacessivel para queries; existe apenas para failover automatico.",
    "whyCorrect": "Para escalar leitura, use Read Replicas (assincronos, podem ser cross-region).",
    "whyWrong": {
     "B": "Standby nao serve queries.",
     "C": "Aurora tem replicas para escala mas Multi-AZ classico nao.",
     "D": "Standby nao roda queries."
    },
    "keyConcept": "Multi-AZ = HA. Read Replica = escala de leitura.",
    "compareWith": [
     "RDS Multi-AZ DB Cluster (cluster com 2 readable standbys)",
     "Aurora cluster nativo"
    ],
    "realWorldContext": "Apps com muita leitura usam read replicas + cache.",
    "commonMistakes": "Confundir HA com escala. Multi-AZ resolve HA, nao throughput.",
    "tutorSeeds": [
     "Multi-AZ DB Cluster (novo)",
     "Aurora storage architecture"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["rds","multi-az","read-replica"]'::jsonb, 'ai-draft', 'active', now(), now()
)
