INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-070', 'aws-clf', 'Diferencas entre RDS Multi-AZ classico e Aurora Multi-AZ?',
  '[{"id":"A","text":"Sao iguais"},{"id":"B","text":"Aurora tem storage distribuido 6-way em 3 AZs, replicas podem servir leitura, failover ~30s; RDS classico tem standby unico sincrono dedicado a failover"},{"id":"C","text":"Aurora nao tem multi-AZ"},{"id":"D","text":"RDS classico e mais rapido em failover"}]'::jsonb, 'B',
  '{
    "summary": "Aurora replica storage 6x em 3 AZs (quorum-based) e ate 15 read replicas; RDS classico tem 1 standby sincrono.",
    "whyCorrect": "Aurora failover usa cluster endpoint e e mais rapido. Read Replicas Aurora podem ser promovidas.",
    "whyWrong": {
     "A": "Sao diferentes.",
     "C": "Aurora e nativamente multi-AZ.",
     "D": "Aurora costuma ser mais rapido no failover."
    },
    "keyConcept": "Aurora arquitetura cluster vs RDS instance+standby.",
    "compareWith": [
     "Aurora Global Database (cross-region 1s RPO)"
    ],
    "realWorldContext": "Workloads OLTP de alta escala preferem Aurora.",
    "commonMistakes": "Aplicar mesmos numeros (Multi-AZ classico) em Aurora.",
    "tutorSeeds": [
     "Aurora failover order",
     "Aurora Serverless v2"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'recall', '["rds","aurora","multi-az"]'::jsonb, 'ai-draft', 'active', now(), now()
)
