INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-072', 'aws-clf', 'Diferenca entre Aurora Serverless v1 e v2?',
  '[{"id":"A","text":"Sao iguais"},{"id":"B","text":"v2 e mais barato sempre"},{"id":"C","text":"v1 e mais novo"},{"id":"D","text":"v1 escala em saltos (pause/resume), latencia maior; v2 escala rapidamente em incrementos finos sem cold start, melhor para producao"}]'::jsonb, 'D',
  '{
    "summary": "Aurora Serverless v2 oferece scaling continuo e fino (segundos), suporta read replicas e features regulares Aurora; v1 e legacy com warm pools e pause.",
    "whyCorrect": "v2 e indicado para producao com variabilidade. v1 ainda tem use case para dev/test.",
    "whyWrong": {
     "A": "Sao distintos.",
     "B": "Depende do workload.",
     "C": "v2 e mais recente."
    },
    "keyConcept": "Aurora Serverless v2 = production-ready elastic compute.",
    "compareWith": [
     "Aurora provisioned cluster"
    ],
    "realWorldContext": "SaaS multi-tenant usa v2 para workloads variaveis.",
    "commonMistakes": "Usar v1 em producao moderna; v2 e recomendado.",
    "tutorSeeds": [
     "ACU = Aurora Capacity Unit",
     "Min/max ACU config"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["aurora","serverless"]'::jsonb, 'ai-draft', 'active', now(), now()
)
