INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-073', 'aws-clf', 'Diferenca principal entre On-Demand e Provisioned capacity modes no DynamoDB?',
  '[{"id":"A","text":"On-Demand: paga por request, escala automaticamente, sem capacity planning; Provisioned: define RCU/WCU, mais barato em workloads estaveis com auto scaling"},{"id":"B","text":"Sao iguais"},{"id":"C","text":"On-Demand e sempre mais barato"},{"id":"D","text":"Provisioned nao escala"}]'::jsonb, 'A',
  '{
    "summary": "On-Demand: pay-per-request, ideal para trafego imprevisivel; Provisioned: planeja RCU/WCU, mais economico em workloads previsiveis com auto scaling.",
    "whyCorrect": "On-Demand evita throttling em spikes mas custa mais por request. Provisioned com auto scaling acerta workloads estaveis.",
    "whyWrong": {
     "B": "Sao distintos.",
     "C": "On-Demand costuma ser mais caro em workload estavel.",
     "D": "Provisioned escala via auto scaling."
    },
    "keyConcept": "On-Demand = elasticidade total. Provisioned = custo otimo previsivel.",
    "compareWith": [
     "Reserved Capacity em Provisioned para desconto"
    ],
    "realWorldContext": "Apps com spikes (lancamento) usam On-Demand; depois migram para Provisioned ao estabilizar.",
    "commonMistakes": "Ficar em On-Demand permanente em workload estavel = caro.",
    "tutorSeeds": [
     "RCU/WCU calculation",
     "Reserved Capacity"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["dynamodb","capacity-mode"]'::jsonb, 'ai-draft', 'active', now(), now()
)
