INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-074', 'aws-clf', 'O que e DAX?',
  '[{"id":"A","text":"Variante de Redis"},{"id":"B","text":"DynamoDB Accelerator: cache in-memory write-through nativo da DynamoDB, latencia microssegundos"},{"id":"C","text":"Engine analitica"},{"id":"D","text":"Replicacao global"}]'::jsonb, 'B',
  '{
    "summary": "DAX e cache gerenciado dedicado a DynamoDB, oferecendo leituras em microssegundos sem mudar a API.",
    "whyCorrect": "Write-through cache; reads vao primeiro ao cache. Reduz custos de RCU e latencia.",
    "whyWrong": {
     "A": "DAX nao e Redis (apesar de filosofia parecida).",
     "C": "Nao e analitico.",
     "D": "Global Tables fazem replicacao."
    },
    "keyConcept": "DAX = cache especifico DynamoDB. Cluster com nodes.",
    "compareWith": [
     "ElastiCache Redis (manual cache-aside)"
    ],
    "realWorldContext": "Aplicacoes read-heavy DynamoDB usam DAX para reduzir custo e latencia.",
    "commonMistakes": "Usar DAX em write-heavy workload nao da o ganho esperado.",
    "tutorSeeds": [
     "Item cache vs Query cache",
     "DAX SDK"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["dynamodb","dax","cache"]'::jsonb, 'ai-draft', 'active', now(), now()
)
