INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-075', 'aws-clf', 'Diferenca principal entre ElastiCache for Redis e ElastiCache for Memcached?',
  '[{"id":"A","text":"Sao iguais"},{"id":"B","text":"Memcached suporta replicacao nativa"},{"id":"C","text":"Redis: persistencia opcional, replicacao, cluster mode, pub/sub, streams, transactions; Memcached: multi-thread, sharding por client, sem persistencia/replicacao"},{"id":"D","text":"Redis nao suporta cluster"}]'::jsonb, 'C',
  '{
    "summary": "Redis e mais rico (persistencia, replicacao, cluster, pub/sub). Memcached e mais simples (multi-thread, sharding client-side).",
    "whyCorrect": "Para cache rico/leaderboard/pub-sub use Redis. Para cache puramente efemero high-throughput simples, Memcached pode bastar.",
    "whyWrong": {
     "A": "Sao distintos.",
     "B": "Memcached nao replica nativamente.",
     "D": "Redis tem cluster mode."
    },
    "keyConcept": "Redis = data structures + persistencia. Memcached = simple memory cache.",
    "compareWith": [
     "MemoryDB for Redis: durability adicional"
    ],
    "realWorldContext": "Sessions/cache de DB usa Redis; cache de pagina simples pode usar Memcached.",
    "commonMistakes": "Escolher Memcached e precisar de pub/sub depois.",
    "tutorSeeds": [
     "MemoryDB vs ElastiCache",
     "Eviction policies"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["elasticache","redis","memcached"]'::jsonb, 'ai-draft', 'active', now(), now()
)
