INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-078', 'aws-clf', 'Uma instancia EC2 nao consegue alcancar o IMDS para pegar credenciais. Qual configuracao deve ser checada (alem de IAM role)?',
  '[{"id":"A","text":"Apenas Security Group"},{"id":"B","text":"Hop limit do IMDSv2 e se a aplicacao usa token PUT corretamente; tambem se IMDS esta habilitado"},{"id":"C","text":"NACL"},{"id":"D","text":"Route Table"}]'::jsonb, 'B',
  '{
    "summary": "IMDS roda em link-local 169.254.169.254 dentro da instancia; SG/NACL/Route nao afetam. Hop limit baixo (1) e IMDSv2 required podem causar falha em containers ou apps que nao implementam token.",
    "whyCorrect": "Containers em hosts EC2 podem precisar hop limit 2 para acessar IMDS via bridge. IMDSv2 required e nao implementado quebra apps.",
    "whyWrong": {
     "A": "SG nao filtra link-local IMDS.",
     "C": "NACL nao afeta IMDS.",
     "D": "Route table nao."
    },
    "keyConcept": "IMDS link-local nao e filtrado por rede VPC; problemas vem de hop limit e versao.",
    "compareWith": [
     "IRSA em EKS",
     "ECS task role"
    ],
    "realWorldContext": "Bug comum: container Docker em EC2 com IMDSv2 hop 1 nao consegue role.",
    "commonMistakes": "Tentar abrir SG para IMDS; nao faz sentido.",
    "tutorSeeds": [
     "Como migrar app para IMDSv2",
     "Hop limit recomendado em containers"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'troubleshoot', '["ec2","imds","troubleshoot"]'::jsonb, 'ai-draft', 'active', now(), now()
)
