INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-079', 'aws-clf', 'Uma equipe encontra alto custo de transferencia entre AZs em ALB+EC2. Qual otimizacao MAIS impacta?',
  '[{"id":"A","text":"Mover todas instancias para uma AZ unica e tolerar single point of failure"},{"id":"B","text":"Habilitar cross-zone em NLB sem analisar"},{"id":"C","text":"Garantir distribuicao balanceada de targets entre AZs e considerar AZ-local routing/algoritmos quando aplicavel; revisar uso de cross-zone load balancing especialmente em NLB"},{"id":"D","text":"Trocar ALB por CLB"}]'::jsonb, 'C',
  '{
    "summary": "Data transfer inter-AZ e cobrado; alinhar consumidores e provedores nas mesmas AZs quando possivel reduz custo, sem sacrificar HA.",
    "whyCorrect": "Equilibrar targets entre AZs e revisar configuracao cross-zone (especialmente em NLB onde cross-zone gera cobranca) reduz transfer entre AZs.",
    "whyWrong": {
     "A": "Sacrifica HA.",
     "B": "Habilitar cross-zone em NLB AUMENTA custo inter-AZ.",
     "D": "CLB e legacy."
    },
    "keyConcept": "Otimizar inter-AZ traffic preserva HA e reduz $.",
    "compareWith": [
     "Topology aware routing em service mesh"
    ],
    "realWorldContext": "Workloads pesados se beneficiam de affinity AZ + EFS One Zone seletivo.",
    "commonMistakes": "Ignorar custo inter-AZ ate fatura crescer.",
    "tutorSeeds": [
     "VPC Flow Logs por AZ",
     "Cost Explorer filter por usage type"
    ]
   }'::jsonb,
