INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v3-080', 'aws-clf', 'Uma carga Lambda esta com cold start alto e SLA estrito. Qual combinacao otimiza?',
  '[{"id":"A","text":"Aumentar timeout e memoria sem mais"},{"id":"B","text":"Mudar para Reserved Concurrency"},{"id":"C","text":"Aumentar /tmp"},{"id":"D","text":"Habilitar Provisioned Concurrency com auto scaling, escolher runtime moderno (e SnapStart se Java/Python/.NET), minimizar dependencias no package, usar ARM Graviton2 quando aplicavel"}]'::jsonb, 'D',
  '{
    "summary": "Cold start reduz com Provisioned Concurrency (pre-aquecidas), SnapStart, pacotes enxutos e runtimes otimizados; Graviton2 (arm64) pode reduzir custo/latencia.",
    "whyCorrect": "Combinacao ataca o cold start em multiplas frentes (provisionamento + runtime + pacote).",
    "whyWrong": {
     "A": "Memoria ajuda mas nao elimina cold start.",
     "B": "Reserved nao acelera.",
     "C": "/tmp nao tem relacao com cold start."
    },
    "keyConcept": "Cold start: Provisioned + SnapStart + pacote leve + Graviton.",
    "compareWith": [
     "Container images Lambda (cold start pode ser maior)"
    ],
    "realWorldContext": "APIs de pagamentos com SLA P99 usam Provisioned + SnapStart.",
    "commonMistakes": "Focar em uma so otimizacao; combinacao da o resultado.",
    "tutorSeeds": [
     "Lambda Power Tuning",
     "Graviton2 cost-perf"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["lambda","cold-start","performance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
