INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-005', 'aws-clf', 'Uma equipe precisa expor uma aplicação interna (rodando em VPC-A, em conta-A) para clientes em VPC-B (conta-B) sem fazer peering nem expor a aplicação na internet. Querem manter os clientes consumindo via DNS privado interno. Qual serviço atende?',
  '[{"id":"A","text":"AWS PrivateLink — publicar a aplicação como Endpoint Service e os clientes acessam via Interface Endpoint"},{"id":"B","text":"VPC Peering bidirecional entre VPC-A e VPC-B"},{"id":"C","text":"Transit Gateway com route tables compartilhadas"},{"id":"D","text":"Internet Gateway com Security Group restritivo"}]'::jsonb, 'A',
  '{
    "summary": "PrivateLink (Endpoint Service + Interface Endpoint) expõe serviço privadamente entre VPCs/contas, sem CIDR overlap.",
    "whyCorrect": "PrivateLink permite ao produtor publicar um Endpoint Service apontando para um NLB ou GWLB. Consumidores criam Interface Endpoints em suas VPCs, recebendo DNS privado e ENIs com IPs locais. Não exige roteamento entre VPCs, não importa se CIDRs colidem, e o tráfego nunca sai da rede AWS.",
    "whyWrong": {
     "B": "VPC Peering exige CIDRs sem overlap, expõe toda a VPC do outro lado (precisa SG/NACL), e não é escalável para muitos consumidores.",
     "C": "Transit Gateway conecta múltiplas VPCs mas também exige CIDR sem overlap e expõe redes inteiras — é over-architecture para expor 1 serviço.",
     "D": "Expor via IGW significa pôr na internet pública — viola o requisito de privado."
    },
    "keyConcept": "AWS PrivateLink — service-as-a-service entre VPCs/contas sem roteamento de rede",
    "compareWith": [
     "PrivateLink vs VPC Peering vs Transit Gateway",
     "Endpoint Service (producer) vs Interface Endpoint (consumer)"
    ],
    "realWorldContext": "Padrão SaaS interno na AWS: empresas publicam APIs internas via PrivateLink para que outras BUs consumam sem expor redes.",
    "commonMistakes": "Confundir PrivateLink (serviço-a-serviço) com VPC Peering (rede-a-rede). PrivateLink encapsula apenas o serviço.",
    "tutorSeeds": [
     "PrivateLink usa NLB ou ALB? Por quê?",
     "Como funciona DNS privado em Interface Endpoints?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["privatelink","endpoint-service","nlb","cross-account"]'::jsonb, 'ai-draft', 'active', now(), now()
)
