INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-006', 'aws-clf', 'Uma empresa tem VPC-A peered com VPC-B, e VPC-B peered com VPC-C. Uma instância na VPC-A tenta acessar instância na VPC-C. O que acontece?',
  '[{"id":"A","text":"Funciona — peering é transitivo na AWS"},{"id":"B","text":"Falha — VPC Peering NÃO é transitivo; para topologia hub-and-spoke use Transit Gateway"},{"id":"C","text":"Funciona, desde que a VPC-B tenha rotas dos dois peerings"},{"id":"D","text":"Funciona apenas se as três VPCs estiverem na mesma região"}]'::jsonb, 'B',
  '{
    "summary": "VPC Peering é NÃO-transitivo por design. Tráfego A→C via B não funciona.",
    "whyCorrect": "Cada peering é uma conexão ponto-a-ponto. A AWS não permite roteamento transitivo: VPC-A não pode usar VPC-B como hub para alcançar VPC-C, mesmo com rotas configuradas. Para hub-and-spoke é necessário Transit Gateway, que centraliza route tables e suporta transitivo.",
    "whyWrong": {
     "A": "Falso — peering é EXPLICITAMENTE não-transitivo. Essa é uma das pegadinhas mais comuns no exame.",
     "C": "Mesmo com rotas configuradas, AWS bloqueia a transitividade no nível da fabric. Não funciona.",
     "D": "Inter-region peering existe e funciona, mas a transitividade continua proibida independente da região."
    },
    "keyConcept": "VPC Peering — relação 1:1, sem transitividade. Para malha use TGW",
    "compareWith": [
     "VPC Peering vs Transit Gateway",
     "Hub-and-spoke vs full-mesh peering"
    ],
    "realWorldContext": "Cresce uma rede com 3-4 VPCs via peering; ao chegar em 5+ vira inviável (precisa N*(N-1)/2 peerings). Migra-se para TGW.",
    "commonMistakes": "Tentar usar VPC-B como ''roteador'' entre A e C com rotas manuais — não funciona, mesmo que a rota exista.",
    "tutorSeeds": [
     "Quantos peerings para conectar 10 VPCs full-mesh?",
     "Como o Transit Gateway resolve o problema da transitividade?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["vpc-peering","transit-gateway","transitive-routing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
