INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-007', 'aws-clf', 'Um banco conecta 40 VPCs (várias contas, várias regiões) num modelo de rede corporativa com roteamento centralizado, segmentação por route tables e propagação BGP de redes on-prem. Qual serviço AWS é a base dessa arquitetura?',
  '[{"id":"A","text":"VPC Peering em malha completa"},{"id":"B","text":"AWS PrivateLink centralizado"},{"id":"C","text":"AWS Transit Gateway com TGW route tables e attachments cross-region peering"},{"id":"D","text":"AWS Direct Connect Gateway"}]'::jsonb, 'C',
  '{
    "summary": "Transit Gateway é hub-and-spoke regional com route tables internas, attachments e suporte a inter-region peering.",
    "whyCorrect": "TGW é o serviço de roteamento centralizado da AWS. Suporta attachments para VPCs, VPNs, Direct Connect Gateway e outros TGWs (cross-region peering). Route tables internas permitem segmentação (ex: produção isolada de dev). Escala para milhares de VPCs e propaga BGP. É a base de uma ''AWS landing zone'' moderna.",
    "whyWrong": {
     "A": "40 VPCs em mesh = 40*39/2 = 780 peerings. Inviável de gerenciar e sem segmentação.",
     "B": "PrivateLink é para expor serviços, não para conectar redes inteiras.",
     "D": "Direct Connect Gateway é parte da solução (DX→TGW), mas sozinho não conecta as 40 VPCs entre si."
    },
    "keyConcept": "AWS Transit Gateway — hub regional para VPCs, VPNs, DX e outros TGWs",
    "compareWith": [
     "TGW vs VPC Peering full-mesh",
     "TGW Route Tables vs VPC Route Tables",
     "TGW Peering vs Cloud WAN"
    ],
    "realWorldContext": "TGW é o backbone da rede AWS na maioria das empresas com 10+ VPCs. Cobra por attachment-hora e por GB processado.",
    "commonMistakes": "Achar que TGW é multicast e roteamento sem configurar route tables. As route tables do TGW são CRÍTICAS — sem elas, attachments não se enxergam.",
    "tutorSeeds": [
     "Como funcionam TGW Route Tables vs Propagations vs Associations?",
     "Quando usar Cloud WAN em vez de TGW?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["transit-gateway","multi-vpc","bgp","landing-zone"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
