INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-008', 'aws-clf', 'Uma fintech precisa de link dedicado de 10 Gbps entre seu datacenter em São Paulo e a AWS, com latência estável e baixa para tráfego de market data. Não querem internet pública no caminho. Qual serviço?',
  '[{"id":"A","text":"Site-to-Site VPN com aceleração via Global Accelerator"},{"id":"B","text":"AWS PrivateLink cross-region"},{"id":"C","text":"VPC Peering com on-prem"},{"id":"D","text":"AWS Direct Connect — dedicated connection 10 Gbps via parceiro DX no PoP de São Paulo"}]'::jsonb, 'D',
  '{
    "summary": "Direct Connect oferece conexão física dedicada — 1, 10 ou 100 Gbps, baixa latência consistente, sem internet.",
    "whyCorrect": "DX dedicated connections são ports físicas (10G/100G) num PoP DX próximo ao datacenter, contratadas via parceiro de telecom. Garante latência baixa e estável e bandwidth dedicado. Suporta VIFs privados (acesso VPC via DX Gateway/TGW), públicos (acesso a serviços AWS públicos) e de trânsito (TGW).",
    "whyWrong": {
     "A": "Site-to-Site VPN passa por internet pública, latência variável. Global Accelerator é para tráfego de usuários finais, não cliente-AWS.",
     "B": "PrivateLink é entre VPCs, não para on-prem ↔ AWS.",
     "C": "Não existe ''VPC Peering com on-prem'' — peering é entre VPCs AWS."
    },
    "keyConcept": "AWS Direct Connect — link físico dedicado (1/10/100 Gbps) entre on-prem e AWS",
    "compareWith": [
     "DX dedicated vs hosted",
     "DX VIFs: public vs private vs transit",
     "DX vs Site-to-Site VPN"
    ],
    "realWorldContext": "Bancos, gov e grandes corporações usam DX. Sempre acompanhado de uma VPN como backup (DX não tem SLA de 100%).",
    "commonMistakes": "Achar que DX tem criptografia nativa — NÃO TEM (é camada 2). Para criptografar usa MACsec (DX dedicated 10/100G) ou IPsec sobre DX (VPN over DX).",
    "tutorSeeds": [
     "Direct Connect dedicated vs hosted — qual a diferença prática?",
     "Como criptografar tráfego sobre Direct Connect?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["direct-connect","hybrid","dedicated-connection","low-latency"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
