INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-009', 'aws-clf', 'Auditoria pergunta: ''O tráfego que passa por nosso Direct Connect é criptografado por padrão?''. Qual é a resposta correta?',
  '[{"id":"A","text":"Não — DX é camada 2 sem criptografia nativa. Para encrypt use MACsec (em DX dedicated 10/100G) ou IPsec sobre DX (VPN over DX)"},{"id":"B","text":"Sim, AWS criptografa todo tráfego DX automaticamente via TLS"},{"id":"C","text":"Sim, DX usa IPsec inline por padrão"},{"id":"D","text":"Sim, apenas em VIFs privados"}]'::jsonb, 'A',
  '{
    "summary": "Direct Connect NÃO criptografa por padrão. Use MACsec ou IPsec sobre DX.",
    "whyCorrect": "DX é uma conexão de camada 2 dedicada — o equivalente a uma ''cross-connect'' privada. Não há criptografia nativa do payload. Para atender compliance que exige encryption-in-transit, AWS oferece MACsec (IEEE 802.1AE, em DX dedicated 10G/100G nos PoPs suportados) ou rodar um túnel Site-to-Site VPN IPsec por cima do DX (chamado ''VPN over DX'' ou ''private VIF + VPN'').",
    "whyWrong": {
     "B": "Falso — não há TLS automático. TLS é aplicação (HTTPS), DX é rede.",
     "C": "DX não usa IPsec por padrão. IPsec é opcional sobre DX.",
     "D": "VIF privado também não criptografa por padrão."
    },
    "keyConcept": "Direct Connect — camada 2, sem criptografia nativa. MACsec ou IPsec sobre DX são opcionais",
    "compareWith": [
     "MACsec vs IPsec over DX",
     "DX inseguro vs DX + VPN encrypted"
    ],
    "realWorldContext": "Pergunta clássica de auditoria PCI/HIPAA. Resposta correta: ''usamos VPN over DX para encryption-in-transit''.",
    "commonMistakes": "Confundir ''tráfego não passa pela internet pública'' (verdadeiro em DX) com ''tráfego é criptografado'' (FALSO). Privacy ≠ encryption.",
    "tutorSeeds": [
     "Como funciona MACsec em Direct Connect?",
     "Qual o overhead de rodar VPN sobre DX?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["direct-connect","encryption","macsec","compliance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
