INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-010', 'aws-clf', 'Uma empresa precisa conectar 4 VPCs em 3 regiões diferentes a múltiplas Direct Connect connections em vários PoPs, com gerenciamento de rotas BGP centralizado. Qual serviço facilita essa associação entre DX e múltiplas VPCs/regiões?',
  '[{"id":"A","text":"VPC Peering inter-region"},{"id":"B","text":"AWS Direct Connect Gateway — permite associar DX a múltiplas VPCs em diferentes regiões e a TGWs"},{"id":"C","text":"AWS PrivateLink Global"},{"id":"D","text":"AWS Cloud Map"}]'::jsonb, 'B',
  '{
    "summary": "Direct Connect Gateway é um objeto global que associa múltiplos VIFs DX a múltiplas VPCs/TGWs em várias regiões.",
    "whyCorrect": "DX Gateway resolve duas dores: (1) associar uma DX connection a VPCs em regiões diferentes (uma DX no PoP-VA pode falar com VPC em us-west-2); (2) associar a Transit Gateways, multiplicando alcance. É um recurso global, sem custo extra (paga só pelo DX e pelo TGW).",
    "whyWrong": {
     "A": "VPC Peering inter-region conecta VPCs entre si, não tem a ver com DX.",
     "C": "''PrivateLink Global'' não é um serviço.",
     "D": "Cloud Map é service discovery para apps, não roteamento de rede."
    },
    "keyConcept": "AWS Direct Connect Gateway — objeto global associa DX a múltiplas VPCs/TGWs em qualquer região",
    "compareWith": [
     "DX Gateway vs Transit VIF + TGW",
     "Private VIF + DX Gateway vs Transit VIF + DX Gateway"
    ],
    "realWorldContext": "Padrão em empresas com presença multi-region: 1-2 DX redundantes + 1 DX Gateway + TGWs por região.",
    "commonMistakes": "Achar que precisa pagar DX em cada região — não. Um DX Gateway permite reusar DX entre regiões via SiteLink (com cobrança específica).",
    "tutorSeeds": [
     "O que é AWS SiteLink em Direct Connect?",
     "Como Transit VIF + DX Gateway difere de Private VIF + DX Gateway?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["direct-connect-gateway","multi-region","transit-gateway","hybrid"]'::jsonb, 'ai-draft', 'active', now(), now()
)
