INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-011', 'aws-clf', 'Uma corporação quer conectar 12 escritórios remotos à AWS, mas o tráfego não justifica Direct Connect dedicado. Eles precisam de túneis IPsec criptografados e fáceis de provisionar. Qual serviço?',
  '[{"id":"A","text":"AWS Client VPN com OpenVPN"},{"id":"B","text":"AWS PrivateLink em cada filial"},{"id":"C","text":"AWS Site-to-Site VPN com customer gateway IPsec em cada escritório"},{"id":"D","text":"Direct Connect hosted de 50 Mbps em cada escritório"}]'::jsonb, 'C',
  '{
    "summary": "Site-to-Site VPN cria túneis IPsec gerenciados entre on-prem (customer gateway) e Virtual Private Gateway ou TGW.",
    "whyCorrect": "Site-to-Site VPN é o serviço padrão para rede-a-rede sobre internet pública. Cada filial configura um Customer Gateway (CGW — pode ser um Cisco, Fortinet, pfSense, etc.) e estabelece 2 túneis IPsec redundantes ao VGW (Virtual Private Gateway) anexado à VPC, ou ao Transit Gateway. Fácil de provisionar via console.",
    "whyWrong": {
     "A": "Client VPN é para usuários finais (laptops) conectarem-se à AWS — não para conectar escritórios inteiros.",
     "B": "PrivateLink é entre VPCs/serviços AWS, não para WAN externa.",
     "D": "DX hosted de 50Mbps em 12 escritórios é caro e demorado — overkill se tráfego não justifica."
    },
    "keyConcept": "Site-to-Site VPN — túneis IPsec gerenciados, network-to-network",
    "compareWith": [
     "Site-to-Site VPN (rede ↔ rede) vs Client VPN (usuário ↔ rede)",
     "VPN over internet vs Direct Connect"
    ],
    "realWorldContext": "VPN é a opção mais comum para conectar filiais à AWS. Empresas grandes combinam: DX nas matrizes + VPN nas filiais.",
    "commonMistakes": "Confundir Site-to-Site VPN com Client VPN. Site-to-Site = sites; Client = laptops.",
    "tutorSeeds": [
     "Quantos túneis IPsec o Site-to-Site VPN cria por VPN connection?",
     "VPN pode terminar diretamente no Transit Gateway?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["site-to-site-vpn","ipsec","hybrid","vpg"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
