INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-012', 'aws-clf', 'Funcionários remotos precisam acessar recursos privados na VPC corporativa a partir de laptops, com autenticação por SAML/AD e túneis criptografados. Qual serviço AWS é o adequado?',
  '[{"id":"A","text":"AWS Site-to-Site VPN com customer gateway em cada laptop"},{"id":"B","text":"AWS Direct Connect Client"},{"id":"C","text":"Amazon WorkSpaces"},{"id":"D","text":"AWS Client VPN — endpoint OpenVPN-compatible gerenciado, integra com AD/SAML/MFA"}]'::jsonb, 'D',
  '{
    "summary": "Client VPN é VPN para usuários finais — clientes OpenVPN em laptops/mobile conectam a um endpoint gerenciado.",
    "whyCorrect": "AWS Client VPN cria um endpoint gerenciado que aceita conexões OpenVPN. Autenticação suporta certificados mútuos, AD Connector, Federated SAML (IdP), e MFA. Após conectar, o usuário recebe IP da subnet associada e acessa recursos privados conforme regras de autorização.",
    "whyWrong": {
     "A": "Site-to-Site VPN não é para laptops individuais — é rede-a-rede.",
     "B": "''Direct Connect Client'' não existe.",
     "C": "WorkSpaces é desktop virtual (VDI), não VPN. Pode ser usado em conjunto, mas não é a resposta à pergunta de VPN."
    },
    "keyConcept": "AWS Client VPN — VPN gerenciada para usuários finais (laptops/mobile)",
    "compareWith": [
     "Client VPN vs Site-to-Site VPN",
     "Client VPN vs SSM Session Manager (para EC2)"
    ],
    "realWorldContext": "Padrão em empresas que adotaram BYOD e remote-first. Pricing: $/hora por endpoint ativo + $/hora por conexão.",
    "commonMistakes": "Para acessar UMA instância EC2 prefira SSM Session Manager (sem VPN). Client VPN é quando o usuário precisa acessar a rede toda.",
    "tutorSeeds": [
     "Quais métodos de autenticação Client VPN suporta?",
     "Como split-tunnel funciona em Client VPN?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["client-vpn","openvpn","remote-access","saml"]'::jsonb, 'ai-draft', 'active', now(), now()
)
