INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-013', 'aws-clf', 'Um arquiteto desenha uma VPC com CIDR 10.0.0.0/16 e precisa criar 6 subnets (2 públicas + 2 privadas + 2 de DB). Ele propõe usar CIDR sobrepostos com outras VPCs corporativas. Qual o impacto desse design?',
  '[{"id":"A","text":"Cria conflitos: VPC Peering e Transit Gateway exigem CIDRs sem overlap; PrivateLink contorna mas é caso a caso"},{"id":"B","text":"Não há impacto, AWS resolve overlap via NAT"},{"id":"C","text":"Funciona em qualquer cenário, AWS faz proxy ARP"},{"id":"D","text":"Causa apenas problemas de DNS, não de roteamento"}]'::jsonb, 'A',
  '{
    "summary": "CIDRs sobrepostos quebram VPC Peering e Transit Gateway. PrivateLink é a saída em alguns casos pontuais.",
    "whyCorrect": "AWS não faz NAT entre VPCs. Se VPC-A usa 10.0.0.0/16 e VPC-B também, peering simplesmente não roteia (rota ambígua). TGW idem. Boa prática: planejar CIDRs globalmente (ex: A=10.10/16, B=10.20/16, C=10.30/16) antes de criar VPCs. PrivateLink expõe apenas serviços (não rede), então pode contornar overlaps em casos específicos.",
    "whyWrong": {
     "B": "AWS não resolve overlap automaticamente — não há NAT entre VPCs.",
     "C": "Não há proxy ARP entre VPCs.",
     "D": "O problema é de ROTEAMENTO, não só de DNS."
    },
    "keyConcept": "VPC CIDR planning — overlap quebra Peering e TGW",
    "compareWith": [
     "RFC1918 (10/8, 172.16/12, 192.168/16) ranges",
     "Secondary CIDR per VPC"
    ],
    "realWorldContext": "Empresas que cresceram organicamente quase sempre têm overlap de CIDR. Migração para 10.x/16 segmentado é projeto de muitos meses.",
    "commonMistakes": "Criar todas as VPCs com 10.0.0.0/16 default — gera problemas futuros. Planejar IPAM com Amazon VPC IP Address Manager evita isso.",
    "tutorSeeds": [
     "Como o AWS VPC IPAM ajuda no planejamento de CIDRs?",
     "Posso ter secondary CIDRs em uma VPC?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["vpc","cidr","ipam","network-design"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
