INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-014', 'aws-clf', 'Uma aplicação IPv6 em subnet privada precisa fazer chamadas para APIs externas IPv6 sem aceitar conexões inbound da internet. Qual é o equivalente de NAT Gateway para IPv6?',
  '[{"id":"A","text":"NAT Gateway IPv6 mode"},{"id":"B","text":"Egress-only Internet Gateway (EIGW) — IGW especial que permite só tráfego de saída IPv6"},{"id":"C","text":"Internet Gateway com Security Group restritivo"},{"id":"D","text":"IPv6 não suporta tráfego outbound em subnet privada"}]'::jsonb, 'B',
  '{
    "summary": "Egress-only IGW é o equivalente IPv6 de NAT GW para outbound-only.",
    "whyCorrect": "IPv6 não tem NAT (todo endereço é roteável). Para emular semântica ''outbound-only'', AWS criou o Egress-only IGW: anexa-se à VPC e adiciona-se rota ::/0 → EIGW nas subnets privadas IPv6. Permite respostas mas bloqueia conexões iniciadas da internet — sem fazer NAT.",
    "whyWrong": {
     "A": "NAT Gateway só suporta IPv4 — não há NAT IPv6 na AWS.",
     "C": "IGW + SG funciona mas exige cuidado: o IGW expõe a subnet para internet inbound (precisa SG/NACL bloqueando). EIGW é mais simples e seguro.",
     "D": "Falso — suporta sim, via EIGW."
    },
    "keyConcept": "Egress-only Internet Gateway — outbound-only IPv6",
    "compareWith": [
     "EIGW (IPv6) vs NAT Gateway (IPv4)",
     "EIGW vs IGW"
    ],
    "realWorldContext": "Apps dual-stack modernas combinam NAT GW (IPv4 saída) + EIGW (IPv6 saída) na mesma route table.",
    "commonMistakes": "Tentar pôr NAT Gateway no caminho de IPv6 — não funciona.",
    "tutorSeeds": [
     "Por que IPv6 não tem NAT?",
     "Como configurar dual-stack na VPC?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'recall', '["ipv6","egress-only-igw","vpc","nat"]'::jsonb, 'ai-draft', 'active', now(), now()
)
