INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-015', 'aws-clf', 'Uma equipe precisa decidir entre VPC Endpoint Gateway e VPC Endpoint Interface para acessar o S3 a partir de subnet privada. Quais são as diferenças de custo e implementação?',
  '[{"id":"A","text":"Os dois são gratuitos e funcionam via DNS apenas"},{"id":"B","text":"Endpoint Gateway é pago e Endpoint Interface é grátis"},{"id":"C","text":"Endpoint Gateway: gratuito, via route table, exclusivo S3/DynamoDB. Endpoint Interface (PrivateLink): pago ($/hora + $/GB), via ENI com DNS privado, suporta quase todos os serviços"},{"id":"D","text":"Ambos exigem NAT Gateway por trás"}]'::jsonb, 'C',
  '{
    "summary": "Gateway: grátis, route table, S3/DynamoDB. Interface (PrivateLink): pago, ENI, maioria dos serviços.",
    "whyCorrect": "Endpoint Gateway entrou em 2015 só para S3 e DynamoDB — sem custo extra, opera via prefix list na route table. Endpoint Interface (introduzido pelo PrivateLink) cria uma ENI na subnet com IP privado e DNS privado, suporta SQS, SNS, KMS, Secrets Manager, ECR, etc., e custa ~$0,01/hora por AZ por endpoint + ~$0,01/GB processado.",
    "whyWrong": {
     "A": "Falso — Interface NÃO é gratuito.",
     "B": "Invertido.",
     "D": "Ambos eliminam a necessidade de NAT GW para chamar o serviço respectivo."
    },
    "keyConcept": "VPC Endpoint Gateway (S3/DDB, free) vs Interface/PrivateLink (paid, broad)",
    "compareWith": [
     "Gateway endpoint vs Interface endpoint",
     "PrivateLink billing"
    ],
    "realWorldContext": "FinOps: usar Gateway Endpoint para S3 economiza milhares de dólares/mês que iriam via NAT GW.",
    "commonMistakes": "Esquecer que S3 agora também suporta Interface Endpoint (PrivateLink) — útil quando se precisa acessar S3 de on-prem via DX. Mas para acesso dentro da VPC, Gateway continua sendo a opção econômica.",
    "tutorSeeds": [
     "Quando usar S3 Interface Endpoint em vez de Gateway?",
     "Quanto custa um Interface Endpoint multi-AZ?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["vpc-endpoint","privatelink","s3","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()
)
