INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-016', 'aws-clf', 'Uma empresa precisa de uma rede global multi-region com policy-based routing, monitoramento centralizado e segmentação por SD-WAN, gerenciada como um único objeto. Qual serviço AWS oferece isso?',
  '[{"id":"A","text":"Múltiplos Transit Gateways com peering manual"},{"id":"B","text":"AWS Global Accelerator"},{"id":"C","text":"Route 53 Resolver Endpoints"},{"id":"D","text":"AWS Cloud WAN — gerencia rede global como um único objeto com policy-as-code"}]'::jsonb, 'D',
  '{
    "summary": "AWS Cloud WAN é um serviço de WAN global gerenciado, sucessor lógico de muitos TGWs interconectados.",
    "whyCorrect": "Cloud WAN unifica conectividade entre VPCs, branches (VPN/SD-WAN), DX e regiões num único ''core network'' com policy declarativa JSON. Substitui o trabalho manual de configurar dezenas de TGWs, peerings e route tables para empresas globais.",
    "whyWrong": {
     "A": "Funciona mas requer muito setup manual; Cloud WAN abstrai isso.",
     "B": "Global Accelerator é para acelerar tráfego de usuários finais (TCP/UDP via Anycast), não para WAN corporativa.",
     "C": "R53 Resolver Endpoints é DNS, não conectividade de rede."
    },
    "keyConcept": "AWS Cloud WAN — global network managed-as-code (policy JSON)",
    "compareWith": [
     "Cloud WAN vs Transit Gateway",
     "Cloud WAN vs SD-WAN appliance"
    ],
    "realWorldContext": "Cloud WAN é a oferta moderna da AWS para empresas globais com 20+ regiões/branches. Reduz complexidade operacional vs TGW.",
    "commonMistakes": "Achar que substitui TGW na hora — TGW continua válido para regional. Cloud WAN é melhor quando a escala é global.",
    "tutorSeeds": [
     "Como Cloud WAN integra com SD-WAN de terceiros (Cisco, VMware)?",
     "Quando migrar de TGW para Cloud WAN faz sentido?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'recall', '["cloud-wan","global-network","sd-wan","policy-as-code"]'::jsonb, 'ai-draft', 'active', now(), now()
)
