INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-017', 'aws-clf', 'Uma aplicação web globalmente distribuída precisa de cache HTTP/HTTPS na borda (próximo aos usuários) para reduzir latência e descarregar tráfego do origin. Qual serviço AWS atende?',
  '[{"id":"A","text":"Amazon CloudFront — CDN com 600+ edge locations e cache configurável"},{"id":"B","text":"AWS Global Accelerator com cache policy"},{"id":"C","text":"AWS Direct Connect com hot caching"},{"id":"D","text":"Amazon Route 53 com edge caching"}]'::jsonb, 'A',
  '{
    "summary": "CloudFront é a CDN da AWS — cache HTTP/HTTPS distribuído em 600+ PoPs globais.",
    "whyCorrect": "CloudFront é a Content Delivery Network: distribui conteúdo via edge locations próximas aos usuários, com cache configurável por behavior (caminho/método), suporte a origin S3/ALB/qualquer HTTP, signed URLs/cookies, Field-level encryption, Lambda@Edge e CloudFront Functions.",
    "whyWrong": {
     "B": "Global Accelerator NÃO faz cache. Roteia TCP/UDP via Anycast IPs pelo backbone AWS — acelera, mas não cacheia.",
     "C": "DX é conexão dedicada on-prem-AWS, sem cache.",
     "D": "Route 53 é DNS — não cacheia conteúdo HTTP."
    },
    "keyConcept": "Amazon CloudFront — CDN HTTP/HTTPS com cache na edge",
    "compareWith": [
     "CloudFront vs Global Accelerator (cache HTTP vs roteamento TCP/UDP)",
     "CloudFront vs S3 Transfer Acceleration"
    ],
    "realWorldContext": "CDN é peça obrigatória de qualquer site/app globalmente acessado. CloudFront integra natural com S3, ALB e Lambda@Edge.",
    "commonMistakes": "Confundir CloudFront com Global Accelerator — são distintos. CF é HTTP cache; GA é TCP/UDP routing.",
    "tutorSeeds": [
     "Como funciona Lambda@Edge vs CloudFront Functions?",
     "O que são cache policies e origin request policies?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["cloudfront","cdn","cache","edge"]'::jsonb, 'ai-draft', 'active', now(), now()
)
