INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-018', 'aws-clf', 'Um SaaS B2B oferece API TCP customizada (jogos, voz, IoT MQTT) acessada globalmente, e precisa de IPs fixos Anycast + roteamento pelo backbone AWS para reduzir latência. NÃO precisa de cache HTTP. Qual serviço?',
  '[{"id":"A","text":"CloudFront com behavior TCP"},{"id":"B","text":"AWS Global Accelerator — 2 IPs Anycast estáticos, roteamento via backbone AWS, suporta TCP/UDP"},{"id":"C","text":"Route 53 com routing policy latency"},{"id":"D","text":"Application Load Balancer global"}]'::jsonb, 'B',
  '{
    "summary": "Global Accelerator fornece IPs Anycast estáticos e direciona tráfego TCP/UDP pelo backbone AWS para o endpoint mais próximo.",
    "whyCorrect": "Global Accelerator é um serviço de rede que provê dois IPs Anycast globais (anunciados em todos os PoPs AWS). O tráfego entra no PoP mais próximo do usuário e viaja pelo backbone privado AWS até o endpoint regional (ALB/NLB/EC2/EIP). Reduz latência ~30-60% em conexões intercontinentais. Suporta TCP/UDP, ideal para jogos, voz, MQTT.",
    "whyWrong": {
     "A": "CloudFront só faz HTTP/HTTPS, não TCP/UDP genérico.",
     "C": "Route 53 latency apenas decide IP via DNS — não rotea pelo backbone AWS.",
     "D": "ALB não é global — é regional por design."
    },
    "keyConcept": "AWS Global Accelerator — IPs Anycast fixos + roteamento via backbone AWS para TCP/UDP",
    "compareWith": [
     "Global Accelerator (TCP/UDP, network) vs CloudFront (HTTP, cache)",
     "Anycast vs DNS-based routing"
    ],
    "realWorldContext": "Usado por empresas de gaming (Riot, Epic), VoIP (Zoom), IoT. Cobrança fixa por accelerator + por GB processado.",
    "commonMistakes": "Achar que Global Accelerator é CDN — ele NÃO cacheia conteúdo. Apenas roteia.",
    "tutorSeeds": [
     "Como Anycast funciona no Global Accelerator?",
     "Posso combinar Global Accelerator com CloudFront?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["global-accelerator","anycast","tcp-udp","backbone"]'::jsonb, 'ai-draft', 'active', now(), now()
)
