INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-020', 'aws-clf', 'Uma empresa quer rotear usuários para o endpoint AWS com a menor latência. Qual routing policy do Route 53 atende?',
  '[{"id":"A","text":"Simple routing"},{"id":"B","text":"Geolocation routing"},{"id":"C","text":"Failover routing"},{"id":"D","text":"Latency-based routing — Route 53 retorna o record do region mais próximo ao usuário em latência"}]'::jsonb, 'D',
  '{
    "summary": "Latency-based routing usa medições internas AWS para rotear ao region de menor latência.",
    "whyCorrect": "Latency-based routing usa dados de latência que AWS coleta continuamente entre usuários (resolvers) e regiões. Configura-se múltiplos records (um por region) com a mesma policy e Route 53 escolhe o region de menor latência para cada query. Diferente de Geolocation, considera latência real, não localização geográfica.",
    "whyWrong": {
     "A": "Simple routing retorna sempre o mesmo valor sem decisão.",
     "B": "Geolocation roteia por país/continente (não por latência medida).",
     "C": "Failover é ativo-passivo (primary-secondary com health check), não otimização de latência."
    },
    "keyConcept": "Route 53 routing policies — latency-based usa latência medida AWS",
    "compareWith": [
     "Simple vs Weighted vs Latency vs Failover vs Geolocation vs Geoproximity vs Multi-value",
     "Latency vs Geoproximity"
    ],
    "realWorldContext": "Padrão em apps multi-region: latency policy nos endpoints regionais, ALB/NLB por trás.",
    "commonMistakes": "Confundir Latency com Geolocation. Geolocation é por país; Latency é por latência medida.",
    "tutorSeeds": [
     "Qual a diferença entre Geolocation e Geoproximity?",
     "Como Multi-value answer routing funciona?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["route-53","latency-routing","multi-region"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
