INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-021', 'aws-clf', 'Uma equipe configura CloudFront para distribuir um site SPA. Eles tentam anexar um certificado ACM gerado em us-east-2 (Ohio). CloudFront rejeita. Qual é a regra?',
  '[{"id":"A","text":"Certificados ACM para CloudFront DEVEM estar em us-east-1 (N. Virginia), porque CloudFront é serviço global gerenciado dessa região"},{"id":"B","text":"ACM precisa estar na mesma região do origin S3"},{"id":"C","text":"CloudFront aceita ACM de qualquer região, basta replicar"},{"id":"D","text":"ACM é proibido em CloudFront — só certificados auto-assinados"}]'::jsonb, 'A',
  '{
    "summary": "ACM em us-east-1 é OBRIGATÓRIO para CloudFront.",
    "whyCorrect": "CloudFront é um serviço global, mas seu controle reside em us-east-1. Qualquer certificado ACM consumido pelo CloudFront precisa estar emitido nessa região. Para ALB/NLB regionais, o ACM precisa estar na mesma região do balancer. Para API Gateway edge-optimized também é us-east-1.",
    "whyWrong": {
     "B": "Origin pode ser em qualquer lugar. O ACM é amarrado ao CloudFront, não ao origin.",
     "C": "ACM não replica entre regiões — você precisa emitir explicitamente em us-east-1.",
     "D": "ACM é totalmente suportado em CloudFront."
    },
    "keyConcept": "CloudFront — ACM deve estar em us-east-1 (N. Virginia)",
    "compareWith": [
     "ACM us-east-1 (CloudFront) vs ACM regional (ALB/NLB)",
     "Edge-optimized vs regional API Gateway"
    ],
    "realWorldContext": "Erro frequente em primeiros deploys de CloudFront. Sempre emitir ACM em us-east-1 quando o destino é CF.",
    "commonMistakes": "Achar que ACM é global como o CloudFront — ACM é regional sempre.",
    "tutorSeeds": [
     "API Gateway regional usa ACM de qual região?",
     "Como funciona DNS validation no ACM?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'troubleshoot', '["cloudfront","acm","tls","us-east-1"]'::jsonb, 'ai-draft', 'active', now(), now()
)
