INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-022', 'aws-clf', 'Em CloudFront, qual é o mecanismo MODERNO recomendado para restringir acesso ao bucket S3 origem, garantindo que apenas o CloudFront possa ler os objetos?',
  '[{"id":"A","text":"Origin Access Identity (OAI) — única forma suportada"},{"id":"B","text":"Origin Access Control (OAC) — sucessor do OAI, suporta SSE-KMS e regiões novas, recomendado pela AWS"},{"id":"C","text":"Tornar o bucket público com bucket policy permissiva"},{"id":"D","text":"Configurar IAM role na distribution"}]'::jsonb, 'B',
  '{
    "summary": "OAC (Origin Access Control) é o sucessor de OAI — recomendado pela AWS.",
    "whyCorrect": "OAI foi a versão antiga (2014). OAC, lançado em 2022, suporta SSE-KMS, regiões opt-in (Bahrain, HK etc.) e usa SigV4 — é a recomendação atual para qualquer distribution nova. Configura-se uma OAC, anexa ao origin S3, e adiciona bucket policy permitindo o CloudFront via AWS:SourceArn.",
    "whyWrong": {
     "A": "OAI ainda funciona mas é legacy. Para distribuições novas, AWS recomenda OAC.",
     "C": "Bucket público viola o requisito de ''apenas CloudFront pode ler''.",
     "D": "Distribution não assume IAM role — usa identidade de origem (OAC/OAI)."
    },
    "keyConcept": "CloudFront — OAC sucede OAI; ambos restringem leitura do S3 ao CF apenas",
    "compareWith": [
     "OAC vs OAI",
     "OAC + SSE-KMS"
    ],
    "realWorldContext": "Boa prática 2025+: usar OAC. Em pipelines de IaC, o módulo CDK/Terraform já default para OAC.",
    "commonMistakes": "Continuar usando OAI em novos projetos por inércia. OAC tem features que OAI não tem (SSE-KMS).",
    "tutorSeeds": [
     "Como o OAC suporta SSE-KMS no S3?",
     "Como migrar de OAI para OAC sem downtime?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["cloudfront","oac","oai","s3","security"]'::jsonb, 'ai-draft', 'active', now(), now()
)
