INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-023', 'aws-clf', 'Uma empresa precisa distribuir vídeos privados onde cada usuário recebe acesso a múltiplos arquivos (vários segmentos HLS) por período limitado, sem precisar gerar URL para cada segmento. Qual recurso do CloudFront atende?',
  '[{"id":"A","text":"Signed URLs — uma URL assinada por arquivo"},{"id":"B","text":"Lambda@Edge basic auth"},{"id":"C","text":"Signed Cookies — cookies assinados que autorizam acesso a múltiplos arquivos sob um path policy"},{"id":"D","text":"Field-level encryption"}]'::jsonb, 'C',
  '{
    "summary": "Signed Cookies autorizam acesso a múltiplos arquivos sob policy. Signed URLs servem 1 arquivo por URL.",
    "whyCorrect": "CloudFront oferece Signed URLs (1 URL por objeto) e Signed Cookies (cookies enviados em todas as requisições subsequentes, autorizando vários arquivos sob um policy statement com path patterns como /videos/episode1/*). Para HLS, onde uma playlist referencia dezenas de segmentos, cookies são muito mais práticos.",
    "whyWrong": {
     "A": "Signed URL exige URL única por arquivo — não funciona para HLS com 100+ segmentos.",
     "B": "Lambda@Edge basic auth é HTTP basic, sem time-bound nem policy de path.",
     "D": "Field-level encryption protege campos POST (CPF, CC), não autoriza acesso a arquivos."
    },
    "keyConcept": "CloudFront — Signed URLs (1 file) vs Signed Cookies (multiple files via policy)",
    "compareWith": [
     "Signed URLs vs Signed Cookies",
     "Canned policy vs Custom policy"
    ],
    "realWorldContext": "Padrão em streaming (Netflix-like): signed cookies + path /content/{user_id}/*.",
    "commonMistakes": "Tentar gerar 200 signed URLs para uma playlist HLS — overhead absurdo. Cookies resolvem.",
    "tutorSeeds": [
     "Como funciona o trusted key group em CloudFront?",
     "Canned vs custom policy nos signed URLs?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["cloudfront","signed-cookies","drm","streaming"]'::jsonb, 'ai-draft', 'active', now(), now()
)
