INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-024', 'aws-clf', 'Uma equipe DevOps quer rodar containers Docker sem precisar provisionar, escalar ou manter instâncias EC2 (sem se preocupar com host). Qual launch type do ECS é a escolha?',
  '[{"id":"A","text":"ECS on EC2 launch type"},{"id":"B","text":"ECS Anywhere"},{"id":"C","text":"EKS managed nodes"},{"id":"D","text":"ECS Fargate launch type — serverless containers, AWS gerencia o host"}]'::jsonb, 'D',
  '{
    "summary": "Fargate elimina a gestão de EC2 hosts — você paga por vCPU/memória que o container usa.",
    "whyCorrect": "Fargate é o launch type serverless do ECS (e do EKS). Você define a task definition com CPU/memória, AWS provisiona a infra invisível. Sem patches de OS, sem capacidade reservada, sem cluster autoscaling de EC2. Cobra por segundo de vCPU/RAM usado pelo task.",
    "whyWrong": {
     "A": "EC2 launch type exige você gerenciar EC2 hosts (AMI, patching, autoscaling).",
     "B": "ECS Anywhere é para rodar tasks em hardware on-prem do cliente — exige você gerenciar o host.",
     "C": "EKS managed nodes ainda são EC2 — você não gerencia OS mas a capacidade é cluster-baseada."
    },
    "keyConcept": "ECS Fargate — serverless containers (sem gestão de EC2 hosts)",
    "compareWith": [
     "Fargate vs EC2 launch type ECS",
     "Fargate (containers) vs Lambda (functions)"
    ],
    "realWorldContext": "Default para apps stateless modernas. Custo por hora maior que EC2 reservado, mas elimina gestão.",
    "commonMistakes": "Achar que Fargate é sempre mais barato — para workloads contínuos e previsíveis, EC2 reservado pode ser 50-70% mais barato.",
    "tutorSeeds": [
     "Quando Fargate é mais caro que EC2 ECS?",
     "Fargate Spot existe? Como funciona?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["ecs","fargate","serverless-containers"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
