INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-025', 'aws-clf', 'No Amazon ECS, qual a diferença entre task definition e service?',
  '[{"id":"A","text":"Task definition é o ''blueprint'' (imagens, CPU, RAM, env vars, networking); Service garante que N tasks dessa definition estejam rodando + load balancer + autoscaling"},{"id":"B","text":"São sinônimos"},{"id":"C","text":"Service é o blueprint; Task definition gerencia replicas"},{"id":"D","text":"Task definition é só para Fargate; Service só para EC2"}]'::jsonb, 'A',
  '{
    "summary": "Task Definition é a especificação (JSON). Service é o controlador que mantém N replicas.",
    "whyCorrect": "Task Definition é como um pod manifest no Kubernetes: define container images, vCPU, memória, port mappings, networking mode, IAM role da task, etc. Service usa essa definition + N (desired count) e mantém esse número de tasks rodando, com integração a ALB/NLB e Application Auto Scaling.",
    "whyWrong": {
     "B": "São conceitos distintos.",
     "C": "Invertido.",
     "D": "Falso — ambos servem para qualquer launch type."
    },
    "keyConcept": "ECS — Task Definition (spec) vs Service (controller)",
    "compareWith": [
     "Task Definition vs Service vs Task (instance)",
     "Service vs Standalone task (one-shot)"
    ],
    "realWorldContext": "Equivalente conceitual: Task Def = Pod Spec, Service ECS = Deployment K8s.",
    "commonMistakes": "Rodar tasks one-shot (standalone) achando que continuam rodando após crash — só Service faz replacement automático.",
    "tutorSeeds": [
     "Qual a diferença entre Service e Standalone Task?",
     "Como funciona Service Discovery (Cloud Map) no ECS?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["ecs","task-definition","service","containers"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
