INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-026', 'aws-clf', 'Uma equipe quer usar Kubernetes na AWS sem gerenciar o control plane (etcd, API server, scheduler). Qual serviço atende?',
  '[{"id":"A","text":"ECS Fargate"},{"id":"B","text":"Amazon EKS — control plane Kubernetes totalmente gerenciado pela AWS ($0,10/hora por cluster)"},{"id":"C","text":"AWS Batch"},{"id":"D","text":"AWS App Runner"}]'::jsonb, 'B',
  '{
    "summary": "EKS gerencia o control plane Kubernetes. Você só se preocupa com worker nodes (ou Fargate).",
    "whyCorrect": "Amazon EKS provê Kubernetes upstream certificado, com control plane (API server, etcd, controller-manager, scheduler) totalmente managed pela AWS, distribuído em 3 AZs. Custa $0,10/hora por cluster. Worker nodes podem ser EC2 (managed node groups) ou Fargate (Fargate profiles).",
    "whyWrong": {
     "A": "ECS Fargate é AWS-proprietary, não Kubernetes.",
     "C": "AWS Batch é orquestração de jobs batch (queue + scheduling), não K8s.",
     "D": "App Runner é PaaS para HTTP, não K8s."
    },
    "keyConcept": "Amazon EKS — managed Kubernetes control plane",
    "compareWith": [
     "EKS vs ECS (K8s vs proprietary)",
     "EKS managed nodes vs Fargate profiles vs self-managed nodes"
    ],
    "realWorldContext": "Escolha de empresas que querem portabilidade (multi-cloud K8s) ou que já têm Helm charts e operators consolidados.",
    "commonMistakes": "Achar que EKS gerencia tudo — control plane sim, mas worker nodes/Fargate precisam configurar IAM, networking, addons (CoreDNS, kube-proxy, VPC CNI).",
    "tutorSeeds": [
     "O que é IRSA e por que é importante?",
     "EKS Anywhere vs EKS Distro — qual a diferença?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["eks","kubernetes","managed-control-plane"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
  stem          = EXCLUDED.stem,
