INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-028', 'aws-clf', 'Um desenvolvedor quer subir uma aplicação container (ou código fonte) e ter HTTPS, auto-scaling, deploys e domínio sem configurar load balancer, ECS, EKS ou Beanstalk. Qual serviço PaaS de containers atende?',
  '[{"id":"A","text":"Elastic Beanstalk"},{"id":"B","text":"Amazon Lightsail Containers"},{"id":"C","text":"ECS Fargate manual"},{"id":"D","text":"AWS App Runner — PaaS gerenciado para containers e código-fonte (Python/Node/Java), com HTTPS, scaling e CI"}]'::jsonb, 'D',
  '{
    "summary": "AWS App Runner é PaaS para containers/código — HTTPS automático, autoscaling, deploys via image push ou git push.",
    "whyCorrect": "App Runner aceita ECR image ou repositório GitHub. Você só especifica build/run commands e ele provê endpoint HTTPS público, autoscaling baseado em concurrent requests, observability via CloudWatch. Não há LB, cluster, networking pra configurar.",
    "whyWrong": {
     "A": "Beanstalk é PaaS mais antigo, focado em apps tradicionais (Tomcat, Node, Python, Docker) com EC2 visível. App Runner abstrai mais.",
     "B": "Lightsail Containers é parecido mas mais simples e voltado a workloads pequenos/preço fixo.",
     "C": "ECS Fargate manual exige configurar VPC, ALB, target group, autoscaling — é o que App Runner abstrai."
    },
    "keyConcept": "AWS App Runner — PaaS moderno para containers e source code",
    "compareWith": [
     "App Runner vs Beanstalk vs Lightsail Containers",
     "App Runner vs ECS Fargate (managed-ness)"
    ],
    "realWorldContext": "Boa escolha para microservices de equipes pequenas que não querem gerir infra. Cobra por vCPU/RAM ativo.",
    "commonMistakes": "Achar que App Runner é só para containers — também aceita source code (auto-build).",
    "tutorSeeds": [
     "App Runner suporta VPC connector para acessar RDS privado?",
     "Como funciona o auto-scaling de App Runner?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["app-runner","paas","containers","serverless"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
