INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-029', 'aws-clf', 'Onde a AWS armazena imagens Docker privadas de uma organização, com IAM, scan de vulnerabilidades e integração com ECS/EKS?',
  '[{"id":"A","text":"Amazon ECR (Elastic Container Registry) — registry de containers gerenciado, com scan, lifecycle, replicação"},{"id":"B","text":"Amazon S3 com bucket policies"},{"id":"C","text":"Docker Hub privado integrado"},{"id":"D","text":"AWS CodeArtifact"}]'::jsonb, 'A',
  '{
    "summary": "Amazon ECR é o registry OCI/Docker gerenciado pela AWS — privado por padrão, integra com IAM e scans.",
    "whyCorrect": "ECR oferece repositórios privados e públicos, autenticação via IAM (sem credenciais Docker Hub), scan de vulnerabilidades (basic ou Enhanced via Inspector), lifecycle policies (remover imagens antigas), replicação cross-region/cross-account e suporte a OCI artifacts.",
    "whyWrong": {
     "B": "S3 pode hospedar tarballs mas não é registry Docker — não tem manifests, layers, scanning.",
     "C": "Docker Hub não é AWS-native.",
     "D": "CodeArtifact é para pacotes (npm, Maven, PyPI), não imagens container."
    },
    "keyConcept": "Amazon ECR — container registry gerenciado AWS",
    "compareWith": [
     "ECR vs Docker Hub",
     "ECR Basic vs Enhanced scanning",
     "ECR Public Gallery"
    ],
    "realWorldContext": "Default para pipelines AWS — push to ECR + pull em ECS/EKS é o caminho oficial.",
    "commonMistakes": "Esquecer de configurar lifecycle policy — repositórios sem limpeza acumulam GBs de imagens antigas.",
    "tutorSeeds": [
     "Como funciona ECR Pull Through Cache?",
     "ECR Enhanced scanning usa qual serviço por baixo?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["ecr","container-registry","docker"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
