INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-030', 'aws-clf', 'Uma equipe quer subir um app Spring Boot pronto, sem gerenciar EC2/load balancer manualmente, mas com visibilidade total da infra (acessível via SSH se necessário) e suporte a múltiplas plataformas (Java/Node/Python/PHP/Ruby/Go/.NET/Docker). Qual serviço PaaS atende?',
  '[{"id":"A","text":"AWS Lambda"},{"id":"B","text":"AWS Elastic Beanstalk — PaaS clássico com EC2 visível, ALB e Auto Scaling gerenciados, multi-plataforma"},{"id":"C","text":"Amazon ECS task standalone"},{"id":"D","text":"AWS CloudShell"}]'::jsonb, 'B',
  '{
    "summary": "Elastic Beanstalk é PaaS clássico — você sobe código e Beanstalk provisiona EC2 + ALB + ASG automaticamente.",
    "whyCorrect": "Beanstalk aceita aplicações em Java/Tomcat, Node, Python, PHP, Ruby, Go, .NET, Docker. Tipos de ambiente: Single Instance (1 EC2, dev) ou Load Balanced (ALB + ASG, prod). Você mantém acesso SSH às EC2, vê CloudWatch logs/metrics, mas Beanstalk gerencia deploys, rollbacks, configurações via .ebextensions.",
    "whyWrong": {
     "A": "Lambda é function-as-a-service — não é fit para apps web Java tradicionais com estado em memória.",
     "C": "ECS task standalone exige cluster, task def, networking — não é PaaS.",
     "D": "CloudShell é shell no browser, não plataforma para hospedar apps."
    },
    "keyConcept": "AWS Elastic Beanstalk — PaaS multi-plataforma com infra visível",
    "compareWith": [
     "Beanstalk vs App Runner (Beanstalk dá mais controle, App Runner abstrai mais)",
     "Beanstalk vs ECS Fargate"
    ],
    "realWorldContext": "Beanstalk é escolha clássica para times migrando workloads on-prem para AWS sem refactor.",
    "commonMistakes": "Achar que Beanstalk é serverless — não é. EC2 é visível e cobrada pelas horas de instância.",
    "tutorSeeds": [
     "Qual a diferença entre single instance e load balanced environment?",
     "Como funciona deploy rolling vs immutable em Beanstalk?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["elastic-beanstalk","paas","java","deployment"]'::jsonb, 'ai-draft', 'active', now(), now()
)
