INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-031', 'aws-clf', 'Uma equipe usa Kubernetes em fábricas (on-prem) e quer estender o mesmo control plane gerenciado pela AWS para esses ambientes, sem instalar/operar K8s upstream do zero. Qual produto AWS atende?',
  '[{"id":"A","text":"ECS Anywhere com K8s flag"},{"id":"B","text":"AWS Outposts mandatório"},{"id":"C","text":"EKS Anywhere — distribuição Kubernetes da AWS para rodar em hardware on-prem (suporte oficial AWS)"},{"id":"D","text":"EKS no Fargate edge"}]'::jsonb, 'C',
  '{
    "summary": "EKS Anywhere permite rodar clusters EKS-compatíveis em hardware on-prem (VMware, bare metal).",
    "whyCorrect": "EKS Anywhere é uma distribuição K8s open-source baseada em EKS Distro. Você opera o cluster on-prem (bare metal ou VMware vSphere) com suporte enterprise pago da AWS. Independente da AWS region — é totalmente on-prem. Diferente de EKS on Outposts (que estende plano de controle AWS ao Outpost).",
    "whyWrong": {
     "A": "ECS Anywhere é o equivalente do ECS, não K8s.",
     "B": "Outposts é hardware AWS dentro do DC do cliente — caro e específico.",
     "D": "Não existe ''EKS Fargate edge''."
    },
    "keyConcept": "EKS Anywhere — distribuição K8s para on-prem",
    "compareWith": [
     "EKS Anywhere vs EKS on Outposts vs EKS region",
     "EKS Distro (open-source) vs EKS Anywhere"
    ],
    "realWorldContext": "Manufatura, varejo e telcos usam EKS Anywhere para padronizar K8s entre AWS cloud e edge sites.",
    "commonMistakes": "Confundir EKS Anywhere com EKS on Outposts. Anywhere é totalmente on-prem; Outposts é AWS hardware no DC.",
    "tutorSeeds": [
     "Qual a diferença entre EKS Distro e EKS Anywhere?",
     "EKS Anywhere funciona em qual hypervisor?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'recall', '["eks-anywhere","hybrid","kubernetes","on-prem"]'::jsonb, 'ai-draft', 'active', now(), now()
)
