INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-032', 'aws-clf', 'Uma equipe DevOps quer descrever toda a infraestrutura (VPC, EC2, RDS, IAM) num arquivo declarativo e versionado, e atualizar de forma idempotente. Qual serviço AWS é IaC nativo?',
  '[{"id":"A","text":"AWS Systems Manager"},{"id":"B","text":"AWS CodeDeploy"},{"id":"C","text":"AWS OpsWorks"},{"id":"D","text":"AWS CloudFormation — IaC nativo, templates YAML/JSON, stacks, change sets, drift detection"}]'::jsonb, 'D',
  '{
    "summary": "CloudFormation é o IaC nativo da AWS — templates declarativos para qualquer recurso.",
    "whyCorrect": "CloudFormation define recursos em templates YAML/JSON. A unidade de deploy é uma ''stack''. Recursos: Stack Sets (multi-conta/multi-region), Change Sets (preview de mudanças antes de aplicar), Drift Detection (detectar mudanças fora do template), Custom Resources (Lambda-backed), Nested Stacks (composição), Intrinsic Functions (Fn::Sub, !Ref, !GetAtt).",
    "whyWrong": {
     "A": "Systems Manager é gestão operacional (Session Manager, Patch Manager), não IaC.",
     "B": "CodeDeploy é deployment de código (apps), não provisioning de infra.",
     "C": "OpsWorks (Chef/Puppet managed) está deprecated."
    },
    "keyConcept": "AWS CloudFormation — Infrastructure as Code nativa AWS",
    "compareWith": [
     "CloudFormation vs Terraform vs CDK",
     "Stack vs Stack Set vs Nested Stack"
    ],
    "realWorldContext": "Base de IaC AWS. CDK e SAM transpilan para CloudFormation por baixo. Terraform é alternativa multi-cloud popular.",
    "commonMistakes": "Achar que CFN só roda em uma região — Stack Sets permitem multi-region/multi-account em uma operação.",
    "tutorSeeds": [
     "O que é Change Set em CloudFormation?",
     "Drift detection — quando aciona?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["cloudformation","iac","stacks","templates"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
