INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-033', 'aws-clf', 'Uma equipe quer aplicar o mesmo template de stack a 30 contas AWS (Organizations) em 5 regiões, com deploy automatizado e drift centralizado. Qual recurso CloudFormation atende?',
  '[{"id":"A","text":"CloudFormation StackSet — implanta a mesma stack em múltiplas contas/regiões com gerenciamento centralizado"},{"id":"B","text":"Stack individual replicada manualmente em cada conta"},{"id":"C","text":"Nested Stack"},{"id":"D","text":"Change Set multi-account"}]'::jsonb, 'A',
  '{
    "summary": "Stack Set é o mecanismo para implantar um template em múltiplas contas/regiões.",
    "whyCorrect": "StackSet é o recurso CFN para deploy em escala: você define o template uma vez e cria stack instances em N contas × M regiões. Integra com AWS Organizations (service-managed permissions) para auto-target de contas. Gerencia drift consolidado de todas as instâncias.",
    "whyWrong": {
     "B": "Replicar manualmente não escala e divergem rapidamente.",
     "C": "Nested Stack é stack-dentro-de-stack na mesma conta/region — para composição modular.",
     "D": "Change Set é preview de mudanças numa stack única — não é mecanismo multi-account."
    },
    "keyConcept": "CloudFormation StackSet — multi-account, multi-region",
    "compareWith": [
     "StackSet vs Stack",
     "Self-managed vs Service-managed StackSet (Organizations)"
    ],
    "realWorldContext": "Padrão para guardrails (ex: implantar Config rules, GuardDuty enable) em todas as contas da org.",
    "commonMistakes": "Achar que StackSet é ''stack grande'' — não. É template-uno + N instâncias distribuídas.",
    "tutorSeeds": [
     "Como funciona o service-managed permission model do StackSet?",
     "Como dropar uma stack instance sem deletar o recurso?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["cloudformation","stackset","organizations","multi-account"]'::jsonb, 'ai-draft', 'active', now(), now()
)
