INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-034', 'aws-clf', 'Um desenvolvedor quer escrever infraestrutura em TypeScript com classes, loops e tipagem (em vez de YAML), e que isso gere CloudFormation por baixo. Qual ferramenta AWS atende?',
  '[{"id":"A","text":"AWS SAM"},{"id":"B","text":"AWS CDK — Cloud Development Kit, suporta TS/Python/Java/Go/.NET e sintetiza CloudFormation"},{"id":"C","text":"AWS Amplify"},{"id":"D","text":"AWS Copilot"}]'::jsonb, 'B',
  '{
    "summary": "AWS CDK permite escrever IaC em linguagens de programação reais, gerando CloudFormation por baixo.",
    "whyCorrect": "CDK suporta TypeScript, Python, Java, Go, .NET. Você escreve ''constructs'' (classes) que representam recursos AWS, com tipagem e abstrações de alto nível. `cdk synth` produz template CloudFormation; `cdk deploy` faz o deploy. Ganho: reuso via classes, lógica condicional, loops, IDE autocomplete.",
    "whyWrong": {
     "A": "SAM é subset de CloudFormation focado em serverless (Lambda, API GW, DynamoDB) — YAML, não linguagem.",
     "C": "Amplify é framework full-stack para web/mobile (frontend + backend).",
     "D": "Copilot é CLI focado em ECS (App, Service, Environment)."
    },
    "keyConcept": "AWS CDK — IaC em linguagens reais, sintetiza CloudFormation",
    "compareWith": [
     "CDK vs CloudFormation (linguagem vs YAML)",
     "CDK vs Terraform CDKTF"
    ],
    "realWorldContext": "Adoção crescente em times com forte cultura de programação — economiza milhares de linhas vs YAML manual.",
    "commonMistakes": "Achar que CDK é ''outra coisa'' que CFN. Não — CDK SEMPRE gera CloudFormation e usa o mesmo deploy.",
    "tutorSeeds": [
     "O que são L1, L2 e L3 constructs no CDK?",
     "Como testar uma stack CDK?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["cdk","iac","typescript","constructs"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
