INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-035', 'aws-clf', 'Uma equipe quer pipeline contínuo: a cada push em branch main, código é compilado, testes rodam, artefato é gerado e implantado em ECS. Qual conjunto de serviços AWS é a base canônica desse pipeline?',
  '[{"id":"A","text":"CodeCommit + CodeBuild + CodeDeploy orquestrados manualmente por Lambda"},{"id":"B","text":"AWS Step Functions + AWS Lambda"},{"id":"C","text":"AWS CodePipeline (orquestrador) + CodeBuild (build/test) + CodeDeploy (deploy ECS); source pode ser GitHub/CodeCommit/S3"},{"id":"D","text":"Apenas CodeBuild"}]'::jsonb, 'C',
  '{
    "summary": "CodePipeline orquestra stages (Source → Build → Test → Deploy) integrando CodeBuild e CodeDeploy.",
    "whyCorrect": "CodePipeline é o motor de CI/CD AWS, modelado em stages com actions. Stages típicos: Source (GitHub/CodeCommit/S3/ECR), Build (CodeBuild), Test (CodeBuild ou third-party), Deploy (CodeDeploy/CloudFormation/ECS/Lambda/S3). CodeBuild compila e testa em containers ephemeral, gera artefatos, CodeDeploy implanta com blue/green ou canary.",
    "whyWrong": {
     "A": "Orquestrar manualmente via Lambda reinventa CodePipeline — anti-padrão.",
     "B": "Step Functions é genérico (workflows). CodePipeline é especializado em CI/CD.",
     "D": "CodeBuild apenas compila — não orquestra fluxo completo."
    },
    "keyConcept": "AWS CodePipeline + CodeBuild + CodeDeploy — stack canônica de CI/CD AWS",
    "compareWith": [
     "CodePipeline vs GitHub Actions vs Jenkins",
     "CodeBuild (build) vs CodeDeploy (deploy)"
    ],
    "realWorldContext": "Padrão simples para equipes 100% AWS. Empresas com GitHub forte preferem GitHub Actions + AWS OIDC.",
    "commonMistakes": "Achar que CodeCommit é obrigatório — não. Source pode ser GitHub/Bitbucket via connection.",
    "tutorSeeds": [
     "Quais source providers o CodePipeline aceita?",
     "Como manual approval funciona em CodePipeline?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["codepipeline","codebuild","codedeploy","cicd"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
  simulado_id   = EXCLUDED.simulado_id,
