INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-036', 'aws-clf', 'Uma empresa quer fazer deploy de uma nova versão da aplicação em ECS sem downtime e com possibilidade de rollback automático se erros aumentarem. Qual estratégia do CodeDeploy atende?',
  '[{"id":"A","text":"In-place — para todas as instâncias e sobe versão nova"},{"id":"B","text":"Manual deploy via SSH em cada container"},{"id":"C","text":"Reboot all-at-once"},{"id":"D","text":"Blue/Green com shift gradual (canary 10% → 100%) e CloudWatch alarms para rollback automático"}]'::jsonb, 'D',
  '{
    "summary": "Blue/Green com canary shift e CloudWatch alarms é a estratégia segura de deploy.",
    "whyCorrect": "CodeDeploy suporta Blue/Green para ECS, Lambda e EC2/on-prem. No ECS, cria 2 target groups: green recebe nova versão; shift de tráfego em porcentagens (canary 10/90, depois 100) ou linear, com CloudWatch alarms monitorando erros 5xx/latência. Se alarme dispara, CodeDeploy faz rollback automaticamente.",
    "whyWrong": {
     "A": "In-place tem downtime e rollback complicado (precisa redeploy).",
     "B": "Manual via SSH é o oposto de safe deployment.",
     "C": "All-at-once causa downtime garantido."
    },
    "keyConcept": "CodeDeploy Blue/Green — zero downtime + rollback automático via CW alarms",
    "compareWith": [
     "Blue/Green vs Canary vs Rolling vs In-place",
     "ECS deployment via CodeDeploy vs nativo rolling"
    ],
    "realWorldContext": "Padrão moderno: blue/green canary 10% por 5min + alarms de 5xx → 100% se OK; rollback se não.",
    "commonMistakes": "Confundir Blue/Green com Rolling. Blue/Green tem 2 ambientes simultâneos; Rolling substitui pouco a pouco no mesmo ambiente.",
    "tutorSeeds": [
     "Como CodeDeploy faz rollback automático?",
     "Quais shift types CodeDeploy suporta?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["codedeploy","blue-green","canary","ecs"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
