INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-037', 'aws-clf', 'Um desenvolvedor precisa armazenar artefatos compartilhados (pacotes npm, Maven, PyPI, NuGet) com integração IAM, sem expor publicamente. Qual serviço AWS atende?',
  '[{"id":"A","text":"AWS CodeArtifact — repositório managed para npm/Maven/PyPI/NuGet/Gradle, com IAM e upstream público (npmjs, Maven Central)"},{"id":"B","text":"Amazon ECR"},{"id":"C","text":"Amazon S3 bucket privado"},{"id":"D","text":"AWS CodeCommit"}]'::jsonb, 'A',
  '{
    "summary": "AWS CodeArtifact é registry managed para artefatos npm/Maven/PyPI/NuGet/Gradle.",
    "whyCorrect": "CodeArtifact funciona como Artifactory/Nexus managed. Suporta múltiplos package managers, repositórios privados/internos, upstream para repositórios públicos (npmjs.org, Maven Central, PyPI) com cache. Auth via IAM (token via AWS CLI).",
    "whyWrong": {
     "B": "ECR é container registry (Docker/OCI), não pacotes.",
     "C": "S3 hosting é manual — sem manifests, sem npm/Maven semantics.",
     "D": "CodeCommit é Git, não pacotes."
    },
    "keyConcept": "AWS CodeArtifact — managed package registry",
    "compareWith": [
     "CodeArtifact vs Artifactory vs Nexus",
     "CodeArtifact (packages) vs ECR (containers)"
    ],
    "realWorldContext": "Útil em empresas que precisam isolar dependências do npmjs (segurança da supply chain).",
    "commonMistakes": "Confundir com ECR — ECR é containers, CodeArtifact é pacotes de código.",
    "tutorSeeds": [
     "Como configurar upstream npm em CodeArtifact?",
     "CodeArtifact suporta Docker?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["codeartifact","packages","npm","maven"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
