INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-038', 'aws-clf', 'Um líder de engenharia quer um IDE no navegador, com terminal Linux, CLI AWS pré-instalada e sem precisar configurar instância. É grátis e ideal para troubleshooting/scripts rápidos. Qual serviço?',
  '[{"id":"A","text":"AWS Cloud9 (deprecated for new customers)"},{"id":"B","text":"AWS CloudShell — terminal Linux no browser, gratuito, com AWS CLI/kubectl/SAM pré-instalados, 1GB persistente"},{"id":"C","text":"AWS Elastic Beanstalk"},{"id":"D","text":"Amazon WorkSpaces Web"}]'::jsonb, 'B',
  '{
    "summary": "AWS CloudShell é terminal Linux gratuito no browser do console, com ferramentas AWS pré-instaladas.",
    "whyCorrect": "CloudShell abre numa tab do AWS Console (ícone shell no header). Roda Amazon Linux 2 com CLI v2, SAM, kubectl, jq, python3, node, git já instalados. 1GB de storage persistente por região. Sem cobrança — perfeito para scripts ad-hoc e quem está estudando.",
    "whyWrong": {
     "A": "Cloud9 era IDE no browser mas a AWS parou de aceitar novos clientes (2024). Quem usa migra para CloudShell + VS Code Remote.",
     "C": "Beanstalk hospeda apps, não é IDE.",
     "D": "WorkSpaces Web é navegador managed para acessar apps — não IDE."
    },
    "keyConcept": "AWS CloudShell — terminal Linux no console, grátis, com ferramentas AWS",
    "compareWith": [
     "CloudShell vs Cloud9 (deprecated)",
     "CloudShell vs local AWS CLI"
    ],
    "realWorldContext": "Default para iniciantes e troubleshooting rápido. Engenheiros sêniores usam para ''rodar um script de emergência'' sem laptop configurado.",
    "commonMistakes": "Achar que CloudShell tem capacidade de longo prazo — sessões expiram após 12h ociosas e o filesystem fora de $HOME é efêmero.",
    "tutorSeeds": [
     "Quanto é a quota persistente do CloudShell?",
     "Como instalar ferramentas adicionais em CloudShell?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["cloudshell","cli","console"]'::jsonb, 'ai-draft', 'active', now(), now()
)
