INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-039', 'aws-clf', 'Uma equipe usa SAM (Serverless Application Model) para definir uma API REST com Lambda + API Gateway + DynamoDB. Como SAM se relaciona com CloudFormation?',
  '[{"id":"A","text":"SAM é uma alternativa concorrente que substitui CloudFormation"},{"id":"B","text":"SAM gera Terraform"},{"id":"C","text":"SAM é uma extensão (transform) do CloudFormation com sintaxe enxuta para serverless; é transpilada para CFN no deploy"},{"id":"D","text":"SAM é só uma CLI sem template"}]'::jsonb, 'C',
  '{
    "summary": "SAM é um superset/transform do CloudFormation, focado em serverless.",
    "whyCorrect": "Templates SAM declaram `Transform: AWS::Serverless-2016-10-31` e usam tipos como `AWS::Serverless::Function`, `AWS::Serverless::Api`, `AWS::Serverless::Table`. No deploy, o transform expande para recursos CFN nativos (Lambda + IAM + API Gateway + etc.). SAM CLI também provê `sam local invoke` (Lambda local via Docker), `sam build`, `sam deploy`.",
    "whyWrong": {
     "A": "Não substitui — é um transform.",
     "B": "SAM gera CFN, não Terraform.",
     "D": "SAM tem template YAML rico, além da CLI."
    },
    "keyConcept": "AWS SAM — transform CloudFormation para serverless + CLI local",
    "compareWith": [
     "SAM vs CloudFormation (subset focado em serverless)",
     "SAM CLI vs CDK"
    ],
    "realWorldContext": "Default para projetos serverless puros (Lambda + API GW + DDB). Mais simples que CDK para esse cenário.",
    "commonMistakes": "Achar que SAM e CDK são iguais — SAM é template-driven, CDK é code-driven.",
    "tutorSeeds": [
     "Como sam local invoke funciona por baixo?",
     "SAM Accelerate — o que é?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["sam","serverless","cloudformation","transform"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
