INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-040', 'aws-clf', 'Uma engenheira quer detectar quando recursos de uma stack CloudFormation foram modificados manualmente (ex: alguém alterou um Security Group fora do template). Qual feature CFN atende?',
  '[{"id":"A","text":"Change Set"},{"id":"B","text":"Stack Policy"},{"id":"C","text":"Nested Stacks"},{"id":"D","text":"Drift Detection — compara estado real dos recursos com o template e reporta diferenças"}]'::jsonb, 'D',
  '{
    "summary": "Drift Detection compara o estado vigente dos recursos com o template e identifica desvios.",
    "whyCorrect": "Drift Detection escaneia recursos de uma stack e compara configuração vigente com o que o template define. Reporta status DRIFTED se houver diferenças, indicando quais propriedades mudaram. Suporta drill-down em StackSet.",
    "whyWrong": {
     "A": "Change Set é preview ANTES de aplicar mudanças no template, não detecta mudanças out-of-band.",
     "B": "Stack Policy é um documento que protege recursos de atualização durante deploys.",
     "C": "Nested Stacks são composição de templates, não detecção."
    },
    "keyConcept": "CloudFormation Drift Detection — detectar mudanças out-of-band em recursos",
    "compareWith": [
     "Drift Detection vs Change Set",
     "Drift vs Stack Policy"
    ],
    "realWorldContext": "Roda periodicamente em pipelines GitOps para garantir que infra está como o código diz.",
    "commonMistakes": "Achar que CFN remedia drift automaticamente — não. Reporta, mas você decide se atualiza o template ou reverte o recurso.",
    "tutorSeeds": [
     "Como remediar drift detectado?",
     "Drift detection cobra extra?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["cloudformation","drift-detection","compliance"]'::jsonb, 'ai-draft', 'active', now(), now()
)
