INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-041', 'aws-clf', 'Uma SRE precisa coletar métricas custom (gauge de queue depth de um broker interno) e disparar alerta quando exceder 500 mensagens por 3 datapoints consecutivos. Qual combinação atende?',
  '[{"id":"A","text":"CloudWatch custom metrics (PutMetricData) + CloudWatch alarm com 3 datapoints"},{"id":"B","text":"AWS X-Ray traces"},{"id":"C","text":"CloudTrail data events"},{"id":"D","text":"AWS Config rule"}]'::jsonb, 'A',
  '{
    "summary": "CloudWatch PutMetricData publica métricas customizadas; alarms disparam por threshold + datapoints.",
    "whyCorrect": "CloudWatch é o serviço de métricas, logs e alarms. Métricas customizadas via API PutMetricData (ou agent). Alarms suportam threshold + evaluation periods + datapoints-to-alarm (ex: 3 de 5 datapoints acima do threshold). Disparam ação: SNS, Auto Scaling, Lambda.",
    "whyWrong": {
     "B": "X-Ray é distributed tracing (latência, dependências), não métricas custom.",
     "C": "CloudTrail é audit de API calls, não métricas de aplicação.",
     "D": "Config avalia compliance de configuração, não métricas runtime."
    },
    "keyConcept": "CloudWatch metrics + alarms — observabilidade core AWS",
    "compareWith": [
     "Standard resolution (60s) vs High resolution (1s) metrics",
     "Composite alarms vs simple alarms"
    ],
    "realWorldContext": "Padrão para alerta on-call. Composite alarms reduzem ruído combinando múltiplos alarms.",
    "commonMistakes": "Confundir periods e datapoints — period é janela de agregação, datapoints é quantos consecutivos para disparar.",
    "tutorSeeds": [
     "Qual a diferença entre standard e high-resolution metrics?",
     "Como composite alarms reduzem alert fatigue?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["cloudwatch","metrics","alarms","custom-metrics"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
