INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-042', 'aws-clf', 'Uma equipe quer analisar logs de várias aplicações via queries declarativas (filtrar campos JSON, agregar contagens, criar dashboards). Qual feature do CloudWatch atende?',
  '[{"id":"A","text":"CloudWatch Metrics"},{"id":"B","text":"CloudWatch Logs Insights — query language para logs com filter, stats, parse, sort"},{"id":"C","text":"CloudWatch RUM"},{"id":"D","text":"CloudWatch Synthetics"}]'::jsonb, 'B',
  '{
    "summary": "Logs Insights é a engine de queries declarativa do CloudWatch Logs.",
    "whyCorrect": "Logs Insights permite queries como `fields @timestamp, status | filter status >= 500 | stats count() by bin(5m)`. Suporta parse de regex, stats de agregação, sort, limit. Salvar como dashboard widget é direto. Cobra por GB de dados varridos.",
    "whyWrong": {
     "A": "Metrics é numérico, não busca em logs.",
     "C": "RUM (Real User Monitoring) coleta dados do browser do usuário final.",
     "D": "Synthetics roda canaries — simulações de usuário."
    },
    "keyConcept": "CloudWatch Logs Insights — query language declarativa para logs",
    "compareWith": [
     "Logs Insights vs Athena (S3 logs)",
     "Logs Insights vs OpenSearch"
    ],
    "realWorldContext": "Ferramenta diária do SRE para investigar incidentes.",
    "commonMistakes": "Custo: Logs Insights cobra por GB de log varrido. Queries sem filtro de tempo varrem tudo — caro.",
    "tutorSeeds": [
     "Como otimizar custo do Logs Insights?",
     "Diferença entre Logs Insights e Athena para logs em S3?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["cloudwatch-logs","logs-insights","queries"]'::jsonb, 'ai-draft', 'active', now(), now()
)
