INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-043', 'aws-clf', 'Um time precisa fazer tracing distribuído (rastrear request HTTP atravessando API GW → Lambda → DynamoDB → Lambda → SQS) e ver latência por hop. Qual serviço atende?',
  '[{"id":"A","text":"CloudWatch Metrics"},{"id":"B","text":"CloudTrail"},{"id":"C","text":"AWS X-Ray — distributed tracing com service map e segments por chamada"},{"id":"D","text":"AWS Config"}]'::jsonb, 'C',
  '{
    "summary": "AWS X-Ray é o serviço de distributed tracing — traces por request, segments por service, service map visual.",
    "whyCorrect": "X-Ray amostra requests e correlaciona segments entre serviços (via trace-id propagado). Mostra service map (DAG dos serviços), latência por hop, erros, anomalias. Integra nativo com API Gateway, Lambda, ECS, EC2, RDS. CloudWatch ServiceLens unifica X-Ray + métricas + logs.",
    "whyWrong": {
     "A": "Metrics não rastreia request individual.",
     "B": "CloudTrail é audit de chamadas AWS API, não request tracing de app.",
     "D": "Config é compliance/configuration, não tracing."
    },
    "keyConcept": "AWS X-Ray — distributed tracing AWS-native",
    "compareWith": [
     "X-Ray vs Jaeger/OpenTelemetry",
     "X-Ray + ServiceLens"
    ],
    "realWorldContext": "Crítico para microservices — identificar bottleneck em request multi-hop.",
    "commonMistakes": "Esquecer de ativar ''Active tracing'' em Lambda e API Gateway — sem isso, X-Ray não recebe dados.",
    "tutorSeeds": [
     "Como X-Ray sampling rate funciona?",
     "X-Ray suporta OpenTelemetry?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["x-ray","tracing","observability"]'::jsonb, 'ai-draft', 'active', now(), now()
)
