INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-044', 'aws-clf', 'Uma SRE quer ver o status público dos serviços AWS (ex: ''há incidente em S3 us-east-1?'') vs eventos específicos da SUA conta (ex: ''sua EC2 i-abc tem manutenção agendada''). Quais dois recursos atendem?',
  '[{"id":"A","text":"CloudWatch Service Status"},{"id":"B","text":"AWS Config Compliance Center"},{"id":"C","text":"Trusted Advisor"},{"id":"D","text":"AWS Health Dashboard — Service Health (público geral) + Your Account Health (eventos personalizados)"}]'::jsonb, 'D',
  '{
    "summary": "AWS Health Dashboard tem 2 visões: Service Health (público) e Your Account Health (personalizado).",
    "whyCorrect": "AWS Health Dashboard substituiu os antigos ''Service Health Dashboard'' (público) e ''Personal Health Dashboard'' (account-specific). Service Health: lista incidentes globais por região/serviço. Your Account Health: eventos que afetam SUA conta (manutenções, account-level issues, security notifications).",
    "whyWrong": {
     "A": "Nome incorreto — CloudWatch tem ServiceLens, não Service Status.",
     "B": "Config Compliance é sobre conformidade de recursos.",
     "C": "Trusted Advisor é recomendações de FinOps/security/perf, não status de serviço."
    },
    "keyConcept": "AWS Health Dashboard — Service Health (público) + Account Health (personalizado)",
    "compareWith": [
     "Service Health (global incidents) vs Account Health (your resources)",
     "Health Dashboard vs Trusted Advisor"
    ],
    "realWorldContext": "Primeira parada quando algo dá errado: ''é AWS ou somos nós?''. Health → Service Health responde.",
    "commonMistakes": "Esperar email proativo — você precisa configurar EventBridge rules para Health events para notificar.",
    "tutorSeeds": [
     "Como EventBridge captura AWS Health events?",
     "Diferença entre AWS Health API e Dashboard?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["aws-health","service-health","personal-health"]'::jsonb, 'ai-draft', 'active', now(), now()
)
