INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-045', 'aws-clf', 'Uma fintech proíbe SSH inbound (porta 22) em instâncias EC2 mas precisa que engenheiros acessem o terminal das instâncias para debug. Qual serviço AWS resolve sem bastion host nem porta 22 aberta?',
  '[{"id":"A","text":"AWS Systems Manager Session Manager — conexão via SSM Agent + IAM, sem porta inbound, com logging em S3/CloudWatch"},{"id":"B","text":"AWS Direct Connect Console"},{"id":"C","text":"Amazon WorkSpaces"},{"id":"D","text":"AWS CodeBuild SSH"}]'::jsonb, 'A',
  '{
    "summary": "SSM Session Manager elimina SSH inbound — conexão sai do agent (outbound) ao SSM endpoint.",
    "whyCorrect": "Session Manager usa o SSM Agent (já pré-instalado em Amazon Linux/Ubuntu modernos). O agent estabelece long-poll outbound HTTPS ao endpoint SSM. Engenheiros abrem sessão via console, CLI ou SSH-over-SSM. Auth e autorização via IAM (princípio: AmazonSSMManagedInstanceCore). Logs de sessão podem ir para CloudWatch ou S3.",
    "whyWrong": {
     "B": "Não existe ''Direct Connect Console SSH''.",
     "C": "WorkSpaces é desktop virtual para usuários — não terminal de EC2.",
     "D": "CodeBuild não dá SSH em EC2."
    },
    "keyConcept": "AWS Systems Manager Session Manager — terminal EC2 sem SSH inbound",
    "compareWith": [
     "Session Manager vs SSH com bastion host",
     "Session Manager vs EC2 Instance Connect"
    ],
    "realWorldContext": "Padrão de segurança moderna: zero portas inbound + Session Manager via IAM + auditoria CloudTrail.",
    "commonMistakes": "Esquecer IAM permissions (SSMManagedInstanceCore + KMS se houver criptografia de session). Ou esquecer endpoints SSM/EC2messages/SSMmessages na VPC privada.",
    "tutorSeeds": [
     "Quais permissions a IAM da EC2 precisa ter?",
     "Como auditar sessions feitas via Session Manager?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["systems-manager","session-manager","security","ssh"]'::jsonb, 'ai-draft', 'active', now(), now()
)
