INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-046', 'aws-clf', 'Uma equipe ops precisa aplicar patches de SO mensalmente em 500 EC2 e 200 servers on-prem, em janelas controladas e com relatório de compliance. Qual serviço atende?',
  '[{"id":"A","text":"AWS Inspector"},{"id":"B","text":"AWS Systems Manager Patch Manager + Maintenance Windows; SSM Agent funciona on-prem via Hybrid Activation"},{"id":"C","text":"AWS Config"},{"id":"D","text":"AWS Macie"}]'::jsonb, 'B',
  '{
    "summary": "SSM Patch Manager + Maintenance Windows automatiza patching em EC2 e on-prem (via Hybrid Activation).",
    "whyCorrect": "Patch Manager define baselines (patches aprovados por SO/severidade) e patch groups (tags em instâncias). Maintenance Windows controla janelas (ex: domingo 02h-06h). Aplica patches via SSM Agent. Funciona em on-prem registrando servidores via ''Hybrid Activation'' (SSM Agent + activation code).",
    "whyWrong": {
     "A": "Inspector escaneia vulnerabilidades — não aplica patches.",
     "C": "Config monitora compliance de configuração, não patch automation.",
     "D": "Macie é descoberta de dados sensíveis em S3."
    },
    "keyConcept": "SSM Patch Manager + Maintenance Windows + Hybrid Activation — patching híbrido",
    "compareWith": [
     "Patch Manager vs Inspector",
     "SSM in AWS vs on-prem (Hybrid Activation)"
    ],
    "realWorldContext": "Padrão para ops híbrida — mesma ferramenta para EC2 e on-prem, relatórios consolidados.",
    "commonMistakes": "Confundir Inspector (scan) com Patch Manager (aplicar). Inspector detecta; Patch Manager corrige.",
    "tutorSeeds": [
     "O que é SSM Hybrid Activation?",
     "Como criar patch baseline custom?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["systems-manager","patch-manager","hybrid","maintenance-windows"]'::jsonb, 'ai-draft', 'active', now(), now()
)
