INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-047', 'aws-clf', 'Uma equipe armazena database password e API tokens. Quer versionamento, rotação automática gratuita e referência em CFN/CDK. Para CONFIGURAÇÕES (não secrets), quer string parameters baratos. Quais serviços atendem cada caso?',
  '[{"id":"A","text":"Secrets Manager para tudo"},{"id":"B","text":"S3 com SSE-KMS para tudo"},{"id":"C","text":"Secrets Manager para senhas/tokens (rotação automática gerenciada); SSM Parameter Store (Standard tier grátis) para configurações"},{"id":"D","text":"KMS encrypted Lambda envs"}]'::jsonb, 'C',
  '{
    "summary": "Secrets Manager para secrets (com rotação Lambda); Parameter Store Standard para config genérica (grátis).",
    "whyCorrect": "Secrets Manager: $0,40/secret/mês + API calls. Rotação automática via Lambda gerenciado (RDS, Aurora, DocumentDB, Redshift integrados). Parameter Store Standard: até 10.000 parameters grátis, valor até 4KB. Advanced tier: até 100KB, pago. Ambos integram com KMS e IAM.",
    "whyWrong": {
     "A": "Caro — guardar 1000 config strings em Secrets Manager custa $400/mês.",
     "B": "S3 não é fit para secrets de baixa latência — KMS-decrypted S3 GETs por hot path.",
     "D": "Lambda envs são plaintext (mesmo com KMS encrypt-at-rest) e estáticos."
    },
    "keyConcept": "Secrets Manager (secrets c/ rotação) vs SSM Parameter Store (config)",
    "compareWith": [
     "Secrets Manager vs Parameter Store SecureString",
     "Parameter Store Standard vs Advanced tier"
    ],
    "realWorldContext": "Pattern típico: Parameter Store para feature flags/config, Secrets Manager para credenciais.",
    "commonMistakes": "Usar Secrets Manager para feature flags — custa caro. Use Parameter Store.",
    "tutorSeeds": [
     "Parameter Store SecureString vs Secrets Manager — quando cada um?",
     "Como funciona rotação automática Secrets Manager + RDS?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["secrets-manager","parameter-store","systems-manager"]'::jsonb, 'ai-draft', 'active', now(), now()
)
