INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-048', 'aws-clf', 'Uma equipe quer simular requests de usuário sintéticos (homepage carrega? login funciona? checkout completa?) periodicamente, para detectar problemas antes dos usuários reais. Qual serviço atende?',
  '[{"id":"A","text":"AWS X-Ray Synthetics"},{"id":"B","text":"AWS Inspector"},{"id":"C","text":"AWS DataSync"},{"id":"D","text":"CloudWatch Synthetics — canaries (scripts Puppeteer/Selenium) que simulam usuário e alertam em falhas"}]'::jsonb, 'D',
  '{
    "summary": "CloudWatch Synthetics provê canaries (Node.js Puppeteer/Selenium) para monitorar UX sintética.",
    "whyCorrect": "Canaries são scripts agendados (configuráveis em frequência) que executam navegação real (Puppeteer/Selenium) ou chamadas API. Geram screenshots, harvests de erros, métricas de duração e success rate. Integra com CloudWatch alarms para alertar quando passos falham.",
    "whyWrong": {
     "A": "X-Ray Synthetics não existe como produto separado.",
     "B": "Inspector é vulnerability scanning.",
     "C": "DataSync é transferência de dados."
    },
    "keyConcept": "CloudWatch Synthetics — canaries para UX monitoring sintético",
    "compareWith": [
     "Synthetics canary vs RUM (real users)",
     "Synthetics vs Pingdom/Datadog Synthetic"
    ],
    "realWorldContext": "Usado para SLA monitoring. Combina com RUM (Real User Monitoring) para visão completa.",
    "commonMistakes": "Esquecer que canaries cobram por execução — alta frequência (1/min) pode ser custosa.",
    "tutorSeeds": [
     "Que linguagens canary blueprints suportam?",
     "Synthetics vs RUM — quando usar cada?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["cloudwatch-synthetics","canaries","monitoring"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
