INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-049', 'aws-clf', 'Uma startup quer ver as quotas atuais (limits) por serviço e solicitar aumento de quota (ex: vCPUs em EC2 on-demand) via console/API. Qual serviço atende?',
  '[{"id":"A","text":"AWS Service Quotas — visualizar/solicitar aumento de quotas por serviço/region"},{"id":"B","text":"AWS Trusted Advisor"},{"id":"C","text":"AWS Budgets"},{"id":"D","text":"AWS Cost Explorer"}]'::jsonb, 'A',
  '{
    "summary": "AWS Service Quotas centraliza visualização e solicitação de aumento de quotas.",
    "whyCorrect": "Service Quotas tem console único para todas as quotas (antigamente ''service limits''). Permite request quota increase via UI/API, ver utilização atual via CloudWatch metrics, configurar alarms quando >80% da quota. Integra com Trusted Advisor.",
    "whyWrong": {
     "B": "Trusted Advisor mostra recomendações (incluindo service limits) mas não é o serviço dedicado a quotas.",
     "C": "Budgets controla orçamento ($), não quotas técnicas.",
     "D": "Cost Explorer analisa gastos."
    },
    "keyConcept": "AWS Service Quotas — gestão centralizada de limits/quotas",
    "compareWith": [
     "Service Quotas vs Trusted Advisor service limits"
    ],
    "realWorldContext": "Antes de lançar produto: revisar quotas relevantes (Lambda concurrency, EBS volume count, Elastic IPs) e solicitar aumento.",
    "commonMistakes": "Esperar dia do lançamento para pedir aumento — pode demorar dias.",
    "tutorSeeds": [
     "Como configurar alarme de quota próximo do limit?",
     "Quotas adjustable vs non-adjustable?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["service-quotas","limits"]'::jsonb, 'ai-draft', 'active', now(), now()
)
