INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-050', 'aws-clf', 'Uma SRE precisa de query unificada para ''todos os recursos AWS que têm tag environment=production em todas as contas e regiões da Organization''. Qual serviço atende?',
  '[{"id":"A","text":"AWS Resource Groups Tag Editor (regional, single account)"},{"id":"B","text":"AWS Resource Explorer — busca cross-region/cross-account de recursos por tag/tipo/keyword"},{"id":"C","text":"AWS Config"},{"id":"D","text":"AWS Tag Manager"}]'::jsonb, 'B',
  '{
    "summary": "AWS Resource Explorer é busca unificada multi-region/multi-account.",
    "whyCorrect": "Resource Explorer indexa recursos AWS continuamente e provê busca tipo Google (tag, type, name, region). Suporta multi-region default view e via AWS Organizations pode estender para multi-account.",
    "whyWrong": {
     "A": "Tag Editor é mais limitado — regional, single account.",
     "C": "Config rastreia configuração ao longo do tempo, mas a busca livre é menos prática.",
     "D": "''Tag Manager'' não é serviço AWS."
    },
    "keyConcept": "AWS Resource Explorer — busca unificada de recursos",
    "compareWith": [
     "Resource Explorer vs Tag Editor vs Config aggregator"
    ],
    "realWorldContext": "Útil para inventário rápido — ''onde estão todos os ALBs com tag team=payments?''.",
    "commonMistakes": "Esquecer de habilitar Resource Explorer na conta — é opt-in.",
    "tutorSeeds": [
     "Diferença entre Resource Explorer e Tag Editor?",
     "Como ativar visão multi-account?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'recall', '["resource-explorer","tagging","inventory"]'::jsonb, 'ai-draft', 'active', now(), now()
)
