INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-051', 'aws-clf', 'Uma corporação quer descobrir inventário de aplicações on-prem (servidores, dependências, network) ANTES de migrar para AWS, sem instalar agente em todas as VMs. Qual serviço atende?',
  '[{"id":"A","text":"AWS Application Migration Service (MGN)"},{"id":"B","text":"AWS DataSync"},{"id":"C","text":"AWS Application Discovery Service — agentless (VMware) ou agent-based, coleta inventário on-prem para migration planning"},{"id":"D","text":"AWS Snowball"}]'::jsonb, 'C',
  '{
    "summary": "Application Discovery Service mapeia ambiente on-prem para planejamento de migração.",
    "whyCorrect": "ADS oferece dois modos: Agentless Discovery Connector (VM appliance no vCenter, descobre VMs sem agent) e Agent-based (coleta detalhes de OS, processos, network). Dados alimentam Migration Hub e ferramentas de business case.",
    "whyWrong": {
     "A": "MGN (Application Migration Service) faz a migração — depois do discovery.",
     "B": "DataSync é transferência de dados em volume.",
     "D": "Snowball é appliance físico para mover petabytes."
    },
    "keyConcept": "AWS Application Discovery Service — inventário pré-migração",
    "compareWith": [
     "ADS vs Migration Evaluator",
     "Agentless vs Agent-based discovery"
    ],
    "realWorldContext": "Fase ''Assess'' do AWS MAP (Migration Acceleration Program).",
    "commonMistakes": "Confundir Discovery (assessment) com MGN (replication/cutover).",
    "tutorSeeds": [
     "Como ADS integra com Migration Hub?",
     "Discovery agentless funciona em Hyper-V?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["application-discovery","migration","assessment"]'::jsonb, 'ai-draft', 'active', now(), now()
)
