INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-052', 'aws-clf', 'Uma empresa quer migrar 200 servidores físicos/VMs para EC2 com replicação contínua, minimal downtime e teste antes do cutover. Qual serviço atende?',
  '[{"id":"A","text":"AWS DataSync com mode VM"},{"id":"B","text":"AWS Snowball Edge"},{"id":"C","text":"AWS Direct Connect Migration"},{"id":"D","text":"AWS Application Migration Service (MGN) — sucessor do CloudEndure Migration; replicação contínua + cutover"}]'::jsonb, 'D',
  '{
    "summary": "AWS MGN (Application Migration Service) é o serviço atual de lift-and-shift; sucede CloudEndure.",
    "whyCorrect": "MGN instala agent no source server que replica continuamente disco para um EBS staging na AWS. Permite testes (lança EC2 com cópia, valida) antes do cutover. Cutover real para de replicar e promove. Substituiu CloudEndure Migration (deprecated).",
    "whyWrong": {
     "A": "DataSync transfere dados (arquivos/objetos), não migra servidores inteiros.",
     "B": "Snowball é offline data transfer de PB.",
     "C": "DX é conectividade de rede, não migração de servidor."
    },
    "keyConcept": "AWS MGN — lift-and-shift moderno (sucessor CloudEndure)",
    "compareWith": [
     "MGN vs CloudEndure (legacy)",
     "MGN vs Server Migration Service (SMS, descontinuado)"
    ],
    "realWorldContext": "Padrão para ''rehost'' (R do 6Rs). Migrações de VMware/Hyper-V/físicos para EC2.",
    "commonMistakes": "Citar CloudEndure no exame — atualmente é MGN.",
    "tutorSeeds": [
     "MGN suporta replicação contínua de qual SO?",
     "Como funciona cutover step-by-step?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["mgn","migration","lift-and-shift","cloudendure"]'::jsonb, 'ai-draft', 'active', now(), now()
)
