INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-053', 'aws-clf', 'Uma empresa migra Oracle on-prem para Aurora PostgreSQL. Precisa converter o schema (tabelas, stored procedures, triggers) e replicar dados com mínimo downtime. Quais serviços atendem juntos?',
  '[{"id":"A","text":"AWS SCT (Schema Conversion Tool) converte schema/código Oracle → PostgreSQL; AWS DMS replica os DADOS com CDC (Change Data Capture)"},{"id":"B","text":"DMS faz tudo, incluindo conversão de schema"},{"id":"C","text":"DataSync + Glue"},{"id":"D","text":"Snowball + manual import"}]'::jsonb, 'A',
  '{
    "summary": "SCT converte schema/código; DMS move os dados. São complementares.",
    "whyCorrect": "AWS SCT (Schema Conversion Tool) é desktop app que converte schema (DDL) e código procedural (PL/SQL → PL/pgSQL). Reporta itens que precisam intervenção manual. AWS DMS (Database Migration Service) move os dados — full load + CDC para minimizar downtime — entre engines heterogêneos.",
    "whyWrong": {
     "B": "DMS NÃO converte schema — só replica dados. Schema precisa de SCT (ou criar manualmente).",
     "C": "DataSync + Glue é para data lakes/files.",
     "D": "Snowball + import manual é unitário, sem CDC."
    },
    "keyConcept": "AWS SCT (schema) + DMS (dados) — migração heterogênea",
    "compareWith": [
     "DMS homogeneous (mesmo engine) vs heterogeneous (precisa SCT)",
     "DMS full load vs CDC"
    ],
    "realWorldContext": "Migração Oracle → Aurora PostgreSQL é o caso de uso emblemático que AWS promove.",
    "commonMistakes": "Achar que DMS converte schema — não. SCT obrigatório para heterogeneous.",
    "tutorSeeds": [
     "Como DMS CDC funciona em Oracle?",
     "Quais transformações SCT suporta?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["dms","sct","migration","database"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
