INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-054', 'aws-clf', 'Uma equipe precisa transferir TB de arquivos do NFS/SMB on-prem para S3/EFS/FSx, com checksums, retomada e bandwidth control. Qual serviço atende?',
  '[{"id":"A","text":"AWS Storage Gateway File mode"},{"id":"B","text":"AWS DataSync — agent on-prem transfere para S3/EFS/FSx com checksums, retry e throttling"},{"id":"C","text":"AWS Snowcone"},{"id":"D","text":"AWS Transfer Family SFTP"}]'::jsonb, 'B',
  '{
    "summary": "AWS DataSync é o serviço de bulk data transfer NFS/SMB ↔ AWS storage.",
    "whyCorrect": "DataSync instala um agent (VM/EC2/on-prem) que faz o transfer entre fontes (NFS, SMB, HDFS, S3, EFS, FSx) e destinos AWS. Provê checksums end-to-end, retomada de transferências, bandwidth throttling, scheduling. Cobra por GB transferido.",
    "whyWrong": {
     "A": "Storage Gateway é cache/file mode contínuo, não bulk migration.",
     "C": "Snowcone é appliance pequeno, online ou shipping — geralmente DataSync online é mais simples.",
     "D": "Transfer Family hospeda SFTP/FTPS/FTP no S3, mas você precisa do cliente push manualmente."
    },
    "keyConcept": "AWS DataSync — bulk file transfer online",
    "compareWith": [
     "DataSync (online) vs Snowball (offline)",
     "DataSync vs Storage Gateway"
    ],
    "realWorldContext": "Padrão para migrar NAS on-prem para S3/EFS antes de retirar storage local.",
    "commonMistakes": "Achar que DataSync funciona sem agent — para fontes on-prem precisa do agent (VM/HW).",
    "tutorSeeds": [
     "Como configurar throttle de bandwidth no DataSync?",
     "DataSync funciona S3 → S3 cross-region?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["datasync","migration","nfs","smb"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
