INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-055', 'aws-clf', 'Um parceiro empresarial envia arquivos diários por SFTP/FTPS/AS2 (EDI B2B) e a empresa quer receber em bucket S3 sem operar servidor FTP. Qual serviço atende?',
  '[{"id":"A","text":"AWS DataSync com endpoint SFTP"},{"id":"B","text":"Storage Gateway VTL"},{"id":"C","text":"AWS Transfer Family — endpoint gerenciado SFTP/FTPS/FTP/AS2 que entrega em S3 ou EFS"},{"id":"D","text":"Lambda + S3 PutObject manual"}]'::jsonb, 'C',
  '{
    "summary": "AWS Transfer Family hospeda endpoint SFTP/FTPS/FTP/AS2 managed entregando em S3/EFS.",
    "whyCorrect": "Transfer Family elimina o servidor FTP — você cria um endpoint gerenciado (custódia regional), define user identity providers (Service Managed, AD, IdP custom Lambda) e mapeia para bucket S3 ou EFS. Suporta SFTP, FTPS, FTP e AS2 (EDI).",
    "whyWrong": {
     "A": "DataSync não roda como servidor SFTP que recebe.",
     "B": "Storage Gateway VTL emula tape para backups.",
     "D": "Lambda + S3 manual exige você operar SFTP server."
    },
    "keyConcept": "AWS Transfer Family — SFTP/FTPS/FTP/AS2 managed",
    "compareWith": [
     "Transfer Family vs DataSync",
     "AS2 (B2B EDI) vs SFTP"
    ],
    "realWorldContext": "Padrão para EDI/B2B (varejistas, logística, healthcare) que ainda usam SFTP/AS2.",
    "commonMistakes": "Esquecer pricing — Transfer Family cobra por endpoint-hora (caro 24/7 mesmo sem uso).",
    "tutorSeeds": [
     "AS2 — para que serve?",
     "Quais identity providers Transfer Family suporta?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["transfer-family","sftp","as2","b2b"]'::jsonb, 'ai-draft', 'active', now(), now()
)
