INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-056', 'aws-clf', 'Uma equipe de analytics ingere clicks de website em real-time (milhões/seg) e precisa processar em janelas de segundos via código próprio (consumer). Os dados ficam retidos por 7 dias para reprocessamento. Qual serviço atende?',
  '[{"id":"A","text":"Amazon Kinesis Data Firehose"},{"id":"B","text":"Amazon SQS Standard"},{"id":"C","text":"Amazon SNS"},{"id":"D","text":"Amazon Kinesis Data Streams — shards, retenção 24h-365d, consumers customizados (KCL/Lambda/Flink)"}]'::jsonb, 'D',
  '{
    "summary": "Kinesis Data Streams é stream particionado em shards com retenção configurável e múltiplos consumers customizados.",
    "whyCorrect": "Data Streams é o serviço de streaming real-time da AWS — escala via shards (1 MB/s in, 2 MB/s out por shard), retenção 24h padrão até 365d, ordem garantida por partition key. Consumers usam KCL (Kinesis Client Library), Lambda, Flink ou EMR.",
    "whyWrong": {
     "A": "Firehose é managed delivery near-real-time (60s+) sem código consumer — não retém para reprocessamento; envia direto pra destino.",
     "B": "SQS é queue (point-to-point), não stream particionado.",
     "C": "SNS é pub-sub (push), sem retenção de stream."
    },
    "keyConcept": "Kinesis Data Streams — streaming real-time, shards, retenção configurável, consumers customizados",
    "compareWith": [
     "KDS vs Firehose",
     "KDS vs SQS vs SNS",
     "KDS vs MSK (Managed Kafka)"
    ],
    "realWorldContext": "Padrão para clickstream, IoT telemetry, logs em alta cardinalidade que precisam de processamento custom.",
    "commonMistakes": "Confundir KDS (você gerencia shards) com Firehose (delivery managed). Erro #1 em CLF.",
    "tutorSeeds": [
     "Qual a diferença entre KDS on-demand mode e provisioned?",
     "Quanto data um shard suporta?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["kinesis","kinesis-data-streams","streaming"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
