INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-057', 'aws-clf', 'Uma equipe quer entregar streams de eventos em S3 (data lake) e em OpenSearch (dashboard) com transformação leve (filtrar campos, decodificar) e SEM precisar escrever código consumer. Qual serviço atende?',
  '[{"id":"A","text":"Amazon Data Firehose (ex-Kinesis Data Firehose) — managed delivery near-real-time para S3/Redshift/OpenSearch/Splunk, com transformação Lambda inline"},{"id":"B","text":"Kinesis Data Streams + Lambda"},{"id":"C","text":"Amazon MSK"},{"id":"D","text":"Amazon EventBridge Pipes"}]'::jsonb, 'A',
  '{
    "summary": "Amazon Data Firehose é managed delivery near-real-time, com buffer time/size e transformação Lambda inline.",
    "whyCorrect": "Firehose recebe eventos (via API, KDS, MSK), buffera por tamanho/tempo (60s+ padrão), aplica Lambda transform opcional, e entrega para S3, Redshift, OpenSearch, Splunk, HTTP endpoints, parceiros (Datadog, New Relic). Zero código consumer e zero gestão de shards.",
    "whyWrong": {
     "B": "Funcionaria mas KDS + Lambda exige código consumer e gestão de shards.",
     "C": "MSK é Managed Kafka — exige consumers custom.",
     "D": "EventBridge Pipes é para conectar source → target com filtros, escala diferente."
    },
    "keyConcept": "Amazon Data Firehose — managed delivery near-real-time + transform inline",
    "compareWith": [
     "Firehose (managed delivery) vs KDS (streaming engine)",
     "Firehose Lambda transform vs Glue ETL"
    ],
    "realWorldContext": "Padrão para ingestion logs/metrics em S3 ou OpenSearch — zero código.",
    "commonMistakes": "Achar que Firehose é real-time — é NEAR-real-time (mínimo 60s de buffer).",
    "tutorSeeds": [
     "Qual o buffer mínimo do Firehose?",
     "Firehose suporta dynamic partitioning em S3?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["kinesis-firehose","data-firehose","streaming","delivery"]'::jsonb, 'ai-draft', 'active', now(), now()
)
