INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-058', 'aws-clf', 'Uma equipe de dados quer rodar SQL ad-hoc diretamente em arquivos Parquet armazenados em S3, sem provisionar nem manter cluster. Qual serviço atende?',
  '[{"id":"A","text":"Amazon Redshift"},{"id":"B","text":"Amazon Athena — interactive SQL serverless sobre S3 (Trino/Presto engine), paga por TB varrido"},{"id":"C","text":"AWS Glue ETL"},{"id":"D","text":"Amazon EMR Studio"}]'::jsonb, 'B',
  '{
    "summary": "Athena é SQL serverless sobre S3 — Trino/Presto sob o capô, pay-per-TB-scanned.",
    "whyCorrect": "Athena permite SQL ANSI direto sobre arquivos em S3 (CSV, JSON, Parquet, ORC). Usa Glue Data Catalog para schemas. Pricing: $5/TB de dados varridos (Parquet/ORC reduzem muito o custo). Sem cluster para manter.",
    "whyWrong": {
     "A": "Redshift exige cluster (mesmo Serverless tem warmup). Bom para DW estruturado/contínuo.",
     "C": "Glue ETL é transformação de dados, não SQL interativo.",
     "D": "EMR exige cluster Spark/Hadoop."
    },
    "keyConcept": "Amazon Athena — interactive SQL serverless sobre S3",
    "compareWith": [
     "Athena vs Redshift Spectrum",
     "Athena vs Glue Data Catalog"
    ],
    "realWorldContext": "Padrão para análise ad-hoc de logs, dados raw em data lake, BI ad-hoc.",
    "commonMistakes": "Achar que Athena é DW — não. É query engine sem armazenamento próprio; dados ficam em S3.",
    "tutorSeeds": [
     "Como Athena usa Glue Data Catalog?",
     "Por que Parquet reduz custo Athena?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["athena","sql","s3","data-lake"]'::jsonb, 'ai-draft', 'active', now(), now()
)
