INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-059', 'aws-clf', 'Uma equipe tem um Redshift cluster com tabelas hot. Eles querem consultar adicionalmente dados em S3 (cold data) sem importar para o cluster, juntando com tabelas Redshift via SQL. Qual serviço atende?',
  '[{"id":"A","text":"Athena com cross-source JOIN ao Redshift"},{"id":"B","text":"Glue Crawler com SQL output"},{"id":"C","text":"Amazon Redshift Spectrum — SQL Redshift sobre dados externos em S3, integra com tabelas Redshift"},{"id":"D","text":"Lake Formation Direct Query"}]'::jsonb, 'C',
  '{
    "summary": "Redshift Spectrum estende o cluster Redshift para consultar dados em S3 via external tables.",
    "whyCorrect": "Spectrum cria ''external schemas'' que apontam para Glue Data Catalog. Você roda SQL no cluster Redshift e ele paraleliza leitura do S3 nos Spectrum nodes (separados do cluster). Permite JOIN entre tabela Redshift (hot) e tabela em S3 (cold). Pricing: $5/TB varrido no S3.",
    "whyWrong": {
     "A": "Athena não joina nativamente com Redshift como tabela. Existe Federated Query mas direção oposta.",
     "B": "Glue Crawler só popula catálogo, não roda query.",
     "D": "Lake Formation governa acessos, não é engine de query."
    },
    "keyConcept": "Redshift Spectrum — query S3 a partir do Redshift",
    "compareWith": [
     "Spectrum vs Athena (Spectrum exige cluster Redshift, Athena não)",
     "Spectrum vs Federated Query"
    ],
    "realWorldContext": "Útil quando data warehouse tem hot/cold com a maior parte do volume em cold no S3.",
    "commonMistakes": "Confundir Spectrum (Redshift) com Athena (standalone). Spectrum precisa de cluster.",
    "tutorSeeds": [
     "Qual a diferença entre Spectrum e Athena na prática?",
     "Como criar external schema em Redshift?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["redshift","redshift-spectrum","data-lake"]'::jsonb, 'ai-draft', 'active', now(), now()
)
