INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-060', 'aws-clf', 'Uma empresa tem dezenas de buckets S3 com dados de várias áreas (RH, finanças, marketing). Quer governança centralizada: permissões fine-grained por tabela/coluna/linha, blueprints de ingestion, audit. Qual serviço atende?',
  '[{"id":"A","text":"AWS Glue Data Catalog sozinho"},{"id":"B","text":"AWS Config Compliance"},{"id":"C","text":"Amazon Macie"},{"id":"D","text":"AWS Lake Formation — camada de governança sobre Glue Data Catalog: permissões fine-grained, blueprints, tags"}]'::jsonb, 'D',
  '{
    "summary": "Lake Formation adiciona governança/permissões fine-grained sobre o Glue Data Catalog.",
    "whyCorrect": "Lake Formation funciona como camada de IAM para data lakes. Define permissions table/column/row-level que Athena/Redshift Spectrum/EMR respeitam. Provê LF-tags (tag-based access control), blueprints de ingestion (CDC databases → S3) e auditoria centralizada.",
    "whyWrong": {
     "A": "Glue Data Catalog tem metadata, mas permissions são IAM bucket-level — não column-level.",
     "B": "Config é compliance de configuração de recursos, não data governance.",
     "C": "Macie descobre PII/sensitive data em S3 — complementar mas não governance."
    },
    "keyConcept": "AWS Lake Formation — governança fine-grained sobre data lake",
    "compareWith": [
     "Lake Formation vs Glue Data Catalog (governance vs metadata)",
     "Lake Formation vs Macie"
    ],
    "realWorldContext": "Padrão em empresas grandes com data lake compartilhado entre áreas — quem vê o quê é decisão de governance.",
    "commonMistakes": "Achar que Lake Formation substitui o Glue — ele USA o Glue Data Catalog, não substitui.",
    "tutorSeeds": [
     "Como funciona LF-Tag-based access control?",
     "Lake Formation funciona com Redshift Spectrum?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["lake-formation","glue","governance","data-lake"]'::jsonb, 'ai-draft', 'active', now(), now()
)
