INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-061', 'aws-clf', 'Uma equipe quer ETL serverless: descobrir schemas em S3, transformar dados Spark sem provisionar cluster e gerar tabelas no catálogo. Qual serviço atende?',
  '[{"id":"A","text":"AWS Glue — ETL serverless Spark + Data Catalog + Crawlers + Studio + DataBrew"},{"id":"B","text":"Amazon EMR"},{"id":"C","text":"AWS Batch"},{"id":"D","text":"Amazon Athena CTAS"}]'::jsonb, 'A',
  '{
    "summary": "AWS Glue é ETL serverless completo com Catalog, Crawlers, Jobs Spark e UI low-code.",
    "whyCorrect": "Glue oferece: Crawlers (descobrem schemas e populam Data Catalog), Jobs (PySpark/Spark Scala serverless), Studio (UI visual de pipelines), DataBrew (low-code de data prep), Data Quality. Tudo serverless, paga por DPU-hora.",
