INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-062', 'aws-clf', 'Uma equipe big data já tem pipelines Spark/Hadoop com Hive, Presto, HBase complexos, exigindo cluster controlado e tunável. Qual serviço atende?',
  '[{"id":"A","text":"AWS Glue Jobs"},{"id":"B","text":"Amazon EMR — cluster managed para Spark/Hadoop/Hive/Presto/HBase/Flink, com EC2 ou EKS ou EMR Serverless"},{"id":"C","text":"Amazon Redshift"},{"id":"D","text":"AWS Batch"}]'::jsonb, 'B',
  '{
    "summary": "Amazon EMR é o serviço de big data clusters managed da AWS.",
    "whyCorrect": "EMR provê clusters pré-configurados com Hadoop ecosystem (Spark, Hive, HBase, Presto, Flink, Pig). Modos: EC2 (clusters tradicionais), EKS (sobre Kubernetes), Serverless (sem provisionar). Bom para workloads grandes com requisitos customizados.",
    "whyWrong": {
