INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-063', 'aws-clf', 'Uma equipe quer Apache Kafka gerenciado pela AWS (sem operar brokers, zookeeper/KRaft), mantendo compatibilidade total com clients Kafka existentes. Qual serviço atende?',
  '[{"id":"A","text":"Kinesis Data Streams (compatível Kafka)"},{"id":"B","text":"Amazon MQ for Kafka"},{"id":"C","text":"Amazon MSK (Managed Streaming for Apache Kafka) — Kafka original gerenciado; também MSK Serverless"},{"id":"D","text":"Amazon SNS"}]'::jsonb, 'C',
  '{
    "summary": "Amazon MSK é Apache Kafka managed — brokers, control plane, monitoring tudo gerenciado.",
    "whyCorrect": "MSK roda Apache Kafka real (não API-compatible, é o software original). AWS gerencia brokers (EC2 ou MSK Serverless), zookeeper/KRaft, patching, monitoramento. Clients Kafka existentes funcionam sem modificação.",
    "whyWrong": {
     "A": "Kinesis Data Streams NÃO é Kafka-compatible — APIs diferentes.",
     "B": "''Amazon MQ for Kafka'' não existe — Amazon MQ suporta ActiveMQ e RabbitMQ.",
     "D": "SNS é pub-sub, não streaming particionado."
    },
    "keyConcept": "Amazon MSK — Apache Kafka managed (vs Kinesis que é proprietário AWS)",
    "compareWith": [
     "MSK (Kafka real) vs Kinesis (AWS proprietário)",
     "MSK Provisioned vs MSK Serverless"
    ],
    "realWorldContext": "Escolha de empresas que vêm de Kafka on-prem e não querem refatorar clients.",
    "commonMistakes": "Achar que Kinesis é Kafka — não. Kinesis tem APIs próprias, Kafka clients não conectam.",
    "tutorSeeds": [
     "MSK Serverless vs Provisioned — diferenças?",
     "Como MSK integra com IAM?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["msk","kafka","streaming"]'::jsonb, 'ai-draft', 'active', now(), now()
)
