INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-064', 'aws-clf', 'Uma empresa precisa hospedar engine de busca para logs/full-text search, com dashboards Kibana-like, sem operar nodes ElasticSearch. Qual serviço atende?',
  '[{"id":"A","text":"Amazon CloudSearch"},{"id":"B","text":"Amazon Kendra"},{"id":"C","text":"Amazon Lex"},{"id":"D","text":"Amazon OpenSearch Service (ex-Elasticsearch Service) — managed OpenSearch/Elasticsearch + OpenSearch Dashboards"}]'::jsonb, 'D',
  '{
    "summary": "Amazon OpenSearch Service é OpenSearch/Elasticsearch managed, com dashboards integrados.",
    "whyCorrect": "OpenSearch Service (renomeado de Amazon Elasticsearch Service em 2021) é OpenSearch managed: cluster com data/master nodes, snapshots, security, integração com IAM, e OpenSearch Dashboards (fork do Kibana). Há também OpenSearch Serverless.",
    "whyWrong": {
     "A": "CloudSearch é serviço legacy menos popular.",
     "B": "Kendra é enterprise search com NLP, casos diferentes.",
     "C": "Lex é chatbot, não search."
    },
    "keyConcept": "Amazon OpenSearch Service — managed search/analytics engine",
    "compareWith": [
     "OpenSearch Service vs OpenSearch Serverless",
     "OpenSearch vs Kendra"
    ],
    "realWorldContext": "Padrão para log search, observability, full-text search em sites.",
    "commonMistakes": "Citar Elasticsearch Service — agora é OpenSearch Service (rename após fork da Elastic).",
    "tutorSeeds": [
     "Diferença entre OpenSearch Service e Serverless?",
     "OpenSearch vs Kendra — quando cada um?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["opensearch","elasticsearch","search"]'::jsonb, 'ai-draft', 'active', now(), now()
)
