INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-065', 'aws-clf', 'Uma analista quer dashboards BI compartilháveis a partir de Redshift/S3/Athena, com cache in-memory para acelerar visualizações. Qual serviço atende?',
  '[{"id":"A","text":"Amazon QuickSight — BI service AWS-native; SPICE é o engine in-memory que acelera dashboards"},{"id":"B","text":"AWS Glue Studio"},{"id":"C","text":"Amazon Athena Notebooks"},{"id":"D","text":"Amazon Managed Grafana"}]'::jsonb, 'A',
  '{
    "summary": "Amazon QuickSight é o BI da AWS; SPICE é o cache in-memory que acelera visualizações.",
    "whyCorrect": "QuickSight provê dashboards, análises ad-hoc, ML insights e embedding. SPICE (Super-fast, Parallel, In-memory Calculation Engine) cacheia dados em RAM para queries instantâneas. Pricing: Standard (autores $9/usuário) ou Enterprise (autores $18 + readers pay-per-session).",
    "whyWrong": {
     "B": "Glue Studio é UI para pipelines ETL, não BI.",
     "C": "Athena Notebooks é Jupyter para SQL/PySpark exploratório.",
     "D": "Managed Grafana é dashboards para observability (métricas/logs)."
    },
    "keyConcept": "Amazon QuickSight + SPICE — BI managed AWS",
    "compareWith": [
     "QuickSight vs Tableau/Power BI",
     "Standard vs Enterprise edition"
    ],
    "realWorldContext": "Boa fit para empresas já AWS-native que querem BI sem licenças adicionais.",
    "commonMistakes": "Achar que SPICE é storage primário — não. É cache, dados originais ficam em Redshift/S3/RDS.",
    "tutorSeeds": [
     "Standard vs Enterprise QuickSight?",
     "Como configurar refresh do SPICE?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["quicksight","bi","spice"]'::jsonb, 'ai-draft', 'active', now(), now()
)
