INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-066', 'aws-clf', 'Uma equipe de ML quer treinar e implantar modelos custom com control sobre código, frameworks (PyTorch/TF) e endpoints inference. Qual serviço atende?',
  '[{"id":"A","text":"Amazon Comprehend"},{"id":"B","text":"Amazon SageMaker — plataforma ML end-to-end: Studio, Training, Inference endpoints, Ground Truth, Canvas"},{"id":"C","text":"Amazon Rekognition"},{"id":"D","text":"Amazon Bedrock"}]'::jsonb, 'B',
  '{
    "summary": "Amazon SageMaker é a plataforma ML AWS — treinamento, inferência, governança e MLOps.",
    "whyCorrect": "SageMaker oferece IDE (Studio), notebooks managed, training jobs (CPU/GPU), hyperparameter tuning, model registry, endpoints de inference (real-time, serverless, batch, async), Ground Truth (labeling), Canvas (no-code ML), Feature Store, Pipelines, Model Monitor. Suporta TF/PyTorch/XGBoost/Hugging Face.",
    "whyWrong": {
     "A": "Comprehend é serviço NLP pronto (sentiment, entities), não plataforma de custom training.",
     "C": "Rekognition é serviço vision pronto.",
     "D": "Bedrock é serving de foundation models prontos."
    },
    "keyConcept": "Amazon SageMaker — plataforma ML para treinamento e inferência custom",
    "compareWith": [
     "SageMaker (custom) vs Comprehend/Rekognition (pronto)",
     "SageMaker vs Bedrock (FM)"
    ],
    "realWorldContext": "Default para equipes de ML que treinam modelos próprios.",
    "commonMistakes": "Subestimar gama: SageMaker tem 20+ subprodutos. Não é só notebooks.",
    "tutorSeeds": [
     "O que é SageMaker Canvas?",
     "Real-time endpoint vs serverless endpoint vs batch?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["sagemaker","ml","training"]'::jsonb, 'ai-draft', 'active', now(), now()
)
