INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-067', 'aws-clf', 'Uma empresa quer integrar foundation models (Claude, Llama, Mistral, Titan, Cohere) via API gerenciada, sem treinar nem hospedar GPU. Qual serviço atende?',
  '[{"id":"A","text":"Amazon SageMaker JumpStart"},{"id":"B","text":"Amazon Lex"},{"id":"C","text":"Amazon Bedrock — API gerenciada para foundation models de Anthropic, Meta, Mistral, AI21, Cohere, Amazon Titan, Stability AI"},{"id":"D","text":"Amazon Q"}]'::jsonb, 'C',
  '{
    "summary": "Amazon Bedrock é o catálogo managed de Foundation Models multi-vendor da AWS.",
    "whyCorrect": "Bedrock provê API uniforme (InvokeModel/Converse) para FMs de Anthropic (Claude), Meta (Llama), Mistral, AI21, Cohere, Amazon (Titan, Nova), Stability AI. Recursos extras: Knowledge Bases (RAG), Agents, Guardrails, Model evaluation. Pricing por token (input/output) ou Provisioned throughput.",
    "whyWrong": {
     "A": "SageMaker JumpStart hospeda modelos open-source mas exige você gerenciar endpoint.",
     "B": "Lex é chatbot framework, não FMs raw.",
     "D": "Amazon Q é assistente conversacional para uso interno (não API de modelos)."
    },
    "keyConcept": "Amazon Bedrock — managed foundation models multi-vendor",
    "compareWith": [
     "Bedrock (managed FM API) vs SageMaker (DIY model hosting)",
     "Bedrock vs Amazon Q"
    ],
    "realWorldContext": "Acesso a Claude/Llama sem deal-com-Anthropic-direto. Default em pipelines GenAI corporativos.",
    "commonMistakes": "Achar que Bedrock treina seu modelo do zero — não. Ele serve FMs pré-treinados; suporta fine-tuning leve.",
    "tutorSeeds": [
     "Como funciona Knowledge Bases for Bedrock?",
     "Quais modelos Bedrock atualmente serve?"
    ]
   }'::jsonb,
