INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-068', 'aws-clf', 'Uma empresa quer adicionar OCR (extrair texto de fatura escaneada, NF-e PDF, formulários) com extração estruturada de tabelas e key-value pairs. Qual serviço AWS atende?',
  '[{"id":"A","text":"Amazon Rekognition"},{"id":"B","text":"Amazon Comprehend"},{"id":"C","text":"Amazon Polly"},{"id":"D","text":"Amazon Textract — OCR avançado com extração de tabelas, formulários e key-value pairs"}]'::jsonb, 'D',
  '{
    "summary": "Amazon Textract é OCR AWS com awareness estrutural — tabelas, forms, key-value pairs.",
    "whyCorrect": "Textract não só extrai texto bruto (como OCR tradicional) — entende layout: identifica tabelas com linhas/colunas, formulários com chave-valor, queries (perguntas em natural language sobre o documento). Suporta sync e async (large PDFs).",
    "whyWrong": {
     "A": "Rekognition é vision — objetos, faces, moderação. Não estrutura texto.",
     "B": "Comprehend é NLP em texto já extraído.",
     "C": "Polly é text-to-speech."
    },
    "keyConcept": "Amazon Textract — OCR com estrutura (tabelas, forms)",
    "compareWith": [
     "Textract vs Rekognition Text",
     "Textract Tables vs Forms vs Queries"
    ],
    "realWorldContext": "Padrão para automação de documentos (faturas, contratos, exames médicos).",
    "commonMistakes": "Confundir com Rekognition — Rekognition vê ''texto detectado'' em imagem; Textract entende layout de documento.",
    "tutorSeeds": [
     "Como Textract Queries funciona?",
     "Qual a diferença entre Textract sync e async?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["textract","ocr","documents"]'::jsonb, 'ai-draft', 'active', now(), now()
)
