INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-069', 'aws-clf', 'Uma manufatureira quer ingerir telemetria de 100k sensores industriais via MQTT, processar em edge gateways, e armazenar/analisar em cloud. Quais serviços atendem?',
  '[{"id":"A","text":"AWS IoT Core (MQTT broker managed) + AWS IoT Greengrass (edge runtime nos gateways) + IoT Analytics ou Timestream para storage/análise"},{"id":"B","text":"Amazon API Gateway + Lambda + DynamoDB"},{"id":"C","text":"Amazon SQS + EC2"},{"id":"D","text":"Apenas Kinesis Data Streams"}]'::jsonb, 'A',
  '{
    "summary": "IoT Core (broker MQTT) + Greengrass (edge) + IoT Analytics/Timestream (storage) é a stack IoT AWS.",
    "whyCorrect": "IoT Core é broker MQTT managed com device registry, X.509 auth, rules engine. Greengrass roda containers/Lambda em gateways edge (Linux/Windows). IoT Analytics oferece pipelines analíticos para dados de sensores; Timestream é DB time-series.",
    "whyWrong": {
     "B": "API Gateway + Lambda não suporta MQTT nativo.",
     "C": "SQS+EC2 não é solução IoT — falta MQTT, device management.",
     "D": "Kinesis é stream mas não substitui broker MQTT + device registry."
    },
    "keyConcept": "AWS IoT stack — Core (broker) + Greengrass (edge) + Analytics/Timestream",
    "compareWith": [
     "IoT Core vs MSK/Kafka",
     "Greengrass v1 vs v2"
    ],
    "realWorldContext": "Padrão em manufatura 4.0, smart cities, agritech.",
    "commonMistakes": "Confundir IoT Core (broker cloud) com Greengrass (runtime edge). São complementares.",
    "tutorSeeds": [
     "Como Greengrass orquestra Lambda no edge?",
     "Quais protocolos IoT Core aceita além de MQTT?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["iot-core","greengrass","edge","mqtt"]'::jsonb, 'ai-draft', 'active', now(), now()
)
