INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-070', 'aws-clf', 'Uma empresa de streaming quer transcodificar vídeo (4K → ABR), entregar via HLS/DASH com inserção de anúncios server-side. Quais serviços AWS Elemental atendem?',
  '[{"id":"A","text":"Apenas CloudFront"},{"id":"B","text":"AWS Elemental MediaConvert (transcoding VOD) + MediaPackage (origin packaging HLS/DASH) + MediaTailor (SSAI ads) — entregues via CloudFront"},{"id":"C","text":"MediaLive sozinho"},{"id":"D","text":"Kinesis Video Streams"}]'::jsonb, 'B',
  '{
    "summary": "Stack AWS Elemental: MediaConvert (VOD transcoding), MediaLive (live), MediaPackage (packaging), MediaTailor (ads).",
    "whyCorrect": "MediaConvert: transcoding de arquivos (VOD) para múltiplas resoluções/codecs. MediaLive: ingest e encoding ao vivo. MediaPackage: origin server que empacota em HLS/DASH/CMAF/MSS. MediaTailor: server-side ad insertion (SSAI) personalizada. CloudFront distribui ao usuário final.",
    "whyWrong": {
     "A": "CloudFront entrega mas não transcoda.",
     "C": "MediaLive é só live, não cobre VOD nem packaging/ads.",
     "D": "KVS é para ingest de stream de câmeras IoT, não para distribuição."
    },
    "keyConcept": "AWS Elemental media services — convert/live/package/tailor",
    "compareWith": [
     "MediaConvert (VOD) vs MediaLive (live)",
     "MediaPackage vs MediaTailor"
    ],
    "realWorldContext": "Stack usada por OTT players (DAZN, FuboTV, etc.).",
    "commonMistakes": "Citar MediaLive para VOD — é só live. VOD = MediaConvert.",
    "tutorSeeds": [
     "Como funciona SSAI vs CSAI?",
     "AWS IVS — quando preferir sobre MediaLive?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["elemental","media-convert","media-package","media-tailor"]'::jsonb, 'ai-draft', 'active', now(), now()
)
