INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-071', 'aws-clf', 'Uma equipe migra workloads e quer dashboard central para acompanhar status de cada wave de migração (servidores em discovery, replicating, cutover, decommissioned). Qual serviço atende?',
  '[{"id":"A","text":"AWS Control Tower"},{"id":"B","text":"AWS Systems Manager OpsCenter"},{"id":"C","text":"AWS Migration Hub — dashboard central de tracking entre ADS, MGN, DMS, Resilience Hub"},{"id":"D","text":"AWS Trusted Advisor"}]'::jsonb, 'C',
