INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-072', 'aws-clf', 'Para apps que rodam em containers e precisam de descoberta de serviços (service discovery) entre tasks ECS sem usar load balancer entre todos, qual feature ECS atende?',
  '[{"id":"A","text":"Apenas IAM"},{"id":"B","text":"ALB para cada task"},{"id":"C","text":"DynamoDB com endereços"},{"id":"D","text":"Service Connect / Service Discovery — DNS A records (via Cloud Map) ou injeção de proxy Envoy entre tasks ECS"}]'::jsonb, 'D',
  '{
    "summary": "ECS Service Connect (Envoy) e Service Discovery (Cloud Map DNS) provêem descoberta entre tasks.",
    "whyCorrect": "ECS oferece dois mecanismos: Service Discovery via Cloud Map (registra DNS A records para cada task), e Service Connect (Envoy sidecar com observabilidade, retries, mesh-like). Permite microservices se chamarem por hostname lógico.",
    "whyWrong": {
     "A": "IAM é authn/authz, não descoberta.",
     "B": "ALB para cada task é caro e contraproducente.",
     "C": "DynamoDB com endpoints manuais é antipattern (reinventa Cloud Map)."
    },
    "keyConcept": "ECS Service Connect / Service Discovery — descoberta nativa entre tasks",
    "compareWith": [
     "Service Connect (Envoy) vs Service Discovery (Cloud Map DNS)",
     "Cloud Map vs Route 53 private"
    ],
    "realWorldContext": "Padrão moderno em microservices ECS — substitui o pattern antigo de ALB-entre-todos.",
    "commonMistakes": "Achar que Service Discovery dispensa Cloud Map — é Cloud Map por baixo.",
    "tutorSeeds": [
     "Service Connect vs Service Discovery — quando cada um?",
     "Cloud Map suporta HTTP namespace?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["ecs","service-connect","service-discovery","cloud-map"]'::jsonb, 'ai-draft', 'active', now(), now()
)
