INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-073', 'aws-clf', 'Uma equipe de jogos quer dedicar servidores multiplayer com scaling, fleet management e matchmaking. Qual serviço AWS atende?',
  '[{"id":"A","text":"Amazon GameLift — managed fleets para servidores de jogo dedicados (FlexMatch matchmaking, fleet auto-scaling)"},{"id":"B","text":"Amazon EC2 manual"},{"id":"C","text":"AWS Lambda"},{"id":"D","text":"Amazon Lightsail"}]'::jsonb, 'A',
  '{
    "summary": "Amazon GameLift hospeda servidores multiplayer dedicados com matchmaking.",
    "whyCorrect": "GameLift provê fleets de game servers (EC2 com seu binário), scaling automático, FlexMatch para matchmaking de jogadores, Sessions e Queues. Tem GameLift Anywhere para hardware on-prem.",
    "whyWrong": {
     "B": "EC2 manual exige você operar tudo (sessões, matchmaking).",
     "C": "Lambda não é fit para sessões de jogo persistentes.",
     "D": "Lightsail é VPS simples."
