INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-074', 'aws-clf', 'Uma corporação configurou CloudWatch alarms mas tem ''alert fatigue'' — recebe centenas de notificações falsas. Quer combinar múltiplos alarms (CPU alto E latência alta) num único alerta. Qual recurso atende?',
  '[{"id":"A","text":"CloudWatch Anomaly Detection"},{"id":"B","text":"CloudWatch Composite Alarms — combina N alarms via expressão booleana (AND/OR/NOT)"},{"id":"C","text":"CloudWatch Synthetics"},{"id":"D","text":"CloudTrail Insights"}]'::jsonb, 'B',
  '{
    "summary": "Composite Alarms combinam múltiplos alarms via expressões booleanas — reduzem ruído.",
    "whyCorrect": "Composite Alarms permitem expressões como `ALARM(alarm1) AND ALARM(alarm2)` — só disparam quando a condição composta é satisfeita. Reduzem alert fatigue: alerta só se CPU alta E erros 5xx altos simultaneamente.",
    "whyWrong": {
     "A": "Anomaly Detection é outro tipo de alarm (threshold dinâmico), não composição.",
     "C": "Synthetics roda canaries.",
     "D": "CloudTrail Insights detecta atividade anômala em API calls."
    },
    "keyConcept": "CloudWatch Composite Alarms — combinação booleana de alarms",
    "compareWith": [
     "Composite vs Simple alarms",
     "Anomaly Detection thresholds"
    ],
    "realWorldContext": "Best practice moderna em SRE: composite alarms aninhados reduzem 90% do alert noise.",
    "commonMistakes": "Achar que composite alarm dispara ação em cada alarm filho — só dispara quando a expressão composta é verdadeira.",
    "tutorSeeds": [
     "Como nest composite alarms?",
     "Anomaly Detection — quando usar?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["cloudwatch","composite-alarms","alerting"]'::jsonb, 'ai-draft', 'active', now(), now()
)
