INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-075', 'aws-clf', 'Um arquiteto quer rotear usuários para um endpoint baseado em BIDDING — pesos podem mudar (90/10 inicialmente, depois 50/50 após teste A/B). Qual routing policy Route 53 atende?',
  '[{"id":"A","text":"Latency-based routing"},{"id":"B","text":"Multi-value routing"},{"id":"C","text":"Weighted routing — pesos numéricos por record que controlam % de tráfego"},{"id":"D","text":"Geolocation routing"}]'::jsonb, 'C',
  '{
    "summary": "Weighted routing distribui tráfego por % via pesos numéricos configuráveis.",
    "whyCorrect": "Weighted routing assigns pesos (0-255) a múltiplos records do mesmo nome. R53 calcula % de queries por peso (ex: 90/10 envia ~90% ao primeiro). Ideal para canary deployments, A/B testing, blue/green.",
    "whyWrong": {
     "A": "Latency-based escolhe por latência medida, não por peso.",
     "B": "Multi-value retorna até 8 records simultâneos para client-side LB.",
     "D": "Geolocation é por país/continente."
    },
    "keyConcept": "Route 53 Weighted routing — % de tráfego por peso",
    "compareWith": [
     "Weighted (peso) vs Latency (latência) vs Geo (país)",
     "Canary deployment via weighted"
    ],
    "realWorldContext": "Padrão para canary release/A-B testing em nível DNS.",
    "commonMistakes": "Esperar precisão exata 90/10 — DNS tem cache TTL, distribuição é estatística.",
    "tutorSeeds": [
     "Como TTL afeta weighted routing?",
     "Pesos somam 100?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["route-53","weighted-routing","canary"]'::jsonb, 'ai-draft', 'active', now(), now()
)
