INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-076', 'aws-clf', 'Uma equipe configurou ECS task que precisa acessar S3, mas as tasks recebem erro ''AccessDenied''. O IAM role da instância EC2 tem permissão a S3. Por que pode estar falhando?',
  '[{"id":"A","text":"Tasks ECS herdam automaticamente role da instância — deve ser problema de bucket policy"},{"id":"B","text":"S3 não suporta IAM role em ECS"},{"id":"C","text":"Task precisa de IAM user com access keys"},{"id":"D","text":"Tasks devem ter Task Role IAM (taskRoleArn) específica; o role do instance profile não vale para a task em Fargate ou em containerd com agent moderno"}]'::jsonb, 'D',
  '{
    "summary": "ECS tasks usam TASK ROLE (definida na task definition), não a role da instância EC2.",
    "whyCorrect": "Cada task definition pode (e deve) ter `taskRoleArn` apontando para uma IAM role específica do app. AWS recomenda least privilege por task. O `executionRoleArn` (diferente) é só para o ECS Agent puxar imagem, escrever logs, etc. — não dá acesso à app.",
    "whyWrong": {
     "A": "EC2 instance role NÃO é herdado pelo container — é antipattern de segurança.",
     "B": "Falso — S3 suporta perfeitamente IAM role em ECS.",
     "C": "Access keys em container é antipattern (rotação, leak)."
    },
    "keyConcept": "ECS Task Role vs Execution Role — Task Role é a permissão do app",
    "compareWith": [
     "Task Role (app) vs Execution Role (ECS Agent)",
     "Task Role vs EC2 instance profile"
    ],
    "realWorldContext": "Erro frequente em primeiro deploy de containers. Solução: criar IAM role + anexar como `taskRoleArn`.",
    "commonMistakes": "Confundir Task Role com Execution Role. Execution Role serve para AWS pull-image/logs; Task Role é o que o seu app usa.",
    "tutorSeeds": [
     "Qual a diferença exata entre taskRoleArn e executionRoleArn?",
     "Como debug ''AccessDenied'' em ECS task?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'troubleshoot', '["ecs","iam","task-role","permissions"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
