INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-077', 'aws-clf', 'Um usuário relata erros 502 esporádicos em aplicação atrás de CloudFront. A latência aumenta nas regiões longe do origin. Onde focar primeiro o troubleshooting?',
  '[{"id":"A","text":"Verificar logs do CloudFront (RTL/standard logs) e origin response codes; 502 frequentemente é origin timeout — aumentar Origin Response Timeout e revisar saúde do origin"},{"id":"B","text":"Aumentar TTL do cache"},{"id":"C","text":"Trocar para Global Accelerator"},{"id":"D","text":"Aumentar TTL do DNS"}]'::jsonb, 'A',
  '{
    "summary": "502 em CloudFront geralmente origina-se do origin — origin timeout, TLS handshake, response inválido.",
    "whyCorrect": "CloudFront retorna 502 quando o origin responde inválido (TLS error, conexão fechada, response não-HTTP). Real-Time Logs e Standard Logs no CloudFront mostram x-edge-result-type. Investigar: status do origin (ALB/EC2), origin response timeout (padrão 30s, pode estender até 60s), TLS protocols suportados, network ACLs.",
    "whyWrong": {
     "B": "TTL cache não resolve 502 (que ocorre no caminho ao origin, não no cache).",
     "C": "Trocar serviço não diagnostica o problema.",
     "D": "DNS TTL não afeta 502 do CloudFront."
    },
    "keyConcept": "CloudFront 502/504 — falhas no origin path; debug via CF logs e origin health",
    "compareWith": [
     "502 (bad gateway) vs 504 (gateway timeout) vs 503"
    ],
    "realWorldContext": "Cenário comum. CloudFront é raramente o culpado — geralmente origin (ALB, EC2, Lambda) saturado.",
    "commonMistakes": "Culpar ''CloudFront problemático'' sem ler os logs. CF é robusto; 502 é sintoma de origin issue.",
    "tutorSeeds": [
     "Como ler x-edge-result-type em CloudFront logs?",
     "Como ajustar Origin Response Timeout?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'troubleshoot', '["cloudfront","troubleshooting","502","origin"]'::jsonb, 'ai-draft', 'active', now(), now()
)
ON CONFLICT (id) DO UPDATE SET
