INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-078', 'aws-clf', 'Uma equipe configurou Transit Gateway com 5 VPCs anexadas, mas VPC-A não consegue alcançar VPC-B mesmo com peering attachments. Onde investigar?',
  '[{"id":"A","text":"Recriar o TGW"},{"id":"B","text":"Verificar TGW Route Tables: associations (qual TGW RT cada attachment usa) e propagations (rotas propagadas); e também as VPC route tables apontando para o TGW"},{"id":"C","text":"Aumentar MTU do TGW"},{"id":"D","text":"Trocar para Cloud WAN"}]'::jsonb, 'B',
  '{
    "summary": "Tráfego em TGW depende de Route Tables do TGW (associations + propagations) + Route Tables das VPCs.",
    "whyCorrect": "TGW tem suas próprias route tables internas. Cada attachment é ASSOCIADO a uma TGW RT (qual RT consulta) e suas rotas podem ser PROPAGADAS para outras TGW RTs. Além disso, a route table de subnet da VPC precisa rota → TGW para o CIDR remoto. Falta de qualquer uma quebra o tráfego.",
    "whyWrong": {
     "A": "Recriar é overreaction sem diagnóstico.",
     "C": "MTU em TGW é fixo (8500 bytes em Jumbo).",
     "D": "Trocar tecnologia não diagnostica problema."
    },
    "keyConcept": "TGW Route Tables — Associations (qual RT consulta) + Propagations (qual RT recebe rotas)",
    "compareWith": [
     "TGW RT Association vs Propagation",
     "TGW RT vs VPC RT"
    ],
    "realWorldContext": "Causa #1 de TGW não rotear: faltar route na VPC route table ou attachment associado a RT errada.",
    "commonMistakes": "Achar que basta criar attachment — sem associations/propagations corretas, o tráfego não passa.",
    "tutorSeeds": [
     "Como funciona TGW Association vs Propagation?",
     "Quantas route tables um TGW pode ter?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'troubleshoot', '["transit-gateway","troubleshooting","routing"]'::jsonb, 'ai-draft', 'active', now(), now()
)
