INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-079', 'aws-clf', 'Uma startup quer melhorar app web global existente — usuários no Brasil reclamam de lentidão mas o origin está em us-east-1. Eles querem solução simples, com cache HTTP. Qual a melhor recomendação inicial?',
  '[{"id":"A","text":"Replicar todo o stack para sa-east-1 com Route 53 latency routing"},{"id":"B","text":"Trocar Application Load Balancer por Network Load Balancer"},{"id":"C","text":"Colocar Amazon CloudFront na frente — cache HTTP global nos PoPs perto dos usuários, sem mudar origin"},{"id":"D","text":"Habilitar Auto Scaling agressivo"}]'::jsonb, 'C',
  '{
    "summary": "CloudFront é a solução de menor esforço para reduzir latência global em apps HTTP — cache na edge.",
    "whyCorrect": "Adicionar CloudFront na frente do origin existente cacheia conteúdo estático (e até dinâmico via cache policies) em PoPs próximos do Brasil. Reduz latência sem refatorar nem replicar infra. Setup leva horas; benefício imediato.",
    "whyWrong": {
     "A": "Replicar stack é caro e demorado; CloudFront resolve a maior parte do problema com fração do esforço.",
     "B": "NLB é L4 — não muda nada para usuário web tradicional.",
     "D": "Auto Scaling não resolve latência geográfica."
    },
    "keyConcept": "CloudFront como pre-cache HTTP global — quick win para apps internacionais",
    "compareWith": [
     "CloudFront (caching) vs Multi-region replication (heavyweight)"
    ],
    "realWorldContext": "Sempre comece com CloudFront antes de pensar em multi-region.",
    "commonMistakes": "Pular CloudFront e ir direto para multi-region — overkill e caro.",
    "tutorSeeds": [
     "Quando multi-region é realmente necessário sobre CloudFront?",
     "Como configurar cache policies para conteúdo dinâmico?"
    ]
   }'::jsonb,
  'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["cloudfront","cdn","latency","best-practice"]'::jsonb, 'ai-draft', 'active', now(), now()
)
