INSERT INTO questions (id, simulado_id, stem, options, correct_id, explanation, topic, domain, difficulty, scenario_type, tags, source, status, created_at, updated_at) VALUES (
  'clf-c02-tech-v4-080', 'aws-clf', 'Para garantir continuidade do negócio quando recursos do Route 53 são impactados, a AWS oferece um serviço dedicado a failover regional altamente confiável, independente do plano de controle DNS comum. Qual é?',
  '[{"id":"A","text":"Route 53 Resolver"},{"id":"B","text":"AWS Backup"},{"id":"C","text":"AWS Resilience Hub"},{"id":"D","text":"Route 53 Application Recovery Controller (ARC) — failover regional altamente confiável com data plane isolado em 5 regiões"}]'::jsonb, 'D',
  '{
    "summary": "Route 53 ARC é o serviço de orquestração de failover regional com data plane resiliente.",
    "whyCorrect": "ARC tem dois recursos: Readiness Check (audita prontidão de réplicas regionais) e Routing Control (toggle de saúde controlando Route 53 health checks via 5 cluster endpoints altamente redundantes — mesmo em outage do plano de controle do R53). Crítico para apps multi-region.",
    "whyWrong": {
     "A": "Route 53 Resolver é DNS resolver entre VPC e on-prem.",
     "B": "AWS Backup é gestão de backups.",
     "C": "Resilience Hub avalia resiliência da arquitetura."
    },
    "keyConcept": "Route 53 Application Recovery Controller — orquestração resiliente de failover regional",
    "compareWith": [
     "ARC Routing Controls vs Health Checks tradicionais",
     "ARC vs Resilience Hub"
    ],
    "realWorldContext": "Usado por bancos e empresas com SLAs duros para multi-region failover.",
    "commonMistakes": "Confundir com health checks tradicionais — ARC usa cluster específico de 5 regiões para resilience extra.",
    "tutorSeeds": [
     "Como funciona o cluster ARC de 5 regiões?",
     "ARC Readiness Check — para que serve?"
    ]
